styles:
* { margin:0; padding:0; box-sizing:border-box; -webkit-tap-highlight-color:transparent; }
html,body { width:100%; height:100%; overflow:hidden; background:#140806;
  font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif; touch-action:none;
  user-select:none; -webkit-user-select:none; }
#game { position:fixed; inset:0; display:block; }
.ov { position:fixed; inset:0; display:flex; flex-direction:column; align-items:center;
  justify-content:flex-start; z-index:10; pointer-events:none; text-align:center;
  overflow-y:auto; -webkit-overflow-scrolling:touch; padding:4vh 0; }
.ov .panel { pointer-events:auto; background:linear-gradient(165deg,rgba(42,19,8,.88),rgba(10,4,2,.92) 55%,rgba(26,10,4,.90));
  border:2px solid rgba(255,140,46,.55); backdrop-filter:blur(10px); -webkit-backdrop-filter:blur(10px);
  border-radius:18px; padding:26px 34px; max-width:88vw; margin:auto;
  max-height:92vh; overflow-y:auto; -webkit-overflow-scrolling:touch;
  box-shadow:0 24px 60px rgba(0,0,0,.55), 0 0 60px rgba(255,90,20,.28), inset 0 1px 0 rgba(255,220,160,.20), inset 0 0 40px rgba(255,90,20,.06);
  animation:panelIn .45s cubic-bezier(.2,.9,.25,1.15); }
@keyframes panelIn { from{opacity:0; transform:translateY(14px) scale(.96)} to{opacity:1; transform:none} }
h1.logo { font-size:min(15vw,84px); font-weight:900; letter-spacing:2px; line-height:1;
  background:linear-gradient(180deg,#fff7c0 5%,#ffd76a 30%,#ff8c2e 62%,#e8352c 100%);
  background-size:100% 180%; animation:logoSheen 5s ease-in-out infinite;
  -webkit-background-clip:text; background-clip:text; color:transparent;
  filter:drop-shadow(0 4px 18px rgba(255,110,20,.55)); }
@keyframes logoSheen { 0%,100%{background-position:50% 0%} 50%{background-position:50% 100%} }
.sub { color:#ffb347; font-weight:700; letter-spacing:3px; font-size:13px; margin-top:10px; }
.tag { color:#c98a5a; font-size:12px; margin-top:8px; letter-spacing:1px; }
.bigbtn { pointer-events:auto; margin-top:22px; background:linear-gradient(180deg,#ffb03a 0%,#ff7a2e 45%,#e8352c 100%);
  color:#fff; border:none; border-radius:999px; font-size:20px; font-weight:900; letter-spacing:2px;
  padding:16px 52px; cursor:pointer; box-shadow:0 6px 30px rgba(255,80,20,.5), inset 0 1px 0 rgba(255,255,255,.45), inset 0 -8px 16px rgba(120,10,0,.30);
  animation:pulse 1.6s infinite; transition:transform .08s, filter .15s; }
.bigbtn:hover { filter:brightness(1.08); }
.bigbtn:active { transform:scale(.94); }
/* TAP TO START rebuild: big touch target, instant tap response, no double-tap zoom */
#startbtn{ touch-action:manipulation; -webkit-tap-highlight-color:transparent;
  min-height:64px; min-width:min(78vw,320px);
  /* phone one-line fix (final pass): keep "TAP TO START 🔥" on one line inside the pill —
     nowrap + inline-flex centering, with font/padding shrinking via the page's min()/vw
     pattern so desktop (20px / 52px sides) is unchanged */
  white-space:nowrap; display:inline-flex; align-items:center; justify-content:center;
  font-size:min(20px,4.8vw); padding-left:min(52px,6vw); padding-right:min(52px,6vw); }
#startbtn.tapped{ transform:scale(.92); filter:brightness(1.18); }
.clabel { color:#ffb347; font-weight:800; letter-spacing:3px; font-size:12px; margin:16px 0 8px; }
#pname { font:800 18px system-ui; padding:12px 16px; border-radius:12px; border:2px solid rgba(255,150,60,.5);
  background:rgba(10,4,2,.8); color:#ffe9d6; text-align:center; width:min(64vw,280px); letter-spacing:1px; }
#pcswatches { display:flex; gap:10px; justify-content:center; margin:4px 0; flex-wrap:wrap; }
.pcsw { width:44px; height:44px; border-radius:50%; cursor:pointer; border:3px solid transparent; pointer-events:auto; }
.pcsw.sel { border-color:#fff; box-shadow:0 0 12px rgba(255,255,255,.65); }
.bigbtn:disabled { filter:grayscale(.8) brightness(.6); animation:none; cursor:default; }
@keyframes pulse { 0%,100%{transform:scale(1)} 50%{transform:scale(1.05)} }
#topbar { position:fixed; top:0; left:0; right:0; z-index:9; display:none;
  justify-content:space-between; align-items:center; padding:10px 14px; pointer-events:none; }
#topbar .pill { background:linear-gradient(180deg,rgba(32,15,6,.78),rgba(10,4,2,.80)); border:1px solid rgba(255,140,46,.4); color:#ffd76a;
  border-radius:999px; padding:6px 14px; font-size:13px; font-weight:800; letter-spacing:1px;
  box-shadow:0 3px 10px rgba(0,0,0,.40), inset 0 1px 0 rgba(255,220,160,.18); backdrop-filter:blur(6px); -webkit-backdrop-filter:blur(6px); }
#fps { color:#7dff9a; }
#foepill { display:none; }
#objbanner { position:fixed; top:84px; left:50%; transform:translateX(-50%); z-index:9; display:none; text-align:center;
  pointer-events:none; color:#ffd76a; font:800 13px system-ui; letter-spacing:2px;
  text-shadow:0 2px 8px #000; padding:6px 16px; max-width:calc(100vw - 140px);
  background:rgba(10,4,2,.65); border-radius:12px; border:1px solid rgba(255,140,46,.35);
  white-space:normal; }
#joy { position:fixed; left:22px; bottom:26px; width:124px; height:124px; border-radius:50%;
  z-index:9; background:rgba(20,10,6,.35); border:2px solid rgba(255,150,60,.45);
  display:none; pointer-events:auto; touch-action:none; }
#knob { position:absolute; left:50%; top:50%; width:56px; height:56px; border-radius:50%;
  background:radial-gradient(circle at 35% 30%,#ffd76a,#ff7a2e 70%);
  transform:translate(-50%,-50%); box-shadow:0 0 18px rgba(255,140,40,.7); pointer-events:none; }
/* multiplayer combat buttons: attack / block / jump (bottom-right, MP only) */
#mpcombat { position:fixed; right:8px; left:8px; bottom:12px; z-index:10; display:none;
  gap:8px; align-items:flex-end; justify-content:flex-end; flex-wrap:nowrap; overflow-x:auto;
  padding:4px 2px; -webkit-overflow-scrolling:touch; }
#mpcombat.on { display:flex; }
.mpcbtn { width:60px; height:60px; min-width:60px; border-radius:50%; font-size:26px; line-height:1;
  border:3px solid rgba(255,255,255,.4); cursor:pointer; touch-action:manipulation;
  -webkit-tap-highlight-color:transparent; user-select:none; -webkit-user-select:none;
  box-shadow:0 4px 0 rgba(0,0,0,.35), 0 0 18px rgba(255,150,60,.35);
  transition:transform .07s; font-family:inherit; }
.mpcbtn:active { transform:scale(.9); }
#mpatkbtn { background:radial-gradient(circle at 35% 30%,#ffd76a,#ff5a2e 70%); }
#mpblkbtn { background:radial-gradient(circle at 35% 30%,#bfe6ff,#2e7adf 70%); }
#mpblkbtn.active { border-color:#fff; box-shadow:0 0 26px #4db2ff, 0 4px 0 rgba(0,0,0,.35); }
#mpjumpbtn { background:radial-gradient(circle at 35% 30%,#d6ffe9,#2edf7a 70%); }
#vign { position:fixed; inset:0; z-index:5; pointer-events:none;
  background:radial-gradient(ellipse at center, transparent 52%, rgba(16,4,0,.38) 78%, rgba(8,1,0,.62) 100%); }
.stat { color:#ffe9d6; font-size:15px; margin:4px 0; font-weight:600; }
.stat b { color:#ffd76a; }
#clskey { display:flex; gap:10px; margin-top:10px; justify-content:center; flex-wrap:wrap; }
#clskey span { font-size:11px; color:#ffe9d6; background:rgba(255,140,46,.12);
  border:1px solid rgba(255,140,46,.3); border-radius:8px; padding:3px 8px; font-weight:700; }
/* mode hub */
#hubbtns { display:flex; flex-direction:column; gap:10px; margin-top:18px; width:min(78vw,340px); }
.modebtn { pointer-events:auto; display:flex; align-items:center; gap:12px; text-align:left;
  background:linear-gradient(180deg,rgba(48,21,9,.92),rgba(22,10,4,.95)); border:2px solid rgba(255,150,60,.4); border-radius:14px;
  padding:12px 16px; cursor:pointer; color:#ffe9d6;
  box-shadow:0 5px 14px rgba(0,0,0,.40), inset 0 1px 0 rgba(255,220,160,.14);
  transition:transform .15s ease, box-shadow .15s ease, border-color .15s ease; }
.modebtn:active { transform:scale(.96); }
.modebtn:hover { transform:translateY(-2px); border-color:rgba(255,180,90,.78); box-shadow:0 9px 22px rgba(0,0,0,.48), 0 0 16px rgba(255,140,40,.28), inset 0 1px 0 rgba(255,220,160,.18); }
.modebtn .ic { font-size:30px; filter:drop-shadow(0 3px 4px rgba(0,0,0,.55)); }
.modebtn .nm { font:900 16px system-ui; letter-spacing:1px; color:#ffd76a; }
.modebtn .ds { font:600 11px system-ui; color:#c98a5a; margin-top:2px; }
/* leaderboards */
#lbtabs { display:flex; gap:8px; margin:14px 0 6px; }
.lbtab { pointer-events:auto; background:rgba(30,14,6,.9); border:2px solid rgba(255,150,60,.35);
  color:#ffd76a; border-radius:10px; padding:8px 16px; font:800 13px system-ui; cursor:pointer; }
.lbtab.on { background:rgba(255,120,30,.25); border-color:#ffb347; }
#lblist { width:min(78vw,340px); max-height:38vh; overflow-y:auto; margin-top:6px; }
.lbrow { display:flex; justify-content:space-between; align-items:center; padding:8px 12px;
  border-bottom:1px solid rgba(255,150,60,.18); color:#ffe9d6; font:700 13px system-ui; }
.lbrow.me { background:rgba(255,150,60,.14); border-radius:8px; }
.lbrow .rk { color:#ffb347; font-weight:900; width:34px; }
.lbrow .sc { color:#7dff9a; font-weight:900; }
#lbnote { color:#8a6a5a; font-size:11px; margin-top:8px; letter-spacing:1px; }
/* toast + exp bar */
#toast { position:fixed; top:38%; left:50%; transform:translate(-50%,-50%); z-index:30; display:none;
  background:rgba(10,4,2,.92); border:2px solid #ffd76a; border-radius:14px; padding:14px 26px;
  color:#ffd76a; font:900 18px system-ui; letter-spacing:1px; text-align:center;
  box-shadow:0 0 40px rgba(255,180,60,.5); pointer-events:none; transition:opacity .4s; }
#expbar { position:fixed; top:48px; left:14px; z-index:9; display:none; pointer-events:none;
  background:rgba(10,4,2,.7); border:1px solid rgba(255,150,60,.4); border-radius:10px;
  padding:5px 10px; color:#ffd76a; font:800 11px system-ui; letter-spacing:1px; }
#expfillwrap { width:110px; height:6px; background:rgba(255,255,255,.12); border-radius:3px; margin-top:4px; }
#expfill { height:100%; width:0%; background:linear-gradient(90deg,#ffb347,#7dff9a); border-radius:3px; }
/* premium visual pass 2026-10-12: toast depth, name-field focus glow, tab + swatch motion, joystick glow */
#toast { background:linear-gradient(180deg,rgba(42,19,7,.95),rgba(12,5,2,.96)); box-shadow:0 18px 44px rgba(0,0,0,.55), 0 0 40px rgba(255,180,60,.5), inset 0 1px 0 rgba(255,230,180,.25); }
#pname { transition:border-color .15s, box-shadow .15s; }
#pname:focus { outline:none; border-color:#ffd76a; box-shadow:0 0 14px rgba(255,180,60,.45); }
.lbtab { transition:background .15s, border-color .15s, transform .1s; }
.lbtab:active { transform:scale(.95); }
.pcsw { transition:transform .12s, box-shadow .12s, border-color .12s; }
.pcsw:hover { transform:scale(1.1); }
#knob { box-shadow:0 0 22px rgba(255,140,40,.85), inset 0 2px 5px rgba(255,255,255,.45); }
#joy { box-shadow:inset 0 0 24px rgba(0,0,0,.35), 0 0 18px rgba(255,120,40,.18); backdrop-filter:blur(3px); -webkit-backdrop-filter:blur(3px); }
/* ===== short-screen compaction (audit 2026-10-18 §3.4): landscape phones (height <= 500px) only.
   Desktop / tall screens are untouched — every rule below lives inside this media query.
   Fixes: title #startbtn clipped 11px below the fold; #createov #pstart 42px below the fold at open;
   eases #hubov's 1,179px mode-list scroll. CSS-only — no script blocks touched (no CSP hash churn). */
@media (max-height:500px) {
  .ov { padding:1vh 0; }
  .ov .panel { padding:12px 20px; }
  h1.logo { font-size:46px; }
  .sub { font-size:11px; margin-top:6px; }
  .tag { font-size:11px; margin-top:5px; }
  #clskey { margin-top:6px; gap:6px; }
  .bigbtn { margin-top:12px; font-size:17px; padding:10px 34px; }
  #startbtn { min-height:48px; }
  /* "Who's playing?" card: the logo carries an inline 48px font-size, hence !important */
  #createov .panel { padding:10px 20px; }
  #createov .logo { font-size:30px !important; line-height:1; }
  .clabel { margin:8px 0 4px; font-size:11px; }
  #pname { padding:8px 12px; font-size:16px; }
  #pcswatches { gap:8px; }
  .pcsw { width:32px; height:32px; }
  #pstart { margin-top:10px; }
  /* mode hub: smaller logo (inline 56px, hence !important), tighter cards and gaps */
  #hubov .logo { font-size:30px !important; line-height:1; }
  #hubbtns { margin-top:8px; gap:6px; }
  .modebtn { padding:7px 12px; border-radius:12px; gap:10px; }
  .modebtn .ic { font-size:21px; }
  .modebtn .nm { font-size:14px; }
  .modebtn .ds { font-size:10px; margin-top:1px; }
  #fbgemrow { margin:0; }
  #fbgempill { padding:4px 14px; font-size:13px; }
}

.mpmodebtn { background:rgba(255,255,255,0.08); border:2px solid rgba(255,255,255,0.15); color:#ffe9d6; border-radius:10px; padding:8px 14px; font-size:14px; font-weight:700; cursor:pointer; font-family:inherit; }
.mpmodebtn.on { background:linear-gradient(180deg,#ff8c2e,#cc5a00); border-color:#ffd76a; }
.mpplayer { display:flex; align-items:center; gap:8px; padding:6px 10px; margin:4px 0; background:rgba(255,255,255,0.06); border-radius:8px; font-size:14px; }
.mpplayer .rdot { width:10px; height:10px; border-radius:50%; background:#666; flex-shrink:0; }
.mpplayer.ready .rdot { background:#4aff6a; }
.mpplayer .teamtag { font-size:11px; font-weight:700; padding:2px 8px; border-radius:6px; }
.mpplayer .team0 { background:#3ca9ff; color:#fff; }
.mpplayer .team1 { background:#ff5a3c; color:#fff; }
.mpplayer .hostname { color:#ffd76a; }
  /* ===== Fire Babys Style Studio + Store ===== */
  #fbgemrow { display:flex; justify-content:center; margin:2px 0 10px; }
  #fbgempill { pointer-events:auto; background:rgba(30,14,6,.9); border:2px solid #4de88a;
    border-radius:999px; padding:8px 18px; color:#c8ffd6; font:900 16px system-ui; letter-spacing:1px;
    box-shadow:0 0 24px rgba(77,232,138,.25); }
  .swrow { display:flex; flex-wrap:wrap; gap:8px; justify-content:center; margin:6px 0 4px; max-width:340px; }
  .swbtn { pointer-events:auto; border:2px solid rgba(255,150,60,.4); border-radius:12px;
    background:rgba(30,14,6,.9); color:#ffe9d6; font:800 13px system-ui; padding:8px 10px; cursor:pointer;
    min-width:44px; text-align:center; }
  .swbtn.sel { border-color:#ffd76a; background:rgba(255,140,46,.25); box-shadow:0 0 14px rgba(255,180,60,.5); }
  .swdot { width:34px; height:34px; border-radius:50%; border:2px solid rgba(255,255,255,.35); }
  .swbtn.sel .swdot { border-color:#ffd76a; }
  #custpreview { width:200px; height:200px; border-radius:18px; margin:4px auto 2px; display:block;
    background:radial-gradient(circle at 50% 35%, rgba(255,140,46,.25), rgba(10,4,2,.6) 75%);
    border:2px solid rgba(255,150,60,.4); }
  .storetabs { display:flex; gap:6px; justify-content:center; margin:8px 0; flex-wrap:wrap; }
  .stab { pointer-events:auto; border:2px solid rgba(255,150,60,.4); border-radius:12px; padding:8px 14px;
    background:rgba(30,14,6,.9); color:#ffe9d6; font:900 13px system-ui; letter-spacing:1px; cursor:pointer; }
  .stab.sel { border-color:#ffd76a; background:rgba(255,140,46,.3); }
  .storegrid { display:grid; grid-template-columns:repeat(2, minmax(0,1fr)); gap:10px; margin-top:6px;
    max-width:360px; max-height:38vh; overflow-y:auto; -webkit-overflow-scrolling:touch; padding:2px; }
  .sitem { pointer-events:auto; background:rgba(30,14,6,.92); border:2px solid rgba(255,150,60,.4);
    border-radius:14px; padding:10px 8px; cursor:pointer; color:#ffe9d6; text-align:center; }
  .sitem .em { font-size:30px; }
  .sitem .nm { font:900 13px system-ui; margin-top:4px; }
  .sitem .ds { font:400 11px system-ui; color:#d8b89a; margin-top:2px; min-height:26px; }
  .sitem .pr { font:900 14px system-ui; color:#4de88a; margin-top:6px; }
  .sitem .pr.lock { color:#c98a5a; }
  .sitem.owned { border-color:#4de88a; }
  .sitem.equipped { border-color:#ffd76a; box-shadow:0 0 16px rgba(255,215,106,.55); }
  .sitem .badge { display:inline-block; font:900 10px system-ui; letter-spacing:1px; border-radius:8px;
    padding:3px 8px; margin-top:6px; }
  .sitem .badge.eq { background:#ffd76a; color:#2a1206; }
  .sitem .badge.ow { background:#4de88a; color:#0a2a12; }
  .gempacks { display:grid; grid-template-columns:repeat(2, minmax(0,1fr)); gap:10px; margin-top:6px; }
  .gpack { pointer-events:auto; background:rgba(30,14,6,.92); border:2px solid rgba(184,154,255,.5);
    border-radius:12px; padding:14px 10px; }
  .gpack .gq { font:900 26px system-ui; }
  .gpack .gt { font:900 10px system-ui; letter-spacing:2px; color:#b79aff; margin:4px 0 10px; }
  .gbigbtn { pointer-events:auto; font:900 14px system-ui; color:#1a0e04; cursor:pointer;
    background:linear-gradient(180deg,#ffd76a,#ff8c2e); border:3px solid #ff6a1a; border-radius:12px;
    padding:10px 14px; box-shadow:0 4px 0 #a33c10; }
  .gbigbtn:active { transform:translateY(3px); box-shadow:0 1px 0 #a33c10; }
  .sitem.confirm { border-color:#ff5a3c; animation:fbshake .3s; }
  @keyframes fbshake { 25%{transform:translateX(-4px)} 75%{transform:translateX(4px)} }
  #fbemotebtn { position:fixed; right:22px; bottom:118px; z-index:12; width:64px; height:64px; border-radius:50%;
    font-size:30px; display:none; align-items:center; justify-content:center;
    background:linear-gradient(180deg,#ffd76a,#ff8c2e); border:3px solid #ff6a1a;
    box-shadow:0 4px 0 #a33c10, 0 8px 18px rgba(255,106,26,.4); cursor:pointer; }
  #fbemotebtn.on { display:flex; }
  #fbemotepop { position:fixed; right:86px; bottom:112px; z-index:13; display:none; gap:8px;
    background:rgba(10,4,2,.92); border:2px solid rgba(255,150,60,.5); border-radius:14px; padding:10px; }
  #fbemotepop.on { display:flex; }
  #fbemotepop button { font-size:28px; background:rgba(255,140,46,.15); border:2px solid rgba(255,150,60,.4);
    border-radius:12px; padding:6px 10px; cursor:pointer; }

/* ---- banner (hub + content pages) ---- */
#fb-seasonal-banner{background:linear-gradient(90deg,#2a1052,#4b1d8f 45%,#2a1052);color:#ffe9d6;text-align:center;padding:12px 16px 11px;border-bottom:3px solid #ff8c1a;box-shadow:0 4px 24px rgba(124,58,237,.35);position:relative;z-index:60}
#fb-seasonal-banner .fb-sb-main{font-size:clamp(18px,3.6vw,26px);font-weight:900;letter-spacing:.5px;color:#ffb347;text-shadow:0 2px 14px rgba(255,140,26,.45);line-height:1.25}
#fb-seasonal-banner .fb-sb-sub{font-size:clamp(12px,2.6vw,14.5px);font-weight:600;color:#e9defc;margin-top:3px;line-height:1.4}
/* ---- decoration layers (never clickable, below menus) ---- */
#fb-seasonal-wall{position:fixed;inset:0;pointer-events:none;z-index:0;overflow:hidden}
#fb-seasonal-wall .fb-sb-wall-glyph{position:absolute;line-height:1;opacity:.09}
#fb-seasonal-decor{position:fixed;inset:0;pointer-events:none;z-index:90}
html.fb-mode-game #fb-seasonal-decor{z-index:2}
#fb-seasonal-decor .fb-sb-glyph{position:absolute;line-height:1;filter:drop-shadow(0 4px 10px rgba(0,0,0,.45))}
#fb-seasonal-ambience{position:fixed;inset:0;pointer-events:none;z-index:89;overflow:hidden}
#fb-seasonal-ambience .fb-sb-fall{position:absolute;top:-8vh;line-height:1;opacity:.5;animation-name:fb-sb-fall;animation-timing-function:linear;animation-iteration-count:infinite}
@keyframes fb-sb-fall{from{transform:translate3d(0,-8vh,0) rotate(-8deg)}to{transform:translate3d(3vw,112vh,0) rotate(38deg)}}
@keyframes fb-sb-bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-9px)}}
.fb-sb-bob{animation:fb-sb-bob 3.6s ease-in-out infinite}
/* ---- game-page badge ---- */
.fb-sb-badge{position:absolute;left:50%;bottom:6px;transform:translateX(-50%);font-size:17px;letter-spacing:2px;opacity:.55;line-height:1;white-space:nowrap}
/* ---- accents: every page ---- */
html.fb-theme-halloween ::selection{background:rgba(255,140,26,.5);color:#fff}
html.fb-mode-page body{background-color:#1c0a2a}
/* ---- hub showcase: deep-purple night + pumpkin glow ---- */
html.fb-mode-hub body{background:radial-gradient(1100px 560px at 50% -120px,rgba(124,58,237,.34),transparent 62%),radial-gradient(700px 380px at 85% 110%,rgba(255,140,26,.16),transparent 60%),#170a26}
html.fb-mode-hub nav.top{background:rgba(23,10,38,.96);border-bottom-color:rgba(155,89,182,.55)}
html.fb-mode-hub .hero{background:radial-gradient(ellipse at 50% 0%,rgba(255,140,26,.20),transparent 65%);border-bottom-color:rgba(155,89,182,.55)}
html.fb-mode-hub .hero h1{color:#ffb347;text-shadow:0 0 26px rgba(124,58,237,.65),0 4px 30px rgba(255,106,26,.35)}
