*{box-sizing:border-box;margin:0;padding:0}
:root{
  --flame:#ff6a1a; --ember:#e8352c; --gold:#ffd76a; --cream:#ffe9d6;
  --ink:#1a0d06; --sky:#7fd4ff; --card:rgba(255,255,255,.045);
}
::selection{background:rgba(255,106,26,.45);color:#fff}
body{font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  background:radial-gradient(1200px 620px at 50% -120px,rgba(255,106,26,.16),transparent 60%),#1a0d06;color:var(--cream);line-height:1.55}
a{color:#ff9d5c}
.wrap{max-width:1080px;margin:0 auto;padding:0 16px}
/* NAV */
nav.top{position:sticky;top:0;z-index:100;background:rgba(26,13,6,.96);border-bottom:2px solid rgba(255,106,26,.35);backdrop-filter:blur(6px);color:#ffe9d6}
nav.top .wrap{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;flex-wrap:wrap;gap:8px 16px}
.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:#ffb347;font-weight:900;letter-spacing:1px;font-size:20px}
.brand svg{width:34px;height:34px}
nav.top a.navlink{color:#ffd9ae;text-decoration:none;font-weight:700;font-size:15px;margin-left:16px;transition:color .15s}
nav.top a.navlink:hover{color:var(--gold)}
/* HERO */
.hero{background:radial-gradient(ellipse at 50% 0%,rgba(255,106,26,.24),transparent 65%);
  color:var(--cream);text-align:center;padding:44px 16px 40px;position:relative;overflow:hidden;border-bottom:2px solid rgba(255,106,26,.25)}
.hero .mascots{display:flex;justify-content:center;gap:14px;margin-bottom:12px}
.hero .mascots svg{filter:drop-shadow(0 6px 16px rgba(255,106,26,.35))}
.hero h1{font-size:clamp(30px,6vw,52px);font-weight:900;letter-spacing:-.5px;margin:6px 0 10px;color:#ffb347;text-shadow:0 4px 30px rgba(255,106,26,.35)}
.hero h1 .hl{color:#ffd76a;text-shadow:0 2px 0 rgba(163,60,16,.8)}
.hero p.pitch{max-width:640px;margin:0 auto 20px;font-size:clamp(15px,3.4vw,19px);font-weight:600;color:#ffd9ae}
.btn{display:inline-block;background:linear-gradient(180deg,#ffd76a,#ff8c2e);color:#2a1206;font-weight:900;font-size:18px;
  padding:14px 34px;border-radius:999px;text-decoration:none;border:3px solid #ff6a1a;
  box-shadow:0 6px 0 #a33c10,0 10px 24px rgba(255,106,26,.35);transition:transform .08s,box-shadow .08s}
.btn:hover{transform:translateY(-2px)}
.btn:active{transform:translateY(3px);box-shadow:0 2px 0 #a33c10}
.btn.alt{background:linear-gradient(180deg,#7de8ff,#1e9fd8);color:#06283a;border-color:#1e9fd8;box-shadow:0 6px 0 #0f5e85,0 10px 24px rgba(30,159,216,.35)}
.prize{display:inline-block;background:rgba(255,255,255,.05);border:2px dashed rgba(255,179,71,.65);border-radius:14px;
  padding:8px 18px;font-weight:800;margin-top:16px;font-size:15px;color:#ffe9d6;box-shadow:inset 0 1px 0 rgba(255,255,255,.08)}
.prize b{color:var(--gold)}
.badge{display:inline-flex;align-items:center;gap:8px;background:rgba(63,174,74,.12);border:2px solid rgba(63,174,74,.5);
  color:#bfe9c2;font-weight:700;border-radius:999px;padding:8px 16px;margin-top:14px;font-size:14px}
/* SECTIONS */
section.block{padding:36px 0}
h2.sec{font-size:clamp(22px,4.5vw,32px);font-weight:900;letter-spacing:1px;margin-bottom:6px;color:#ffb347}
p.sub{margin-bottom:18px;color:#d8b89a;font-size:16px}
/* GRID */
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:18px}
.card{background:linear-gradient(180deg,rgba(255,255,255,.06),rgba(255,255,255,.03));border-radius:20px;overflow:hidden;border:2px solid rgba(255,106,26,.3);
  box-shadow:0 10px 28px rgba(0,0,0,.35);display:flex;flex-direction:column;transition:transform .15s,border-color .15s,box-shadow .15s}
.card:hover{transform:translateY(-4px);border-color:rgba(255,179,71,.75);box-shadow:0 16px 36px rgba(0,0,0,.45),0 0 24px rgba(255,106,26,.18)}
.card .thumb{height:150px;display:flex;align-items:center;justify-content:center;position:relative}
.card .thumb.splash{background:linear-gradient(135deg,#4fc3ff 0%,#1e88e5 60%,#0d47a1 100%)}
.card .thumb.soon{background:repeating-linear-gradient(45deg,#2b1408 0 16px,#211006 16px 32px)}
.card .thumb svg{width:92px;height:92px;filter:drop-shadow(0 4px 0 rgba(0,0,0,.25))}
.card .body{padding:14px 16px 16px;flex:1;display:flex;flex-direction:column}
.card h3{font-size:19px;margin-bottom:4px;color:#ffd76a}
.card .by{font-size:13px;color:#c9a06a;margin-bottom:8px}
.card p.desc{font-size:14px;color:#e8c9a8;flex:1}
.card .meta{display:flex;justify-content:space-between;align-items:center;margin-top:12px}
.card .plays{font-size:13px;font-weight:700;color:#c9a06a}
.playbtn{background:linear-gradient(180deg,#ffd76a,#ff8c2e);color:#2a1206;font-weight:900;text-decoration:none;
  padding:9px 22px;border-radius:999px;border:2px solid #ff6a1a;box-shadow:0 4px 0 #a33c10;transition:transform .08s,box-shadow .08s}
.playbtn:hover{transform:translateY(-2px)}
.playbtn:active{transform:translateY(2px);box-shadow:0 1px 0 #a33c10}
.tag-soon{position:absolute;top:10px;left:10px;background:rgba(26,13,6,.92);border:1px solid rgba(255,215,106,.5);color:var(--gold);
  font-size:12px;font-weight:800;padding:4px 12px;border-radius:999px;letter-spacing:1px}
.card.featured{border-color:rgba(30,159,216,.65);box-shadow:0 10px 28px rgba(0,0,0,.35),0 0 24px rgba(30,159,216,.16)}
.card.featured .tag-soon{background:#1e9fd8;border-color:transparent;color:#fff}
/* AD SLOTS */
.adslot{border:3px dashed rgba(255,179,71,.35);border-radius:16px;background:rgba(255,255,255,.03);color:#a87f5c;
  text-align:center;padding:26px 12px;font-size:13px;font-weight:700;margin:18px 0}
.adslot small{display:block;font-weight:400;font-size:12px;margin-top:4px}
/* CTA BANNER */
.cta{background:linear-gradient(180deg,rgba(255,106,26,.14),rgba(232,53,44,.1)),rgba(255,255,255,.04);border:2px solid rgba(255,106,26,.4);box-shadow:0 14px 34px rgba(0,0,0,.35);color:#ffe9d6;border-radius:24px;padding:30px 22px;text-align:center;margin:10px 0 0}
.cta h2{font-size:clamp(22px,5vw,32px);margin-bottom:8px;color:#ffb347}
.cta p{color:#ffd9a0;margin-bottom:18px;font-weight:600}
/* FORM */
form.card-form,.card-form{background:linear-gradient(180deg,rgba(255,255,255,.06),rgba(255,255,255,.03));border:2px solid rgba(255,106,26,.3);border-radius:22px;padding:24px;max-width:640px;margin:0 auto;box-shadow:0 14px 34px rgba(0,0,0,.35);color:#ffe9d6}
form.card-form label{display:block;font-weight:800;margin:14px 0 6px;font-size:15px}
form.card-form input[type=text],form.card-form input[type=email],
form.card-form textarea,form.card-form input[type=url]{
  width:100%;padding:12px 14px;border:2px solid rgba(255,106,26,.35);background:rgba(0,0,0,.35);color:#ffe9d6;border-radius:12px;font-size:16px;font-family:inherit}
form.card-form input:focus,form.card-form textarea:focus{border-color:#ff8c2e;outline:none;box-shadow:0 0 0 3px rgba(255,140,46,.25)}
form.card-form textarea{min-height:110px;resize:vertical}
form.card-form .rules{display:flex;gap:10px;align-items:flex-start;margin-top:16px;font-size:14px}
form.card-form .rules input{margin-top:4px;transform:scale(1.3)}
form.card-form button{margin-top:20px;width:100%}
#formMsg{display:none;margin-top:18px;background:rgba(63,174,74,.12);border:2px solid rgba(63,174,74,.5);border-radius:14px;
  padding:16px;font-weight:700;color:#bfe9c2;text-align:center}
/* EMAIL CAPTURE */
.news{background:linear-gradient(135deg,#ff8c2e,#e8352c);border:2px solid rgba(255,215,106,.4);box-shadow:0 14px 34px rgba(232,53,44,.25);border-radius:22px;padding:28px 20px;
  text-align:center;color:#fff;margin-top:26px}
.news h2{margin-bottom:6px}
.news p{color:#ffe3c2;margin-bottom:16px;font-weight:600}
.news .row{display:flex;gap:10px;max-width:480px;margin:0 auto}
.news input{flex:1;padding:13px 16px;border-radius:999px;border:none;font-size:16px;background:rgba(255,247,236,.96);color:#2a1206}
.news button{background:var(--ink);color:#ffe9d6;border:none;border-radius:999px;
  padding:13px 26px;font-weight:800;font-size:16px;cursor:pointer}
#newsMsg{display:none;margin-top:14px;font-weight:800}
/* FOOTER */
footer{background:rgba(0,0,0,.25);border-top:2px solid rgba(255,106,26,.3);color:#d8b89a;text-align:center;padding:30px 16px;margin-top:40px}
footer .flames{font-size:26px;margin-bottom:8px}
footer p{font-size:14px;color:#a87f5c}
footer .line{font-weight:800;color:var(--gold);margin-top:12px;font-size:16px}
/* Voting banner (injected at runtime by voting.js — hooks/structure untouched):
   its light card keeps dark text, as it had on the old light theme */
.vote-banner{color:#2b1a0e}
@media(max-width:560px){.news .row{flex-direction:column}}
@media(max-width:420px){.grid{grid-template-columns:1fr}}

