/* fbvis-cycle1: card presentation pass — medallion portrait frames, per-character
   element tints on the FRAME only (faces/art unchanged), chips, focus states. */
.card{position:relative;overflow:hidden;--t1:#ff6a1a;--t2:#7a2d00}
.card::before{content:"";position:absolute;top:0;left:0;right:0;height:5px;background:linear-gradient(90deg,transparent,var(--t1),transparent)}
.grid:not(.villains) .card:nth-child(1){--t1:#ff6a1a;--t2:#7a2d00}
.grid:not(.villains) .card:nth-child(2){--t1:#c98a4a;--t2:#5f3d17}
.grid:not(.villains) .card:nth-child(3){--t1:#ffd23f;--t2:#8a6410}
.grid:not(.villains) .card:nth-child(4){--t1:#ff4a3a;--t2:#7c1d12}
