.grid.villains .card:nth-child(1){--t1:#8a9a5b;--t2:#3d4726}
.grid.villains .card:nth-child(2){--t1:#e8c93a;--t2:#6e5c0e}
.grid.villains .card:nth-child(3){--t1:#4aa8ff;--t2:#173f6e}
.grid.villains .card:nth-child(4){--t1:#9aa4b0;--t2:#3c434c}
