body{background:radial-gradient(120% 90% at 50% 0%,rgba(255,123,28,0.13),transparent 55%),radial-gradient(110% 100% at 50% 115%,rgba(255,123,28,0.09),transparent 60%),#140a06}
button:focus-visible,a:focus-visible,input:focus-visible,[tabindex]:focus-visible{outline:3px solid #ffb347;outline-offset:2px;border-radius:6px}
#ctlBtns button{background:linear-gradient(180deg,rgba(34,18,9,.88),rgba(14,7,3,.88));border:1px solid rgba(255,255,255,.28);box-shadow:0 2px 10px rgba(0,0,0,.45),inset 0 1px 0 rgba(255,255,255,.15);transition:filter .12s ease,transform .12s ease}
#ctlBtns button:hover{filter:brightness(1.35)}
.ov{background:radial-gradient(90% 62% at 50% 28%,rgba(255,123,28,0.18),transparent 65%),rgba(18,7,2,.93)}
.ov h1{filter:drop-shadow(0 3px 14px rgba(255,123,28,0.4))}
.btn{transition:transform .12s ease,filter .12s ease,box-shadow .12s ease}
.btn:hover:not(:active){filter:brightness(1.08);transform:translateY(-1px)}
.safety{box-shadow:0 6px 18px rgba(0,0,0,.35)}
#hud>span{background:linear-gradient(180deg,rgba(34,18,9,.85),rgba(14,7,3,.85));border:1px solid rgba(255,255,255,.22);border-radius:999px;padding:4px 14px;box-shadow:0 2px 10px rgba(0,0,0,.45)}
@media (prefers-reduced-motion:reduce){#overlay button,.lvlBtn,#back,#sysbtns button,#ctlBtns button,.btn,.dbtn,.abtn{transition:none}}

/* ---- banner (hub + content pages) ---- */
#fb-seasonal-banner{background:linear-gradient(90deg,#2a1052,#4b1d8f 45%,#2a1052);color:#ffe9d6;text-align:center;padding:12px 16px 11px;border-bottom:3px solid #ff8c1a;box-shadow:0 4px 24px rgba(124,58,237,.35);position:relative;z-index:60}
#fb-seasonal-banner .fb-sb-main{font-size:clamp(18px,3.6vw,26px);font-weight:900;letter-spacing:.5px;color:#ffb347;text-shadow:0 2px 14px rgba(255,140,26,.45);line-height:1.25}
#fb-seasonal-banner .fb-sb-sub{font-size:clamp(12px,2.6vw,14.5px);font-weight:600;color:#e9defc;margin-top:3px;line-height:1.4}
/* ---- decoration layers (never clickable, below menus) ---- */
#fb-seasonal-wall{position:fixed;inset:0;pointer-events:none;z-index:0;overflow:hidden}
#fb-seasonal-wall .fb-sb-wall-glyph{position:absolute;line-height:1;opacity:.09}
#fb-seasonal-decor{position:fixed;inset:0;pointer-events:none;z-index:90}
html.fb-mode-game #fb-seasonal-decor{z-index:2}
#fb-seasonal-decor .fb-sb-glyph{position:absolute;line-height:1;filter:drop-shadow(0 4px 10px rgba(0,0,0,.45))}
#fb-seasonal-ambience{position:fixed;inset:0;pointer-events:none;z-index:89;overflow:hidden}
#fb-seasonal-ambience .fb-sb-fall{position:absolute;top:-8vh;line-height:1;opacity:.5;animation-name:fb-sb-fall;animation-timing-function:linear;animation-iteration-count:infinite}
@keyframes fb-sb-fall{from{transform:translate3d(0,-8vh,0) rotate(-8deg)}to{transform:translate3d(3vw,112vh,0) rotate(38deg)}}
@keyframes fb-sb-bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-9px)}}
.fb-sb-bob{animation:fb-sb-bob 3.6s ease-in-out infinite}
/* ---- game-page badge ---- */
.fb-sb-badge{position:absolute;left:50%;bottom:6px;transform:translateX(-50%);font-size:17px;letter-spacing:2px;opacity:.55;line-height:1;white-space:nowrap}
/* ---- accents: every page ---- */
html.fb-theme-halloween ::selection{background:rgba(255,140,26,.5);color:#fff}
html.fb-mode-page body{background-color:#1c0a2a}
/* ---- hub showcase: deep-purple night + pumpkin glow ---- */
html.fb-mode-hub body{background:radial-gradient(1100px 560px at 50% -120px,rgba(124,58,237,.34),transparent 62%),radial-gradient(700px 380px at 85% 110%,rgba(255,140,26,.16),transparent 60%),#170a26}
html.fb-mode-hub nav.top{background:rgba(23,10,38,.96);border-bottom-color:rgba(155,89,182,.55)}
html.fb-mode-hub .hero{background:radial-gradient(ellipse at 50% 0%,rgba(255,140,26,.20),transparent 65%);border-bottom-color:rgba(155,89,182,.55)}
html.fb-mode-hub .hero h1{color:#ffb347;text-shadow:0 0 26px rgba(124,58,237,.65),0 4px 30px rgba(255,106,26,.35)}
html.fb-mode-hub .card{border-color:rgba(155,89,182,.5)}
html.fb-mode-hub .card:hover{border-color:#ff8c1a;box-shadow:0 16px 36px rgba(0,0,0,.45),0 0 26px rgba(124,58,237,.35)}
html.fb-mode-hub footer{border-top-color:rgba(155,89,182,.5)}
html.fb-mode-hub .hero,html.fb-mode-hub .whatsnew,html.fb-mode-hub .wrap,html.fb-mode-hub footer{position:relative;z-index:1}
/* ---- reduced motion: no falling/floating glyphs ---- */
@media (prefers-reduced-motion: reduce){#fb-seasonal-ambience{display:none}.fb-sb-bob{animation:none}}

scripts:
const cv=document.getElementById('c'),ctx=cv.getContext('2d');
let W,H;function rs(){W=cv.width=cv.clientWidth;H=cv.height=cv.clientHeight;}window.addEventListener('resize',rs);rs();
const G=0.7,JV=-13.5;
let py,vy,onGround,gaps,speed,score,best=+(localStorage.getItem('br_best')||0),run=false,frame=0;
document.getElementById('best').textContent=best;
/* gamer-check: sound (this game shipped silent) + pause */
let AC=null,MUTED=false,paused=false,lastShown=-1;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+(delay||0);
 const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
 o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
 g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={jump(){tone(300,660,0.14,'sine',0.13);},djump(){tone(500,900,0.14,'sine',0.13);},hit(){tone(220,70,0.25,'square',0.15);noiseHit();},bonk(){tone(900,300,0.12,'square',0.12);},rocket(){tone(150,900,0.4,'sawtooth',0.1);},over(){tone(420,90,0.45,'sawtooth',0.14);tone(210,60,0.55,'square',0.09,0.08);},click(){tone(600,600,0.06,'square',0.1);}};
function noiseHit(){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime,len=ac.sampleRate*0.15,buf=ac.createBuffer(1,len,ac.sampleRate),d=buf.getChannelData(0);for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);const s=ac.createBufferSource();s.buffer=buf;const g=ac.createGain();g.gain.setValueAtTime(0.15,t);g.gain.exponentialRampToValueAtTime(0.001,t+0.15);s.connect(g);g.connect(ac.destination);s.start(t);}
const groundY=()=>H*0.78;
const embers=[];for(let i=0;i<24;i++)embers.push({x:Math.random(),y:Math.random(),s:1+Math.random()*2.2,v:12+Math.random()*26,ph:Math.random()*6.28});let tick=0;
/* ===== Jeff 2026-10-13 additions: double jump, hazard birds, step platforms, secret rocket mode ===== */
let jumps=0,hearts=3,invulnT=0,floorY=0,plats=[],birds=[],birdT=5,pressT=0,holding=false,rocketOn=false,rocketFuel=100,rocketUsed=false;
const PX=()=>W*0.25;
function setHearts(){document.getElementById('hearts').textContent='❤️'.repeat(Math.max(0,hearts))||'💔';}
function reset(){py=groundY()-26;vy=0;onGround=true;gaps=[];speed=5;score=0;frame=0;lastShown=-1;paused=false;document.getElementById('pauseOv').classList.add('hidden');
 jumps=0;hearts=3;invulnT=0;floorY=groundY();plats=[];birds=[];birdT=6;pressT=0;holding=false;rocketOn=false;rocketFuel=100;rocketUsed=false;setHearts();
 for(let i=0;i<4;i++)gaps.push({x:W+i*(W*0.55)+200,w:70+Math.random()*60});
 // stone step platforms you can land on and jump off of (some bridge the lava gaps)
 for(let i=0;i<3;i++){const gx=gaps[i%gaps.length];plats.push({x:gx.x-30,w:gx.w+60,h:52});}
 for(let i=0;i<3;i++)plats.push({x:W*0.7+i*W*0.6,w:110+Math.random()*70,h:56+((i*37)%50)});}
function pressJump(){if(!run||paused)return;
 if(onGround){vy=JV;onGround=false;jumps=1;sfx.jump();}
 else if(jumps<2){vy=JV*0.92;jumps=2;sfx.djump();for(let i=0;i<6;i++)embers.push({x:PX()/W,y:(py+20)/H,s:1.5,v:-30,ph:Math.random()*6});}}
function birdHit(){if(invulnT>0||rocketOn)return;hearts--;setHearts();invulnT=1.6;sfx.hit();vy=-7;
 if(hearts<=0){gameOver(true);}}
document.getElementById('startBtn').onclick=()=>{audio();sfx.click();document.getElementById('title').classList.add('hidden');reset();run=true;};
document.getElementById('pauseBtn').onclick=e=>{e.stopPropagation();if(run&&!paused){paused=true;document.getElementById('pauseOv').classList.remove('hidden');}};
document.getElementById('resumeBtn').onclick=()=>{paused=false;document.getElementById('pauseOv').classList.add('hidden');};
document.getElementById('prestartBtn').onclick=()=>{document.getElementById('pauseOv').classList.add('hidden');reset();run=true;};
document.getElementById('muteBtn').onclick=e=>{e.stopPropagation();MUTED=!MUTED;e.currentTarget.textContent=MUTED?'🔇':'🔊';};
document.getElementById('againBtn').onclick=()=>{document.getElementById('over').classList.add('hidden');reset();run=true;};
window.addEventListener('pointerdown',e=>{if(run&&!e.target.classList.contains('btn')&&!(e.target.closest&&e.target.closest('#ctlBtns'))){holding=true;pressT=0;pressJump();}});
window.addEventListener('pointerup',()=>{holding=false;});
window.addEventListener('pointercancel',()=>{holding=false;});
document.getElementById('jumpBtn').addEventListener('pointerdown',e=>{e.stopPropagation();holding=true;pressT=0;pressJump();});
document.getElementById('jumpBtn').addEventListener('pointerup',e=>{e.stopPropagation();holding=false;});
window.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();if(!e.repeat){holding=true;pressT=0;pressJump();}}
 if((e.code==='KeyP'||e.code==='Escape')&&run){paused=!paused;document.getElementById('pauseOv').classList.toggle('hidden',!paused);}});
window.addEventListener('keyup',e=>{if(e.code==='Space')holding=false;});
function fireBaby(x,y,r,face){ // cute fire baby
 const g=ctx.createRadialGradient(x,y-r*0.3,r*0.2,x,y,r*1.6);g.addColorStop(0,'#ffe27a');g.addColorStop(0.5,'#ffb347');g.addColorStop(1,'#ff7b1c');
 ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(x,y-r);ctx.quadraticCurveTo(x+r*1.1,y-r*0.2,x+r*0.75,y+r*0.7);ctx.quadraticCurveTo(x+r*0.4,y+r*1.15,x,y+r*1.05);ctx.quadraticCurveTo(x-r*0.4,y+r*1.15,x-r*0.75,y+r*0.7);ctx.quadraticCurveTo(x-r*1.1,y-r*0.2,x,y-r);ctx.shadowColor='#ff9a2a';ctx.shadowBlur=18;ctx.fill();ctx.shadowBlur=0;
 ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(x-r*0.32,y+r*0.1,r*0.2,0,7);ctx.arc(x+r*0.32,y+r*0.1,r*0.2,0,7);ctx.fill();
 ctx.fillStyle='#222';ctx.beginPath();ctx.arc(x-r*0.32,y+r*0.12,r*0.1,0,7);ctx.arc(x+r*0.32,y+r*0.12,r*0.1,0,7);ctx.fill();
 ctx.strokeStyle='#5a2400';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y+r*0.42,r*0.22,0.15*Math.PI,0.85*Math.PI);ctx.stroke();
 if(!onGround){ctx.strokeStyle='#5a2400';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x-r*1.15,y+r*0.3);ctx.lineTo(x-r*1.5,y-r*0.1);ctx.moveTo(x+r*1.15,y+r*0.3);ctx.lineTo(x+r*1.5,y-r*0.1);ctx.stroke();}
}
let lastT=0;
function loop(t){
 const _now=t||0;const dtF=Math.min(2.5,Math.max(0.2,lastT?((_now-lastT)/16.667):1));lastT=_now;
 tick+=dtF;
 ctx.clearRect(0,0,W,H);
 const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#3a1c07');sky.addColorStop(0.6,'#241005');sky.addColorStop(1,'#1a0d05');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
 ctx.save();ctx.globalCompositeOperation='lighter';for(const e of embers){const ey=H-((e.y*H+tick*e.v)%(H+24));const ex=(e.x*W+Math.sin(tick*0.02+e.ph)*12+W)%W;ctx.globalAlpha=0.5;ctx.fillStyle='#ff9a2a';ctx.beginPath();ctx.arc(ex,ey,e.s,0,7);ctx.fill();}ctx.restore();ctx.globalAlpha=1;
 // bg volcano silhouettes (positive-wrapped: they used to drift off-screen for good on long runs)
 ctx.fillStyle='#33190a';for(let i=0;i<5;i++){let bx=((i*W/4-frame*0.2)%(W+200)+(W+200))%(W+200)-100;ctx.beginPath();ctx.moveTo(bx,H*0.7);ctx.lineTo(bx+80,H*0.35);ctx.lineTo(bx+160,H*0.7);ctx.fill();}
 if(run&&!paused){
  frame+=dtF;
  const dtS=dtF/60,px=PX(),gy=groundY();
  if(invulnT>0)invulnT-=dtS;
  // --- SECRET ROCKET MODE: hold jump >0.22s. Fuel drains in flight, refills on the ground. ---
  if(holding){pressT+=dtS;if(pressT>0.22&&rocketFuel>0){if(!rocketOn){rocketOn=true;rocketUsed=true;sfx.rocket();} }}else{pressT=0;rocketOn=false;}
  if(rocketOn){rocketFuel=Math.max(0,rocketFuel-36*dtS);if(rocketFuel<=0)rocketOn=false;
   vy=-8.5;py+=vy*dtF;onGround=false;
   if(py<70){py=70;vy=0;}}
  else{
   if(onGround){
    // did the floor vanish? (platform scrolled away, or a lava gap opened under Blaze)
    let supported=(floorY===gy);
    if(floorY!==gy){const p=plats.find(p=>Math.abs(gy-p.h-floorY)<3);supported=!!(p&&px>p.x-8&&px<p.x+p.w+8);}
    else if(gaps.some(g=>px>g.x+8&&px<g.x+g.w-8))supported=false;
    if(!supported){onGround=false;vy=0;}
   }
   if(!onGround){
    const prevB=py+26;
    vy+=G*dtF;py+=vy*dtF;
    if(vy>=0){ // falling: land on a step platform whose top we crossed
     for(const p of plats){const top=gy-p.h;
      if(prevB<=top+2&&py+26>=top&&px>p.x-8&&px<p.x+p.w+8){py=top-26;vy=0;onGround=true;jumps=0;floorY=top;break;}}
    }
    if(!onGround&&py+26>=gy){ // reached ground level
     if(gaps.some(g=>px>g.x+8&&px<g.x+g.w-8)){ /* over lava: keep falling! */ }
     else{py=gy-26;vy=0;onGround=true;jumps=0;floorY=gy;}
    }
    if(py-30>H)gameOver(); // fell into the lava gap
   }
  }
  if(onGround)rocketFuel=Math.min(100,rocketFuel+30*dtS);
  speed=Math.min(13,5+score/400); // capped: uncapped speed became unreactable late-run
  score+=speed/10*dtF;const _sf=Math.floor(score);if(_sf!==lastShown){lastShown=_sf;document.getElementById('score').textContent=_sf;}
  for(let g of gaps){g.x-=speed*dtF;
   if(g.x+g.w<-50){const _far=Math.max.apply(null,gaps.map(o=>o.x));g.x=Math.max(W+40,_far+300+Math.random()*160);g.w=Math.min(165,70+Math.random()*60+score/80);} // capped width + guaranteed spacing: a gap is always jumpable
  }
  for(const p of plats){p.x-=speed*dtF;
   if(p.x+p.w<-60){const far=Math.max.apply(null,plats.map(o=>o.x+o.w).concat(gaps.map(o=>o.x+o.w)));p.x=far+240+Math.random()*160;p.w=110+Math.random()*80;p.h=52+Math.random()*54;}}
  // --- hazard birds: random grumps that swoop at Blaze ---
  birdT-=dtS;
  if(birdT<=0){birdT=3.5+Math.random()*4;birds.push({x:W+50,y:gy-70-Math.random()*130,vx:3+Math.random()*2,ph:Math.random()*6,dead:false,vy:0,rot:0});}
  for(const b of birds){
   if(b.dead){b.vy+=0.5;b.y+=b.vy*dtF;b.rot+=0.25*dtF;b.x-=speed*0.5*dtF;continue;}
   b.x-=(b.vx+speed*0.45)*dtF;b.y+=Math.sin(tick*0.15+b.ph)*0.8*dtF;
   if(Math.hypot(b.x-px,b.y-py)<42){
    if(rocketOn){b.dead=true;b.vy=-4;sfx.bonk();score+=25;}
    else{b.dead=true;b.vy=-3;birdHit();}
   }
  }
  birds=birds.filter(b=>b.x>-80&&b.y<H+80);
 }
 // ground with gaps
 ctx.fillStyle='#4a2c12';ctx.fillRect(0,groundY(),W,H-groundY());
 ctx.fillStyle='#5f3a18';for(let i=0;i<W;i+=40)ctx.fillRect(i-(frame*speed%40),groundY(),18,8);
 for(let g of gaps){ // lava in gaps
  let gg=ctx.createLinearGradient(0,groundY(),0,H);gg.addColorStop(0,'#ffdd44');gg.addColorStop(0.5,'#ff7b1c');gg.addColorStop(1,'#c22e00');
  ctx.fillStyle=gg;ctx.fillRect(g.x,groundY(),g.w,H-groundY());
  ctx.fillStyle='#ffedb0';for(let b=0;b<3;b++){let bx=g.x+((frame*2+b*37)%g.w);ctx.beginPath();ctx.arc(bx,groundY()+14+((b*23)%30),4,0,7);ctx.fill();}
 }
 // stone step platforms (land on top, jump off the edge)
 for(const p of plats){const top=groundY()-p.h;
  ctx.fillStyle='#6a5138';ctx.fillRect(p.x,top,p.w,p.h);
  ctx.fillStyle='#8a6c4c';ctx.fillRect(p.x,top,p.w,10);
  ctx.fillStyle='rgba(0,0,0,.25)';for(let sx=p.x+14;sx<p.x+p.w-8;sx+=30)ctx.fillRect(sx,top+22,16,6);
  ctx.strokeStyle='#3a2a16';ctx.lineWidth=2;ctx.strokeRect(p.x,top,p.w,p.h);}
 // hazard birds (grumpy enemy birds — NOT Fire Babys)
 for(const b of birds){
  ctx.save();ctx.translate(b.x,b.y);if(b.dead)ctx.rotate(b.rot);
  const flap=Math.sin(tick*0.6+b.ph)*(b.dead?2:9);
  ctx.fillStyle='#4a5a8a'; // wing
  ctx.beginPath();ctx.moveTo(-2,-4);ctx.lineTo(-16,-10-flap);ctx.lineTo(-4,4);ctx.closePath();ctx.fill();
  ctx.fillStyle='#5a6ea8';ctx.beginPath();ctx.ellipse(0,0,17,11,0,0,7);ctx.fill(); // body
  ctx.fillStyle='#7a90c8';ctx.beginPath();ctx.arc(13,-4,8,0,7);ctx.fill(); // head
  ctx.fillStyle='#ffb300';ctx.beginPath();ctx.moveTo(19,-5);ctx.lineTo(28,-2);ctx.lineTo(19,0);ctx.closePath();ctx.fill(); // beak
  ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(14,-6,3.4,0,7);ctx.fill();
  ctx.fillStyle='#141414';ctx.beginPath();ctx.arc(13.5,-6,1.8,0,7);ctx.fill();
  ctx.strokeStyle='#141414';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(9,-11);ctx.lineTo(18,-8);ctx.stroke(); // angry brow
  ctx.fillStyle='#4a5a8a';ctx.beginPath();ctx.moveTo(-15,0);ctx.lineTo(-24,-6);ctx.lineTo(-23,4);ctx.closePath();ctx.fill(); // tail
  ctx.restore();
 }
 // SECRET rocket flame + fuel meter
 if(rocketOn){const fl=26+Math.sin(tick*2.2)*8;
  const fg=ctx.createLinearGradient(0,py+20,0,py+20+fl*2);fg.addColorStop(0,'#fff3b0');fg.addColorStop(0.4,'#ffd23f');fg.addColorStop(1,'rgba(255,90,0,0)');
  ctx.fillStyle=fg;ctx.beginPath();ctx.moveTo(PX()-11,py+20);ctx.lineTo(PX()+11,py+20);ctx.lineTo(PX(),py+20+fl*2);ctx.closePath();ctx.fill();}
 if(rocketUsed&&run){ctx.fillStyle='rgba(0,0,0,.5)';ctx.fillRect(PX()-26,py-58,52,7);
  ctx.fillStyle=rocketOn?'#ffd23f':'#7fd4ff';ctx.fillRect(PX()-26,py-58,52*rocketFuel/100,7);}
 const _blink=invulnT>0&&Math.sin(tick*1.4)>0;
 ctx.globalAlpha=_blink?0.35:1;
 fireBaby(W*0.25,py,26);
 ctx.globalAlpha=1;
 requestAnimationFrame(loop);
}
function gameOver(byBird){if(!run)return;run=false;sfx.over();let s=Math.floor(score);document.getElementById('final').textContent=s;
 if(byBird)document.getElementById('overMsg').innerHTML='Those grumpy birds got Blaze!<br>Distance: <b id="final">'+s+'</b>m';
 if(s>best){best=s;localStorage.setItem('br_best',best);document.getElementById('best').textContent=best;}
 document.getElementById('over').classList.remove('hidden');}
/* ===== MUSIC (Jeff 2026-10-13): 'Ember Gallop' — Blaze Runner's own track.
   Synthesized Web Audio only (no files). 134 BPM, E minor, driving gallop bass,
   heroic pentatonic lead. Lightweight lookahead scheduler; mute via 🔊. ===== */
const _mf=m=>440*Math.pow(2,(m-69)/12);
const MUS={on:false,step:0,nextT:0,BPM:134,
 BASS:[40,0,40,40,0,40,0,40, 40,0,40,40,0,40,0,40, 36,0,36,36,0,36,0,36, 38,0,38,38,0,43,0,38],
 LEAD:[64,0,67,0,71,0,67,0, 64,0,67,0,74,0,71,67, 72,0,76,0,74,0,72,0, 74,0,71,0,69,0,67,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(MUTED||paused||!run){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-(audio()?audio().currentTime:0));
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.16,'square',0.055,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.22,'triangle',0.06,d);
  if(s%2===0)tone(120,42,0.12,'sine',0.14,d); // kick
  if(s%8===2||s%8===6){tone(190,120,0.07,'triangle',0.05,d);} // snare-ish tick
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());
reset();loop();

