scripts:
'use strict';
/* ============================================================
   CINDER'S ICE RINK CHAOS v2 — AAA Rebuild
   - Flick physics on slippery ice, 5 levels, star ratings
   - Combo system, trauma shake, particle ice shards
   - Parental gate, layered Web Audio
   ============================================================ */
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();

/* audio */
let AC=null,MUTED=false;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
function noise(dur,vol,delay=0,lp=3000){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const len=ac.sampleRate*dur,buf=ac.createBuffer(1,len,ac.sampleRate),d=buf.getChannelData(0);
  for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);
  const s=ac.createBufferSource();s.buffer=buf;const f=ac.createBiquadFilter();f.type='lowpass';f.frequency.value=lp;
  const g=ac.createGain();g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  s.connect(f);f.connect(g);g.connect(ac.destination);s.start(t);}

/* living ember backdrop (overhaul) */
const embers=[];
for(let i=0;i<24;i++)embers.push({x:Math.random()*Math.max(W,300),y:Math.random()*Math.max(H,300),s:1+Math.random()*2.5,v:12+Math.random()*26,o:0.22+Math.random()*0.5});
/* [w5b perf] Pre-baked glow sprites. Profiling (Chromium/SwiftShader, W2 rAF
   method): this game ran at 10.0 FPS with ~26 non-zero shadowBlur sets/frame;
   neutralising shadowBlur alone restored 59.9 FPS (fast siblings use <=1/frame).
   The ember loop (24 shadowed fills/frame) and the per-block shadowBlur were
   the hot-loop offenders, so both now blit a pre-rendered radial-glow sprite
   with the same colours/falloff instead of paying a shadow pass per frame. */
function makeGlowSprite(hex){const c=document.createElement('canvas');c.width=c.height=96;const x=c.getContext('2d');
  const r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);
  const gr=x.createRadialGradient(48,48,0,48,48,48);
  gr.addColorStop(0,`rgba(${r},${g},${b},0.9)`);gr.addColorStop(0.35,`rgba(${r},${g},${b},0.38)`);gr.addColorStop(1,`rgba(${r},${g},${b},0)`);
  x.fillStyle=gr;x.fillRect(0,0,96,96);return c;}
const EMBER_SPRITE=makeGlowSprite('#ffa53a');
const BLOCK_GLOW_ORANGE=makeGlowSprite('#ff7a2a'),BLOCK_GLOW_BLUE=makeGlowSprite('#7fd4ff');
function drawEmbers(){ctx.save();ctx.globalCompositeOperation='lighter';
  for(const e of embers){ctx.globalAlpha=e.o*(0.6+0.4*Math.sin(G.time*3+e.x*0.05));
    const r=e.s*7;ctx.drawImage(EMBER_SPRITE,e.x-r,e.y-r,r*2,r*2);}
  ctx.restore();}
function updateEmbers(dt){for(const e of embers){e.y-=e.v*dt;e.x+=Math.sin((G.time+e.y)*0.02)*0.3;
  if(e.y<-12){e.y=H+12;e.x=Math.random()*W;}}}
const sfx={
  flick(){noise(0.15,0.25,0,2000);tone(400,800,0.12,'sine',0.12);},
  slideSfx(){noise(0.3,0.08,0,800);},
  shatter(){noise(0.35,0.4,0,5000);tone(1400,300,0.3,'triangle',0.2);tone(2000,600,0.2,'sine',0.1,0.04);},
  hit(){tone(200,80,0.1,'square',0.15);noise(0.1,0.2,0,1000);},
  combo(n){[659,784,988,1175,1319].slice(0,Math.min(n,5)).forEach((f,i)=>tone(f,f,0.12,'sine',0.13,i*0.05));},
  win(){[523,659,784,1047].forEach((f,i)=>tone(f,f,0.25,'triangle',0.18,i*0.1));},
  click(){tone(600,600,0.06,'square',0.1);}
};

/* pools */
const particles=[],floaters=[];
for(let i=0;i<250;i++)particles.push({a:false});
for(let i=0;i<25;i++)floaters.push({a:false});
function spawnP(x,y,vx,vy,life,color,size){const p=particles.find(p=>!p.a);if(!p)return;
  p.a=true;p.x=x;p.y=y;p.vx=vx;p.vy=vy;p.life=life;p.max=life;p.color=color;p.size=size;}
function spawnText(x,y,txt,color='#ffd23f',size=20){const f=floaters.find(f=>!f.a);if(!f)return;
  f.a=true;f.x=x;f.y=y;f.txt=txt;f.color=color;f.size=size;f.life=1.2;}

/* trauma */
let trauma=0,hitStop=0,shakeX=0,shakeY=0;
function addTrauma(t){trauma=Math.min(1,trauma+t);}

/* state */
const G={state:'title',level:1,score:0,levelStartScore:0,shots:3,shotsUsed:0,combo:0,comboT:0,
  blocks:[],targets:[],time:0,dragBlock:null,dragX:0,dragY:0};
const ICE_FRICTION=0.995; // slippery!

function buildLevel(n){
  G.blocks=[];G.targets=[];G.shotsUsed=0;G.combo=0;boomQueue.length=0;booms.length=0;
  const cx=W/2,gy=H*0.82;
  const T=(x,y)=>G.targets.push({x,y,r:22,dead:false,wob:Math.random()*6});
  const B=(x,y)=>G.blocks.push({x,y,vx:0,vy:0,r:26,used:false,held:false,spin:0,vr:0});
  if(n===1){
    B(cx-120,gy-60);B(cx+120,gy-60);
    T(cx-60,gy-200);T(cx+60,gy-200);T(cx,gy-280);
    G.shots=3;
  }else if(n===2){
    B(cx-150,gy-60);B(cx,gy-60);B(cx+150,gy-60);
    T(cx-100,gy-180);T(cx+100,gy-180);T(cx-50,gy-300);T(cx+50,gy-300);
    G.shots=4;
  }else if(n===3){
    // diamond formation
    B(cx-100,gy-60);B(cx+100,gy-60);B(cx,gy-140);
    T(cx,gy-220);T(cx-80,gy-300);T(cx+80,gy-300);T(cx,gy-380);T(cx-40,gy-140);T(cx+40,gy-140);
    G.shots=4;
  }else if(n===4){
    B(cx-140,gy-60);B(cx+140,gy-60);B(cx-70,gy-140);B(cx+70,gy-140);
    for(let i=0;i<5;i++)T(cx-120+i*60,gy-240);
    T(cx-60,gy-340);T(cx+60,gy-340);T(cx,gy-420);
    G.shots=5;
  }else if(n===6){
    B(cx-160,gy-60);B(cx-80,gy-60);B(cx,gy-60);B(cx+80,gy-60);B(cx+160,gy-60);
    for(let i=0;i<6;i++)T(cx-150+i*60,gy-220);
    for(let i=0;i<4;i++)T(cx-90+i*60,gy-330);
    T(cx-40,gy-420);T(cx+40,gy-420);
    G.shots=5;
  }else if(n===7){
    B(cx-140,gy-60);B(cx+140,gy-60);B(cx-70,gy-140);B(cx+70,gy-140);B(cx,gy-60);
    for(let i=0;i<5;i++)T(cx-120+i*60,gy-240);
    for(let i=0;i<4;i++)T(cx-90+i*60,gy-340);
    T(cx-60,gy-430);T(cx,gy-430);T(cx+60,gy-430);T(cx,gy-160);
    G.shots=5;
  }else if(n===8){
    B(cx-150,gy-60);B(cx-50,gy-60);B(cx+50,gy-60);B(cx+150,gy-60);B(cx-75,gy-140);B(cx+75,gy-140);
    for(let i=0;i<6;i++)T(cx-150+i*60,gy-230);
    for(let i=0;i<5;i++)T(cx-120+i*60,gy-330);
    T(cx-60,gy-430);T(cx,gy-430);T(cx+60,gy-430);
    G.shots=6;
  }else if(n===9){
    B(cx-160,gy-60);B(cx+160,gy-60);B(cx-80,gy-120);B(cx+80,gy-120);B(cx,gy-60);B(cx,gy-180);
    for(let i=0;i<6;i++)T(cx-150+i*60,gy-250);
    for(let i=0;i<5;i++)T(cx-120+i*60,gy-350);
    for(let i=0;i<4;i++)T(cx-90+i*60,gy-440);
    G.shots=6;
  }else if(n===10){
    B(cx-160,gy-60);B(cx+160,gy-60);B(cx-80,gy-120);B(cx+80,gy-120);B(cx,gy-60);B(cx,gy-190);
    for(let i=0;i<7;i++)T(cx-165+i*55,gy-230);
    for(let i=0;i<6;i++)T(cx-150+i*60,gy-340);
    for(let i=0;i<4;i++)T(cx-90+i*60,gy-440);
    G.shots=6;
  }else{
    B(cx-160,gy-60);B(cx+160,gy-60);B(cx-80,gy-120);B(cx+80,gy-120);B(cx,gy-60);
    for(let i=0;i<6;i++)T(cx-150+i*60,gy-220);
    for(let i=0;i<4;i++)T(cx-90+i*60,gy-330);
    T(cx,gy-430);
    G.shots=6;
  }
  // weapon: last block each level is an Ember Bomb Block (splash smash)
  if(G.blocks.length)G.blocks[G.blocks.length-1].bomb=true;
  G.levelStartScore=G.score;
  G.shots=G.blocks.length; // gamer-check: shots must equal flickable blocks, or running out can never trigger the fail state
  document.getElementById('level').textContent=`LEVEL ${n}/10`;
  document.getElementById('shots').textContent='🧊 '+(G.shots-G.shotsUsed);
}
function updateScoreUI(){document.getElementById('score').textContent='⭐ '+G.score;}

/* ===== Jeff 2026-10-13: EVERY diamond explodes and chains to nearby diamonds =====
   Direct ice hit still scores the normal combo points. An exploding diamond
   blasts every diamond within CHAIN_R; those blow too after a short delay
   (cascade feel). Chain kills pay a flat +50 each (same as the old Ember Bomb
   splash), so scoring stays coherent. The Ember Bomb Block keeps its bigger
   blast radius (130) for its direct hit. */
const CHAIN_R=100,CHAIN_DELAY=0.09;
const boomQueue=[]; // {t,delay,r}
function diamondBlastFX(t,big){
  for(let i=0;i<(big?18:12);i++){const a=Math.random()*Math.PI*2,sp=100+Math.random()*280;
    spawnP(t.x,t.y,Math.cos(a)*sp,Math.sin(a)*sp,0.55,big?'#ff9a3a':'#aee2ff',3+Math.random()*4);}
  booms.push({x:t.x,y:t.y,r:6,max:big?130:CHAIN_R,life:0.28,maxLife:0.28});
}
const booms=[];
function killDiamond(t,cause,big){
  // cause: 'hit' (scored by caller) | 'chain' (+50 flat, keeps chaining)
  t.dead=true;noise(0.2,0.22,0,900);addTrauma(big?0.45:0.25);
  if(cause==='chain'){G.score+=50;updateScoreUI();spawnText(t.x,t.y-20,'CHAIN +50','#ffb347',16);}
  diamondBlastFX(t,big);
  boomQueue.push({t,delay:CHAIN_DELAY,r:big?130:CHAIN_R});
}
function processBooms(dt){
  for(const q of boomQueue){
    q.delay-=dt;
    if(q.delay<=0&&!q.done){q.done=true;
      for(const o of G.targets){
        if(o===q.t||o.dead)continue;
        if(Math.hypot(o.x-q.t.x,o.y-q.t.y)<=q.r+o.r*0.4)killDiamond(o,'chain',false);
      }
    }
  }
  for(let i=boomQueue.length-1;i>=0;i--)if(boomQueue[i].done)boomQueue.splice(i,1);
  for(let i=booms.length-1;i>=0;i--){const b=booms[i];b.life-=dt;b.r+=(b.max-b.r)*Math.min(1,dt*14);if(b.life<=0)booms.splice(i,1);}
}

/* physics */
function update(dt){
  G.time+=dt;
  processBooms(dt);
  G.comboT-=dt;if(G.comboT<=0)G.combo=0;
  for(const b of G.blocks){
    if(b.held)continue;
    // ice physics: very low friction
    b.x+=b.vx*dt;b.y+=b.vy*dt;
    const _fr=Math.pow(ICE_FRICTION,dt*60);b.vx*=_fr;b.vy*=_fr; // dt-scaled friction
    b.spin+=b.vr*dt;b.vr*=0.99;
    if(b.used&&!b.slid&&Math.hypot(b.vx,b.vy)>260){b.slid=true;sfx.slideSfx();} // was dead code: slide sound now fires
    // walls
    if(b.x<b.r){b.x=b.r;b.vx=Math.abs(b.vx)*0.8;sfx.hit();}
    if(b.x>W-b.r){b.x=W-b.r;b.vx=-Math.abs(b.vx)*0.8;sfx.hit();}
    if(b.y<b.r){b.y=b.r;b.vy=Math.abs(b.vy)*0.8;}
    if(b.y>H-b.r){b.y=H-b.r;b.vy=-Math.abs(b.vy)*0.8;sfx.hit();}
    // target collisions
    for(const t of G.targets){
      if(t.dead)continue;
      const d=Math.hypot(b.x-t.x,b.y-t.y);
      if(d<b.r+t.r){
        const speed=Math.hypot(b.vx,b.vy);
        if(speed>120){
          G.combo++;G.comboT=1.5;
          const pts=Math.round(100*(1+G.combo*0.3));
          G.score+=pts;updateScoreUI();
          sfx.shatter();addTrauma(0.3);hitStop=Math.max(hitStop,0.04);
          spawnText(t.x,t.y-20,'+'+pts);
          if(G.combo>=2){spawnText(t.x,t.y-50,'COMBO x'+G.combo,'#7fd4ff',16);sfx.combo(G.combo);}
          for(let i=0;i<14;i++){
            const a=Math.random()*Math.PI*2,sp=100+Math.random()*250;
            spawnP(t.x,t.y,Math.cos(a)*sp,Math.sin(a)*sp,0.6,'#aee2ff',3+Math.random()*4);
          }
          // Jeff 2026-10-13: the diamond EXPLODES and chains to nearby diamonds
          // (Ember Bomb Block = bigger blast). Chain kills pay +50 each in killDiamond.
          killDiamond(t,'hit',!!b.bomb);
          // bounce block (guard d===0: block dead-centre on target)
          const nx=d>0?(b.x-t.x)/d:1,ny=d>0?(b.y-t.y)/d:0;
          b.vx=nx*speed*0.5;b.vy=ny*speed*0.5;
        }
      }
    }
    // block-block collision
    for(const o of G.blocks){
      if(o===b||o.held)continue;
      const d=Math.hypot(b.x-o.x,b.y-o.y);
      if(d<b.r+o.r&&d>0){
        const nx=(b.x-o.x)/d,ny=(b.y-o.y)/d;
        const overlap=(b.r+o.r-d)/2;
        b.x+=nx*overlap;b.y+=ny*overlap;o.x-=nx*overlap;o.y-=ny*overlap;
        const rel=Math.hypot(b.vx-o.vx,b.vy-o.vy);
        if(rel>80){sfx.hit();addTrauma(0.1);}
        const tvx=b.vx,tvy=b.vy;
        b.vx=o.vx*0.9;b.vy=o.vy*0.9;o.vx=tvx*0.9;o.vy=tvy*0.9;
      }
    }
  }
  // win check
  if(G.state==='play'&&G.targets.every(t=>t.dead))levelComplete();
  // fail check
  const moving=G.blocks.some(b=>Math.hypot(b.vx,b.vy)>15);
  if(G.state==='play'&&!moving&&!G.dragBlock&&boomQueue.length===0&&(G.shots-G.shotsUsed)<=0&&!G.targets.every(t=>t.dead)){
    G.failT=(G.failT||0)+dt;
    if(G.failT>1.2)levelFailed();
  }else G.failT=0;
}
function levelComplete(){
  G.state='clear';sfx.win();
  const left=G.shots-G.shotsUsed;
  const stars=left>=2?3:left>=1?2:1;
  const bonus=stars*400;G.score+=bonus;updateScoreUI();
  for(let i=0;i<25;i++){const a=Math.random()*Math.PI*2;
    spawnP(W/2,H/2,Math.cos(a)*300,Math.sin(a)*300,1,'#aee2ff',5);}
  setTimeout(()=>{
    if(G.level>=10){
      showOverlay('🏆 ICE MASTER!',
        `<div class="stars">★★★</div><p style="font-size:26px;font-weight:900">Final Score: ${G.score}</p>`,
        '🔥 Fire Safety: You\'re a fire safety champion!',
        '↻ PLAY AGAIN',()=>{G.level=1;G.score=0;updateScoreUI();buildLevel(1);G.state='play';});
    }else{
      showOverlay(`⭐ LEVEL ${G.level} CLEAR!`,
        `<div class="stars">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</div><p>Score: ${G.score} (+${bonus} bonus)</p>`,
        '🔥 Fire Safety: Ice and water can help cool a burn — tell a grown-up!',
        '▶ NEXT LEVEL',()=>{G.level++;buildLevel(G.level);G.state='play';});
    }
  },1000);
}
function levelFailed(){
  G.state='fail';
  showOverlay('💥 OUT OF ICE BLOCKS',
    `<p>So close! ${G.targets.filter(t=>!t.dead).length} targets remain.</p><p>Score: ${G.score}</p>`,
    '🔥 Fire Safety: Never give up on safety — try again!',
    '↻ TRY AGAIN',()=>{G.score=G.levelStartScore;updateScoreUI();buildLevel(G.level);G.state='play';}); // retry restores level-start score: no farming
}

/* input */
canvas.addEventListener('pointerdown',e=>{
  if(G.state!=='play'||G.dragBlock)return;
  if((G.shots-G.shotsUsed)<=0)return;
  for(const b of G.blocks){
    if(b.used)continue;
    if(Math.hypot(b.x-e.clientX,b.y-e.clientY)<b.r+25){
      G.dragBlock=b;b.held=true;G.dragX=e.clientX;G.dragY=e.clientY;
      canvas.setPointerCapture(e.pointerId);break;
    }
  }
});
canvas.addEventListener('pointermove',e=>{
  if(!G.dragBlock)return;
  let dx=e.clientX-G.dragBlock.x,dy=e.clientY-G.dragBlock.y;
  const max=140,d=Math.hypot(dx,dy);
  if(d>max){dx=dx/d*max;dy=dy/d*max;}
  G.dragX=G.dragBlock.x+dx;G.dragY=G.dragBlock.y+dy;
});
function releaseDrag(e){
  const b=G.dragBlock;if(!b)return;
  b.held=false;G.dragBlock=null;
  const dx=b.x-G.dragX,dy=b.y-G.dragY;
  const pow=Math.hypot(dx,dy);
  if(pow<25)return;
  b.vx=dx/pow*Math.min(pow,140)*9;
  b.vy=dy/pow*Math.min(pow,140)*9;
  b.vr=(Math.random()-0.5)*10;
  b.used=true;b.slid=false;G.shotsUsed++;G.combo=0;
  document.getElementById('shots').textContent='🧊 '+(G.shots-G.shotsUsed);
  sfx.flick();addTrauma(0.2);
  for(let i=0;i<8;i++)spawnP(b.x,b.y,(Math.random()-0.5)*200,(Math.random()-0.5)*200,0.3,'#fff',3);
}
canvas.addEventListener('pointerup',releaseDrag);
canvas.addEventListener('pointercancel',releaseDrag);

/* overlay */
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
let pendingLevel=0;
function startGame(){audio();const lv=pendingLevel||1;pendingLevel=0;G.level=lv;G.score=0;updateScoreUI();buildLevel(lv);G.state='play';overlay.classList.add('hidden');}
function selLevel(n){sfx.click();pendingLevel=n;showMathGate();}
obtn.onclick=()=>{showMathGate();};
(function(){let h='';for(let i=1;i<=10;i++)h+=`<button class="lvlBtn" onclick="event.stopPropagation();selLevel(${i})">${i}</button>`;
document.getElementById('levelSel').innerHTML=h;})();

/* render */
function render(){
  // ice rink background
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#0a1628');bg.addColorStop(0.6,'#12304a');bg.addColorStop(1,'#0d2036');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  drawEmbers();
  // rink markings
  ctx.strokeStyle='rgba(174,226,255,0.15)';ctx.lineWidth=3;
  ctx.beginPath();ctx.arc(W/2,H*0.5,Math.min(W,H)*0.3,0,Math.PI*2);ctx.stroke();
  ctx.beginPath();ctx.moveTo(0,H*0.5);ctx.lineTo(W,H*0.5);ctx.stroke();
  // ice sparkles
  ctx.fillStyle='rgba(255,255,255,0.12)';
  for(let i=0;i<30;i++){
    const sx=(i*173+G.time*8)%W,sy=(i*97)%H;
    const tw=0.5+Math.sin(G.time*3+i)*0.5;
    ctx.globalAlpha=0.06+tw*0.1;
    ctx.fillRect(sx,sy,3,3);
  }
  ctx.globalAlpha=1;
  // snowflakes falling
  ctx.fillStyle='rgba(255,255,255,0.4)';
  for(let i=0;i<20;i++){
    const sx=(i*211+G.time*20)%W,sy=(i*137+G.time*40)%H;
    ctx.beginPath();ctx.arc(sx,sy,2,0,Math.PI*2);ctx.fill();
  }
  ctx.save();
  if(trauma>0)ctx.translate(shakeX,shakeY);
  // targets (crystals)
  for(const t of G.targets){
    if(t.dead)continue;
    t.wob+=0.1;
    const pulse=1+Math.sin(t.wob)*0.08;
    ctx.save();ctx.translate(t.x,t.y);ctx.scale(pulse,pulse);
    const g=ctx.createLinearGradient(-t.r,-t.r,t.r,t.r);
    g.addColorStop(0,'#d6f0ff');g.addColorStop(0.5,'#5ab8e8');g.addColorStop(1,'#2a78b8');
    ctx.fillStyle=g;
    ctx.beginPath();
    ctx.moveTo(0,-t.r);ctx.lineTo(t.r*0.7,-t.r*0.3);ctx.lineTo(t.r*0.7,t.r*0.3);
    ctx.lineTo(0,t.r);ctx.lineTo(-t.r*0.7,t.r*0.3);ctx.lineTo(-t.r*0.7,-t.r*0.3);
    ctx.closePath();ctx.fill();
    ctx.strokeStyle='rgba(255,255,255,0.7)';ctx.lineWidth=2;ctx.stroke();
    ctx.fillStyle='rgba(255,255,255,0.9)';
    ctx.fillRect(-6,-12,5,5);
    ctx.restore();
  }
  // explosion rings (chain blasts)
  for(const b of booms){
    ctx.save();ctx.globalAlpha=Math.max(0,b.life/b.maxLife)*0.85;
    ctx.strokeStyle='#ffd23f';ctx.lineWidth=4;
    ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.stroke();
    ctx.strokeStyle='rgba(174,226,255,0.8)';ctx.lineWidth=2;
    ctx.beginPath();ctx.arc(b.x,b.y,b.r*0.7,0,Math.PI*2);ctx.stroke();
    ctx.restore();
  }
  // drag line
  if(G.dragBlock){
    ctx.strokeStyle='rgba(255,255,255,0.7)';ctx.lineWidth=3;ctx.setLineDash([10,8]);
    ctx.beginPath();ctx.moveTo(G.dragBlock.x,G.dragBlock.y);ctx.lineTo(G.dragX,G.dragY);ctx.stroke();
    ctx.setLineDash([]);
    // power indicator
    const pow=Math.hypot(G.dragBlock.x-G.dragX,G.dragBlock.y-G.dragY);
    ctx.fillStyle=pow>100?'#ff4a00':pow>50?'#ffd23f':'#7fd4ff';
    ctx.font='900 16px system-ui';ctx.textAlign='center';
    ctx.fillText(Math.round(pow/140*100)+'%',G.dragBlock.x,G.dragBlock.y-40);
    ctx.textAlign='left';
    const _lvx=G.dragBlock.x-G.dragX,_lvy=G.dragBlock.y-G.dragY,_ll=Math.hypot(_lvx,_lvy)||1;
    ctx.fillStyle='rgba(255,210,63,0.9)';
    for(let _s=1;_s<=3;_s++){ctx.beginPath();ctx.arc(G.dragBlock.x+_lvx/_ll*_s*24,G.dragBlock.y+_lvy/_ll*_s*24,4.5,0,Math.PI*2);ctx.fill();}
  }
  // ice blocks
  for(const b of G.blocks){
    ctx.save();ctx.translate(b.x,b.y);ctx.rotate(b.spin);
    {const gr=b.r*(b.held?3.4:2.9);ctx.save();ctx.globalAlpha=0.55;ctx.drawImage(b.bomb?BLOCK_GLOW_ORANGE:BLOCK_GLOW_BLUE,-gr,-gr,gr*2,gr*2);ctx.restore();} // [w5b perf] pre-baked glow (was shadowBlur 13/22 per block per frame)
    const g=ctx.createLinearGradient(-b.r,-b.r,b.r,b.r);
    g.addColorStop(0,'rgba(220,240,255,0.95)');g.addColorStop(0.5,'rgba(140,200,240,0.9)');g.addColorStop(1,'rgba(90,140,190,0.9)');
    ctx.fillStyle=g;
    // rounded ice cube
    const r=b.r,cr=10;
    ctx.beginPath();
    ctx.moveTo(-r+cr,-r);ctx.lineTo(r-cr,-r);ctx.arcTo(r,-r,r,-r+cr,cr);
    ctx.lineTo(r,r-cr);ctx.arcTo(r,r,r-cr,r,cr);
    ctx.lineTo(-r+cr,r);ctx.arcTo(-r,r,-r,r-cr,cr);
    ctx.lineTo(-r,-r+cr);ctx.arcTo(-r,-r,-r+cr,-r,cr);
    ctx.closePath();ctx.fill();
    ctx.strokeStyle='rgba(255,255,255,0.8)';ctx.lineWidth=2;ctx.stroke();
    // inner shine
    ctx.fillStyle='rgba(255,255,255,0.35)';
    ctx.beginPath();ctx.ellipse(-r*0.3,-r*0.35,r*0.35,r*0.2,-0.5,0,Math.PI*2);ctx.fill();
    if(b.bomb){ctx.fillStyle='rgba(255,122,42,0.85)';ctx.beginPath();ctx.arc(0,0,10+Math.sin(G.time*6)*2,0,Math.PI*2);ctx.fill();
      ctx.fillStyle='#ffd23f';ctx.beginPath();ctx.arc(0,0,5,0,Math.PI*2);ctx.fill();}
    // Cinder face on ice
    ctx.fillStyle='#1a2a3a';
    ctx.beginPath();ctx.arc(-8,-4,4,0,Math.PI*2);ctx.arc(8,-4,4,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#1a2a3a';ctx.lineWidth=2.5;ctx.lineCap='round';
    ctx.beginPath();ctx.arc(0,6,8,0.4,Math.PI-0.4);ctx.stroke();
    ctx.restore();
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size*(p.life/p.max),0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  // floaters
  ctx.textAlign='center';
  for(const f of floaters){
    if(!f.a)continue;
    ctx.globalAlpha=Math.min(1,f.life);
    ctx.font=`900 ${f.size}px system-ui`;ctx.fillStyle='#000';
    ctx.fillText(f.txt,f.x+2,f.y+2);ctx.fillStyle=f.color;ctx.fillText(f.txt,f.x,f.y);
  }
  ctx.globalAlpha=1;ctx.textAlign='left';
  if(G.state==='play'&&G.shotsUsed===0){ // [gauntlet clarity] goal line on the play screen until the first shot (game-40 pattern)
    const _pw=Math.min(540,W-16); // [gauntlet fix] pill + text sized to fit phone widths
    ctx.fillStyle='rgba(0,0,0,0.45)';ctx.beginPath();ctx.roundRect(W/2-_pw/2,14,_pw,34,10);ctx.fill();
    ctx.fillStyle='#fff';ctx.font='900 '+(W<520?13:16)+'px system-ui';ctx.textAlign='center';
    ctx.fillText(W<520?'DRAG BACK, LET GO — IT EXPLODES!':'DRAG A BLOCK BACK, LET GO — IT EXPLODES AND CRACKS THE ICE!',W/2,78);
    ctx.textAlign='left';
  }
  ctx.restore();
}


/* gamer-check: pause + mute controls */
const _pz=document.getElementById('pauseOv');
function fbPause(){if(G.state==='play'){G.state='pause';_pz.classList.remove('hidden');}}
function fbResume(){if(G.state==='pause'){G.state='play';_pz.classList.add('hidden');}}
document.getElementById('pauseBtn').onclick=e=>{e.stopPropagation();fbPause();};
document.getElementById('resumeBtn').onclick=()=>{fbResume();};
document.getElementById('muteBtn').onclick=e=>{e.stopPropagation();MUTED=!MUTED;e.currentTarget.textContent=MUTED?'🔇':'🔊';};
document.getElementById('prestartBtn').onclick=()=>{_pz.classList.add('hidden');G.score=G.levelStartScore||0;updateScoreUI();buildLevel(G.level);G.state='play';};
addEventListener('keydown',e=>{if(e.key==='p'||e.key==='P'||e.key==='Escape'){if(G.state==='play')fbPause();else if(G.state==='pause')fbResume();}});

/* loop */
let lastT=0;
function loop(t){
  const rawDt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  let dt=rawDt;
  if(hitStop>0){hitStop-=rawDt;dt=rawDt*0.1;}
  trauma=Math.max(0,trauma-dt*1.8);
  const sh=trauma*trauma*18;
  shakeX=(Math.random()-0.5)*sh*2;shakeY=(Math.random()-0.5)*sh*2;
  if(G.state==='play')update(dt);else G.time+=dt;
  updateEmbers(dt);
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=500*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  for(const f of floaters){if(!f.a)continue;f.y-=60*dt;f.life-=dt;if(f.life<=0)f.a=false;}
  render();
  requestAnimationFrame(loop);
}
/* ===== MUSIC (Jeff 2026-10-13): 'Crystal Cascade' — Ice Rink's own track.
   Synthesized Web Audio only. 122 BPM, sparkling sine-bell arpeggios over a soft
   pulsing bass — icy and playful, with an 8th-note shaker drive for intensity.
   Starts on first interaction; controlled by the existing 🔊 mute. ===== */
const _mf=m=>440*Math.pow(2,(m-69)/12);
const MUS={on:false,step:0,nextT:0,BPM:122,
 BASS:[45,0,0,0,0,0,45,0, 41,0,0,0,0,0,41,0, 48,0,0,0,0,0,48,0, 43,0,0,0,0,0,43,0],
 LEAD:[81,84,88,84,81,84,88,93, 89,93,89,84,89,93,96,93, 84,88,91,88,84,88,91,88, 91,95,91,88,86,84,81,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(MUTED||G.state!=='play'){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.3,'triangle',0.07,d);
  const l=this.LEAD[s];if(l){tone(_mf(l),_mf(l),0.24,'sine',0.055,d);tone(_mf(l)*2,_mf(l)*2,0.12,'sine',0.016,d);} // bell + harmonic sparkle
  if(s%8===0)tone(110,45,0.13,'sine',0.12,d); // soft kick, once a bar
  if(s%8===4)tone(130,50,0.13,'sine',0.1,d);
  noise(0.03,0.02,d,7000); // shaker hat every 8th
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());
updateScoreUI();
requestAnimationFrame(loop);

