scripts:
'use strict';
/* ============================================================
   LORD INFERNO'S BALLISTA SIEGE v2 — AAA Rebuild
   - Vertical shooter: drag to steer, auto-fire
   - 15 levels, enemy waves, power-ups, boss fights
   - Levels 11–15 + the Horned Moon finale added 2026-10-15 (Jeff's order)
   - Particle explosions, trauma shake, layered audio
   ============================================================ */
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();

/* audio */
let AC=null,MUTED=false;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
function noise(dur,vol,delay=0,lp=2000){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const len=ac.sampleRate*dur,buf=ac.createBuffer(1,len,ac.sampleRate),d=buf.getChannelData(0);
  for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);
  const s=ac.createBufferSource();s.buffer=buf;const f=ac.createBiquadFilter();f.type='lowpass';f.frequency.value=lp;
  const g=ac.createGain();g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  s.connect(f);f.connect(g);g.connect(ac.destination);s.start(t);}

/* living ember backdrop (overhaul) */
const embers=[];
for(let i=0;i<24;i++)embers.push({x:Math.random()*Math.max(W,300),y:Math.random()*Math.max(H,300),s:1+Math.random()*2.5,v:12+Math.random()*26,o:0.22+Math.random()*0.5});
/* [w5c perf] Pre-baked glow sprites — the W5b-proven pattern copied from game-04:
   the ember loop's 24 per-frame shadowBlur=8 fills collapsed FPS under software
   rendering (10.0 FPS); blit a one-time radial-glow sprite instead. Colours,
   falloff and alpha unchanged; no gameplay/balance changes. */
function makeGlowSprite(hex){const c=document.createElement('canvas');c.width=c.height=96;const x=c.getContext('2d');
  const r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);
  const gr=x.createRadialGradient(48,48,0,48,48,48);
  gr.addColorStop(0,`rgba(${r},${g},${b},0.9)`);gr.addColorStop(0.35,`rgba(${r},${g},${b},0.38)`);gr.addColorStop(1,`rgba(${r},${g},${b},0)`);
  x.fillStyle=gr;x.fillRect(0,0,96,96);return c;}
const EMBER_SPRITE=makeGlowSprite('#ffa53a');
const BULLET_GLOW=makeGlowSprite('#ffd23f'); // [w5c perf] bullet glow sprite
function drawEmbers(){ctx.save();ctx.globalCompositeOperation='lighter';
  for(const e of embers){ctx.globalAlpha=e.o*(0.6+0.4*Math.sin(G.time*3+e.x*0.05));
    const r=e.s*7;ctx.drawImage(EMBER_SPRITE,e.x-r,e.y-r,r*2,r*2);} // [w5c perf] pre-baked glow (was shadowBlur=8 per ember per frame)
  ctx.restore();}
function updateEmbers(dt){for(const e of embers){e.y-=e.v*dt;e.x+=Math.sin((G.time+e.y)*0.02)*0.3;
  if(e.y<-12){e.y=H+12;e.x=Math.random()*W;}}}
const sfx={
  shoot(){tone(800,400,0.08,'square',0.08);},
  explode(){noise(0.3,0.35,0,800);tone(150,40,0.25,'sawtooth',0.2);},
  hit(){noise(0.2,0.3,0,500);tone(200,60,0.2,'square',0.2);},
  power(){tone(500,1500,0.2,'sine',0.15);tone(750,2000,0.15,'sine',0.1,0.08);},
  win(){[523,659,784,1047].forEach((f,i)=>tone(f,f,0.25,'triangle',0.18,i*0.1));},
  click(){tone(600,600,0.06,'square',0.1);}
};

/* pools */
const particles=[],floaters=[];
for(let i=0;i<300;i++)particles.push({a:false});
for(let i=0;i<25;i++)floaters.push({a:false});
function spawnP(x,y,vx,vy,life,color,size){const p=particles.find(p=>!p.a);if(!p)return;
  p.a=true;p.x=x;p.y=y;p.vx=vx;p.vy=vy;p.life=life;p.max=life;p.color=color;p.size=size;}
function spawnText(x,y,txt,color='#ffd23f'){const f=floaters.find(f=>!f.a);if(!f)return;
  f.a=true;f.x=x;f.y=y;f.txt=txt;f.color=color;f.life=1.1;}
let trauma=0,hitStop=0,shakeX=0,shakeY=0;
function addTrauma(t){trauma=Math.min(1,trauma+t);}

/* state */
const G={state:'title',level:1,score:0,wave:1,waveKills:0,waveTarget:8,
  px:0,py:0,hp:100,maxHp:100,fireT:0,
  bullets:[],enemies:[],pickups:[],time:0,invuln:0,
  power:1,powerT:0,boss:null};
function reset(level){
  G.level=level;G.wave=1;G.waveKills=0;G.waveTarget=6+level*2;
  G.px=W/2;G.py=H*0.82;G.hp=100;G.maxHp=100;G.fireT=0;
  G.bullets=[];G.enemies=[];G.pickups=[];G.power=1;G.powerT=0;G.boss=null;G.invuln=0;
  document.getElementById('level').textContent=`LEVEL ${level}/15`;
  document.getElementById('wave').textContent='🌊 Wave 1';
  updateHP();
}
function updateScoreUI(){document.getElementById('score').textContent='⭐ '+G.score;}
function updateHP(){document.getElementById('hpfill').style.width=(G.hp/G.maxHp*100)+'%';}

/* spawning */
function spawnEnemy(){
  const lvl=G.level;
  const r=Math.random();
  let type='rock';
  if(lvl>=11){
    /* Levels 11+: the fleets get new tricks — shielded carriers, weavers, splitters */
    if(G.wave>=2&&r<0.16)type='carrier';
    else if(r<0.38)type='splitter';
    else if(r<0.62)type='weaver';
    else if(G.wave>=3&&r<0.76)type='dart';
    else if(G.wave>=2&&r<0.88)type='tank';
  }else{
    if(G.wave>=3&&r<0.25)type='dart';
    else if(G.wave>=2&&r<0.45)type='tank';
  }
  const x=40+Math.random()*(W-80);
  const base={x,y:-40,vx:(Math.random()-0.5)*60,dead:false,t:0};
  if(type==='rock')Object.assign(base,{type,hp:1+Math.floor(lvl/2),vy:120+lvl*20+Math.random()*60,r:24,score:50});
  else if(type==='dart')Object.assign(base,{type,hp:2,vy:200+lvl*25,r:18,score:100});
  else if(type==='weaver')Object.assign(base,{type,hp:3+Math.floor(lvl/3),vy:150+lvl*12,r:22,score:150,bx:x,amp:55+Math.random()*55,ph:Math.random()*6.28});
  else if(type==='splitter')Object.assign(base,{type,hp:5,vy:110+lvl*10,r:26,score:150});
  else if(type==='carrier')Object.assign(base,{type,hp:12+lvl,vy:52+lvl*5,r:42,score:400,shieldHp:6,spawnT:2.5});
  else Object.assign(base,{type:'tank',hp:4+lvl,vy:70+lvl*10,r:34,score:200});
  G.enemies.push(base);
}
/* ===== Jeff 2026-10-13: sky-ships + pilots, giant boss ships, home-world setting =====
   Every level flies over a DIFFERENT part of the Fire Babys home world, with a
