function theme(){return LEVEL_THEMES[(G.level-1)%LEVEL_THEMES.length];}
function bossTheme(){return BOSS_THEMES[(G.level-1)%BOSS_THEMES.length];}
/* little bad-guy pilot: round head, angry brows, frown, themed hat */
function drawPilot(x,y,r,skin,hat,accent){
  ctx.fillStyle=skin;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();
  ctx.strokeStyle='#1a0d08';ctx.lineWidth=Math.max(1.5,r*0.16);ctx.lineCap='round';
  ctx.beginPath();ctx.moveTo(x-r*0.75,y-r*0.45);ctx.lineTo(x-r*0.15,y-r*0.1);ctx.stroke();
  ctx.beginPath();ctx.moveTo(x+r*0.75,y-r*0.45);ctx.lineTo(x+r*0.15,y-r*0.1);ctx.stroke();
  ctx.fillStyle='#14100c';
  ctx.beginPath();ctx.arc(x-r*0.32,y+r*0.08,r*0.17,0,Math.PI*2);ctx.arc(x+r*0.32,y+r*0.08,r*0.17,0,Math.PI*2);ctx.fill();
  ctx.beginPath();ctx.arc(x,y+r*0.72,r*0.4,Math.PI*1.15,Math.PI*1.85);ctx.stroke(); // frown
  ctx.fillStyle=accent||'#ffd23f';
  if(hat==='crown'){ctx.beginPath();ctx.moveTo(x-r*0.8,y-r*0.75);ctx.lineTo(x-r*0.8,y-r*1.25);ctx.lineTo(x-r*0.3,y-r*0.9);ctx.lineTo(x,y-r*1.3);ctx.lineTo(x+r*0.3,y-r*0.9);ctx.lineTo(x+r*0.8,y-r*1.25);ctx.lineTo(x+r*0.8,y-r*0.75);ctx.closePath();ctx.fill();}
  else if(hat==='horns'){ctx.beginPath();ctx.moveTo(x-r*0.8,y-r*0.5);ctx.quadraticCurveTo(x-r*1.3,y-r*1.1,x-r*0.7,y-r*1.25);ctx.quadraticCurveTo(x-r*0.75,y-r*0.8,x-r*0.45,y-r*0.6);ctx.closePath();ctx.fill();
    ctx.beginPath();ctx.moveTo(x+r*0.8,y-r*0.5);ctx.quadraticCurveTo(x+r*1.3,y-r*1.1,x+r*0.7,y-r*1.25);ctx.quadraticCurveTo(x+r*0.75,y-r*0.8,x+r*0.45,y-r*0.6);ctx.closePath();ctx.fill();}
  else if(hat==='hood'){ctx.strokeStyle=accent||'#888';ctx.lineWidth=r*0.5;ctx.beginPath();ctx.arc(x,y-r*0.1,r*0.95,Math.PI*1.05,Math.PI*1.95);ctx.stroke();}
  else if(hat==='turban'){ctx.beginPath();ctx.ellipse(x,y-r*0.8,r*0.95,r*0.5,0,0,Math.PI*2);ctx.fill();}
  else{ctx.fillRect(x-r*0.85,y-r*1.05,r*1.7,r*0.4);ctx.fillRect(x-r*0.6,y-r*1.4,r*1.2,r*0.4);} // cap
}
function spawnBoss(){
  const lvl=G.level,bt=bossTheme();
  if(lvl===15){spawnMoonFortress(bt);return;}
  G.boss={x:W/2,y:-90,vy:60,hp:20+lvl*12,maxHp:20+lvl*12,r:55,t:0,fireT:1.5,volley:0,dead:false,type:'boss',score:1000};
  G.enemies.push(G.boss);
  spawnText(W/2,H*0.3,'⚠️ BOSS: '+bt.name+'!','#ff4a00');
  spawnText(W/2,H*0.38,theme().place,'#ffd23f');
  sfx.hit();
}
/* Boss attack pattern is DIFFERENT every level (Jeff 2026-10-13):
   L1 fan · L2 wide fan · L3 aimed shots · L4 spiral · L5 fan+aimed alternating ·
   L6 aimed triple-bursts · L7 fast spiral · L8 ring burst + fan · L9 aimed+spiral ·
   L10 Lord Inferno rotates fan / aimed / spiral / ring by volley. */
function bossBolt(bo,a,spd){
  G.enemies.push({x:bo.x,y:bo.y+40,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd+60,
    hp:1,r:12,dead:false,t:0,type:'bolt',score:25});
}
function bossFire(bo){
  const lvl=G.level;bo.volley++;
  bo.fireT=Math.max(0.6,1.6-lvl*0.15);
  const fan=(n,spread,spd)=>{for(let i=0;i<n;i++){const a=Math.PI/2+(i-(n-1)/2)*spread;bossBolt(bo,a,spd);}};
  const aimed=(n,spd)=>{const base=Math.atan2(G.py-bo.y,G.px-bo.x);for(let i=0;i<n;i++)bossBolt(bo,base+(i-(n-1)/2)*0.14,spd);};
  const spiral=(n,spd)=>{for(let i=0;i<n;i++){const a=Math.PI/2+Math.sin(bo.t*2.6)*0.9+(i-(n-1)/2)*0.5;bossBolt(bo,a,spd);}};
  const spiralR=(n,spd)=>{for(let i=0;i<n;i++){const a=Math.PI/2-Math.sin(bo.t*2.6)*0.9+(i-(n-1)/2)*0.5;bossBolt(bo,a,spd);}};
  const ring=(n,spd)=>{for(let i=0;i<n;i++){const a=i/n*Math.PI*2+bo.t;bossBolt(bo,a,spd);}};
  switch(lvl){
    case 1: fan(3+lvl,0.35,180);break;
    case 2: fan(6,0.42,180);break;
    case 3: aimed(2,240);break;
    case 4: spiral(3,190);bo.fireT=0.8;break;
    case 5: bo.volley%2?fan(6,0.35,185):aimed(2,235);break;
    case 6: aimed(3,250);bo.fireT=1.0;break;
    case 7: spiral(4,200);bo.fireT=0.62;break;
    case 8: bo.volley%3===0?ring(8,130):fan(6,0.38,185);break;
    case 9: bo.volley%2?aimed(3,250):spiral(4,200);bo.fireT=0.85;break;
    /* Levels 11–14 (2026-10-15): denser, meaner twists on the classic patterns */
    case 11: fan(5,0.32,195);fan(5,0.62,165);bo.fireT=1.15;break;              // double fan, wide + narrow
    case 12: aimed(4,255);bo.fireT=0.95;break;                                 // quad aimed stream
    case 13: bo.volley%2?spiral(5,210):spiralR(5,210);bo.fireT=0.7;break;      // twin spirals, alternating spin
    case 14: ring(12,140);aimed(2,250);bo.fireT=1.05;break;                    // full ring + aimed punish
    default:{const p=bo.volley%4;if(p===0)fan(8,0.36,195);else if(p===1)aimed(3,255);else if(p===2)spiral(4,205);else ring(10,135);bo.fireT=0.95;}
  }
  sfx.shoot();
}
function spawnPickup(x,y){
  const types=['hp','rapid','spread','shield','nova','twin'];
  G.pickups.push({x,y,vy:100,type:types[Math.floor(Math.random()*types.length)],t:0});
}

/* ============================================================
   LEVEL 15 FINALE — THE HORNED MOON (2026-10-15, Jeff's order)
   Our own original design: Lord Inferno (the game's villain) has
   parked a gigantic horned moon-fortress over the home world —
   a spherical battle-station with demonic horns, glowing ember
   cracks, turret ring, and a huge central ember-eye cannon.
   3 phases: (1) turret ring + escorts, (2) sweeping eye-beam,
   (3) venting core — hit the core while it's exposed!
   ============================================================ */
const MOON_TURRETS=[[-84,20],[-58,74],[-20,94],[20,94],[58,74],[84,20]];
function moonBolt(x,y,a,spd){
  G.enemies.push({x,y,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd+40,
    hp:1,r:12,dead:false,t:0,type:'bolt',score:25});
}
function spawnMoonFortress(bt){
  G.boss={x:W/2,y:-150,vy:78,hp:260,maxHp:260,r:100,t:0,fireT:2,volley:0,dead:false,
    type:'boss',kind:'moon',score:5000,phase:1,
    turretT:1.8,turretIdx:0,turretFlash:-1,turretFlashT:0,
    beamState:'idle',beamT:2.6,beamA:0,beamDir:1,
    coreOpen:false,coreT:0,escortT:3.5,sealNoteT:0};
  G.enemies.push(G.boss);
  spawnText(W/2,H*0.28,'🌕 THE HORNED MOON RISES!','#ff4a00');
  spawnText(W/2,H*0.36,"😈 LORD INFERNO: 'My fortress is UNBEATABLE!'",'#ffd23f');
  sfx.hit();
}
/* damage a bullet does to the fortress: phases 1–2 the hull takes it;
   phase 3 only the EXPOSED CORE takes damage (double); sealed = clang! */
function moonHit(e,x,y){
  if(e.phase<3)return 1;
  if(!e.coreOpen)return 0;
  return Math.hypot(x-e.x,y-(e.y+52))<42?2:0;
}
function moonUpdate(bo,dt){
  bo.t+=dt;
  if(bo.sealNoteT>0)bo.sealNoteT-=dt;
  if(bo.turretFlashT>0)bo.turretFlashT-=dt;
  if(bo.y<Math.min(178,H*0.24)){bo.y+=bo.vy*dt;return;} // still descending into position
  bo.x=W/2+Math.sin(bo.t*0.45)*W*0.1;
  /* phase by hull fraction */
  const frac=bo.hp/bo.maxHp;
  const np=frac>0.66?1:frac>0.33?2:3;
  if(np!==bo.phase){
    bo.phase=np;bo.beamState='idle';bo.beamT=2.0;
    if(np===2){spawnText(W/2,H*0.34,"😈 'FEEL MY EMBER EYE!'",'#ff9a3a');sfx.hit();}
    if(np===3){bo.coreOpen=true;bo.coreT=4;
      spawnText(W/2,H*0.34,'⚠ THE CORE IS EXPOSED — HIT THE GLOWING CORE!','#7fd4ff');sfx.power();}
  }
  /* turret ring: rotating hardpoints fire aimed bolts (faster each phase) */
  bo.turretT-=dt;
  if(bo.turretT<=0){
    bo.turretT=bo.phase===3?0.95:bo.phase===2?1.25:1.5;
    const n=bo.phase===1?2:bo.phase===2?2:3;
    for(let k=0;k<n;k++){
      const idx=(bo.turretIdx+k*2)%6,[ox,oy]=MOON_TURRETS[idx];
      const tx=bo.x+ox*bo.r/100,ty=bo.y+oy*bo.r/100;
      const a=Math.atan2(G.py-ty,G.px-tx);
      moonBolt(tx,ty,a,215);
      if(k===0){bo.turretFlash=idx;bo.turretFlashT=0.18;}
    }
    bo.turretIdx=(bo.turretIdx+1)%6;
    sfx.shoot();
  }
  /* phase 1: escort ships dribble out of the hangar bays */
  if(bo.phase===1){
    bo.escortT-=dt;
    const live=G.enemies.filter(e=>!e.dead&&e!==bo&&e.type!=='bolt').length;
    if(bo.escortT<=0&&live<3){
      bo.escortT=4.2;
      const s=Math.random()<0.5?-1:1;
      G.enemies.push({type:'rock',x:bo.x+s*bo.r*0.8,y:bo.y+bo.r*0.5,vx:s*40,vy:150,
        hp:3,r:24,dead:false,t:0,score:50});
    }
  }
  /* phases 2–3: the ember-eye cannon — charge (telegraphed), then a sweeping beam */
  if(bo.phase>=2){
    bo.beamT-=dt;
    if(bo.beamState==='idle'&&bo.beamT<=0){
      bo.beamState='charge';bo.beamT=bo.phase===3?1.2:1.6;
      spawnText(bo.x,bo.y+bo.r+30,'⚠ EYE CANNON CHARGING!','#ff4a00');
      tone(180,880,bo.beamT,'sawtooth',0.07);
    }else if(bo.beamState==='charge'&&bo.beamT<=0){
      bo.beamState='fire';bo.beamT=bo.phase===3?2.0:2.4;bo.beamDir*=-1;
      noise(0.5,0.25,0,900);tone(90,45,0.5,'sawtooth',0.15);
    }else if(bo.beamState==='fire'){
      const dur=bo.phase===3?2.0:2.4,pr=1-Math.max(0,bo.beamT)/dur;
      bo.beamA=bo.beamDir*(-0.95+1.9*pr);
      const ex=bo.x,ey=bo.y-6,dx=G.px-ex,dy=G.py-ey;
      if(dy>10){
        const dist=Math.hypot(dx,dy),ang=Math.atan2(dx,dy);
        if(Math.abs(ang-bo.beamA)<Math.atan2(24,dist)+0.015)damagePlayer(16);
      }
      if(Math.random()<0.6)spawnP(ex+Math.sin(bo.beamA)*140,ey+Math.cos(bo.beamA)*140,
        (Math.random()-0.5)*60,120,0.35,'#ff8a3a',3);
      if(bo.beamT<=0){bo.beamState='idle';bo.beamT=bo.phase===3?1.9:2.6;}
    }
  }
  /* phase 3: the core vents on a cycle — open 4s (hit it!), sealed 2.5s */
  if(bo.phase===3){
    bo.coreT-=dt;
    if(bo.coreOpen&&Math.random()<0.35)
      spawnP(bo.x+(Math.random()-0.5)*30,bo.y+52,(Math.random()-0.5)*40,-60-Math.random()*60,0.5,'#ffb347',3);
    if(bo.coreT<=0){
      bo.coreOpen=!bo.coreOpen;bo.coreT=bo.coreOpen?4:2.5;
      spawnText(bo.x,bo.y+bo.r+30,bo.coreOpen?'⚠ CORE EXPOSED!':'😈 CORE SEALED!','#7fd4ff');
      if(bo.coreOpen)sfx.power();
    }
  }
}

/* THE HORNED MOON — fortress renderer (original code-art, game's own style).
   Drawn in local space: caller has already translated to (e.x, e.y). */
function drawMoonFortress(e,bt){
  const R=e.r;
  const bob=Math.sin(e.t*3+e.x*0.05)*2;
  ctx.translate(0,bob);
  /* the sweeping ember-eye beam (under the hull rim glow, over the sky) */
  if(e.beamState==='charge'||e.beamState==='fire'){
    const ex=0,ey=-6,a=e.beamState==='fire'?e.beamA:e.beamDir*-0.95;
    const len=H;
    const dx=Math.sin(a),dy=Math.cos(a);
    ctx.save();
    if(e.beamState==='charge'){
      const pl=0.5+0.5*Math.sin(G.time*22);
      ctx.strokeStyle=`rgba(255,74,0,${0.25+0.3*pl})`;ctx.lineWidth=3;ctx.setLineDash([14,12]);
      ctx.beginPath();ctx.moveTo(ex,ey);ctx.lineTo(ex+dx*len,ey+dy*len);ctx.stroke();
      ctx.setLineDash([]);
    }else{
      /* solid layered fills (no full-screen gradient — software renderers
         choke on huge gradient polygons; this is the w5c perf lesson) */
      const wdt=30+Math.sin(G.time*40)*5;
      ctx.globalCompositeOperation='lighter';
      const beamPoly=w=>{ctx.beginPath();
        ctx.moveTo(ex-dy*6,ey+dx*6);
        ctx.lineTo(ex+dx*len-dy*w,ey+dy*len+dx*w);
        ctx.lineTo(ex+dx*len+dy*w,ey+dy*len-dx*w);
        ctx.lineTo(ex+dy*6,ey-dx*6);
        ctx.closePath();ctx.fill();};
      ctx.fillStyle='rgba(255,90,20,0.30)';beamPoly(wdt*1.9);
      ctx.fillStyle='rgba(255,170,70,0.65)';beamPoly(wdt);
      ctx.fillStyle='rgba(255,240,200,0.85)';beamPoly(7);
    }
    ctx.restore();
  }
  /* hull: a great dark sphere banded in iron, rim-lit in ember */
  const hg=ctx.createRadialGradient(-R*0.35,-R*0.4,R*0.15,0,0,R*1.15);
  hg.addColorStop(0,'#5a2430');hg.addColorStop(0.55,'#33101c');hg.addColorStop(1,'#12040a');
  ctx.fillStyle=hg;
  ctx.beginPath();ctx.arc(0,0,R,0,Math.PI*2);ctx.fill();
  ctx.strokeStyle=bt.accent;ctx.lineWidth=3.5;ctx.stroke();
  ctx.strokeStyle='rgba(255,150,80,0.28)';ctx.lineWidth=2;
  ctx.beginPath();ctx.ellipse(0,0,R*0.99,R*0.36,0,0,Math.PI*2);ctx.stroke();
  ctx.beginPath();ctx.ellipse(0,0,R*0.36,R*0.99,0,0,Math.PI*2);ctx.stroke();
  /* demonic horns — grand curved horns sweeping off the upper rim */
  ctx.fillStyle='#20060e';
  for(const s of [-1,1]){
    ctx.beginPath();
    ctx.moveTo(s*R*0.62,-R*0.66);
    ctx.quadraticCurveTo(s*R*1.28,-R*1.05,s*R*1.34,-R*1.62);
    ctx.quadraticCurveTo(s*R*0.98,-R*1.28,s*R*0.86,-R*0.88);
    ctx.quadraticCurveTo(s*R*0.72,-R*0.72,s*R*0.62,-R*0.66);
    ctx.closePath();ctx.fill();
    ctx.strokeStyle='rgba(255,120,50,0.5)';ctx.lineWidth=2;ctx.stroke();
    ctx.fillStyle='#ff7a2a'; // ember-glowing horn tip
    ctx.beginPath();ctx.arc(s*R*1.33,-R*1.6,4+Math.sin(G.time*7)*1.2,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#20060e';
  }
  /* glowing ember cracks crawling over the hull */
  ctx.save();ctx.globalCompositeOperation='lighter';
  const cracks=[[-0.75,0.3,-0.5,0.42,-0.58,0.62],[-0.8,-0.25,-0.55,-0.12,-0.62,0.05],[0.78,0.42,0.55,0.5,0.6,0.68],[0.72,-0.5,0.5,-0.38,0.56,-0.2]];
  ctx.strokeStyle='rgba(255,106,26,0.85)';ctx.lineWidth=2;
  for(const c of cracks){
    ctx.beginPath();ctx.moveTo(c[0]*R,c[1]*R);ctx.lineTo(c[2]*R,c[3]*R);ctx.lineTo(c[4]*R,c[5]*R);ctx.stroke();
    const gr=16;ctx.globalAlpha=0.5+0.3*Math.sin(G.time*5+c[0]*9);
    ctx.drawImage(EMBER_SPRITE,c[2]*R-gr,c[3]*R-gr,gr*2,gr*2);
  }
  ctx.restore();
  /* turret ring: six hardpoint domes around the lower rim */
  for(let i=0;i<6;i++){
    const [ox,oy]=MOON_TURRETS[i],tx=ox*R/100,ty=oy*R/100;
    ctx.fillStyle='#3a1420';
    ctx.beginPath();ctx.arc(tx,ty,13,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle=bt.accent;ctx.lineWidth=2;ctx.stroke();
    ctx.fillStyle=(e.turretFlash===i&&e.turretFlashT>0)?'#fff2b0':'#ff4a00';
    ctx.fillRect(tx-2.5,ty+6,5,10);
    ctx.beginPath();ctx.arc(tx,ty,4.5,0,Math.PI*2);ctx.fill();
  }
  /* command dome: LORD INFERNO himself at the helm, glaring down */
  ctx.fillStyle='rgba(190,230,255,0.32)';
  ctx.beginPath();ctx.arc(0,-R*0.74,R*0.3,Math.PI,Math.PI*2);ctx.fill();
  ctx.strokeStyle=bt.accent;ctx.lineWidth=2.5;
  ctx.beginPath();ctx.arc(0,-R*0.74,R*0.3,Math.PI,Math.PI*2);ctx.stroke();
  drawPilot(0,-R*0.76,R*0.21,bt.skin,bt.hat,bt.accent);
  /* THE EMBER EYE — central cannon; it glows as it charges */
  const charge=e.beamState==='charge'?(1-Math.max(0,e.beamT)/(e.phase===3?1.2:1.6)):0;
  const eyeGlow=e.beamState==='fire'?1:charge;
  ctx.save();ctx.globalCompositeOperation='lighter';
  const egr=34+eyeGlow*30+Math.sin(G.time*6)*3;
  ctx.globalAlpha=0.35+eyeGlow*0.55;
  ctx.drawImage(EMBER_SPRITE,-egr,-6-egr,egr*2,egr*2);
  ctx.restore();
  const eg2=ctx.createRadialGradient(0,-6,2,0,-6,27);
  eg2.addColorStop(0,'#fff3c8');eg2.addColorStop(0.45,'#ffb347');eg2.addColorStop(0.8,'#ff5a1a');eg2.addColorStop(1,'#7a1408');
  ctx.fillStyle=eg2;
  ctx.beginPath();ctx.arc(0,-6,26,0,Math.PI*2);ctx.fill();
  ctx.strokeStyle='#ffd23f';ctx.lineWidth=3;ctx.stroke();
  ctx.fillStyle='#1c0505';
  ctx.beginPath();ctx.arc(0,-6,10+eyeGlow*4,0,Math.PI*2);ctx.fill();
  /* the core (phase 3): armored vent low on the hull — hit it while it's open! */
  if(e.phase===3){
    const cx=0,cy=52;
    if(e.coreOpen){
      ctx.save();ctx.globalCompositeOperation='lighter';
      const cgr=30+Math.sin(G.time*10)*5;
      ctx.drawImage(EMBER_SPRITE,cx-cgr,cy-cgr,cgr*2,cgr*2);
      ctx.restore();
      const cg2=ctx.createRadialGradient(cx,cy,2,cx,cy,20);
      cg2.addColorStop(0,'#ffffff');cg2.addColorStop(0.5,'#ffd23f');cg2.addColorStop(1,'#ff6a00');
      ctx.fillStyle=cg2;
      ctx.beginPath();ctx.arc(cx,cy,19,0,Math.PI*2);ctx.fill();
      ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.stroke();
    }else{
      ctx.fillStyle='#40202c';
      ctx.beginPath();ctx.arc(cx,cy,19,0,Math.PI*2);ctx.fill();
      ctx.strokeStyle=bt.accent;ctx.lineWidth=2.5;ctx.stroke();
      ctx.beginPath();ctx.moveTo(cx-13,cy-13);ctx.lineTo(cx+13,cy+13);
      ctx.moveTo(cx+13,cy-13);ctx.lineTo(cx-13,cy+13);ctx.stroke();
    }
  }
  /* name tag + hp bar (same treatment as the other boss ships) */
  ctx.fillStyle='rgba(0,0,0,0.55)';ctx.fillRect(-R*0.95,R*0.98,R*1.9,17);
  ctx.fillStyle=bt.accent;ctx.font='900 11px system-ui';ctx.textAlign='center';
  ctx.fillText('😈 LORD INFERNO — THE HORNED MOON',0,R*0.98+13);ctx.textAlign='left';
  ctx.fillStyle='rgba(0,0,0,.5)';ctx.fillRect(-R,-R-18,R*2,8);
  ctx.fillStyle='#ff4a00';ctx.fillRect(-R,-R-18,R*2*(e.hp/e.maxHp),8);
}

/* input: drag to steer */
let dragging=false;
let dragOffX=0,dragOffY=0;
canvas.addEventListener('pointerdown',e=>{dragging=true;dragOffX=G.px-e.clientX;dragOffY=G.py-e.clientY;canvas.setPointerCapture(e.pointerId);});
canvas.addEventListener('pointermove',e=>{if(dragging){G.px=Math.max(20,Math.min(W-20,e.clientX+dragOffX));G.py=Math.max(H*0.4,Math.min(e.clientY+dragOffY,H*0.9));}});
canvas.addEventListener('pointerup',()=>dragging=false);
canvas.addEventListener('pointercancel',()=>dragging=false);
const KEYS={};
addEventListener('keydown',e=>{KEYS[e.key]=true;
  if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))e.preventDefault();});
addEventListener('keyup',e=>{KEYS[e.key]=false;});

/* update */
function update(dt){
  G.time+=dt;
  const _ksp=430*dt; // smooth held-key steering (genre standard for a shmup)
  if(KEYS.ArrowLeft)G.px=Math.max(30,G.px-_ksp);
  if(KEYS.ArrowRight)G.px=Math.min(W-30,G.px+_ksp);
  if(KEYS.ArrowUp)G.py=Math.max(H*0.4,G.py-_ksp);
  if(KEYS.ArrowDown)G.py=Math.min(H*0.92,G.py+_ksp);
  if(G.invuln>0)G.invuln-=dt;
  if(G.powerT>0){G.powerT-=dt;if(G.powerT<=0)G.power=1;}
  // auto-fire
  G.fireT-=dt;
  if(G.fireT<=0){
    G.fireT=G.power===2?0.12:G.power===4?0.20:G.power===5?0.15:0.18;
    const n=G.power===3?3:G.power===4?4:G.power===5?2:1;
    for(let i=0;i<n;i++){
      const off=(i-(n-1)/2)*14;
      G.bullets.push({x:G.px+off,y:G.py-30,vx:G.power===4?(i-(n-1)/2)*140:G.power===5?0:off*8,vy:-700,dead:false}); // Nova fans its 4 bolts; Twin fires 2 straight bolts
    }
    sfx.shoot();
  }
  // bullets
  for(const b of G.bullets){
    b.x+=b.vx*dt;b.y+=b.vy*dt;
    if(b.y<-20)b.dead=true;
    for(const e of G.enemies){
      if(e.dead)continue;
      if(Math.hypot(b.x-e.x,b.y-e.y)<e.r+6){
        b.dead=true;
        if(e.type==='carrier'&&e.shieldHp>0){
          /* shielded carrier: the shield drinks the hit first */
          e.shieldHp--;
          for(let i=0;i<4;i++)spawnP(b.x,b.y,(Math.random()-0.5)*200,(Math.random()-0.5)*200,0.3,'#7fd4ff',3);
          if(e.shieldHp===0)spawnText(e.x,e.y-34,'SHIELD DOWN!','#7fd4ff');
        }else{
          let dmg=1;
          if(e.kind==='moon')dmg=moonHit(e,b.x,b.y);
          e.hp-=dmg;
          if(dmg===0){
            for(let i=0;i<3;i++)spawnP(b.x,b.y,(Math.random()-0.5)*160,(Math.random()-0.5)*160,0.25,'#aee8ff',3);
            if(e.sealNoteT<=0){spawnText(e.x,e.y+e.r+20,'SEALED — WAIT FOR THE CORE!','#aee8ff');e.sealNoteT=1.2;}
          }else{
            for(let i=0;i<4;i++)spawnP(b.x,b.y,(Math.random()-0.5)*200,(Math.random()-0.5)*200,0.3,'#ffd23f',3);
          }
          if(e.hp<=0)killEnemy(e);
        }
        break;
      }
    }
  }
  G.bullets=G.bullets.filter(b=>!b.dead);
  // enemies
  if(G.boss&&!G.boss.dead){
    const bo=G.boss;
    if(bo.kind==='moon'){
      moonUpdate(bo,dt);
    }else{
      bo.t+=dt;
      if(bo.y<140)bo.y+=bo.vy*dt;
      else{bo.x=W/2+Math.sin(bo.t*1.2)*W*0.3;
        bo.fireT-=dt;
        if(bo.fireT<=0)bossFire(bo);
      }
    }
  }
  for(const e of G.enemies){
    if(e.dead||e===G.boss)continue;
    e.t+=dt;e.x+=e.vx*dt;e.y+=e.vy*dt;
    if(e.type==='dart')e.x+=Math.sin(e.t*5)*120*dt;
    if(e.type==='weaver')e.x=e.bx+Math.sin(e.t*2.8+e.ph)*e.amp; // weaver zigzags around its lane
    if(e.type==='carrier'){
      e.spawnT-=dt; // carrier keeps launching mini ships out of its bay
      if(e.spawnT<=0&&G.enemies.length<12){
        e.spawnT=3.4;
        G.enemies.push({type:'mini',x:e.x+(Math.random()<0.5?-1:1)*e.r*0.7,y:e.y+e.r*0.6,
          vx:(Math.random()-0.5)*80,vy:235+G.level*12,hp:1,r:14,dead:false,t:0,score:25});
        spawnText(e.x,e.y+e.r+14,'SHIP LAUNCHED!','#ffb8a0');
      }
    }
    if(e.y>H+60||(e.type==='bolt'&&(e.y<-90||e.x<-70||e.x>W+70)))e.dead=true;
    // hit player
    if(G.invuln<=0&&Math.hypot(e.x-G.px,e.y-G.py)<e.r+22){
      e.dead=true;damagePlayer(e.type==='tank'?25:15);
      explode(e.x,e.y,'#ff6a1a',12);
    }
  }
  G.enemies=G.enemies.filter(e=>!e.dead);
  // pickups
  for(const p of G.pickups){
    p.t+=dt;p.y+=p.vy*dt;
    if(p.y>H+30)p.dead=true;
    if(Math.hypot(p.x-G.px,p.y-G.py)<34){
      p.dead=true;applyPickup(p.type);
    }
  }
  G.pickups=G.pickups.filter(p=>!p.dead);
  // wave spawner
  if(!G.boss||G.boss.dead){
    if(G.waveKills>=G.waveTarget){
      if(G.wave===3&&!G.boss){
        spawnBoss();
      }else if(G.boss&&G.boss.dead){
        levelComplete();
      }else if(G.wave<3){
        G.wave++;G.waveKills=0;G.waveTarget=6+G.level*2+G.wave*2;
        document.getElementById('wave').textContent='🌊 Wave '+G.wave;
        spawnText(W/2,H*0.4,'WAVE '+G.wave,'#7fd4ff');
      }
    }else if(G.enemies.length<4+G.level){
      if(Math.random()<dt*(1+G.level*0.3))spawnEnemy();
    }
  }
  // boss defeated
  if(G.boss&&G.boss.dead&&G.wave>=3)levelComplete();
}
function killEnemy(e){
  e.dead=true;
  const pts=e.score*(1+Math.floor(G.wave/2)*0.5);
  G.score+=Math.round(pts);updateScoreUI();
  G.waveKills++;
  sfx.explode();addTrauma(e.type==='boss'?0.6:0.25);
  explode(e.x,e.y,e.type==='bolt'?'#ff4a00':'#ff8a3a',e.type==='boss'?30:12);
  spawnText(e.x,e.y-20,'+'+Math.round(pts));
  if(Math.random()<0.18)spawnPickup(e.x,e.y);
  if(e.type==='splitter'){
    /* splitter breaks into two zippy mini ships */
    for(const s of [-1,1])
      G.enemies.push({type:'mini',x:e.x+s*18,y:e.y,vx:s*95,vy:200+G.level*10,
        hp:1,r:14,dead:false,t:0,score:25});
  }
  if(e.kind==='moon'){
    /* Lord Inferno bails out — comical retreat, villain-style */
    spawnText(W/2,H*0.3,"😈 'I'LL BE BAAACK!'",'#ffd23f');
    spawnText(W/2,H*0.38,'🚀 Lord Inferno flees in a tiny escape pod!','#7fd4ff');
  }
  if(e.type==='boss'){
    for(let i=0;i<3;i++)spawnPickup(e.x+(Math.random()-0.5)*100,e.y);
    hitStop=0.3;
  }
}
function explode(x,y,color,n){
  for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,sp=80+Math.random()*300;
    spawnP(x,y,Math.cos(a)*sp,Math.sin(a)*sp,0.5+Math.random()*0.4,color,3+Math.random()*5);}
}
function damagePlayer(dmg){
  if(G.invuln>0)return;
  G.hp-=dmg;G.invuln=0.8;updateHP();
  sfx.hit();addTrauma(0.45);hitStop=0.08;
  for(let i=0;i<10;i++)spawnP(G.px,G.py,(Math.random()-0.5)*300,(Math.random()-0.5)*300,0.5,'#ff4a00',4);
  if(G.hp<=0)gameOver();
}
function applyPickup(type){
  sfx.power();
  if(type==='hp'){G.hp=Math.min(G.maxHp,G.hp+30);updateHP();spawnText(G.px,G.py-40,'+HP','#4caf50');}
  else if(type==='rapid'){G.power=2;G.powerT=10;spawnText(G.px,G.py-40,'RAPID FIRE!','#7fd4ff');}
  else if(type==='spread'){G.power=3;G.powerT=10;spawnText(G.px,G.py-40,'SPREAD SHOT!','#ffd23f');}
  else if(type==='nova'){G.power=4;G.powerT=10;spawnText(G.px,G.py-40,'EMBER NOVA x4!','#ff9a3a');tone(300,900,0.2,'sawtooth',0.12);}
  else if(type==='twin'){G.power=5;G.powerT=10;spawnText(G.px,G.py-40,'TWIN BALLISTA!','#ff7fd4');tone(500,1200,0.18,'square',0.1);}
  else{G.invuln=5;spawnText(G.px,G.py-40,'SHIELD!','#4caf50');}
}
function levelComplete(){
  if(G.state!=='play')return;
  G.state='clear';sfx.win();
  const hpBonus=Math.round(G.hp*5);
  G.score+=hpBonus;updateScoreUI();
  const stars=G.hp>70?3:G.hp>35?2:1;
  setTimeout(()=>{
    if(G.level>=15){
      showOverlay('🌕 THE SKIES ARE SAFE!',
        `<div class="stars">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</div><p><b>The Horned Moon is beaten!</b> Lord Inferno fled in a tiny escape pod, shaking his fist all the way home. 🚀</p><p style="font-size:26px;font-weight:900">Final Score: ${G.score}</p>`,
        '🔥 Fire Safety: You\'re a fire safety champion! Real heroes keep the skies AND their homes safe — test your smoke alarms every month!',
        '↻ PLAY AGAIN',()=>{reset(1);G.score=0;updateScoreUI();G.state='play';});
    }else{
      showOverlay(`⭐ LEVEL ${G.level} CLEAR!`,
        `<div class="stars">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</div><p>Score: ${G.score} (+${hpBonus} HP bonus)</p>`,
        '🔥 Fire Safety: Never aim anything at a fire — get away and call for help!',
        '▶ NEXT LEVEL',()=>{reset(G.level+1);G.state='play';});
    }
  },800);
}
function gameOver(){
  G.state='over';sfx.hit();addTrauma(0.7);
  explode(G.px,G.py,'#ff6a1a',25);
  setTimeout(()=>{
    showOverlay('💥 BALLISTA DOWN!',
      `<p style="font-size:24px;font-weight:900">Score: ${G.score}</p><p>Wave: ${G.wave}</p>`,
      '🔥 Fire Safety: Never aim anything at a fire — get away and call for help!',
      '↻ TRY AGAIN',()=>{reset(G.level);G.score=0;updateScoreUI();G.state='play';});
  },800);
}

/* overlay */
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();reset(pendingLevel||1);pendingLevel=0;G.score=0;updateScoreUI();G.state='play';overlay.classList.add('hidden');}
let pendingLevel=0;
function selLevel(n){sfx.click();pendingLevel=n;showMathGate();}
obtn.onclick=()=>{showMathGate();};
(function(){let h='';for(let i=1;i<=15;i++)h+=`<button class="lvlBtn" onclick="event.stopPropagation();selLevel(${i})">${i}</button>`;
document.getElementById('levelSel').innerHTML=h;})();

/* render */
function render(){
  const th=theme();
  // HOME WORLD sky (ember dusk, tinted per kingdom) — NOT outer space
  const sky=ctx.createLinearGradient(0,0,0,H);
  sky.addColorStop(0,th.sky[0]);sky.addColorStop(0.55,th.sky[1]);sky.addColorStop(1,th.sky[2]);
  ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
  // level 15: the Horned Moon itself hangs in the sky behind the fight
  if(G.level===15){
    const mx=W*0.8,my=H*0.15,mr=Math.min(58,W*0.11);
    ctx.fillStyle='rgba(232,224,255,0.9)';
    ctx.beginPath();ctx.arc(mx,my,mr,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='rgba(160,150,190,0.5)';
    ctx.beginPath();ctx.arc(mx-mr*0.3,my-mr*0.2,mr*0.16,0,Math.PI*2);ctx.fill();
    ctx.beginPath();ctx.arc(mx+mr*0.25,my+mr*0.3,mr*0.12,0,Math.PI*2);ctx.fill();
    ctx.beginPath();ctx.arc(mx+mr*0.45,my-mr*0.35,mr*0.09,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#2a0a14';
    ctx.beginPath();ctx.moveTo(mx-mr*0.8,my-mr*0.55);ctx.quadraticCurveTo(mx-mr*1.25,my-mr*1.15,mx-mr*0.55,my-mr*1.2);ctx.quadraticCurveTo(mx-mr*0.72,my-mr*0.85,mx-mr*0.5,my-mr*0.62);ctx.closePath();ctx.fill();
    ctx.beginPath();ctx.moveTo(mx+mr*0.8,my-mr*0.55);ctx.quadraticCurveTo(mx+mr*1.25,my-mr*1.15,mx+mr*0.55,my-mr*1.2);ctx.quadraticCurveTo(mx+mr*0.72,my-mr*0.85,mx+mr*0.5,my-mr*0.62);ctx.closePath();ctx.fill();
  }
  // the great volcano on the horizon (home-world landmark), slow parallax
  const vOff=(G.time*12)%(H*1.4);
  ctx.fillStyle=th.land;
  for(let k=-1;k<2;k++){
    const vy=H*0.9-vOff+k*H*1.4;
    if(vy<-H*0.4||vy>H+H*0.4)continue;
    ctx.beginPath();ctx.moveTo(W*0.18,vy);ctx.lineTo(W*0.5,vy-H*0.34);ctx.lineTo(W*0.82,vy);ctx.closePath();ctx.fill();
    ctx.fillStyle='#ff4a00';ctx.beginPath();ctx.ellipse(W*0.5,vy-H*0.335,W*0.045,H*0.012,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle=th.land;
  }
  // scrolling kingdom silhouettes along the bottom (shape varies by level)
  const gOff=(G.time*130)%110;
  ctx.fillStyle=th.land;
  ctx.fillRect(0,H-46,W,46);
  for(let i=-1;i<W/110+2;i++){
    const sx=i*110-gOff,base=H-46;
    if(th.shape==='peaks'){ctx.beginPath();ctx.moveTo(sx,base);ctx.lineTo(sx+40,base-52-((i*37)%26));ctx.lineTo(sx+80,base);ctx.closePath();ctx.fill();}
    else if(th.shape==='spires'){ctx.fillRect(sx+22,base-64-((i*29)%30),16,64+((i*29)%30));ctx.beginPath();ctx.moveTo(sx+16,base-64-((i*29)%30));ctx.lineTo(sx+30,base-84-((i*29)%30));ctx.lineTo(sx+44,base-64-((i*29)%30));ctx.closePath();ctx.fill();}
    else if(th.shape==='trees'){ctx.beginPath();ctx.arc(sx+40,base-38,26+((i*23)%10),0,Math.PI*2);ctx.fill();ctx.fillRect(sx+36,base-30,8,30);}
    else if(th.shape==='waves'){ctx.beginPath();ctx.ellipse(sx+50,base+4,62,16,0,Math.PI,Math.PI*2);ctx.fill();}
    else{ctx.beginPath();ctx.ellipse(sx+55,base,58,20+((i*31)%12),0,Math.PI,Math.PI*2);ctx.fill();} // dunes
  }
  drawEmbers();
  // drifting clouds over the kingdoms
  ctx.fillStyle='rgba(255,190,140,0.13)';
  for(let i=0;i<5;i++){
    const cx=(i*311+G.time*40)%(W+200)-100,cy=(i*173)%(H*0.6);
    ctx.beginPath();ctx.ellipse(cx,cy,70,22,0,0,Math.PI*2);ctx.fill();
  }
  ctx.save();
  if(trauma>0)ctx.translate(shakeX,shakeY);
  // pickups
  for(const p of G.pickups){
    ctx.save();ctx.translate(p.x,p.y);ctx.rotate(Math.sin(p.t*4)*0.2);
    const cols={hp:'#4caf50',rapid:'#7fd4ff',spread:'#ffd23f',shield:'#9a7fd4',nova:'#ff9a3a',twin:'#ff7fd4'};
    ctx.fillStyle=cols[p.type];ctx.strokeStyle='#fff';ctx.lineWidth=2;
    ctx.beginPath();ctx.arc(0,0,15,0,Math.PI*2);ctx.fill();ctx.stroke();
    ctx.fillStyle='#fff';ctx.font='900 14px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';
    ctx.fillText({hp:'+',rapid:'»',spread:'∴',shield:'◈',nova:'✦',twin:'✚'}[p.type],0,1);
    ctx.restore();
  }
  ctx.textBaseline='alphabetic';
  // enemies: ALL are flying sky-ships with a little bad-guy pilot (Jeff 2026-10-13)
  const thE=theme();
  for(const e of G.enemies){
    ctx.save();ctx.translate(e.x,e.y);
    const bob=Math.sin(e.t*3+e.x*0.05)*2;
    if(e.type==='boss'&&e.kind==='moon'){
      drawMoonFortress(e,bossTheme());
    }else if(e.type==='boss'){
      const bt=bossTheme(),R=e.r;
      ctx.translate(0,bob);
      // GIANT boss ship: wide hull, wing cannons, big dome with the angry boss inside
      const bg2=ctx.createLinearGradient(0,-R,0,R);
      bg2.addColorStop(0,bt.hull);bg2.addColorStop(1,'#1c0a06');
      ctx.fillStyle=bg2;
      ctx.beginPath();ctx.ellipse(0,R*0.25,R*1.55,R*0.62,0,0,Math.PI*2);ctx.fill();
      ctx.strokeStyle=bt.accent;ctx.lineWidth=4;ctx.stroke();
      // wings + cannons
      ctx.fillStyle=bt.hull;
      ctx.beginPath();ctx.moveTo(-R*1.2,-R*0.1);ctx.lineTo(-R*1.85,R*0.45);ctx.lineTo(-R*1.1,R*0.55);ctx.closePath();ctx.fill();
      ctx.beginPath();ctx.moveTo(R*1.2,-R*0.1);ctx.lineTo(R*1.85,R*0.45);ctx.lineTo(R*1.1,R*0.55);ctx.closePath();ctx.fill();
      ctx.fillStyle='#2a2a33';
      ctx.fillRect(-R*1.75,R*0.4,10,20);ctx.fillRect(R*1.75-10,R*0.4,10,20);
      // engine flames
      const bf=12+Math.sin(G.time*26)*5;
      const bfg=ctx.createLinearGradient(0,-R*0.5,0,-R*0.5-bf*2);
      bfg.addColorStop(0,'#ffd23f');bfg.addColorStop(1,'rgba(255,106,0,0)');
      ctx.fillStyle=bfg;
      ctx.beginPath();ctx.moveTo(-R*0.5,-R*0.42);ctx.lineTo(-R*0.2,-R*0.42);ctx.lineTo(-R*0.35,-R*0.42-bf*2);ctx.closePath();ctx.fill();
      ctx.beginPath();ctx.moveTo(R*0.2,-R*0.42);ctx.lineTo(R*0.5,-R*0.42);ctx.lineTo(R*0.35,-R*0.42-bf*2);ctx.closePath();ctx.fill();
      // cockpit dome + THE BOSS (angry, sitting in the ship)
      ctx.fillStyle='rgba(190,230,255,0.35)';
      ctx.beginPath();ctx.arc(0,-R*0.28,R*0.62,Math.PI,Math.PI*2);ctx.fill();
      ctx.strokeStyle=bt.accent;ctx.lineWidth=3;
      ctx.beginPath();ctx.arc(0,-R*0.28,R*0.62,Math.PI,Math.PI*2);ctx.stroke();
      drawPilot(0,-R*0.34,R*0.42,bt.skin,bt.hat,bt.accent);
      // boss name tag
      ctx.fillStyle='rgba(0,0,0,0.55)';ctx.fillRect(-R*0.95,R*0.98,R*1.9,17);
      ctx.fillStyle=bt.accent;ctx.font='900 11px system-ui';ctx.textAlign='center';
      ctx.fillText(bt.name,0,R*0.98+13);ctx.textAlign='left';
      // hp bar
      ctx.fillStyle='rgba(0,0,0,.5)';ctx.fillRect(-R,-R-18,R*2,8);
      ctx.fillStyle='#ff4a00';ctx.fillRect(-R,-R-18,R*2*(e.hp/e.maxHp),8);
    }else if(e.type==='dart'){
      // DART SHIP: sleek, fast, pointed nose down, pilot in a slit cockpit
      ctx.translate(0,bob);
      const dg=ctx.createLinearGradient(0,-e.r,0,e.r);
      dg.addColorStop(0,thE.hull);dg.addColorStop(1,'#140a20');
      ctx.fillStyle=dg;
      ctx.beginPath();ctx.moveTo(0,e.r*1.25);ctx.lineTo(e.r*0.72,-e.r*0.7);ctx.lineTo(0,-e.r*0.35);ctx.lineTo(-e.r*0.72,-e.r*0.7);ctx.closePath();ctx.fill();
      ctx.strokeStyle=thE.accent;ctx.lineWidth=2;ctx.stroke();
      ctx.fillStyle='rgba(190,230,255,0.5)';
      ctx.beginPath();ctx.ellipse(0,-e.r*0.25,e.r*0.3,e.r*0.42,0,0,Math.PI*2);ctx.fill();
      drawPilot(0,-e.r*0.25,e.r*0.3,thE.pilot,'hood',thE.accent);
      const df=8+Math.sin(G.time*30+e.x)*3;
      ctx.fillStyle='rgba(255,160,40,0.8)';
      ctx.beginPath();ctx.moveTo(-4,-e.r*0.72);ctx.lineTo(4,-e.r*0.72);ctx.lineTo(0,-e.r*0.72-df*1.6);ctx.closePath();ctx.fill();
    }else if(e.type==='tank'){
      // HAULER SHIP: big bulky freighter, twin domes, pilot up front
      ctx.translate(0,bob);
      const tg=ctx.createLinearGradient(0,-e.r,0,e.r);
      tg.addColorStop(0,thE.hull);tg.addColorStop(1,'#160d06');
      ctx.fillStyle=tg;
      ctx.beginPath();ctx.ellipse(0,0,e.r*1.25,e.r*0.85,0,0,Math.PI*2);ctx.fill();
      ctx.strokeStyle=thE.accent;ctx.lineWidth=3;ctx.stroke();
      ctx.fillStyle='rgba(20,12,6,0.6)';
      ctx.fillRect(-e.r*1.1,-e.r*0.1,e.r*0.5,e.r*0.5);ctx.fillRect(e.r*0.6,-e.r*0.1,e.r*0.5,e.r*0.5); // cargo pods
      ctx.fillStyle='rgba(190,230,255,0.45)';
      ctx.beginPath();ctx.arc(0,-e.r*0.3,e.r*0.42,Math.PI,Math.PI*2);ctx.fill();
      drawPilot(0,-e.r*0.32,e.r*0.3,thE.pilot,'cap',thE.accent);
      ctx.strokeStyle=thE.accent;ctx.lineWidth=2;
      ctx.beginPath();ctx.arc(0,e.r*0.28,e.r*0.5,0.2,Math.PI-0.2);ctx.stroke();
    }else if(e.type==='weaver'){
      // WEAVER SHIP: crescent wings, darts side to side as it dives
      ctx.translate(0,bob);
      const wg=ctx.createLinearGradient(0,-e.r,0,e.r);
      wg.addColorStop(0,thE.hull);wg.addColorStop(1,'#12081c');
      ctx.fillStyle=wg;
      ctx.beginPath();ctx.moveTo(0,e.r*1.2);
      ctx.quadraticCurveTo(e.r*1.5,e.r*0.5,e.r*1.35,-e.r*0.6);
      ctx.quadraticCurveTo(e.r*0.5,-e.r*0.25,0,-e.r*0.4);
      ctx.quadraticCurveTo(-e.r*0.5,-e.r*0.25,-e.r*1.35,-e.r*0.6);
      ctx.quadraticCurveTo(-e.r*1.5,e.r*0.5,0,e.r*1.2);ctx.fill();
      ctx.strokeStyle=thE.accent;ctx.lineWidth=2;ctx.stroke();
      ctx.fillStyle='rgba(190,230,255,0.5)';
      ctx.beginPath();ctx.ellipse(0,-e.r*0.15,e.r*0.3,e.r*0.38,0,0,Math.PI*2);ctx.fill();
      drawPilot(0,-e.r*0.15,e.r*0.28,thE.pilot,'hood',thE.accent);
      const wf=7+Math.sin(G.time*30+e.x)*3;
      ctx.fillStyle='rgba(255,160,40,0.8)';
      ctx.beginPath();ctx.moveTo(-4,-e.r*0.55);ctx.lineTo(4,-e.r*0.55);ctx.lineTo(0,-e.r*0.55-wf*1.6);ctx.closePath();ctx.fill();
    }else if(e.type==='carrier'){
      // CARRIER SHIP: huge shielded freighter that launches mini ships
      ctx.translate(0,bob);
      const cg=ctx.createLinearGradient(0,-e.r,0,e.r);
      cg.addColorStop(0,thE.hull);cg.addColorStop(1,'#140a06');
      ctx.fillStyle=cg;
      ctx.beginPath();ctx.ellipse(0,0,e.r*1.5,e.r*0.82,0,0,Math.PI*2);ctx.fill();
      ctx.strokeStyle=thE.accent;ctx.lineWidth=3;ctx.stroke();
      ctx.fillStyle='rgba(20,12,6,0.65)';
      ctx.fillRect(-e.r*1.3,-e.r*0.05,e.r*0.6,e.r*0.55);ctx.fillRect(e.r*0.7,-e.r*0.05,e.r*0.6,e.r*0.55); // hangar bays
      ctx.fillStyle=(Math.sin(G.time*6+e.x)>0)?'#ff4a4a':thE.accent;
      ctx.beginPath();ctx.arc(-e.r*1.0,e.r*0.2,3.5,0,Math.PI*2);ctx.arc(e.r*1.0,e.r*0.2,3.5,0,Math.PI*2);ctx.fill();
      ctx.fillStyle='rgba(190,230,255,0.45)';
      ctx.beginPath();ctx.arc(0,-e.r*0.32,e.r*0.45,Math.PI,Math.PI*2);ctx.fill();
      drawPilot(0,-e.r*0.34,e.r*0.3,thE.pilot,'cap',thE.accent);
      // shield bubble — visibly thins as the shield is shot away
      if(e.shieldHp>0){
        ctx.strokeStyle=`rgba(127,212,255,${0.25+0.45*(e.shieldHp/6)})`;
        ctx.lineWidth=3;
        ctx.beginPath();ctx.arc(0,0,e.r*1.62,0,Math.PI*2);ctx.stroke();
        ctx.strokeStyle='rgba(255,255,255,0.35)';ctx.lineWidth=1.5;
        ctx.beginPath();ctx.arc(0,0,e.r*1.62,Math.PI*1.15,Math.PI*1.5);ctx.stroke();
      }
    }else if(e.type==='splitter'){
      // SPLITTER POD: two fused halves with a glowing crack seam
      ctx.translate(0,bob);
      const pg=ctx.createLinearGradient(0,-e.r,0,e.r);
      pg.addColorStop(0,thE.hull);pg.addColorStop(1,'#160a10');
      ctx.fillStyle=pg;
      ctx.beginPath();ctx.ellipse(0,0,e.r*1.05,e.r*0.9,0,0,Math.PI*2);ctx.fill();
      ctx.strokeStyle=thE.accent;ctx.lineWidth=2.5;ctx.stroke();
      ctx.strokeStyle='#ffb347';ctx.lineWidth=2;
      ctx.beginPath();ctx.moveTo(0,-e.r*0.85);
      ctx.lineTo(e.r*0.16,-e.r*0.3);ctx.lineTo(-e.r*0.14,e.r*0.1);ctx.lineTo(e.r*0.1,e.r*0.55);ctx.lineTo(0,e.r*0.85);ctx.stroke();
      ctx.fillStyle='rgba(190,230,255,0.45)';
      ctx.beginPath();ctx.arc(-e.r*0.45,-e.r*0.3,e.r*0.34,Math.PI,Math.PI*2);ctx.fill();
      ctx.beginPath();ctx.arc(e.r*0.45,-e.r*0.3,e.r*0.34,Math.PI,Math.PI*2);ctx.fill();
      drawPilot(-e.r*0.45,-e.r*0.32,e.r*0.24,thE.pilot,'cap',thE.accent);
      drawPilot(e.r*0.45,-e.r*0.32,e.r*0.24,thE.pilot,'hood',thE.accent);
    }else if(e.type==='bolt'){
      // boss fire-bolt (a shot, not a ship)
      ctx.fillStyle='#ff6a00';
      ctx.beginPath();ctx.arc(0,0,e.r,0,Math.PI*2);ctx.fill();
      ctx.fillStyle='#ffd23f';ctx.beginPath();ctx.arc(0,0,e.r*0.5,0,Math.PI*2);ctx.fill();
    }else{
      // SCOUT SHIP: little saucer with the pilot right on top in a dome
      ctx.translate(0,bob);
      const sg=ctx.createLinearGradient(0,-e.r,0,e.r);
      sg.addColorStop(0,thE.hull);sg.addColorStop(1,'#160d08');
      ctx.fillStyle=sg;
      ctx.beginPath();ctx.ellipse(0,e.r*0.25,e.r*1.15,e.r*0.5,0,0,Math.PI*2);ctx.fill();
      ctx.strokeStyle=thE.accent;ctx.lineWidth=2;ctx.stroke();
      // blinking rim lights
      ctx.fillStyle=(Math.sin(G.time*8+e.x)>0)?thE.accent:'#ff4a4a';
      for(let li=-1;li<=1;li++){ctx.beginPath();ctx.arc(li*e.r*0.62,e.r*0.32,3,0,Math.PI*2);ctx.fill();}
      ctx.fillStyle='rgba(190,230,255,0.45)';
      ctx.beginPath();ctx.arc(0,-e.r*0.12,e.r*0.52,Math.PI,Math.PI*2);ctx.fill();
      drawPilot(0,-e.r*0.18,e.r*0.36,thE.pilot,'cap',thE.accent);
    }
    ctx.restore();
  }
  // bullets
  for(const b of G.bullets){
    ctx.save();{ctx.save();ctx.globalAlpha=0.55;const gr2=26;ctx.drawImage(BULLET_GLOW,b.x-gr2,b.y-gr2,gr2*2,gr2*2);ctx.restore();} // [w5c perf] pre-baked bullet glow (was shadowBlur=12 per bullet per frame)
    const g=ctx.createLinearGradient(b.x,b.y-14,b.x,b.y+6);
    g.addColorStop(0,'#fff');g.addColorStop(0.5,'#ffd23f');g.addColorStop(1,'#ff6a00');
    ctx.fillStyle=g;
    ctx.beginPath();ctx.ellipse(b.x,b.y,5,12,0,0,Math.PI*2);ctx.fill();
    ctx.restore();
  }
  // player ballista
  if(G.state==='play'){
    const blink=G.invuln>0&&Math.sin(G.time*30)>0;
    ctx.globalAlpha=blink?0.4:1;
    ctx.save();ctx.translate(G.px,G.py);
    ctx.shadowColor='#ff7a2a';ctx.shadowBlur=16;
    // ballista base
    ctx.fillStyle='#5a3a1a';
    ctx.fillRect(-24,-8,48,16);
    ctx.fillStyle='#3a2410';
    ctx.beginPath();ctx.arc(-24,8,8,0,Math.PI*2);ctx.arc(24,8,8,0,Math.PI*2);ctx.fill();
    // bow arms
    ctx.strokeStyle='#8a5a2a';ctx.lineWidth=6;ctx.lineCap='round';
    ctx.beginPath();ctx.moveTo(0,-8);ctx.quadraticCurveTo(-30,-30,-38,-8);ctx.stroke();
    ctx.beginPath();ctx.moveTo(0,-8);ctx.quadraticCurveTo(30,-30,38,-8);ctx.stroke();
    // Ruko riding
    const g2=ctx.createRadialGradient(-6,-26,4,0,-20,18);
    g2.addColorStop(0,'#ffe9a0');g2.addColorStop(0.5,'#ff7a2a');g2.addColorStop(1,'#d42a1a');
    ctx.fillStyle=g2;ctx.beginPath();ctx.arc(0,-20,17,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#2b1a0e';
    ctx.beginPath();ctx.arc(-6,-22,3,0,Math.PI*2);ctx.arc(6,-22,3,0,Math.PI*2);ctx.fill();
    // engine flame
    const fl=10+Math.sin(G.time*30)*5;
    const fg=ctx.createLinearGradient(0,8,0,8+fl*2);
    fg.addColorStop(0,'#ffd23f');fg.addColorStop(1,'rgba(255,106,0,0)');
    ctx.fillStyle=fg;
    ctx.beginPath();ctx.moveTo(-8,8);ctx.lineTo(8,8);ctx.lineTo(0,8+fl*2);ctx.closePath();ctx.fill();
    ctx.restore();
    ctx.globalAlpha=1;
    // shield ring
    if(G.invuln>2){
      ctx.strokeStyle='rgba(76,175,80,0.7)';ctx.lineWidth=3;
      ctx.beginPath();ctx.arc(G.px,G.py,40+Math.sin(G.time*6)*3,0,Math.PI*2);ctx.stroke();
    }
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size*(p.life/p.max),0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  ctx.textAlign='center';
  for(const f of floaters){
    if(!f.a)continue;
    ctx.globalAlpha=Math.min(1,f.life);
    ctx.font='900 20px system-ui';ctx.fillStyle='#000';
    ctx.fillText(f.txt,f.x+2,f.y+2);ctx.fillStyle=f.color;ctx.fillText(f.txt,f.x,f.y);
  }
  ctx.globalAlpha=1;ctx.textAlign='left';
  ctx.restore();
}


/* gamer-check: pause + mute controls */
const _pz=document.getElementById('pauseOv');
function fbPause(){if(G.state==='play'){G.state='pause';_pz.classList.remove('hidden');}}
function fbResume(){if(G.state==='pause'){G.state='play';_pz.classList.add('hidden');}}
document.getElementById('pauseBtn').onclick=e=>{e.stopPropagation();fbPause();};
document.getElementById('resumeBtn').onclick=()=>{fbResume();};
document.getElementById('muteBtn').onclick=e=>{e.stopPropagation();MUTED=!MUTED;e.currentTarget.textContent=MUTED?'🔇':'🔊';};
document.getElementById('prestartBtn').onclick=()=>{_pz.classList.add('hidden');reset(G.level);G.score=0;updateScoreUI();G.state='play';};
addEventListener('keydown',e=>{if(e.key==='p'||e.key==='P'||e.key==='Escape'){if(G.state==='play')fbPause();else if(G.state==='pause')fbResume();}});

/* loop */
let lastT=0;
function loop(t){
  const rawDt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  let dt=rawDt;
  if(hitStop>0){hitStop-=rawDt;dt=rawDt*0.1;}
  trauma=Math.max(0,trauma-dt*1.8);
  const sh=trauma*trauma*18;
  shakeX=(Math.random()-0.5)*sh*2;shakeY=(Math.random()-0.5)*sh*2;
  if(G.state==='play')update(dt);else G.time+=dt;
  updateEmbers(dt);
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=300*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  for(const f of floaters){if(!f.a)continue;f.y-=50*dt;f.life-=dt;if(f.life<=0)f.a=false;}
  render();
  requestAnimationFrame(loop);
}
/* ===== MUSIC (Jeff 2026-10-13): 'Siege of the Ember Keep' — Ballista Siege's
   own track. Synthesized Web Audio only. 98 BPM, D minor: low saw drones, detuned
   war-pads each bar, a dramatic square-wave war horn lead, heavy syncopated drums.
   Starts on first interaction; controlled by the existing 🔊 mute. ===== */
const _mf=m=>440*Math.pow(2,(m-69)/12);
const MUS={on:false,step:0,nextT:0,BPM:98,
 BASS:[38,0,0,0,38,0,41,0, 34,0,0,0,34,0,38,0, 41,0,0,0,41,0,45,0, 33,0,0,0,40,0,45,0],
 PAD:[50,46,53,45], // Dm, Bb, F, A roots (one pad chord per bar)
 LEAD:[74,0,0,77,0,76,74,0, 72,0,74,0,0,0,69,0, 77,0,0,81,0,79,77,0, 76,0,74,0,72,0,74,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(MUTED||G.state!=='play'){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.16){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  if(s%8===0){const p=this.PAD[s/8]; // war pad: root + fifth, two detuned saws
   tone(_mf(p),_mf(p),1.6,'sawtooth',0.02,d);tone(_mf(p)*1.005,_mf(p)*1.005,1.6,'sawtooth',0.02,d);
   tone(_mf(p+7),_mf(p+7),1.6,'triangle',0.028,d);}
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.34,'sawtooth',0.075,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.3,'square',0.045,d);
  if(s%8===0||s%8===3)tone(110,38,0.16,'sine',0.17,d); // war-drum kick
  if(s%8===2||s%8===6){noise(0.1,0.09,d,1600);tone(180,110,0.08,'triangle',0.05,d);} // snare
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());
updateScoreUI();
requestAnimationFrame(loop);

