scripts:
'use strict';
/* ============================================================
   BLAZE'S MAGMA BOUNCE v3 — full rebuild
   - Vertical climber: steer Blaze, bounce on rising magma bubbles
   - 12 levels: goal height before energy runs out; rising lava
   - Ember stars = points + energy; wind gusts on later levels
   ============================================================ */
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();

/* audio */
let AC=null,MUTED=false;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
function noise(dur,vol,delay=0,lp=1000){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const len=ac.sampleRate*dur,buf=ac.createBuffer(1,len,ac.sampleRate),d=buf.getChannelData(0);
  for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);
  const s=ac.createBufferSource();s.buffer=buf;const f=ac.createBiquadFilter();f.type='lowpass';f.frequency.value=lp;
  const g=ac.createGain();g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  s.connect(f);f.connect(g);g.connect(ac.destination);s.start(t);}

/* living ember backdrop (overhaul) */
const embers=[];
for(let i=0;i<24;i++)embers.push({x:Math.random()*Math.max(W,300),y:Math.random()*Math.max(H,300),s:1+Math.random()*2.5,v:12+Math.random()*26,o:0.22+Math.random()*0.5});
/* [w5c perf] Pre-baked glow sprites — the W5b-proven pattern copied from game-04:
   the ember loop's 24 per-frame shadowBlur=8 fills collapsed FPS under software
   rendering (10.0 FPS); blit a one-time radial-glow sprite instead. Colours,
   falloff and alpha unchanged; no gameplay/balance changes. */
function makeGlowSprite(hex){const c=document.createElement('canvas');c.width=c.height=96;const x=c.getContext('2d');
  const r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);
  const gr=x.createRadialGradient(48,48,0,48,48,48);
  gr.addColorStop(0,`rgba(${r},${g},${b},0.9)`);gr.addColorStop(0.35,`rgba(${r},${g},${b},0.38)`);gr.addColorStop(1,`rgba(${r},${g},${b},0)`);
  x.fillStyle=gr;x.fillRect(0,0,96,96);return c;}
const EMBER_SPRITE=makeGlowSprite('#ffa53a');
function drawEmbers(){ctx.save();ctx.globalCompositeOperation='lighter';
  for(const e of embers){ctx.globalAlpha=e.o*(0.6+0.4*Math.sin(G.time*3+e.x*0.05));
    const r=e.s*7;ctx.drawImage(EMBER_SPRITE,e.x-r,e.y-r,r*2,r*2);} // [w5c perf] pre-baked glow (was shadowBlur=8 per ember per frame)
  ctx.restore();}
function updateEmbers(dt){for(const e of embers){e.y-=e.v*dt;e.x+=Math.sin((G.time+e.y)*0.02)*0.3;
  if(e.y<-12){e.y=H+12;e.x=Math.random()*W;}}}
const sfx={
  pop(){noise(0.08,0.14,0,1800);tone(500,950,0.12,'sine',0.14);},
  mega(){noise(0.12,0.2,0,1200);tone(300,1200,0.2,'sine',0.16);},
  star(){tone(880,1320,0.15,'triangle',0.15);tone(1320,1760,0.1,'triangle',0.08,0.06);},
  dunk(){noise(0.4,0.35,0,500);tone(400,90,0.35,'sawtooth',0.15);},
  low(){tone(300,200,0.3,'sine',0.12);},
  win(){[523,659,784,1047].forEach((f,i)=>tone(f,f,0.25,'triangle',0.18,i*0.1));},
  click(){tone(600,600,0.06,'square',0.1);}
};

/* pools */
const particles=[],floaters=[];
for(let i=0;i<250;i++)particles.push({a:false});
for(let i=0;i<20;i++)floaters.push({a:false});
function spawnP(x,y,vx,vy,life,color,size){const p=particles.find(p=>!p.a);if(!p)return;
  p.a=true;p.x=x;p.y=y;p.vx=vx;p.vy=vy;p.life=life;p.max=life;p.color=color;p.size=size;}
function spawnText(x,y,txt,color='#ffd23f',size=20){const f=floaters.find(f=>!f.a);if(!f)return;
  f.a=true;f.x=x;f.y=y;f.txt=txt;f.color=color;f.size=size;f.life=1.2;}
let trauma=0,shakeX=0,shakeY=0;
function addTrauma(t){trauma=Math.min(1,trauma+t);}

/* levels: goal height (m), energy seconds, bubble density/size, lava rise px/s, wind gusts */
const PX_PER_M=50,GRAV=1500,BOUNCE_V=1150,MEGA_V=1520;
const LEVELS=[
  {goal:60,time:45,bubbles:7,brMin:26,brMax:40,lava:6,wind:0},
  {goal:80,time:50,bubbles:7,brMin:25,brMax:38,lava:8,wind:0},
  {goal:100,time:55,bubbles:6,brMin:24,brMax:37,lava:11,wind:0},
  {goal:120,time:60,bubbles:6,brMin:24,brMax:36,lava:14,wind:0},
  {goal:145,time:65,bubbles:6,brMin:23,brMax:35,lava:17,wind:0},
  {goal:170,time:70,bubbles:5,brMin:22,brMax:34,lava:20,wind:0},
  {goal:200,time:75,bubbles:5,brMin:22,brMax:33,lava:23,wind:130},
  {goal:230,time:80,bubbles:5,brMin:21,brMax:32,lava:26,wind:160},
  {goal:265,time:85,bubbles:5,brMin:21,brMax:31,lava:28,wind:190},
  {goal:300,time:90,bubbles:4,brMin:20,brMax:30,lava:30,wind:220},
  {goal:340,time:95,bubbles:4,brMin:20,brMax:29,lava:32,wind:245},
  {goal:380,time:100,bubbles:4,brMin:20,brMax:28,lava:35,wind:270}
];

/* state */
const G={state:'title',level:1,score:0,levelStartScore:0,time:0,energy:0,energyMax:1,
  blaze:{x:0,y:0,vx:0,vy:0,r:24,squash:0,soaked:false},
  bubbles:[],stars:[],camY:0,lavaY:0,windPhase:0,steam:true,dunkT:0,dunkReason:'',
  heightM:0,shownM:-1};
const keys={left:false,right:false};
let dragX=null;

function newBubble(y){
  const L=LEVELS[G.level-1];
  const r=L.brMin+Math.random()*(L.brMax-L.brMin);
  return{x:r+Math.random()*Math.max(1,W-2*r),y,r,
    rise:22+Math.random()*30+L.lava*1.2,
    mega:Math.random()<0.12,wob:Math.random()*6.28,pop:0};
}
function newStar(y){
  return{x:24+Math.random()*Math.max(1,W-48),y,r:13,spin:Math.random()*6.28,taken:false};
}
function startLevel(n){
  const L=LEVELS[n-1];
  G.level=n;G.levelStartScore=G.score;G.time=0;
  G.energy=L.time;G.energyMax=L.time;G.steam=true;G.dunkT=0;
  G.heightM=0;G.shownM=-1;G.windPhase=Math.random()*6.28;
  G.lavaY=90;
  const b=G.blaze;b.x=W/2;b.y=-40;b.vx=0;b.vy=0;b.r=24;b.squash=0;b.soaked=false;
  G.camY=b.y-H*0.42;
  G.bubbles=[];
  // starter bubble right under Blaze
  const sb=newBubble(b.y+b.r+30);sb.x=b.x;sb.mega=false;G.bubbles.push(sb);
  for(let i=1;i<L.bubbles;i++){
    const bb=newBubble(G.lavaY-60-Math.random()*(L.goal*PX_PER_M*0.6));
    bb.x=bb.r+Math.random()*Math.max(1,W-2*bb.r);G.bubbles.push(bb);
  }
  G.stars=[];
  for(let i=0;i<4;i++)G.stars.push(newStar(b.y-120-Math.random()*H));
  document.getElementById('level').textContent=`LEVEL ${n}/12`;
  updateGoalUI();
  const rd=document.getElementById('round');
  rd.textContent=`⬆ LEVEL ${n} — REACH ${L.goal}m!`;rd.classList.remove('hidden');
  setTimeout(()=>rd.classList.add('hidden'),2200);
}
function updateScoreUI(){document.getElementById('score').textContent='⭐ '+G.score;}
function updateGoalUI(){
  const m=Math.floor(G.heightM),L=LEVELS[G.level-1];
  document.getElementById('goal').textContent=`⬆ ${m}m / ${L.goal}m`;
  G.shownM=m;
}

/* game flow */
function levelClear(){
  if(G.state!=='play')return;
  G.state='clear';sfx.win();
  const L=LEVELS[G.level-1];
  const bonus=L.goal*2+Math.ceil(Math.max(0,G.energy))*10; // goal-height bonus + remaining energy x10
  G.score+=bonus;updateScoreUI();
  const frac=Math.max(0,G.energy)/G.energyMax;
  const stars=frac>=0.45?'⭐⭐⭐':(frac>=0.2?'⭐⭐':'⭐');
  setTimeout(()=>{
    if(G.level>=12){
      showOverlay('🏆 VOLCANO CONQUERED!',
        `<p style="font-size:26px;font-weight:900">Final Score: ${G.score}</p><p>Blaze bounced all the way to the top — 380m!</p>`,
        '🔥 Fire Safety: You\'re a fire safety champion!',
        '↻ PLAY AGAIN',()=>{G.score=0;updateScoreUI();startLevel(1);G.state='play';});
    }else{
      showOverlay(`⭐ LEVEL ${G.level} CLEARED! ${stars}`,
        `<p>Goal height reached: ${L.goal}m!</p><p>Energy bonus: +${Math.ceil(Math.max(0,G.energy))*10} &nbsp;•&nbsp; Level bonus: +${L.goal*2}</p><p>Score: ${G.score}</p>`,
        '🔥 Fire Safety: Hot lava is like a real fire — never touch, always stay back!',
        '▶ NEXT LEVEL',()=>{startLevel(G.level+1);G.state='play';});
    }
  },900);
}
function startDunk(reason){
  if(G.state!=='play')return;
  G.state='dunk';G.dunkT=0;G.dunkReason=reason;G.blaze.soaked=false;
  sfx.dunk();addTrauma(0.5);
  for(let i=0;i<22;i++){const a=Math.random()*Math.PI*2;
    spawnP(G.blaze.x,G.lavaY,Math.cos(a)*280,Math.sin(a)*280-120,0.7,'#ff6a00',4+Math.random()*4);}
}
function updateDunk(dt){
  G.dunkT+=dt;
  const b=G.blaze;
  if(G.dunkT<0.45){ // playful sink
    b.y+=((G.lavaY+14)-b.y)*Math.min(1,dt*8);b.vx=0;b.vy=0;
  }else{ // pops back up, soaked and giggling — never harmed
    b.y+=((G.lavaY-b.r-4)-b.y)*Math.min(1,dt*10);
    b.soaked=true;b.squash*=0.9;
    if(Math.random()<0.5)spawnP(b.x+(Math.random()-0.5)*30,b.y-b.r,0,-80,0.5,'#7fd4ff',3);
  }
  G.camY+=((b.y-H*0.42)-G.camY)*Math.min(1,dt*5);
  if(G.dunkT>=1.15){
    G.state='over';
    const why=G.dunkReason==='energy'?'Blaze ran out of steam — he\'s all tuckered out!':'Blaze took a playful dunk in the magma pool!';
    showOverlay('💦 SPLASHED!',
      `<p>${why} He's soaked, giggling, and ready to bounce again!</p><p>Height: ${Math.floor(G.heightM)}m &nbsp;•&nbsp; Score: ${G.score}</p>`,
      '🔥 Fire Safety: Hot lava is like a real fire — never touch, always stay back!',
      '↻ TRY AGAIN',()=>{G.score=G.levelStartScore;updateScoreUI();startLevel(G.level);G.state='play';}); // retry restores level-start score: no farming
  }
}

/* gameplay */
function update(dt){
  const L=LEVELS[G.level-1],b=G.blaze;
  G.time+=dt;
  // energy
  if(G.steam){G.energy-=dt;
    if(G.energy<=0){G.energy=0;G.steam=false;sfx.low();
      spawnText(b.x,b.y-40,'😮‍💨 OUT OF STEAM!','#9ad4ff',20);}}
  // wind gusts (later levels)
  let windAcc=0;
  if(L.wind>0){
    windAcc=L.wind*Math.sin(G.time*0.7+G.windPhase)*(0.4+0.6*Math.abs(Math.sin(G.time*0.23)));
    b.vx+=windAcc*dt;
    if(Math.abs(windAcc)>40&&Math.random()<0.4)
      spawnP(b.x+(windAcc>0?-30:30),b.y+(Math.random()-0.5)*60,windAcc*1.5,(Math.random()-0.5)*60,0.4,'#cfe8ff',2);
  }
  // controls: keys
  const ACC=2600,MAXV=430;
  if(keys.left)b.vx-=ACC*dt;
  if(keys.right)b.vx+=ACC*dt;
  if(dragX!==null){ // touch/pointer drag steering
    const want=Math.max(-MAXV,Math.min(MAXV,(dragX-b.x)*10));
    b.vx+=(want-b.vx)*Math.min(1,dt*10);
  }
  b.vx=Math.max(-MAXV,Math.min(MAXV,b.vx));
  // gravity
  b.vy+=GRAV*dt;
  b.x+=b.vx*dt;b.y+=b.vy*dt;
  b.squash*=Math.pow(0.02,dt);
  // walls
  if(b.x<b.r){b.x=b.r;b.vx=Math.abs(b.vx)*0.5;}
  if(b.x>W-b.r){b.x=W-b.r;b.vx=-Math.abs(b.vx)*0.5;}
  // bubbles rise + recycle around Blaze's band
  const bandTop=b.y-H*0.75,bandBot=Math.min(b.y+H*0.55,G.lavaY-30);
  for(const u of G.bubbles){
    u.y-=u.rise*dt;u.wob+=dt*2;
    if(u.pop>0)u.pop-=dt;
    if(u.y<bandTop-120||u.y>bandBot+160||u.y>G.lavaY-u.r*0.4){
      const nb=newBubble(bandTop+Math.random()*Math.max(40,bandBot-bandTop));
      Object.assign(u,nb);
    }
  }
  // bounce on bubbles
  if(G.steam){
    for(const u of G.bubbles){
      const dx=b.x-u.x,dy=b.y-u.y,d=Math.hypot(dx,dy);
      if(b.vy>0&&b.y<u.y+d*u.r*0.2&&d<b.r+u.r*0.9){
        b.y=u.y-(b.r+u.r*0.9);
        b.vy=u.mega?-MEGA_V:-BOUNCE_V;
        b.squash=0.35;
        u.pop=0.15;
        if(u.mega){sfx.mega();G.score+=50;spawnText(b.x,b.y-40,'MEGA BOUNCE! +50','#ffd23f',22);addTrauma(0.25);}
        else sfx.pop();
        for(let i=0;i<10;i++){const a=Math.random()*Math.PI*2;
          spawnP(u.x,u.y,Math.cos(a)*180,Math.sin(a)*180-60,0.5,'#ff9a3a',3+Math.random()*3);}
        updateScoreUI();
        break;
      }
    }
  }
  // stars: spin, collect, recycle ahead
  for(const s of G.stars){
    s.spin+=dt*4;
    if(s.taken)continue;
    const d=Math.hypot(b.x-s.x,b.y-s.y);
    if(d<b.r+s.r){
      s.taken=true;G.score+=100;G.energy=Math.min(G.energyMax,G.energy+3);
      sfx.star();spawnText(s.x,s.y,'+100 ⭐','#ffd23f',20);
      for(let i=0;i<8;i++){const a=Math.random()*Math.PI*2;
        spawnP(s.x,s.y,Math.cos(a)*140,Math.sin(a)*140-40,0.4,'#ffd23f',3);}
      updateScoreUI();
    }
    if(s.taken||s.y>G.camY+H+60||s.y<b.y-H*1.2){
      const ns=newStar(b.y-160-Math.random()*H*0.8);
      Object.assign(s,ns);
    }
  }
  // height + goal
  G.heightM=Math.max(G.heightM,-b.y/PX_PER_M);
  if(Math.floor(G.heightM)!==G.shownM)updateGoalUI();
  // rising lava — the pressure
  G.lavaY-=L.lava*dt;
  // camera follows Blaze
  G.camY+=((b.y-H*0.42)-G.camY)*Math.min(1,dt*5);
  // lose: lava catches Blaze
  if(b.y+b.r*0.55>G.lavaY)startDunk(G.steam?'lava':'energy');
  if(G.heightM>=L.goal)levelClear();
}

/* overlay */
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();G.score=0;updateScoreUI();startLevel(1);G.state='play';overlay.classList.add('hidden');}
obtn.onclick=()=>{showMathGate();};

/* input */
canvas.addEventListener('pointerdown',e=>{
  if(G.state!=='play')return;
  dragX=e.clientX;
});
canvas.addEventListener('pointermove',e=>{if(dragX!==null)dragX=e.clientX;});
canvas.addEventListener('pointerup',()=>{dragX=null;});
canvas.addEventListener('pointercancel',()=>{dragX=null;});
function bindSteer(id,key){
  const el=document.getElementById(id);
  el.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true;el.setPointerCapture(e.pointerId);});
  el.addEventListener('pointerup',()=>{keys[key]=false;});
  el.addEventListener('pointercancel',()=>{keys[key]=false;});
}
bindSteer('steerL','left');bindSteer('steerR','right');
addEventListener('keydown',e=>{
  if(e.key==='ArrowLeft'||e.key==='a'||e.key==='A'){keys.left=true;e.preventDefault();}
  if(e.key==='ArrowRight'||e.key==='d'||e.key==='D'){keys.right=true;e.preventDefault();}
});
addEventListener('keyup',e=>{
  if(e.key==='ArrowLeft'||e.key==='a'||e.key==='A')keys.left=false;
  if(e.key==='ArrowRight'||e.key==='d'||e.key==='D')keys.right=false;
});

/* render */
function drawBlaze(){
  const b=G.blaze,x=b.x,sy=b.y-G.camY;
  ctx.save();ctx.translate(x,sy);
  ctx.scale(1+b.squash,1-b.squash);
  // body: approved code-art Blaze — round flame-teardrop Fire Baby
  const g=ctx.createRadialGradient(-8,-10,5,0,0,b.r);
  g.addColorStop(0,'#ffe9a0');g.addColorStop(0.5,'#ff7a2a');g.addColorStop(1,'#d42a1a');
  ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,b.r,0,Math.PI*2);ctx.fill();
  // flame tuft on top
  ctx.fillStyle='#ff4a00';
  const w=Math.sin(G.time*10)*4;
  ctx.beginPath();ctx.moveTo(-10,-b.r+4);ctx.quadraticCurveTo(w,-b.r-16,10,-b.r+4);
  ctx.quadraticCurveTo(0,-b.r-6,-10,-b.r+4);ctx.fill();
  if(b.soaked){
    // soaked but smiling — never harmed
    ctx.fillStyle='#7fd4ff';
    ctx.beginPath();ctx.arc(-b.r*0.5,-2,4,0,Math.PI*2);ctx.arc(b.r*0.45,4,3.4,0,Math.PI*2);ctx.arc(0,-b.r*0.7,3,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#2b1a0e';ctx.lineWidth=2.5;ctx.lineCap='round';
    ctx.beginPath();ctx.arc(-8,-4,6,Math.PI*1.15,Math.PI*1.85);ctx.stroke();
    ctx.beginPath();ctx.arc(8,-4,6,Math.PI*1.15,Math.PI*1.85);ctx.stroke();
    ctx.beginPath();ctx.arc(0,4,9,0.2,Math.PI-0.2);ctx.stroke(); // big grin
  }else{
    ctx.fillStyle='#2b1a0e';
    ctx.beginPath();ctx.arc(-8,-4,4,0,Math.PI*2);ctx.arc(8,-4,4,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#2b1a0e';ctx.lineWidth=2.5;ctx.lineCap='round';
    ctx.beginPath();ctx.arc(0,6,8,0.3,Math.PI-0.3);ctx.stroke();
  }
  ctx.restore();
}
function drawBubble(u){
  const sy=u.y-G.camY;
  if(sy<-60||sy>H+60)return;
  ctx.save();ctx.translate(u.x,sy);
  const g=ctx.createRadialGradient(-u.r*0.3,-u.r*0.3,u.r*0.1,0,0,u.r);
  g.addColorStop(0,'rgba(255,220,150,0.95)');
  g.addColorStop(0.45,'rgba(255,140,40,0.85)');
  g.addColorStop(1,'rgba(200,60,10,0.9)');
  ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,u.r*(u.pop>0?1.25:1),0,Math.PI*2);ctx.fill();
  ctx.strokeStyle='rgba(255,240,200,0.7)';ctx.lineWidth=2;
  ctx.beginPath();ctx.arc(0,0,u.r*0.72,Math.PI*1.1,Math.PI*1.6);ctx.stroke();
  if(u.mega){
    ctx.strokeStyle='rgba(255,215,63,0.9)';ctx.lineWidth=3;
    ctx.beginPath();ctx.arc(0,0,u.r+4+Math.sin(G.time*6)*2,0,Math.PI*2);ctx.stroke();
  }
  ctx.restore();
}
function drawStar(s){
  const sy=s.y-G.camY;
  if(sy<-40||sy>H+40||s.taken)return;
  ctx.save();ctx.translate(s.x,sy);ctx.rotate(Math.sin(s.spin)*0.25);
  ctx.fillStyle='#ffd23f';
  ctx.beginPath();
  for(let i=0;i<5;i++){
    const a=-Math.PI/2+i*Math.PI*2/5,a2=a+Math.PI/5;
    ctx.lineTo(Math.cos(a)*s.r,Math.sin(a)*s.r);
    ctx.lineTo(Math.cos(a2)*s.r*0.45,Math.sin(a2)*s.r*0.45);
  }
  ctx.closePath();ctx.fill();
  ctx.fillStyle='#fff3c4';
  ctx.beginPath();ctx.arc(-s.r*0.25,-s.r*0.25,s.r*0.2,0,Math.PI*2);ctx.fill();
  ctx.restore();
}
function render(){
  const b=G.blaze,L=LEVELS[G.level-1];
  const bg=ctx.createRadialGradient(W/2,H*0.4,50,W/2,H*0.4,Math.max(W,H));
  bg.addColorStop(0,'#3a1a0a');bg.addColorStop(0.6,'#1a0d08');bg.addColorStop(1,'#0a0505');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  // volcano silhouette layers (parallax on climb)
  ctx.save();
  for(let li=0;li<2;li++){
    const off=((G.camY*(0.15+li*0.15))%(W*2)+W*2)%(W*2);
    ctx.fillStyle=li===0?'rgba(60,25,12,0.55)':'rgba(38,16,9,0.7)';
    ctx.beginPath();ctx.moveTo(0,H);
    for(let x=0;x<=W;x+=40){
      const wx=x+off;
      const h=H*0.55-li*H*0.08-Math.abs(Math.sin(wx*0.011+li*2))*H*0.22;
      ctx.lineTo(x,h);
    }
    ctx.lineTo(W,H);ctx.closePath();ctx.fill();
  }
  ctx.restore();
  drawEmbers();
  ctx.save();
  if(trauma>0)ctx.translate(shakeX,shakeY);
  // altitude ticks
  const topM=Math.ceil((-G.camY)/PX_PER_M)+10,botM=Math.max(0,Math.floor((-G.camY-H)/PX_PER_M)-2);
  ctx.fillStyle='rgba(255,233,200,0.5)';ctx.font='700 12px system-ui';ctx.textAlign='left';
  for(let m=botM;m<=topM;m++){
    if(m%20!==0||m===0)continue;
    const sy=-m*PX_PER_M-G.camY;
    ctx.fillRect(8,sy,26,2);
    ctx.fillText(m+'m',38,sy+4);
  }
  // goal flag
  const goalSy=-L.goal*PX_PER_M-G.camY;
  if(goalSy>-80&&goalSy<H+80){
    ctx.strokeStyle='rgba(255,255,255,0.35)';ctx.lineWidth=3;ctx.setLineDash([12,10]);
    ctx.beginPath();ctx.moveTo(0,goalSy);ctx.lineTo(W,goalSy);ctx.stroke();ctx.setLineDash([]);
    const fx=W-46;
    ctx.strokeStyle='#8a5a3a';ctx.lineWidth=5;
    ctx.beginPath();ctx.moveTo(fx,goalSy);ctx.lineTo(fx,goalSy-56);ctx.stroke();
    const wv=Math.sin(G.time*8)*4;
    ctx.fillStyle='#3fae5a';
    ctx.beginPath();ctx.moveTo(fx,goalSy-56);ctx.lineTo(fx+44+wv,goalSy-44);ctx.lineTo(fx,goalSy-32);ctx.closePath();ctx.fill();
    ctx.fillStyle='#fff';ctx.font='900 15px system-ui';ctx.textAlign='center';
    ctx.fillText(`GOAL ${L.goal}m`,W/2,goalSy-12);
  }
  // stars + bubbles
  for(const s of G.stars)drawStar(s);
  for(const u of G.bubbles)drawBubble(u);
  drawBlaze();
  // lava: drawn after Blaze so a dunk reads as going under
  const lavaSy=G.lavaY-G.camY;
  if(lavaSy<H+120){
    const lg=ctx.createLinearGradient(0,lavaSy,0,H+120);
    lg.addColorStop(0,'#ffd23f');lg.addColorStop(0.06,'#ff8a00');lg.addColorStop(0.35,'#ff4a00');lg.addColorStop(1,'#5a1a00');
    ctx.fillStyle=lg;ctx.fillRect(0,lavaSy,W,H+120-lavaSy);
    // churning surface
    for(let i=0;i<14;i++){
      const wx=(i*97+G.time*60*(1+i%3))% (W+60)-30;
      const wy=lavaSy+Math.sin(G.time*3+i)*5;
      ctx.fillStyle='rgba(255,230,150,0.75)';
      ctx.beginPath();ctx.arc(wx,wy,3+(i%3)*2,0,Math.PI*2);ctx.fill();
    }
  }
  // wind indicator
  if(L.wind>0){
    const wv=Math.sin(G.time*0.7+G.windPhase);
    if(Math.abs(wv)>0.25){
      ctx.fillStyle='rgba(207,232,255,0.85)';ctx.font='900 26px system-ui';ctx.textAlign='center';
      ctx.fillText(wv>0?'💨 ▶':'◀ 💨',W/2,110);
    }
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y-G.camY,p.size*(p.life/p.max),0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  ctx.textAlign='center';
  for(const f of floaters){
    if(!f.a)continue;
    ctx.globalAlpha=Math.min(1,f.life);
    ctx.font=`900 ${f.size||20}px system-ui`;ctx.fillStyle='#000';
    ctx.fillText(f.txt,f.x+2,f.y-G.camY+2);ctx.fillStyle=f.color;ctx.fillText(f.txt,f.x,f.y-G.camY);
  }
  ctx.globalAlpha=1;ctx.textAlign='left';
  // energy bar (canvas-drawn, no DOM thrash)
  const bw=Math.min(220,W*0.5),bx=W/2-bw/2,by=56;
  ctx.fillStyle='rgba(0,0,0,0.5)';
  ctx.fillRect(bx-4,by-4,bw+8,18);
  const frac=Math.max(0,G.energy)/G.energyMax;
  ctx.fillStyle=frac>0.5?'#3fae5a':(frac>0.25?'#ffd23f':'#ff4a00');
  if(frac>0)ctx.fillRect(bx,by,Math.max(4,bw*frac),10);
  ctx.fillStyle='#fff';ctx.font='900 13px system-ui';ctx.textAlign='center';
  ctx.fillText('⏳ '+Math.ceil(Math.max(0,G.energy))+'s',W/2,by+9);
  ctx.textAlign='left';
  ctx.restore();
}

/* gamer-check: pause + mute controls */
const _pz=document.getElementById('pauseOv');
function fbPause(){if(G.state==='play'){G.state='pause';_pz.classList.remove('hidden');}}
function fbResume(){if(G.state==='pause'){G.state='play';_pz.classList.add('hidden');}}
document.getElementById('pauseBtn').onclick=e=>{e.stopPropagation();fbPause();};
document.getElementById('resumeBtn').onclick=()=>{fbResume();};
document.getElementById('muteBtn').onclick=e=>{e.stopPropagation();MUTED=!MUTED;e.currentTarget.textContent=MUTED?'🔇':'🔊';};
document.getElementById('prestartBtn').onclick=()=>{_pz.classList.add('hidden');G.score=G.levelStartScore||0;updateScoreUI();startLevel(G.level);G.state='play';};
addEventListener('keydown',e=>{if(e.key==='p'||e.key==='P'||e.key==='Escape'){if(G.state==='play')fbPause();else if(G.state==='pause')fbResume();}});

/* loop */
let lastT=0;
function loop(t){
  const rawDt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  const dt=rawDt;
  trauma=Math.max(0,trauma-dt*1.8);
  const sh=trauma*trauma*18;
  shakeX=(Math.random()-0.5)*sh*2;shakeY=(Math.random()-0.5)*sh*2;
  if(G.state==='play')update(dt);
  else if(G.state==='dunk')updateDunk(dt);
  else G.time+=dt;
  updateEmbers(dt);
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=400*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  for(const f of floaters){if(!f.a)continue;f.y-=50*dt;f.life-=dt;if(f.life<=0)f.a=false;}
  render();
  requestAnimationFrame(loop);
}
startLevel(1);
updateScoreUI();
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Bubble Bounce Boogie' — Blaze's Magma
   Bounce's own track. Synthesized Web Audio only. 126 BPM, C major pentatonic
   over a C–G–Am–F loop: octave-bounce square bass, playful triangle lead,
   marching kick/snare/hats — bounce energy for a climbing game.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-06-blazes-magma-bounce.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
const MUS={on:false,step:0,nextT:0,BPM:126,
 BASS:[36,0,48,0,36,0,48,0, 43,0,55,0,43,0,55,0, 45,0,57,0,45,0,57,0, 41,0,53,0,41,0,48,0],
 LEAD:[72,0,76,0,79,0,76,0, 74,0,79,0,81,0,79,0, 81,0,84,0,81,0,79,0, 77,0,76,0,74,0,72,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(MUTED||G.state!=='play'){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.15,'square',0.05,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.2,'triangle',0.06,d);
  if(s%8===0||s%8===4)tone(120,45,0.11,'sine',0.13,d); // marching kick
  if(s%8===2||s%8===6)noise(0.08,0.08,d,1800); // snare
  if(s%2===0)noise(0.025,0.02,d,6500); // hat
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

