@keyframes fb-sb-fall{from{transform:translate3d(0,-8vh,0) rotate(-8deg)}to{transform:translate3d(3vw,112vh,0) rotate(38deg)}}
@keyframes fb-sb-bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-9px)}}
.fb-sb-bob{animation:fb-sb-bob 3.6s ease-in-out infinite}
/* ---- game-page badge ---- */
.fb-sb-badge{position:absolute;left:50%;bottom:6px;transform:translateX(-50%);font-size:17px;letter-spacing:2px;opacity:.55;line-height:1;white-space:nowrap}
/* ---- accents: every page ---- */
html.fb-theme-halloween ::selection{background:rgba(255,140,26,.5);color:#fff}
html.fb-mode-page body{background-color:#1c0a2a}
/* ---- hub showcase: deep-purple night + pumpkin glow ---- */
html.fb-mode-hub body{background:radial-gradient(1100px 560px at 50% -120px,rgba(124,58,237,.34),transparent 62%),radial-gradient(700px 380px at 85% 110%,rgba(255,140,26,.16),transparent 60%),#170a26}
html.fb-mode-hub nav.top{background:rgba(23,10,38,.96);border-bottom-color:rgba(155,89,182,.55)}
html.fb-mode-hub .hero{background:radial-gradient(ellipse at 50% 0%,rgba(255,140,26,.20),transparent 65%);border-bottom-color:rgba(155,89,182,.55)}
html.fb-mode-hub .hero h1{color:#ffb347;text-shadow:0 0 26px rgba(124,58,237,.65),0 4px 30px rgba(255,106,26,.35)}
html.fb-mode-hub .card{border-color:rgba(155,89,182,.5)}
html.fb-mode-hub .card:hover{border-color:#ff8c1a;box-shadow:0 16px 36px rgba(0,0,0,.45),0 0 26px rgba(124,58,237,.35)}
html.fb-mode-hub footer{border-top-color:rgba(155,89,182,.5)}
html.fb-mode-hub .hero,html.fb-mode-hub .whatsnew,html.fb-mode-hub .wrap,html.fb-mode-hub footer{position:relative;z-index:1}
/* ---- reduced motion: no falling/floating glyphs ---- */
@media (prefers-reduced-motion: reduce){#fb-seasonal-ambience{display:none}.fb-sb-bob{animation:none}}

scripts:
'use strict';
/* ============================================================
   SIZZLE'S SPARK JUMP v3 — precision charge-jump platformer
   - HOLD to charge, aim with arrows/drag, RELEASE to leap
   - Trajectory preview, crumbling ledges, magma trench,
     updraft vents, 15 levels, 3 hearts, precision scoring
   ============================================================ */
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);
  if(G&&G.ledges)buildLevel(G.level,true);}
addEventListener('resize',resize);

function clamp(v,a,b){return v<a?a:(v>b?b:v);}
function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);
  t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}

/* audio — synthesized Web Audio SFX only (no music system) */
let AC=null,MUTED=false;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
function noise(dur,vol,delay=0){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const len=Math.floor(ac.sampleRate*dur),buf=ac.createBuffer(1,len,ac.sampleRate),d=buf.getChannelData(0);
  for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);
  const s=ac.createBufferSource();s.buffer=buf;const g=ac.createGain();g.gain.value=vol;
  const f=ac.createBiquadFilter();f.type='lowpass';f.frequency.value=900;
  s.connect(f);f.connect(g);g.connect(ac.destination);s.start(t);}
const sfx={
  chargeTick(p){tone(280+p*520,320+p*520,0.05,'square',0.05);},
  release(){tone(420,950,0.16,'sine',0.16);noise(0.12,0.06);},
  land(){tone(520,720,0.08,'sine',0.12);},
  perfect(){tone(700,1400,0.16,'sine',0.14);tone(1050,1750,0.18,'sine',0.10,0.08);},
  crumble(){noise(0.22,0.10);tone(220,90,0.2,'square',0.07);},
  splash(){noise(0.45,0.16);tone(320,80,0.4,'sawtooth',0.12);},
  heart(){tone(420,140,0.3,'sine',0.14);},
  vent(){tone(250,640,0.28,'sine',0.08);},
  clear(){tone(523,523,0.12,'sine',0.12);tone(659,659,0.12,'sine',0.12,0.12);tone(784,784,0.22,'sine',0.14,0.24);},
  click(){tone(600,600,0.06,'square',0.1);}
};

/* living ember backdrop */
const embers=[];
for(let i=0;i<24;i++)embers.push({x:Math.random()*1200,y:Math.random()*1600,s:1+Math.random()*2.5,v:12+Math.random()*26,o:0.22+Math.random()*0.5});
function makeGlowSprite(hex){const c=document.createElement('canvas');c.width=c.height=96;const x=c.getContext('2d');
  const r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);
  const gr=x.createRadialGradient(48,48,0,48,48,48);
  gr.addColorStop(0,`rgba(${r},${g},${b},0.9)`);gr.addColorStop(0.35,`rgba(${r},${g},${b},0.38)`);gr.addColorStop(1,`rgba(${r},${g},${b},0)`);
  x.fillStyle=gr;x.fillRect(0,0,96,96);return c;}
const EMBER_SPRITE=makeGlowSprite('#ffa53a');
function drawEmbers(){ctx.save();ctx.globalCompositeOperation='lighter';
  for(const e of embers){ctx.globalAlpha=e.o*(0.6+0.4*Math.sin(G.time*3+e.x*0.05));
    const r=e.s*7;ctx.drawImage(EMBER_SPRITE,e.x-r,e.y-r,r*2,r*2);}
  ctx.restore();}
function updateEmbers(dt){for(const e of embers){e.y-=e.v*dt;e.x+=Math.sin((G.time+e.y)*0.02)*0.3;
  if(e.y<-12){e.y=H+12;e.x=Math.random()*W;}}}

/* particles + floaters (pooled, no per-frame DOM) */
const particles=[],floaters=[];
for(let i=0;i<120;i++)particles.push({a:false});
for(let i=0;i<15;i++)floaters.push({a:false});
function spawnP(x,y,vx,vy,life,color,size){const p=particles.find(p=>!p.a);if(!p)return;
  p.a=true;p.x=x;p.y=y;p.vx=vx;p.vy=vy;p.life=life;p.max=life;p.color=color;p.size=size;}
function spawnText(x,y,txt){const f=floaters.find(f=>!f.a);if(!f)return;
  f.a=true;f.x=x;f.y=y;f.txt=txt;f.life=1.1;}

/* physics */
const GRAV=1900,CHG_TIME=0.85,V_MIN=480,V_MAX=1120,AIM_MAX=1.13;
const MAGMA_H=54; // magma band height at screen bottom

const LESSONS=[
  '🔥 Fire Safety: Sizzle\'s spark rule — matches and lighters are tools, not toys. Only grown-ups touch them!',
  '🔥 Fire Safety: If your clothes ever catch fire — STOP, DROP, and ROLL!',
  '🔥 Fire Safety: Sparks fly in games. In real life, stay far away from open flames.',
  '🔥 Fire Safety: Always have a grown-up nearby when anything hot is around.',
  '🔥 Fire Safety: Never play with fire to look cool — real heroes prevent fires!'
];
const LEVEL_NAMES=['Warm-Up Hop','Ember Steps','Crackling Stones','Long Leap','Crumble Alley',
  'Hot Foot Hop','Narrow Escape','Updraft Rise','Vent Voyage','Thin Air','Magma Maze',
  'Spark Sprint','The Gauntlet','Inferno\'s Edge','Trench Champion'];

/* state */
const G={state:'title',mode:'idle',level:1,score:0,best:0,hearts:3,
  px:0,py:0,vx:0,vy:0,on:0,lastSafe:0,charge:0,aim:0,aimBase:0,
  ledges:[],vents:[],time:0,splashT:0,soaked:0,shake:0,chargeSnd:0,
  perfects:0,levelStartScore:0,dragging:false,dragX:0,magmaY:0};
try{G.best=parseInt(localStorage.getItem('sizzle_best')||'0',10)||0;}catch(e){}
resize();

function magmaYNow(){return H-MAGMA_H;}

function buildLevel(n,keepPos){
  const t=(n-1)/14,rng=mulberry32(n*7919+101);
  const jumps=4+Math.round(t*4);            // 4..8 ledges to cross
  const gapBase=120+t*150;                 // horizontal reach per jump
  const ledgeW=Math.round(130-t*58);       // 130..72 px wide
  const crumble=1.7-t*0.75;                // 1.7..0.95 s — always long enough to finish a full charge if you start right away
  const minCX=26+ledgeW/2,maxCX=W-26-ledgeW/2;
  // place a center x for the next ledge: strong zigzag, never stacked
  // vertically above the previous ledge (min 80px horizontal separation)
  function nextCX(pcx,dist){
    let dir=rng()<0.5?-1:1;
    let ncx=pcx+dir*dist;
    if(ncx<minCX||ncx>maxCX){dir=-dir;ncx=pcx+dir*dist;}
    ncx=clamp(ncx,minCX,maxCX);
    if(Math.abs(ncx-pcx)<80){
      // push inward with guaranteed separation — never teleport across
      // the screen (on wide desktop windows a mirror would be unreachable)
      ncx=pcx<W/2?clamp(pcx+120,minCX,maxCX):clamp(pcx-120,minCX,maxCX);
      if(Math.abs(ncx-pcx)<80)ncx=pcx<W/2?maxCX:minCX;
    }
    return ncx;
  }
  G.ledges=[];
  const startW=ledgeW+60;
  let y=H-150;
  const sx=clamp(40+rng()*70,26,W-26-startW);
  G.ledges.push({x:sx,y:y,w:startW,t:0,T:0,state:'solid',goal:false,fallY:0});
  for(let j=0;j<jumps;j++){
    const prev=G.ledges[G.ledges.length-1];
    const pcx=prev.x+prev.w/2;
    // pick the rise first, then cap the horizontal distance by it:
    // dist <= 2*rise+50 keeps the required lob angle gentle (<= ~63 deg)
    // so the success window in (charge, aim) space stays wide and fair
    const rise=(55+t*25)+rng()*30;                       // 55..110 px up
    const maxDist=Math.min(gapBase*1.25,2.0*rise+50);
    const dist=90+rng()*Math.max(30,maxDist-90);
    const ncx=nextCX(pcx,dist);
    let ny=y-rise;
    if(ny<H*0.10)ny=y+(40+rng()*40);       // ran out of headroom: step down instead
    ny=clamp(ny,H*0.10,H-170);
    y=ny;
    G.ledges.push({x:ncx-ledgeW/2,y:ny,w:ledgeW,t:0,T:crumble,state:'solid',goal:false,fallY:0});
  }
  // goal ledge with banner — same anti-stack + fair-angle placement
  const last=G.ledges[G.ledges.length-1],lcx=last.x+last.w/2;
  const gRise=50+rng()*40;
  const gcx=nextCX(lcx,Math.min(gapBase*0.85,2.0*gRise+50));
  let gy=last.y-gRise;
  if(gy<H*0.10)gy=last.y+54;
  gy=clamp(gy,H*0.10,H-170);
  G.ledges.push({x:clamp(gcx-70,26,W-26-140),y:gy,w:140,t:0,T:0,state:'solid',goal:true,fallY:0});
  // updraft vents on levels 8+: helpers over genuinely wide gaps,
  // distinct gaps only, column centered between the two ledge centers
  G.vents=[];
  if(n>=8){
    const wide=[];
    for(let i=0;i<G.ledges.length-1;i++){
      const a=G.ledges[i],b=G.ledges[i+1];
      if(Math.abs((b.x+b.w/2)-(a.x+a.w/2))>=150)wide.push(i);
    }
    const nv=Math.min(2,1+((n-8)>>2),wide.length);
    for(let v=0;v<nv;v++){
      const i=wide[Math.floor(rng()*wide.length)];
      wide.splice(wide.indexOf(i),1);
      const a=G.ledges[i],b=G.ledges[i+1];
      const midX=((a.x+a.w/2)+(b.x+b.w/2))/2;
      G.vents.push({x:clamp(midX-32,20,W-84),w:64,
        y0:Math.min(a.y,b.y)-30,y1:Math.max(a.y,b.y)+10});
    }
  }
  if(!keepPos)placeOnLedge(0);
  updateHUD();
}
function placeOnLedge(i){
  const p=G.ledges[i];
  G.on=i;G.lastSafe=i;G.px=p.x+p.w/2;G.py=p.y-20;G.vx=0;G.vy=0;
  G.mode='idle';G.charge=0;G.aim=0;
  aimAtNext();
}
function aimAtNext(){
  // Kind default aim: search (by simulation, same physics as flight) for
  // the launch angle whose arc — at a friendly mid charge — lands closest
  // to the next ledge's center. The player then mainly tunes the power.
  const cur=G.ledges[G.on];
  const nxt=G.ledges[Math.min(G.on+1,G.ledges.length-1)];
  const sx=cur.x+cur.w/2,sy=cur.y-20,tx=nxt.x+nxt.w/2,ty=nxt.y-20;
  let bestA=clamp(Math.atan2(tx-sx,-(ty-sy)),-AIM_MAX,AIM_MAX),bestErr=1e9;
  const keepCharge=G.charge,keepAim=G.aim;
  for(let a=-AIM_MAX;a<=AIM_MAX;a+=0.04){
    const pts=simArc(sx,sy,a,0.68);
    let err=1e8;
    for(let i=1;i<pts.length;i++){
      const p0=pts[i-1],p1=pts[i];
      if(p1[2]>0&&p0[1]<=ty&&p1[1]>=ty){
        const f=(ty-p0[1])/Math.max(1e-6,p1[1]-p0[1]);
        err=Math.abs((p0[0]+(p1[0]-p0[0])*f)-tx);
        break;
      }
    }
    if(err===1e8&&pts.length){ // never fell through the target plane
      const last=pts[pts.length-1];
      err=Math.abs(last[0]-tx)+Math.abs(last[1]-ty)+400;
    }
    if(err<bestErr){bestErr=err;bestA=a;}
  }
  G.charge=keepCharge;G.aim=keepAim;
  G.aimBase=bestA;G.aim=bestA;
}

/* charging / jumping */
function startCharge(px){
  if(G.state!=='play'||G.mode!=='idle')return;
  G.mode='charge';G.charge=0;G.chargeSnd=0;
  G.dragging=true;G.dragX=px;G.aim=G.aimBase;
}
function dragAim(px){
  if(G.mode!=='charge')return;
  G.aim=clamp(G.aimBase+(px-G.dragX)*0.004,-AIM_MAX,AIM_MAX);
}
function releaseJump(){
  if(G.mode!=='charge')return;
  G.dragging=false;
  const v=V_MIN+G.charge*(V_MAX-V_MIN);
  G.vx=v*Math.sin(G.aim);G.vy=-v*Math.cos(G.aim);
  G.lastSafe=G.on;G.mode='fly';sfx.release();
  for(let i=0;i<8;i++)spawnP(G.px,G.py+18,(Math.random()-0.5)*160,Math.random()*120,0.35,'#ffd23f',4);
}
function jumpVel(){const v=V_MIN+G.charge*(V_MAX-V_MIN);return[v*Math.sin(G.aim),-v*Math.cos(G.aim)];}
function inVent(x,y){for(const v of G.vents){
  if(x>v.x&&x<v.x+v.w&&y>v.y0&&y<v.y1)return true;}return false;}
/* single source of flight physics — used by BOTH the real update and
   the trajectory preview, so the preview can never lie */
function stepFlight(s,dt){
  s.vy+=GRAV*dt;
  if(inVent(s.x,s.y)){s.vy-=2600*dt;s.vy=Math.max(s.vy,-560);}
  s.x+=s.vx*dt;s.y+=s.vy*dt;
  if(s.x<24){s.x=24;s.vx=Math.abs(s.vx)*0.5;}
  if(s.x>W-24){s.x=W-24;s.vx=-Math.abs(s.vx)*0.5;}
}
function simArc(x,y,aim,charge){
  const v=V_MIN+charge*(V_MAX-V_MIN);
  const s={x:x,y:y,vx:v*Math.sin(aim),vy:-v*Math.cos(aim)};
  const pts=[[s.x,s.y,s.vy]],dt=1/30;
  for(let i=0;i<46;i++){
    stepFlight(s,dt);
    pts.push([s.x,s.y,s.vy]);
    if(s.y>magmaYNow())break;
  }
  return pts;
}
function simTrajectory(){
  const all=simArc(G.px,G.py,G.aim,G.charge),pts=[];
  for(let i=0;i<all.length;i+=3)pts.push([all[i][0],all[i][1]]);
  return pts;
}

/* landing / missing */
function landOn(i){
  const p=G.ledges[i];
  G.on=i;G.px=clamp(G.px,p.x-8,p.x+p.w+8);G.py=p.y-20;G.vx=0;G.vy=0;
  G.mode='idle';G.charge=0;
  if(p.goal){levelClear();return;}
  const isNew=i>G.lastSafe;
  G.lastSafe=i;
  if(p.state==='solid'&&p.T>0){p.state='crumbling';p.t=p.T;sfx.crumble();}
  if(isNew){
    const off=Math.abs(G.px-(p.x+p.w/2))/(p.w/2);
    if(off<0.36){G.score+=150;G.perfects++;sfx.perfect();spawnText(G.px,p.y-46,'PERFECT +150');}
    else if(off<0.7){G.score+=50;sfx.land();spawnText(G.px,p.y-46,'+50');}
    else{G.score+=25;sfx.land();spawnText(G.px,p.y-46,'+25');}
    updateHUD();
  }else{sfx.land();}
  aimAtNext();
}
function miss(){
  if(G.mode==='splash')return;
  G.mode='splash';G.splashT=1.15;G.shake=0.35;
  G.hearts--;sfx.splash();sfx.heart();updateHUD();
  for(let i=0;i<22;i++)spawnP(G.px,magmaYNow(),(Math.random()-0.5)*420,-Math.random()*520,0.7,
    ['#ff6a00','#ffd23f','#ff3b1f','#fff'][i%4],3+Math.random()*4);
}
function respawn(){
  if(G.hearts<=0){gameOver();return;}
  G.soaked=2.2;placeOnLedge(G.lastSafe);G.mode='idle';
  for(let i=0;i<10;i++)spawnP(G.px,G.py,(Math.random()-0.5)*120,-Math.random()*160,0.5,'#7fd4ff',3);
}

/* level flow */
function levelClear(){
  G.state='clear';
  const bonus=G.hearts*50;G.score+=bonus;
  if(G.level<15&&G.hearts<3)G.hearts++;
  if(G.score>G.best){G.best=G.score;try{localStorage.setItem('sizzle_best',String(G.best));}catch(e){}}
  updateHUD();sfx.clear();
  for(let i=0;i<26;i++)spawnP(G.px+(Math.random()-0.5)*120,G.py-40,(Math.random()-0.5)*260,-Math.random()*300,0.9,
    ['#ffd23f','#ff9a3a','#fff','#c4a0ff'][i%4],4);
  const last=G.level>=15;
  setTimeout(()=>{
    showOverlay(last?'🏆 TRENCH CHAMPION!':'⚡ LEVEL '+G.level+' CLEAR!',
      `<p><b>${LEVEL_NAMES[G.level-1]}</b> — done!</p>`+
      `<p style="font-size:22px;font-weight:900">Score: ${G.score}</p>`+
      `<p>Perfect landings: ${G.perfects} · Heart bonus: +${bonus}</p>`+
      (last?`<p>Best: ${G.best}</p><p>You leapt all 15 levels of the magma trench!</p>`:`<p>Next: <b>${LEVEL_NAMES[G.level]}</b></p>`),
      LESSONS[(G.level-1)%LESSONS.length],
      last?'↻ PLAY AGAIN':'NEXT ▶',()=>{
        if(last){resetAll();}
        else{G.level++;G.levelStartScore=G.score;G.perfects=0;buildLevel(G.level);G.state='play';}
      });
  },700);
}
function gameOver(){
  G.state='over';
  if(G.score>G.best){G.best=G.score;try{localStorage.setItem('sizzle_best',String(G.best));}catch(e){}}
  setTimeout(()=>{
    showOverlay('💦 OUT OF HEARTS',
      `<p style="font-size:22px;font-weight:900">Score: ${G.score}</p><p>Level ${G.level} of 15 — ${LEVEL_NAMES[G.level-1]}</p><p>Best: ${G.best}</p>`,
      LESSONS[(G.level-1)%LESSONS.length],
      '↻ RETRY LEVEL',()=>{retryLevel();});
  },500);
}
function retryLevel(){
  G.score=G.levelStartScore;G.hearts=3;G.perfects=0;
  buildLevel(G.level);G.state='play';
}
function reset(){
  // restart current level (pause-menu contract)
  G.score=G.levelStartScore;G.hearts=3;G.perfects=0;
  buildLevel(G.level);G.state='play';updateHUD();
}
function resetAll(){
  G.level=1;G.score=0;G.hearts=3;G.perfects=0;G.levelStartScore=0;
  buildLevel(1);G.state='play';updateHUD();
}

/* update */
function update(dt){
  G.time+=dt;
  G.magmaY=magmaYNow();
  // crumbling ledges
  for(let i=0;i<G.ledges.length;i++){
    const p=G.ledges[i];
    if(p.state==='crumbling'){
      p.t-=dt;
      if(p.t<=0){p.state='gone';p.fallY=0;
        if(G.on===i&&(G.mode==='idle'||G.mode==='charge')){miss();}
      }
    }else if(p.state==='gone'){
      p.fallY+=560*dt;
    }
  }
  if(G.mode==='charge'){
    G.charge=Math.min(1,G.charge+dt/CHG_TIME);
    G.chargeSnd+=dt;
    if(G.chargeSnd>0.12){G.chargeSnd=0;sfx.chargeTick(G.charge);}
    if(G.keyL)G.aim=clamp(G.aim-1.7*dt,-AIM_MAX,AIM_MAX);
    if(G.keyR)G.aim=clamp(G.aim+1.7*dt,-AIM_MAX,AIM_MAX);
    if(Math.random()<0.6)spawnP(G.px+(Math.random()-0.5)*24,G.py+16,(Math.random()-0.5)*60,-Math.random()*90,0.3,'#ffd23f',3);
  }else if(G.mode==='fly'){
    const prevFeet=G.py+20;
    const wasVent=inVent(G.px,G.py);
    const s={x:G.px,y:G.py,vx:G.vx,vy:G.vy};
    stepFlight(s,dt);
    G.px=s.x;G.py=s.y;G.vx=s.vx;G.vy=s.vy;
    if(wasVent){
      if(Math.random()<0.7)spawnP(G.px+(Math.random()-0.5)*30,G.py+20,(Math.random()-0.5)*60,-Math.random()*220,0.5,'#bfe9ff',3);
      if(!update._ventSnd||G.time-update._ventSnd>0.5){update._ventSnd=G.time;sfx.vent();}
    }
    // landing check (falling only, solid/crumbling ledges)
    if(G.vy>0){
      const feet=G.py+20;
      for(let i=0;i<G.ledges.length;i++){
        const p=G.ledges[i];
        if(p.state==='gone')continue;
        if(G.px>p.x-10&&G.px<p.x+p.w+10&&prevFeet<=p.y+6&&feet>=p.y-2){
          landOn(i);break;
        }
      }
    }
    // magma = miss (never harm: he pops back out soaked and laughing)
    if(G.mode==='fly'&&G.py+20>=G.magmaY)miss();
  }else if(G.mode==='splash'){
    G.splashT-=dt;
    if(G.splashT<=0)respawn();
  }
  if(G.soaked>0)G.soaked-=dt;
  if(G.shake>0)G.shake-=dt;
  updateHUDLive();
}

/* HUD */
