/* input */
canvas.addEventListener('pointerdown',e=>{e.preventDefault();startCharge(e.clientX);});
canvas.addEventListener('pointermove',e=>{dragAim(e.clientX);});
canvas.addEventListener('pointerup',e=>{e.preventDefault();releaseJump();});
canvas.addEventListener('pointercancel',()=>{releaseJump();});
