document.getElementById('prestartBtn').onclick=()=>{_pz.classList.add('hidden');reset();};

/* ============ render ============ */
function drawBG(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#160a12');bg.addColorStop(0.55,'#241016');bg.addColorStop(1,'#3a1408');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  // distant volcano glow
  const vg=ctx.createRadialGradient(W/2,H*0.16,10,W/2,H*0.16,W*0.5);
  vg.addColorStop(0,'rgba(255,90,20,0.20)');vg.addColorStop(1,'rgba(255,90,20,0)');
  ctx.fillStyle=vg;ctx.fillRect(0,0,W,H);
  // cavern walls
  ctx.fillStyle='#1c0f0a';
  ctx.beginPath();ctx.moveTo(0,0);
  for(let y=0;y<=H;y+=60)ctx.lineTo(14+Math.sin(y*0.02+G.time*0.2)*8,y);
  ctx.lineTo(0,H);ctx.closePath();ctx.fill();
  ctx.beginPath();ctx.moveTo(W,0);
  for(let y=0;y<=H;y+=60)ctx.lineTo(W-14-Math.sin(y*0.023+G.time*0.17)*8,y);
  ctx.lineTo(W,H);ctx.closePath();ctx.fill();
  drawEmbers();
}
function drawMagma(){
  const my=magmaYNow();
  const g=ctx.createLinearGradient(0,my,0,H);
  g.addColorStop(0,'#ffd23f');g.addColorStop(0.25,'#ff7a1f');g.addColorStop(0.6,'#d63a12');g.addColorStop(1,'#7a1c05');
  ctx.fillStyle=g;ctx.fillRect(0,my,W,H-my);
  // animated surface blobs
  ctx.save();ctx.globalCompositeOperation='lighter';
  for(let i=0;i<14;i++){
    const bx=(i*97+Math.sin(G.time*1.7+i*2.1)*22)%W;
    const br=10+6*Math.sin(G.time*2.3+i*1.3);
    ctx.globalAlpha=0.5;ctx.fillStyle='#ffe9a0';
    ctx.beginPath();ctx.arc((bx+W)%W,my+6+4*Math.sin(G.time*3+i),Math.max(2,br*0.6),0,Math.PI*2);ctx.fill();
  }
  ctx.restore();ctx.globalAlpha=1;
  ctx.fillStyle='rgba(255,210,63,0.85)';
  for(let i=0;i<W;i+=26){
    const wy=my+3*Math.sin(i*0.11+G.time*4);
    ctx.fillRect(i,wy,22,3);
  }
}
function drawLedge(p){
  const fall=p.state==='gone'?p.fallY:0;
  const y=p.y+fall;
  if(y<-40||y>H+40)return;
  ctx.save();
  if(p.state==='crumbling'){
    const frac=p.t/p.T;
    ctx.translate((Math.random()-0.5)*(1-frac)*6,0);
    if(frac<0.45)ctx.globalAlpha=0.55+frac;
  }
  if(p.state==='gone')ctx.globalAlpha=Math.max(0,1-fall/160);
  // rock platform
  const g=ctx.createLinearGradient(0,y-14,0,y+10);
  if(p.goal){g.addColorStop(0,'#3f7a3a');g.addColorStop(1,'#1e4a1e');}
  else{g.addColorStop(0,'#5a4a3a');g.addColorStop(0.35,'#3d2f22');g.addColorStop(1,'#241a12');}
  ctx.fillStyle=g;
  ctx.beginPath();ctx.roundRect(p.x,y-14,p.w,24,8);ctx.fill();
  ctx.strokeStyle=p.goal?'#7fd47f':'rgba(255,150,60,0.5)';ctx.lineWidth=2;ctx.stroke();
  // top moss/ember edge
  ctx.fillStyle=p.goal?'#8fe08f':'#ff9a3a';
  ctx.fillRect(p.x+4,y-16,p.w-8,4);
  // cracks when crumbling
  if(p.state==='crumbling'&&p.t/p.T<0.55){
    ctx.strokeStyle='rgba(0,0,0,0.7)';ctx.lineWidth=2;
    ctx.beginPath();
    ctx.moveTo(p.x+p.w*0.3,y-12);ctx.lineTo(p.x+p.w*0.38,y+8);
    ctx.moveTo(p.x+p.w*0.65,y-12);ctx.lineTo(p.x+p.w*0.58,y+8);
    ctx.stroke();
  }
  // goal banner
  if(p.goal){
    ctx.strokeStyle='#caa46a';ctx.lineWidth=5;
    ctx.beginPath();ctx.moveTo(p.x+p.w/2-34,y-14);ctx.lineTo(p.x+p.w/2-34,y-64);
    ctx.moveTo(p.x+p.w/2+34,y-14);ctx.lineTo(p.x+p.w/2+34,y-64);ctx.stroke();
    const wave=Math.sin(G.time*5)*4;
    ctx.fillStyle='#fff';
    for(let i=0;i<4;i++)ctx.fillRect(p.x+p.w/2-34+i*17,y-64+((i%2)?wave:-wave),17,12);
    ctx.fillStyle='#111';
    for(let i=0;i<4;i++)ctx.fillRect(p.x+p.w/2-34+((i+1)%2)*17,y-64+(((i+1)%2)?wave:-wave),17,12);
    ctx.font='900 20px system-ui';ctx.textAlign='center';ctx.fillStyle='#ffd23f';
    ctx.fillText('🏁 GOAL',p.x+p.w/2,y-72);ctx.textAlign='left';
  }
  ctx.restore();
}
function drawVent(v){
  ctx.save();
  const g=ctx.createLinearGradient(0,v.y0,0,v.y1);
  g.addColorStop(0,'rgba(160,220,255,0)');g.addColorStop(0.5,'rgba(160,220,255,0.20)');g.addColorStop(1,'rgba(160,220,255,0)');
  ctx.fillStyle=g;ctx.fillRect(v.x,v.y0,v.w,v.y1-v.y0);
  ctx.fillStyle='rgba(200,235,255,0.75)';
  for(let i=0;i<5;i++){
    const yy=v.y1-((G.time*160+i*47)%(v.y1-v.y0));
    const xx=v.x+v.w/2+Math.sin(G.time*3+i*1.7)*14;
    ctx.beginPath();ctx.moveTo(xx,yy-9);ctx.lineTo(xx-7,yy+2);ctx.lineTo(xx+7,yy+2);ctx.closePath();ctx.fill();
  }
  ctx.restore();
}
/* Sizzle — round flame-teardrop Fire Baby, archer showoff energy.
   NO beaks/wings/feathers. Kid-safe. */
function drawSizzle(x,y){
  ctx.save();
  let sx=0,sy=0;
  if(G.shake>0){sx=(Math.random()-0.5)*10*G.shake/0.35;sy=(Math.random()-0.5)*10*G.shake/0.35;}
  ctx.translate(x+sx,y+sy);
  const charging=G.mode==='charge';
  const sq=charging?G.charge*0.14:0;
  ctx.scale(1+sq+(G.mode==='idle'?Math.sin(G.time*6)*0.02:0),1-sq);
  // power glow while charging
  if(charging){
    ctx.save();ctx.globalCompositeOperation='lighter';
    const r=30+G.charge*26;
    ctx.globalAlpha=0.25+G.charge*0.4;
    ctx.drawImage(EMBER_SPRITE,-r,-r-6,r*2,r*2);
    ctx.restore();
  }
  ctx.shadowColor='#ff7a2a';ctx.shadowBlur=18;
  // flame-teardrop body
  const g=ctx.createRadialGradient(-7,-8,4,0,6,26);
  g.addColorStop(0,'#ffe9a0');g.addColorStop(0.5,'#ff9a3a');g.addColorStop(1,'#e8352c');
  ctx.fillStyle=g;
  ctx.beginPath();
  ctx.moveTo(0,-38);
  ctx.bezierCurveTo(10,-26,20,-14,20,8);
  ctx.arc(0,8,20,Math.PI/2*0.32,Math.PI*2-Math.PI/2*0.32,true);
  ctx.bezierCurveTo(-20,-14,-10,-26,0,-38);
  ctx.closePath();ctx.fill();
  ctx.shadowBlur=0;
  // little wooden bow (archer showoff) — left side
  ctx.strokeStyle='#8a5a2a';ctx.lineWidth=4;ctx.lineCap='round';
  ctx.beginPath();ctx.arc(-26,2,16,-1.1,1.1);ctx.stroke();
  ctx.strokeStyle='rgba(255,255,255,0.75)';ctx.lineWidth=1.5;
  ctx.beginPath();ctx.moveTo(-26+16*Math.cos(-1.1),2+16*Math.sin(-1.1));
  ctx.lineTo(-26+16*Math.cos(1.1),2+16*Math.sin(1.1));ctx.stroke();
  // spark arrow grows while charging
  if(charging){
    const a=G.aim,ax=Math.sin(a),ay=-Math.cos(a);
    const len=26+G.charge*34;
    ctx.strokeStyle='#ffd23f';ctx.lineWidth=3;
    ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(ax*len,ay*len);ctx.stroke();
    ctx.fillStyle='#fff';
    ctx.beginPath();ctx.arc(ax*len,ay*len,3+G.charge*3,0,Math.PI*2);ctx.fill();
  }
  // face — confident showoff
  const soaked=G.soaked>0;
  ctx.strokeStyle='#2b1a0e';ctx.fillStyle='#2b1a0e';ctx.lineWidth=2.5;ctx.lineCap='round';
  // angled showoff brows
  ctx.beginPath();
  ctx.moveTo(-12,-12);ctx.lineTo(-3,-8);
  ctx.moveTo(12,-12);ctx.lineTo(3,-8);
  ctx.stroke();
  // glaring eyes, red-hot pupils
  ctx.beginPath();ctx.arc(-6,-4,4,0,Math.PI*2);ctx.arc(6,-4,4,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#ff2a1a';
  ctx.beginPath();ctx.arc(-6,-4,1.8,0,Math.PI*2);ctx.arc(6,-4,1.8,0,Math.PI*2);ctx.fill();
  // mouth
  ctx.strokeStyle='#2b1a0e';ctx.lineWidth=2.5;
  ctx.beginPath();
  if(soaked){ // laughing it off
    ctx.fillStyle='#5a2317';
    ctx.ellipse(1,8,6,7,0,0,Math.PI*2);ctx.fill();
  }else if(charging){
    ctx.arc(2,6,6,0.3,Math.PI-0.6);ctx.stroke(); // gritted showoff grin
  }else{
    ctx.arc(3,5,7,-0.2,Math.PI-0.9);ctx.stroke(); // smirk
  }
  // soaked drips
  if(soaked){
    ctx.fillStyle='rgba(127,212,255,0.9)';
    for(let i=0;i<4;i++){
      const dx=-14+i*9,dy=14+((G.time*90+i*23)%14);
      ctx.beginPath();ctx.arc(dx,dy,2.6,0,Math.PI*2);ctx.fill();
    }
  }
  ctx.restore();
}
function drawTrajectory(){
  if(G.mode!=='charge')return;
  const pts=simTrajectory();
  ctx.save();
  for(let i=0;i<pts.length;i++){
    const heat=i/Math.max(1,pts.length-1);
    ctx.fillStyle=heat<0.5?'#7dff8a':(heat<0.8?'#ffd23f':'#ff6a3a');
    ctx.globalAlpha=0.9-heat*0.35;
    ctx.beginPath();ctx.arc(pts[i][0],pts[i][1],4.5,0,Math.PI*2);ctx.fill();
  }
  ctx.restore();ctx.globalAlpha=1;
}
function drawPowerBar(){
  if(G.mode!=='charge')return;
  const bw=Math.min(200,W*0.5),bx=W/2-bw/2,by=H-96;
  ctx.save();
  ctx.fillStyle='rgba(0,0,0,0.55)';
  ctx.beginPath();ctx.roundRect(bx-4,by-4,bw+8,20,10);ctx.fill();
  const g=ctx.createLinearGradient(bx,0,bx+bw,0);
  g.addColorStop(0,'#7dff8a');g.addColorStop(0.6,'#ffd23f');g.addColorStop(1,'#ff6a3a');
  ctx.fillStyle=g;
  ctx.beginPath();ctx.roundRect(bx,by,bw*G.charge,12,6);ctx.fill();
  ctx.fillStyle='#fff';ctx.font='900 13px system-ui';ctx.textAlign='center';
  ctx.fillText('SPARK POWER',W/2,by-10);ctx.textAlign='left';
  ctx.restore();
}
function drawHint(){
  if(G.level!==1||G.mode!=='idle'||G.time>14)return;
  ctx.save();ctx.globalAlpha=0.75+0.25*Math.sin(G.time*4);
  ctx.fillStyle='#fff';ctx.font='800 15px system-ui';ctx.textAlign='center';
  ctx.fillText('HOLD to charge — aim ← → — RELEASE to leap!',W/2,H-130);
  ctx.textAlign='left';ctx.restore();
}
function render(){
  ctx.save();
  if(G.shake>0)ctx.translate((Math.random()-0.5)*8,(Math.random()-0.5)*8);
  drawBG();
  for(const v of G.vents)drawVent(v);
  for(const p of G.ledges)drawLedge(p);
  drawMagma();
  drawTrajectory();
  if(G.mode!=='splash')drawSizzle(G.px,G.py);
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  // floaters
  ctx.textAlign='center';
  for(const f of floaters){
    if(!f.a)continue;
    ctx.globalAlpha=Math.min(1,f.life);
    ctx.font='900 18px system-ui';ctx.fillStyle='#000';
    ctx.fillText(f.txt,f.x+2,f.y+2);ctx.fillStyle='#ffd23f';ctx.fillText(f.txt,f.x,f.y);
  }
  ctx.globalAlpha=1;ctx.textAlign='left';
  drawPowerBar();
  drawHint();
  ctx.restore();
}

/* loop */
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(G.state==='play')update(dt);else G.time+=dt;
  updateEmbers(dt);
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=300*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  for(const f of floaters){if(!f.a)continue;f.y-=40*dt;f.life-=dt;if(f.life<=0)f.a=false;}
  render();
  requestAnimationFrame(loop);
}
document.getElementById('best').textContent='🏆 '+G.best;
buildLevel(1);
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Charge & Leap' — Sizzle's Spark Jump's
   own track. Synthesized Web Audio only. 104 BPM, A major: plucky square lead
   with rests to think in (it's a precision game), soft triangle bass pulses,
   sparse drums and a sparkle shimmer on the high notes.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-08-sizzles-spark-jump.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
const MUS={on:false,step:0,nextT:0,BPM:104,
 BASS:[45,0,0,45,0,0,45,0, 40,0,0,40,0,0,40,0, 42,0,0,42,0,0,42,0, 38,0,0,38,0,0,45,0],
 LEAD:[69,0,73,0,0,76,0,0, 81,0,0,76,73,0,0,0, 78,0,81,0,0,85,0,81, 0,76,0,73,0,69,0,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(MUTED||G.state!=='play'){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.22,'triangle',0.06,d);
  const l=this.LEAD[s];if(l){tone(_mf(l),_mf(l),0.16,'square',0.05,d);
   if(l>=78)tone(_mf(l)*2,_mf(l)*2,0.1,'sine',0.014,d);} // sparkle on high notes
  if(s%8===0)tone(115,45,0.12,'sine',0.12,d); // soft kick, once a bar
  if(s%8===4)noise(0.06,0.05,d,1800); // gentle snare
  if(s%4===2)noise(0.02,0.015,d,6500); // sparse hat
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

