scripts:
'use strict';
/* ============================================================
   EMBER CASCADE v3 — full redo (Jeff's order, games 6–11 pass)
   Falling-ember cascade puzzle:
   - Tap a connected group of 2+ same-color orbs to pop them.
   - Orbs fall, columns slide, chain cascades multiply points.
   - 12 levels: grid grows, colors 4→5→6, obsidian blockers,
     Fire Baby face orbs that clear their row as a treat.
   ============================================================ */
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);layout();}
addEventListener('resize',resize);

/* audio */
let AC=null,MUTED=false;try{MUTED=localStorage.getItem('fb_muted')==='1';}catch(e){}
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
function noise(dur,vol,delay=0,lp=1500){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const len=ac.sampleRate*dur,buf=ac.createBuffer(1,len,ac.sampleRate),d=buf.getChannelData(0);
  for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);
  const s=ac.createBufferSource();s.buffer=buf;const f=ac.createBiquadFilter();f.type='lowpass';f.frequency.value=lp;
  const g=ac.createGain();g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  s.connect(f);f.connect(g);g.connect(ac.destination);s.start(t);}
const sfx={
  pop(n){tone(480+Math.min(n,10)*45,900+Math.min(n,10)*60,0.12,'triangle',0.16);noise(0.08,0.12,0,2400);},
  chain(k){const base=560+k*90;[0,1,2].forEach(i=>tone(base+i*130,base+i*130+220,0.13,'triangle',0.15,i*0.05));},
  face(){[660,880,990,1320].forEach((f,i)=>tone(f,f,0.14,'sine',0.14,i*0.06));},
  crack(){noise(0.16,0.22,0,900);tone(160,60,0.14,'sawtooth',0.1);},
  bad(){tone(210,150,0.12,'square',0.07);},
  click(){tone(600,600,0.06,'square',0.1);},
  win(){[523,659,784,1047].forEach((f,i)=>tone(f,f,0.25,'triangle',0.18,i*0.1));},
  lose(){[392,330,262].forEach((f,i)=>tone(f,f,0.22,'triangle',0.14,i*0.12));}
};

/* living ember backdrop */
const embers=[];
for(let i=0;i<24;i++)embers.push({x:Math.random()*Math.max(W||400,300),y:Math.random()*Math.max(H||700,300),s:1+Math.random()*2.5,v:12+Math.random()*26,o:0.22+Math.random()*0.5});
function makeGlowSprite(hex){const c=document.createElement('canvas');c.width=c.height=96;const x=c.getContext('2d');
  const r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);
  const gr=x.createRadialGradient(48,48,0,48,48,48);
  gr.addColorStop(0,`rgba(${r},${g},${b},0.9)`);gr.addColorStop(0.35,`rgba(${r},${g},${b},0.38)`);gr.addColorStop(1,`rgba(${r},${g},${b},0)`);
  x.fillStyle=gr;x.fillRect(0,0,96,96);return c;}
const EMBER_SPRITE=makeGlowSprite('#ffa53a');
function drawEmbers(){ctx.save();ctx.globalCompositeOperation='lighter';
  for(const e of embers){ctx.globalAlpha=e.o*(0.6+0.4*Math.sin(G.time*3+e.x*0.05));
    const r=e.s*7;ctx.drawImage(EMBER_SPRITE,e.x-r,e.y-r,r*2,r*2);}
  ctx.restore();}
function updateEmbers(dt){for(const e of embers){e.y-=e.v*dt;e.x+=Math.sin((G.time+e.y)*0.02)*0.3;
  if(e.y<-12){e.y=H+12;e.x=Math.random()*W;}}}

/* particles + floaters (pooled, same pattern as before) */
const particles=[],floaters=[];
for(let i=0;i<220;i++)particles.push({a:false});
for(let i=0;i<24;i++)floaters.push({a:false});
function spawnP(x,y,vx,vy,life,color,size){const p=particles.find(p=>!p.a);if(!p)return;
  p.a=true;p.x=x;p.y=y;p.vx=vx;p.vy=vy;p.life=life;p.max=life;p.color=color;p.size=size;}
function spawnText(x,y,txt,color='#ffd23f',size){const f=floaters.find(f=>!f.a);if(!f)return;
  f.a=true;f.x=x;f.y=y;f.txt=txt;f.color=color;f.life=1.3;f.size=size||20;}
function burst(x,y,color,n,pow){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,sp=(0.3+Math.random()*0.7)*pow;
  spawnP(x,y,Math.cos(a)*sp,Math.sin(a)*sp-40,0.45+Math.random()*0.3,color,2.5+Math.random()*2.5);}}

/* orb palette — flame colors + cool teal + violet (spec order) */
const PALETTE=[
  {id:0,name:'orange', body:'#ff7a1a',deep:'#c2430a',glow:'#ffa53a',ink:'#4a1c02'},
  {id:1,name:'gold',   body:'#ffc21f',deep:'#c78d06',glow:'#ffe066',ink:'#4a3200'},
  {id:2,name:'red',    body:'#ff4040',deep:'#b01e1e',glow:'#ff7a5c',ink:'#4a0d0d'},
  {id:3,name:'teal',   body:'#17c3b2',deep:'#0a7a70',glow:'#5ee8d8',ink:'#063a35'},
  {id:4,name:'violet', body:'#9b5de5',deep:'#5f2ea6',glow:'#c99aff',ink:'#2a0d4a'}
];
const OBS=-1; // obsidian blocker cell value

/* levels: cols x rows, colors in play, move budget, score target, blockers */
const LEVELS=[
  {cols:6,rows:7, colors:4,moves:18,target:700, obs:0},
  {cols:6,rows:7, colors:4,moves:18,target:850, obs:0},
  {cols:7,rows:7, colors:4,moves:19,target:1050,obs:0},
  {cols:7,rows:8, colors:4,moves:20,target:1250,obs:0},
  {cols:7,rows:8, colors:5,moves:20,target:1400,obs:0},
  {cols:8,rows:8, colors:5,moves:21,target:1650,obs:0},
  {cols:8,rows:9, colors:5,moves:21,target:1900,obs:3},
  {cols:8,rows:9, colors:5,moves:22,target:2150,obs:4},
  {cols:9,rows:9, colors:5,moves:22,target:2450,obs:5},
  {cols:9,rows:10,colors:5,moves:23,target:2750,obs:6},
  {cols:9,rows:10,colors:5,moves:23,target:3100,obs:7},
  {cols:10,rows:10,colors:5,moves:24,target:3500,obs:8}
];
const FACE_CHANCE=0.045; // share of fresh orbs that carry a happy Fire Baby face

/* state */
const G={state:'title',paused:false,time:0,
  level:1,score:0,moves:0,target:0,stars:0,
  cols:6,rows:7,board:[],face:null,animating:false,
  scoresQueue:[],phase:'idle',phaseT:0,chainK:0,lastGain:0,totalLevels:LEVELS.length};
const geo={x0:0,y0:0,cell:40};
const falling=[]; // visual-only falling orbs
let popSet=new Set(),popT=0,chainBannerT=0,glowSet=new Set(),glowPulse=0;
function cellCX(c){return geo.x0+(c+0.5)*geo.cell;}
function cellCY(r){return geo.y0+(r+0.5)*geo.cell;}
function layout(){
  const L=LEVELS[Math.min(G.level,LEVELS.length)-1];
  const bw=Math.min(W*0.94,430),bh=Math.min(H*0.70,600);
  geo.cell=Math.max(24,Math.floor(Math.min(bw/L.cols,bh/L.rows)));
  const gw=geo.cell*L.cols,gh=geo.cell*L.rows;
  geo.x0=Math.round((W-gw)/2);geo.y0=Math.round(Math.max(64,(H-gh)/2-6));
}
function idx(c,r){return r*G.cols+c;}
function cellAt(c,r){if(c<0||r<0||c>=G.cols||r>=G.rows)return null;return G.board[idx(c,r)];}
function newOrb(colors){return {v:Math.floor(Math.random()*colors),face:Math.random()<FACE_CHANCE,pop:0};}
function fillBoard(){
  const L=LEVELS[G.level-1];
  G.cols=L.cols;G.rows=L.rows;G.board=[];
  for(let r=0;r<G.rows;r++)for(let c=0;c<G.cols;c++)G.board.push(newOrb(L.colors));
  // sprinkle obsidian blockers in the lower-middle of the board
  let placed=0,guard=0;
  while(placed<L.obs&&guard++<300){
    const c=1+Math.floor(Math.random()*(G.cols-2));
    const r=Math.floor(G.rows*0.45)+Math.floor(Math.random()*(G.rows-Math.floor(G.rows*0.45)));
    const i=idx(c,r);
    if(G.board[i].v!==OBS){G.board[i]={v:OBS,face:false,pop:0};placed++;}
  }
}
function flood(c,r,val,seen){
  const stack=[[c,r]];seen.add(idx(c,r));const out=[];
  while(stack.length){
    const cur=stack.pop();out.push(cur);
    const dirs=[[1,0],[-1,0],[0,1],[0,-1]];
    for(const d of dirs){
      const nc=cur[0]+d[0],nr=cur[1]+d[1];
      if(nc<0||nr<0||nc>=G.cols||nr>=G.rows)continue;
      const i=idx(nc,nr);
      if(seen.has(i))continue;
      const cell=G.board[i];
      if(cell&&cell.v===val){seen.add(i);stack.push([nc,nr]);}
    }
  }
  return out;
}
function groupAt(c,r){
  const cell=cellAt(c,r);
  if(!cell||cell.v===OBS)return null;
  const seen=new Set(),cells=flood(c,r,cell.v,seen);
  return {val:cell.v,cells};
}
function findAutoGroup(minSize){
  const seen=new Set();
  for(let r=0;r<G.rows;r++)for(let c=0;c<G.cols;c++){
    const i=idx(c,r),cell=G.board[i];
    if(!cell||cell.v===OBS||seen.has(i))continue;
    const cells=flood(c,r,cell.v,seen);
    if(cells.length>=minSize)return cells;
  }
  return null;
}
function findAnyGroup(){return findAutoGroup(2);}
function rowFaceCell(cells){
  for(const cr of cells){const cell=G.board[idx(cr[0],cr[1])];if(cell&&cell.face)return cr;}
  return null;
}
function popScore(n,k){
  let s=0;
  const mult=Math.min(k,5); // chain multiplier caps at x5 — keeps cascades big but bounded
  if(k===1)s=n*10+(n>=3?(n-2)*(n-2)*5:0);
  else if(n<3)s=0;
  else s=(n*10+(n-2)*(n-2)*5)*mult;
  return s;
}
function collectPops(cells,addRow){
  const set=new Set();
  for(const cr of cells)set.add(idx(cr[0],cr[1]));
  if(addRow!==null&&addRow!==undefined){
    for(let c=0;c<G.cols;c++){
      const cell=G.board[idx(c,addRow)];
      if(cell&&cell.v!==OBS)set.add(idx(c,addRow));
    }
  }
  return set;
}
function adjacentObsidian(set){
  const out=new Set();
  for(const i of set){
    const c=i%G.cols,r=(i/G.cols)|0;
    const dirs=[[1,0],[-1,0],[0,1],[0,-1]];
    for(const d of dirs){
      const nc=c+d[0],nr=r+d[1];
      if(nc<0||nr<0||nc>=G.cols||nr>=G.rows)continue;
      const cell=G.board[idx(nc,nr)];
      if(cell&&cell.v===OBS)out.add(idx(nc,nr));
    }
  }
  return out;
}
function applyGravity(){
  for(let c=0;c<G.cols;c++){
    let write=G.rows-1;
    for(let r=G.rows-1;r>=0;r--){
      const cell=G.board[idx(c,r)];
      if(cell&&cell.v===OBS){write=r-1;continue;}
      if(cell){if(write!==r){G.board[idx(c,write)]=cell;G.board[idx(c,r)]=null;}write--;}
    }
    for(let r=write;r>=0;r--)G.board[idx(c,r)]=null;
  }
  // columns slide together: wholly empty columns shift right, orbs slide left
  let wc=0;
  for(let c=0;c<G.cols;c++){
    let empty=true;
    for(let r=0;r<G.rows;r++)if(G.board[idx(c,r)]){empty=false;break;}
    if(!empty){
      if(wc!==c)for(let r=0;r<G.rows;r++){G.board[idx(wc,r)]=G.board[idx(c,r)];G.board[idx(c,r)]=null;}
      wc++;
    }
  }
}
function refill(){
  const L=LEVELS[G.level-1];
  for(let c=0;c<G.cols;c++){
    let segStart=0;
    for(let r=0;r<=G.rows;r++){
      const atObs=r<G.rows&&G.board[idx(c,r)]&&G.board[idx(c,r)].v===OBS;
      if(r===G.rows||atObs){
        // segment [segStart, r-1]: after gravity its gaps sit at the top
        let n=0;for(let rr=segStart;rr<r;rr++)if(!G.board[idx(c,rr)])n++;
        let k=0;
        for(let rr=segStart;rr<r;rr++){
          if(!G.board[idx(c,rr)]){
            const orb=newOrb(L.colors);G.board[idx(c,rr)]=orb;k++;
            falling.push({c,r:rr,v:orb.v,face:orb.face,dy:-(n-k+1)*geo.cell,t:0});
          }
        }
        segStart=r+1;
      }
    }
  }
}
function settle(){applyGravity();refill();}

/* turn resolution — state machine inside resolveStep */
function updateHUD(){
  document.getElementById('fire').textContent='⭐ '+G.score;
  document.getElementById('wave').textContent=`🧩 Level ${Math.min(G.level,G.totalLevels)}/${G.totalLevels}`;
  document.getElementById('lives').textContent=`👆 Moves ${G.moves}`;
}
function startLevel(lv){
  G.level=lv;const L=LEVELS[lv-1];
  G.target=L.target;G.score=0;G.moves=L.moves;G.chainK=0;G.lastGain=0;
  G.phase='idle';G.animating=false;popSet=new Set();falling.length=0;glowSet=new Set();
  fillBoard();settle();layout();updateHUD();
}
function resolveStep(){
  if(G.phase==='pop'){
    // collect & score the pop group
    const n=popSet.size;
    const gain=popScore(n,G.chainK);
    G.score+=gain;G.lastGain=gain;
    if(G.chainK>1)sfx.chain(G.chainK);else sfx.pop(n);
    if(n>=6)spawnText(W/2,H*0.20,'BOOM!','#ffd23f',30);
    if(G.chainK>1){chainBannerT=1.1;spawnText(W/2,H*0.26,`CHAIN x${G.chainK}!`,'#c99aff',26);}
    // bursts + optional row-face + obsidian cracks
    for(const i of popSet){
      const c=i%G.cols,r=(i/G.cols)|0;
      const cell=G.board[i];
      const pal=cell?PALETTE[cell.v]:null;
      burst(cellCX(c),cellCY(r),pal?pal.glow:'#ffd76a',n>=6?10:5,150+n*8);
    }
    const frc=rowFaceCell([...popSet].map(i=>[i%G.cols,(i/G.cols)|0]));
    const addRow=frc?frc[1]:null;
    const full=collectPops([...popSet].map(i=>[i%G.cols,(i/G.cols)|0]),addRow);
    if(addRow!==null&&addRow!==undefined){sfx.face();spawnText(W/2,H*0.34,'FIRE BABY ROW!','#7dff8a',24);}
    for(const i of full)G.board[i]=null;
    if(full.size>popSet.size)for(let c=0;c<G.cols;c++)burst(cellCX(c),cellCY(addRow),PALETTE[(c%PALETTE.length)].glow,4,120);
    const cracked=adjacentObsidian(full);
    if(cracked.size){sfx.crack();for(const i of cracked){G.board[i]=null;burst(cellCX(i%G.cols),cellCY((i/G.cols)|0),'#8a8a9a',8,130);spawnText(cellCX(i%G.cols),cellCY((i/G.cols)|0),'CRACK!','#cfd4e6',18);}}
    G.phase='settle';G.phaseT=0.22;
    updateHUD();
    return;
  }
  if(G.phase==='settle'){applyGravity();G.phase='check';return;}
  if(G.phase==='check'){
    // chains form ONLY from the fall/slide — fresh refills never chain,
    // which is what makes cascades exciting instead of endless
    const auto=findAutoGroup(3);
    if(auto){
      G.chainK++;popSet=new Set(auto.map(cr=>idx(cr[0],cr[1])));
      for(const cr of auto){const i=idx(cr[0],cr[1]);const cell=G.board[i];if(cell)cell.pop=1;}
      popT=0.28;G.phase='pop';G.phaseT=0.28;
      return;
    }
    refill();
    G.phase='idle';G.animating=false;
    glowPulse=0.6;glowSet=new Set();
    const hint=findAnyGroup();
    if(hint)for(const cr of hint)glowSet.add(idx(cr[0],cr[1]));
    if(G.score>=G.target){levelClear();return;}
    if(G.moves<=0){levelFail();return;}
    updateHUD();
    return;
  }
}
function tapOrb(c,r){
  if(G.state!=='play'||G.paused||G.animating)return;
  if(c<0||r<0||c>=G.cols||r>=G.rows)return;
  const g=groupAt(c,r);
  if(!g){sfx.bad();spawnText(e_clientX(),e_clientY(),'Need 2+ touching!','#ff9a5a',16);return;}
  if(g.cells.length<2){sfx.bad();spawnText(e_clientX(),e_clientY(),'Need 2+ touching!','#ff9a5a',16);return;}
  G.moves--;
  G.chainK=1;
  popSet=new Set(g.cells.map(cr=>idx(cr[0],cr[1])));
  for(const cr of g.cells){const cell=G.board[idx(cr[0],cr[1])];if(cell)cell.pop=1;}
  popT=0.28;G.phase='pop';G.phaseT=0.28;G.animating=true;
  updateHUD();
}
let _lastX=W/2,_lastY=H/2;
function e_clientX(){return _lastX;}function e_clientY(){return _lastY;}
canvas.addEventListener('pointerdown',e=>{
  _lastX=e.clientX;_lastY=e.clientY;
  if(G.state!=='play'||G.paused||G.animating)return;
  const c=Math.floor((e.clientX-geo.x0)/geo.cell),r=Math.floor((e.clientY-geo.y0)/geo.cell);
  tapOrb(c,r);
});

/* stars */
function starCount(lv,score){
  const t=LEVELS[lv-1].target;
  if(score>=t*1.6)return 3;
  if(score>=t*1.25)return 2;
  return 1;
}

/* overlay screens */
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();startLevel(1);G.state='play';overlay.classList.add('hidden');}
obtn.onclick=()=>{showMathGate();};
function levelClear(){
  const stars=starCount(G.level,G.score);G.stars=stars;
  sfx.win();
  if(G.level>=G.totalLevels){
    G.state='over';
    setTimeout(()=>{showOverlay('🏆 CASCADE MASTER!',
      `<p>You cleared all <b>12 levels</b> of Ember Cascade!</p><p style="font-size:26px">${'⭐'.repeat(3)}</p>`,
      '🔥 Fire Safety: Matches and lighters are tools for grown-ups — never toys!',
      '↻ PLAY AGAIN',()=>{startLevel(1);G.state='play';});},500);
  }else{
    G.state='clear';const next=G.level+1;
    setTimeout(()=>{showOverlay(`✅ LEVEL ${G.level} CLEAR!`,
      `<p>Target <b>${G.target}</b> smashed with <b>${G.score}</b> points!</p><p style="font-size:26px">${'⭐'.repeat(stars)}${'☆'.repeat(3-stars)}</p><p>Moves left: ${G.moves}</p>`,
      '🔥 Fire Safety: A clear head solves any puzzle — stay calm and think!',
      `▶ LEVEL ${next}`,()=>{startLevel(next);G.state='play';});},500);
  }
}
function levelFail(){
  G.state='over';sfx.lose();
  setTimeout(()=>{showOverlay('💥 OUT OF MOVES!',
    `<p>So close! You reached <b>${G.score}</b> of the <b>${G.target}</b> target.</p><p>Try bigger bunches — and watch for chain cascades!</p>`,
    '🔥 Fire Safety: If at first you don\'t succeed, try a safer plan — never give up!',
    '↻ TRY AGAIN',()=>{startLevel(G.level);G.state='play';});},500);
}

/* pause / mute / restart */
function setPaused(p){G.paused=!!(p&&G.state==='play');const b=document.getElementById('pauseBtn');if(b)b.textContent=G.paused?'▶':'⏸';}
document.getElementById('pauseBtn').addEventListener('click',e=>{e.currentTarget.blur();setPaused(!G.paused);sfx.click();});
const muteBtnEl=document.getElementById('muteBtn');muteBtnEl.textContent=MUTED?'🔇':'🔊';
muteBtnEl.addEventListener('click',e=>{e.currentTarget.blur();MUTED=!MUTED;muteBtnEl.textContent=MUTED?'🔇':'🔊';try{localStorage.setItem('fb_muted',MUTED?'1':'0');}catch(err){}if(!MUTED)sfx.click();});
document.getElementById('restartBtn').addEventListener('click',e=>{e.currentTarget.blur();if(G.state==='title')return;sfx.click();startLevel(G.level);G.state='play';overlay.classList.add('hidden');setPaused(false);});
addEventListener('keydown',e=>{if(e.key==='p'||e.key==='P'||e.key==='Escape')setPaused(!G.paused);if(e.key==='m'||e.key==='M')muteBtnEl.click();});

/* update */
function update(dt){
  G.time+=dt;
  if(G.animating){
    popT-=dt;
    if(popT<=0)resolveStep();
  }
  if(chainBannerT>0)chainBannerT-=dt;
  if(glowPulse>0)glowPulse-=dt;
  updateEmbers(dt);
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=300*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  for(const f of floaters){if(!f.a)continue;f.y-=40*dt;f.life-=dt;if(f.life<=0)f.a=false;}
  for(const fl of falling){
    fl.t+=dt;
    const dur=0.28;
    if(fl.t>=dur){fl.done=true;}
  }
  for(let i=falling.length-1;i>=0;i--)if(falling[i].done)falling.splice(i,1);
  // pop scale animation on marked orbs
  for(let r=0;r<G.rows;r++)for(let c=0;c<G.cols;c++){
    const cell=G.board[idx(c,r)];
    if(cell&&cell.pop>0){cell.pop=Math.min(1.35,cell.pop+dt*3);}
  }
  render();
}

/* render */
function drawFaceOrb(x,y,rad,ink){
  // happy Fire Baby face, code-drawn: two bright eyes + a big cheerful grin
  ctx.fillStyle=ink;
  ctx.beginPath();ctx.arc(x-rad*0.34,y-rad*0.12,rad*0.11,0,Math.PI*2);ctx.fill();
  ctx.beginPath();ctx.arc(x+rad*0.34,y-rad*0.12,rad*0.11,0,Math.PI*2);ctx.fill();
  ctx.strokeStyle=ink;ctx.lineWidth=Math.max(2,rad*0.10);ctx.lineCap='round';
  ctx.beginPath();ctx.arc(x,y+rad*0.08,rad*0.42,Math.PI*0.18,Math.PI*0.82);ctx.stroke();
  // rosy cheeks
  ctx.fillStyle='rgba(255,255,255,0.35)';
  ctx.beginPath();ctx.arc(x-rad*0.52,y+rad*0.24,rad*0.13,0,Math.PI*2);ctx.fill();
  ctx.beginPath();ctx.arc(x+rad*0.52,y+rad*0.24,rad*0.13,0,Math.PI*2);ctx.fill();
}
function drawOrb(x,y,rad,cell,t){
  const pal=PALETTE[cell.v];
  const pulse=1+0.05*Math.sin(t*3+x*0.05+y*0.03);
  let r=rad*pulse;
  if(cell.pop>0)r=rad*(1+(cell.pop-1)*0.9);
  // soft glow
  ctx.save();
  ctx.globalAlpha=cell.pop>0?0.85:0.5;
  const spr=EMBER_SPRITE;
  ctx.drawImage(spr,x-r*2.1,y-r*2.1,r*4.2,r*4.2);
  ctx.restore();
  // flame-teardrop body: round bottom, soft point at top
  const g=ctx.createRadialGradient(x-r*0.35,y-r*0.4,r*0.15,x,y+r*0.1,r*1.15);
  g.addColorStop(0,'#ffffff');g.addColorStop(0.35,pal.body);g.addColorStop(1,pal.deep);
  ctx.fillStyle=g;
  ctx.beginPath();
  ctx.moveTo(x,y-r*1.12);
  ctx.bezierCurveTo(x+r*0.85,y-r*0.55,x+r*0.95,y+r*0.25,x+r*0.62,y+r*0.72);
  ctx.bezierCurveTo(x+r*0.35,y+r*0.98,x-r*0.35,y+r*0.98,x-r*0.62,y+r*0.72);
  ctx.bezierCurveTo(x-r*0.95,y+r*0.25,x-r*0.85,y-r*0.55,x,y-r*1.12);
  ctx.fill();
  ctx.strokeStyle='rgba(60,20,0,0.55)';ctx.lineWidth=2;ctx.stroke();
  // inner sparkle
  ctx.fillStyle='rgba(255,255,255,0.5)';
  ctx.beginPath();ctx.arc(x-r*0.3,y-r*0.18,r*0.16,0,Math.PI*2);ctx.fill();
  if(cell.face)drawFaceOrb(x,y+r*0.08,r,pal.ink);
  if(cell.pop>0){
    ctx.strokeStyle='rgba(255,255,255,'+(0.9-(cell.pop-1)*1.4)+')';ctx.lineWidth=3;
    ctx.beginPath();ctx.arc(x,y,r*1.15,0,Math.PI*2);ctx.stroke();
  }
}
function drawObsidian(x,y,rad){
  ctx.fillStyle='#23202a';
  const s=rad*1.7;
  ctx.beginPath();
  if(ctx.roundRect)ctx.roundRect(x-s/2,y-s/2,s,s,6);else ctx.rect(x-s/2,y-s/2,s,s);
  ctx.fill();
  ctx.strokeStyle='#4a4458';ctx.lineWidth=2;ctx.stroke();
  ctx.strokeStyle='rgba(160,150,190,0.35)';ctx.lineWidth=1.5;
  ctx.beginPath();ctx.moveTo(x-s*0.28,y-s*0.1);ctx.lineTo(x+s*0.05,y+s*0.18);ctx.lineTo(x+s*0.3,y-s*0.22);ctx.stroke();
  ctx.fillStyle='rgba(255,255,255,0.10)';
  ctx.beginPath();ctx.arc(x-s*0.2,y-s*0.25,3,0,Math.PI*2);ctx.fill();
}
function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#1a0d08');bg.addColorStop(0.5,'#2a1a0a');bg.addColorStop(1,'#1a0d08');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  drawEmbers();
  const L=LEVELS[Math.min(G.level,LEVELS.length)-1];
  const gw=geo.cell*G.cols,gh=geo.cell*G.rows;
  // board frame
  ctx.fillStyle='rgba(0,0,0,0.35)';
  ctx.beginPath();
  if(ctx.roundRect)ctx.roundRect(geo.x0-8,geo.y0-8,gw+16,gh+16,14);else ctx.rect(geo.x0-8,geo.y0-8,gw+16,gh+16);
  ctx.fill();
  ctx.strokeStyle='rgba(255,180,90,0.35)';ctx.lineWidth=2;ctx.stroke();
  // target progress bar
  const bw=gw,bx=geo.x0,by=Math.max(geo.y0-30,70);
  ctx.fillStyle='rgba(0,0,0,0.55)';
  ctx.beginPath();if(ctx.roundRect)ctx.roundRect(bx,by,bw,12,6);else ctx.rect(bx,by,bw,12);ctx.fill();
  const frac=Math.min(1,G.score/Math.max(1,G.target));
  if(frac>0){
    const pg=ctx.createLinearGradient(bx,0,bx+bw,0);
    pg.addColorStop(0,'#ff6a1a');pg.addColorStop(1,'#ffd23f');
    ctx.fillStyle=pg;
    ctx.beginPath();if(ctx.roundRect)ctx.roundRect(bx,by,bw*frac,12,6);else ctx.rect(bx,by,bw*frac,12);ctx.fill();
  }
  ctx.fillStyle='#ffe9d6';ctx.font='800 13px system-ui';ctx.textAlign='center';
  ctx.fillText(`🎯 ${G.score} / ${L.target}`,W/2,by-6);
  ctx.textAlign='left';
  // hint shimmer on a suggested group when idle
  const hinting=G.state==='play'&&!G.animating&&glowSet.size>0;
  // cells with an active fall-in visual are drawn only by the falling pass
  const fallingCells=new Set(falling.map(fl=>idx(fl.c,fl.r)));
  // orbs
  for(let r=0;r<G.rows;r++)for(let c=0;c<G.cols;c++){
    const cell=G.board[idx(c,r)];
    if(!cell)continue;
    const x=cellCX(c),y=cellCY(r),rad=geo.cell*0.42;
    if(cell.v===OBS){drawObsidian(x,y,rad);continue;}
    if(fallingCells.has(idx(c,r)))continue;
    drawOrb(x,y,rad,cell,G.time);
    if(hinting&&glowSet.has(idx(c,r))){
      ctx.strokeStyle='rgba(255,255,255,'+(0.35+0.3*Math.sin(G.time*6))+')';ctx.lineWidth=2.5;
      ctx.beginPath();ctx.arc(x,y,rad*1.08,0,Math.PI*2);ctx.stroke();
    }
  }
  // falling (newly spawned) orbs slide in
  for(const fl of falling){
    const ease=Math.min(1,fl.t/0.28);
    const yy=cellCY(fl.r)+fl.dy*(1-ease)*(1-ease);
    drawOrb(cellCX(fl.c),yy,geo.cell*0.42,{v:fl.v,face:fl.face,pop:0},G.time);
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  // chain banner
  if(chainBannerT>0&&G.chainK>1){
    ctx.textAlign='center';ctx.font='900 30px system-ui';
    ctx.globalAlpha=Math.min(1,chainBannerT);
    ctx.fillStyle='#000';ctx.fillText(`⛓ CHAIN x${G.chainK}!`,W/2+2,H*0.15+2);
    ctx.fillStyle='#c99aff';ctx.fillText(`⛓ CHAIN x${G.chainK}!`,W/2,H*0.15);
    ctx.globalAlpha=1;ctx.textAlign='left';
  }
  // floaters with dark pill backdrop
  ctx.textAlign='center';
  for(const f of floaters){
    if(!f.a)continue;
    const a=Math.min(1,f.life);
    ctx.font='900 '+(f.size||20)+'px system-ui';
    const tw=ctx.measureText(f.txt).width;
    ctx.globalAlpha=a*0.72;ctx.fillStyle='#000';
    ctx.beginPath();
    if(ctx.roundRect)ctx.roundRect(f.x-tw/2-10,f.y-21,tw+20,28,9);else ctx.rect(f.x-tw/2-10,f.y-21,tw+20,28);
    ctx.fill();
    ctx.globalAlpha=a;
    ctx.fillStyle='#000';ctx.fillText(f.txt,f.x+2,f.y+2);
    ctx.fillStyle=f.color;ctx.fillText(f.txt,f.x,f.y);
  }
  ctx.globalAlpha=1;ctx.textAlign='left';
  if(G.paused){ctx.fillStyle='rgba(0,0,0,0.5)';ctx.fillRect(0,0,W,H);ctx.fillStyle='#fff';ctx.font='900 36px system-ui';ctx.textAlign='center';ctx.fillText('⏸ PAUSED',W/2,H/2);ctx.font='700 16px system-ui';ctx.fillText('Tap ⏸ or press P to keep playing',W/2,H/2+32);ctx.textAlign='left';}
}

/* loop */
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(!G.paused)update(dt);
  requestAnimationFrame(loop);
}
resize();
fillBoard();
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Cascade Glow' — Ember Cascade's own
   track. Synthesized Web Audio only. 96 BPM, F major (F–B♭–Dm–C): warm
   triangle lead in gentle cascading descents with a sine-bell shimmer,
   soft half-note bass pulses and a quiet shaker — calm puzzle glow.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-09-ember-cascade.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
const MUS={on:false,step:0,nextT:0,BPM:96,
 BASS:[41,0,0,0,0,0,41,0, 34,0,0,0,0,0,34,0, 38,0,0,0,0,0,38,0, 36,0,0,0,0,0,43,0],
 LEAD:[77,0,74,0,72,0,69,0, 74,0,72,0,69,0,65,0, 74,0,72,0,69,0,65,0, 69,0,72,0,74,0,77,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(MUTED||G.paused||G.state!=='play'){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.3,'triangle',0.07,d);
  const l=this.LEAD[s];if(l){tone(_mf(l),_mf(l),0.26,'triangle',0.05,d);
   tone(_mf(l)*2,_mf(l)*2,0.12,'sine',0.014,d);} // bell shimmer
  if(s%8===0)tone(110,45,0.13,'sine',0.11,d); // soft kick, once a bar
  if(s%8===4)tone(130,50,0.13,'sine',0.09,d);
  noise(0.03,0.016,d,7000); // gentle shaker every 8th
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

