scripts:
'use strict';
/* ============================================================
   CALDERA CLIMB v3 — vertical climber rebuild
   Blaze auto-bounces up rock ledges; steer left/right (keys or drag).
   Steam vents launch you higher; falling rocks telegraph then drop
   (hit = knocked down + lose a heart, dizzy stars, never injury).
   Lava rises below as pressure. Reach the rim flag to clear 10 levels.
   ============================================================ */
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;
  canvas.style.width=W+'px';canvas.style.height=H+'px';
  ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);

/* audio (same tone() helper contract as the old game) */
let AC=null,MUTED=false;try{MUTED=localStorage.getItem('fb_muted')==='1';}catch(e){}
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
function noise(dur,vol,freq,delay=0){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const len=Math.max(1,Math.floor(ac.sampleRate*dur)),buf=ac.createBuffer(1,len,ac.sampleRate),d=buf.getChannelData(0);
  for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);
  const s=ac.createBufferSource(),f=ac.createBiquadFilter(),g=ac.createGain();
  s.buffer=buf;f.type='bandpass';f.frequency.value=freq;f.Q.value=1.2;
  s.connect(f);f.connect(g);g.connect(ac.destination);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  s.start(t);s.stop(t+dur+0.05);}
const sfx={
  bounce(){tone(300,700,0.12,'sine',0.12);},
  vent(){noise(0.5,0.22,900);tone(150,900,0.45,'sine',0.14);},
  warn(){tone(880,880,0.09,'square',0.09);tone(880,880,0.09,'square',0.09,0.14);},
  hit(){tone(220,90,0.25,'square',0.16);noise(0.2,0.18,400);},
  heart(){tone(660,330,0.3,'triangle',0.16);},
  dodge(){tone(1200,1800,0.1,'sine',0.1);},
  bad(){tone(200,80,0.3,'square',0.15);},
  win(){[523,659,784,1047].forEach((f,i)=>tone(f,f,0.25,'triangle',0.18,i*0.1));},
  click(){tone(600,600,0.06,'square',0.1);}
};

/* level design: goal in meters; narrower ledges, more rocks, faster lava, wind later */
const PPM=48; /* pixels per meter */
const LEVELS=[
  {goal:150,w:118,gap:[86,130],rockT:5.0,lava:7, wind:false},
  {goal:230,w:110,gap:[88,136],rockT:4.6,lava:9, wind:false},
  {goal:330,w:102,gap:[90,142],rockT:4.2,lava:11,wind:false},
  {goal:450,w:96, gap:[92,148],rockT:3.8,lava:13,wind:true},
  {goal:600,w:90, gap:[94,154],rockT:3.4,lava:15,wind:true},
  {goal:770,w:84, gap:[96,160],rockT:3.0,lava:18,wind:true},
  {goal:950,w:78, gap:[98,165],rockT:2.8,lava:21,wind:true},
  {goal:1150,w:72,gap:[100,170],rockT:2.5,lava:23,wind:true},
  {goal:1370,w:66,gap:[102,174],rockT:2.3,lava:25,wind:true},
  {goal:1600,w:60,gap:[104,178],rockT:2.1,lava:28,wind:true},
];
const JUMP=980,GRAV=2600,HSPD=380;

/* state */
const G={state:'title',level:1,score:0,startScore:0,hearts:3,
  hero:{x:0,y:0,vx:0,vy:0,r:20},ledges:[],rocks:[],parts:[],tele:[],
  camY:0,maxAlt:0,lavaY:0,lastLedgeY:0,
  rockT:0,windT:4,gust:0,gustDir:1,invuln:0,dizzy:0,
  time:0,paused:false};
const keys={l:false,r:false};
let dragOn=false,dragX0=0,dragHx=0,dragHero0=0;

function field(){const PW=Math.min(W,520);return{x0:(W-PW)/2,pw:PW};}
function cfg(){return LEVELS[G.level-1];}

function addLedge(y){
  const f=field(),L=cfg();
  const w=L.w*(0.9+Math.random()*0.2);
  const x=f.x0+8+Math.random()*Math.max(1,f.pw-16-w);
  const vent=Math.random()<0.16&&G.ledges.length>4;
  G.ledges.push({x:x,y:y,w:w,vent:vent});
  return G.ledges[G.ledges.length-1];
}
function initLevel(n){
  const L=LEVELS[n-1];
  G.level=n;G.startScore=G.score;G.hearts=3;
  G.ledges=[];G.rocks=[];G.parts=[];G.tele=[];
  G.maxAlt=0;G.rockT=3;G.windT=5;G.gust=0;G.invuln=0;G.dizzy=0;
  const f=field();
  G.ledges.push({x:f.x0+f.pw/2-60,y:0,w:120,vent:false});
  let topY=0;
  while(topY>-(L.goal*PPM+400))topY=addLedge(topY-(L.gap[0]+Math.random()*(L.gap[1]-L.gap[0]))).y;
  /* rim ledge with the flag */
  G.ledges.push({x:f.x0+f.pw/2-90,y:-L.goal*PPM,w:180,vent:false,flag:true});
  const h=G.hero;h.x=f.x0+f.pw/2;h.y=-30;h.vx=0;h.vy=-JUMP*0.6;h.r=20;
  G.lastLedgeY=0;G.camY=h.y-H*0.42;G.lavaY=340;
  document.getElementById('level').textContent=`LV ${n}/10`;
  updateHUD(true);
}
function updateHUD(force){
  const alt=Math.max(0,Math.floor(G.maxAlt));
  const a=`⭐ ${G.score}`,b=`🎯 ${alt}m/${cfg().goal}m`;
  if(force||a!==updateHUD._a){document.getElementById('score').textContent=a;updateHUD._a=a;}
  if(force||b!==updateHUD._b){document.getElementById('moves').textContent=b;updateHUD._b=b;}
}
function addScore(n,x,y,txt){
  G.score+=n;updateHUD();
  if(txt)spawnText(x,y,txt);
}

/* floaters */
const floaters=[];
for(let i=0;i<10;i++)floaters.push({a:false});
function spawnText(x,y,txt){const f=floaters.find(f=>!f.a);if(!f)return;
  f.a=true;f.x=x;f.y=y;f.txt=txt;f.life=1.3;}

/* particles */
function burst(x,y,n,col,spd,life){
  for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=spd*(0.4+Math.random()*0.8);
    G.parts.push({x:x,y:y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-60,life:life*(0.6+Math.random()*0.8),max:life,col:col,r:2+Math.random()*3});}
  if(G.parts.length>240)G.parts.splice(0,G.parts.length-240);}

function loseHeart(x,y,why){
  if(G.invuln>0||G.state!=='play')return;
  G.hearts--;G.invuln=1.4;G.dizzy=1.2;
  sfx.hit();sfx.heart();
  burst(x,y,14,'#ffd23f',260,0.9);burst(x,y,8,'#ff6a1a',180,0.7);
  spawnText(x,y-40,'💔 OUCH!'+(why?' '+why:''));
  const f=field();
  if(G.hearts<=0){gameOver();return;}
  /* knocked down a few ledges, respawn on the last safe ledge */
  G.hero.y=G.lastLedgeY-G.hero.r-2;G.hero.vy=-JUMP*0.85;G.hero.vx=0;
  G.hero.x=Math.max(f.x0+20,Math.min(f.x0+f.pw-20,G.hero.x));
  G.lavaY=Math.max(G.lavaY,G.hero.y+460);
}

/* physics + spawning */
function step(dt){
  const L=cfg(),f=field(),h=G.hero;
  /* steering */
  let mv=0;
  if(keys.l)mv-=1;if(keys.r)mv+=1;
  h.vx=mv*HSPD;
  if(dragOn)h.x=dragHx;
  if(G.gust>0)h.x+=G.gustDir*130*dt;
  h.x+=h.vx*dt;
  /* wrap around the caldera walls */
  if(h.x<f.x0-22)h.x=f.x0+f.pw+22;
  if(h.x>f.x0+f.pw+22)h.x=f.x0-22;
  h.vy+=GRAV*dt;
  const prevBottom=h.y+h.r;
  h.y+=h.vy*dt;
  /* ledge landings (falling onto a top) */
  if(h.vy>0){
    for(const ld of G.ledges){
      if(prevBottom<=ld.y+6&&h.y+h.r>=ld.y&&h.x>ld.x-6&&h.x<ld.x+ld.w+6){
        h.y=ld.y-h.r;
        G.lastLedgeY=ld.y;
        if(ld.vent){
          h.vy=-JUMP*1.5;sfx.vent();addScore(25,h.x,h.y-30,'+25 VENT!');
          burst(h.x,ld.y,16,'#cfd8dc',200,0.8);
        }else{
          h.vy=-JUMP;sfx.bounce();addScore(2,h.x,h.y-24,'+2');
          burst(h.x,ld.y,6,'#8d6e63',120,0.5);
        }
        break;
      }
    }
  }
  /* altitude + score */
  const alt=Math.max(0,-h.y/PPM);
  if(alt>G.maxAlt){
    const gain=Math.floor(alt)-Math.floor(G.maxAlt);
    if(gain>0)addScore(gain*3,h.x,h.y-40,'+'+gain*3+'m');
    G.maxAlt=alt;
  }
  updateHUD();
  /* camera follows up only */
  const target=h.y-H*0.42;
  if(target<G.camY)G.camY+=(target-G.camY)*Math.min(1,dt*6);
  /* keep ledges coming above, drop far below */
  let topY=Infinity;for(const ld of G.ledges)if(ld.y<topY)topY=ld.y;
  while(topY>G.camY-300){topY=addLedge(topY-(L.gap[0]+Math.random()*(L.gap[1]-L.gap[0]))).y;}
  G.ledges=G.ledges.filter(ld=>ld.y<G.camY+H+420);
  /* lava pressure */
  G.lavaY-=L.lava*dt;
  if(h.y+h.r>=G.lavaY){
    loseHeart(h.x,h.y,'LAVA!');
    if(G.state!=='play')return;
  }
  /* fell out of view */
  if(h.y-h.r>G.camY+H+130){
    loseHeart(h.x,G.camY+H-60,'WHOA!');
    if(G.state!=='play')return;
  }
  /* rocks: telegraph then drop */
  G.rockT-=dt;
  if(G.rockT<=0){
    G.rockT=L.rockT*(0.7+Math.random()*0.6);
    const tx=f.x0+20+Math.random()*(f.pw-40);
    G.tele.push({x:tx,y:G.camY+50,t:0.9});
    sfx.warn();
  }
  for(let i=G.tele.length-1;i>=0;i--){
    const t=G.tele[i];t.t-=dt;
    if(t.t<=0){G.rocks.push({x:t.x,y:G.camY-30,vy:0,r:22,counted:false,rot:0});G.tele.splice(i,1);}
  }
  const rockV=480+G.level*40;
  for(let i=G.rocks.length-1;i>=0;i--){
    const r=G.rocks[i];r.vy=rockV;r.y+=r.vy*dt;r.rot+=dt*3;
    const dx=h.x-r.x,dy=h.y-r.y;
    if(G.invuln<=0&&dx*dx+dy*dy<Math.pow(h.r+r.r*0.72,2)){
      loseHeart(h.x,h.y,'BONK!');
      G.rocks.splice(i,1);
      if(G.state!=='play')return;
      continue;
    }
    if(!r.counted&&r.y>h.y+60){r.counted=true;addScore(10,h.x,h.y-44,'+10 DODGED!');sfx.dodge();}
    if(r.y>G.camY+H+120)G.rocks.splice(i,1);
  }
  /* wind gusts (level 4+) */
  if(L.wind){
    G.windT-=dt;
    if(G.windT<=0&&G.gust<=0){
      G.gust=2.2;G.gustDir=Math.random()<0.5?-1:1;
      G.windT=4+Math.random()*3.5;sfx.warn();
    }
    if(G.gust>0)G.gust-=dt;
  }
  /* goal: rim flag */
  if(alt>=L.goal){levelComplete();return;}
  if(G.invuln>0)G.invuln-=dt;
  if(G.dizzy>0)G.dizzy-=dt;
  /* particles */
  for(let i=G.parts.length-1;i>=0;i--){
    const p=G.parts[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=500*dt;p.life-=dt;
    if(p.life<=0)G.parts.splice(i,1);
  }
}

/* overlay (same shell contracts as the old game) */
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');showLevels();
  }else document.getElementById('ma').value='';
}
function showLevels(){
  otitle.innerHTML='🌋 PICK LEVEL';
  let h='';
  for(let i=1;i<=10;i++)h+=`<button class="lvlBtn" onclick="event.stopPropagation();pickLevel(${i})">${i}</button>`;
  obody.innerHTML=`<p>Bounce up the ledges, ride steam vents, dodge rocks, and beat the rising lava to the rim flag!</p><div id="lvlSel">${h}</div>`;
  obtn.style.display='none';
  overlay.classList.remove('hidden');
}
function pickLevel(n){sfx.click();audio();G.score=0;initLevel(n);G.state='play';overlay.classList.add('hidden');}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;
  obtn.textContent=btn;obtn.style.display='';
