  const bonus=G.hearts*100;G.score+=bonus;updateHUD();
  const m=Math.floor(G.maxAlt);
  if(G.level>=10){
    showOverlay('🏆 VOLCANO CONQUERED!',
      `<p style="font-size:24px;font-weight:900">Blaze reached the rim!</p><p>Final Score: ${G.score}</p><p>All 10 levels cleared!</p>`,
      '🔥 Fire Safety: You climbed like a champion — in a real fire, the real win is getting OUT fast!',
