obtn.onclick=()=>{showMathGate();};

/* pause / mute / restart (same contracts as old game) */
function setPaused(p){G.paused=!!(p&&G.state==='play');const b=document.getElementById('pauseBtn');if(b)b.textContent=G.paused?'▶':'⏸';}
document.getElementById('pauseBtn').addEventListener('click',e=>{e.currentTarget.blur();setPaused(!G.paused);sfx.click();});
const muteBtnEl=document.getElementById('muteBtn');muteBtnEl.textContent=MUTED?'🔇':'🔊';
muteBtnEl.addEventListener('click',e=>{e.currentTarget.blur();MUTED=!MUTED;muteBtnEl.textContent=MUTED?'🔇':'🔊';try{localStorage.setItem('fb_muted',MUTED?'1':'0');}catch(err){}if(!MUTED)sfx.click();});
document.getElementById('restartBtn').addEventListener('click',e=>{e.currentTarget.blur();if(G.state==='title')return;sfx.click();G.score=G.startScore;initLevel(G.level);G.state='play';overlay.classList.add('hidden');setPaused(false);});

/* input: arrows/A,D steer; drag moves Blaze */
addEventListener('keydown',e=>{
  if(e.key==='p'||e.key==='P'||e.key==='Escape'){setPaused(!G.paused);return;}
  if(e.key==='m'||e.key==='M'){muteBtnEl.click();return;}
  if(G.state!=='play'||G.paused)return;
  if(e.key==='ArrowLeft'||e.key==='a'||e.key==='A'){keys.l=true;e.preventDefault();}
  if(e.key==='ArrowRight'||e.key==='d'||e.key==='D'){keys.r=true;e.preventDefault();}
});
addEventListener('keyup',e=>{
  if(e.key==='ArrowLeft'||e.key==='a'||e.key==='A')keys.l=false;
  if(e.key==='ArrowRight'||e.key==='d'||e.key==='D')keys.r=false;
});
canvas.addEventListener('pointerdown',e=>{dragOn=true;dragX0=e.clientX;dragHero0=G.hero.x;dragHx=G.hero.x;});
addEventListener('pointermove',e=>{if(dragOn)dragHx=dragHero0+(e.clientX-dragX0)*1.8;});
addEventListener('pointerup',()=>{dragOn=false;});
addEventListener('pointercancel',()=>{dragOn=false;});

/* render */
/* living embers (same as old game) */
const EMBER_SEEDS=Array.from({length:24},(_,i)=>({x:(i*0.61803)%1,y:(i*0.754877)%1,s:1+((i*7)%3),v:12+((i*13)%24),d:((i*29)%20)-10}));
function drawEmbers(bw,bh){ctx.save();ctx.globalCompositeOperation='lighter';const t=G.time||0;
  for(const e of EMBER_SEEDS){const ey=bh-((e.y*bh+t*e.v)%bh);const ex=e.x*bw+Math.sin(t*0.7+e.y*9)*e.d;
    ctx.globalAlpha=0.13+0.09*Math.sin(t*2+e.y*20);ctx.fillStyle='#ff9a3a';ctx.shadowColor='#ff6a00';ctx.shadowBlur=0;
    ctx.beginPath();ctx.arc(ex,ey,e.s,0,Math.PI*2);ctx.fill();}
  ctx.restore();}

function drawBlaze(x,y,r,tilt){
  ctx.save();ctx.translate(x,y);ctx.rotate(tilt);
  if(G.invuln>0&&Math.floor(G.time*12)%2===0)ctx.globalAlpha=0.35;
  const g=ctx.createLinearGradient(0,-r*1.6,0,r*1.1);
  g.addColorStop(0,'#ffd76a');g.addColorStop(0.45,'#ff8c2e');g.addColorStop(1,'#e03e12');
  ctx.fillStyle=g;ctx.shadowColor='#ff6a00';ctx.shadowBlur=0;
  ctx.beginPath();
  ctx.moveTo(0,-r*1.55);
  ctx.bezierCurveTo(r*1.15,-r*0.6,r*0.95,r*0.7,0,r);
  ctx.bezierCurveTo(-r*0.95,r*0.7,-r*1.15,-r*0.6,0,-r*1.55);
  ctx.fill();ctx.shadowBlur=0;
  /* inner glow flame */
  const g2=ctx.createLinearGradient(0,-r*0.9,0,r*0.7);
  g2.addColorStop(0,'rgba(255,246,200,0.95)');g2.addColorStop(1,'rgba(255,246,200,0)');
  ctx.fillStyle=g2;ctx.beginPath();
  ctx.moveTo(0,-r*0.95);ctx.bezierCurveTo(r*0.6,-r*0.3,r*0.5,r*0.4,0,r*0.6);
  ctx.bezierCurveTo(-r*0.5,r*0.4,-r*0.6,-r*0.3,0,-r*0.95);ctx.fill();
  if(G.dizzy>0){
    /* playful dizzy stars instead of pain */
    ctx.fillStyle='#ffd23f';ctx.shadowColor='#ffd23f';ctx.shadowBlur=0;
    for(let i=0;i<3;i++){const a=G.time*5+i*2.094,sx=Math.cos(a)*r*1.3,sy=-r*0.6+Math.sin(a)*r*0.5;
      ctx.beginPath();ctx.arc(sx,sy,3.5,0,Math.PI*2);ctx.fill();}
    ctx.shadowBlur=0;
  }else{
    /* face: angry-V brows, glaring eyes, smirk — no beaks/wings/feathers, ever */
    ctx.strokeStyle='#3a1408';ctx.lineWidth=3.5;ctx.lineCap='round';
    ctx.beginPath();ctx.moveTo(-r*0.62,-r*0.42);ctx.lineTo(-r*0.14,-r*0.24);ctx.stroke();
    ctx.beginPath();ctx.moveTo(r*0.62,-r*0.42);ctx.lineTo(r*0.14,-r*0.24);ctx.stroke();
    for(const sx of [-r*0.34,r*0.34]){
      ctx.fillStyle='#fff';ctx.beginPath();ctx.ellipse(sx,-r*0.05,r*0.22,r*0.28,0,0,Math.PI*2);ctx.fill();
      ctx.fillStyle='#c81e1e';ctx.beginPath();ctx.arc(sx,-r*0.02,r*0.11,0,Math.PI*2);ctx.fill();
      ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(sx-r*0.04,-r*0.06,r*0.035,0,Math.PI*2);ctx.fill();
    }
    ctx.strokeStyle='#3a1408';ctx.lineWidth=3;
    ctx.beginPath();ctx.arc(-r*0.05,r*0.42,r*0.34,0.35,Math.PI-0.9);ctx.stroke();
  }
  ctx.restore();
}
function drawLedge(ld){
  const y=ld.y-G.camY;if(y<-40||y>H+60)return;
  ctx.save();
  ctx.fillStyle='rgba(0,0,0,0.35)';ctx.beginPath();ctx.roundRect(ld.x+3,ld.y-G.camY+5,ld.w,14,7);ctx.fill();
  const g=ctx.createLinearGradient(0,ld.y-G.camY,0,ld.y-G.camY+14);
  g.addColorStop(0,'#5a4033');g.addColorStop(0.5,'#3d2b22');g.addColorStop(1,'#241812');
  ctx.fillStyle=g;ctx.beginPath();ctx.roundRect(ld.x,ld.y-G.camY,ld.w,14,7);ctx.fill();
  ctx.strokeStyle='rgba(255,122,26,0.8)';ctx.lineWidth=2;
  ctx.beginPath();ctx.moveTo(ld.x+6,ld.y-G.camY+2);ctx.lineTo(ld.x+ld.w-6,ld.y-G.camY+2);ctx.stroke();
  ctx.strokeStyle='rgba(0,0,0,0.4)';ctx.lineWidth=1.5;
  for(let i=0;i<3;i++){const cx=ld.x+10+((ld.w-20)*((i*0.37+0.2)%1));
    ctx.beginPath();ctx.moveTo(cx,ld.y-G.camY+5);ctx.lineTo(cx+5,ld.y-G.camY+11);ctx.stroke();}
  if(ld.vent){
    const pulse=0.5+0.5*Math.sin(G.time*8);
    ctx.fillStyle=`rgba(255,170,60,${0.35+0.4*pulse})`;ctx.shadowColor='#ff9a00';ctx.shadowBlur=0;
    ctx.beginPath();ctx.ellipse(ld.x+ld.w/2,ld.y-G.camY-4,ld.w*0.16,8,0,0,Math.PI*2);ctx.fill();
    ctx.shadowBlur=0;ctx.fillStyle='#ffd23f';ctx.font='900 13px system-ui';ctx.textAlign='center';
    ctx.fillText('♨',ld.x+ld.w/2,ld.y-G.camY+1);ctx.textAlign='left';
  }
  if(ld.flag){
    ctx.strokeStyle='#8d6e63';ctx.lineWidth=5;
    ctx.beginPath();ctx.moveTo(ld.x+ld.w/2,ld.y-G.camY);ctx.lineTo(ld.x+ld.w/2,ld.y-G.camY-64);ctx.stroke();
    const wave=Math.sin(G.time*6)*4;
    ctx.fillStyle='#ffd23f';ctx.shadowColor='#ffd23f';ctx.shadowBlur=0;
    ctx.beginPath();ctx.moveTo(ld.x+ld.w/2,ld.y-G.camY-64);
    ctx.lineTo(ld.x+ld.w/2+52+wave,ld.y-G.camY-52);
    ctx.lineTo(ld.x+ld.w/2,ld.y-G.camY-40);ctx.closePath();ctx.fill();ctx.shadowBlur=0;
  }
  ctx.restore();
}
function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#170903');bg.addColorStop(0.55,'#241005');bg.addColorStop(1,'#3a0f02');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  const f=field();
  /* caldera walls */
  ctx.fillStyle='#0d0603';
  ctx.fillRect(0,0,f.x0,H);ctx.fillRect(f.x0+f.pw,0,W-(f.x0+f.pw),H);
  ctx.fillStyle='rgba(255,106,26,0.06)';
  const off=(G.camY*0.4)%90;
  for(let y=-90+off;y<H+90;y+=90){
    ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(f.x0,y+18);ctx.lineTo(0,y+36);ctx.closePath();ctx.fill();
    ctx.beginPath();ctx.moveTo(W,y);ctx.lineTo(f.x0+f.pw,y+18);ctx.lineTo(W,y+36);ctx.closePath();ctx.fill();
  }
  /* glowing cracks on the walls */
  ctx.strokeStyle='rgba(255,110,20,0.35)';ctx.lineWidth=2;
  for(let i=0;i<6;i++){
    const wy=((i*233-G.camY*0.7)%(H+120)+(H+120))%(H+120)-60;
    const wx=i%2===0?f.x0*0.4:W-f.x0*0.4;
    ctx.beginPath();ctx.moveTo(wx,wy);ctx.lineTo(wx+(i%3-1)*14,wy+22);ctx.lineTo(wx,wy+44);ctx.stroke();
  }
  drawEmbers(W,H);
  /* lava below */
  const lavaScreenY=G.lavaY-G.camY;
  if(lavaScreenY<H+80){
    const lg=ctx.createLinearGradient(0,lavaScreenY,0,H);
    lg.addColorStop(0,'#ffe066');lg.addColorStop(0.15,'#ff8c1a');lg.addColorStop(0.5,'#e03e12');lg.addColorStop(1,'#7a1e05');
    ctx.fillStyle=lg;ctx.shadowColor='#ff6a00';ctx.shadowBlur=0;
    ctx.beginPath();ctx.moveTo(0,H);
    ctx.lineTo(0,lavaScreenY);
    for(let x=0;x<=W;x+=24)ctx.lineTo(x,lavaScreenY+Math.sin(G.time*4+x*0.05)*7);
    ctx.lineTo(W,H);ctx.closePath();ctx.fill();ctx.shadowBlur=0;
  }
  /* ledges, flag, rocks, telegraphs */
  for(const ld of G.ledges)drawLedge(ld);
  for(const t of G.tele){
    const pulse=0.4+0.6*Math.abs(Math.sin(G.time*10));
    ctx.fillStyle=`rgba(255,60,40,${0.25+0.45*pulse})`;
    ctx.beginPath();ctx.ellipse(t.x,t.y-G.camY+30,26,10,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#fff';ctx.font='900 20px system-ui';ctx.textAlign='center';
    ctx.fillText('⚠',t.x,t.y-G.camY);ctx.textAlign='left';
  }
  for(const r of G.rocks){
    const y=r.y-G.camY;if(y<-60||y>H+60)continue;
    ctx.save();ctx.translate(r.x,y);ctx.rotate(r.rot);
    ctx.fillStyle='#4a3b30';ctx.shadowColor='#000';ctx.shadowBlur=0;
    ctx.beginPath();
    for(let i=0;i<7;i++){const a=i/7*Math.PI*2,rr=r.r*(0.85+0.15*Math.sin(i*2.7));
      const px=Math.cos(a)*rr,py=Math.sin(a)*rr;i?ctx.lineTo(px,py):ctx.moveTo(px,py);}
    ctx.closePath();ctx.fill();ctx.shadowBlur=0;
    ctx.strokeStyle='rgba(0,0,0,0.5)';ctx.lineWidth=2;
    ctx.beginPath();ctx.moveTo(-r.r*0.4,-r.r*0.2);ctx.lineTo(r.r*0.3,r.r*0.35);ctx.stroke();
    ctx.restore();
  }
  /* particles */
  for(const p of G.parts){
    ctx.globalAlpha=Math.max(0,p.life/p.max);
    ctx.fillStyle=p.col;ctx.beginPath();ctx.arc(p.x,p.y-G.camY,p.r,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  /* Blaze */
  if(G.state==='play')drawBlaze(G.hero.x,G.hero.y-G.camY,G.hero.r,Math.max(-0.25,Math.min(0.25,G.hero.vx/1600)));
  /* wind arrows */
  if(G.gust>0){
    ctx.fillStyle='rgba(160,220,255,0.8)';ctx.font='900 26px system-ui';ctx.textAlign='center';
    const dir=G.gustDir>0?'→':'←';
    for(let i=0;i<4;i++)ctx.fillText(dir,W/2+(i-1.5)*70,80);
    ctx.textAlign='left';
  }
  /* hearts */
  for(let i=0;i<3;i++){
    ctx.font='20px system-ui';ctx.textAlign='left';
    ctx.globalAlpha=i<G.hearts?1:0.22;
    ctx.fillText('❤️',16+i*28,92);
  }
  ctx.globalAlpha=1;
  /* floaters */
  ctx.textAlign='center';
  for(const fl of floaters){
    if(!fl.a)continue;
    ctx.globalAlpha=Math.min(1,fl.life);
    ctx.font='900 20px system-ui';ctx.fillStyle='#000';
    ctx.fillText(fl.txt,fl.x+2,fl.y-G.camY+2);ctx.fillStyle='#ffd23f';ctx.fillText(fl.txt,fl.x,fl.y-G.camY);
  }
  ctx.globalAlpha=1;ctx.textAlign='left';
  if(G.paused){ctx.fillStyle='rgba(0,0,0,0.55)';ctx.fillRect(0,0,W,H);ctx.fillStyle='#fff';ctx.font='900 30px system-ui';ctx.textAlign='center';ctx.fillText('⏸ PAUSED',W/2,H/2);ctx.font='700 14px system-ui';ctx.fillText('Tap ⏸ or press P to keep playing',W/2,H/2+28);ctx.textAlign='left';}
}

/* loop */
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(!G.paused){
    G.time+=dt;
    if(G.state==='play')step(dt);
  }
  for(const fl of floaters){if(!fl.a)continue;fl.y-=40*dt;fl.life-=dt;if(fl.life<=0)fl.a=false;}
  render();
  requestAnimationFrame(loop);
}
resize();
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Summit Fever' — Caldera Climb's own
   track. Synthesized Web Audio only. 118 BPM, G dorian: the triangle lead
   climbs higher every bar (just like the climb), pulsing square bass, and
   drums that build bar by bar — sparse at the base, full at the summit.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-10-caldera-climb.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
const MUS={on:false,step:0,nextT:0,BPM:118,
 BASS:[43,0,43,0,43,0,46,0, 43,0,43,0,43,0,50,0, 39,0,39,0,39,0,46,0, 41,0,41,0,48,0,50,0],
 LEAD:[67,0,70,0,74,0,0,0, 74,0,77,0,79,0,0,0, 79,0,82,0,86,0,0,0, 84,0,82,0,79,0,77,74],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(MUTED||G.paused||G.state!=='play'){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);const bar=(s/8)|0;
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.16,'square',0.05,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.22,'triangle',0.06,d);
  if(s%8===0||s%8===4)tone(120,45,0.11,'sine',0.13,d); // kick
  if(bar>=1&&(s%8===2||s%8===6))noise(0.08,0.08,d,1800); // snare joins bar 2+
  if(bar===0){if(s%4===0)noise(0.02,0.015,d,6500);} // hats build with altitude
  else if(bar===1){if(s%2===0)noise(0.02,0.018,d,6500);}
  else noise(0.02,0.02,d,6500);
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

