scripts:
'use strict';
/* ============================================================
   MAGMA TRENCH DODGE v3 — 3-lane trench dodge-survival rebuild
   - Lane switching (swipe / tap sides / arrows / A,D)
   - Magma geysers telegraph (bubbles + rumble) then erupt
   - Water drops refill a shield; shield absorbs one hit
   - 3 hearts; 12 distance-goal levels; near-miss bonuses
   ============================================================ */
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();
function lerp(a,b,t){return a+(b-a)*t;}

/* audio (same helper contracts as shell) */
let AC=null,MUTED=false;try{MUTED=localStorage.getItem('fb_muted')==='1';}catch(e){}
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
function noise(dur,vol,delay=0,lp=800){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const len=ac.sampleRate*dur,buf=ac.createBuffer(1,len,ac.sampleRate),d=buf.getChannelData(0);
  for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);
  const s=ac.createBufferSource();s.buffer=buf;const f=ac.createBiquadFilter();f.type='lowpass';f.frequency.value=lp;
  const g=ac.createGain();g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  s.connect(f);f.connect(g);g.connect(ac.destination);s.start(t);}
const sfx={
  lane(){tone(300,520,0.08,'sine',0.12);},
  drop(){tone(900,1500,0.1,'sine',0.12);tone(1500,2100,0.08,'sine',0.08,0.06);},
  near(){tone(700,1400,0.15,'triangle',0.14);},
  warn(){noise(0.35,0.14,0,150);},
  erupt(){noise(0.32,0.26,0,400);},
  soak(){tone(500,180,0.2,'square',0.1);noise(0.4,0.18,0.02,1200);},
  hurt(){tone(250,75,0.35,'sawtooth',0.18);noise(0.25,0.2,0,500);},
  clear(){tone(523,523,0.12,'triangle',0.14);tone(659,659,0.12,'triangle',0.14,0.12);tone(784,784,0.2,'triangle',0.14,0.24);},
  over(){noise(0.45,0.3,0,450);tone(300,60,0.45,'sawtooth',0.18);},
  click(){tone(600,600,0.06,'square',0.1);}
};

/* level structure: 12 distance-goal levels */
const NLEVELS=12;
const LEVEL_GOALS=[150,200,250,300,360,420,480,550,620,700,780,900];
function levelSpeed(l){return 0.55+(l-1)*0.045;}
function warnZ(){return 1.1*G.speed;} /* ~1.1s of telegraph, constant across levels */

/* perspective trench geometry */
const HY=()=>H*0.20, HEROY=()=>H*0.78;
function laneSpread(z){const t=Math.max(0,Math.min(1,z/1.2));return lerp(W*0.045,W*0.30,t);}
function laneX(i,z){return W/2+(i-1)*laneSpread(z);}
function laneY(z){const t=Math.max(0,Math.min(1,z/1.2));return lerp(HY(),HEROY(),t);}
function laneScale(z){const t=Math.max(0,Math.min(1,z/1.2));return lerp(0.18,1,t);}

const G={state:'title',score:0,dist:0,best:0,speed:levelSpeed(1),time:0,
  level:1,levelDist:0,hearts:3,shield:0,shieldMeter:0,invuln:0,flash:0,shake:0,
  heroLane:1,heroPos:1,lastSwitchT:-9,lastLane:1,
  geysers:[],drops:[],geyserT:1.6,dropT:0.8,dead:false,paused:false,_df:0};
try{G.best=parseInt(localStorage.getItem('trench_best')||'0',10)||0;}catch(e){}

function reset(){
  G.score=0;G.dist=0;G.level=1;G.levelDist=0;G.hearts=3;G.shield=0;G.shieldMeter=0;
  G.invuln=0;G.flash=0;G.shake=0;G.heroLane=1;G.heroPos=1;G.lastSwitchT=-9;G.lastLane=1;
  G.geysers=[];G.drops=[];G.geyserT=1.6;G.dropT=0.8;G.speed=levelSpeed(1);
  G.time=0;G.dead=false;G.paused=false;G._df=0;
  const _pb=document.getElementById('pauseBtn');if(_pb)_pb.textContent='⏸';
  document.getElementById('best').textContent='🏆 '+G.best;
  updateHUD();updateLevel();updateHP();updateShield();
}
function updateHUD(){
  document.getElementById('score').textContent='⭐ '+G.score;
  document.getElementById('dist').textContent='🏃 '+Math.floor(G.dist)+'m';
}
function updateLevel(){document.getElementById('lvl').textContent='LV '+G.level+'/'+NLEVELS;}
function updateHP(){document.getElementById('hp').textContent='❤️'.repeat(G.hearts)+'🖤'.repeat(3-G.hearts);}
function updateShield(){document.getElementById('sh').textContent=G.shield>0?'🛡 READY':'💧 '+G.shieldMeter+'/2';}
function heroScreenX(){return laneX(G.heroPos,0);}

function switchLane(dir){
  if(G.state!=='play'||G.dead||G.paused)return;
  const nl=Math.max(0,Math.min(2,G.heroLane+dir));
  if(nl!==G.heroLane){
    G.lastLane=G.heroLane;G.heroLane=nl;G.lastSwitchT=G.time;sfx.lane();
    for(let i=0;i<5;i++)spawnP(heroScreenX(),HEROY(),-dir*60+(Math.random()-0.5)*60,-Math.random()*90,0.3,'#ffb347',3);
  }
}

/* input: swipe / tap sides / arrows / A,D */
let pStartX=null,pStartT=0;
canvas.addEventListener('pointerdown',e=>{e.preventDefault();pStartX=e.clientX;pStartT=performance.now();});
canvas.addEventListener('pointerup',e=>{
  if(pStartX===null)return;
  const dx=e.clientX-pStartX;pStartX=null;
  if(Math.abs(dx)>24)switchLane(dx>0?1:-1);
  else switchLane(e.clientX<W/2?-1:1);
});
canvas.addEventListener('pointercancel',()=>{pStartX=null;});
addEventListener('keydown',e=>{
  if(e.key==='ArrowLeft'||e.key==='a'||e.key==='A'){switchLane(-1);e.preventDefault();}
  else if(e.key==='ArrowRight'||e.key==='d'||e.key==='D'){switchLane(1);e.preventDefault();}
});

const particles=[];
for(let i=0;i<150;i++)particles.push({a:false});
function spawnP(x,y,vx,vy,life,color,size){const p=particles.find(p=>!p.a);if(!p)return;
  p.a=true;p.x=x;p.y=y;p.vx=vx;p.vy=vy;p.life=life;p.max=life;p.color=color;p.size=size;}
const floaters=[];
for(let i=0;i<10;i++)floaters.push({a:false});
function spawnText(x,y,txt,color='#ffd23f'){const f=floaters.find(f=>!f.a);if(!f)return;
  f.a=true;f.x=x;f.y=y;f.txt=txt;f.color=color;f.life=1;}

function trySpawnGeyser(){
  /* fairness: never cover all 3 lanes near the hero — at most 2 lanes threatened */
  const covered=new Set(G.geysers.filter(g=>g.z>0&&g.z<0.95).map(g=>g.lane));
  if(covered.size>=2)return;
  const free=[0,1,2].filter(l=>!covered.has(l));
  const lane=free[(Math.random()*free.length)|0];
  G.geysers.push({lane:lane,z:1.4,warned:false,erupted:false,eruptT:0,seed:Math.random()*10,gone:false});
}
function spawnDrop(){
  const lane=(Math.random()*3)|0;
  G.drops.push({lane:lane,z:1.4,prevZ:1.4,spin:Math.random()*6,taken:false,missed:false,gone:false});
}
function collectDrop(d){
  d.taken=true;d.gone=true;
  G.score+=25;sfx.drop();
  for(let i=0;i<8;i++)spawnP(laneX(d.lane,0),HEROY()-14,(Math.random()-0.5)*220,(Math.random()-0.5)*220,0.5,'#7fd4ff',4);
  if(G.shield===0){
    G.shieldMeter++;
    if(G.shieldMeter>=2){G.shield=1;G.shieldMeter=0;spawnText(heroScreenX(),HEROY()-100,'SHIELD UP! 🛡','#7fd4ff');}
  }
  updateHUD();updateShield();
}
function eruptAt(lane){
  /* near-miss: hero dodged out of this lane at the last moment */
  if(G.heroLane!==lane&&G.lastLane===lane&&(G.time-G.lastSwitchT)<0.45){
    G.score+=20;updateHUD();sfx.near();
    spawnText(heroScreenX(),HEROY()-100,'CLOSE! +20','#7fd4ff');
  }
  if(Math.round(G.heroPos)!==lane||G.invuln>0)return;
  if(G.shield>0){
    G.shield=0;G.invuln=1.4;updateShield();sfx.soak();
    for(let i=0;i<16;i++)spawnP(heroScreenX(),HEROY()-24,(Math.random()-0.5)*170,-Math.random()*180,0.85,'#bfe8ff',5);
    spawnText(heroScreenX(),HEROY()-100,'SOAKED! 💦','#bfe8ff');
    return;
  }
  G.hearts--;updateHP();sfx.hurt();G.flash=1;G.shake=0.7;G.invuln=1.6;
  spawnText(heroScreenX(),HEROY()-100,'OUCH! -1 ❤️','#ff8a8a');
  if(G.hearts<=0)die();
}
function update(dt){
  G.time+=dt;
  const sp=G.speed;
  /* smooth lane switching (frame-rate independent) */
  G.heroPos+=(G.heroLane-G.heroPos)*(1-Math.exp(-dt*11));
  if(Math.abs(G.heroLane-G.heroPos)<0.002)G.heroPos=G.heroLane;
  G.invuln=Math.max(0,G.invuln-dt);
  G.flash=Math.max(0,G.flash-dt*2.2);
  G.shake=Math.max(0,G.shake-dt*3);
  /* distance: ~21 m/s on level 1, faster as speed ramps */
  const dm=sp*dt*38;
  G.levelDist+=dm;G.dist+=dm;
  if(Math.floor(G.dist)!==G._df){G._df=Math.floor(G.dist);updateHUD();}
  if(G.levelDist>=LEVEL_GOALS[G.level-1]){levelClear();return;}
  /* spawns */
  G.geyserT-=dt;
  if(G.geyserT<=0){trySpawnGeyser();G.geyserT=Math.max(0.85,2.3-G.level*0.13)+Math.random()*0.4;}
  G.dropT-=dt;
  if(G.dropT<=0){spawnDrop();G.dropT=1.4+Math.random()*1.2;}
  /* geysers */
  const hx=heroScreenX(),hy2=HEROY();
  for(const g of G.geysers){
    g.z-=sp*dt;
    if(!g.warned&&g.z<=warnZ()){g.warned=true;sfx.warn();}
    if(g.warned&&!g.erupted){
      if(Math.random()<0.45)spawnP(laneX(g.lane,g.z)+(Math.random()-0.5)*30,laneY(g.z),0,-120-Math.random()*90,0.35,'#ff7a2a',3);
    }
    if(!g.erupted&&g.z<=0){
      g.erupted=true;g.eruptT=0.55;sfx.erupt();
      eruptAt(g.lane);
      if(G.dead)return;
    }
    if(g.erupted){
      g.eruptT-=dt;
      if(Math.random()<0.7)spawnP(laneX(g.lane,g.z)+(Math.random()-0.5)*34,laneY(g.z)-10,(Math.random()-0.5)*110,-320-Math.random()*220,0.5,'#ff4a00',5);
    }
    if(g.z<-0.25||(g.erupted&&g.eruptT<=0&&g.z<-0.1))g.gone=true;
  }
  G.geysers=G.geysers.filter(g=>!g.gone);
  /* water drops */
  for(const d of G.drops){
    d.prevZ=d.z;d.z-=sp*dt;d.spin+=dt*5;
    if(!d.taken&&d.prevZ>0&&d.z<=0){
      if(Math.round(G.heroPos)===d.lane)collectDrop(d);
      else d.missed=true;
    }
    if(d.z<-0.15)d.gone=true;
  }
  G.drops=G.drops.filter(d=>!d.gone);
  /* hero trail embers while running */
  if(Math.random()<0.35)spawnP(hx-14+ (Math.random()-0.5)*10,hy2+16,-40,-Math.random()*50,0.3,'#ffb347',3);
}
function die(){
  if(G.dead)return;
  G.dead=true;sfx.over();
  for(let i=0;i<24;i++)spawnP(heroScreenX(),HEROY()-20,(Math.random()-0.5)*360,(Math.random()-0.5)*300,0.8,'#ff7a2a',5);
  const isBest=G.score>G.best;
  if(isBest){G.best=G.score;try{localStorage.setItem('trench_best',String(G.best));}catch(e){}}
  setTimeout(()=>{
    document.getElementById('best').textContent='🏆 '+G.best;
    showOverlay('💥 WIPED OUT!',
      `${isBest?'<p style="color:#ffd23f;font-weight:900">🏆 NEW BEST!</p>':''}<p style="font-size:24px;font-weight:900">Score: ${G.score}</p><p>Level reached: ${G.level} / ${NLEVELS}</p><p>Distance: ${Math.floor(G.dist)}m</p><p>Best: ${G.best}</p>`,
      '🔥 Fire Safety: When running from danger, look where you\'re going — don\'t look back!',
      '↻ RUN AGAIN',()=>{reset();G.state='play';});
  },700);
}
function levelClear(){
  const done=G.level,bonus=100*done;
  G.score+=bonus;updateHUD();sfx.clear();
  const isBest=G.score>G.best;
  if(isBest){G.best=G.score;try{localStorage.setItem('trench_best',String(G.best));}catch(e){}}
  document.getElementById('best').textContent='🏆 '+G.best;
  if(done>=NLEVELS){
    G.state='over';
    showOverlay('🏆 TRENCH MASTER!',
      `${isBest?'<p style="color:#ffd23f;font-weight:900">🏆 NEW BEST!</p>':''}<p style="font-size:24px;font-weight:900">Final Score: ${G.score}</p><p>All 12 levels cleared!</p><p>Distance: ${Math.floor(G.dist)}m</p><p>Best: ${G.best}</p>`,
      '🔥 Fire Safety: Geysers and volcanoes are amazing from far away — if the ground rumbles, move away and tell a grown-up!',
      '↻ PLAY AGAIN',()=>{reset();G.state='play';});
    return;
  }
  G.state='clear';
  showOverlay('🌊 LEVEL '+done+' CLEAR!',
    `<p style="font-size:22px;font-weight:900">Clear bonus +${bonus}</p><p>Score: ${G.score}</p><p>Total distance: ${Math.floor(G.dist)}m</p><p>Next goal: ${LEVEL_GOALS[done]}m — faster magma ahead!</p>`,
    '🔥 Fire Safety: Real geysers erupt with super-hot water — always stay on the boardwalk and hold a grown-up\'s hand!',
    'NEXT ▶',()=>{
      G.level=done+1;G.levelDist=0;G.hearts=3;G.shield=0;G.shieldMeter=0;G.invuln=0;G.flash=0;
      G.geysers=[];G.drops=[];G.geyserT=1.6;G.dropT=0.8;G.speed=levelSpeed(G.level);
      G.heroLane=1;G.heroPos=1;G.lastSwitchT=-9;G.lastLane=1;
      updateHUD();updateLevel();updateHP();updateShield();
      G.state='play';
    });
}

/* overlay (shell contract) */
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();reset();G.state='play';overlay.classList.add('hidden');}
obtn.onclick=()=>{showMathGate();};

/* pause / mute / restart (shell contracts) */
function setPaused(p){G.paused=!!(p&&G.state==='play');const b=document.getElementById('pauseBtn');if(b)b.textContent=G.paused?'▶':'⏸';}
document.getElementById('pauseBtn').addEventListener('click',e=>{e.currentTarget.blur();setPaused(!G.paused);sfx.click();});
const muteBtnEl=document.getElementById('muteBtn');muteBtnEl.textContent=MUTED?'🔇':'🔊';
muteBtnEl.addEventListener('click',e=>{e.currentTarget.blur();MUTED=!MUTED;muteBtnEl.textContent=MUTED?'🔇':'🔊';try{localStorage.setItem('fb_muted',MUTED?'1':'0');}catch(err){}if(!MUTED)sfx.click();});
document.getElementById('restartBtn').addEventListener('click',e=>{e.currentTarget.blur();if(G.state==='title')return;sfx.click();reset();G.state='play';overlay.classList.add('hidden');});
addEventListener('keydown',e=>{if(e.key==='p'||e.key==='P'||e.key==='Escape')setPaused(!G.paused);if(e.key==='m'||e.key==='M')muteBtnEl.click();});

/* render */
/* living embers (shell background accent) */
const EMBER_SEEDS=Array.from({length:24},(_,i)=>({x:(i*0.61803)%1,y:(i*0.754877)%1,s:1+((i*7)%3),v:12+((i*13)%24),d:((i*29)%20)-10}));
function makeGlowSprite(hex){const c=document.createElement('canvas');c.width=c.height=96;const x=c.getContext('2d');
  const r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);
  const gr=x.createRadialGradient(48,48,0,48,48,48);
  gr.addColorStop(0,`rgba(${r},${g},${b},0.9)`);gr.addColorStop(0.35,`rgba(${r},${g},${b},0.38)`);gr.addColorStop(1,`rgba(${r},${g},${b},0)`);
  x.fillStyle=gr;x.fillRect(0,0,96,96);return c;}
const EMBER_SPRITE=makeGlowSprite('#ff9a3a');
function drawEmbers(bw,bh){ctx.save();ctx.globalCompositeOperation='lighter';const t=(typeof G!=='undefined'&&G.time)||0;
  for(const e of EMBER_SEEDS){const ey=bh-((e.y*bh+t*e.v)%bh);const ex=e.x*bw+Math.sin(t*0.7+e.y*9)*e.d;
    ctx.globalAlpha=0.13+0.09*Math.sin(t*2+e.y*20);
    const r=e.s*7;ctx.drawImage(EMBER_SPRITE,ex-r,ey-r,r*2,r*2);}
  ctx.restore();}

function drawTrench(hy,heroY){
  /* trench floor: perspective quad between outer lane edges */
  const fx0=laneX(0,1.2)-22,fx1=laneX(2,1.2)+22,bx0=laneX(0,0)-46,bx1=laneX(2,0)+46,by=heroY+H*0.16;
  const fg=ctx.createLinearGradient(0,hy,0,by);
  fg.addColorStop(0,'#2a1208');fg.addColorStop(0.55,'#4a2410');fg.addColorStop(1,'#5e2a0e');
  ctx.fillStyle=fg;
  ctx.beginPath();ctx.moveTo(fx0,hy);ctx.lineTo(fx1,hy);ctx.lineTo(bx1,by);ctx.lineTo(bx0,by);ctx.closePath();ctx.fill();
  /* rocky walls left and right */
  const wg=ctx.createLinearGradient(0,hy,0,by);
  wg.addColorStop(0,'#0c0508');wg.addColorStop(1,'#241016');
  ctx.fillStyle=wg;
  ctx.beginPath();ctx.moveTo(0,hy);ctx.lineTo(fx0,hy);ctx.lineTo(bx0,by);ctx.lineTo(0,by);ctx.closePath();ctx.fill();
  ctx.beginPath();ctx.moveTo(W,hy);ctx.lineTo(fx1,hy);ctx.lineTo(bx1,by);ctx.lineTo(W,by);ctx.closePath();ctx.fill();
  /* magma glow creeping up the wall bases */
  ctx.fillStyle='rgba(255,74,0,0.20)';
  ctx.beginPath();ctx.moveTo(fx0,hy);ctx.lineTo(bx0,by);ctx.lineTo(bx0,by-26);ctx.lineTo(fx0,hy+6);ctx.closePath();ctx.fill();
  ctx.beginPath();ctx.moveTo(fx1,hy);ctx.lineTo(bx1,by);ctx.lineTo(bx1,by-26);ctx.lineTo(fx1,hy+6);ctx.closePath();ctx.fill();
  /* glowing lava cracks scrolling on the floor */
  ctx.fillStyle='#ff4a00';
  for(let i=0;i<8;i++){
    const z=((i*0.618+G.time*G.speed*0.55)%1.15);
    const t=z/1.2,s=laneScale(z);
    const cx=lerp(laneX(0,z)+16,laneX(2,z)-16,(i*0.377)%1);
    ctx.globalAlpha=0.25+0.3*Math.sin(G.time*5+i*2)*0.5+0.2;
    ctx.fillRect(cx,laneY(z)+10*s,26*s,3.5*s);
  }
  ctx.globalAlpha=1;
  /* lane guide lines */
  ctx.strokeStyle='rgba(255,170,60,0.28)';ctx.lineWidth=2;
  for(let i=0;i<3;i++){
    ctx.beginPath();ctx.moveTo(laneX(i,1.2),hy);ctx.lineTo(laneX(i,0),by);ctx.stroke();
  }
  /* outer edge lines, brighter */
  ctx.strokeStyle='rgba(255,120,30,0.5)';ctx.lineWidth=3;
  ctx.beginPath();ctx.moveTo(fx0,hy);ctx.lineTo(bx0,by);ctx.stroke();
  ctx.beginPath();ctx.moveTo(fx1,hy);ctx.lineTo(bx1,by);ctx.stroke();
}
function drawGeyser(g){
  const s=laneScale(g.z),x=laneX(g.lane,g.z),y=laneY(g.z);
  if(g.erupted){
    /* magma column */
    const h=215*s;
    const lg=ctx.createLinearGradient(0,y,0,y-h);
    lg.addColorStop(0,'#ffdd44');lg.addColorStop(0.4,'#ff6a00');lg.addColorStop(1,'rgba(255,74,0,0.08)');
    ctx.fillStyle=lg;
    const wob=Math.sin(G.time*26+g.seed)*7*s,wdt=30*s;
    ctx.beginPath();
    ctx.moveTo(x-wdt,y);ctx.lineTo(x-wdt*0.6+wob,y-h);
    ctx.lineTo(x+wdt*0.6+wob,y-h);ctx.lineTo(x+wdt,y);
    ctx.closePath();ctx.fill();
    /* fiery crown */
    ctx.fillStyle='rgba(255,180,40,0.85)';
    ctx.beginPath();ctx.ellipse(x+wob,y-h,13*s,5*s,0,0,Math.PI*2);ctx.fill();
  }else if(g.warned){
    /* telegraph: bubbling glow in the lane + warning mark */
    const a=0.45+Math.sin(G.time*14)*0.3;
    ctx.fillStyle=`rgba(255,74,0,${a})`;
    ctx.beginPath();ctx.ellipse(x,y+6*s,34*s,11*s,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle=`rgba(255,170,40,${a})`;
    ctx.beginPath();ctx.ellipse(x,y+6*s,20*s,7*s,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#fff';ctx.font='900 '+Math.round(22*s+4)+'px system-ui';ctx.textAlign='center';
    ctx.fillText('!',x,y-16*s);
    ctx.textAlign='left';
  }
}
function drawDrop(d){
  const s=laneScale(d.z),x=laneX(d.lane,d.z),y=laneY(d.z)-16*s+Math.sin(d.spin)*3*s,r=13*s;
  ctx.save();ctx.translate(x,y);
  const g=ctx.createLinearGradient(0,-r,0,r);
  g.addColorStop(0,'#d6f4ff');g.addColorStop(0.5,'#5ab8e8');g.addColorStop(1,'#2273b8');
  ctx.fillStyle=g;
  ctx.beginPath();
  ctx.moveTo(0,-r*1.25);
  ctx.quadraticCurveTo(r,r*0.5,0,r);
  ctx.quadraticCurveTo(-r,r*0.5,0,-r*1.25);
  ctx.fill();
  ctx.strokeStyle='rgba(255,255,255,0.75)';ctx.lineWidth=2;ctx.stroke();
  ctx.fillStyle='rgba(255,255,255,0.85)';
  ctx.beginPath();ctx.ellipse(-r*0.3,0,r*0.18,r*0.3,-0.4,0,Math.PI*2);ctx.fill();
  ctx.restore();
}
function drawHero(heroY){
  if(G.dead)return;
  const px=heroScreenX(),py=heroY;
  const lean=(G.heroLane-G.heroPos)*0.45;
  /* shadow */
  ctx.fillStyle='rgba(0,0,0,0.32)';
  ctx.beginPath();ctx.ellipse(px,py+26,24,7,0,0,Math.PI*2);ctx.fill();
  ctx.save();ctx.translate(px,py);ctx.rotate(lean);
  if(G.invuln>0)ctx.globalAlpha=0.55+0.35*Math.sin(G.time*30);
  /* running feet */
  const lp=Math.sin(G.time*16)*7;
  ctx.fillStyle='#8a2a10';
  ctx.beginPath();ctx.ellipse(-9+lp,24,7,4.5,0,0,Math.PI*2);ctx.fill();
  ctx.beginPath();ctx.ellipse(9-lp,24,7,4.5,0,0,Math.PI*2);ctx.fill();
  /* flame-teardrop body (approved Fire Babys look) */
  ctx.shadowColor='#ff7a2a';ctx.shadowBlur=18;
  const g=ctx.createRadialGradient(-7,-10,4,0,-2,27);
  g.addColorStop(0,'#ffe9a0');g.addColorStop(0.5,'#ff7a2a');g.addColorStop(1,'#d42a1a');
  ctx.fillStyle=g;
  ctx.beginPath();
  ctx.moveTo(0,-30);
  ctx.quadraticCurveTo(17,-12,20,2);
  ctx.quadraticCurveTo(22,18,10,23);
  ctx.quadraticCurveTo(0,27,-10,23);
  ctx.quadraticCurveTo(-22,18,-20,2);
  ctx.quadraticCurveTo(-17,-12,0,-30);
  ctx.fill();
  ctx.shadowBlur=0;
  ctx.strokeStyle='#7a1e08';ctx.lineWidth=2.5;ctx.stroke();
  /* flame licks */
  ctx.fillStyle='#ffcf3f';
  const w=Math.sin(G.time*13)*2.5;
  ctx.beginPath();ctx.moveTo(-6,-26);ctx.quadraticCurveTo(w,-40,5,-27);ctx.quadraticCurveTo(0,-32,-6,-26);ctx.fill();
  /* face: determined hero (angry V brows, glaring eyes, brave grin) */
  ctx.strokeStyle='#2b1a0e';ctx.lineWidth=3;ctx.lineCap='round';
  ctx.beginPath();ctx.moveTo(-12,-8);ctx.lineTo(-4,-3);ctx.stroke();
  ctx.beginPath();ctx.moveTo(12,-8);ctx.lineTo(4,-3);ctx.stroke();
  ctx.fillStyle='#fff';
  ctx.beginPath();ctx.arc(-6.5,0.5,3.6,0,Math.PI*2);ctx.arc(6.5,0.5,3.6,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#c81e05';
  ctx.beginPath();ctx.arc(-6.5,0.8,1.8,0,Math.PI*2);ctx.arc(6.5,0.8,1.8,0,Math.PI*2);ctx.fill();
  ctx.strokeStyle='#2b1a0e';ctx.lineWidth=2.5;
  ctx.beginPath();ctx.moveTo(-5,10);ctx.quadraticCurveTo(0,14,6,9);ctx.stroke();
  ctx.restore();
  /* shield bubble */
  if(G.shield>0){
    ctx.save();ctx.globalAlpha=0.5+0.18*Math.sin(G.time*6);
    ctx.strokeStyle='#7fd4ff';ctx.lineWidth=3;
    ctx.fillStyle='rgba(127,212,255,0.13)';
    ctx.beginPath();ctx.arc(px,py-2,38,0,Math.PI*2);ctx.fill();ctx.stroke();
    ctx.restore();
  }
}
function render(){
  const sky=ctx.createLinearGradient(0,0,0,H);
  sky.addColorStop(0,'#160a1e');sky.addColorStop(0.5,'#4a1620');sky.addColorStop(1,'#8a2a10');
  ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
  drawEmbers(W,H);
  const hy=HY(),heroY=HEROY();
  /* distant volcano */
  ctx.fillStyle='#120812';
  const vx=W*0.5;
  ctx.beginPath();ctx.moveTo(vx-110,hy);ctx.lineTo(vx,hy-92);ctx.lineTo(vx+110,hy);ctx.closePath();ctx.fill();
  ctx.fillStyle='#ff4a00';
  ctx.beginPath();ctx.ellipse(vx,hy-90,15,4.5,0,0,Math.PI*2);ctx.fill();
  ctx.save();
  if(G.shake>0)ctx.translate((Math.random()-0.5)*G.shake*14,(Math.random()-0.5)*G.shake*10);
  drawTrench(hy,heroY);
  /* entities far-to-near */
  const ents=[];
  for(const g of G.geysers)ents.push({z:g.z,k:0,o:g});
  for(const d of G.drops)ents.push({z:d.z,k:1,o:d});
  ents.sort((a,b)=>b.z-a.z);
  for(const e of ents){if(e.k===0)drawGeyser(e.o);else drawDrop(e.o);}
  drawHero(heroY);
  /* particles */
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  /* floaters */
  ctx.textAlign='center';
  for(const f of floaters){
    if(!f.a)continue;
    ctx.globalAlpha=Math.min(1,f.life);
    ctx.font='900 18px system-ui';ctx.fillStyle='#000';
    ctx.fillText(f.txt,f.x+2,f.y+2);ctx.fillStyle=f.color;ctx.fillText(f.txt,f.x,f.y);
  }
  ctx.globalAlpha=1;ctx.textAlign='left';
  /* hurt flash */
  if(G.flash>0){ctx.fillStyle=`rgba(255,40,20,${(G.flash*0.32).toFixed(3)})`;ctx.fillRect(-20,-20,W+40,H+40);}
  ctx.restore();
  if(G.paused){ctx.fillStyle='rgba(0,0,0,0.5)';ctx.fillRect(0,0,W,H);ctx.fillStyle='#fff';ctx.font='900 36px system-ui';ctx.textAlign='center';ctx.fillText('⏸ PAUSED',W/2,H/2);ctx.font='700 16px system-ui';ctx.fillText('Tap ⏸ or press P to keep running',W/2,H/2+32);ctx.textAlign='left';}
}

/* loop */
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(G.state==='play'&&!G.dead&&!G.paused)update(dt);else G.time+=dt*0.3;
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=800*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  for(const f of floaters){if(!f.a)continue;f.y-=40*dt;f.life-=dt;if(f.life<=0)f.a=false;}
  render();
  requestAnimationFrame(loop);
}
document.getElementById('best').textContent='🏆 '+G.best;
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Trench Runner' — Magma Trench Dodge's
   own track. Synthesized Web Audio only. 132 BPM, D phrygian: syncopated
   sawtooth bass with that menacing ♭2 bite, sparse square stab lead,
   off-beat war-kick and ticking hats — geyser-dodging tension.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-11-magma-trench-dodge.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
const MUS={on:false,step:0,nextT:0,BPM:132,
 BASS:[38,0,38,39,0,38,0,0, 38,0,38,39,0,41,0,0, 36,0,36,38,0,36,0,0, 34,0,38,0,41,0,43,0],
 LEAD:[74,0,0,74,0,0,75,0, 74,0,0,0,0,70,0,0, 72,0,0,72,0,0,74,0, 75,0,0,74,0,0,0,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(MUTED||G.paused||G.state!=='play'){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.13,'sawtooth',0.065,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.14,'square',0.045,d);
  if(s%8===0||s%8===3||s%8===6)tone(118,40,0.13,'sine',0.15,d); // syncopated kick
  if(s%8===4)noise(0.08,0.08,d,1700); // snare
  noise(0.018,0.016,d,7200); // ticking hats
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

