scripts:
'use strict';
/* ============================================================
   VOLCANIC PINBALL v2 — AAA Rebuild
   - Real flipper physics, bumpers, slingshots, lanes
   - 3 balls, combo multiplier, tilt nudge
   ============================================================ */
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR,TABLE={x:0,y:0,w:0,h:0};
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);
  const tw=Math.min(W*0.92,420),th=Math.min(H*0.86,700);
  TABLE={x:(W-tw)/2,y:(H-th)/2+10,w:tw,h:th};}
addEventListener('resize',resize);resize();

/* audio */
let AC=null,MUTED=false;try{MUTED=localStorage.getItem('fb_muted')==='1';}catch(e){}
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  flip(){tone(300,500,0.06,'square',0.1);},
  bumper(){tone(800,1200,0.08,'square',0.14);tone(1200,1600,0.06,'sine',0.1,0.03);},
  sling(){tone(500,800,0.08,'square',0.12);},
  drain(){tone(400,80,0.5,'sawtooth',0.18);},
  launch(){tone(200,800,0.3,'sawtooth',0.14);},
  click(){tone(600,600,0.06,'square',0.1);}
};

/* table layout (relative) */
let _lay=null,_layKey='';
function layout(){
  const T=TABLE;
  const key=T.x+','+T.y+','+T.w+','+T.h;
  if(_lay&&key===_layKey)return _lay; // persistent: flipper/bumper/sling state must survive between calls
  _layKey=key;
  _lay={
    bumpers:[
      {x:T.x+T.w*0.3,y:T.y+T.h*0.22,r:26,pts:100},{x:T.x+T.w*0.7,y:T.y+T.h*0.22,r:26,pts:100},
      {x:T.x+T.w*0.5,y:T.y+T.h*0.34,r:26,pts:100},
      {x:T.x+T.w*0.5,y:T.y+T.h*0.12,r:18,pts:125,special:'nova'},
    ],
    slings:[
      {x:T.x+T.w*0.28,y:T.y+T.h*0.62,w:44,h:80,side:-1,cool:0},
      {x:T.x+T.w*0.72,y:T.y+T.h*0.62,w:44,h:80,side:1,cool:0},
    ],
    flipL:{x:T.x+T.w*0.36,y:T.y+T.h*0.86,len:T.w*0.22,ang:0.5,active:false},
    flipR:{x:T.x+T.w*0.64,y:T.y+T.h*0.86,len:T.w*0.22,ang:-0.5,active:false},
    drainY:T.y+T.h*0.98,
    launchX:T.x+T.w*0.92,
  };
  return _lay;
}

const G={state:'title',score:0,best:0,balls:3,combo:1,comboT:0,
  ball:null,time:0,shake:0,nudge:0,shield:false,paused:false,stuckT:0,nudgeCool:0};
try{G.best=parseInt(localStorage.getItem('pinball_best')||'0',10)||0;}catch(e){}
const GRAV=1400;

function newBall(){
  const L=layout();
  G.ball={x:L.launchX,y:TABLE.y+TABLE.h*0.7,vx:0,vy:0,r:11,launched:false,trail:[]};
}
function launchBall(){
  if(!G.ball||G.ball.launched)return;
  G.ball.launched=true;G.ball.vy=-1500;
  sfx.launch();
}
function updateHUD(){
  document.getElementById('score').textContent='⭐ '+G.score;
  document.getElementById('balls').textContent='🔴 '+G.balls+(G.shield?' 🛡️':'');
  document.getElementById('best').textContent='🏆 '+G.best;
}
function addScore(pts,x,y){
  const p=Math.round(pts*G.combo);
  G.score+=p;updateHUD();
  spawnText(x,y,'+'+p);
}

/* input */
function setFlip(side,down){
  const L=layout();
  const f=side==='L'?L.flipL:L.flipR;
  if(down&&!f.active){f.active=true;sfx.flip();}
  else if(!down)f.active=false;
}
document.getElementById('flipL').addEventListener('pointerdown',e=>{e.preventDefault();setFlip('L',true);});
document.getElementById('flipL').addEventListener('pointerup',()=>setFlip('L',false));
document.getElementById('flipR').addEventListener('pointerdown',e=>{e.preventDefault();setFlip('R',true);});
document.getElementById('flipR').addEventListener('pointerup',()=>setFlip('R',false));
addEventListener('keydown',e=>{
  if(e.key==='ArrowLeft'||e.key==='z')setFlip('L',true);
  if(e.key==='ArrowRight'||e.key==='/')setFlip('R',true);
  if(e.key===' '&&G.ball&&!G.ball.launched)launchBall();
  if(e.key==='ArrowDown'&&G.ball&&G.ball.launched&&G.nudgeCool<=0&&G.state==='play'&&!G.paused){
    G.nudgeCool=1.5;G.ball.vy-=170;G.shake=Math.max(G.shake,0.25);tone(300,500,0.08,'square',0.08);}
});
addEventListener('keyup',e=>{
  if(e.key==='ArrowLeft'||e.key==='z')setFlip('L',false);
  if(e.key==='ArrowRight'||e.key==='/')setFlip('R',false);
});
canvas.addEventListener('pointerdown',e=>{
  if(G.ball&&!G.ball.launched)launchBall();
});

/* physics */
const particles=[],floaters=[];
for(let i=0;i<120;i++)particles.push({a:false});
for(let i=0;i<15;i++)floaters.push({a:false});
function spawnP(x,y,vx,vy,life,color,size){const p=particles.find(p=>!p.a);if(!p)return;
  p.a=true;p.x=x;p.y=y;p.vx=vx;p.vy=vy;p.life=life;p.max=life;p.color=color;p.size=size;}
function spawnText(x,y,txt){const f=floaters.find(f=>!f.a);if(!f)return;
  f.a=true;f.x=x;f.y=y;f.txt=txt;f.life=1;}

// compute flipper segment
function flipSeg(f,isLeft,adv){
  const rest=isLeft?0.45:-0.45,act=isLeft?-0.5:0.5;
  const target=f.active?act:rest;
  if(adv)f.ang+=(target-f.ang)*0.55; // physics advances in update() only — render() must not move flippers
  const dx=Math.cos(f.ang)*f.len*(isLeft?1:-1);
  const dy=Math.sin(f.ang)*f.len*(isLeft?-1:1)*-1;
  // left flipper: pivot left, tip goes up-right when active
  if(isLeft)return{x1:f.x,y1:f.y,x2:f.x+Math.cos(-f.ang)*f.len,y2:f.y-Math.sin(-f.ang)*f.len};
  return{x1:f.x,y1:f.y,x2:f.x-Math.cos(-f.ang)*f.len,y2:f.y-Math.sin(-f.ang)*f.len};
}
function distToSeg(px,py,x1,y1,x2,y2){
  const dx=x2-x1,dy=y2-y1,L2=dx*dx+dy*dy;
  let t=L2?((px-x1)*dx+(py-y1)*dy)/L2:0;
  t=Math.max(0,Math.min(1,t));
  return{x:x1+t*dx,y:y1+t*dy,d:Math.hypot(px-(x1+t*dx),py-(y1+t*dy))};
}
function update(dt){
  G.time+=dt;
  G.comboT-=dt;if(G.comboT<=0)G.combo=1;
  G.shake=Math.max(0,G.shake-dt*3);
  const L=layout(),b=G.ball;
  if(!b||G.state!=='play')return;
  if(!b.launched){
    b.y=TABLE.y+TABLE.h*0.7+Math.sin(G.time*3)*4;
    return;
  }
  b.vy+=GRAV*dt;
  b.x+=b.vx*dt;b.y+=b.vy*dt;
  b.vx*=0.999;
  // trail
  b.trail.push({x:b.x,y:b.y});if(b.trail.length>8)b.trail.shift();
  const T=TABLE;
  // walls
  if(b.x-b.r<T.x+4){b.x=T.x+4+b.r;b.vx=Math.abs(b.vx)*0.9;}
  if(b.x+b.r>T.x+T.w-4){b.x=T.x+T.w-4-b.r;b.vx=-Math.abs(b.vx)*0.9;}
  if(b.y-b.r<T.y+4){b.y=T.y+4+b.r;b.vy=Math.abs(b.vy)*0.9;}
  // plunger lane: the curved top deflects the ball left into the playfield;
  // the divider is solid from the playfield side so the ball can't fall back into the lane
  const laneX=L.launchX-14;
  if(b.x>laneX&&b.y<T.y+T.h*0.30)b.vx-=2600*dt;
  else if(b.x<laneX&&b.x+b.r>laneX&&b.y>T.y+T.h*0.30){b.x=laneX-b.r;b.vx=-Math.abs(b.vx)*0.85;}
  // bumpers
  for(const bp of L.bumpers){
    const d=Math.hypot(b.x-bp.x,b.y-bp.y);
    if(d<b.r+bp.r){
      const nx=(b.x-bp.x)/d,ny=(b.y-bp.y)/d;
      const sp=Math.max(500,Math.hypot(b.vx,b.vy)*1.1);
      b.vx=nx*sp;b.vy=ny*sp;
      b.x=bp.x+nx*(bp.r+b.r);b.y=bp.y+ny*(bp.r+b.r);
      G.combo=Math.min(8,G.combo+0.5);G.comboT=3;
      addScore(bp.pts||100,bp.x,bp.y-30);
      if(bp.special==='nova'&&!G.shield){G.shield=true;updateHUD();spawnText(bp.x,bp.y-50,'🛡️ EMBER SHIELD!');tone(900,1500,0.2,'sine',0.14);}
      sfx.bumper();G.shake=0.35;
      bp.flash=0.3;
      for(let i=0;i<8;i++)spawnP(bp.x,bp.y,(Math.random()-0.5)*300,(Math.random()-0.5)*300,0.4,'#ffd23f',4);
    }
    bp.flash=Math.max(0,(bp.flash||0)-dt);
  }
  // slingshots
  for(const s of L.slings){
    s.cool=Math.max(0,(s.cool||0)-dt);
    if(s.cool<=0&&b.x>s.x-s.w/2&&b.x<s.x+s.w/2&&b.y>s.y-s.h/2&&b.y<s.y+s.h/2){
      s.cool=0.3;
      b.vx=s.side*380;b.vy=-420;
      sfx.sling();G.shake=0.2;
      addScore(50,s.x,s.y-40);
    }
  }
  // flippers
  const fl=flipSeg(L.flipL,true,true),fr=flipSeg(L.flipR,false,true);
  for(const [seg,isL] of [[fl,true],[fr,false]]){
    const c=distToSeg(b.x,b.y,seg.x1,seg.y1,seg.x2,seg.y2);
    if(c.d<b.r+6){
      const f=isL?L.flipL:L.flipR;
      const power=f.active?1050:250;
      // hit direction: perpendicular to flipper
      const dx=seg.x2-seg.x1,dy=seg.y2-seg.y1,len=Math.hypot(dx,dy)||1;
      let nx=-dy/len,ny=dx/len;
      if(ny>0){nx=-nx;ny=-ny;}
      b.vx=nx*power+(isL?120:-120);b.vy=ny*power;
      b.x=c.x+nx*(b.r+7);b.y=c.y+ny*(b.r+7);
      if(f.active){G.combo=Math.min(8,G.combo+0.25);G.comboT=3;addScore(25,b.x,b.y-20);}
      sfx.flip();
    }
  }
  // anti-stuck: a ball resting somewhere safe for >2.5s gets a gentle nudge (pinball staple)
  G.nudgeCool=Math.max(0,G.nudgeCool-dt);
  const spdNow=Math.hypot(b.vx,b.vy);
  if(spdNow<50&&b.y<L.drainY-40){G.stuckT+=dt;
    if(G.stuckT>2.5){G.stuckT=0;b.vy-=380;b.vx+=(Math.random()<0.5?-140:140);spawnText(b.x,b.y-24,'NUDGE!');tone(500,900,0.12,'sine',0.1);}}
  else G.stuckT=0;
  // drain
  if(b.y>L.drainY){
    sfx.drain();
    for(let i=0;i<12;i++)spawnP(b.x,TABLE.y+TABLE.h,(Math.random()-0.5)*200,-Math.random()*200,0.5,'#ff4a5a',4);
    if(G.shield){
      G.shield=false;G.combo=1;updateHUD();
      spawnText(b.x,TABLE.y+TABLE.h*0.7,'🛡️ SHIELD SAVE!');tone(700,1400,0.25,'sine',0.14);
      newBall();
    }else{
      G.balls--;G.combo=1;updateHUD();
      if(G.balls<=0)gameOver();
      else{newBall();}
    }
  }
}
function gameOver(){
  G.state='over';
  const isBest=G.score>G.best;
  if(isBest){G.best=G.score;try{localStorage.setItem('pinball_best',String(G.best));}catch(e){}}
  setTimeout(()=>{
    showOverlay('💥 GAME OVER',
      `${isBest?'<p style="color:#ffd23f;font-weight:900">🏆 NEW BEST!</p>':''}<p style="font-size:24px;font-weight:900">Score: ${G.score}</p><p>Best: ${G.best}</p>`,
      '🔥 Fire Safety: Pinball is electric fun — never touch real electrical panels!',
      '↻ PLAY AGAIN',()=>{G.score=0;G.balls=3;G.combo=1;G.shield=false;newBall();G.state='play';updateHUD();});
  },600);
}

/* overlay */
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();G.score=0;G.balls=3;G.combo=1;G.shield=false;newBall();G.state='play';overlay.classList.add('hidden');updateHUD();setPaused(false);}
obtn.onclick=()=>{showMathGate();};

/* pause / mute / restart (gamer-check batch 03) */
function setPaused(p){G.paused=!!(p&&G.state==='play');const b=document.getElementById('pauseBtn');if(b)b.textContent=G.paused?'▶':'⏸';}
document.getElementById('pauseBtn').addEventListener('click',e=>{e.currentTarget.blur();setPaused(!G.paused);sfx.click();});
const muteBtnEl=document.getElementById('muteBtn');muteBtnEl.textContent=MUTED?'🔇':'🔊';
muteBtnEl.addEventListener('click',e=>{e.currentTarget.blur();MUTED=!MUTED;muteBtnEl.textContent=MUTED?'🔇':'🔊';try{localStorage.setItem('fb_muted',MUTED?'1':'0');}catch(err){}if(!MUTED)sfx.click();});
document.getElementById('restartBtn').addEventListener('click',e=>{e.currentTarget.blur();if(G.state==='title')return;sfx.click();G.score=0;G.balls=3;G.combo=1;G.shield=false;G.stuckT=0;newBall();G.state='play';overlay.classList.add('hidden');updateHUD();setPaused(false);});
addEventListener('keydown',e=>{if(e.key==='p'||e.key==='P'||e.key==='Escape')setPaused(!G.paused);if(e.key==='m'||e.key==='M')muteBtnEl.click();});

/* render */
/* living embers (overhaul) */
const EMBER_SEEDS=Array.from({length:24},(_,i)=>({x:(i*0.61803)%1,y:(i*0.754877)%1,s:1+((i*7)%3),v:12+((i*13)%24),d:((i*29)%20)-10}));
/* [w5c perf] Pre-baked glow sprites — the W5b-proven pattern copied from game-04:
   the ember loop's 24 per-frame shadowBlur=8 fills collapsed FPS under software
   rendering (10.0 FPS); blit a one-time radial-glow sprite instead. Colours,
   falloff and alpha unchanged; no gameplay/balance changes. */
function makeGlowSprite(hex){const c=document.createElement('canvas');c.width=c.height=96;const x=c.getContext('2d');
  const r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);
  const gr=x.createRadialGradient(48,48,0,48,48,48);
  gr.addColorStop(0,`rgba(${r},${g},${b},0.9)`);gr.addColorStop(0.35,`rgba(${r},${g},${b},0.38)`);gr.addColorStop(1,`rgba(${r},${g},${b},0)`);
  x.fillStyle=gr;x.fillRect(0,0,96,96);return c;}
const EMBER_SPRITE=makeGlowSprite('#ff9a3a');
function drawEmbers(bw,bh){ctx.save();ctx.globalCompositeOperation='lighter';const t=(typeof G!=='undefined'&&G.time)||0;
  for(const e of EMBER_SEEDS){const ey=bh-((e.y*bh+t*e.v)%bh);const ex=e.x*bw+Math.sin(t*0.7+e.y*9)*e.d;
    ctx.globalAlpha=0.13+0.09*Math.sin(t*2+e.y*20);
    const r=e.s*7;ctx.drawImage(EMBER_SPRITE,ex-r,ey-r,r*2,r*2);} // [w5c perf] pre-baked glow (was shadowBlur=8 per ember per frame)
  ctx.restore();}
function render(){
  const bgG=ctx.createLinearGradient(0,0,0,H);
  bgG.addColorStop(0,'#1c1030');bgG.addColorStop(0.6,'#0d0a14');bgG.addColorStop(1,'#2a0f08');
  ctx.fillStyle=bgG;ctx.fillRect(0,0,W,H);
  drawEmbers(W,H);
  const T=TABLE,L=layout();
  ctx.save();
  if(G.shake>0)ctx.translate((Math.random()-0.5)*G.shake*16,(Math.random()-0.5)*G.shake*16);
  // table
  const tg=ctx.createLinearGradient(0,T.y,0,T.y+T.h);
  tg.addColorStop(0,'#1a1030');tg.addColorStop(1,'#0d0a1a');
  ctx.fillStyle=tg;
  ctx.beginPath();ctx.roundRect(T.x,T.y,T.w,T.h,24);ctx.fill();
  ctx.strokeStyle='#ff6a1a';ctx.lineWidth=4;ctx.stroke();
  // inner decorations: volcano
  ctx.fillStyle='rgba(255,106,0,0.08)';
  ctx.beginPath();ctx.arc(T.x+T.w/2,T.y+T.h*0.12,60,0,Math.PI*2);ctx.fill();
  // plunger lane
  ctx.strokeStyle='rgba(255,255,255,0.2)';ctx.lineWidth=2;
  ctx.beginPath();ctx.moveTo(L.launchX-14,T.y+T.h*0.3);ctx.lineTo(L.launchX-14,T.y+T.h);ctx.stroke();
  ctx.fillStyle='rgba(255,255,255,0.3)';ctx.font='12px system-ui';ctx.textAlign='center';
  ctx.fillText('TAP TO LAUNCH',L.launchX,T.y+T.h*0.5);
  ctx.textAlign='left';
  // bumpers
  for(const bp of L.bumpers){
    const fl=bp.flash||0;
    const g=ctx.createRadialGradient(bp.x-8,bp.y-8,4,bp.x,bp.y,bp.r);
    g.addColorStop(0,fl>0?'#fff':'#ffd76a');g.addColorStop(0.5,'#ff8a00');g.addColorStop(1,'#a33c10');
    ctx.fillStyle=g;ctx.beginPath();ctx.arc(bp.x,bp.y,bp.r,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.stroke();
    ctx.fillStyle='#2a1206';ctx.font='900 14px system-ui';ctx.textAlign='center';
    ctx.fillText(bp.special==='nova'?'🌟':String(bp.pts||100),bp.x,bp.y+5);ctx.textAlign='left';
  }
  // slingshots
  for(const s of L.slings){
    ctx.fillStyle='#3a2a5a';
    ctx.beginPath();
    ctx.moveTo(s.x-s.w/2,s.y-s.h/2);ctx.lineTo(s.x+s.w/2,s.y-s.h/2);
    ctx.lineTo(s.x+s.side*s.w/2,s.y+s.h/2);ctx.lineTo(s.x-s.side*s.w/2,s.y+s.h/2);
    ctx.closePath();ctx.fill();
    ctx.strokeStyle='#7a5aaa';ctx.lineWidth=2;ctx.stroke();
  }
  // flippers
  const fl=flipSeg(L.flipL,true,false),fr=flipSeg(L.flipR,false,false);
  ctx.strokeStyle='#ffd23f';ctx.lineWidth=14;ctx.lineCap='round';
  ctx.beginPath();ctx.moveTo(fl.x1,fl.y1);ctx.lineTo(fl.x2,fl.y2);ctx.stroke();
  ctx.beginPath();ctx.moveTo(fr.x1,fr.y1);ctx.lineTo(fr.x2,fr.y2);ctx.stroke();
  ctx.strokeStyle='#a37a00';ctx.lineWidth=3;
  ctx.beginPath();ctx.moveTo(fl.x1,fl.y1);ctx.lineTo(fl.x2,fl.y2);ctx.stroke();
  ctx.beginPath();ctx.moveTo(fr.x1,fr.y1);ctx.lineTo(fr.x2,fr.y2);ctx.stroke();
  // drain warning
  const dg=ctx.createLinearGradient(0,T.y+T.h*0.9,0,T.y+T.h);
  dg.addColorStop(0,'rgba(255,74,0,0)');dg.addColorStop(1,'rgba(255,74,0,0.3)');
  ctx.fillStyle=dg;ctx.fillRect(T.x,T.y+T.h*0.9,T.w,T.h*0.1);
  // ball
  const b=G.ball;
  if(b){
    // [w5b] trail dots are clipped to the table interior (they used to render
    // outside the table frame when the ball hugged the launch lane / walls)
    ctx.save();ctx.beginPath();ctx.roundRect(T.x+2,T.y+2,T.w-4,T.h-4,22);ctx.clip();
    for(const t of b.trail){
      ctx.globalAlpha=0.25;ctx.fillStyle='#ff8a00';
      ctx.beginPath();ctx.arc(t.x,t.y,b.r*0.7,0,Math.PI*2);ctx.fill();
    }
    ctx.restore();
    ctx.globalAlpha=1;
    const g=ctx.createRadialGradient(b.x-4,b.y-4,2,b.x,b.y,b.r);
    g.addColorStop(0,'#fff');g.addColorStop(0.4,'#ffd23f');g.addColorStop(1,'#ff6a00');
    ctx.fillStyle=g;ctx.shadowColor='#ff8a00';ctx.shadowBlur=16;
    ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
    if(G.shield){ctx.strokeStyle='#7fd4ff';ctx.lineWidth=2.5;ctx.shadowColor='#7fd4ff';ctx.shadowBlur=10;
      ctx.beginPath();ctx.arc(b.x,b.y,b.r+5,0,Math.PI*2);ctx.stroke();ctx.shadowBlur=0;}
    // face
    ctx.fillStyle='#2b1a0e';
    ctx.beginPath();ctx.arc(b.x-3.5,b.y-2,2.5,0,Math.PI*2);ctx.arc(b.x+3.5,b.y-2,2.5,0,Math.PI*2);ctx.fill();
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  ctx.textAlign='center';
  for(const f of floaters){
    if(!f.a)continue;
    ctx.globalAlpha=Math.min(1,f.life);
    ctx.font='900 18px system-ui';ctx.fillStyle='#000';
    ctx.fillText(f.txt,f.x+2,f.y+2);ctx.fillStyle='#ffd23f';ctx.fillText(f.txt,f.x,f.y);
  }
  ctx.globalAlpha=1;ctx.textAlign='left';
  // combo — [w5b] was drawn at y=52, on top of the ball-count HUD pill and the
  // table's top border. Now sits inside the table, clear of the frame and of
  // the nova bumper below it.
  if(G.combo>1&&G.state==='play'){
    const cy=T.y+32;
    ctx.textAlign='center';ctx.font='900 22px system-ui';
    ctx.fillStyle='#000';ctx.fillText(`🔥 x${G.combo.toFixed(1)}`,W/2+2,cy+2);
    ctx.fillStyle='#ff8a00';ctx.fillText(`🔥 x${G.combo.toFixed(1)}`,W/2,cy);
    ctx.textAlign='left';
  }
  ctx.restore();
  if(G.paused){ctx.fillStyle='rgba(0,0,0,0.5)';ctx.fillRect(0,0,W,H);ctx.fillStyle='#fff';ctx.font='900 36px system-ui';ctx.textAlign='center';ctx.fillText('⏸ PAUSED',W/2,H/2);ctx.font='700 16px system-ui';ctx.fillText('Tap ⏸ or press P to keep playing',W/2,H/2+32);ctx.textAlign='left';}
}

/* loop */
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(G.state==='play'&&!G.paused)update(dt);else G.time+=dt;
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  for(const f of floaters){if(!f.a)continue;f.y-=40*dt;f.life-=dt;if(f.life<=0)f.a=false;}
  render();
  requestAnimationFrame(loop);
}
document.getElementById('best').textContent='🏆 '+G.best;
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Flippers in the Furnace' — Volcanic Pinball's own
   track. Synthesized Web Audio only. 138 BPM, A minor pentatonic: a bright
   square lead trades phrases with itself over a springy root-fifth bass —
   pinball call-and-response.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-12-volcanic-pinball.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
const MUS={on:false,step:0,nextT:0,BPM:138,
 BASS:[45,0,52,0,45,0,52,0, 45,0,52,0,45,0,52,0, 41,0,48,0,41,0,48,0, 43,0,50,0,55,0,52,0],
 LEAD:[69,0,72,0,76,0,0,0, 0,0,69,0,72,69,0,0, 79,0,76,0,72,0,0,0, 0,0,74,0,76,0,0,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(MUTED||G.paused||G.state!=='play'){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.14,'square',0.05,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.16,'square',0.05,d);
  if(s%8===0||s%8===4)tone(120,45,0.11,'sine',0.13,d); // kick
  if(s%8===2||s%8===6)tone(190,120,0.07,'triangle',0.07,d); // tone-only snare
  if(s%4===2)tone(6800,6800,0.015,'square',0.008,d); // hat click
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

