scripts:
'use strict';
/* ============================================================
   PYRA PRIME DEFENSE v2 — AAA Rebuild
   - Breakout: paddle, ball physics, brick types
   - Power-ups: multi-ball, wide, laser, slow, life
   - 5 levels, particles, screen shake
   ============================================================ */
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();

/* audio */
let AC=null,MUTED=false;try{MUTED=localStorage.getItem('fb_muted')==='1';}catch(e){}
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
function noise(dur,vol,delay=0,lp=2000){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const len=ac.sampleRate*dur,buf=ac.createBuffer(1,len,ac.sampleRate),d=buf.getChannelData(0);
  for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);
  const s=ac.createBufferSource();s.buffer=buf;const f=ac.createBiquadFilter();f.type='lowpass';f.frequency.value=lp;
  const g=ac.createGain();g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  s.connect(f);f.connect(g);g.connect(ac.destination);s.start(t);}
const sfx={
  paddle(){tone(400,600,0.06,'square',0.1);},
  brick(){tone(600,900,0.08,'square',0.12);noise(0.08,0.15,0,3000);},
  tough(){tone(300,200,0.1,'square',0.12);},
  power(){tone(600,1500,0.2,'sine',0.14);},
  laser(){tone(1200,400,0.12,'sawtooth',0.1);},
  lose(){tone(400,100,0.4,'sawtooth',0.16);},
  win(){[523,659,784,1047].forEach((f,i)=>tone(f,f,0.25,'triangle',0.18,i*0.1));},
  click(){tone(600,600,0.06,'square',0.1);}
};

const G={state:'title',level:1,score:0,lives:3,
  px:0,pw:110,balls:[],bricks:[],powerups:[],lasers:[],
  time:0,shake:0,stickyT:0,slowT:0,laserT:0,paused:false,keysL:false,keysR:false,
  /* [slimer 2026-10-18] Slimer integration: aqua ball mode (water = the trap),
     foam paddle cannons (the smother), rainbow slicks, guaranteed teaching drops */
  foamShots:[],slicks:[],ballMode:'fire',ballModeT:0,foamT:0,foamCool:0,dropQueue:[],foamDropT:0};
const BALL_R=10;

/* [slimer 2026-10-18] Convert some wall bricks into Slimers (type 4): a NEW enemy
   type, not a reskin — skeletons/bricks stay exactly as they were. Level 1 gets
   exactly ONE gentle practice Slimer (spec: first appearances include one safe
   practice Slimer so kids learn water backfires without punishment); later
   levels scale 2→6. A breakout wall has far more cells than a defense lane has
   enemies, so a literal 1-in-6 of all cells (12+ on L2) would need dozens of
   aimed smother hits and make levels unfinishable — the count is scaled to
   keep a foam focus killing each Slimer in reasonable time instead. */
function placeSlimers(count){
  if(!G.bricks.length)return;
  const cands=G.bricks.slice();
  const stride=Math.max(1,Math.floor(cands.length/Math.max(count,1)));
  let idx=(G.level*7)%stride;
  const picks=[];
  for(let i=0;i<count&&cands.length;i++){
    picks.push(cands.splice(idx%cands.length,1)[0]);
    idx+=stride+((i*5)%3);
  }
  picks.forEach((b,k)=>{
    b.type=4;b.hp=999;b.dead=false;
    b.cover=0;b.grow=1;b.wobble=0;b.panic=0;b.dying=0;b.slideY=0;
    b.dripT=0.4+k*0.5;b._grewHint=false;b._hotHint=false;
  });
  if(picks.length)G.dropQueue=['aqua','foam']; // teaching drops: trap first, then the secret
}
function buildLevel(n){
  G.bricks=[];G.balls=[];G.powerups=[];G.lasers=[];
  G.pw=110;G.stickyT=0;G.slowT=0;G.laserT=0;
  G.foamShots=[];G.slicks=[];G.ballMode='fire';G.ballModeT=0;G.foamT=0;G.foamCool=0;G.dropQueue=[];G.foamDropT=6;
  G.px=W/2;
  const cols=Math.max(6,Math.min(12,Math.floor(W/70)));
  const bw=(W*0.92)/cols,gap=4;let bh=28;
  const ox=(W-(bw*cols+gap*(cols-1)))/2,oy=H<500?112:H*0.12; // [audit 2026-10-18] ox now accounts for the inter-brick gaps (was: wall ran 10px off the right edge at 844px wide)
  const rows=Math.min(12,4+n); // [levels+] rows capped at 12 so the wall never crowds the paddle
  if(H<500)bh=Math.max(12,Math.min(28,Math.floor((H*0.78-oy)/rows)-gap)); // [audit 2026-10-18] short screens (landscape phones): shrink brick height so deep-level walls end above the ball/paddle line (was: wall bottom 492px on a 390px screen at L10, 48 bricks off-screen)
  const patterns=[
    (r,c)=>1, // solid
    (r,c)=>(r+c)%2?1:2, // checker
    (r,c)=>r===0||r===rows-1||c===0||c===cols-1?2:1, // border tough
    (r,c)=>Math.abs(c-cols/2)<2?3:((r*7+c*3)%5===0?2:1), // center bonus
    (r,c)=>(r%2===0)?(c%3===0?3:1):(c%3===1?2:1), // mixed
    (r,c)=>((r+c)%2===0&&r%2===0)||((r+c)%2===1&&(r*3+c)%8===0)?2:1, // [levels+ L6] checker-tough
    (r,c)=>r===0||r===rows-1||c===0||c===cols-1?2:(Math.abs(c-cols/2)<2?3:((r+c)%6===0?2:1)), // [levels+ L7] border+bonus
    (r,c)=>r%3===0?(c%3===0?3:2):(r%3===1?(c%2===0?2:1):(c%3===1?2:1)), // [levels+ L8] mixed stripes
    (r,c)=>r%2===0?2:(c%4===0?3:(c%3===0?2:1)), // [levels+ L9] stripes
    (r,c)=>r===0||r===rows-1?2:((r+c)%2===0?2:(c%5===0?3:((r*2+c)%4===0?2:1))), // [levels+ L10] medley
  ];
  const pat=patterns[(n-1)%patterns.length];
  for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){
    const t=pat(r,c);
    if(t===0)continue;
    G.bricks.push({x:ox+c*(bw+gap),y:oy+r*(bh+gap),w:bw,h:bh,
      hp:t===1?1:t===2?2:1,type:t,flash:0});
  }
  placeSlimers(n===1?1:Math.min(2+Math.floor((n-1)/2),6)); // [slimer] L1: 1 practice; L2+: 2→6
  resetBall();
  document.getElementById('level').textContent=`LV ${n}/10`;
  document.getElementById('lives').textContent='❤️ '+G.lives;
}
function resetBall(){
  G.balls=[{x:G.px,y:H*0.78,vx:(Math.random()<0.5?-1:1)*220,vy:-420,stuck:true}];
}
function updateHUD(){document.getElementById('score').textContent='⭐ '+G.score;}

/* input */
function movePaddle(x){G.px=Math.max(G.pw/2,Math.min(W-G.pw/2,x));}
canvas.addEventListener('pointermove',e=>movePaddle(e.clientX));
canvas.addEventListener('pointerdown',e=>{
  movePaddle(e.clientX);
  // launch stuck balls
  for(const b of G.balls)if(b.stuck){b.stuck=false;b.vy=-460;}
});
addEventListener('keydown',e=>{
  if(e.key==='ArrowLeft'){G.keysL=true;e.preventDefault();}
  if(e.key==='ArrowRight'){G.keysR=true;e.preventDefault();}
  if(e.key===' '){for(const b of G.balls)if(b.stuck){b.stuck=false;b.vy=-460;}}
});
addEventListener('keyup',e=>{
  if(e.key==='ArrowLeft')G.keysL=false;
  if(e.key==='ArrowRight')G.keysR=false;
});

/* update */
const particles=[],floaters=[];
for(let i=0;i<150;i++)particles.push({a:false});
for(let i=0;i<15;i++)floaters.push({a:false});
function spawnP(x,y,vx,vy,life,color,size){const p=particles.find(p=>!p.a);if(!p)return;
  p.a=true;p.x=x;p.y=y;p.vx=vx;p.vy=vy;p.life=life;p.max=life;p.color=color;p.size=size;}
function spawnText(x,y,txt,color='#ffd23f'){const f=floaters.find(f=>!f.a);if(!f)return;
  f.a=true;f.x=x;f.y=y;f.txt=txt;f.color=color;f.life=1;}

function update(dt){
  G.time+=dt;G.shake=Math.max(0,G.shake-dt*3);
  if(G.laserT>0)G.laserT-=dt;
  if(G.slowT>0)G.slowT-=dt;
  if(G.stickyT>0)G.stickyT-=dt;
  if(G.ballModeT>0){G.ballModeT-=dt;if(G.ballModeT<=0)G.ballMode='fire';} // [slimer] aqua mode expiry
  if(G.foamT>0)G.foamT-=dt; // [slimer] smother-foam cannon timer
  const py=H*0.82;
  if(G.keysL)movePaddle(G.px-660*dt);
  if(G.keysR)movePaddle(G.px+660*dt);
  // paddle auto-follow for stuck balls
  for(const b of G.balls)if(b.stuck){b.x=G.px;b.y=py-16;}
  // lasers
  if(G.laserT>0){
    G.laserCool=(G.laserCool||0)-dt;
    if(G.laserCool<=0){G.laserCool=0.3;
      G.lasers.push({x:G.px-30,y:py-20},{x:G.px+30,y:py-20});
      sfx.laser();}
  }
  for(const l of G.lasers){
    l.y-=700*dt;
    for(const br of G.bricks){
      if(br.dead||br.dying>0)continue;
      if(l.x>br.x&&l.x<br.x+br.w&&l.y>br.y&&l.y<br.y+br.h){
        l.dead=true;hitBrick(br,1,null,'laser');break;
      }
    }
    if(l.y<0)l.dead=true;
  }
  G.lasers=G.lasers.filter(l=>!l.dead);
  // [slimer] smother-foam cannons — same paddle-shot idiom as the lasers, but
  // the foam blobs SMOTHER: the only shots that can bury a Slimer.
  if(G.foamT>0){
    G.foamCool-=dt;
    if(G.foamCool<=0){G.foamCool=0.28;
      G.foamShots.push({x:G.px-30,y:py-20},{x:G.px+30,y:py-20});
      noise(0.06,0.07,0,900);}
  }
  for(const s of G.foamShots){
    s.y-=640*dt;
    for(const br of G.bricks){
      if(br.dead||br.dying>0)continue;
      if(s.x>br.x&&s.x<br.x+br.w&&s.y>br.y&&s.y<br.y+br.h){
        s.dead=true;hitBrick(br,1,null,'foam');break;
      }
    }
    if(s.y<0)s.dead=true;
  }
  G.foamShots=G.foamShots.filter(s=>!s.dead);
  updateSlimers(dt);
  // balls
  for(const b of G.balls){
    if(b.stuck)continue;
    b.x+=b.vx*dt;b.y+=b.vy*dt;
    // speed clamp
    const sp=Math.hypot(b.vx,b.vy),min=G.slowT>0?250:380,max=720;
    if(sp<min){b.vx*=min/sp;b.vy*=min/sp;}
    if(sp>max){b.vx*=max/sp;b.vy*=max/sp;}
    // walls
    if(b.x<BALL_R){b.x=BALL_R;b.vx=Math.abs(b.vx);}
    if(b.x>W-BALL_R){b.x=W-BALL_R;b.vx=-Math.abs(b.vx);}
    if(b.y<BALL_R){b.y=BALL_R;b.vy=Math.abs(b.vy);}
    // paddle
    if(b.vy>0&&b.y+BALL_R>py-10&&b.y+BALL_R<py+16&&Math.abs(b.x-G.px)<G.pw/2+BALL_R){
      const rel=(b.x-G.px)/(G.pw/2);
      const ang=rel*1.1; // -63° to 63°
      const spd=Math.hypot(b.vx,b.vy);
      b.vx=Math.sin(ang)*spd;b.vy=-Math.cos(ang)*spd;
      b.y=py-10-BALL_R;
      sfx.paddle();
      if(G.stickyT>0){b.stuck=true;}
      for(let i=0;i<4;i++)spawnP(b.x,py,(Math.random()-0.5)*150,-Math.random()*100,0.25,'#ffd23f',3);
    }
    // bricks
    for(const br of G.bricks){
      if(br.dead||br.dying>0)continue;
      if(b.x+BALL_R>br.x&&b.x-BALL_R<br.x+br.w&&b.y+BALL_R>br.y&&b.y-BALL_R<br.y+br.h){
        // determine bounce side
        const overlapL=b.x+BALL_R-br.x,overlapR=br.x+br.w-(b.x-BALL_R);
        const overlapT=b.y+BALL_R-br.y,overlapB=br.y+br.h-(b.y-BALL_R);
        const m=Math.min(overlapL,overlapR,overlapT,overlapB);
        if(m===overlapL||m===overlapR)b.vx*=-1;else b.vy*=-1;
        hitBrick(br,1,b,'ball');
        break;
      }
    }
    // keep a minimum vertical component so rallies always come back down
    const sp2=Math.hypot(b.vx,b.vy);
    if(sp2>0&&Math.abs(b.vy)<sp2*0.22){
      b.vy=(b.vy<0?-1:1)*sp2*0.22;
      const rx=Math.sqrt(Math.max(0,sp2*sp2-b.vy*b.vy));
      b.vx=(b.vx<0?-1:1)*rx;
    }
    // fell
    if(b.y>H+30)b.dead=true;
  }
  G.balls=G.balls.filter(b=>!b.dead);
  if(G.balls.length===0){
    G.lives--;document.getElementById('lives').textContent='❤️ '+G.lives;
    sfx.lose();G.shake=0.5;
    if(G.lives<=0)gameOver();
    else resetBall();
  }
  // powerups fall
  for(const p of G.powerups){
    p.y+=160*dt;p.spin+=dt*4;
    if(p.y>py-14&&p.y<py+16&&Math.abs(p.x-G.px)<G.pw/2+14){
      p.dead=true;applyPower(p.type);
    }
    if(p.y>H+20)p.dead=true;
  }
  G.powerups=G.powerups.filter(p=>!p.dead);
  for(const br of G.bricks)if(br.flash>0)br.flash=Math.max(0,br.flash-dt);
  // win check
  if(G.bricks.every(b=>b.dead))levelComplete();
}
/* [slimer 2026-10-18] Slimer hit rules — THE SECRET, readable at a glance:
   - 'foam' (smother cannons): cover builds, he panics and shrinks ~15% per hit;
     at full cover he's DEFEATED — a buried mound, eyes peeking, slides away.
   - ball in AQUA mode (water): the trap — splash particles, smug wobble, he
     GROWS up to 1.6x and gets TANKIER (needs extra cover). No HP loss, ever.
   - fire ball / laser / nova (everything else): NO damage — happy wobble only,
     so kids READ that non-smother attacks don't work. */
function slimerNeed(br){return 4+(br.grow>=1.55?2:br.grow>=1.3?1:0);}
function slimerHit(br,src){
  const cx=br.x+br.w/2,cy=br.y+br.h/2;
  if(src==='foam'){
    const need=slimerNeed(br);
    br.cover++;
    br.grow=Math.max(0.55,br.grow*0.85); // shrinks ~15% per smother hit
    br.panic=1;br.wobble=0.8;
    for(let i=0;i<10;i++)spawnP(cx,cy,(Math.random()-0.5)*180,(Math.random()-0.6)*180,0.6,
      i%3?'#f2ead8':'#c9b18a',4);
    noise(0.12,0.14,0,1100);
    if(br.cover>=need){
      br.dying=0.001;br.slideY=0; // defeat plays out in updateSlimers: mound + slide off
      spawnText(cx,br.y,'SMOTHERED!','#f2ead8');
      tone(500,180,0.25,'sine',0.12);
    }else{
      spawnText(cx,br.y,'POOF! '+br.cover+'/'+need,'#f2ead8');
    }
    return;
  }
  if(src==='ball'&&G.ballMode==='aqua'){
    if(br.grow<1.6){
      br.grow=Math.min(1.6,br.grow+0.2); // water makes him GROW — never kills him
      br.wobble=1;
      for(let i=0;i<12;i++)spawnP(cx,cy,(Math.random()-0.5)*260,(Math.random()-0.5)*260,0.6,
        i%3?'#3fc6ff':'#1a5f8a',4);
      noise(0.16,0.16,0,700);
      if(!br._grewHint){br._grewHint=true;spawnText(cx,br.y-6,'💧 HE GREW!','#3fc6ff');}
    }
    return;
  }
  // fire / laser / nova / plain shots: visibly DON'T work — smug wobble, no HP loss
  br.wobble=1;
  for(let i=0;i<6;i++)spawnP(cx,cy,(Math.random()-0.5)*120,-Math.random()*120,0.4,'#ff9a3a',3);
  if(!br._hotHint){br._hotHint=true;spawnText(cx,br.y-6,"🔥 won't work — SMOTHER him!",'#ffd23f');}
  sfx.tough();
}
function updateSlimers(dt){
  let anyAlive=false;
  for(const br of G.bricks){
    if(br.type!==4||br.dead)continue;
    anyAlive=true;
    br.wobble=Math.max(0,br.wobble-dt*1.6);
    br.panic=Math.max(0,br.panic-dt*0.8);
    if(br.dying>0){
      // slapstick defeat: buried mound, eyes peeking, slides off the wall edge
      br.dying+=dt;br.slideY+=dt*70;
      if(br.dying>1.0){
        br.dead=true;
        G.score+=50;updateHUD(); // same value as a standard type-1 brick — no economy change
        spawnText(br.x+br.w/2,br.y+br.slideY,'+50');
        for(let i=0;i<14;i++)spawnP(br.x+br.w/2,br.y+br.slideY,(Math.random()-0.5)*200,(Math.random()-0.5)*160,0.6,
          i%2?'#f2ead8':'#c9b18a',4);
        noise(0.2,0.14,0,1400);
      }
      continue;
    }
    // ooze: drips fall off the cell and pool into a rainbow slick on the wall
    br.dripT-=dt;
    if(br.dripT<=0){
      br.dripT=0.3+Math.random()*0.45;
      const cx=br.x+br.w/2;
      G.slicks.push({x:cx+(Math.random()-0.5)*br.w*0.5,y:br.y+br.h+3,
        rx:br.w*0.3*(0.8+br.grow*0.3),life:6,max:6});
      if(G.slicks.length>90)G.slicks.shift();
      spawnP(cx,br.y+br.h,(Math.random()-0.5)*40,50+Math.random()*40,0.5,'#1a0a22',3);
    }
  }
  for(const sl of G.slicks){sl.life-=dt;sl.rx+=dt*2;}
  G.slicks=G.slicks.filter(sl=>sl.life>0);
  /* Finishability guarantee: while a Slimer lives and no foam is available
     (cannons idle, none falling), a foam supply drop falls over him every ~6s,
     so a level can never soft-lock on its last Slimer. */
  if(anyAlive&&G.foamT<=0&&!G.powerups.some(p=>p.type==='foam'&&!p.dead)){
    G.foamDropT-=dt;
    if(G.foamDropT<=0){
      G.foamDropT=6;
      const sl=G.bricks.find(b=>b.type===4&&!b.dead&&!(b.dying>0));
      if(sl)G.powerups.push({x:Math.max(20,Math.min(W-20,sl.x+sl.w/2)),y:0,type:'foam',spin:0});
    }
  }else if(anyAlive){G.foamDropT=Math.min(G.foamDropT,6);}
}
function hitBrick(br,dmg,b,src){
  src=src||'ball';
  if(br.dead||br.dying>0)return;
  if(br.type===4){slimerHit(br,src);return;} // [slimer] Slimers ignore normal HP entirely
  br.hp-=dmg;br.flash=0.2;
  if(br.hp<=0){
    br.dead=true;
    const pts=br.type===3?150:br.type===2?80:50;
    G.score+=pts;updateHUD();
    sfx.brick();G.shake=Math.max(G.shake,0.15);
    spawnText(br.x+br.w/2,br.y,'+'+pts);
    for(let i=0;i<10;i++)spawnP(br.x+br.w/2,br.y+br.h/2,(Math.random()-0.5)*250,(Math.random()-0.5)*250,0.5,
      br.type===3?'#ffd23f':br.type===2?'#8a7a6a':'#a05a3a',4);
    // powerup drop — [slimer] while a Slimer lives, the first two broken bricks
    // force-drop the teaching pair (aqua trap, then foam secret); after that the
    // normal roll runs with aqua/foam added to the pool.
    const slimerAlive=G.bricks.some(x=>x.type===4&&!x.dead);
    if(slimerAlive&&G.dropQueue.length){
      G.powerups.push({x:br.x+br.w/2,y:br.y,type:G.dropQueue.shift(),spin:0});
    }else{
      const r=Math.random();
      if(r<0.22){
        const types=['multi','wide','laser','slow','life','sticky','nova','foam','aqua','foam'];
        G.powerups.push({x:br.x+br.w/2,y:br.y,type:types[Math.floor(Math.random()*types.length)],spin:0});
      }
    }
  }else{sfx.tough();}
}
function applyPower(type){
  sfx.power();
  const py=H*0.82;
  if(type==='multi'){
    const nb=[];
    for(const b of G.balls)for(let i=0;i<2;i++){
      const a=Math.random()*Math.PI*2;
      nb.push({x:b.x,y:b.y,vx:Math.cos(a)*400,vy:Math.sin(a)*400,stuck:false});
    }
    G.balls.push(...nb);
    spawnText(G.px,py-40,'MULTI-BALL!','#7fd4ff');
  }else if(type==='wide'){G.pw=Math.min(220,G.pw+50);spawnText(G.px,py-40,'WIDE!','#4caf50');}
  else if(type==='laser'){G.laserT=12;spawnText(G.px,py-40,'LASERS!','#ff4a5a');}
