  else if(type==='life'){G.lives++;document.getElementById('lives').textContent='❤️ '+G.lives;spawnText(G.px,py-40,'+1 LIFE!','#ff6a8a');}
  else if(type==='aqua'){G.ballMode='aqua';G.ballModeT=10;spawnText(G.px,py-40,'💧 AQUA BALL!','#3fc6ff');} // [slimer] water mode — the trap vs Slimers
