  else if(type==='nova'){
    const alive=G.bricks.filter(br=>!br.dead);
    alive.sort((a,b2)=>Math.hypot(a.x+a.w/2-G.px,a.y-py)-Math.hypot(b2.x+b2.w/2-G.px,b2.y-py));
