/* render */
/* living embers (overhaul) */
const EMBER_SEEDS=Array.from({length:24},(_,i)=>({x:(i*0.61803)%1,y:(i*0.754877)%1,s:1+((i*7)%3),v:12+((i*13)%24),d:((i*29)%20)-10}));
/* [w5b perf] Pre-baked ember glow sprite. Profiling (Chromium/SwiftShader, W2
   rAF method): this game ran at 10.0 FPS with ~26 non-zero shadowBlur sets/frame,
   24 of them this ember loop; neutralising shadowBlur alone restored 59.9 FPS
   (fast siblings use <=1/frame). Embers now blit a pre-rendered radial-glow
   sprite with the same colour/falloff. (The 61 createLinearGradient/frame for
   bricks were measured NOT to be the bottleneck — 59.9 FPS in the A/B with
   gradients untouched — so brick rendering is left exactly as-is.) */
const EMBER_SPRITE=(()=>{const c=document.createElement('canvas');c.width=c.height=96;const x=c.getContext('2d');
  const gr=x.createRadialGradient(48,48,0,48,48,48);
  gr.addColorStop(0,'rgba(255,154,58,0.9)');gr.addColorStop(0.35,'rgba(255,122,42,0.38)');gr.addColorStop(1,'rgba(255,106,0,0)');
  x.fillStyle=gr;x.fillRect(0,0,96,96);return c;})();
function drawEmbers(bw,bh){ctx.save();ctx.globalCompositeOperation='lighter';const t=(typeof G!=='undefined'&&G.time)||0;
  for(const e of EMBER_SEEDS){const ey=bh-((e.y*bh+t*e.v)%bh);const ex=e.x*bw+Math.sin(t*0.7+e.y*9)*e.d;
    ctx.globalAlpha=0.13+0.09*Math.sin(t*2+e.y*20);
    const r=e.s*7;ctx.drawImage(EMBER_SPRITE,ex-r,ey-r,r*2,r*2);}
  ctx.restore();}
/* [slimer 2026-10-18] Slimer drawing — canvas, in the game's idiom, per
   SLIMERS-SPEC + concept art: glossy black-purple round blob, rainbow oil
   swirls, two drippy stub arms, big eyes + smug drippy grin; panic wide eyes
   and an "o" mouth as foam/sand cover builds; defeated = buried mound with
   just his eyes peeking. NO text on the character, ever. */
function drawSlimer(br){
  const cx=br.x+br.w/2,cy=br.y+br.h/2;
  const t=G.time,seed=br.x*0.7+br.y*1.3;
  const wob=Math.sin(t*7+seed)*4*br.wobble;
  const ooze=Math.sin(t*2.2+seed)*3; // constant oozy slosh, squash-and-stretch
  const R=Math.min(br.w,br.h)*0.62*br.grow;
  ctx.save();
  ctx.translate(cx,cy+(br.slideY||0));
  if(br.dying>0){
    // buried mound with just his eyes peeking out
    ctx.globalAlpha=Math.max(0,1-br.dying*0.7);
    ctx.fillStyle='#c9b18a';
    ctx.beginPath();ctx.ellipse(0,7,R*1.15,R*0.55,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#f2ead8';
    ctx.beginPath();ctx.ellipse(-R*0.15,1,R*0.82,R*0.4,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#fff';
    ctx.beginPath();ctx.arc(-R*0.28,-R*0.08,R*0.17,0,Math.PI*2);ctx.arc(R*0.16,-R*0.14,R*0.17,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#1a0a12';
    ctx.beginPath();ctx.arc(-R*0.28,-R*0.05,R*0.07,0,Math.PI*2);ctx.arc(R*0.16,-R*0.11,R*0.07,0,Math.PI*2);ctx.fill();
    ctx.restore();return;
  }
  ctx.scale(1+wob*0.02+ooze*0.008,1-wob*0.02-ooze*0.008);
  // glossy black-purple oil body
  const g=ctx.createRadialGradient(-R*0.3,-R*0.35,R*0.1,0,0,R*1.15);
  g.addColorStop(0,'#5a2a78');g.addColorStop(0.55,'#2a1238');g.addColorStop(1,'#12060f');
  ctx.fillStyle=g;ctx.strokeStyle='#0a0408';ctx.lineWidth=3;
  ctx.beginPath();ctx.ellipse(0,0,R,R*0.92,0,0,Math.PI*2);ctx.fill();ctx.stroke();
  // rainbow oil-slick swirls, slowly rotating
  ctx.save();
  ctx.beginPath();ctx.ellipse(0,0,Math.max(1,R-3),Math.max(1,(R-3)*0.92),0,0,Math.PI*2);ctx.clip();
  const swc=['#ff3fa4','#3fd4c6','#ffb43f','#7f5fff'];
  for(let i=0;i<4;i++){
    ctx.strokeStyle=swc[i];ctx.globalAlpha=0.5;ctx.lineWidth=2.5;
    ctx.beginPath();
    ctx.arc(0,0,R*(0.28+i*0.2),t*(0.6+i*0.22)+seed+i,t*(0.6+i*0.22)+seed+i+Math.PI*1.2);
    ctx.stroke();
  }
  ctx.restore();
  // gloss highlight
  ctx.fillStyle='rgba(255,255,255,0.35)';
  ctx.beginPath();ctx.ellipse(-R*0.32,-R*0.42,R*0.26,R*0.13,-0.6,0,Math.PI*2);ctx.fill();
  // two drippy stub arms
  ctx.fillStyle='#1c0b24';ctx.strokeStyle='#0a0408';ctx.lineWidth=2;
  for(const sx of[-1,1]){
    ctx.beginPath();ctx.ellipse(sx*R*1.02,R*0.08+wob*0.4,R*0.18,R*0.3,sx*0.25,0,Math.PI*2);ctx.fill();ctx.stroke();
    ctx.beginPath();ctx.arc(sx*R*1.1,R*0.36,R*0.07,0,Math.PI*2);ctx.fill(); // drip blob
  }
  // face — panic (wide eyes + "o" mouth) once cover builds, else smug gloat
  const panicky=br.panic>0.15||br.cover>0;
  if(panicky){
    ctx.fillStyle='#fff';
    ctx.beginPath();ctx.arc(-R*0.3,-R*0.12,R*0.24,0,Math.PI*2);ctx.arc(R*0.3,-R*0.12,R*0.24,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#1a0a12';
    ctx.beginPath();ctx.arc(-R*0.3,-R*0.12,R*0.1,0,Math.PI*2);ctx.arc(R*0.3,-R*0.12,R*0.1,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#1a0a12';ctx.lineWidth=3;
    ctx.beginPath();ctx.arc(0,R*0.3,R*0.12,0,Math.PI*2);ctx.stroke();
  }else{
    ctx.fillStyle='#fff';
    ctx.beginPath();ctx.arc(-R*0.3,-R*0.1,R*0.22,0,Math.PI*2);ctx.arc(R*0.3,-R*0.1,R*0.22,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#2a1238'; // half-lidded smug lids
    ctx.fillRect(-R*0.52,-R*0.34,R*0.44,R*0.13);ctx.fillRect(R*0.08,-R*0.34,R*0.44,R*0.13);
    ctx.fillStyle='#1a0a12';
    ctx.beginPath();ctx.arc(-R*0.28,-R*0.05,R*0.09,0,Math.PI*2);ctx.arc(R*0.32,-R*0.05,R*0.09,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#1a0a12';ctx.lineWidth=4;ctx.lineCap='round';
    ctx.beginPath();ctx.arc(0,R*0.02,R*0.4,0.25*Math.PI,0.75*Math.PI);ctx.stroke(); // wide smug grin
    ctx.strokeStyle='#7f5fff';ctx.lineWidth=3; // drippy drool off the grin
    ctx.beginPath();ctx.moveTo(R*0.08,R*0.34);ctx.lineTo(R*0.08,R*0.5);ctx.stroke();
  }
  // smother cover: foam/sand piling over him as cover builds (he shrinks under it)
  if(br.cover>0){
    const need=slimerNeed(br),f=Math.min(1,br.cover/need);
    ctx.fillStyle='rgba(242,234,216,0.92)';
    ctx.beginPath();ctx.ellipse(0,R*0.95-R*1.2*f,R*1.05*(0.4+0.6*f),Math.max(2,R*0.75*f),0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='rgba(201,177,138,0.85)';
    ctx.beginPath();ctx.ellipse(-R*0.3,R*0.95-R*1.05*f,R*0.4*f+2,R*0.3*f+2,0,0,Math.PI*2);ctx.fill();
  }
  ctx.restore();
}
function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#140a08');bg.addColorStop(1,'#2a1408');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  drawEmbers(W,H);
  ctx.save();
  if(G.shake>0)ctx.translate((Math.random()-0.5)*G.shake*14,(Math.random()-0.5)*G.shake*14);
  // bricks
  for(const br of G.bricks){
    if(br.dead)continue;
    if(br.type===4)continue; // [slimer] Slimers are blobs, not bricks — drawn by drawSlimer() below
    const cols={1:['#c46a3a','#8a3a1a'],2:['#8a7a6a','#4a3a2a'],3:['#ffd23f','#a37a00']};
    const [c1,c2]=cols[br.type];
    const g=ctx.createLinearGradient(0,br.y,0,br.y+br.h);
    g.addColorStop(0,br.flash>0?'#fff':c1);g.addColorStop(1,c2);
    ctx.fillStyle=g;
    ctx.beginPath();ctx.roundRect(br.x+2,br.y+2,br.w-4,br.h-4,6);ctx.fill();
    ctx.strokeStyle='rgba(255,255,255,0.25)';ctx.lineWidth=1.5;ctx.stroke();
    if(br.type===2&&br.hp>1){
      ctx.fillStyle='rgba(0,0,0,0.4)';ctx.font='900 14px system-ui';ctx.textAlign='center';
      ctx.fillText('2',br.x+br.w/2,br.y+br.h/2+5);ctx.textAlign='left';
    }
    if(br.type===3){
      ctx.font='16px system-ui';ctx.textAlign='center';
      ctx.fillText('⭐',br.x+br.w/2,br.y+br.h/2+6);ctx.textAlign='left';
    }
  }
  // [slimer] rainbow oil slicks pooled under the Slimers, then the Slimers
  for(const sl of G.slicks){
    const a=Math.max(0,sl.life/sl.max);
    ctx.save();ctx.globalAlpha=a*0.85;
    const swc=['#ff3fa4','#ffb43f','#3fd4c6','#7f5fff'];
    for(let i=0;i<4;i++){
      ctx.strokeStyle=swc[i];ctx.lineWidth=2.5;
      ctx.beginPath();ctx.ellipse(sl.x,sl.y,Math.max(2,sl.rx*(1-i*0.16)),Math.max(1.5,6*(1-i*0.16)),0,0,Math.PI*2);ctx.stroke();
    }
    ctx.fillStyle='#12060f';ctx.globalAlpha=a*0.5;
    ctx.beginPath();ctx.ellipse(sl.x,sl.y,sl.rx*0.7,4.4,0,0,Math.PI*2);ctx.fill();
    ctx.restore();
  }
  for(const br of G.bricks)if(br.type===4&&!br.dead)drawSlimer(br);
  const py=H*0.82;
  // paddle
  const pg=ctx.createLinearGradient(0,py-10,0,py+10);
  pg.addColorStop(0,'#ffd76a');pg.addColorStop(0.5,'#ff8a00');pg.addColorStop(1,'#a33c10');
  ctx.fillStyle=pg;ctx.shadowColor='#ff8a00';ctx.shadowBlur=G.laserT>0?18:10;
  ctx.beginPath();ctx.roundRect(G.px-G.pw/2,py-10,G.pw,20,10);ctx.fill();ctx.shadowBlur=0;
  ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.stroke();
  if(G.laserT>0){
    ctx.fillStyle='#ff4a5a';
    ctx.fillRect(G.px-34,py-22,8,12);ctx.fillRect(G.px+26,py-22,8,12);
  }
  if(G.foamT>0){ // [slimer] foam cannon nozzles on the paddle
    ctx.fillStyle='#f2ead8';
    ctx.fillRect(G.px-34,py-22,8,12);ctx.fillRect(G.px+26,py-22,8,12);
    ctx.fillStyle='#c9b18a';
    ctx.fillRect(G.px-34,py-13,8,3);ctx.fillRect(G.px+26,py-13,8,3);
  }
  // lasers
  ctx.fillStyle='#ff4a5a';
  for(const l of G.lasers)ctx.fillRect(l.x-2,l.y-14,4,14);
  // [slimer] foam blobs from the smother cannons
  for(const s of G.foamShots){
    ctx.fillStyle='#f2ead8';
    ctx.beginPath();ctx.arc(s.x,s.y,5,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='rgba(255,255,255,0.75)';
    ctx.beginPath();ctx.arc(s.x-1.5,s.y-1.5,2,0,Math.PI*2);ctx.fill();
  }
  // balls — [slimer] in AQUA mode the ball runs blue: water, the trap vs Slimers
  for(const b of G.balls){
    const aqua=G.ballMode==='aqua';
    const g=ctx.createRadialGradient(b.x-3,b.y-3,2,b.x,b.y,BALL_R);
    if(aqua){g.addColorStop(0,'#fff');g.addColorStop(0.4,'#5fd4ff');g.addColorStop(1,'#1668b0');}
    else{g.addColorStop(0,'#fff');g.addColorStop(0.4,'#ffd23f');g.addColorStop(1,'#ff6a00');}
    ctx.fillStyle=g;ctx.shadowColor=aqua?'#3fc6ff':'#ff8a00';ctx.shadowBlur=14;
    ctx.beginPath();ctx.arc(b.x,b.y,BALL_R,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
    ctx.fillStyle='#2b1a0e';
    ctx.beginPath();ctx.arc(b.x-3,b.y-2,2.2,0,Math.PI*2);ctx.arc(b.x+3,b.y-2,2.2,0,Math.PI*2);ctx.fill();
  }
  // powerups
  for(const p of G.powerups){
    ctx.save();ctx.translate(p.x,p.y);ctx.rotate(Math.sin(p.spin)*0.2);
    const icons={multi:'✦',wide:'↔',laser:'🔫',slow:'⏳',life:'❤️',sticky:'🍯',nova:'💥',aqua:'💧',foam:'🫧'};
    const cols={multi:'#7fd4ff',wide:'#4caf50',laser:'#ff4a5a',slow:'#9a7fd4',life:'#ff6a8a',sticky:'#ffd23f',nova:'#ff9a3a',aqua:'#2aa7e0',foam:'#e8dcc2'};
    ctx.fillStyle=cols[p.type];
    ctx.beginPath();ctx.arc(0,0,15,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.stroke();
    ctx.fillStyle='#fff';ctx.font='14px system-ui';ctx.textAlign='center';
    ctx.fillText(icons[p.type],0,5);ctx.textAlign='left';
    ctx.restore();
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  ctx.textAlign='center';
  for(const f of floaters){
    if(!f.a)continue;
    ctx.globalAlpha=Math.min(1,f.life);
    ctx.font='900 18px system-ui';ctx.fillStyle='#000';
    ctx.fillText(f.txt,f.x+2,f.y+2);ctx.fillStyle=f.color;ctx.fillText(f.txt,f.x,f.y);
  }
  ctx.globalAlpha=1;ctx.textAlign='left';
  ctx.restore();
  if(G.paused){ctx.fillStyle='rgba(0,0,0,0.5)';ctx.fillRect(0,0,W,H);ctx.fillStyle='#fff';ctx.font='900 36px system-ui';ctx.textAlign='center';ctx.fillText('⏸ PAUSED',W/2,H/2);ctx.font='700 16px system-ui';ctx.fillText('Tap ⏸ or press P to keep playing',W/2,H/2+32);ctx.textAlign='left';}
}

/* loop */
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(G.state==='play'&&!G.paused)update(dt);else G.time+=dt;
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  for(const f of floaters){if(!f.a)continue;f.y-=40*dt;f.life-=dt;if(f.life<=0)f.a=false;}
  render();
  requestAnimationFrame(loop);
}
updateHUD();
requestAnimationFrame(loop);
