 LEAD:[62,0,65,0,69,0,65,0, 67,0,69,0,71,0,69,0, 65,0,69,0,72,0,69,0, 67,0,64,0,62,0,0,0],
 PAD:[38,36,41,43],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(MUTED||G.paused||G.state!=='play'){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  if(s%8===0){const p=this.PAD[s>>3];if(p){tone(_mf(p),_mf(p),1.6,'sawtooth',0.016,d);tone(_mf(p)*1.006,_mf(p)*1.006,1.6,'sawtooth',0.016,d);tone(_mf(p+7),_mf(p+7),1.6,'triangle',0.02,d);}} // pad chord
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.2,'triangle',0.06,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.24,'sawtooth',0.045,d);
  if(s%8===0||s%8===4)tone(118,45,0.12,'sine',0.12,d); // marching kick
  if(s%8===2||s%8===6)noise(0.08,0.07,d,1800); // snare
  if(s%4===0)noise(0.02,0.012,d,6800); // quiet hat
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

