  {e:'✨',c:'#ffd23f',n:'Sizzle'},{e:'🪨',c:'#8a7a6a',n:'Boulder'},
  {e:'❄️',c:'#7fd4ff',n:'Cinder'},{e:'👹',c:'#c4a0ff',n:'Inferno'},
  {e:'💧',c:'#4a90d9',n:'Aqua'},{e:'🌋',c:'#ff6a00',n:'Magma'},
  {e:'⚡',c:'#ffeb3b',n:'Volt'},{e:'🌟',c:'#ffffff',n:'Nova'},
  {e:'🔮',c:'#9a7fd4',n:'Mystic'},{e:'💎',c:'#aee2ff',n:'Crystal'},
];
// THE SLIMER — oil villain (spec: fire-babys-shows/characters/SLIMERS-SPEC.md).
// Not a regular face pair: the Slimer card pairs with the Lid card (the smother verb).
const SLIMER_FACE={e:'🛢️',c:'#2a1a4a',n:'Slimer'};
const LID_FACE={e:'🍳',c:'#9aa4b8',n:'Lid'};
const SLIMER_PAIR=99;
const G={state:'title',level:1,cards:[],first:null,second:null,lock:false,
  flips:0,matched:0,score:0,time:0,combo:0,preview:0};
function initLevel(n){
  G.level=n;G.flips=0;G.matched=0;G.combo=0;G.first=null;G.second=null;G.lock=false;
  const pairCount=[8,10,12,12,12,12,12,12][n-1]||8;
  layout();
  // The Slimer smother pair takes the last pair slot: one special pair per board
  // (1 of 8 pairs on L1 … 1 of 12 later) — rare, and the preview shows him first so
  // kids meet him slow and alone and learn that water backfires without punishment.
  const faces=FACES.slice(0,pairCount-1);
  let deck=[];
  faces.forEach((f,i)=>{deck.push({id:i,face:f},{id:i,face:f});});
  deck.push({id:SLIMER_PAIR,face:SLIMER_FACE,kind:'slimer'},
            {id:SLIMER_PAIR,face:LID_FACE,kind:'lid'});
  // shuffle
  for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]];}
  G.cards=deck.map((d,i)=>({id:d.id,face:d.face,kind:d.kind||null,flip:0,matched:false,glow:0,
    grow:1,wob:0,cover:0,coverTarget:0,defeated:false,slide:0,
    r:Math.floor(i/COLS),c:i%COLS}));
