  for(const cd of G.cards)cd.flip=1;
  G.lock=true;G.preview=[1.6,1.6,1.6,1.4,1.2,1.0,0.9,0.8][n-1]||1.6;
  updateHUD();
}
function updateHUD(){
  document.getElementById('score').textContent='⭐ '+G.score;
  document.getElementById('flips').textContent='🃏 '+G.flips;
  const total=[8,10,12,12,12,12,12,12][G.level-1]||8;
  document.getElementById('pairs').textContent=`✅ ${G.matched}/${total}`;
}
canvas.addEventListener('pointerdown',e=>{
  if(G.state!=='play'||G.lock||PAUSED)return;
  const rect=canvas.getBoundingClientRect();
  const c=Math.floor((e.clientX-rect.left-GX)/CELL),r=Math.floor((e.clientY-rect.top-GY)/CELL);
  const card=G.cards.find(cd=>cd.r===r&&cd.c===c);
  if(!card||card.matched||card.flip>0.5)return;
  if(G.first===card)return;
  card.flip=0.01;sfx.flip();
  if(!G.first)G.first=card;
  else{
    G.second=card;G.lock=true;G.flips++;
    if(G.first.id===G.second.id){
      const slim=[G.first,G.second].find(cd=>cd.kind==='slimer');
      if(slim){
        // SMOTHER WIN: Slimer + Lid pair. The lid drops, cover builds, he panics
        // and shrinks — then he is defeated flat and slides off on his own slick.
        slim.coverTarget=1;sfx.lid();
        setTimeout(()=>{
          slim.defeated=true;
          G.first.matched=true;G.second.matched=true;
          G.first.glow=0.6;G.second.glow=0.6;
          G.matched++;G.combo++;
          const pts=100+G.combo*25; // same value as any standard pair — no scoring change
          G.score+=pts;sfx.deflate();updateHUD();
          spawnText(slim);
          G.first=null;G.second=null;G.lock=false;
          if(G.matched>=([8,10,12,12,12,12,12,12][G.level-1]||8))levelComplete();
        },1600);
      }else{
      setTimeout(()=>{
        G.first.matched=true;G.second.matched=true;
        G.first.glow=0.6;G.second.glow=0.6;
        G.matched++;G.combo++;
        const pts=100+G.combo*25;
        G.score+=pts;sfx.match();updateHUD();
        spawnText(G.first);
        G.first=null;G.second=null;G.lock=false;
        if(G.matched>=([8,10,12,12,12,12,12,12][G.level-1]||8))levelComplete();
      },400);
      }
    }else{
      G.combo=0;sfx.no();
      const slimM=[G.first,G.second].find(cd=>cd.kind==='slimer');
      const aquaM=[G.first,G.second].find(cd=>!cd.kind&&cd.face&&cd.face.n==='Aqua');
      if(slimM&&aquaM){
        // WATER TRAP: Aqua's water on an oil Slimer — he splashes, spreads and
        // GROWS (cap ~1.6x) with a happy smug wobble. No damage, ever.
        slimM.grow=Math.min(1.6,slimM.grow+0.3);
        slimM.wob=1.4;sfx.splash();spawnSplashDrops(slimM);
        const f=floaters.find(fl=>!fl.a);
        if(f){f.a=true;f.x=GX+slimM.c*CELL+CELL/2;f.y=GY+slimM.r*CELL;f.txt='💦 SPLASH! HE GREW!';f.life=1.4;}
      }
      setTimeout(()=>{
        G.first.flip=-0.01;G.second.flip=-0.01;
        G.first=null;G.second=null;G.lock=false;
        updateHUD();
      },800);
    }
    updateHUD();
  }
});
const floaters=[];
for(let i=0;i<10;i++)floaters.push({a:false});
function spawnText(card){
  const f=floaters.find(f=>!f.a);if(!f)return;
  f.a=true;f.x=GX+card.c*CELL+CELL/2;f.y=GY+card.r*CELL;f.txt='+'+(100+G.combo*25);f.life=1;
}
/* ===== THE SLIMER — canvas-drawn oil villain (glossy black-purple blob, rainbow
   oil swirls, drippy stub arms, smug grin; panic face under the lid; dizzy spiral
   eyes when smothered flat). No text is ever drawn on the character. ===== */
const splashDrops=[];
function spawnSplashDrops(card){
  const bx=GX+card.c*CELL+CELL/2,by=GY+card.r*CELL+CELL/2;
  for(let i=0;i<12;i++){
    splashDrops.push({x:bx+(Math.random()-0.5)*30,y:by+(Math.random()-0.5)*20,
      vx:(Math.random()-0.5)*280,vy:-120-Math.random()*240,life:0.9+Math.random()*0.4,
      c:['#7f5fff','#4fe3ff','#ff5fd0','#ffd23f'][i%4],r:3+Math.random()*4});
  }
}
function drawSlick(cx,cy,w){
  ctx.save();ctx.translate(cx,cy);
  const g=ctx.createLinearGradient(-w,0,w,0);
  g.addColorStop(0,'rgba(127,95,255,.6)');g.addColorStop(0.25,'rgba(79,227,255,.6)');
  g.addColorStop(0.5,'rgba(255,95,208,.6)');g.addColorStop(0.75,'rgba(255,210,63,.6)');
  g.addColorStop(1,'rgba(127,95,255,.6)');
  ctx.fillStyle=g;
  ctx.beginPath();ctx.ellipse(0,0,w,w*0.32,0,0,Math.PI*2);ctx.fill();
  ctx.globalAlpha=0.6;ctx.fillStyle='#fff';
  ctx.beginPath();ctx.ellipse(-w*0.3,-w*0.06,w*0.35,w*0.07,-0.2,0,Math.PI*2);ctx.fill();
  ctx.restore();
}
function drawSlimerFace(S,mood,R){
  const ey=-R*0.12,eyeW=R*0.3,eyeH=mood==='smug'?R*0.2:R*0.32;
