      ctx.fillStyle='#0a0716';
      ctx.beginPath();ctx.arc(ex,ey,R*0.1,0,Math.PI*2);ctx.fill();
      ctx.fillStyle='#fff';
      ctx.beginPath();ctx.arc(ex+R*0.035,ey-R*0.035,R*0.035,0,Math.PI*2);ctx.fill();
    }
