function drawDroppingLid(S,R,cover){
  const w=R*1.5,topY=-R*1.55+(1-cover)*R*2.6; // lid lands as cover builds
  ctx.save();ctx.translate(0,topY);
  ctx.fillStyle='#c3ccd9';ctx.strokeStyle='#5f6a7d';ctx.lineWidth=Math.max(2,S*0.015);
  ctx.beginPath();ctx.ellipse(0,0,w,w*0.42,0,Math.PI,0);ctx.fill();ctx.stroke();
  ctx.fillStyle='#8d97a8';ctx.fillRect(-w,-S*0.008,w*2,S*0.03);
