}
function drawLidRest(S){
  const w=S*0.24;
  ctx.save();ctx.translate(S*0.2,-S*0.14);ctx.rotate(0.5);
  ctx.fillStyle='#c3ccd9';ctx.strokeStyle='#5f6a7d';ctx.lineWidth=2;
  ctx.beginPath();ctx.ellipse(0,0,w,w*0.4,0,0,Math.PI*2);ctx.fill();ctx.stroke();
  ctx.fillStyle='#5f6a7d';ctx.beginPath();ctx.arc(0,0,S*0.03,0,Math.PI*2);ctx.fill();
