  const defeated=!!card.defeated,slide=card.slide||0;
  // rainbow oil slick — under him while he lives, left behind as his matched remnant
  drawSlick(cx,cy+S*0.3,S*0.3*(0.7+0.5*grow)*(defeated?1.35:1));
  ctx.save();
  ctx.translate(cx+slide*S*1.1,cy);
  ctx.globalAlpha=Math.max(0,1-slide*1.5);
  if(defeated){
    // DEFEATED: smothered flat and buried, dizzy spiral eyes, slides off on his slick
    const R=S*0.22;
    ctx.fillStyle='#141020';
    ctx.beginPath();ctx.ellipse(0,S*0.16,R*1.7,R*0.5,0,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#fff';ctx.lineWidth=Math.max(2,S*0.02);
    for(const ex of [-R*0.55,R*0.55]){
      ctx.beginPath();
      for(let a=0;a<Math.PI*4;a+=0.25){const rr=R*0.2*(1-a/(Math.PI*4.4));const px=ex+Math.cos(a)*rr,py=S*0.02+Math.sin(a)*rr;a===0?ctx.moveTo(px,py):ctx.lineTo(px,py);}
