    const sc=grow*(1-0.45*cover);
    const R=S*0.235*sc;
    const w=Math.sin(G.time*9)*0.06*Math.min(1,0.35+wob);
    ctx.scale(1+w,1-w);
    // glossy black-purple blob body
    const bg=ctx.createLinearGradient(0,-R,0,R);
    bg.addColorStop(0,'#41265f');bg.addColorStop(0.55,'#1d1233');bg.addColorStop(1,'#0d0919');
    ctx.fillStyle=bg;
    ctx.beginPath();ctx.ellipse(0,0,R,R*1.02,0,0,Math.PI*2);ctx.fill();
    ctx.lineWidth=Math.max(2,R*0.09);ctx.strokeStyle='#050310';ctx.stroke();
