    ctx.save();ctx.beginPath();ctx.ellipse(0,0,R,R*1.02,0,0,Math.PI*2);ctx.clip();
    const cols=['#ff5fd0','#7f5fff','#4fe3ff','#ffd23f','#8affc1'];
