/* living embers (overhaul) */
const EMBER_SEEDS=Array.from({length:24},(_,i)=>({x:(i*0.61803)%1,y:(i*0.754877)%1,s:1+((i*7)%3),v:12+((i*13)%24),d:((i*29)%20)-10}));
function drawEmbers(bw,bh){ctx.save();ctx.globalCompositeOperation='lighter';const t=(typeof G!=='undefined'&&G.time)||0;
  for(const e of EMBER_SEEDS){const ey=bh-((e.y*bh+t*e.v)%bh);const ex=e.x*bw+Math.sin(t*0.7+e.y*9)*e.d;
    ctx.globalAlpha=0.13+0.09*Math.sin(t*2+e.y*20);ctx.fillStyle='#ff9a3a';
    ctx.beginPath();ctx.arc(ex,ey,e.s,0,Math.PI*2);ctx.fill();}
  ctx.restore();}
const _frontGrads={};let _backGrad=null,_backGradCell=0; // [gauntlet perf] gradient caches
function render(){
  // [gauntlet perf] background gradient cached (was re-created every frame)
  if(!render._bg||render._bgH!==H){const bgn=ctx.createLinearGradient(0,0,0,H);
    bgn.addColorStop(0,'#241038');bgn.addColorStop(0.6,'#160a1e');bgn.addColorStop(1,'#2a0f08');
    render._bg=bgn;render._bgH=H;}
  ctx.fillStyle=render._bg;ctx.fillRect(0,0,W,H);
  drawEmbers(W,H);
  for(const card of G.cards){
    const x=GX+card.c*CELL,y=GY+card.r*CELL;
    // flip animation
    const fs=G.frameScale||1;
    if(card.flip>0&&card.flip<1)card.flip=Math.min(1,card.flip+0.12*fs);
    if(card.flip<0&&card.flip>-1)card.flip=Math.max(-1,card.flip-0.12*fs);
    if(card.flip===-1)card.flip=0;
    // [slimer-fix] was cos(flip*PI/2): at flip=1 sx=0, so EVERY face-up card (incl. the
    // Slimer) rendered as a 5% sliver. cos(flip*PI) is the standard flip: back shrinks
    // 1->0 over the first half, front grows 0->1 over the second half.
    const sx=Math.abs(Math.cos(card.flip*Math.PI));
    const cx=x+CELL/2;
    ctx.save();ctx.translate(cx,y+CELL/2);ctx.scale(Math.max(0.05,sx),1);ctx.translate(-CELL/2,-CELL/2);
    const showingFront=card.flip>0.5||card.matched;
    if(showingFront&&(card.kind==='slimer'||card.kind==='lid')){drawSpecialCard(card);ctx.restore();continue;}
    if(showingFront){
      // [gauntlet perf] face gradient cached per face colour; matched-card shadowBlur=16 (per matched card, per frame) removed — the green fill + stroke already mark matches
      let g=_frontGrads[card.face.c+'|'+CELL];
      if(!g){g=ctx.createLinearGradient(0,0,0,CELL);g.addColorStop(0,'#fff');g.addColorStop(1,card.face.c+'44');_frontGrads[card.face.c+'|'+CELL]=g;}
      ctx.fillStyle=card.matched?'#2a4a2a':g;
      ctx.beginPath();ctx.roundRect(4,4,CELL-8,CELL-8,12);ctx.fill();
      ctx.strokeStyle=card.matched?'#4caf50':card.face.c;ctx.lineWidth=3;ctx.stroke();
      ctx.font=`${CELL*0.4}px system-ui`;ctx.textAlign='center';
      ctx.fillText(card.face.e,CELL/2,CELL/2+CELL*0.14);
      ctx.font=`900 ${CELL*0.13}px system-ui`;ctx.fillStyle='#333';
      ctx.fillText(card.face.n,CELL/2,CELL*0.82);
      ctx.textAlign='left';
      if(card.glow>0){
        ctx.strokeStyle=`rgba(255,210,63,${card.glow})`;ctx.lineWidth=5;
        ctx.beginPath();ctx.roundRect(4,4,CELL-8,CELL-8,12);ctx.stroke();
        card.glow-=0.03*(G.frameScale||1);
      }
    }else{
      // [gauntlet perf] card-back gradient cached
      if(!_backGrad||_backGradCell!==CELL){_backGrad=ctx.createLinearGradient(0,0,CELL,CELL);_backGrad.addColorStop(0,'#3a2a5a');_backGrad.addColorStop(1,'#1a0e2a');_backGradCell=CELL;}
      ctx.fillStyle=_backGrad;
      ctx.beginPath();ctx.roundRect(4,4,CELL-8,CELL-8,12);ctx.fill();
      ctx.strokeStyle='#8a4dff';ctx.lineWidth=2;ctx.stroke();
      ctx.fillStyle='rgba(138,77,255,0.4)';ctx.font=`${CELL*0.35}px system-ui`;ctx.textAlign='center';
      ctx.fillText('🔥',CELL/2,CELL/2+CELL*0.12);ctx.textAlign='left';
    }
    ctx.restore();
  }
  for(const d of splashDrops){
    if(d.life<=0)continue;
    ctx.globalAlpha=Math.min(1,d.life*1.6);
    ctx.fillStyle=d.c;
    ctx.beginPath();ctx.arc(d.x,d.y,d.r,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  ctx.textAlign='center';
  if(G.preview>0){ctx.font='900 26px system-ui';ctx.fillStyle='#ffd23f';ctx.fillText('👀 LOOK & REMEMBER!',W/2,54);}
  for(const f of floaters){
    if(!f.a)continue;
    ctx.globalAlpha=Math.min(1,f.life);
    ctx.font='900 20px system-ui';ctx.fillStyle='#ffd23f';
    ctx.fillText(f.txt,f.x,f.y);
  }
  ctx.globalAlpha=1;ctx.textAlign='left';
}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;if(PAUSED){requestAnimationFrame(loop);return;}G.time+=dt;G.frameScale=Math.min(3,dt*60||1);
  if(G.preview>0){G.preview-=dt;if(G.preview<=0){for(const cd of G.cards)if(!cd.matched)cd.flip=-0.01;G.lock=false;}}
  for(const f of floaters){if(!f.a)continue;f.y-=30*dt;f.life-=dt;if(f.life<=0)f.a=false;}
  for(const cd of G.cards){
    if(cd.kind!=='slimer')continue;
    if(cd.wob>0)cd.wob-=dt;
    if(cd.cover<cd.coverTarget)cd.cover=Math.min(cd.coverTarget,cd.cover+dt*1.5);
    if(cd.defeated&&cd.matched&&cd.slide<1)cd.slide=Math.min(1,cd.slide+dt*1.4);
  }
  for(const d of splashDrops){if(d.life<=0)continue;d.life-=dt;d.x+=d.vx*dt;d.y+=d.vy*dt;d.vy+=760*dt;}
  render();
  requestAnimationFrame(loop);
}
resize();
requestAnimationFrame(loop);

let MUTED=false;try{MUTED=localStorage.getItem('fb_muted')==='1';}catch(e){}
let PAUSED=false,pauseT0=0;
const pauseBanner=document.getElementById('pauseBanner'),btnMuteEl=document.getElementById('btnMute');
function syncMuteBtn(){btnMuteEl.textContent=MUTED?'🔇':'🔊';}
syncMuteBtn();
btnMuteEl.addEventListener('click',e=>{e.stopPropagation();MUTED=!MUTED;try{localStorage.setItem('fb_muted',MUTED?'1':'0');}catch(err){}syncMuteBtn();if(!MUTED)sfx.click();});
function setPaused(p){if(p===PAUSED)return;PAUSED=p;pauseBanner.classList.toggle('hidden',!p);document.getElementById('btnPause').textContent=p?'▶':'⏸';}
document.getElementById('btnPause').addEventListener('click',e=>{e.stopPropagation();if(G.state==='play'&&overlay.classList.contains('hidden'))setPaused(!PAUSED);});
document.getElementById('btnRestart').addEventListener('click',e=>{e.stopPropagation();restartGame();});
function restartGame(){setPaused(false);if(G.state==='title')return;G.score=0;initLevel(G.level);G.state='play';overlay.classList.add('hidden');}
/* ===== MUSIC (Jeff 2026-10-15): 'Slow Melt' — Cinder's Melt-Down's own
   track. Synthesized Web Audio only. 92 BPM, Bb major, half-time: a droopy
   sine lead that slides a semitone down as it plays — every note is
   literally melting — over slow half-note bass and a lazy half-time groove.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-15-cinders-melt-down.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
const MUS={on:false,step:0,nextT:0,BPM:92,
 BASS:[46,0,0,0,0,0,0,0, 51,0,0,0,0,0,0,0, 43,0,0,0,0,0,0,0, 41,0,0,0,48,0,0,0],
 LEAD:[70,0,0,74,0,72,0,0, 75,0,0,74,0,70,0,0, 67,0,0,70,0,74,0,0, 72,0,70,0,69,0,0,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(MUTED||PAUSED||G.state!=='play'){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.5,'sine',0.06,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l-1),0.36,'sine',0.055,d); // melting slide down
  if(s%8===0)tone(105,42,0.14,'sine',0.12,d); // half-time kick
  if(s%8===4)tone(185,115,0.08,'triangle',0.06,d); // lazy tone-only snare
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

