scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR,HOLES=[];
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);layoutHoles();}
function layoutHoles(){
  HOLES=[];
  const cols=3,rows=3;
  const gw=Math.min(W*0.86,420),gh=Math.min(H*0.6,420);
  const ox=(W-gw)/2,oy=(H-gh)/2+40;
  for(let r=0;r<rows;r++)for(let c=0;c<cols;c++)
    HOLES.push({x:ox+gw*(c+0.5)/cols,y:oy+gh*(r+0.5)/rows,r:Math.min(gw,gh)/cols*0.32,
      mole:null});
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);
}
addEventListener('resize',resize);
let AC=null;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
function noise(dur,vol,delay=0,lp=1200){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const len=ac.sampleRate*dur,buf=ac.createBuffer(1,len,ac.sampleRate),d=buf.getChannelData(0);
  for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);
  const s=ac.createBufferSource();s.buffer=buf;const f=ac.createBiquadFilter();f.type='lowpass';f.frequency.value=lp;
  const g=ac.createGain();g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  s.connect(f);f.connect(g);g.connect(ac.destination);s.start(t);}
const sfx={
  bonk(){noise(0.1,0.3,0,800);tone(300,150,0.1,'square',0.15);},
  mallet(){tone(700,1400,0.12,'triangle',0.16);tone(1050,1750,0.12,'triangle',0.12,0.07);noise(0.08,0.15,0,600);},
  golden(){tone(900,1800,0.15,'sine',0.15);tone(1400,2200,0.12,'sine',0.1,0.06);},
  ouch(){tone(400,150,0.2,'sawtooth',0.15);},
  pop(){tone(500,800,0.06,'sine',0.08);},
  end(){[659,523,392,523].forEach((f,i)=>tone(f,f,0.2,'triangle',0.15,i*0.12));},
  click(){tone(600,600,0.06,'square',0.1);}
};
const G={state:'title',score:0,best:0,time:60,combo:1,comboT:0,spawnT:0.5,hits:0,miss:0,anim:0,malletT:0};
try{G.best=parseInt(localStorage.getItem('whack_best')||'0',10)||0;}catch(e){}
function reset(){
  G.score=0;G.time=60;G.combo=1;G.comboT=0;G.spawnT=0.3;G.hits=0;G.miss=0;G.malletT=0;
  for(const h of HOLES)h.mole=null;
  updateHUD();
  document.getElementById('best').textContent='🏆 '+G.best;
}
let _hudCache='';
function updateHUD(){
  const s='⭐ '+G.score,c='🔥 x'+G.combo+(G.malletT>0?' 🔨':'');
  if(_hudCache!==s+c){_hudCache=s+c;document.getElementById('score').textContent=s;document.getElementById('combo').textContent=c;}
  document.getElementById('timerfill').style.width=(G.time/60*100)+'%';
}
function spawnMole(){
  const empty=HOLES.filter(h=>!h.mole);
  if(!empty.length)return;
  const h=empty[Math.floor(Math.random()*empty.length)];
  const r=Math.random();
  let type='rock';
  if(r<0.06&&G.malletT<=0)type='mallet'; // Golden Mallet pickup!
  else if(r<0.17)type='golden';
  else if(r<0.35)type='baby'; // don't hit!
  const speedMul=1+(60-G.time)/60; // faster over time
  h.mole={type,pop:0,up:1,life:(type==='baby'?1.4:type==='mallet'?1.3:1.1)/speedMul,bonked:false,wob:Math.random()*6};
  sfx.pop();
}
canvas.addEventListener('pointerdown',e=>{
  if(G.state!=='play'||PAUSED)return;
  const rect=canvas.getBoundingClientRect();
  const x=e.clientX-rect.left,y=e.clientY-rect.top;
  let hit=false;
  for(const h of HOLES){
    if(!h.mole||h.mole.bonked||h.mole.pop<0.6)continue;
    if(Math.hypot(x-h.x,y-h.y-h.r*0.4)<h.r*(G.malletT>0?1.4:1.15)){
      hit=true;h.mole.bonked=true;h.mole.pop=1.2;
      if(h.mole.type==='mallet'){
        // Golden Mallet: +25% points & bigger bonk radius for 5s
        G.malletT=5;G.hits++;sfx.mallet();
        spawnText(h.x,h.y-h.r,'🔨 GOLDEN MALLET!','#ffd23f');
        burst(h.x,h.y-h.r*0.5,'#ffd23f');
      }else if(h.mole.type==='baby'){
        // oops! penalty
        G.score=Math.max(0,G.score-50);G.combo=1;
        sfx.ouch();G.miss++;
        spawnText(h.x,h.y-h.r,'-50 😢','#ff4a5a');
      }else{
        const pts=Math.round((h.mole.type==='golden'?50:10)*G.combo*(G.malletT>0?1.25:1));
        G.score+=pts;G.hits++;
        G.combo=Math.min(8,G.combo+1);G.comboT=2.5;
        if(h.mole.type==='golden')sfx.golden();else sfx.bonk();
        spawnText(h.x,h.y-h.r,'+'+pts,h.mole.type==='golden'?'#ffd23f':'#fff');
        burst(h.x,h.y-h.r*0.5,h.mole.type==='golden'?'#ffd23f':'#ffb347');
      }
      updateHUD();
      break;
    }
  }
  if(!hit){G.combo=Math.max(1,G.combo-1);updateHUD();}
});
const particles=[],floaters=[];
const embers=[];
for(let i=0;i<24;i++)embers.push({x:Math.random()*2400,y:Math.random()*1600,s:1+Math.random()*2.5,vy:14+Math.random()*26,vx:(Math.random()-0.5)*8,ph:Math.random()*6});
function updateEmbers(dt){for(const e of embers){e.y-=e.vy*dt;e.x+=e.vx*dt+Math.sin(G.anim*2+e.ph)*6*dt;if(e.y<-12){e.y=H+12;e.x=Math.random()*W;}if(e.x<-4)e.x+=W+8;if(e.x>W+4)e.x-=W+8;}}
/* [w5c perf] Pre-baked glow sprites — the W5b-proven pattern copied from game-04:
   the ember loop's 24 per-frame shadowBlur=8 fills collapsed FPS under software
   rendering (10.0 FPS); blit a one-time radial-glow sprite instead. Colours,
   falloff and alpha unchanged; no gameplay/balance changes. */
function makeGlowSprite(hex){const c=document.createElement('canvas');c.width=c.height=96;const x=c.getContext('2d');
  const r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);
  const gr=x.createRadialGradient(48,48,0,48,48,48);
  gr.addColorStop(0,`rgba(${r},${g},${b},0.9)`);gr.addColorStop(0.35,`rgba(${r},${g},${b},0.38)`);gr.addColorStop(1,`rgba(${r},${g},${b},0)`);
  x.fillStyle=gr;x.fillRect(0,0,96,96);return c;}
const EMBER_SPRITE=makeGlowSprite('#ff8a3a');
const MOLE_GLOW_FIRE=makeGlowSprite('#ff7a2a'); // [gauntlet perf] mole glow sprites
const MOLE_GLOW_GOLD=makeGlowSprite('#ffd23f'); // [gauntlet perf]
function drawEmbers(){ctx.save();ctx.globalCompositeOperation='lighter';for(const e of embers){const tw=0.5+0.5*Math.sin(G.anim*3+e.ph);ctx.globalAlpha=0.10+0.16*tw;const r=e.s*7;ctx.drawImage(EMBER_SPRITE,e.x-r,e.y-r,r*2,r*2);}ctx.restore();ctx.globalAlpha=1;}

for(let i=0;i<100;i++)particles.push({a:false});
for(let i=0;i<12;i++)floaters.push({a:false});
function burst(x,y,color){
  for(let i=0;i<10;i++){const p=particles.find(p=>!p.a);if(!p)break;
    const a=Math.random()*Math.PI*2;
    p.a=true;p.x=x;p.y=y;p.vx=Math.cos(a)*200;p.vy=Math.sin(a)*200-100;
    p.life=0.4;p.max=0.4;p.color=color;p.size=3+Math.random()*4;}
}
function spawnText(x,y,txt,color){
  const f=floaters.find(f=>!f.a);if(!f)return;
  f.a=true;f.x=x;f.y=y;f.txt=txt;f.color=color;f.life=1;
}
function update(dt){
  G.time-=dt;G.comboT-=dt;G.malletT=Math.max(0,G.malletT-dt);
  if(G.comboT<=0&&G.combo>1){G.combo--;G.comboT=0.8;} // step down gradually, not instantly
  if(G.time<=0){endGame();return;}
  // spawn rate increases
  G.spawnT-=dt;
  if(G.spawnT<=0){
    spawnMole();
    const base=Math.max(0.25,0.7-(60-G.time)/60*0.45);
    G.spawnT=base+Math.random()*0.3;
    // sometimes double
    if(Math.random()<0.3)spawnMole();
  }
  for(const h of HOLES){
    const m=h.mole;
    if(!m)continue;
    m.wob+=dt*8;
    if(m.pop<1)m.pop=Math.min(1,m.pop+dt*5);
    else{
      m.life-=dt;
      if(m.life<=0){m.pop-=dt*6;if(m.pop<=0)h.mole=null;}
    }
    if(m.bonked){m.pop+=dt*8;if(m.pop>=1.6)h.mole=null;}
  }
  updateHUD();
}
function endGame(){
  G.state='over';sfx.end();
  for(const h of HOLES)h.mole=null;
  const isBest=G.score>G.best;
  if(isBest){G.best=G.score;try{localStorage.setItem('whack_best',String(G.best));}catch(e){}}
  const acc=G.hits+G.miss?Math.round(G.hits/(G.hits+G.miss)*100):100;
  setTimeout(()=>{
    showOverlay('⏰ TIME UP!',
      `${isBest?'<p style="color:#ffd23f;font-weight:900">🏆 NEW BEST!</p>':''}<p style="font-size:26px;font-weight:900">Score: ${G.score}</p><p>Bonks: ${G.hits} | Oops: ${G.miss} | Accuracy: ${acc}%</p><p>Best: ${G.best}</p>`,
      '🔥 Fire Safety: Fast reactions save lives — practice your fire drill!',
      '↻ PLAY AGAIN',()=>{reset();G.state='play';});
  },500);
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  setPaused(false);
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();reset();G.state='play';overlay.classList.add('hidden');}
obtn.onclick=()=>{showMathGate();};
function drawMole(h,m){
  const popE=m.pop<1?m.pop:Math.max(0,2-m.pop); // 0→1 up, 1→2 bonk squash
  const y=h.y-h.r*0.9*popE;
  const squash=m.bonked?0.4:0;
  ctx.save();ctx.translate(h.x,y);ctx.scale(1+squash,1-squash);
  const wob=Math.sin(m.wob)*0.08;
  ctx.rotate(wob);
  // [gauntlet perf] was shadowColor/shadowBlur=16 on every mole every frame — pre-baked glow sprite behind the body instead (15/25 sweep class)
  if(m.type==='baby'||m.type==='golden'||m.type==='mallet'){
    ctx.save();ctx.globalAlpha=0.5;const gr2=h.r*2.0;
    ctx.drawImage(m.type==='baby'?MOLE_GLOW_FIRE:MOLE_GLOW_GOLD,-gr2,-gr2,gr2*2,gr2*2);ctx.restore();
  }
  if(m.type==='baby'){
    // fire baby: DON'T HIT
    const g=ctx.createRadialGradient(-8,-10,4,0,0,h.r);
    g.addColorStop(0,'#ffe9a0');g.addColorStop(0.5,'#ff7a2a');g.addColorStop(1,'#d42a1a');
    ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,h.r*0.85,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#2b1a0e';
    ctx.beginPath();ctx.arc(-8,-4,4,0,Math.PI*2);ctx.arc(8,-4,4,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#2b1a0e';ctx.lineWidth=2.5;ctx.lineCap='round';
    ctx.beginPath();ctx.arc(0,4,8,0.3,Math.PI-0.3);ctx.stroke();
    // "friend" indicator
    ctx.fillStyle='#4caf50';ctx.font=`900 ${h.r*0.4}px system-ui`;ctx.textAlign='center';
    ctx.fillText('💚',0,-h.r-6);ctx.textAlign='left';
  }else{
    const g=ctx.createRadialGradient(-8,-8,4,0,0,h.r);
    if(m.type==='golden'||m.type==='mallet'){g.addColorStop(0,'#fff');g.addColorStop(0.5,'#ffd23f');g.addColorStop(1,'#a37a00');}
    else{g.addColorStop(0,'#9a8a7a');g.addColorStop(1,'#4a3a2a');}
    ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,h.r*0.85,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#2a1a0a';ctx.lineWidth=2;ctx.stroke();
    // angry eyes
    ctx.fillStyle=m.type==='golden'?'#7a5a00':'#ff4a00';
    ctx.beginPath();ctx.arc(-9,-6,5,0,Math.PI*2);ctx.arc(9,-6,5,0,Math.PI*2);ctx.fill();
    // hard hat
    ctx.fillStyle='#ffd23f';
    ctx.beginPath();ctx.arc(0,-h.r*0.5,h.r*0.5,Math.PI,0);ctx.fill();
    ctx.fillRect(-h.r*0.7,-h.r*0.55,h.r*1.4,6);
    if(m.type==='mallet'){ctx.font=`900 ${h.r*0.55}px system-ui`;ctx.textAlign='center';ctx.fillText('🔨',0,-h.r-4);ctx.textAlign='left';}
  }
  ctx.restore();
}
function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#1a0d08');bg.addColorStop(1,'#3a1a0a');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  drawEmbers();
  // lava glow behind
  for(const h of HOLES){
    const lg=ctx.createRadialGradient(h.x,h.y,5,h.x,h.y,h.r*2);
    lg.addColorStop(0,'rgba(255,74,0,0.25)');lg.addColorStop(1,'rgba(255,74,0,0)');
    ctx.fillStyle=lg;ctx.beginPath();ctx.arc(h.x,h.y,h.r*2,0,Math.PI*2);ctx.fill();
    // hole
    ctx.fillStyle='#0a0505';
    ctx.beginPath();ctx.ellipse(h.x,h.y,h.r*1.1,h.r*0.45,0,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#ff4a00';ctx.lineWidth=3;
    ctx.beginPath();ctx.ellipse(h.x,h.y,h.r*1.1,h.r*0.45,0,0,Math.PI*2);ctx.stroke();
    // lava inside
    ctx.fillStyle='#ff4a00';ctx.globalAlpha=0.5+Math.sin(G.anim*5+h.x)*0.2;
    ctx.beginPath();ctx.ellipse(h.x,h.y+2,h.r*0.85,h.r*0.3,0,0,Math.PI*2);ctx.fill();
    ctx.globalAlpha=1;
  }
  // moles (behind holes drawn after for pop effect)
  for(const h of HOLES)if(h.mole)drawMole(h,h.mole);
  // hammer cursor hint
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  if(G.state==='play'&&G.time>56){ // [gauntlet clarity] goal line while the first moles pop
    const _pw2=Math.min(430,W-16); // [gauntlet fix] pill sized to fit phone widths
    ctx.fillStyle='rgba(0,0,0,0.45)';ctx.beginPath();ctx.roundRect(W/2-_pw2/2,64,_pw2,34,10);ctx.fill();
    ctx.fillStyle='#fff';ctx.font='900 '+(W<520?13:16)+'px system-ui';ctx.textAlign='center';
    ctx.fillText('TAP THE GOLDEN ONES — NEVER THE BABYS!',W/2,86);
    ctx.textAlign='left';
  }
  ctx.textAlign='center';
  for(const f of floaters){
    if(!f.a)continue;
    ctx.globalAlpha=Math.min(1,f.life);
    ctx.font='900 22px system-ui';ctx.fillStyle='#000';
    ctx.fillText(f.txt,f.x+2,f.y+2);ctx.fillStyle=f.color;ctx.fillText(f.txt,f.x,f.y);
  }
  ctx.globalAlpha=1;ctx.textAlign='left';
}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;if(PAUSED){requestAnimationFrame(loop);return;}G.anim+=dt;updateEmbers(dt); // countdown handled in update()
  if(G.state==='play')update(dt);
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=600*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  for(const f of floaters){if(!f.a)continue;f.y-=40*dt;f.life-=dt;if(f.life<=0)f.a=false;}
  render();
  requestAnimationFrame(loop);
}
resize();
document.getElementById('best').textContent='🏆 '+G.best;
requestAnimationFrame(loop);

let MUTED=false;try{MUTED=localStorage.getItem('fb_muted')==='1';}catch(e){}
let PAUSED=false,pauseT0=0;
const pauseBanner=document.getElementById('pauseBanner'),btnMuteEl=document.getElementById('btnMute');
function syncMuteBtn(){btnMuteEl.textContent=MUTED?'🔇':'🔊';}
syncMuteBtn();
btnMuteEl.addEventListener('click',e=>{e.stopPropagation();MUTED=!MUTED;try{localStorage.setItem('fb_muted',MUTED?'1':'0');}catch(err){}syncMuteBtn();if(!MUTED)sfx.click();});
function setPaused(p){if(p===PAUSED)return;PAUSED=p;pauseBanner.classList.toggle('hidden',!p);document.getElementById('btnPause').textContent=p?'▶':'⏸';}
document.getElementById('btnPause').addEventListener('click',e=>{e.stopPropagation();if(G.state==='play'&&overlay.classList.contains('hidden'))setPaused(!PAUSED);});
document.getElementById('btnRestart').addEventListener('click',e=>{e.stopPropagation();restartGame();});
function restartGame(){setPaused(false);if(G.state==='title')return;reset();G.state='play';overlay.classList.add('hidden');}
/* ===== MUSIC (Jeff 2026-10-15): 'Freefall Furnace' — Inferno Drop's own
   track. Synthesized Web Audio only. 128 BPM, C minor: the sawtooth lead
   arpeggiates DOWN a little further every bar while the bass line sinks
   under it — a controlled freefall.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-16-inferno-drop.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
const MUS={on:false,step:0,nextT:0,BPM:128,
 BASS:[48,0,48,0,46,0,44,0, 44,0,44,0,43,0,41,0, 39,0,39,0,41,0,43,0, 46,0,44,0,43,0,41,0],
 LEAD:[84,0,79,0,75,0,72,0, 82,0,79,0,77,0,75,0, 79,0,75,0,72,0,67,0, 75,0,72,0,70,0,67,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(MUTED||PAUSED||G.state!=='play'){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.14,'sawtooth',0.055,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.13,'sawtooth',0.045,d);
  if(s%8===0||s%8===4)tone(120,45,0.11,'sine',0.13,d); // kick
  if(s%8===2||s%8===6)noise(0.08,0.08,d,1750); // snare
  if(s%2===0)noise(0.02,0.016,d,6800); // hat
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

