#fb-seasonal-banner .fb-sb-sub{font-size:clamp(12px,2.6vw,14.5px);font-weight:600;color:#e9defc;margin-top:3px;line-height:1.4}
/* ---- decoration layers (never clickable, below menus) ---- */
#fb-seasonal-wall{position:fixed;inset:0;pointer-events:none;z-index:0;overflow:hidden}
#fb-seasonal-wall .fb-sb-wall-glyph{position:absolute;line-height:1;opacity:.09}
#fb-seasonal-decor{position:fixed;inset:0;pointer-events:none;z-index:90}
html.fb-mode-game #fb-seasonal-decor{z-index:2}
#fb-seasonal-decor .fb-sb-glyph{position:absolute;line-height:1;filter:drop-shadow(0 4px 10px rgba(0,0,0,.45))}
#fb-seasonal-ambience{position:fixed;inset:0;pointer-events:none;z-index:89;overflow:hidden}
#fb-seasonal-ambience .fb-sb-fall{position:absolute;top:-8vh;line-height:1;opacity:.5;animation-name:fb-sb-fall;animation-timing-function:linear;animation-iteration-count:infinite}
@keyframes fb-sb-fall{from{transform:translate3d(0,-8vh,0) rotate(-8deg)}to{transform:translate3d(3vw,112vh,0) rotate(38deg)}}
@keyframes fb-sb-bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-9px)}}
.fb-sb-bob{animation:fb-sb-bob 3.6s ease-in-out infinite}
/* ---- game-page badge ---- */
.fb-sb-badge{position:absolute;left:50%;bottom:6px;transform:translateX(-50%);font-size:17px;letter-spacing:2px;opacity:.55;line-height:1;white-space:nowrap}
/* ---- accents: every page ---- */
html.fb-theme-halloween ::selection{background:rgba(255,140,26,.5);color:#fff}
html.fb-mode-page body{background-color:#1c0a2a}
/* ---- hub showcase: deep-purple night + pumpkin glow ---- */
html.fb-mode-hub body{background:radial-gradient(1100px 560px at 50% -120px,rgba(124,58,237,.34),transparent 62%),radial-gradient(700px 380px at 85% 110%,rgba(255,140,26,.16),transparent 60%),#170a26}
html.fb-mode-hub nav.top{background:rgba(23,10,38,.96);border-bottom-color:rgba(155,89,182,.55)}
html.fb-mode-hub .hero{background:radial-gradient(ellipse at 50% 0%,rgba(255,140,26,.20),transparent 65%);border-bottom-color:rgba(155,89,182,.55)}
html.fb-mode-hub .hero h1{color:#ffb347;text-shadow:0 0 26px rgba(124,58,237,.65),0 4px 30px rgba(255,106,26,.35)}
html.fb-mode-hub .card{border-color:rgba(155,89,182,.5)}
html.fb-mode-hub .card:hover{border-color:#ff8c1a;box-shadow:0 16px 36px rgba(0,0,0,.45),0 0 26px rgba(124,58,237,.35)}
html.fb-mode-hub footer{border-top-color:rgba(155,89,182,.5)}
html.fb-mode-hub .hero,html.fb-mode-hub .whatsnew,html.fb-mode-hub .wrap,html.fb-mode-hub footer{position:relative;z-index:1}
/* ---- reduced motion: no falling/floating glyphs ---- */
@media (prefers-reduced-motion: reduce){#fb-seasonal-ambience{display:none}.fb-sb-bob{animation:none}}

scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson'),
      comboPop=document.getElementById('comboPop');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();
let AC=null;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  drop(){tone(500,300,0.08,'square',0.1);},
  perfect(){tone(800,1200,0.12,'sine',0.14);tone(1200,1600,0.1,'sine',0.1,0.05);},
  trim(){tone(400,200,0.1,'sawtooth',0.1);},
  miss(){tone(300,100,0.25,'sawtooth',0.14);},
  win(){[523,659,784,1047].forEach((f,i)=>tone(f,f,0.25,'triangle',0.18,i*0.1));},
  click(){tone(600,600,0.06,'square',0.1);}
};
const G={state:'title',score:0,best:0,height:0,misses:0,combo:0,
  blocks:[],cur:null,camY:0,time:0,shake:0};
try{G.best=parseInt(localStorage.getItem('stack_best')||'0',10)||0;}catch(e){}
const BH=34;
function reset(){
  G.score=0;G.height=0;G.misses=0;G.combo=0;G.blocks=[];G.camY=0;
  const bw=Math.min(W*0.6,300);
  G.blocks.push({x:W/2-bw/2,w:bw,y:H*0.85,hue:20});
  spawnBlock();
  updateHUD();
  document.getElementById('best').textContent='🏆 '+G.best;
}
function spawnBlock(){
  const prev=G.blocks[G.blocks.length-1];
  const speed=Math.min(520,220+G.height*14);
  const dir=Math.random()<0.5?-1:1;
  G.cur={x:dir>0?-prev.w:W,y:prev.y-BH,w:prev.w,vx:speed*dir,hue:(prev.hue+14)%360};
}
function updateHUD(){
  document.getElementById('score').textContent='⭐ '+G.score;
  document.getElementById('height').textContent='🗼 '+G.height;
}
function drop(){
  if(G.state!=='play'||!G.cur||PAUSED)return;
  const cur=G.cur,prev=G.blocks[G.blocks.length-1];
  const overlapL=Math.max(cur.x,prev.x),overlapR=Math.min(cur.x+cur.w,prev.x+prev.w);
  const overlap=overlapR-overlapL;
  sfx.drop();
  if(overlap<=0){
    // total miss
    G.misses++;G.combo=0;sfx.miss();G.shake=0.5;
    // block falls
    cur.falling=true;cur.vy=0;
    if(G.misses>=3){gameOver();return;}
    spawnBlock();
    G.blocks.push({x:cur.x,w:cur.w,y:cur.y,hue:cur.hue,falling:true,vy:0,dead:true}); // the missed block visibly falls
    updateHUD();
    return;
  }
  const perfect=Math.abs((cur.x+cur.w/2)-(prev.x+prev.w/2))<12;
  burst17(cur.x+cur.w/2,cur.y,perfect?'#ffd23f':`hsl(${cur.hue},80%,65%)`,perfect?16:7);
  if(perfect){
    // snap to prev
    cur.x=prev.x;cur.w=prev.w;
    G.combo++;
    const pts=50+G.combo*20;
    G.score+=pts;sfx.perfect();
    comboPop.textContent=G.combo>=3?`PERFECT x${G.combo}!`:'PERFECT!';
    comboPop.classList.remove('pop');void comboPop.offsetWidth;comboPop.classList.add('pop');
    setTimeout(()=>comboPop.classList.remove('pop'),400);
  }else{
    G.combo=0;
    // trim overhang
    const trimmed=cur.w-overlap;
    if(trimmed>0){
      sfx.trim();
      // falling piece
      G.blocks.push({x:cur.x<prev.x?cur.x:overlapR,w:trimmed,y:cur.y,hue:cur.hue,falling:true,vy:0,dead:true});
    }
    cur.x=overlapL;cur.w=overlap;
    G.score+=25;
  }
  cur.y=prev.y-BH;
  G.blocks.push({x:cur.x,w:cur.w,y:cur.y,hue:cur.hue});
  G.height++;G.score+=10;
  updateHUD();
  if(G.height>=50){gameWin();return;}
  spawnBlock();
}
canvas.addEventListener('pointerdown',e=>{e.preventDefault();drop();});
addEventListener('keydown',e=>{if(e.repeat)return;if(e.key===' '||e.key==='Enter'){drop();e.preventDefault();}});
const particles=[];
for(let i=0;i<80;i++)particles.push({a:false});
const embers=[];
for(let i=0;i<24;i++)embers.push({x:Math.random()*2400,y:Math.random()*1600,s:1+Math.random()*2.5,vy:14+Math.random()*26,vx:(Math.random()-0.5)*8,ph:Math.random()*6});
function updateEmbers(dt){for(const e of embers){e.y-=e.vy*dt;e.x+=e.vx*dt+Math.sin(G.time*2+e.ph)*6*dt;if(e.y<-12){e.y=H+12;e.x=Math.random()*W;}if(e.x<-4)e.x+=W+8;if(e.x>W+4)e.x-=W+8;}}
/* [w5c perf] Pre-baked glow sprites — the W5b-proven pattern copied from game-04:
   the ember loop's 24 per-frame shadowBlur=8 fills collapsed FPS under software
   rendering (10.0 FPS); blit a one-time radial-glow sprite instead. Colours,
   falloff and alpha unchanged; no gameplay/balance changes. */
function makeGlowSprite(hex){const c=document.createElement('canvas');c.width=c.height=96;const x=c.getContext('2d');
  const r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);
  const gr=x.createRadialGradient(48,48,0,48,48,48);
  gr.addColorStop(0,`rgba(${r},${g},${b},0.9)`);gr.addColorStop(0.35,`rgba(${r},${g},${b},0.38)`);gr.addColorStop(1,`rgba(${r},${g},${b},0)`);
  x.fillStyle=gr;x.fillRect(0,0,96,96);return c;}
const EMBER_SPRITE=makeGlowSprite('#ff8a3a');
function drawEmbers(){ctx.save();ctx.globalCompositeOperation='lighter';for(const e of embers){const tw=0.5+0.5*Math.sin(G.time*3+e.ph);ctx.globalAlpha=0.10+0.16*tw;const r=e.s*7;ctx.drawImage(EMBER_SPRITE,e.x-r,e.y-r,r*2,r*2);}ctx.restore();ctx.globalAlpha=1;}

function burst17(x,y,color,n){for(let i=0;i<n;i++){const p=particles.find(p=>!p.a);if(!p)break;const a=Math.random()*Math.PI*2;p.a=true;p.x=x;p.y=y;p.vx=Math.cos(a)*170;p.vy=Math.sin(a)*170-70;p.life=0.45;p.max=0.45;p.color=color;p.size=3+Math.random()*3;}}
function update(dt){
  G.time+=dt;G.shake=Math.max(0,G.shake-dt*3);
  for(let i=G.blocks.length-1;i>=0;i--)if(G.blocks[i].gone)G.blocks.splice(i,1); // cull fallen pieces: array no longer grows forever
  if(G.cur&&!G.cur.falling){
    G.cur.x+=G.cur.vx*dt;
    if(G.cur.x<=-G.cur.w){G.cur.x=-G.cur.w;G.cur.vx=Math.abs(G.cur.vx);}
    if(G.cur.x>=W){G.cur.x=W;G.cur.vx=-Math.abs(G.cur.vx);}
  }
  // falling pieces
  for(const b of G.blocks){
    if(b.falling||b.dead){b.vy=(b.vy||0)+2000*dt;b.y+=(b.vy||0)*dt;
      if(b.y>H-G.camY+60)b.gone=true;}
  }
  // camera ease
  const target=Math.max(0,(G.height-7)*BH); // height-based: trimmed falling pieces in G.blocks must not move the camera
  G.camY+=(target-G.camY)*Math.min(1,dt*4);
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)p.a=false;}
}
function gameOver(){
  G.state='over';
  const isBest=G.score>G.best;
  if(isBest){G.best=G.score;try{localStorage.setItem('stack_best',String(G.best));}catch(e){}}
  setTimeout(()=>{
    showOverlay('💥 TOWER TOPPLED!',
      `${isBest?'<p style="color:#ffd23f;font-weight:900">🏆 NEW BEST!</p>':''}<p style="font-size:24px;font-weight:900">Score: ${G.score}</p><p>Height: ${G.height} blocks</p><p>Best: ${G.best}</p>`,
      '🔥 Fire Safety: Build your tower of safety knowledge!',
      '↻ STACK AGAIN',()=>{reset();G.state='play';});
  },600);
}
function gameWin(){
  G.state='clear';sfx.win();
  const isBest=G.score>G.best;
  if(isBest){G.best=G.score;try{localStorage.setItem('stack_best',String(G.best));}catch(e){}}
  setTimeout(()=>{
    showOverlay('🏆 SKY HIGH!',
      `<p>50 blocks stacked!</p><p style="font-size:24px;font-weight:900">Score: ${G.score}</p>`,
      '🔥 Fire Safety: You\'re a champion!',
      '↻ PLAY AGAIN',()=>{reset();G.state='play';});
  },600);
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  setPaused(false);
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();reset();G.state='play';overlay.classList.add('hidden');}
obtn.onclick=()=>{showMathGate();};
function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#0d1420');bg.addColorStop(1,'#1a2438');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  // stars
  ctx.fillStyle='rgba(255,255,255,0.4)';
  for(let i=0;i<40;i++){
    const sx=(i*197)%W,sy=(i*131)%H;
    ctx.globalAlpha=0.15+((i*37)%40)/100;
    ctx.fillRect(sx,sy,2,2);
  }
  ctx.globalAlpha=1;
  drawEmbers();
  ctx.save();
  if(G.shake>0)ctx.translate((Math.random()-0.5)*G.shake*14,(Math.random()-0.5)*G.shake*14);
  ctx.translate(0,G.camY); // camY scrolls the tower DOWN into view as it grows up (sign was inverted)
  // blocks
  for(const b of G.blocks){
    if(b.gone)continue;
    const y=b.y;
    if(y<-G.camY-BH||y>H-G.camY+BH)continue;
    const g=ctx.createLinearGradient(0,y,0,y+BH);
    g.addColorStop(0,`hsl(${b.hue},70%,55%)`);g.addColorStop(1,`hsl(${b.hue},70%,35%)`);
    ctx.fillStyle=g;
    ctx.beginPath();ctx.roundRect(b.x,y,b.w,BH,6);ctx.fill();
    ctx.strokeStyle='rgba(255,255,255,0.3)';ctx.lineWidth=2;ctx.stroke();
    // shine
    ctx.fillStyle='rgba(255,255,255,0.15)';
    ctx.fillRect(b.x+6,y+4,b.w-12,6);
  }
  // current sliding block
  const cur=G.cur;
  if(cur&&G.state==='play'){
    const g=ctx.createLinearGradient(0,cur.y,0,cur.y+BH);
    g.addColorStop(0,`hsl(${cur.hue},80%,60%)`);g.addColorStop(1,`hsl(${cur.hue},80%,40%)`);
    ctx.fillStyle=g;
    ctx.shadowColor='#ffd76a';ctx.shadowBlur=18;
    ctx.globalAlpha=0.95;
    ctx.beginPath();ctx.roundRect(cur.x,cur.y,cur.w,BH,6);ctx.fill();
    ctx.shadowBlur=0;
    ctx.globalAlpha=1;
    ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.stroke();
    // drop guide
    ctx.strokeStyle='rgba(255,255,255,0.2)';ctx.lineWidth=2;ctx.setLineDash([8,8]);
    ctx.beginPath();ctx.moveTo(cur.x+cur.w/2,cur.y+BH);ctx.lineTo(cur.x+cur.w/2,H-G.camY);ctx.stroke();
    ctx.setLineDash([]);
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  ctx.restore();
  // misses
  ctx.fillStyle='rgba(255,74,90,0.9)';ctx.font='900 18px system-ui';
  ctx.fillText('❌'.repeat(G.misses)+'🤍'.repeat(3-G.misses),16,H-56);
}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;if(PAUSED){requestAnimationFrame(loop);return;}
  if(G.state==='play')update(dt);else G.time+=dt;
  updateEmbers(dt);
  render();
  requestAnimationFrame(loop);
}
document.getElementById('best').textContent='🏆 '+G.best;
requestAnimationFrame(loop);

let MUTED=false;try{MUTED=localStorage.getItem('fb_muted')==='1';}catch(e){}
let PAUSED=false,pauseT0=0;
const pauseBanner=document.getElementById('pauseBanner'),btnMuteEl=document.getElementById('btnMute');
function syncMuteBtn(){btnMuteEl.textContent=MUTED?'🔇':'🔊';}
syncMuteBtn();
btnMuteEl.addEventListener('click',e=>{e.stopPropagation();MUTED=!MUTED;try{localStorage.setItem('fb_muted',MUTED?'1':'0');}catch(err){}syncMuteBtn();if(!MUTED)sfx.click();});
function setPaused(p){if(p===PAUSED)return;PAUSED=p;pauseBanner.classList.toggle('hidden',!p);document.getElementById('btnPause').textContent=p?'▶':'⏸';}
document.getElementById('btnPause').addEventListener('click',e=>{e.stopPropagation();if(G.state==='play'&&overlay.classList.contains('hidden'))setPaused(!PAUSED);});
document.getElementById('btnRestart').addEventListener('click',e=>{e.stopPropagation();restartGame();});
function restartGame(){setPaused(false);if(G.state==='title')return;reset();G.state='play';overlay.classList.add('hidden');}
/* ===== MUSIC (Jeff 2026-10-15): 'Sprint Spark' — Flame Sprint 2D's own
   track. Synthesized Web Audio only. 156 BPM, E major pentatonic: a chip
   square lead over a relentless eighth-note ostinato bass — no coasting,
   full sprint.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-17-flame-sprint-2d.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
const MUS={on:false,step:0,nextT:0,BPM:156,
 BASS:[40,40,40,40,40,40,40,40, 47,47,47,47,47,47,47,47, 49,49,49,49,49,49,49,49, 45,45,45,45,45,45,47,47],
 LEAD:[76,0,80,0,83,0,80,0, 83,0,85,0,83,0,80,0, 85,0,88,0,85,0,83,0, 78,0,80,0,76,0,73,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(MUTED||PAUSED||G.state!=='play'){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.1,'square',0.05,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.11,'square',0.045,d);
  if(s%2===0)tone(124,45,0.1,'sine',0.13,d); // driving kick
  if(s%8===2||s%8===6)tone(190,120,0.07,'triangle',0.07,d); // tone-only snare
  tone(7000,7000,0.012,'square',0.006,d); // hat click
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

