function findFloating(){
  // BFS from top row
  const seen=new Set(),stack=[];
  if(G.grid[0])for(let c=0;c<G.grid[0].length;c++)if(G.grid[0][c]){seen.add('0,'+c);stack.push({r:0,c});}
  while(stack.length){
    const cur=stack.pop();
    for(const nb of neighbors(cur.r,cur.c)){
      const k=nb.r+','+nb.c;
      if(!seen.has(k)){seen.add(k);stack.push(nb);}
    }
  }
  const floating=[];
  for(let r=0;r<G.grid.length;r++)for(let c=0;c<(G.grid[r]?G.grid[r].length:0);c++)
    if(G.grid[r][c]&&!seen.has(r+','+c))floating.push({r,c});
  return floating;
}
