function snapBubble(){
  const f=G.flying;G.flying=null;
  if(!G.bombReady&&G.shots>0&&G.shots%6===0){G.bombReady=true;spawnText(W/2,H*0.55,'💣 EMBER BOMB READY — TAP NEXT!');updateHUD();}
  // find nearest empty cell (existing rows + one new row below the grid).
  // The scan bound is snapshotted BEFORE the loop: creating that new row
  // inside the loop used to grow G.grid.length as fast as r advanced, so
  // the bound receded forever, the grid grew without limit, and the
  // engine eventually threw RangeError "Invalid array length".
  let best=null,bd=1e9;
  const scanRows=G.grid.length+1;
  for(let r=0;r<scanRows;r++){
    if(!G.grid[r])G.grid[r]=[];
    const maxC=COLS-(r%2?1:0);
    for(let c=0;c<maxC;c++){
      if(G.grid[r][c])continue;
      const p=gridPos(r,c);
      const d=Math.hypot(f.x-p.x,f.y-p.y);
      if(d<bd){bd=d;best={r,c};}
    }
  }
  if(!best)return;
  // ensure row exists
  while(G.grid.length<=best.r)G.grid.push([]);
  G.grid[best.r][best.c]={c:f.c,pop:0.01};
  sfx.stick();
  // check cluster
  let cluster=findCluster(best.r,best.c);
  if(f.bomb){
    // Ember Bomb: also pop up to 3 neighbouring bubbles of any colour (capped for balance)
    const inCluster=new Set(cluster.map(cell=>cell.r+','+cell.c));
    const extra=[];
    for(const cell of cluster){for(const nb of neighbors(cell.r,cell.c)){
      const k=nb.r+','+nb.c;
      if(!inCluster.has(k)&&G.grid[nb.r][nb.c]){inCluster.add(k);extra.push(nb);if(extra.length>=3)break;}
    }if(extra.length>=3)break;}
    cluster=cluster.concat(extra);
  }
  if(cluster.length>=3||(f.bomb&&cluster.length>=1)){
    for(const cell of cluster){
      G.grid[cell.r][cell.c].pop=0.3;
      G.grid[cell.r][cell.c].popping=true;
    }
    const pts=cluster.length*60;
    G.score+=pts;sfx.pop(cluster.length);G.shake=0.25;
    spawnText(f.x,f.y,'+'+pts);
    for(const cell of cluster){
      const p=gridPos(cell.r,cell.c);
      burst(p.x,p.y,COLORS[G.grid[cell.r][cell.c].c]);
    }
    setTimeout(()=>{
      for(const cell of cluster)if(G.grid[cell.r]&&G.grid[cell.r][cell.c])G.grid[cell.r][cell.c]=null;
      // drop floating
      const floating=findFloating();
      if(floating.length){
        sfx.drop();
        for(const cell of floating){
          const p=gridPos(cell.r,cell.c);
          G.falling=G.falling||[];
          G.falling.push({x:p.x,y:p.y,vy:0,c:G.grid[cell.r][cell.c].c});
          G.grid[cell.r][cell.c]=null;
          G.score+=30;
        }
        spawnText(W/2,H*0.4,`+${floating.length*30} DROP!`);
      }
      updateHUD();
      checkWin();
      if(G.state==='play')checkLose();
    },280);
  }else{
    checkLose();
  }
  // ceiling drop every 6 shots
  G.dropCount++;
  if(G.dropCount>=6){
    G.dropCount=0;
    // add new row at top
    const newRow=[];
    for(let c=0;c<COLS;c++)newRow.push({c:Math.floor(Math.random()*G.colors),pop:0});
    G.grid.unshift(newRow);
    // hex rows alternate length by parity: after the shift, truncate any row
    // that is now too long for its parity or its last bubble hangs off-board
    for(let r=0;r<G.grid.length;r++){const maxC=COLS-(r%2?1:0);if(G.grid[r]&&G.grid[r].length>maxC)G.grid[r].length=maxC;}
    checkLose();
  }
  newShooter();
  updateHUD();
}
