    if(f.x<R){f.x=R;f.vx=Math.abs(f.vx);}
    if(f.x>W-R){f.x=W-R;f.vx=-Math.abs(f.vx);}
    if(f.y<R){snapBubble();return;}
    // bubble collision
    for(let r=0;r<G.grid.length;r++){
      for(let c=0;c<(G.grid[r]?G.grid[r].length:0);c++){
        if(!G.grid[r][c])continue;
        const p=gridPos(r,c);
        if(Math.hypot(f.x-p.x,f.y-p.y)<R*1.85){snapBubble();return;}
      }
    }
    if(f.y>H){G.flying=null;newShooter();}
  }
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  for(const f of floaters){if(!f.a)continue;f.y-=40*dt;f.life-=dt;if(f.life<=0)f.a=false;}
}
