scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson'),
      bigscore=document.getElementById('bigscore');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();
let AC=null;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  flap(){tone(500,800,0.08,'sine',0.12);},
  score(){tone(800,1200,0.1,'triangle',0.14);},
  die(){tone(400,80,0.4,'sawtooth',0.18);},
  swoosh(){tone(300,600,0.15,'sine',0.08);},
  click(){tone(600,600,0.06,'square',0.1);}
};
const G={state:'title',score:0,best:0,py:0,vy:0,rot:0,pipes:[],time:0,
  speed:220,spawnT:0,dead:false,groundY:0,flash:0,ready:true};
try{G.best=parseInt(localStorage.getItem('flap_best')||'0',10)||0;}catch(e){}
G.groundY=()=>H*0.88;
function reset(){
  G.score=0;G.py=H*0.42;G.vy=0;G.rot=0;G.pipes=[];G.time=0;
  G.speed=220;G.spawnT=1.4;G.dead=false;G.flash=0;G.ready=true; // [gauntlet fix] gentle opener: hover until first flap
  bigscore.classList.remove('hidden');bigscore.textContent='0';
  document.getElementById('best').textContent='🏆 '+G.best;
  updateHUD();
}
function updateHUD(){document.getElementById('score').textContent='⭐ '+G.score;}
function flap(){
  if(G.state!=='play'||G.dead||PAUSED)return;
  G.ready=false;
  G.vy=-560;sfx.flap();
  for(let i=0;i<5;i++)spawnP(W*0.32,G.py+16,(Math.random()-0.5)*120,Math.random()*100,0.3,'#fff',3);
}
canvas.addEventListener('pointerdown',e=>{e.preventDefault();flap();});
addEventListener('keydown',e=>{if(e.repeat)return;if(e.key===' '||e.key==='ArrowUp'){flap();e.preventDefault();}}); // repeat guard: holding Space was an auto-flap exploit
const particles=[];
for(let i=0;i<60;i++)particles.push({a:false});
const pops=[]; // [gauntlet fix] floating score popups
const embers=[];
for(let i=0;i<24;i++)embers.push({x:Math.random()*2400,y:Math.random()*1600,s:1+Math.random()*2.5,vy:14+Math.random()*26,vx:(Math.random()-0.5)*8,ph:Math.random()*6});
function updateEmbers(dt){for(const e of embers){e.y-=e.vy*dt;e.x+=e.vx*dt+Math.sin(G.time*2+e.ph)*6*dt;if(e.y<-12){e.y=H+12;e.x=Math.random()*W;}if(e.x<-4)e.x+=W+8;if(e.x>W+4)e.x-=W+8;}}
/* [w5c perf] Pre-baked glow sprites — the W5b-proven pattern copied from game-04:
   the ember loop's 24 per-frame shadowBlur=8 fills collapsed FPS under software
   rendering (10.0 FPS); blit a one-time radial-glow sprite instead. Colours,
   falloff and alpha unchanged; no gameplay/balance changes. */
function makeGlowSprite(hex){const c=document.createElement('canvas');c.width=c.height=96;const x=c.getContext('2d');
  const r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);
  const gr=x.createRadialGradient(48,48,0,48,48,48);
  gr.addColorStop(0,`rgba(${r},${g},${b},0.9)`);gr.addColorStop(0.35,`rgba(${r},${g},${b},0.38)`);gr.addColorStop(1,`rgba(${r},${g},${b},0)`);
  x.fillStyle=gr;x.fillRect(0,0,96,96);return c;}
const EMBER_SPRITE=makeGlowSprite('#ff8a3a');
function drawEmbers(){ctx.save();ctx.globalCompositeOperation='lighter';for(const e of embers){const tw=0.5+0.5*Math.sin(G.time*3+e.ph);ctx.globalAlpha=0.10+0.16*tw;const r=e.s*7;ctx.drawImage(EMBER_SPRITE,e.x-r,e.y-r,r*2,r*2);}ctx.restore();ctx.globalAlpha=1;}

function spawnP(x,y,vx,vy,life,color,size){const p=particles.find(p=>!p.a);if(!p)return;
  p.a=true;p.x=x;p.y=y;p.vx=vx;p.vy=vy;p.life=life;p.max=life;p.color=color;p.size=size;}
function spawnPipe(){
  const gap=Math.max(160,210-G.score*1.6); // softer triple-ramp: gap now bottoms at 160 and shrinks slower
  const margin=80;
  const gy=margin+Math.random()*(H*0.7-margin*2-gap);
  G.pipes.push({x:W+60,gapY:gy,gapH:gap,w:74,scored:false});
}
function update(dt){
  G.time+=dt;
  if(G.ready){G.py=H*0.42+Math.sin(G.time*3)*8;G.vy=0;G.rot=0;return;} // [gauntlet fix] ready beat: no gravity, no pipes until the first flap
  G.speed=Math.min(380,220+G.score*6);
  // physics
  G.vy+=2100*dt;
  G.vy=Math.min(G.vy,900);
  G.py+=G.vy*dt;
  G.rot=Math.max(-0.4,Math.min(1.2,G.vy/700));
  const px=W*0.32,pr=20;
  // spawn
  G.spawnT-=dt;
  if(G.spawnT<=0){spawnPipe();G.spawnT=Math.max(1.05,1.55-G.score*0.015);}
  // pipes
  for(const p of G.pipes){
    p.x-=G.speed*dt;
    // score
    if(!p.scored&&p.x+p.w<px){
      p.scored=true;G.score++;sfx.score();
      bigscore.textContent=G.score;updateHUD();
      pops.push({x:px,y:G.py-36,t0:G.time}); // [gauntlet fix] '+1' popup at the gate
    }
    // collision
    if(px+pr>p.x&&px-pr<p.x+p.w){
      if(G.py-pr<p.gapY||G.py+pr>p.gapY+p.gapH){die();return;}
    }
    if(p.x<-100)p.gone=true;
  }
  G.pipes=G.pipes.filter(p=>!p.gone);
  // ground/ceiling
  if(G.py+pr>=G.groundY()){G.py=G.groundY()-pr;die();return;}
  if(G.py-pr<0){G.py=pr;G.vy=0;}
  // trail
  if(Math.random()<0.5)spawnP(px-14,G.py,(Math.random()-0.5)*40,Math.random()*40,0.35,'#ffd23f',3);
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)p.a=false;}
}
function die(){
  if(G.dead)return;
  G.dead=true;sfx.die();G.flash=0.4;
  for(let i=0;i<18;i++)spawnP(W*0.32,G.py,(Math.random()-0.5)*350,(Math.random()-0.5)*350,0.6,'#ff6a1a',5);
  const isBest=G.score>G.best;
  if(isBest){G.best=G.score;try{localStorage.setItem('flap_best',String(G.best));}catch(e){}}
  const medal=G.score>=40?'🏆':G.score>=25?'🥇':G.score>=15?'🥈':G.score>=8?'🥉':'';
  setTimeout(()=>{
    G.state='over'; // [gauntlet fix] peer games end in 'over' — keeps the music gate frozen behind the crash card
    bigscore.classList.add('hidden');
    showOverlay('💥 CRASHED!',
      `${medal?`<div id="medal">${medal}</div>`:''}${isBest?'<p style="color:#ffd23f;font-weight:900">🏆 NEW BEST!</p>':''}<p style="font-size:28px;font-weight:900">Score: ${G.score}</p><p>Best: ${G.best}</p>`,
      '🔥 Fire Safety: Flying is fun in games — stay grounded during storms!',
      '↻ FLY AGAIN',()=>{reset();G.state='play';});
  },700);
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  setPaused(false);
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();reset();G.state='play';overlay.classList.add('hidden');sfx.swoosh();}
obtn.onclick=()=>{showMathGate();};
function render(){
  // sky
  const sky=ctx.createLinearGradient(0,0,0,H);
  const t=(Math.sin(G.time*0.1)+1)/2;
  sky.addColorStop(0,'#0d1a2a');sky.addColorStop(0.7,'#1a2a4a');sky.addColorStop(1,'#2a1a3a');
  ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
  drawEmbers();
  // parallax mountains
  ctx.fillStyle='#0a1220';
  for(let i=0;i<3;i++){
    const off=(G.time*G.speed*0.2*(i+1)/3)%(W+200);
    for(let x=-200;x<W+200;x+=220){
      const mx=x-off+((i*97)%220);
      ctx.beginPath();ctx.moveTo(mx,G.groundY());ctx.lineTo(mx+110,G.groundY()-120-i*40);ctx.lineTo(mx+220,G.groundY());ctx.closePath();ctx.fill();
    }
  }
  // clouds
  ctx.fillStyle='rgba(255,255,255,0.08)';
  for(let i=0;i<6;i++){
    const cx=((i*311+G.time*G.speed*0.3)%(W+200)+(W+200))%(W+200)-100;
    const cy=(i*173)%(H*0.5);
    ctx.beginPath();ctx.ellipse(cx,cy,60,18,0,0,Math.PI*2);ctx.fill();
  }
  const gy=G.groundY();
  // pipes (crystal gates)
  for(const p of G.pipes){
    // top
    drawCrystal(p.x,0,p.w,p.gapY,true);
    // bottom
    drawCrystal(p.x,p.gapY+p.gapH,p.w,gy-(p.gapY+p.gapH),false);
  }
  // ground
  const gg=ctx.createLinearGradient(0,gy,0,H);
  gg.addColorStop(0,'#2a4a3a');gg.addColorStop(1,'#0d1a12');
  ctx.fillStyle=gg;ctx.fillRect(0,gy,W,H-gy);
  ctx.fillStyle='rgba(255,255,255,0.1)';
  for(let x=0;x<W;x+=40){
    const gx=((x-G.time*G.speed)%(W+40)+(W+40))%(W+40)-20;
    ctx.fillRect(gx,gy+8,20,4);
  }
  // player
  if(!G.dead||G.state!=='over'){
    const px=W*0.32;
    ctx.save();ctx.translate(px,G.py);ctx.rotate(G.rot);
    // glow
    const gl=ctx.createRadialGradient(0,0,5,0,0,36);
    gl.addColorStop(0,'rgba(255,150,50,0.35)');gl.addColorStop(1,'rgba(255,150,50,0)');
    ctx.fillStyle=gl;ctx.beginPath();ctx.arc(0,0,36,0,Math.PI*2);ctx.fill();
    const g=ctx.createRadialGradient(-6,-7,3,0,0,20);
    g.addColorStop(0,'#ffe9a0');g.addColorStop(0.5,'#ff9a3a');g.addColorStop(1,'#e8352c');
    ctx.shadowColor='#ff9a3a';ctx.shadowBlur=16;
    ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,20,0,Math.PI*2);ctx.fill();
    ctx.shadowBlur=0;
    // flame tuft (brand rule: zero wings/feathers — a flickering flame plume instead of the old wing)
    const wa=Math.sin(G.time*22)*0.5;
    ctx.fillStyle='#ff6a1a';
    ctx.save();ctx.translate(-15,0);ctx.rotate(0.25+wa*0.15);
    ctx.beginPath();ctx.moveTo(2,-6);ctx.quadraticCurveTo(-13,0,2,7);ctx.quadraticCurveTo(-4,0,2,-6);ctx.fill();
    ctx.restore();
    // face
    ctx.fillStyle='#2b1a0e';
    ctx.beginPath();ctx.arc(5,-4,3.5,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#2b1a0e';ctx.lineWidth=2.5;ctx.lineCap='round';
    ctx.beginPath();ctx.arc(8,4,6,0.4,Math.PI-0.8);ctx.stroke();
    ctx.restore();
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  // [gauntlet fix] score popups: rise + fade over 0.9s
  ctx.textAlign='center';ctx.font='900 24px system-ui';
  for(const pp of pops){const age=G.time-pp.t0,a=1-age/0.9;if(a<=0)continue;
    ctx.globalAlpha=a;ctx.fillStyle='#ffd23f';ctx.fillText('+1',pp.x,pp.y-age*46);}
  ctx.globalAlpha=1;ctx.textAlign='left';
  for(let i=pops.length-1;i>=0;i--)if(G.time-pops[i].t0>0.9)pops.splice(i,1);
  // flash
  if(G.flash>0){
    ctx.fillStyle=`rgba(255,255,255,${G.flash})`;ctx.fillRect(0,0,W,H);
  }
  // get ready
  if(G.state==='play'&&(G.ready||G.score===0)){
    ctx.textAlign='center';ctx.font='900 '+(W<520?19:28)+'px system-ui'; // [gauntlet fix] sized to fit phone widths
    ctx.fillStyle='#fff';ctx.fillText('TAP TO FLAP — THREAD THE GATES!',W/2,H*0.52);
    ctx.textAlign='left';
  }
}
function drawCrystal(x,y,w,h,isTop){
  if(h<=0)return;
  const g=ctx.createLinearGradient(x,0,x+w,0);
  g.addColorStop(0,'#2a5a8a');g.addColorStop(0.5,'#5ab8e8');g.addColorStop(1,'#2a5a8a');
  ctx.fillStyle=g;
  ctx.fillRect(x+3,y,w-6,h);
  // crystal facets
  ctx.strokeStyle='rgba(255,255,255,0.25)';ctx.lineWidth=2;
  for(let i=0;i<3;i++){
    const fy=y+h*(i+0.5)/3;
    ctx.beginPath();ctx.moveTo(x+6,fy);ctx.lineTo(x+w-6,fy);ctx.stroke();
  }
  // cap
  ctx.fillStyle='#7fd4ff';
  if(isTop)ctx.fillRect(x,y+h-14,w,14);
  else ctx.fillRect(x,y,w,14);
  ctx.strokeStyle='#fff';ctx.lineWidth=2;
  if(isTop){ctx.strokeRect(x+1,y+h-14,w-2,14);}
  else{ctx.strokeRect(x+1,y,w-2,14);}
}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;if(PAUSED){requestAnimationFrame(loop);return;}
  if(G.state==='play'&&!G.dead)update(dt);else G.time+=dt;
  if(G.flash>0)G.flash=Math.max(0,G.flash-dt*3); // frame-rate independent (was a per-frame constant in render)
  updateEmbers(dt);
  render();
  requestAnimationFrame(loop);
}
document.getElementById('best').textContent='🏆 '+G.best;
requestAnimationFrame(loop);

let MUTED=false;try{MUTED=localStorage.getItem('fb_muted')==='1';}catch(e){}
let PAUSED=false,pauseT0=0;
const pauseBanner=document.getElementById('pauseBanner'),btnMuteEl=document.getElementById('btnMute');
function syncMuteBtn(){btnMuteEl.textContent=MUTED?'🔇':'🔊';}
syncMuteBtn();
btnMuteEl.addEventListener('click',e=>{e.stopPropagation();MUTED=!MUTED;try{localStorage.setItem('fb_muted',MUTED?'1':'0');}catch(err){}syncMuteBtn();if(!MUTED)sfx.click();});
function setPaused(p){if(p===PAUSED)return;PAUSED=p;pauseBanner.classList.toggle('hidden',!p);document.getElementById('btnPause').textContent=p?'▶':'⏸';}
document.getElementById('btnPause').addEventListener('click',e=>{e.stopPropagation();if(G.state==='play'&&overlay.classList.contains('hidden'))setPaused(!PAUSED);});
document.getElementById('btnRestart').addEventListener('click',e=>{e.stopPropagation();restartGame();});
function restartGame(){setPaused(false);if(G.state==='title')return;reset();G.state='play';overlay.classList.add('hidden');}
/* ===== MUSIC (Jeff 2026-10-15): 'Stonewall Stomp' — Boulder's Fortress's own
   track. Synthesized Web Audio only. 96 BPM, G minor: a heavy square lead
   and low pad roots (Gm-Eb-Bb-F) under stomping syncopated drums — the
   fortress does not move.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-20-boulders-fortress.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
const MUS={on:false,step:0,nextT:0,BPM:96,
 BASS:[43,0,0,43,0,0,43,0, 51,0,0,51,0,0,48,0, 46,0,0,46,0,0,46,0, 41,0,0,41,0,43,46,0],
 LEAD:[67,0,0,70,0,0,74,0, 75,0,0,74,0,70,0,0, 70,0,0,74,0,77,0,0, 74,0,70,0,67,0,0,0],
 PAD:[43,51,46,41],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(MUTED||PAUSED||G.state!=='play'){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  if(s%8===0){const p=this.PAD[s>>3];if(p){tone(_mf(p),_mf(p),1.6,'sawtooth',0.02,d);tone(_mf(p)*1.006,_mf(p)*1.006,1.6,'sawtooth',0.02,d);tone(_mf(p+7),_mf(p+7),1.6,'triangle',0.024,d);}} // pad chord
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.2,'square',0.065,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.22,'square',0.05,d);
  if(s%8===0||s%8===3||s%8===6)tone(105,40,0.14,'sine',0.16,d); // stomp kick
  if(s%8===4)tone(185,115,0.08,'triangle',0.08,d); // tone-only snare
  if(s%8===7)tone(80,55,0.12,'triangle',0.08,d); // low tom
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

