scripts:
'use strict';
const canvas=document.getElementById('c');let ctx=canvas.getContext('2d');const mainCtx=ctx;
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR,PZ,BX,BY,GRID;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);layout();
  if(typeof G!=='undefined'&&G.pieces&&G.pieces.length)reScatter();}
/* [w5b] Non-overlapping scatter slots: a jittered grid over the whole visible
   play area (margin 8, below the HUD). Slots outside the board come first so
   pieces ring the board when there is room; every slot is fully on-screen and
   no two slots overlap, on any viewport / puzzle size. */
function scatterSlots(n){
  const margin=8,top=64,step=PZ+10;
  const cols=Math.max(1,Math.floor((W-margin*2-PZ)/step)+1);
  const rows=Math.max(1,Math.floor((H-top-margin-PZ)/step)+1);
  const bw=PZ*GRID,bx0=BX-4,by0=BY-4;
  const outside=[],inside=[];
  for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){
    const cx=margin+PZ/2+c*step,cy=top+PZ/2+r*step;
    const over=(cx+PZ/2>bx0&&cx-PZ/2<bx0+bw+8&&cy+PZ/2>by0&&cy-PZ/2<by0+bw+8);
    // cells under the top-right control cluster or the bottom-right rating
    // pill are last-resort too, so pieces stay grabbable, not just on-screen
    const ui=(cx+PZ/2>W-190&&cy-PZ/2<120)||(cx+PZ/2>W-200&&cy+PZ/2>H-64)||(cx-PZ/2<132&&cy+PZ/2>H-58);
    (over||ui?inside:outside).push({x:cx,y:cy});
  }
  const shuf=a=>{for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
  const cells=shuf(outside).concat(shuf(inside));
  const jmax=Math.max(0,(step-PZ)/2-2);
  return cells.slice(0,n).map(s=>({
    x:Math.max(PZ/2+margin,Math.min(W-PZ/2-margin,s.x+(Math.random()*2-1)*jmax)),
    y:Math.max(top+PZ/2,Math.min(H-PZ/2-margin,s.y+(Math.random()*2-1)*jmax))}));
}
function reScatter(){
  const free=G.pieces.filter(p=>!p.placed);
  const slots=scatterSlots(free.length);
  free.forEach((p,i)=>{if(G.drag===p)return;const s=slots[i];if(s){p.x=s.x;p.y=s.y;}});
}
function layout(){
  const n=[3,4,5,5,6,6,7,7][G.level-1]||3;
  GRID=n;
  PZ=Math.min(W*0.86/n,H*0.5/n,110);
  BX=(W-PZ*n)/2;BY=(H-PZ*n)/2+20;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);
}
addEventListener('resize',resize);
let AC=null;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  grab(){tone(400,600,0.06,'sine',0.08);},
  snap(){tone(700,1100,0.12,'triangle',0.14);tone(1100,1500,0.08,'sine',0.1,0.05);},
  win(){[523,659,784,1047,1319].forEach((f,i)=>tone(f,f,0.2,'triangle',0.15,i*0.09));},
  click(){tone(600,600,0.06,'square',0.1);}
};
// puzzle images: drawn volcano scenes
function drawPuzzleArt(px,py,pz,level){
  // each piece shows part of a volcano scene
  const g=ctx.createLinearGradient(px,py,px,py+pz);
  if(level===1){
    g.addColorStop(0,'#1a2a4a');g.addColorStop(0.5,'#ff6a1a');g.addColorStop(1,'#3a1a0a');
  }else if(level===2){
    g.addColorStop(0,'#0d1a2a');g.addColorStop(0.4,'#5a2a8a');g.addColorStop(0.7,'#ff4a00');g.addColorStop(1,'#1a0d08');
  }else if(level===4){
    g.addColorStop(0,'#0d2a2a');g.addColorStop(0.35,'#2a8a6a');g.addColorStop(0.65,'#ff8a00');g.addColorStop(1,'#1a0d08');
  }else if(level===5){
    g.addColorStop(0,'#2a0d1a');g.addColorStop(0.35,'#8a2a5a');g.addColorStop(0.65,'#ff6a1a');g.addColorStop(1,'#0d0805');
  }else if(level===6){
    g.addColorStop(0,'#1a1a0d');g.addColorStop(0.35,'#6a8a2a');g.addColorStop(0.65,'#ffd23f');g.addColorStop(1,'#141005');
  }else if(level===7){
    g.addColorStop(0,'#0d1a3a');g.addColorStop(0.35,'#2a5a8a');g.addColorStop(0.65,'#ff4a00');g.addColorStop(1,'#080d1a');
  }else if(level===8){
    g.addColorStop(0,'#3a0d0d');g.addColorStop(0.3,'#8a1a1a');g.addColorStop(0.6,'#ff8a00');g.addColorStop(1,'#1a0505');
  }else{
    g.addColorStop(0,'#2a1a3a');g.addColorStop(0.35,'#ff8a00');g.addColorStop(0.6,'#ffd23f');g.addColorStop(1,'#0d0805');
  }
  ctx.fillStyle=g;ctx.fillRect(px,py,pz,pz);
  // volcano silhouette (relative to full image)
  const fx=(px-BX)/(PZ*GRID),fy=(py-BY)/(PZ*GRID);
  ctx.fillStyle='#1a0d08';
  ctx.beginPath();
  ctx.moveTo(BX+PZ*GRID*0.2,BY+PZ*GRID*0.85);
  ctx.lineTo(BX+PZ*GRID*0.5,BY+PZ*GRID*0.25);
  ctx.lineTo(BX+PZ*GRID*0.8,BY+PZ*GRID*0.85);
  ctx.closePath();
  ctx.save();ctx.beginPath();ctx.rect(px,py,pz,pz);ctx.clip();ctx.fill();ctx.restore();
  // lava
  ctx.fillStyle='#ff4a00';
  ctx.save();ctx.beginPath();ctx.rect(px,py,pz,pz);ctx.clip();
  ctx.beginPath();ctx.ellipse(BX+PZ*GRID*0.5,BY+PZ*GRID*0.27,PZ*GRID*0.06,PZ*GRID*0.02,0,0,Math.PI*2);ctx.fill();
  ctx.restore();
  // fire baby
  const bx=BX+PZ*GRID*0.5,by=BY+PZ*GRID*0.6;
  ctx.save();ctx.beginPath();ctx.rect(px,py,pz,pz);ctx.clip();
  const bg=ctx.createRadialGradient(bx-5,by-6,3,bx,by,20);
  bg.addColorStop(0,'#ffe9a0');bg.addColorStop(0.5,'#ff7a2a');bg.addColorStop(1,'#d42a1a');
  ctx.fillStyle=bg;ctx.beginPath();ctx.arc(bx,by,16,0,Math.PI*2);ctx.fill();
  ctx.restore();
}
const G={state:'title',level:1,pieces:[],score:0,levelScore:0,startT:0,time:0,drag:null,lastSec:-1};
function initLevel(n){
  G.level=n;layout();
  G.pieces=[];G.drag=null;G.levelScore=0;G.startT=performance.now();
  const idx=[];
  for(let r=0;r<GRID;r++)for(let c=0;c<GRID;c++)idx.push({r,c});
  // shuffle positions
  for(let i=idx.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[idx[i],idx[j]]=[idx[j],idx[i]];}
  const slots=scatterSlots(idx.length);
  idx.forEach((pos,i)=>{
    // [w5b] scattered onto non-overlapping, fully on-screen slots (was: random
    // edge bands that stacked pieces on top of each other and half off-screen)
    const sx=slots[i]?slots[i].x:W/2,sy=slots[i]?slots[i].y:H/2;
    // home IS the target: a piece's picture fragment belongs in its home slot.
    // (Targets used to be re-shuffled after creation, so the finished picture
    // could never assemble and no slot visually matched its piece.)
    G.pieces.push({hr:Math.floor(i/GRID),hc:i%GRID,
      tr:Math.floor(i/GRID),tc:i%GRID,
      x:sx,y:sy,placed:false,snap:0});
  });
  document.getElementById('level').textContent=`PUZZLE ${n}/8`;
  updateHUD();
}
function updateHUD(){document.getElementById('score').textContent='⭐ '+G.score;}
function pieceAt(x,y){
  for(let i=G.pieces.length-1;i>=0;i--){
    const p=G.pieces[i];
    if(p.placed)continue;
    if(x>p.x-PZ/2&&x<p.x+PZ/2&&y>p.y-PZ/2&&y<p.y+PZ/2)return p;
  }
  return null;
}
canvas.addEventListener('pointerdown',e=>{
  if(G.state!=='play'||PAUSED)return;
  const rect=canvas.getBoundingClientRect();
  const p=pieceAt(e.clientX-rect.left,e.clientY-rect.top);
  if(p){
    G.drag=p;
    p.ox=e.clientX-rect.left-p.x;p.oy=e.clientY-rect.top-p.y;
    sfx.grab();
    // bring to front
    G.pieces.splice(G.pieces.indexOf(p),1);G.pieces.push(p);
    canvas.setPointerCapture(e.pointerId);
  }
});
canvas.addEventListener('pointermove',e=>{
  if(!G.drag)return;
  const rect=canvas.getBoundingClientRect();
  G.drag.x=e.clientX-rect.left-G.drag.ox;
  G.drag.y=e.clientY-rect.top-G.drag.oy;
});
canvas.addEventListener('pointerup',e=>{
  const p=G.drag;if(!p)return;
  G.drag=null;
  const tx=BX+p.tc*PZ+PZ/2,ty=BY+p.tr*PZ+PZ/2;
  if(Math.hypot(p.x-tx,p.y-ty)<PZ*0.75){
    p.x=tx;p.y=ty;p.placed=true;p.snap=0.4;
    sfx.snap();
    G.score+=100;G.levelScore+=100;updateHUD();
    if(G.pieces.every(q=>q.placed))levelComplete();
  }
});
function levelComplete(){
  G.state='clear'; // freeze play/timer while the completion overlay is pending
  const elapsed=(performance.now()-G.startT)/1000;
  const bonus=Math.max(0,Math.round((180-elapsed)*5));
  G.score+=bonus;updateHUD();sfx.win();
  setTimeout(()=>{
    if(G.level>=8){
      showOverlay('🏆 PUZZLE MASTER!',
        `<p style="font-size:24px;font-weight:900">Final Score: ${G.score}</p><p>All 8 puzzles solved!</p>`,
        '🔥 Fire Safety: You\'re a champion!',
        '↻ PLAY AGAIN',()=>{G.score=0;initLevel(1);G.state='play';});
    }else{
      showOverlay(`⭐ PUZZLE ${G.level} SOLVED!`,
        `<p>Time: ${elapsed.toFixed(1)}s (+${bonus} speed bonus)</p><p>Score: ${G.score}</p>`,
        '🔥 Fire Safety: Piece together your escape plan!',
        '▶ NEXT PUZZLE',()=>{initLevel(G.level+1);G.state='play';});
    }
  },700);
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');showLevels();
  }else document.getElementById('ma').value='';
}
function showLevels(){
  otitle.innerHTML='🧩 PICK PUZZLE';
  let h='';
  const names=['3×3 Easy','4×4 Medium','5×5 Hard','5×5 Expert','6×6 Master','6×6 Grandmaster','7×7 Legend','7×7 Ultimate'];
  for(let i=1;i<=8;i++)h+=`<button class="lvlBtn" onclick="event.stopPropagation();pickLevel(${i})">${names[i-1]}</button>`;
  obody.innerHTML=`<p>Drag pieces into their glowing slots!</p><div id="lvlSel">${h}</div>`;
  obtn.style.display='none';
  overlay.classList.remove('hidden');
}
function pickLevel(n){sfx.click();audio();G.score=0;initLevel(n);G.state='play';overlay.classList.add('hidden');}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;
  obtn.textContent=btn;obtn.style.display='';
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
obtn.onclick=()=>{showMathGate();};
function render(){
  const bg21=ctx.createLinearGradient(0,0,0,H);
  bg21.addColorStop(0,'#160d08');bg21.addColorStop(1,'#2e1608');
  ctx.fillStyle=bg21;ctx.fillRect(0,0,W,H);
  drawEmbers();
  if(!G.pieces.length)return;
  buildScene();
  ctx.globalAlpha=0.16;ctx.drawImage(sceneCanvas,BX,BY);ctx.globalAlpha=1;
  // target slots (glowing)
  for(let r=0;r<GRID;r++)for(let c=0;c<GRID;c++){
    const x=BX+c*PZ,y=BY+r*PZ;
    const filled=G.pieces.some(p=>p.placed&&p.tr===r&&p.tc===c);
    if(!filled){
      ctx.strokeStyle=`rgba(255,210,63,${0.3+Math.sin(G.time*3+r+c)*0.15})`;
      ctx.lineWidth=3;ctx.setLineDash([10,8]);
      ctx.strokeRect(x+4,y+4,PZ-8,PZ-8);
      ctx.setLineDash([]);
    }
  }
  // placed pieces (in grid)
  for(const p of G.pieces){
    if(!p.placed)continue;
    const x=BX+p.tc*PZ,y=BY+p.tr*PZ;
    ctx.save();ctx.beginPath();ctx.rect(x,y,PZ,PZ);ctx.clip();
    // draw the piece's home image portion
    drawPieceArt(p.hr,p.hc,x,y);
    ctx.restore();
    ctx.strokeStyle='rgba(255,255,255,0.4)';ctx.lineWidth=2;
    ctx.strokeRect(x+1,y+1,PZ-2,PZ-2);
    if(p.snap>0){
      ctx.strokeStyle=`rgba(255,210,63,${p.snap})`;ctx.lineWidth=4;
      ctx.strokeRect(x,y,PZ,PZ);p.snap-=0.03;
    }
  }
  // unplaced pieces (draggable)
  for(const p of G.pieces){
    if(p.placed)continue;
    const isDrag=p===G.drag;
    ctx.save();
    if(isDrag){ctx.shadowColor='rgba(255,210,63,0.8)';ctx.shadowBlur=20;}
    ctx.beginPath();ctx.rect(p.x-PZ/2,p.y-PZ/2,PZ,PZ);ctx.clip();
    drawPieceArt(p.hr,p.hc,p.x-PZ/2,p.y-PZ/2);
    ctx.restore();
    ctx.strokeStyle=isDrag?'#ffd23f':'rgba(255,255,255,0.5)';ctx.lineWidth=isDrag?4:2;
    ctx.strokeRect(p.x-PZ/2,p.y-PZ/2,PZ,PZ);
  }
  // timer
  drawPaused21();
  if(G.state==='play'){
    const el=Math.floor(((PAUSED&&pauseT0?pauseT0:performance.now())-G.startT)/1000);
    if(el!==G.lastSec){G.lastSec=el;document.getElementById('timer').textContent='⏱️ '+el+'s';} // was a DOM write every frame
  }
}
let sceneCanvas=null,sceneKey='';
function buildScene(){
  const key=G.level+'|'+Math.round(PZ*GRID)+'|'+GRID;
  if(sceneCanvas&&sceneKey===key)return;
  const size=Math.max(2,Math.ceil(PZ*GRID));
  const sc=document.createElement('canvas');sc.width=size;sc.height=size;
  const sBX=BX,sBY=BY;BX=0;BY=0;ctx=sc.getContext('2d');
  drawPuzzleArt(0,0,PZ*GRID,G.level);
  ctx=mainCtx;BX=sBX;BY=sBY;
  sceneCanvas=sc;sceneKey=key;
}
function drawPaused21(){
  if(!PAUSED)return;
  ctx.fillStyle='rgba(0,0,0,0.45)';ctx.fillRect(0,0,W,H);
  ctx.fillStyle='#fff';ctx.font='900 34px system-ui';ctx.textAlign='center';
  ctx.fillText('⏸ PAUSED',W/2,H/2);ctx.textAlign='left';
}
function drawPieceArt(hr,hc,px,py){
  // blit the prerendered scene (was: full scene redraw per piece per frame)
  buildScene();
  ctx.drawImage(sceneCanvas,hc*PZ,hr*PZ,PZ,PZ,px,py,PZ,PZ);
}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;G.time+=dt;updateEmbers(dt);
  render();
  requestAnimationFrame(loop);
}

const embers=[];
for(let i=0;i<24;i++)embers.push({x:Math.random()*2400,y:Math.random()*1600,s:1+Math.random()*2.5,vy:14+Math.random()*26,vx:(Math.random()-0.5)*8,ph:Math.random()*6});
function updateEmbers(dt){for(const e of embers){e.y-=e.vy*dt;e.x+=e.vx*dt+Math.sin(G.time*2+e.ph)*6*dt;if(e.y<-12){e.y=H+12;e.x=Math.random()*W;}if(e.x<-4)e.x+=W+8;if(e.x>W+4)e.x-=W+8;}}
function drawEmbers(){ctx.save();ctx.globalCompositeOperation='lighter';for(const e of embers){const tw=0.5+0.5*Math.sin(G.time*3+e.ph);ctx.globalAlpha=0.10+0.16*tw;ctx.fillStyle='#ff8a3a';ctx.beginPath();ctx.arc(e.x,e.y,e.s,0,Math.PI*2);ctx.fill();}ctx.restore();ctx.globalAlpha=1;}

let MUTED=false,PAUSED=false,pauseT0=0;
const _tone21=tone;
tone=function(f0,f1,dur,type,vol,delay=0){if(MUTED)return;_tone21(f0,f1,dur,type,vol,delay);};
document.getElementById('muteBtn').onclick=()=>{MUTED=!MUTED;document.getElementById('muteBtn').textContent=MUTED?'🔇':'🔊';if(!MUTED)sfx.click();};
function setPaused(p){
  if(p&&G.state!=='play')return;
  PAUSED=p;
  if(p)pauseT0=performance.now();
  else if(pauseT0){G.startT+=performance.now()-pauseT0;pauseT0=0;}
  document.getElementById('pauseBtn').textContent=PAUSED?'▶':'⏸';
}
document.getElementById('pauseBtn').onclick=()=>{if(G.state==='play')setPaused(!PAUSED);};
document.getElementById('restartBtn').onclick=()=>{
  if(G.state!=='play')return;
  if(PAUSED)setPaused(false);
  G.score-=G.levelScore;initLevel(G.level);updateHUD();sfx.click();
};
addEventListener('keydown',e=>{if((e.key==='p'||e.key==='P'||e.key==='Escape')&&G.state==='play')setPaused(!PAUSED);});
resize();
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Snap Happy' — Sizzle's Puzzle Snap's own
   track. Synthesized Web Audio only. 108 BPM, F major pentatonic: a plucky
   square lead with lots of air around it — room to think, snap, and smile.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-21-sizzles-target-pop.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
const MUS={on:false,step:0,nextT:0,BPM:108,
 BASS:[41,0,0,0,48,0,0,0, 46,0,0,0,53,0,0,0, 38,0,0,0,45,0,0,0, 36,0,0,0,48,0,50,0],
 LEAD:[77,0,0,81,0,0,77,0, 0,74,0,0,77,0,0,0, 74,0,0,77,0,81,0,0, 0,79,0,77,0,0,0,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(MUTED||PAUSED||G.state!=='play'){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.24,'triangle',0.05,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.13,'square',0.05,d);
  if(s%8===0)tone(112,45,0.12,'sine',0.1,d); // sparse kick
  if(s===12||s===28)tone(190,120,0.07,'triangle',0.05,d); // occasional tone-only snare
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

