scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();
let AC=null;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
function noise(dur,vol,delay=0,lp=1000){const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const len=ac.sampleRate*dur,buf=ac.createBuffer(1,len,ac.sampleRate),d=buf.getChannelData(0);
  for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);
  const s=ac.createBufferSource();s.buffer=buf;const f=ac.createBiquadFilter();f.type='lowpass';f.frequency.value=lp;
  const g=ac.createGain();g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  s.connect(f);f.connect(g);g.connect(ac.destination);s.start(t);}
const sfx={
  shoot(){tone(700,400,0.06,'square',0.05);},
  kill(){noise(0.1,0.18,0,900);},
  hurt(){tone(250,100,0.2,'sawtooth',0.16);},
  xp(){tone(900,1300,0.07,'sine',0.08);},
  level(){tone(600,1200,0.25,'triangle',0.16);tone(900,1600,0.2,'sine',0.12,0.1);},
  nova(){tone(180,720,0.22,'triangle',0.14);noise(0.18,0.15,0,800);},
  dash(){tone(280,880,0.14,'sine',0.05);noise(0.14,0.09,0,2200);},
  click(){tone(600,600,0.06,'square',0.1);}
};
const G={state:'title',score:0,kills:0,time:0,
  px:0,py:0,hp:100,maxHp:100,level:1,xp:0,xpNeed:8,
  dmg:12,fireRate:0.45,projSpeed:520,projCount:1,moveSpeed:300,magnet:90,
  enemies:[],shots:[],gems:[],fireT:0,spawnT:1,invuln:0,shake:0,leveling:false,novaT:0,novaLvl:0};
function reset(){
  Object.assign(G,{score:0,kills:0,time:0,hp:100,maxHp:100,level:1,xp:0,xpNeed:8,
    dmg:12,fireRate:0.45,projSpeed:520,projCount:1,moveSpeed:300,magnet:90,
    fireT:0,spawnT:1,invuln:0,shake:0,leveling:false,novaT:0,novaLvl:0});
  G.px=W/2;G.py=H/2;G.enemies=[];G.shots=[];G.gems=[];
  updateHUD();
}
function updateHUD(){
  document.getElementById('score').textContent='⭐ '+G.score;
  const m=Math.floor(G.time/60),s=Math.floor(G.time%60);
  document.getElementById('timer').textContent=`⏱️ ${m}:${s.toString().padStart(2,'0')}`;
  document.getElementById('kills').textContent='💀 '+G.kills;
  document.getElementById('hpfill').style.width=(G.hp/G.maxHp*100)+'%';
  document.getElementById('xpfill').style.width=(G.xp/G.xpNeed*100)+'%';
}
// movement
let dragging=false,pointerTarget=null;
canvas.addEventListener('pointerdown',e=>{dragging=true;pointerTarget={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);});
canvas.addEventListener('pointermove',e=>{
  if(!dragging||G.state!=='play'||G.leveling)return;
  pointerTarget={x:e.clientX,y:e.clientY};
});
canvas.addEventListener('pointerup',()=>{dragging=false;pointerTarget=null;});
const keys={};
addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;});
addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;});
function spawnEnemy(){
  const t=G.time;
  const r=Math.random();
  let type='chaser';
  if(t>90&&r<0.15)type='tank';
  else if(t>45&&r<0.35)type='dasher';
  // spawn at edge
  const side=Math.floor(Math.random()*4);
  let x,y;
  if(side===0){x=-30;y=Math.random()*H;}else if(side===1){x=W+30;y=Math.random()*H;}
