  const c=document.createElement('canvas');c.width=(r+2)*2;c.height=(r+2)*2;
  const x2=c.getContext('2d');x2.translate(r+2,r+2);
  const g=x2.createRadialGradient(-6,-6,3,0,0,r);
  if(type==='tank'){g.addColorStop(0,flash?'#fff':'#6a5a4a');g.addColorStop(1,'#2a1a0a');}
  else if(type==='dasher'){g.addColorStop(0,flash?'#fff':'#a08a6a');g.addColorStop(1,'#4a2a1a');}
  else{g.addColorStop(0,flash?'#fff':'#8a7a6a');g.addColorStop(1,'#3a2a1a');}
