  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  if(s===0||s===16)noise(1.5,0.04,d,850); // long wind swell
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.4,'sawtooth',0.05,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.34,'sawtooth',0.045,d);
  if(s%8===0)tone(95,40,0.15,'sine',0.13,d); // half-time kick
  if(s%8===4)noise(0.09,0.07,d,1600); // half-time snare
  if(s===24)noise(0.02,0.012,d,6800); // lone gust tick
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

