scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();
let AC=null;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  draw(){tone(600,700,0.03,'sine',0.04);},
  go(){tone(400,800,0.2,'triangle',0.14);},
  win(){[523,659,784,1047].forEach((f,i)=>tone(f,f,0.25,'triangle',0.18,i*0.1));},
  bump(){tone(300,200,0.06,'square',0.08);},
  click(){tone(600,600,0.06,'square',0.1);}
};
// levels: start, goal, obstacles
const LEVELS=[
  {sx:0.15,sy:0.3,gx:0.85,gy:0.7,ink:400,obs:[]},
  {sx:0.12,sy:0.75,gx:0.88,gy:0.25,ink:450,obs:[{x:0.4,y:0.4,w:0.2,h:0.06}]},
  {sx:0.5,sy:0.15,gx:0.5,gy:0.85,ink:500,obs:[{x:0.3,y:0.45,w:0.4,h:0.06}]},
  {sx:0.1,sy:0.5,gx:0.9,gy:0.5,ink:420,obs:[{x:0.42,y:0.2,w:0.06,h:0.6}]},
  {sx:0.15,sy:0.2,gx:0.85,gy:0.8,ink:550,obs:[{x:0.35,y:0.3,w:0.3,h:0.06},{x:0.35,y:0.6,w:0.3,h:0.06}]},
  {sx:0.85,sy:0.15,gx:0.15,gy:0.85,ink:600,obs:[{x:0.4,y:0.4,w:0.2,h:0.2}]},
  {sx:0.1,sy:0.85,gx:0.9,gy:0.15,ink:600,obs:[{x:0.25,y:0.3,w:0.5,h:0.05},{x:0.25,y:0.6,w:0.5,h:0.05}]},
  {sx:0.5,sy:0.1,gx:0.5,gy:0.9,ink:650,obs:[{x:0.2,y:0.35,w:0.25,h:0.05},{x:0.55,y:0.35,w:0.25,h:0.05},{x:0.2,y:0.65,w:0.25,h:0.05},{x:0.55,y:0.65,w:0.25,h:0.05}]},
  {sx:0.15,sy:0.25,gx:0.85,gy:0.75,ink:600,obs:[{x:0.35,y:0.32,w:0.3,h:0.06},{x:0.35,y:0.62,w:0.3,h:0.06}]},
  {sx:0.85,sy:0.2,gx:0.15,gy:0.8,ink:625,obs:[{x:0.42,y:0.25,w:0.06,h:0.25},{x:0.42,y:0.6,w:0.06,h:0.25},{x:0.65,y:0.42,w:0.2,h:0.06}]},
  {sx:0.5,sy:0.12,gx:0.5,gy:0.88,ink:650,obs:[{x:0.2,y:0.35,w:0.25,h:0.05},{x:0.55,y:0.35,w:0.25,h:0.05},{x:0.35,y:0.6,w:0.3,h:0.05}]},
  {sx:0.1,sy:0.85,gx:0.9,gy:0.15,ink:675,obs:[{x:0.25,y:0.3,w:0.22,h:0.05},{x:0.53,y:0.3,w:0.22,h:0.05},{x:0.25,y:0.6,w:0.22,h:0.05},{x:0.53,y:0.6,w:0.22,h:0.05}]},
  {sx:0.15,sy:0.15,gx:0.85,gy:0.85,ink:700,obs:[{x:0.3,y:0.28,w:0.18,h:0.05},{x:0.55,y:0.42,w:0.18,h:0.05},{x:0.3,y:0.56,w:0.18,h:0.05},{x:0.55,y:0.7,w:0.18,h:0.05},{x:0.65,y:0.2,w:0.05,h:0.18}]},
];
const G={state:'title',level:1,lines:[],drawing:null,ink:400,maxInk:400,
  ball:null,rolling:false,score:0,time:0,hintT:0,goBtn:{x:0,y:0,w:90,h:44}};
function initLevel(n){
  const L=LEVELS[n-1];
  G.level=n;G.lines=[];segCache=null;G.drawing=null;G.ink=L.ink;G.maxInk=L.ink;
  G.ball={x:L.sx*W,y:L.sy*H,vx:0,vy:0,r:16};
  G.rolling=false;G.rollT=0;G.stillT=0;G.score=G.score||0;
  G.goBtn={x:W-110,y:H-118,w:90,h:44};
  document.getElementById('level').textContent=`LV ${n}/13`;
  updateInk();updateHUD();
}
function updateHUD(){document.getElementById('score').textContent='⭐ '+G.score;}
function updateInk(){document.getElementById('inkfill').style.width=(G.ink/G.maxInk*100)+'%';}
// drawing
canvas.addEventListener('pointerdown',e=>{
  if(G.state!=='play')return;
  const rect=canvas.getBoundingClientRect();
  const x=e.clientX-rect.left,y=e.clientY-rect.top;
  // GO button
  const gb=G.goBtn;
  if(!G.rolling&&x>gb.x&&x<gb.x+gb.w&&y>gb.y&&y<gb.y+gb.h){
    if(!G.lines.length){G.hintT=1.4;sfx.bump();return;}
    G.rolling=true;sfx.go();return;
  }
  if(G.rolling)return;
  G.drawing={pts:[{x,y}]};
  canvas.setPointerCapture(e.pointerId);
});
canvas.addEventListener('pointermove',e=>{
  if(!G.drawing)return;
  const rect=canvas.getBoundingClientRect();
  const x=e.clientX-rect.left,y=e.clientY-rect.top;
  const last=G.drawing.pts[G.drawing.pts.length-1];
  const d=Math.hypot(x-last.x,y-last.y);
  if(d>6){
    if(G.ink<d){finishLine();return;}
    G.ink-=d;updateInk();
    G.drawing.pts.push({x,y});
    if(Math.random()<0.3)sfx.draw();
  }
});
canvas.addEventListener('pointerup',()=>finishLine());
function finishLine(){
  if(G.drawing&&G.drawing.pts.length>3){G.lines.push(G.drawing);segCache=null;}
  G.drawing=null;
}
document.getElementById('ballBtn').addEventListener('click',()=>{
  if(G.state==='play'){
    const L=LEVELS[G.level-1];
    G.ball={x:L.sx*W,y:L.sy*H,vx:0,vy:0,r:16};
    G.rolling=false;G.rollT=0;G.stillT=0;sfx.click();
  }
});
document.getElementById('clearBtn').addEventListener('click',()=>{
  if(G.state==='play'&&!G.rolling){
    G.lines=[];segCache=null;const L=LEVELS[G.level-1];G.ink=L.ink;updateInk();sfx.click();
  }
});
// physics
let segCache=null;
function lineSegs(){
  if(segCache)return segCache;
  const segs=[];
  for(const line of G.lines){
    for(let i=0;i<line.pts.length-1;i++)
      segs.push({x1:line.pts[i].x,y1:line.pts[i].y,x2:line.pts[i+1].x,y2:line.pts[i+1].y});
  }
  segCache=segs;return segs;
}
function distToSeg(px,py,x1,y1,x2,y2){
  const dx=x2-x1,dy=y2-y1,L2=dx*dx+dy*dy||1;
  let t=((px-x1)*dx+(py-y1)*dy)/L2;t=Math.max(0,Math.min(1,t));
  return{d:Math.hypot(px-(x1+t*dx),py-(y1+t*dy)),x:x1+t*dx,y:y1+t*dy,nx:-dy/Math.sqrt(L2),ny:dx/Math.sqrt(L2)};
}
const particles=[];
for(let i=0;i<60;i++)particles.push({a:false});
function update(dt){
  G.time+=dt;if(G.hintT>0)G.hintT-=dt;
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  if(!G.rolling||G.state!=='play')return;
  const b=G.ball,L=LEVELS[G.level-1];
  b.vy+=1400*dt;
  b.vx*=0.998;
  b.x+=b.vx*dt;b.y+=b.vy*dt;
  // line collisions
  for(const s of lineSegs()){
    const c=distToSeg(b.x,b.y,s.x1,s.y1,s.x2,s.y2);
    if(c.d<b.r+4){
      // push out
      const nx=c.nx,ny=c.ny;
      // ensure normal points away from ball velocity or upward
      const dot=b.vx*nx+b.vy*ny;
      const px=dot<0?nx:-nx,py=dot<0?ny:-ny;
      b.x=c.x+px*(b.r+4);b.y=c.y+py*(b.r+4);
      const vn=b.vx*px+b.vy*py;
      if(vn<0){
        b.vx-=1.7*vn*px;b.vy-=1.7*vn*py;
        b.vx*=0.96;b.vy*=0.96;
        if(Math.abs(vn)>120)sfx.bump();
      }
      // friction along line
      b.vx*=0.999;b.vy*=0.999;
    }
  }
  // obstacle collisions (solid blocks)
  for(const o of L.obs){
    const ox=o.x*W,oy=o.y*H,ow=o.w*W,oh=o.h*H;
    if(b.x+b.r>ox&&b.x-b.r<ox+ow&&b.y+b.r>oy&&b.y-b.r<oy+oh){
      // push out (simple)
      const dl=b.x+b.r-ox,dr=ox+ow-(b.x-b.r),dt2=b.y+b.r-oy,db=oy+oh-(b.y-b.r);
      const m=Math.min(dl,dr,dt2,db);
      if(m===dl){b.x=ox-b.r;b.vx=-Math.abs(b.vx)*0.6;}
      else if(m===dr){b.x=ox+ow+b.r;b.vx=Math.abs(b.vx)*0.6;}
      else if(m===dt2){b.y=oy-b.r;b.vy=-Math.abs(b.vy)*0.6;}
      else{b.y=oy+oh+b.r;b.vy=Math.abs(b.vy)*0.6;}
      sfx.bump();
    }
  }
  // walls
  if(b.x<b.r){b.x=b.r;b.vx=Math.abs(b.vx)*0.7;}
  if(b.x>W-b.r){b.x=W-b.r;b.vx=-Math.abs(b.vx)*0.7;}
  if(b.y>H-b.r){b.y=H-b.r;b.vy=-Math.abs(b.vy)*0.5;b.vx*=0.9;}
  // goal check
  const gx=L.gx*W,gy=L.gy*H;
  if(Math.hypot(b.x-gx,b.y-gy)<34){
    levelComplete();return;
  }
  // stuck: ball at rest for 2.5s, or 12s total roll, ends the attempt
  G.rollT=(G.rollT||0)+dt;
  if(Math.hypot(b.vx,b.vy)<28)G.stillT=(G.stillT||0)+dt;else G.stillT=0;
  if(G.stillT>2.5||G.rollT>12){levelFailed();return;}
}
function levelComplete(){
  G.state='clear';sfx.win();
  const inkBonus=Math.round(G.ink/G.maxInk*300);
  const pts=200+inkBonus;G.score+=pts;updateHUD();
  const stars=G.ink/G.maxInk>0.5?3:G.ink/G.maxInk>0.25?2:1;
  document.getElementById('stars').textContent=`⭐ ${stars}/3`;
  for(let i=0;i<20;i++){const p=particles.find(p=>!p.a);if(!p)break;
    const L=LEVELS[G.level-1];
    p.a=true;p.x=L.gx*W;p.y=L.gy*H;
    const a=Math.random()*Math.PI*2;p.vx=Math.cos(a)*250;p.vy=Math.sin(a)*250;
    p.life=0.7;p.max=0.7;p.color='#ffd23f';p.size=4;}
  setTimeout(()=>{
    if(G.level>=13){
      showOverlay('🏆 MASTER ARTIST!',
        `<p style="font-size:24px;font-weight:900">Final Score: ${G.score}</p><p>All 13 levels solved!</p>`,
        '🔥 Fire Safety: You\'re a champion!',
        '↻ PLAY AGAIN',()=>{G.score=0;initLevel(1);G.state='play';});
    }else{
      showOverlay(`⭐ LEVEL ${G.level} COMPLETE!`,
        `<div style="color:#ffd23f;font-size:26px">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</div><p>+${pts} pts (+${inkBonus} ink bonus)</p>`,
        '🔥 Fire Safety: Draw your escape route!',
        '▶ NEXT LEVEL',()=>{initLevel(G.level+1);G.state='play';});
    }
  },800);
}
function levelFailed(){
  G.state='clear';
  setTimeout(()=>{
    showOverlay('💥 STUCK!',
      `<p>The fire baby couldn't reach the goal.</p><p>Try a different line!</p>`,
      '🔥 Fire Safety: Never give up!',
      '↻ TRY AGAIN',()=>{initLevel(G.level);G.state='play';});
  },500);
}
let mathAnswer=0;
