function pickLevel(n){sfx.click();audio();G.score=0;initLevel(n);G.state='play';overlay.classList.add('hidden');}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;
  obtn.textContent=btn;obtn.style.display='';
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
obtn.onclick=()=>{showMathGate();};
function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#140d08');bg.addColorStop(1,'#1e1208');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  if(G.state==='title')return;
  // [gauntlet contrast] faint dotted guide grid over the near-empty black field (pre-rendered once per size)
  if(!render._grid||render._gridW!==W||render._gridH!==H){
    const gc=document.createElement('canvas');gc.width=W;gc.height=H;const gx2=gc.getContext('2d');
    gx2.fillStyle='rgba(255,255,255,0.055)';
    for(let dx=24;dx<W;dx+=48)for(let dy=24;dy<H;dy+=48){gx2.beginPath();gx2.arc(dx,dy,1.6,0,Math.PI*2);gx2.fill();}
    render._grid=gc;render._gridW=W;render._gridH=H;
  }
  ctx.drawImage(render._grid,0,0);
  // living ember background (additive glow)
  ctx.save();ctx.globalCompositeOperation='lighter';
  for(let i=0;i<24;i++){
    const ex=((i*173+Math.sin(G.time*0.7+i)*12)%W+W)%W;
    const ey=H-((i*137+G.time*(22+(i%5)*7))%(H+30));
    ctx.globalAlpha=0.08+((i*29)%26)/100;ctx.fillStyle=i%3?'#ff7a2a':'#ffd23f';
    ctx.beginPath();ctx.arc(ex,ey,1.6+(i%3),0,Math.PI*2);ctx.fill();
  }
  ctx.restore();ctx.globalAlpha=1;
  const L=LEVELS[G.level-1];
  // obstacles
  for(const o of L.obs){
    ctx.fillStyle='#3a2a1a';
    ctx.fillRect(o.x*W,o.y*H,o.w*W,o.h*H);
    ctx.strokeStyle='#5a4a3a';ctx.lineWidth=2;
    ctx.strokeRect(o.x*W,o.y*H,o.w*W,o.h*H);
  }
  // start & goal
  const sx=L.sx*W,sy=L.sy*H,gx=L.gx*W,gy=L.gy*H;
  ctx.fillStyle='#4caf50';ctx.globalAlpha=0.3;
  ctx.beginPath();ctx.arc(sx,sy,30,0,Math.PI*2);ctx.fill();
  ctx.globalAlpha=1;
  ctx.fillStyle='#4caf50';ctx.font='900 13px system-ui';ctx.textAlign='center';
  ctx.fillText('START',sx,sy-36);ctx.textAlign='left';
  // goal: pulsing
  const pulse=1+Math.sin(G.time*4)*0.12;
  ctx.save();ctx.translate(gx,gy);ctx.scale(pulse,pulse);
  const gg=ctx.createRadialGradient(0,0,5,0,0,34);
  gg.addColorStop(0,'rgba(255,210,63,0.9)');gg.addColorStop(1,'rgba(255,210,63,0.1)');
  ctx.fillStyle=gg;ctx.beginPath();ctx.arc(0,0,34,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#ffd23f';ctx.font='28px system-ui';ctx.textAlign='center';
  ctx.fillText('🏁',0,10);ctx.textAlign='left';
  ctx.restore();
  // drawn lines
  ctx.strokeStyle='#7fd4ff';ctx.lineWidth=7;ctx.lineCap='round';ctx.lineJoin='round';
  for(const line of G.lines){
    ctx.beginPath();
    line.pts.forEach((p,i)=>i===0?ctx.moveTo(p.x,p.y):ctx.lineTo(p.x,p.y));
    ctx.stroke();
    ctx.strokeStyle='rgba(255,255,255,0.5)';ctx.lineWidth=2;
    ctx.stroke();
    ctx.strokeStyle='#7fd4ff';ctx.lineWidth=7;
  }
  if(G.drawing){
    ctx.beginPath();
    G.drawing.pts.forEach((p,i)=>i===0?ctx.moveTo(p.x,p.y):ctx.lineTo(p.x,p.y));
    ctx.stroke();
  }
  // ball
  const b=G.ball;
  if(b){
    const g=ctx.createRadialGradient(b.x-5,b.y-6,3,b.x,b.y,b.r);
    g.addColorStop(0,'#ffe9a0');g.addColorStop(0.5,'#ff7a2a');g.addColorStop(1,'#d42a1a');
    ctx.fillStyle=g;ctx.shadowColor='#ff7a2a';ctx.shadowBlur=6;
    ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
    ctx.fillStyle='#2b1a0e';
    ctx.beginPath();ctx.arc(b.x-5,b.y-3,3,0,Math.PI*2);ctx.arc(b.x+5,b.y-3,3,0,Math.PI*2);ctx.fill();
  }
  // GO button
  if(!G.rolling&&G.state==='play'){
    const gb=G.goBtn;
    ctx.fillStyle=G.lines.length?'#4caf50':'#555';
    ctx.beginPath();ctx.roundRect(gb.x,gb.y,gb.w,gb.h,12);ctx.fill();
    ctx.fillStyle='#fff';ctx.font='900 18px system-ui';ctx.textAlign='center';
    ctx.fillText('▶ GO',gb.x+gb.w/2,gb.y+gb.h/2+6);ctx.textAlign='left';
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  if(G.state==='play'&&!G.rolling&&G.lines.length===0){ // [gauntlet clarity] the draw sentence on the play screen (was menu-only)
    ctx.fillStyle='rgba(255,255,255,0.85)';ctx.font='900 18px system-ui';ctx.textAlign='center';
    ctx.fillText('DRAW A PATH, THEN PRESS ▶ GO!',W/2,H*0.16);
    ctx.textAlign='left';
  }
  if(G.hintT>0){
    ctx.fillStyle='rgba(0,0,0,0.6)';ctx.beginPath();ctx.roundRect(W/2-130,H*0.3-24,260,48,12);ctx.fill();
    ctx.fillStyle='#ffd23f';ctx.font='900 19px system-ui';ctx.textAlign='center';
    ctx.fillText('✏️ Draw a line first!',W/2,H*0.3+7);ctx.textAlign='left';
  }
  if(PAUSED){
    ctx.fillStyle='rgba(0,0,0,0.45)';ctx.fillRect(0,0,W,H);
    ctx.fillStyle='#fff';ctx.font='900 34px system-ui';ctx.textAlign='center';
    ctx.fillText('⏸ PAUSED',W/2,H/2);ctx.textAlign='left';
  }
}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(G.state==='play'&&!PAUSED)update(dt);else G.time+=dt;
  render();
  requestAnimationFrame(loop);
}
let MUTED=false,PAUSED=false;
const _tone25=tone;
tone=function(f0,f1,dur,type,vol,delay=0){if(MUTED)return;_tone25(f0,f1,dur,type,vol,delay);};
document.getElementById('muteBtn').onclick=()=>{MUTED=!MUTED;document.getElementById('muteBtn').textContent=MUTED?'🔇':'🔊';if(!MUTED)sfx.click();};
function setPaused(p){PAUSED=p;document.getElementById('pauseBtn').textContent=PAUSED?'▶':'⏸';}
document.getElementById('pauseBtn').onclick=()=>{if(G.state==='play')setPaused(!PAUSED);};
addEventListener('keydown',e=>{if((e.key==='p'||e.key==='P'||e.key==='Escape')&&G.state==='play')setPaused(!PAUSED);});
resize();
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Draw the Line' — Lava Line Draw's own
   track. Synthesized Web Audio only. 100 BPM, C lydian: a gentle sine lead
   and almost no drums at all — calm creative space for drawing your way out.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-25-lava-line-draw.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
const MUS={on:false,step:0,nextT:0,BPM:100,
 BASS:[36,0,0,0,0,0,0,0, 38,0,0,0,0,0,0,0, 43,0,0,0,0,0,0,0, 36,0,0,0,43,0,38,0],
 LEAD:[72,0,74,0,78,0,76,0, 74,0,0,0,71,0,0,0, 76,0,79,0,81,0,79,0, 76,0,74,0,72,0,0,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(MUTED||PAUSED||G.state!=='play'){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.5,'sine',0.045,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.3,'sine',0.05,d);
  if(s%16===0)tone(100,45,0.12,'sine',0.08,d); // barely-there pulse, twice a loop
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

