scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();
let AC=null;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  hit(){tone(500,700,0.06,'square',0.1);},
  wall(){tone(300,400,0.05,'square',0.07);},
  score(){tone(700,1000,0.15,'triangle',0.14);},
  lose(){tone(400,150,0.25,'sawtooth',0.13);},
  win(){[523,659,784,1047,1319].forEach((f,i)=>tone(f,f,0.2,'triangle',0.15,i*0.09));},
  click(){tone(600,600,0.06,'square',0.1);}
};
const DIFFS=[
  {aiSpeed:280,aiErr:90,ballSpeed:420},
  {aiSpeed:380,aiErr:45,ballSpeed:520},
  {aiSpeed:560,aiErr:8,ballSpeed:620},
];
const G={state:'title',diff:2,ps:0,as:0,surge:0,
  py:0,ay:0,bx:0,by:0,bvx:0,bvy:0,serveT:0,
  time:0,shake:0,trail:[],spin:0};
const PW=14,PH=110,BR=11;
function reset(){
  G.ps=0;G.as=0;G.surge=0;G.py=H/2;G.ay=H/2;
  serve(Math.random()<0.5?-1:1);
  updateHUD();
}
function speedScale(){return W<600?0.72:1;}
function serve(dir){
  const D=DIFFS[G.diff];
  G.bx=W/2;G.by=H/2;
  const a=(Math.random()-0.5)*0.9;
  G.bvx=Math.cos(a)*D.ballSpeed*speedScale()*dir;
  G.bvy=Math.sin(a)*D.ballSpeed*speedScale();
  G.serveT=0.8;G.trail=[];
}
function updateHUD(){
  document.getElementById('pscore').textContent=G.ps;
  document.getElementById('ascore').textContent=G.as;
}
document.querySelectorAll('.dbtn').forEach(b=>{
  b.addEventListener('click',e=>{
    e.stopPropagation();
    document.querySelectorAll('.dbtn').forEach(x=>x.classList.remove('sel'));
    b.classList.add('sel');G.diff=+b.dataset.d;sfx.click();
  });
});
function movePlayer(y){G.py=Math.max(PH/2,Math.min(H-PH/2,y));}
canvas.addEventListener('pointermove',e=>movePlayer(e.clientY));
canvas.addEventListener('pointerdown',e=>movePlayer(e.clientY));
const keysOn={};
addEventListener('keydown',e=>{keysOn[e.key.toLowerCase()]=true;});
addEventListener('keyup',e=>{keysOn[e.key.toLowerCase()]=false;});
const particles=[];
for(let i=0;i<80;i++)particles.push({a:false});
function burst(x,y,color){
  for(let i=0;i<8;i++){const p=particles.find(p=>!p.a);if(!p)break;
    const a=Math.random()*Math.PI*2;
    p.a=true;p.x=x;p.y=y;p.vx=Math.cos(a)*200;p.vy=Math.sin(a)*200;
    p.life=0.35;p.max=0.35;p.color=color;p.size=3+Math.random()*3;}
}
function update(dt){
  G.time+=dt;G.shake=Math.max(0,G.shake-dt*3);
  if(keysOn['arrowup']||keysOn['w'])movePlayer(G.py-640*dt);
  if(keysOn['arrowdown']||keysOn['s'])movePlayer(G.py+640*dt);
  const D=DIFFS[G.diff];
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  if(G.serveT>0){G.serveT-=dt;return;}
  // AI
  let aiTarget=G.by;
  if(G.bvx>0){ // ball coming toward AI
    let predY;
    if(G.diff===2){
      // HARD bot (2026-10-12): full trajectory read — steps the ball
      // forward with the game's own wall + spin-curve physics, so it
      // tracks curving balls the old straight-line guess missed...
      let sx=G.bx,sy=G.by,svx=G.bvx,svy=G.bvy,ss=G.spin;
      const plane=W-30-PW-BR, sdt=1/120;
      for(let s=0;s<480&&sx<plane;s++){
        svy+=ss*sdt; ss*=Math.pow(0.99,sdt*60);
        sx+=svx*sdt; sy+=svy*sdt;
        if(sy<BR){sy=BR;svy=Math.abs(svy);}
        if(sy>H-BR){sy=H-BR;svy=-Math.abs(svy);}
      }
      predY=sy;
      // ...and it AIMS the return away from the player's paddle by
      // offsetting the contact point (rel>0 sends the ball downward).
      const want=(G.py<predY)?0.55:-0.55;
      aiTarget=predY-want*(PH/2);
      if(Math.abs(aiTarget-predY)>PH/2-BR-4)aiTarget=predY; // never whiff on purpose
    }else{
      // easy/medium: straight-line prediction, no spin read
      const t=(W-30-G.bx)/G.bvx;
      predY=G.by+G.bvy*t;
      predY=((predY%(H*2))+H*2)%(H*2);
      if(predY>H)predY=H*2-predY;
      aiTarget=predY;
    }
    aiTarget+=(Math.random()-0.5)*D.aiErr;
  }else{
    aiTarget=H/2+Math.sin(G.time*1.5)*60; // idle drift
  }
  const dy=aiTarget-G.ay;
  G.ay+=Math.max(-D.aiSpeed*dt,Math.min(D.aiSpeed*dt,dy));
  G.ay=Math.max(PH/2,Math.min(H-PH/2,G.ay));
  // ball
  G.bx+=G.bvx*dt;G.by+=G.bvy*dt;
  // spin curve
  if(G.spin!==0){
    G.bvy+=G.spin*dt;G.spin*=Math.pow(0.99,dt*60);
  }
  G.trail.push({x:G.bx,y:G.by});if(G.trail.length>10)G.trail.shift();
  // walls
  if(G.by<BR){G.by=BR;G.bvy=Math.abs(G.bvy);sfx.wall();}
  if(G.by>H-BR){G.by=H-BR;G.bvy=-Math.abs(G.bvy);sfx.wall();}
  // player paddle (left)
  if(G.bvx<0&&G.bx-BR<30+PW&&G.bx+BR>30){
    if(Math.abs(G.by-G.py)<PH/2+BR){
      const rel=(G.by-G.py)/(PH/2);
      let spd=Math.min(950*speedScale(),Math.hypot(G.bvx,G.bvy)*1.06+12);
      G.surge++;
      const surged=G.surge>=4;
      if(surged){spd=Math.min(1188*speedScale(),spd*1.25);G.surge=0;} // FLAME SURGE: +25%
      const ang=rel*1.05;
      G.bvx=Math.cos(ang)*spd;G.bvy=Math.sin(ang)*spd;
      G.bx=30+PW+BR;
      G.spin=rel*220; // curve!
      if(surged){tone(250,950,0.2,'sawtooth',0.15);burst(G.bx,G.by,'#ff9a3a');burst(G.bx,G.by,'#ffd23f');}
      else{sfx.hit();burst(G.bx,G.by,'#7fd4ff');}
    }
  }
  // AI paddle (right)
  if(G.bvx>0&&G.bx+BR>W-30-PW){
    if(Math.abs(G.by-G.ay)<PH/2+BR){
      const rel=(G.by-G.ay)/(PH/2);
      const spd=Math.min(950*speedScale(),Math.hypot(G.bvx,G.bvy)*1.06+12);
      const ang=rel*1.05;
      G.bvx=-Math.cos(ang)*spd;G.bvy=Math.sin(ang)*spd;
      G.bx=W-30-PW-BR;
      G.spin=-rel*220;
      sfx.hit();burst(G.bx,G.by,'#ff6a8a');
    }
  }
  // score
  if(G.bx<-30){
    G.as++;sfx.lose();G.shake=0.35;updateHUD();
    burst(20,G.by,'#ff4a5a',12);
    if(G.as>=7){endGame(false);return;}
    serve(1);
  }
  if(G.bx>W+30){
    G.ps++;sfx.score();G.shake=0.2;updateHUD();
    burst(W-20,G.by,'#7fd4ff',12);
    if(G.ps>=7){endGame(true);return;}
    serve(-1);
  }
}
function endGame(won){
  G.state='over';
  if(won)sfx.win();else sfx.lose();
  setTimeout(()=>{
    showOverlay(won?'🏆 YOU WIN!':'💥 AI WINS',
      `<p style="font-size:28px;font-weight:900">${G.ps} — ${G.as}</p><p>${won?'Amazing rally!':'The machine got you this time!'}</p>`,
      '🔥 Fire Safety: A good rally takes practice!',
      '↻ REMATCH',()=>{reset();G.state='play';});
  },700);
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();reset();G.state='play';overlay.classList.add('hidden');}
obtn.onclick=()=>{showMathGate();};
/* [w5c perf] Pre-baked glow sprites — the W5b-proven pattern copied from game-04:
   the ember loop's 24 per-frame shadowBlur=8 fills collapsed FPS under software
   rendering (10.0 FPS); blit a one-time radial-glow sprite instead. Colours,
   falloff and alpha unchanged; no gameplay/balance changes. */
function makeGlowSprite(hex){const c=document.createElement('canvas');c.width=c.height=96;const x=c.getContext('2d');
  const r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);
  const gr=x.createRadialGradient(48,48,0,48,48,48);
  gr.addColorStop(0,`rgba(${r},${g},${b},0.9)`);gr.addColorStop(0.35,`rgba(${r},${g},${b},0.38)`);gr.addColorStop(1,`rgba(${r},${g},${b},0)`);
  x.fillStyle=gr;x.fillRect(0,0,96,96);return c;}
const EMBER_SPRITE=makeGlowSprite('#ff7a2a');
const EMBER_SPRITE_GOLD=makeGlowSprite('#ffd23f');
function render(){
  const bgd=ctx.createLinearGradient(0,0,0,H);
  bgd.addColorStop(0,'#0d0a14');bgd.addColorStop(0.6,'#1a1030');bgd.addColorStop(1,'#2a1408');
  ctx.fillStyle=bgd;ctx.fillRect(0,0,W,H);
  // living ember background (additive glow)
  ctx.save();ctx.globalCompositeOperation='lighter';
  for(let i=0;i<24;i++){
    const ex=((i*173+Math.sin(G.time*0.7+i)*12)%W+W)%W;
    const ey=H-((i*137+G.time*(22+(i%5)*7))%(H+30));
    ctx.globalAlpha=0.08+((i*29)%26)/100;
    const r=(1.6+(i%3))*7;ctx.drawImage(i%3?EMBER_SPRITE:EMBER_SPRITE_GOLD,ex-r,ey-r,r*2,r*2); // [w5c perf] pre-baked glow (was shadowBlur=8 per ember per frame)
  }
  ctx.restore();ctx.globalAlpha=1;

  ctx.save();
  if(G.shake>0)ctx.translate((Math.random()-0.5)*G.shake*12,(Math.random()-0.5)*G.shake*12);
  // center line
  ctx.strokeStyle='rgba(255,255,255,0.15)';ctx.lineWidth=4;ctx.setLineDash([18,14]);
  ctx.beginPath();ctx.moveTo(W/2,0);ctx.lineTo(W/2,H);ctx.stroke();
  ctx.setLineDash([]);
  // center circle
  ctx.strokeStyle='rgba(255,255,255,0.1)';ctx.lineWidth=3;
  ctx.beginPath();ctx.arc(W/2,H/2,70,0,Math.PI*2);ctx.stroke();
  // paddles
  // [gauntlet perf] paddle gradients cached (fixed geometry); shadowBlur=12 replaced with a cheap glow underlay
  if(!render._pg1){render._pg1=ctx.createLinearGradient(0,0,PW,0);render._pg1.addColorStop(0,'#7fd4ff');render._pg1.addColorStop(1,'#2a78b8');}
  const pg1=render._pg1;
  ctx.fillStyle='rgba(127,212,255,0.30)';
  ctx.beginPath();ctx.roundRect(26,G.py-PH/2-4,PW+8,PH+8,10);ctx.fill();
  ctx.fillStyle=pg1;
  ctx.beginPath();ctx.roundRect(30,G.py-PH/2,PW,PH,8);ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.3)';ctx.fillRect(34,G.py-PH/2+8,3,PH-16);
  if(!render._pg2){render._pg2=ctx.createLinearGradient(0,0,PW,0);render._pg2.addColorStop(0,'#ff6a8a');render._pg2.addColorStop(1,'#a32a4a');}
  const pg2=render._pg2;
  ctx.fillStyle=pg2;
  ctx.beginPath();ctx.roundRect(W-30-PW,G.ay-PH/2,PW,PH,8);ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.3)';ctx.fillRect(W-30-PW+4,G.ay-PH/2+8,3,PH-16);
  // ball trail
  for(const t of G.trail){
    ctx.globalAlpha=0.2;ctx.fillStyle='#ffd23f';
    ctx.beginPath();ctx.arc(t.x,t.y,BR*0.7,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  // ball
  if(G.serveT<=0){
    const g=ctx.createRadialGradient(G.bx-4,G.by-4,2,G.bx,G.by,BR);
    g.addColorStop(0,'#fff');g.addColorStop(0.4,'#ffd23f');g.addColorStop(1,'#ff6a00');
    {ctx.save();ctx.globalAlpha=0.6;const gr3=BR*2.6;ctx.drawImage(EMBER_SPRITE_GOLD,G.bx-gr3,G.by-gr3,gr3*2,gr3*2);ctx.restore();} // [gauntlet perf] pre-baked ball glow (was shadowBlur=16 per frame)
    ctx.fillStyle=g;
    ctx.beginPath();ctx.arc(G.bx,G.by,BR,0,Math.PI*2);ctx.fill();
    // spin indicator
    if(Math.abs(G.spin)>40){
      ctx.strokeStyle='rgba(255,255,255,0.5)';ctx.lineWidth=2;
      ctx.beginPath();ctx.arc(G.bx,G.by,BR+6,G.time*8,G.time*8+2);ctx.stroke();
    }
  }else{
    ctx.fillStyle='#fff';ctx.font='900 24px system-ui';ctx.textAlign='center';
    ctx.fillText('GET READY...',W/2,H/2-60);ctx.textAlign='left';
  }
  if(G.state==='play'&&G.surge>=3){
    ctx.fillStyle='#ff9a3a';ctx.font='900 16px system-ui';ctx.textAlign='center';
    ctx.fillText('🔥 NEXT HIT: FLAME SURGE!',W/2,H-18);ctx.textAlign='left';
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  ctx.restore();
  if(PAUSED){
    ctx.fillStyle='rgba(0,0,0,0.45)';ctx.fillRect(0,0,W,H);
    ctx.fillStyle='#fff';ctx.font='900 34px system-ui';ctx.textAlign='center';
    ctx.fillText('⏸ PAUSED',W/2,H/2);ctx.textAlign='left';
  }
}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(G.state==='play'&&!PAUSED)update(dt);else G.time+=dt;
  render();
  requestAnimationFrame(loop);
}
let MUTED=false,PAUSED=false;
const _tone26=tone;
tone=function(f0,f1,dur,type,vol,delay=0){if(MUTED)return;_tone26(f0,f1,dur,type,vol,delay);};
document.getElementById('muteBtn').onclick=()=>{MUTED=!MUTED;document.getElementById('muteBtn').textContent=MUTED?'🔇':'🔊';if(!MUTED)sfx.click();};
function setPaused(p){PAUSED=p;document.getElementById('pauseBtn').textContent=PAUSED?'▶':'⏸';}
document.getElementById('pauseBtn').onclick=()=>{if(G.state==='play')setPaused(!PAUSED);};
document.getElementById('restartBtn').onclick=()=>{if(G.state==='play'){setPaused(false);reset();G.state='play';sfx.click();}};
addEventListener('keydown',e=>{if((e.key==='p'||e.key==='P'||e.key==='Escape')&&G.state==='play')setPaused(!PAUSED);});
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Paddle Clash' — Pyra Paddle Battle's own
   track. Synthesized Web Audio only. 130 BPM, A minor: the square lead
   ping-pongs between octaves like a rally that refuses to end, with a
   paddle-tick snare.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-26-pyra-paddle-battle.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
const MUS={on:false,step:0,nextT:0,BPM:130,
 BASS:[45,0,45,0,52,0,45,0, 45,0,45,0,52,0,50,0, 41,0,41,0,48,0,41,0, 40,0,40,0,47,0,52,0],
 LEAD:[81,0,69,0,84,0,72,0, 81,0,69,0,79,0,67,0, 84,0,72,0,81,0,69,0, 83,0,71,0,76,0,64,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(MUTED||PAUSED||G.state!=='play'){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.13,'square',0.05,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.13,'square',0.05,d);
  if(s%8===0||s%8===4)tone(120,45,0.11,'sine',0.12,d); // kick
  if(s%8===2||s%8===6)tone(210,150,0.03,'square',0.06,d); // paddle-tick snare
  if(s%2===0)tone(6800,6800,0.015,'square',0.008,d); // hat click
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

