scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();
let AC=null;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(window.__muted)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  bounce(){tone(400+Math.random()*100,700,0.09,'sine',0.1);},
  super(){tone(600,1400,0.18,'triangle',0.14);},
  break(){tone(500,150,0.12,'square',0.1);},
  fall(){tone(400,80,0.6,'sawtooth',0.14);},
  click(){tone(600,600,0.06,'square',0.1);}
};
const G={state:'title',score:0,best:0,px:0,py:0,vx:0,vy:0,
  plats:[],camY:0,time:0,dead:false};
try{G.best=parseInt(localStorage.getItem('bounce_best')||'0',10)||0;}catch(e){}
const PW2=76,PH2=16;
function reset(){
  G.score=0;G.px=W/2;G.py=H-100;G.vx=0;G.vy=-950;
  G.plats=[];G.camY=0;G.time=0;G.dead=false;
  // starting platforms
  G.plats.push({x:W/2-PW2/2,y:H-60,type:'normal',vx:0});
  let y=H-160;
  while(y>-H*2){
    spawnPlat(y);y-=60-Math.random()*20;
  }
  updateHUD();
  document.getElementById('best').textContent='🏆 '+Math.floor(G.best/10)+'m';
}
function spawnPlat(y){
  const r=Math.random();
  let type='normal';
  const h=Math.floor(-y/500);
  if(h>3&&r<0.12+Math.min(0.08,h*0.004))type='break';
  else if(h>2&&r<0.3)type='move';
  else if(h>4&&r<0.38)type='super';
  G.plats.push({
    x:Math.random()*(W-PW2),y,type,
    vx:type==='move'?(Math.random()<0.5?-1:1)*(60+Math.random()*60+Math.min(70,h*5)):0,
    broken:false
  });
}
function updateHUD(){
  document.getElementById('score').textContent='📏 '+Math.floor(G.score/10)+'m';
  if(G.score>G.best)document.getElementById('best').textContent='🏆 '+Math.floor(G.score/10)+'m';
}
// steering
let dragX=null;
canvas.addEventListener('pointerdown',e=>{dragX=e.clientX;try{canvas.setPointerCapture(e.pointerId);}catch(err){}});
canvas.addEventListener('pointermove',e=>{
  if(dragX===null||G.state!=='play')return;
  G.px+=(e.clientX-dragX)*1.4;dragX=e.clientX;
});
canvas.addEventListener('pointerup',()=>dragX=null);
const keys={};
addEventListener('keydown',e=>keys[e.key.toLowerCase()]=true);
addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
const particles=[];
for(let i=0;i<60;i++)particles.push({a:false});
function update(dt){
  G.time+=dt;
  // steer
  if(keys['arrowleft']||keys['a'])G.px-=340*dt;
  if(keys['arrowright']||keys['d'])G.px+=340*dt;
  // wrap
  if(G.px<-20)G.px=W+20;if(G.px>W+20)G.px=-20;
  // physics
  G.vy=Math.min(G.vy+1500*dt,1500);
  const prevFeet=G.py+16;
  G.py+=G.vy*dt;
  // camera follows up
  const screenY=G.py-G.camY;
  if(screenY<H*0.4){
    G.camY-=(H*0.4-screenY);
    const h=Math.floor(-G.camY/10);
    if(h>G.score){G.score=h;updateHUD();}
  }
  // spawn more
  const topY=G.camY-100;
  let minY=1e9;
  for(const p of G.plats)minY=Math.min(minY,p.y);
  while(minY>topY){
    minY-=55+Math.random()*25;
    spawnPlat(minY);
  }
  // platform collisions (falling onto)
  if(G.vy>0){
    for(const p of G.plats){
      if(p.broken)continue;
      if(G.py+16>p.y&&prevFeet<p.y+PH2+8&&G.px+14>p.x&&G.px-14<p.x+PW2){
        if(p.type==='break'){
          p.broken=true;sfx.break();
          for(let i=0;i<6;i++){const pt=particles.find(pt=>!pt.a);if(!pt)break;
            pt.a=true;pt.x=p.x+PW2/2;pt.y=p.y;pt.vx=(Math.random()-0.5)*200;pt.vy=-Math.random()*150;
            pt.life=0.4;pt.max=0.4;pt.color='#ff4a5a';pt.size=4;}
        }else{
          G.py=p.y-16;
          G.vy=p.type==='super'?-1350:-950;
          if(p.type==='super')sfx.super();else sfx.bounce();
          for(let i=0;i<5;i++){const pt=particles.find(pt=>!pt.a);if(!pt)break;
            pt.a=true;pt.x=G.px+(Math.random()-0.5)*22;pt.y=p.y;pt.vx=(Math.random()-0.5)*160;pt.vy=-Math.random()*90;
            pt.life=0.3;pt.max=0.3;pt.color=p.type==='super'?'#ffd23f':'#9fe870';pt.size=3;}
        }
        break;
      }
    }
  }
  // moving platforms
  for(const p of G.plats){
    if(p.vx!==0){
      p.x+=p.vx*dt;
      if(p.x<0||p.x+PW2>W)p.vx*=-1;
    }
  }
  // cleanup
  G.plats=G.plats.filter(p=>p.y<G.camY+H+100);
  // fell
  if(G.py-G.camY>H+60&&!G.dead){
    G.dead=true;sfx.fall();
    const isBest=G.score>G.best;
    if(isBest){G.best=G.score;try{localStorage.setItem('bounce_best',String(G.best));}catch(e){}}
    setTimeout(()=>{
      showOverlay('💥 YOU FELL!',
        `${isBest?'<p style="color:#ffd23f;font-weight:900">🏆 NEW BEST!</p>':''}<p style="font-size:26px;font-weight:900">Height: ${Math.floor(G.score/10)}m</p><p>Best: ${Math.floor(G.best/10)}m</p>`,
        '🔥 Fire Safety: Bounce back from mistakes!',
        '↻ BOUNCE AGAIN',()=>{reset();G.state='play';});
    },600);
  }
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=400*dt;p.life-=dt;if(p.life<=0)p.a=false;}
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  window.__paused=false;pauseBtn.textContent='⏸';
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();reset();G.state='play';overlay.classList.add('hidden');}
obtn.onclick=()=>{showMathGate();};
/* [w5c perf] Pre-baked glow sprites — the W5b-proven pattern copied from game-04:
   the ember loop's 24 per-frame shadowBlur=8 fills collapsed FPS under software
   rendering (10.0 FPS); blit a one-time radial-glow sprite instead. Colours,
   falloff and alpha unchanged; no gameplay/balance changes. */
function makeGlowSprite(hex){const c=document.createElement('canvas');c.width=c.height=96;const x=c.getContext('2d');
  const r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);
  const gr=x.createRadialGradient(48,48,0,48,48,48);
  gr.addColorStop(0,`rgba(${r},${g},${b},0.9)`);gr.addColorStop(0.35,`rgba(${r},${g},${b},0.38)`);gr.addColorStop(1,`rgba(${r},${g},${b},0)`);
  x.fillStyle=gr;x.fillRect(0,0,96,96);return c;}
const EMBER_SPRITE=makeGlowSprite('#ff7a2a');
const EMBER_SPRITE_GOLD=makeGlowSprite('#ffd23f');
function render(){
  // sky gradient based on height
  const hgt=Math.floor(-G.camY/2000);
  const bg=ctx.createLinearGradient(0,0,0,H);
  const hue=Math.min(200,140+hgt*8);
  bg.addColorStop(0,`hsl(${hue},40%,10%)`);
  bg.addColorStop(1,`hsl(${(hue+40)%360},50%,18%)`);
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  // clouds parallax
  ctx.fillStyle='rgba(255,255,255,0.07)';
  for(let i=0;i<8;i++){
    const cy=((i*233-G.camY*0.3)%(H+200)+(H+200))%(H+200)-100;
    const cx=(i*311)%W;
    ctx.beginPath();ctx.ellipse(cx,cy,70,20,0,0,Math.PI*2);ctx.fill();
  }
  // living ember background (additive glow)
  ctx.save();ctx.globalCompositeOperation='lighter';
  for(let i=0;i<24;i++){
    const ex=((i*173+Math.sin(G.time*0.7+i)*12)%W+W)%W;
    const ey=H-((i*137+G.time*(22+(i%5)*7))%(H+30));
    ctx.globalAlpha=0.08+((i*29)%26)/100;
    const r=(1.6+(i%3))*7;ctx.drawImage(i%3?EMBER_SPRITE:EMBER_SPRITE_GOLD,ex-r,ey-r,r*2,r*2); // [w5c perf] pre-baked glow (was shadowBlur=8 per ember per frame)
  }
  ctx.restore();ctx.globalAlpha=1;
  const offY=-G.camY;
  // platforms
  for(const p of G.plats){
    if(p.broken)continue;
    const sy=p.y+offY;
    if(sy<-30||sy>H+30)continue;
    let col='#4caf50',dark='#2a6a2a';
    if(p.type==='move'){col='#5ab8e8';dark='#2a6a8a';}
    else if(p.type==='break'){col='#ff4a5a';dark='#a32a3a';}
    else if(p.type==='super'){col='#ffd23f';dark='#a37a00';}
    ctx.fillStyle=dark;ctx.beginPath();ctx.roundRect(p.x,sy+3,PW2,PH2,8);ctx.fill();
    ctx.fillStyle=col;ctx.beginPath();ctx.roundRect(p.x,sy,PW2,PH2,8);ctx.fill();
    ctx.fillStyle='rgba(255,255,255,0.35)';ctx.fillRect(p.x+6,sy+3,PW2-12,4);
    if(p.type==='super'){
      ctx.font='13px system-ui';ctx.textAlign='center';
      ctx.fillText('⚡',p.x+PW2/2,sy+13);ctx.textAlign='left';
    }
  }
  // player
  const py=G.py+offY;
  if(py<H+40){
    const squash=Math.max(0.7,Math.min(1.3,1+G.vy/3000));
    ctx.save();ctx.translate(G.px,py);ctx.scale(1/squash,squash);
    const g=ctx.createRadialGradient(-6,-7,3,0,0,18);
    g.addColorStop(0,'#ffe9a0');g.addColorStop(0.5,'#ff7a2a');g.addColorStop(1,'#d42a1a');
    ctx.fillStyle=g;ctx.shadowColor='#ff7a2a';ctx.shadowBlur=16;
    ctx.beginPath();ctx.arc(0,0,16,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
    ctx.fillStyle='#2b1a0e';
    const look=G.vy<0?-3:3;
    ctx.beginPath();ctx.arc(-5,look-2,3,0,Math.PI*2);ctx.arc(5,look-2,3,0,Math.PI*2);ctx.fill();
    ctx.restore();
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    const sy=p.y+offY;
    ctx.beginPath();ctx.arc(p.x,sy,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
}

window.__paused=false;window.__muted=false;
const pauseBtn=document.getElementById('pauseBtn'),muteBtn=document.getElementById('muteBtn');
function setPaused(v){if(!['play','countdown'].includes(G.state))return;window.__paused=v;pauseBtn.textContent=v?'▶':'⏸';}
pauseBtn.addEventListener('click',e=>{e.stopPropagation();setPaused(!window.__paused);});
function toggleMute(){window.__muted=!window.__muted;muteBtn.textContent=window.__muted?'🔇':'🔊';}
muteBtn.addEventListener('click',e=>{e.stopPropagation();toggleMute();});
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(k==='p'||k==='escape')setPaused(!window.__paused);if(k==='m')toggleMute();});
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(!window.__paused&&G.state==='play'&&!G.dead)update(dt);else if(!window.__paused)G.time+=dt;
  render();
  if(window.__paused){ctx.fillStyle='rgba(0,0,0,0.55)';ctx.fillRect(0,0,W,H);ctx.fillStyle='#fff';ctx.font='900 34px system-ui';ctx.textAlign='center';ctx.fillText('⏸ PAUSED',W/2,H/2);ctx.font='700 17px system-ui';ctx.fillText('Tap ▶ or press P to resume',W/2,H/2+38);ctx.textAlign='left';}
  requestAnimationFrame(loop);
}
document.getElementById('best').textContent='🏆 '+Math.floor(G.best/10)+'m';
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Bounce House Ember' — Ember Bounce 2D's own
   track. Synthesized Web Audio only. 124 BPM, D major pentatonic: a rubbery
   triangle lead over an octave- bounce bass — the whole track is on springs.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Freeze gate CONFIRMED at insertion (2026-10-15): window.__muted mutes, window.__paused pauses, and music only
   plays while G.state==='play' — all read from this shell's own code.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-27-ember-bounce-2d.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
// Freeze gate (insertion-confirmed 2026-10-15): hard-wired to this shell's
// own confirmed globals — window.__muted / window.__paused / G.state. try/catch kept so it can never throw.
const _mGate=()=>{try{return !!(window.__muted||window.__paused||G.state!=='play');}catch(e){return false;}};
const MUS={on:false,step:0,nextT:0,BPM:124,
 BASS:[38,50,38,50,38,50,38,50, 43,55,43,55,43,55,43,55, 47,59,47,59,47,59,47,59, 45,57,45,57,45,57,50,52],
 LEAD:[74,0,78,0,81,0,78,0, 78,0,81,0,83,0,81,0, 83,0,81,0,78,0,81,0, 78,0,76,0,74,0,0,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(_mGate()){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.11,'triangle',0.05,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.15,'triangle',0.05,d);
  if(s%8===0||s%8===4)tone(120,45,0.11,'sine',0.13,d); // kick
  if(s%8===2||s%8===6)tone(190,120,0.07,'triangle',0.07,d); // tone-only snare
  if(s%2===0)tone(6800,6800,0.015,'square',0.008,d); // hat click
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

