scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();
let AC=null;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(window.__muted)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  tap(){tone(400+Math.random()*200,600,0.05,'square',0.07);},
  round(){tone(600,900,0.2,'triangle',0.14);},
  win(){[523,659,784,1047].forEach((f,i)=>tone(f,f,0.25,'triangle',0.18,i*0.1));},
  lose(){tone(400,120,0.4,'sawtooth',0.15);},
  count(n){tone(n*200+400,n*200+400,0.12,'sine',0.15);},
  click(){tone(600,600,0.06,'square',0.1);},
  anchor(){tone(170,60,0.25,'triangle',0.2);tone(500,950,0.16,'sine',0.1,0.03);}
};
const DIFFS=[
  {ai:2.2,name:'Easy'},
  {ai:3.2,name:'Medium'},
  {ai:4.2,name:'Hard'},
];
const G={state:'title',diff:2,round:1,pyou:0,pai:0,anchor:0,
  pos:0, // -1 (ai wins) to +1 (you win)
  counting:0,countT:0,tapTimes:[],time:0,shake:0,ropeTug:0};
function reset(){
  G.round=1;G.pyou=0;G.pai=0;G.pos=0;
  updateHUD();
}
function updateHUD(){
  document.getElementById('round').textContent=`ROUND ${Math.min(G.round,9)}/9`;
  document.getElementById('score').textContent=`YOU ${G.pyou}/5 — ${G.pai}/5 AI`;
}
document.querySelectorAll('.dbtn').forEach(b=>{
  b.addEventListener('click',e=>{
    e.stopPropagation();
    document.querySelectorAll('.dbtn').forEach(x=>x.classList.remove('sel'));
    b.classList.add('sel');G.diff=+b.dataset.d;sfx.click();
  });
});
function startRound(){
  G.pos=0;G.anchor=0;G.counting=3;G.countT=0;G.tapTimes=[];
  G.state='countdown';
  updateHUD();
}
function doPull(x,y){
  if(G.state!=='play')return;
  G.pos+=0.032; // each tap pulls
  G.anchor=Math.min(20,G.anchor+1); // taps charge the Ember Anchor
  G.ropeTug=1;
  G.tapTimes.push(performance.now());
  const now=performance.now();
  G.tapTimes=G.tapTimes.filter(t=>now-t<1000);
  document.getElementById('taps').textContent=`👆 ${G.tapTimes.length}/s`;
  sfx.tap();
  ripples.push({x:x,y:y,r:10,a:1});
  document.getElementById('anchorBtn').classList.toggle('ready',G.anchor>=20);
  if(G.pos>=1){winRound(true);}
}
canvas.addEventListener('pointerdown',e=>{
  if(G.state!=='play')return;
  e.preventDefault();
  const rect=canvas.getBoundingClientRect();
  doPull(e.clientX-rect.left,e.clientY-rect.top);
});
function slamAnchor(){
  if(G.state!=='play'||G.anchor<20)return;
  G.anchor=0;G.pos+=0.16;G.ropeTug=1;sfx.anchor();
  document.getElementById('anchorBtn').classList.remove('ready');
    for(let i=0;i<10;i++){const p=particles.find(p=>!p.a);if(!p)break;
      p.a=true;p.x=W/2+G.pos*W*0.38;p.y=H*0.45;p.vx=(Math.random()-0.5)*260;p.vy=(Math.random()-0.5)*260;
      p.life=0.45;p.max=0.45;p.color='#ffd23f';p.size=4;}
  if(G.pos>=1)winRound(true);
}
document.getElementById('anchorBtn').addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();slamAnchor();});
addEventListener('keydown',e=>{
  const k=e.key.toLowerCase();
  if(!e.repeat&&G.state==='play'&&(k==='arrowleft'||k==='arrowright'||k==='a'||k==='d'||k==='enter')){doPull(W/2,H*0.45);}
  if((e.key===' '||e.key==='Spacebar')&&G.state==='play'&&G.anchor>=20){
    e.preventDefault();slamAnchor();
  }
});
const ripples=[];
const embers=[];for(let i=0;i<24;i++)embers.push({x:Math.random()*2200,y:Math.random()*1200,s:1+Math.random()*2.5,v:14+Math.random()*26,ph:Math.random()*6.28});
/* [w5c perf] Pre-baked glow sprites — the W5b-proven pattern copied from game-04:
   the ember loop's 24 per-frame shadowBlur=8 fills collapsed FPS under software
   rendering (10.0 FPS); blit a one-time radial-glow sprite instead. Colours,
   falloff and alpha unchanged; no gameplay/balance changes. */
function makeGlowSprite(hex){const c=document.createElement('canvas');c.width=c.height=96;const x=c.getContext('2d');
  const r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);
  const gr=x.createRadialGradient(48,48,0,48,48,48);
  gr.addColorStop(0,`rgba(${r},${g},${b},0.9)`);gr.addColorStop(0.35,`rgba(${r},${g},${b},0.38)`);gr.addColorStop(1,`rgba(${r},${g},${b},0)`);
  x.fillStyle=gr;x.fillRect(0,0,96,96);return c;}
const EMBER_SPRITE=makeGlowSprite('#ff9a3a');
const HEAD_GLOW=makeGlowSprite('#ff7a2a'); // [w5c perf] character-head glow sprite
function drawEmbers(){ctx.save();ctx.globalCompositeOperation='lighter';
  for(const e of embers){e.y-=e.v*0.016;e.x+=Math.sin(G.time*0.9+e.ph)*0.3;
    if(e.y<-6){e.y=H+6;e.x=Math.random()*W;}
    const tw=0.5+0.5*Math.sin(G.time*2+e.ph);
    ctx.globalAlpha=0.13+0.22*tw;const r=e.s*7;ctx.drawImage(EMBER_SPRITE,(e.x%(W+12))-r,e.y-r,r*2,r*2);}
  ctx.restore();ctx.globalAlpha=1;}
const particles=[];
for(let i=0;i<80;i++)particles.push({a:false});
function update(dt){
  G.time+=dt;G.shake=Math.max(0,G.shake-dt*3);
  G.ropeTug=Math.max(0,G.ropeTug-dt*4);
  if(G.state==='countdown'){
    G.countT+=dt;
    const n=3-Math.floor(G.countT);
    if(n!==G.counting&&n>0){G.counting=n;sfx.count(n);}
    if(G.countT>=3){
      G.state='play';G.counting=0;sfx.count(4);
    }
    return;
  }
  if(G.state!=='play')return;
  // AI pulls
  const D=DIFFS[G.diff];
  G.pos-=D.ai*dt*0.05*(1+G.round*0.12);
  // natural drift back to center
  G.pos-=G.pos*0.15*dt;
  // tap rate decay display
  const now=performance.now();
  G.tapTimes=G.tapTimes.filter(t=>now-t<1000);
  if(Math.random()<0.1)document.getElementById('taps').textContent=`👆 ${G.tapTimes.length}/s`;
  if(G.pos<=-1){winRound(false);}
  for(const r of ripples){r.r+=180*dt;r.a-=2.5*dt;}
  for(let i=ripples.length-1;i>=0;i--)if(ripples[i].a<=0)ripples.splice(i,1);
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)p.a=false;}
}
function winRound(youWon){
  document.getElementById('anchorBtn').classList.remove('ready');
  if(youWon){G.pyou++;sfx.win();G.shake=0.3;}
  else{G.pai++;sfx.lose();G.shake=0.3;}
  updateHUD();
  // celebration
  for(let i=0;i<20;i++){const p=particles.find(p=>!p.a);if(!p)break;
    p.a=true;p.x=W/2;p.y=H*0.4;
    const a=Math.random()*Math.PI*2;p.vx=Math.cos(a)*280;p.vy=Math.sin(a)*280;
    p.life=0.7;p.max=0.7;p.color=youWon?'#ffd23f':'#ff4a5a';p.size=4;}
  if(G.pyou>=5||G.pai>=5){
    G.state='over';
    setTimeout(()=>{
      const won=G.pyou>=5;
      showOverlay(won?'🏆 YOU WIN THE MATCH!':'💥 AI WINS THE MATCH',
        `<p style="font-size:28px;font-weight:900">YOU ${G.pyou} — ${G.pai} AI</p><p>${won?'Incredible tapping!':'The AI out-pulled you!'}</p>`,
        '🔥 Fire Safety: Pull together — teamwork wins!',
        '↻ REMATCH',()=>{reset();startRound();});
    },900);
  }else{
    G.state='roundend';G.round++;sfx.round();
    setTimeout(()=>{
      showOverlay(youWon?'💪 ROUND WON!':'😤 ROUND LOST',
        `<p>Score: YOU ${G.pyou} — ${G.pai} AI</p><p>Get ready for round ${G.round}!</p>`,
        '🔥 Fire Safety: Keep pulling!',
        '▶ NEXT ROUND',()=>{startRound();});
    },900);
  }
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  window.__paused=false;pauseBtn.textContent='⏸';
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();reset();startRound();overlay.classList.add('hidden');}
obtn.onclick=()=>{showMathGate();};
function render(){
  // [gauntlet perf] background gradient cached (was re-created every frame)
  if(!render._bg||render._bgH!==H){const bgn=ctx.createLinearGradient(0,0,0,H);
    bgn.addColorStop(0,'#140d08');bgn.addColorStop(0.6,'#1e1408');bgn.addColorStop(1,'#2a1a0a');
    render._bg=bgn;render._bgH=H;}
  ctx.fillStyle=render._bg;ctx.fillRect(0,0,W,H);
  drawEmbers();
  ctx.save();
  if(G.shake>0)ctx.translate((Math.random()-0.5)*G.shake*12,(Math.random()-0.5)*G.shake*12);
  const cy=H*0.45;
  const flagX=W/2+G.pos*W*0.38;
  // win lines
  ctx.strokeStyle='rgba(127,212,255,0.6)';ctx.lineWidth=4;ctx.setLineDash([12,8]);
  ctx.beginPath();ctx.moveTo(W*0.12,cy-90);ctx.lineTo(W*0.12,cy+90);ctx.stroke();
  ctx.strokeStyle='rgba(255,106,138,0.6)';
  ctx.beginPath();ctx.moveTo(W*0.88,cy-90);ctx.lineTo(W*0.88,cy+90);ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle='#7fd4ff';ctx.font='900 13px system-ui';ctx.textAlign='center';
  ctx.fillText('YOUR LINE',W*0.12,cy-100);
  ctx.fillStyle='#ff6a8a';ctx.fillText('AI LINE',W*0.88,cy-58);
  ctx.textAlign='left';
  // rope (sagging)
  const tug=G.ropeTug;
  ctx.strokeStyle='#c89a5a';ctx.lineWidth=10+tug*4;ctx.lineCap='round';
  ctx.beginPath();
  ctx.moveTo(W*0.08,cy+Math.sin(G.time*2)*4);
  ctx.quadraticCurveTo(W/2,cy+40-tug*18,flagX,cy);
  ctx.quadraticCurveTo(W*0.75,cy-30+tug*10,W*0.92,cy+Math.sin(G.time*2+1)*4);
  ctx.stroke();
  // flag
  const fg=flagX;
  ctx.fillStyle='#ffd23f';
  ctx.beginPath();ctx.moveTo(fg,cy-46);ctx.lineTo(fg+34,cy-34);ctx.lineTo(fg,cy-22);ctx.closePath();ctx.fill();
  ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.stroke();
  // pullers: you (left) vs AI (right)
  drawTeam(W*0.08,cy,'#7fd4ff','YOU',true);
  drawTeam(W*0.92,cy,'#ff6a8a','AI',false);
  // center marker showing who's winning
  const mw=Math.abs(G.pos)*100;
  ctx.fillStyle=G.pos>0?'#7fd4ff':G.pos<0?'#ff6a8a':'#666';
  ctx.font='900 20px system-ui';ctx.textAlign='center';
  if(Math.abs(G.pos)>0.05)ctx.fillText(G.pos>0?'◀ PULLING!':'PULLING! ▶',W/2,cy+76);
  ctx.textAlign='left';
  // tap ripples
  for(const r of ripples){
    ctx.globalAlpha=Math.max(0,r.a);
    ctx.strokeStyle='#ffd23f';ctx.lineWidth=3;
    ctx.beginPath();ctx.arc(r.x,r.y,r.r,0,Math.PI*2);ctx.stroke();
  }
  ctx.globalAlpha=1;
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  // Ember Anchor meter (weapon)
  if(G.state==='play'||G.state==='countdown'){
    const bw=Math.min(280,W*0.6),bx=W/2-bw/2,by=cy+138;
    ctx.fillStyle='rgba(0,0,0,0.5)';ctx.beginPath();ctx.roundRect(bx,by,bw,16,8);ctx.fill();
    ctx.fillStyle=G.anchor>=20?'#ffd23f':'#ff8c2e';
    ctx.beginPath();ctx.roundRect(bx,by,bw*(G.anchor/20),16,8);ctx.fill();
    ctx.fillStyle='#fff';ctx.font='900 13px system-ui';ctx.textAlign='center';
    ctx.fillText(G.anchor>=20?'⚓ EMBER ANCHOR READY — PRESS SPACE!':'⚓ Ember Anchor '+G.anchor+'/20',W/2,by+32);
    ctx.textAlign='left';
  }
  ctx.restore();
  // countdown
  if(G.state==='countdown'&&G.counting>0){
    ctx.fillStyle='rgba(0,0,0,0.5)';ctx.fillRect(0,0,W,H);
    ctx.fillStyle='#ffd23f';ctx.font='900 90px system-ui';ctx.textAlign='center';
    ctx.fillText(G.counting,W/2,H/2);ctx.textAlign='left';
    ctx.font='900 22px system-ui';ctx.fillStyle='#fff';
    ctx.fillText('TAP FAST WHEN IT STARTS!',W/2,H/2+60);
  }
  if(G.state==='play'){
    ctx.fillStyle='rgba(255,255,255,0.7)';ctx.font='900 18px system-ui';ctx.textAlign='center';
    ctx.fillText('👆 TAP TAP TAP! 👆',W/2,H*0.78);
    ctx.textAlign='left';
  }
}
function drawTeam(x,y,color,label,faceRight){
  // 3 pullers
  for(let i=0;i<3;i++){
    const px=x+(faceRight?-1:1)*i*44;
    const lean=Math.sin(G.time*6+i)*3+(G.state==='play'?8:0);
    ctx.save();ctx.translate(px,y+30);ctx.rotate((faceRight?-1:1)*lean*0.02);
    // body
    ctx.fillStyle=color;ctx.globalAlpha=0.9;
    ctx.beginPath();ctx.roundRect(-14,-34,28,40,8);ctx.fill();
    // head (fire baby)
    // [gauntlet perf] head gradient cached (fixed geometry — was re-created for all 6 pullers every frame)
    if(!drawTeam._hg){drawTeam._hg=ctx.createRadialGradient(-4,-44,2,0,-40,14);
      drawTeam._hg.addColorStop(0,'#ffe9a0');drawTeam._hg.addColorStop(1,'#ff7a2a');}
    ctx.fillStyle=drawTeam._hg;
    {ctx.save();ctx.globalAlpha=0.55;const gr2=29;ctx.drawImage(HEAD_GLOW,-gr2,-40-gr2,gr2*2,gr2*2);ctx.restore();} // [w5c perf] pre-baked head glow (was shadowBlur=16 per head per frame)
    ctx.beginPath();ctx.arc(0,-40,13,0,Math.PI*2);ctx.fill();
    ctx.restore();
  }
  ctx.globalAlpha=1;
  ctx.fillStyle=color;ctx.font='900 16px system-ui';ctx.textAlign='center';
  ctx.fillText(label,x,y+80);ctx.textAlign='left';
}

window.__paused=false;window.__muted=false;
const pauseBtn=document.getElementById('pauseBtn'),muteBtn=document.getElementById('muteBtn');
function setPaused(v){if(!['play','countdown'].includes(G.state))return;window.__paused=v;pauseBtn.textContent=v?'▶':'⏸';}
pauseBtn.addEventListener('click',e=>{e.stopPropagation();setPaused(!window.__paused);});
function toggleMute(){window.__muted=!window.__muted;muteBtn.textContent=window.__muted?'🔇':'🔊';}
muteBtn.addEventListener('click',e=>{e.stopPropagation();toggleMute();});
/* [w5b] restart control (site standard pause/mute/restart) — wired to the same
   reset path the match-end REMATCH button uses: reset() + startRound() */
const restartBtn=document.getElementById('restartBtn');
restartBtn.addEventListener('click',e=>{e.stopPropagation();if(!['play','countdown'].includes(G.state))return;window.__paused=false;pauseBtn.textContent='⏸';overlay.classList.add('hidden');reset();startRound();sfx.click();});
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(k==='p'||k==='escape')setPaused(!window.__paused);if(k==='m')toggleMute();});
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(!window.__paused&&(G.state==='countdown'||G.state==='play'))update(dt);else if(!window.__paused)G.time+=dt;
  render();
  if(window.__paused){ctx.fillStyle='rgba(0,0,0,0.55)';ctx.fillRect(0,0,W,H);ctx.fillStyle='#fff';ctx.font='900 34px system-ui';ctx.textAlign='center';ctx.fillText('⏸ PAUSED',W/2,H/2);ctx.font='700 17px system-ui';ctx.fillText('Tap ▶ or press P to resume',W/2,H/2+38);ctx.textAlign='left';}
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Heave-Ho Heat' — Thermal Tug-of-War's own
   track. Synthesized Web Audio only. 112 BPM, E minor: the lead pushes
   uphill for two bars, then gets pulled back down — and the bass accents
   land on the heave and the ho.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Freeze gate CONFIRMED at insertion (2026-10-15): window.__muted mutes, window.__paused pauses, and music only
   plays while G.state==='play' — all read from this shell's own code.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-28-thermal-tug-of-war.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
// Freeze gate (insertion-confirmed 2026-10-15): hard-wired to this shell's
// own confirmed globals — window.__muted / window.__paused / G.state. try/catch kept so it can never throw.
const _mGate=()=>{try{return !!(window.__muted||window.__paused||G.state!=='play');}catch(e){return false;}};
const MUS={on:false,step:0,nextT:0,BPM:112,
 BASS:[40,0,0,47,0,0,40,0, 36,0,0,43,0,0,36,0, 43,0,0,50,0,0,43,0, 38,0,0,45,0,0,47,0],
 LEAD:[64,0,67,0,71,0,0,0, 0,0,74,0,76,0,0,0, 79,0,76,0,74,0,71,0, 0,0,69,0,67,0,64,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(_mGate()){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.16,'square',0.055,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.18,'square',0.05,d);
  if(s%8===0||s%8===3||s%8===4)tone(118,45,0.12,'sine',0.13,d); // heave-ho kick accents
  if(s%8===6)tone(190,120,0.07,'triangle',0.07,d); // tone-only snare on the ho
  if(s%4===0)tone(6800,6800,0.015,'square',0.007,d); // hat click
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

