  {plats:[[0,0.8,1.4,0.2],[1.9,0.67,0.8,0.08],[3.1,0.54,0.8,0.08],[4.3,0.67,0.8,0.08],[5.5,0.54,0.8,0.08],[6.7,0.67,0.8,0.08],[7.9,0.54,0.8,0.08],[9.1,0.67,0.8,0.08],[10.3,0.8,1.7,0.2]],
   coins:[[2.2,0.57],[3.4,0.44],[4.6,0.57],[5.8,0.44],[8.2,0.44],[9.4,0.57]],enemies:[[0.8,0.72],[4.6,0.59],[7,0.59],[11,0.72]],goal:11.4,len:12},
  {plats:[[0,0.8,1.2,0.2],[1.7,0.67,0.9,0.08],[3,0.54,0.9,0.08],[4.3,0.67,0.9,0.08],[5.6,0.54,0.9,0.08],[6.9,0.67,0.9,0.08],[8.2,0.54,0.9,0.08],[9.5,0.67,0.9,0.08],[10.7,0.8,1.3,0.2]],
   coins:[[2,0.57],[3.3,0.44],[4.6,0.57],[5.9,0.44],[8.5,0.44],[9.8,0.57]],enemies:[[0.7,0.72],[3.3,0.46],[7.2,0.59],[11.3,0.72]],goal:11.4,len:12},
  {plats:[[0,0.8,1,0.2],[1.5,0.67,0.8,0.08],[2.7,0.54,0.8,0.08],[3.9,0.67,0.8,0.08],[5.1,0.54,0.8,0.08],[6.3,0.67,0.8,0.08],[7.5,0.54,0.8,0.08],[8.7,0.67,0.8,0.08],[9.9,0.54,0.8,0.08],[11.1,0.8,0.9,0.2]],
   coins:[[1.8,0.57],[3,0.44],[4.2,0.57],[5.4,0.44],[6.6,0.57],[7.8,0.44],[10.2,0.44]],enemies:[[0.6,0.72],[4.2,0.59],[7.8,0.46],[11.5,0.72]],goal:11.4,len:12},
];
const TILE=90; // world units
const G={state:'title',level:1,score:0,
  px:0,py:0,vx:0,vy:0,onGround:false,face:1,
  camX:0,coins:[],enemies:[],time:0,shake:0,dead:false,coyote:0,jbuf:0,shots:[],shotCD:0,startScore:0};
function initLevel(n){
  const L=LEVELS[n-1];
  G.level=n;G.px=TILE*0.5;G.py=H*0.5;G.vx=0;G.vy=0;G.camX=0;
  G.time=0;G.shake=0;G.dead=false;G.score=G.score||0;
  G.shots=[];G.shotCD=0;G.startScore=G.score;
  G.coins=L.coins.map(c=>({x:c[0]*TILE,y:c[1]*H,taken:false,t:Math.random()*6}));
  G.enemies=L.enemies.map(e=>({x:e[0]*TILE,y:e[1]*H,vx:60,dir:1,dead:false,t:Math.random()*6,minX:(e[0]-0.6)*TILE,maxX:(e[0]+0.6)*TILE}));
  document.getElementById('level').textContent=`LV ${n}/10`;
  document.getElementById('coins').textContent=`🪙 0/${G.coins.length}`;
  updateHUD();
}
function updateHUD(){document.getElementById('score').textContent='⭐ '+G.score;}
// input
const keys={};
addEventListener('keydown',e=>{
  keys[e.key.toLowerCase()]=true;
  if(e.key===' '||e.key==='ArrowUp'){jump();e.preventDefault();}
});
addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;
  if(e.key===' '||e.key==='ArrowUp')jumpCut();});
function jumpCut(){if(G.state==='play'&&G.vy<-320)G.vy=-320;}
function shootFireball(){
  if(G.state!=='play'||G.dead||G.shotCD>0)return;
  G.shotCD=0.35;sfx.shoot();
  G.shots.push({x:G.px+G.face*22,y:G.py-2,vx:G.face*540,life:0.9});
}
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(k==='f'||k==='x')shootFireball();});
function jump(){
  if(G.state!=='play'||G.dead)return;
  if(G.onGround||G.coyote>0){
    G.vy=-780;G.onGround=false;G.coyote=0;sfx.jump();
  }else G.jbuf=0.12;
}
let touchL=false,touchR=false,runPtr=null;
canvas.addEventListener('pointerdown',e=>{
  if(G.state!=='play')return;
  if(e.clientX<W*0.4)jump();
  else{touchR=true;runPtr=e.pointerId;try{canvas.setPointerCapture(e.pointerId);}catch(err){}}
});
canvas.addEventListener('pointerup',e=>{if(e.pointerId===runPtr){touchR=false;runPtr=null;}});
canvas.addEventListener('pointercancel',e=>{if(e.pointerId===runPtr){touchR=false;runPtr=null;}});
document.getElementById('jumpBtn').addEventListener('pointerdown',e=>{e.stopPropagation();jump();});
document.getElementById('jumpBtn').addEventListener('pointerup',()=>jumpCut());
document.getElementById('shootBtn').addEventListener('pointerdown',e=>{e.stopPropagation();shootFireball();});
function bindHold(id,fn){const el=document.getElementById(id);
  el.addEventListener('pointerdown',e=>{e.stopPropagation();fn(true);});
  ['pointerup','pointercancel','pointerleave'].forEach(ev=>el.addEventListener(ev,()=>fn(false)));}
bindHold('leftBtn',v=>touchL=v);bindHold('rightBtn',v=>touchR=v);
if('ontouchstart'in window){document.getElementById('jumpBtn').style.display='block';document.getElementById('shootBtn').style.display='block';document.getElementById('moveBtns').style.display='flex';}
const particles=[];
for(let i=0;i<70;i++)particles.push({a:false});
const embers=[];for(let i=0;i<24;i++)embers.push({x:Math.random()*2200,y:Math.random()*1200,s:1+Math.random()*2.5,v:14+Math.random()*26,ph:Math.random()*6.28});
/* [w5c perf] Pre-baked glow sprites — the W5b-proven pattern copied from game-04:
   the ember loop's 24 per-frame shadowBlur=8 fills collapsed FPS under software
   rendering (10.0 FPS); blit a one-time radial-glow sprite instead. Colours,
   falloff and alpha unchanged; no gameplay/balance changes. */
function makeGlowSprite(hex){const c=document.createElement('canvas');c.width=c.height=96;const x=c.getContext('2d');
  const r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);
  const gr=x.createRadialGradient(48,48,0,48,48,48);
  gr.addColorStop(0,`rgba(${r},${g},${b},0.9)`);gr.addColorStop(0.35,`rgba(${r},${g},${b},0.38)`);gr.addColorStop(1,`rgba(${r},${g},${b},0)`);
  x.fillStyle=gr;x.fillRect(0,0,96,96);return c;}
const EMBER_SPRITE=makeGlowSprite('#ff9a3a');
function drawEmbers(){ctx.save();ctx.globalCompositeOperation='lighter';
  for(const e of embers){e.y-=e.v*0.016;e.x+=Math.sin(G.time*0.9+e.ph)*0.3;
    if(e.y<-6){e.y=H+6;e.x=Math.random()*W;}
    const tw=0.5+0.5*Math.sin(G.time*2+e.ph);
    ctx.globalAlpha=0.13+0.22*tw;const r=e.s*7;ctx.drawImage(EMBER_SPRITE,(e.x%(W+12))-r,e.y-r,r*2,r*2);}
  ctx.restore();ctx.globalAlpha=1;}
function burst(x,y,color){
  for(let i=0;i<7;i++){const p=particles.find(p=>!p.a);if(!p)break;
    const a=Math.random()*Math.PI*2;
    p.a=true;p.x=x;p.y=y;p.vx=Math.cos(a)*180;p.vy=Math.sin(a)*180-60;
    p.life=0.4;p.max=0.4;p.color=color;p.size=3+Math.random()*3;}
}
function plats(){
  return LEVELS[G.level-1].plats.map(p=>({x:p[0]*TILE,y:p[1]*H,w:p[2]*TILE,h:p[3]*H}));
}
function update(dt){
  G.time+=dt;G.shake=Math.max(0,G.shake-dt*3);
  const L=LEVELS[G.level-1];
  // move
  const SPEED=330;
  let ax=0;
  if(keys['arrowright']||keys['d']||touchR)ax+=1;
  if(keys['arrowleft']||keys['a']||touchL)ax-=1;
  G.vx=ax*SPEED;
  if(ax!==0)G.face=ax;
  G.vy+=2200*dt;G.vy=Math.min(G.vy,1200);
  G.px+=G.vx*dt;G.py+=G.vy*dt;
  G.px=Math.max(16,Math.min(L.len*TILE-16,G.px));
  // ground collision
  G.onGround=false;
  const pw=28,ph=32;
  for(const p of plats()){
    if(G.px+pw/2>p.x&&G.px-pw/2<p.x+p.w&&G.py+ph/2>p.y&&G.py+ph/2<p.y+p.h+20&&G.vy>=0){
      const prevY=G.py+ph/2-G.vy*dt;
      if(prevY<=p.y+8){
        G.py=p.y-ph/2;G.vy=0;G.onGround=true;G.coyote=0.1;
      }
    }
    // side bump — only on tall ground slabs; thin platforms are one-way (pass through)
    if(p.h>30&&G.px+pw/2>p.x&&G.px-pw/2<p.x+p.w&&G.py+ph/2>p.y+10&&G.py-ph/2<p.y+p.h){
      if(G.vx>0)G.px=p.x-pw/2;else if(G.vx<0)G.px=p.x+p.w+pw/2;
    }
  }
  G.coyote-=dt;G.jbuf-=dt;G.shotCD=Math.max(0,G.shotCD-dt);
  // fireballs (Ember Blaster)
  for(const sh of G.shots){
    sh.x+=sh.vx*dt;sh.life-=dt;
    for(const e of G.enemies){
      if(!e.dead&&Math.hypot(sh.x-e.x,sh.y-e.y)<32){
        e.dead=true;sh.life=0;G.score+=100;updateHUD();sfx.stomp();burst(e.x,e.y,'#ff8a3a');break;
      }
    }
  }
  G.shots=G.shots.filter(sh=>sh.life>0);
  if(G.jbuf>0&&(G.onGround||G.coyote>0))jump();
  // camera
  G.camX+=((G.px-W*0.38)-G.camX)*Math.min(1,dt*5);
  G.camX=Math.max(0,Math.min(L.len*TILE-W,G.camX));
  // coins
  for(const c of G.coins){
    c.t+=dt*4;
    if(!c.taken&&Math.hypot(G.px-c.x,G.py-c.y)<36){
      c.taken=true;sfx.coin();
      const n=G.coins.filter(x=>x.taken).length;
      document.getElementById('coins').textContent=`🪙 ${n}/${G.coins.length}`;
      G.score+=25;updateHUD();
      burst(c.x,c.y,'#ffd23f');
    }
  }
  // enemies
  for(const e of G.enemies){
    if(e.dead)continue;
    e.t+=dt*6;
    e.x+=e.vx*e.dir*dt;
    if(e.x<e.minX||e.x>e.maxX)e.dir*=-1;
    if(Math.abs(G.px-e.x)<34&&Math.abs(G.py-e.y)<36){
      if(G.vy>80&&G.py<e.y-8){
        // stomp!
        e.dead=true;G.vy=-520;sfx.stomp();G.score+=100;updateHUD();
        burst(e.x,e.y,'#ff6a5a');
      }else if(!G.dead){
        G.dead=true;sfx.hurt();G.shake=0.4;
        setTimeout(()=>{
          showOverlay('💥 OUCH!',
            `<p>You got hit! Score: ${G.score}</p>`,
            '🔥 Fire Safety: Jump to safety!',
            '↻ TRY AGAIN',()=>{G.score=G.startScore;initLevel(G.level);G.state='play';});
        },500);
        return;
      }
    }
  }
  // fell in pit
  if(G.py>H+80&&!G.dead){
    G.dead=true;sfx.hurt();
    setTimeout(()=>{
      showOverlay('💥 YOU FELL!',
        `<p>Watch the gaps! Score: ${G.score}</p>`,
        '🔥 Fire Safety: Watch your step!',
        '↻ TRY AGAIN',()=>{G.score=G.startScore;initLevel(G.level);G.state='play';});
    },500);
    return;
  }
  // goal
  if(G.px>=L.goal*TILE&&!G.dead){
    G.dead=true;sfx.win();
    G.score+=200;updateHUD(); // coins already paid +25 each on pickup — no double count
    setTimeout(()=>{
      if(G.level>=10){
        showOverlay('🏆 QUEST COMPLETE!',
          `<p style="font-size:24px;font-weight:900">Final Score: ${G.score}</p><p>You finished all 10 levels!</p>`,
          '🔥 Fire Safety: You\'re a champion!',
          '↻ PLAY AGAIN',()=>{G.score=0;initLevel(1);G.state='play';});
      }else{
        showOverlay(`⭐ LEVEL ${G.level} CLEAR!`,
          `<p>Coins: ${G.coins.filter(c=>c.taken).length}/${G.coins.length}</p><p>Score: ${G.score}</p>`,
          '🔥 Fire Safety: Keep jumping to safety!',
          '▶ NEXT LEVEL',()=>{initLevel(G.level+1);G.state='play';});
      }
    },600);
  }
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=500*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  // run dust
  if(G.onGround&&Math.abs(G.vx)>100&&Math.random()<0.3){
    const p=particles.find(p=>!p.a);
    if(p){p.a=true;p.x=G.px-G.face*14;p.y=G.py+16;p.vx=-G.face*60;p.vy=-40;
      p.life=0.3;p.max=0.3;p.color='#c89a6a';p.size=3;}
  }
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');showLevels();
  }else document.getElementById('ma').value='';
}
function showLevels(){
  otitle.innerHTML='🏃 PICK LEVEL';
  let h='';
  for(let i=1;i<=10;i++)h+=`<button class="lvlBtn" onclick="event.stopPropagation();pickLevel(${i})">${i}</button>`;
  obody.innerHTML=`<p>Run, jump, stomp, collect!</p><div id="lvlSel">${h}</div>`;
  obtn.style.display='none';
  overlay.classList.remove('hidden');
}
function pickLevel(n){sfx.click();audio();G.score=0;initLevel(n);G.state='play';overlay.classList.add('hidden');}
function showOverlay(title,body,lesson,btn,cb){
  window.__paused=false;pauseBtn.textContent='⏸';
  obtn.style.display='';
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
obtn.onclick=()=>{showMathGate();};
function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#1a2a4a');bg.addColorStop(0.6,'#2a1a3a');bg.addColorStop(1,'#140d08');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  drawEmbers();
  // parallax hills
  ctx.fillStyle='rgba(255,255,255,0.05)';
  for(let i=0;i<6;i++){
    const hx=((i*400-G.camX*0.3)%(W+400)+(W+400))%(W+400)-200;
    ctx.beginPath();ctx.arc(hx,H*0.85,140,Math.PI,0);ctx.fill();
  }
  ctx.save();
  if(G.shake>0)ctx.translate((Math.random()-0.5)*G.shake*12,(Math.random()-0.5)*G.shake*12);
  ctx.translate(-G.camX,0);
  // platforms
  for(const p of plats()){
    const g=ctx.createLinearGradient(0,p.y,0,p.y+p.h);
    g.addColorStop(0,'#6a4a2a');g.addColorStop(1,'#3a2412');
    ctx.fillStyle=g;ctx.fillRect(p.x,p.y,p.w,p.h);
    ctx.fillStyle='#8a6a3a';ctx.fillRect(p.x,p.y,p.w,10);
    // grass tufts
    ctx.fillStyle='#4caf50';
    for(let x=p.x+8;x<p.x+p.w;x+=24)ctx.fillRect(x,p.y-4,3,6);
  }
  // coins
  for(const c of G.coins){
    if(c.taken)continue;
    const bob=Math.sin(c.t)*6;
    ctx.save();ctx.translate(c.x,c.y+bob);ctx.scale(Math.abs(Math.cos(c.t*0.7))*0.6+0.4,1);
    const g=ctx.createRadialGradient(-4,-4,2,0,0,14);
    g.addColorStop(0,'#fff');g.addColorStop(0.5,'#ffd23f');g.addColorStop(1,'#a37a00');
    ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,13,0,Math.PI*2);ctx.fill();
    ctx.restore();
  }
  // enemies (ash blobs)
  for(const e of G.enemies){
    if(e.dead)continue;
    const squash=1+Math.sin(e.t)*0.12;
    ctx.save();ctx.translate(e.x,e.y);ctx.scale(1/squash,squash);
    const g=ctx.createRadialGradient(-6,-7,3,0,0,20);
    g.addColorStop(0,'#6a6a7a');g.addColorStop(1,'#2a2a3a');
    ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,18,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#ff4a00';
    ctx.beginPath();ctx.arc(-6,-3,3.5,0,Math.PI*2);ctx.arc(6,-3,3.5,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#1a1a2a';ctx.lineWidth=3;
    ctx.beginPath();ctx.arc(0,6,7,0.2,Math.PI-0.2);ctx.stroke();
    ctx.restore();
  }
  // goal flag
  const L=LEVELS[G.level-1];
  const gx=L.goal*TILE;
  ctx.strokeStyle='#fff';ctx.lineWidth=5;
  ctx.beginPath();ctx.moveTo(gx,H*0.3);ctx.lineTo(gx,H*0.75);ctx.stroke();
  const wave=Math.sin(G.time*5)*4;
  const fw=gx+60>W?-1:1; // [landscape fix] fly the flag inboard when the pole hugs the right edge
  ctx.fillStyle='#4caf50';
  ctx.beginPath();ctx.moveTo(gx,H*0.3);ctx.lineTo(gx+fw*(54+wave),H*0.36);ctx.lineTo(gx,H*0.44);ctx.closePath();ctx.fill();
  // player
  if(!G.dead){
    ctx.save();ctx.translate(G.px,G.py);ctx.scale(G.face,1);
    const runT=G.onGround?Math.sin(G.time*14)*3:0;
    // glow
    const gl=ctx.createRadialGradient(0,0,5,0,0,34);
    gl.addColorStop(0,'rgba(255,150,50,0.3)');gl.addColorStop(1,'rgba(255,150,50,0)');
    ctx.fillStyle=gl;ctx.beginPath();ctx.arc(0,0,34,0,Math.PI*2);ctx.fill();
    const g=ctx.createRadialGradient(-6,-7,3,0,0,20);
    g.addColorStop(0,'#ffe9a0');g.addColorStop(0.5,'#ff7a2a');g.addColorStop(1,'#d42a1a');
    ctx.fillStyle=g;ctx.shadowColor='#ff7a2a';ctx.shadowBlur=18;
    ctx.beginPath();ctx.arc(0,runT*0.3,18,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
    // legs
    ctx.fillStyle='#a33c10';
    ctx.fillRect(-10,12+runT,7,10-runT);ctx.fillRect(3,12-runT,7,10+runT);
    // face
    ctx.fillStyle='#2b1a0e';
    ctx.beginPath();ctx.arc(5,-4,3.5,0,Math.PI*2);ctx.fill();
    ctx.restore();
  }
  // fireballs (Ember Blaster)
  for(const sh of G.shots){
    ctx.save();ctx.translate(sh.x,sh.y);
    ctx.fillStyle='#ffb347';ctx.shadowColor='#ff6a1a';ctx.shadowBlur=16;
    ctx.beginPath();ctx.arc(0,0,9,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#ffe9a0';ctx.beginPath();ctx.arc(0,0,4.5,0,Math.PI*2);ctx.fill();
    ctx.restore();
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  ctx.restore();
}

window.__paused=false;window.__muted=false;
const pauseBtn=document.getElementById('pauseBtn'),muteBtn=document.getElementById('muteBtn');
function setPaused(v){if(!['play','countdown'].includes(G.state))return;window.__paused=v;pauseBtn.textContent=v?'▶':'⏸';}
pauseBtn.addEventListener('click',e=>{e.stopPropagation();setPaused(!window.__paused);});
function toggleMute(){window.__muted=!window.__muted;muteBtn.textContent=window.__muted?'🔇':'🔊';}
muteBtn.addEventListener('click',e=>{e.stopPropagation();toggleMute();});
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(k==='p'||k==='escape')setPaused(!window.__paused);if(k==='m')toggleMute();});
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(!window.__paused&&G.state==='play'&&!G.dead)update(dt);else if(!window.__paused)G.time+=dt;
  render();
  if(window.__paused){ctx.fillStyle='rgba(0,0,0,0.55)';ctx.fillRect(0,0,W,H);ctx.fillStyle='#fff';ctx.font='900 34px system-ui';ctx.textAlign='center';ctx.fillText('⏸ PAUSED',W/2,H/2);ctx.font='700 17px system-ui';ctx.fillText('Tap ▶ or press P to resume',W/2,H/2+38);ctx.textAlign='left';}
  requestAnimationFrame(loop);
}
resize();
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Quest for the Peak' — Blaze's Jump Quest's own
   track. Synthesized Web Audio only. 122 BPM, G major: a heroic square lead
   with proper marching drums — the quest anthem every jump deserves.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Freeze gate CONFIRMED at insertion (2026-10-15): window.__muted mutes, window.__paused pauses, and music only
   plays while G.state==='play' — all read from this shell's own code.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-29-blazes-jump-quest.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
// Freeze gate (insertion-confirmed 2026-10-15): hard-wired to this shell's
// own confirmed globals — window.__muted / window.__paused / G.state. try/catch kept so it can never throw.
const _mGate=()=>{try{return !!(window.__muted||window.__paused||G.state!=='play');}catch(e){return false;}};
const MUS={on:false,step:0,nextT:0,BPM:122,
 BASS:[43,0,43,0,50,0,43,0, 48,0,48,0,55,0,48,0, 40,0,40,0,47,0,40,0, 38,0,38,0,45,0,50,0],
 LEAD:[67,0,71,0,74,0,79,0, 76,0,74,0,72,0,0,0, 71,0,74,0,76,0,79,0, 78,0,74,0,71,0,0,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(_mGate()){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.14,'square',0.05,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.17,'square',0.05,d);
  if(s%2===0)tone(118,45,0.1,'sine',0.11,d); // marching kick
  if(s%8===2||s%8===6)tone(190,120,0.07,'triangle',0.07,d); // tone-only snare
  if(s===30||s===31)tone(190,120,0.05,'triangle',0.05,d); // pickup roll into the loop
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

