#overlay button:hover:not(:active){filter:brightness(1.08);transform:translateY(-1px)}
#overlay .lesson{border:1px solid rgba(255,255,255,.22);box-shadow:0 6px 18px rgba(0,0,0,.35)}
#mathgate{border:1px solid rgba(255,140,46,0.55);box-shadow:0 8px 22px rgba(0,0,0,.4)}
#mathgate input{transition:border-color .12s ease,box-shadow .12s ease}
#mathgate input:focus{border-color:#ff8c2e;box-shadow:0 0 0 3px rgba(255,140,46,0.35);outline:none}
#back{background:linear-gradient(180deg,rgba(34,18,9,.88),rgba(14,7,3,.88));border:1px solid rgba(255,255,255,.28);box-shadow:0 2px 10px rgba(0,0,0,.45),inset 0 1px 0 rgba(255,255,255,.15);transition:filter .12s ease,transform .12s ease}
#back:hover{filter:brightness(1.35)}
@media (prefers-reduced-motion:reduce){#overlay button,.lvlBtn,#back,#sysbtns button,#ctlBtns button,.btn,.dbtn,.abtn{transition:none}}

/* ---- banner (hub + content pages) ---- */
#fb-seasonal-banner{background:linear-gradient(90deg,#2a1052,#4b1d8f 45%,#2a1052);color:#ffe9d6;text-align:center;padding:12px 16px 11px;border-bottom:3px solid #ff8c1a;box-shadow:0 4px 24px rgba(124,58,237,.35);position:relative;z-index:60}
#fb-seasonal-banner .fb-sb-main{font-size:clamp(18px,3.6vw,26px);font-weight:900;letter-spacing:.5px;color:#ffb347;text-shadow:0 2px 14px rgba(255,140,26,.45);line-height:1.25}
#fb-seasonal-banner .fb-sb-sub{font-size:clamp(12px,2.6vw,14.5px);font-weight:600;color:#e9defc;margin-top:3px;line-height:1.4}
/* ---- decoration layers (never clickable, below menus) ---- */
#fb-seasonal-wall{position:fixed;inset:0;pointer-events:none;z-index:0;overflow:hidden}
#fb-seasonal-wall .fb-sb-wall-glyph{position:absolute;line-height:1;opacity:.09}
#fb-seasonal-decor{position:fixed;inset:0;pointer-events:none;z-index:90}
html.fb-mode-game #fb-seasonal-decor{z-index:2}
#fb-seasonal-decor .fb-sb-glyph{position:absolute;line-height:1;filter:drop-shadow(0 4px 10px rgba(0,0,0,.45))}
#fb-seasonal-ambience{position:fixed;inset:0;pointer-events:none;z-index:89;overflow:hidden}
#fb-seasonal-ambience .fb-sb-fall{position:absolute;top:-8vh;line-height:1;opacity:.5;animation-name:fb-sb-fall;animation-timing-function:linear;animation-iteration-count:infinite}
@keyframes fb-sb-fall{from{transform:translate3d(0,-8vh,0) rotate(-8deg)}to{transform:translate3d(3vw,112vh,0) rotate(38deg)}}
@keyframes fb-sb-bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-9px)}}
.fb-sb-bob{animation:fb-sb-bob 3.6s ease-in-out infinite}
/* ---- game-page badge ---- */
.fb-sb-badge{position:absolute;left:50%;bottom:6px;transform:translateX(-50%);font-size:17px;letter-spacing:2px;opacity:.55;line-height:1;white-space:nowrap}
/* ---- accents: every page ---- */
html.fb-theme-halloween ::selection{background:rgba(255,140,26,.5);color:#fff}
html.fb-mode-page body{background-color:#1c0a2a}
/* ---- hub showcase: deep-purple night + pumpkin glow ---- */
html.fb-mode-hub body{background:radial-gradient(1100px 560px at 50% -120px,rgba(124,58,237,.34),transparent 62%),radial-gradient(700px 380px at 85% 110%,rgba(255,140,26,.16),transparent 60%),#170a26}
html.fb-mode-hub nav.top{background:rgba(23,10,38,.96);border-bottom-color:rgba(155,89,182,.55)}
html.fb-mode-hub .hero{background:radial-gradient(ellipse at 50% 0%,rgba(255,140,26,.20),transparent 65%);border-bottom-color:rgba(155,89,182,.55)}
html.fb-mode-hub .hero h1{color:#ffb347;text-shadow:0 0 26px rgba(124,58,237,.65),0 4px 30px rgba(255,106,26,.35)}
html.fb-mode-hub .card{border-color:rgba(155,89,182,.5)}
html.fb-mode-hub .card:hover{border-color:#ff8c1a;box-shadow:0 16px 36px rgba(0,0,0,.45),0 0 26px rgba(124,58,237,.35)}
html.fb-mode-hub footer{border-top-color:rgba(155,89,182,.5)}
html.fb-mode-hub .hero,html.fb-mode-hub .whatsnew,html.fb-mode-hub .wrap,html.fb-mode-hub footer{position:relative;z-index:1}
/* ---- reduced motion: no falling/floating glyphs ---- */
@media (prefers-reduced-motion: reduce){#fb-seasonal-ambience{display:none}.fb-sb-bob{animation:none}}

scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);layout();}
function layout(){}
addEventListener('resize',resize);
let AC=null;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(window.__muted)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
function noise(dur,vol,delay=0,lp=900){if(window.__muted)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const len=ac.sampleRate*dur,buf=ac.createBuffer(1,len,ac.sampleRate),d=buf.getChannelData(0);
  for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);
  const s=ac.createBufferSource();s.buffer=buf;const f=ac.createBiquadFilter();f.type='lowpass';f.frequency.value=lp;
  const g=ac.createGain();g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  s.connect(f);f.connect(g);g.connect(ac.destination);s.start(t);}
const sfx={
  build(){tone(300,600,0.12,'triangle',0.12);},
  shoot(){tone(700,500,0.05,'square',0.05);},
  boom(){noise(0.2,0.25,0,500);},
  kill(){tone(500,800,0.08,'sine',0.08);},
  leak(){tone(350,120,0.25,'sawtooth',0.14);},
  wave(){tone(400,800,0.3,'triangle',0.14);},
  win(){[523,659,784,1047,1319].forEach((f,i)=>tone(f,f,0.2,'triangle',0.15,i*0.09));},
  click(){tone(600,600,0.06,'square',0.1);}
};
const TOWERS={
  arrow:{cost:50,range:150,dmg:12,rate:0.5,color:'#7fd4ff',emoji:'🏹'},
  cannon:{cost:100,range:120,dmg:35,rate:1.2,color:'#ff8a3a',emoji:'💣'},
  frost:{cost:75,range:130,dmg:6,rate:0.7,color:'#aee2ff',emoji:'❄️',slow:true},
  ember:{cost:125,range:140,dmg:38,rate:1.5,color:'#ff5a2a',emoji:'🔥',burn:true},
};
// 3 lanes
function lanes(){return[H*0.3,H*0.5,H*0.7];}
const G={state:'title',gold:150,wave:0,lives:20,score:0,
  towers:[],enemies:[],shots:[],sel:'arrow',
  waveT:0,spawnQ:[],betweenWaves:0,time:0,shake:0,path:[],msg:'',msgT:0};
function reset(){
  G.gold=150;G.wave=0;G.lives=20;G.score=0;
  G.towers=[];G.enemies=[];G.shots=[];
  G.betweenWaves=1.5;G.time=0;
  updateHUD();
}
function updateHUD(){
  document.getElementById('gold').textContent='🪙 '+Math.floor(G.gold)+' · ⭐ '+G.score;
  document.getElementById('wave').textContent=`🌊 Wave ${Math.min(Math.max(G.wave,1),15)}/15`;
  document.getElementById('lives').textContent='🏰 '+G.lives;
}
document.querySelectorAll('.tbtn').forEach(b=>{
  b.addEventListener('click',e=>{
    e.stopPropagation();
    document.querySelectorAll('.tbtn').forEach(x=>x.classList.remove('sel'));
    b.classList.add('sel');G.sel=b.dataset.t;sfx.click();
  });
});
// --- Tower selling (leftover-fix): LONG-PRESS a placed tower to sell it.
// Tap-to-upgrade already owns the single tap, and a double-tap would sell a
// tower a child just paid to upgrade — so selling uses a deliberate ~600ms
// hold instead: a gold progress ring fills around the tower; reaching full
// sells at 70% of total invested gold (base cost + upgrades paid). Releasing
// early or dragging off the tower cancels with no sale and no upgrade.
const SELL_HOLD=0.6,SELL_RATE=0.7;
G.hold=null; // {tower,x,y,t,cancelled}
function towerAt(x,y){for(const t of G.towers)if(Math.hypot(t.x-x,t.y-y)<44)return t;return null;}
function investedOf(t){if(t.invested!=null)return t.invested;let v=TOWERS[t.type].cost;for(let k=1;k<(t.lvl||1);k++)v+=Math.ceil(TOWERS[t.type].cost*0.7*k);return v;}
function sellRefund(t){return Math.floor(investedOf(t)*SELL_RATE);}
function upgradeTower(t){
  const upCost=Math.ceil(TOWERS[t.type].cost*0.7*(t.lvl||1));
  if((t.lvl||1)>=3){msg('⭐ That tower is max level (Lv3)');return;}
  if(G.gold<upCost){sfx.click();msg('Upgrade needs 🪙 '+upCost);return;}
  G.gold-=upCost;t.invested=investedOf(t)+upCost;t.lvl=(t.lvl||1)+1;t.dmgMul=1+0.5*(t.lvl-1);sfx.build();updateHUD();msg('⬆️ Tower upgraded to Lv'+t.lvl+' — +50% damage!');
}
function sellTower(t){
  const refund=sellRefund(t);
  G.towers=G.towers.filter(x=>x!==t);
  G.gold+=refund;sfx.build();tone(900,1400,0.12,'triangle',0.1);burst(t.x,t.y,'#ffd23f',10);updateHUD();
  msg('💰 Tower sold! +🪙 '+refund);
}
canvas.addEventListener('pointerdown',e=>{
  if(G.state!=='play'||window.__paused)return;
  const rect=canvas.getBoundingClientRect();
  const x=e.clientX-rect.left,y=e.clientY-rect.top;
  // can't build on castle or too far right
  if(x<W*0.14||x>W*0.94||y<H*0.18||y>H*0.85)return;
  const hit=towerAt(x,y);
  if(hit){G.hold={tower:hit,x,y,t:0,cancelled:false};return;} // tap (upgrade) or hold (sell) decided on release / timer
  const T=TOWERS[G.sel];
  if(G.gold<T.cost){sfx.click();msg('Not enough gold — need 🪙 '+T.cost);return;}
  G.gold-=T.cost;sfx.build();updateHUD();
  G.towers.push({x,y,type:G.sel,cd:0,lvl:1,invested:T.cost});
});
canvas.addEventListener('pointermove',e=>{
  if(!G.hold||G.hold.cancelled)return;
  const rect=canvas.getBoundingClientRect();
  const x=e.clientX-rect.left,y=e.clientY-rect.top;
  if(Math.hypot(x-G.hold.x,y-G.hold.y)>24){G.hold.cancelled=true;msg('✋ Sell cancelled');}
});
function endHold(){
  if(!G.hold)return;
  const h=G.hold;G.hold=null;
  if(h.cancelled||h.t>=SELL_HOLD)return; // dragged off = cancel; sold already by the hold timer
  if(window.__paused)return;
  upgradeTower(h.tower); // a short tap on a tower is the existing upgrade gesture
}
canvas.addEventListener('pointerup',endHold);
canvas.addEventListener('pointercancel',()=>{G.hold=null;});
function msg(t){G.msg=t;G.msgT=2.2;}
function startWave(n){
  G.wave=n;sfx.wave();
  const comp=[];
  const count=6+n*2;
  for(let i=0;i<count;i++){
    const r=Math.random();
    let type='grunt';
    if(n>=4&&r<0.2)type='tank';
    else if(n>=3&&r<0.4)type='fast';
    comp.push(type);
  }
  G.spawnQ=comp.map((t,i)=>({type:t,delay:i*(0.9-Math.min(0.5,n*0.04))}));
  updateHUD();
}
function spawnEnemy(type){
  const ls=lanes();
  const lane=Math.floor(Math.random()*3);
  const base={lane,x:W+30,t:Math.random()*10,slowT:0,hitT:0,burnT:0,burnTick:0};
  if(type==='grunt')Object.assign(base,{type,hp:30+G.wave*8,r:15,speed:55+G.wave*3,gold:8});
  else if(type==='fast')Object.assign(base,{type,hp:18+G.wave*5,r:12,speed:110+G.wave*4,gold:10});
  else Object.assign(base,{type:'tank',hp:90+G.wave*20,r:24,speed:35+G.wave*2,gold:25});
  base.y=ls[lane];
  G.enemies.push(base);
}
const particles=[];
for(let i=0;i<120;i++)particles.push({a:false});
function killEnemy(e){
  if(e.dead||e.hp>0)return;
  e.dead=true;G.gold+=e.gold;G.score+=e.gold*10;
  sfx.kill();burst(e.x,e.y,'#8a6a4a',10);updateHUD();
}
const embers=[];for(let i=0;i<24;i++)embers.push({x:Math.random()*2200,y:Math.random()*1200,s:1+Math.random()*2.5,v:14+Math.random()*26,ph:Math.random()*6.28});
/* [w5c perf] Pre-baked glow sprites — the W5b-proven pattern copied from game-04:
   the ember loop's 24 per-frame shadowBlur=8 fills collapsed FPS under software
   rendering (10.0 FPS); blit a one-time radial-glow sprite instead. Colours,
   falloff and alpha unchanged; no gameplay/balance changes. */
function makeGlowSprite(hex){const c=document.createElement('canvas');c.width=c.height=96;const x=c.getContext('2d');
  const r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);
  const gr=x.createRadialGradient(48,48,0,48,48,48);
  gr.addColorStop(0,`rgba(${r},${g},${b},0.9)`);gr.addColorStop(0.35,`rgba(${r},${g},${b},0.38)`);gr.addColorStop(1,`rgba(${r},${g},${b},0)`);
  x.fillStyle=gr;x.fillRect(0,0,96,96);return c;}
const EMBER_SPRITE=makeGlowSprite('#ff9a3a');
function drawEmbers(){ctx.save();ctx.globalCompositeOperation='lighter';
  for(const e of embers){e.y-=e.v*0.016;e.x+=Math.sin(performance.now()*0.0009+e.ph)*0.3;
    if(e.y<-6){e.y=H+6;e.x=Math.random()*W;}
    const tw=0.5+0.5*Math.sin(performance.now()*0.002+e.ph);
    ctx.globalAlpha=0.13+0.22*tw;const r=e.s*7;ctx.drawImage(EMBER_SPRITE,(e.x%(W+12))-r,e.y-r,r*2,r*2);}
  ctx.restore();ctx.globalAlpha=1;}
function burst(x,y,color,n=7){
  for(let i=0;i<n;i++){const p=particles.find(p=>!p.a);if(!p)break;
    const a=Math.random()*Math.PI*2;
    p.a=true;p.x=x;p.y=y;p.vx=Math.cos(a)*200;p.vy=Math.sin(a)*200;
    p.life=0.4;p.max=0.4;p.color=color;p.size=3+Math.random()*3;}
}
function update(dt){
  G.time+=dt;G.shake=Math.max(0,G.shake-dt*3);G.msgT=Math.max(0,G.msgT-dt);
  // wave flow
  if(!G.spawnQ.length&&!G.enemies.length&&G.state==='play'){
    if(G.wave>=15){victory();return;}
    G.betweenWaves-=dt;
    if(G.betweenWaves<=0){startWave(G.wave+1);G.betweenWaves=4;}
  }
  // spawn queue
  for(const q of G.spawnQ)q.delay-=dt;
  while(G.spawnQ.length&&G.spawnQ[0].delay<=0){
    spawnEnemy(G.spawnQ.shift().type);
  }
  // towers shoot
  for(const t of G.towers){
    t.cd-=dt;
    if(t.cd>0)continue;
    const T=TOWERS[t.type];
    let best=null,bd=1e9;
    for(const e of G.enemies){
      const d=Math.hypot(e.x-t.x,e.y-t.y);
      if(d<T.range&&e.x<bd){bd=e.x;best=e;}
    }
    if(best){
      t.cd=T.rate;t.aim=Math.atan2(best.y-t.y,best.x-t.x);
      G.shots.push({x:t.x,y:t.y-14,tx:best.x,ty:best.y,target:best,
        speed:t.type==='cannon'?320:560,dmg:T.dmg*(t.dmgMul||1),type:t.type});
      sfx.shoot();
    }
  }
  // shots
  for(const s of G.shots){
    if(s.target.dead){s.dead=true;continue;}
    const dx=s.target.x-s.x,dy=s.target.y-s.y,d=Math.hypot(dx,dy);
    const step=s.speed*dt;
    if(d<step+10){
      s.dead=true;
      const e=s.target;
      e.hp-=s.dmg;e.hitT=0.1;
      if(s.type==='cannon'){
        sfx.boom();burst(s.x,s.y,'#ff8a3a',12);
        // splash (kills credited via killEnemy)
        for(const o of G.enemies){
          if(o!==e&&!o.dead&&Math.hypot(o.x-e.x,o.y-e.y)<60){o.hp-=s.dmg*0.6;o.hitT=0.1;killEnemy(o);}
        }
      }else if(s.type==='frost'){
        e.slowT=2;burst(s.x,s.y,'#aee2ff',5);
      }else if(s.type==='ember'){
        e.burnT=2;e.burnTick=0;burst(s.x,s.y,'#ff5a2a',7);
      }else{
        burst(s.x,s.y,'#7fd4ff',4);
      }
      killEnemy(e);
    }else{
      s.x+=dx/d*step;s.y+=dy/d*step;
    }
  }
  G.shots=G.shots.filter(s=>!s.dead);
  // enemies march
  for(const e of G.enemies){
    if(e.dead)continue;
    e.t+=dt;e.hitT=Math.max(0,e.hitT-dt);
    if(e.burnT>0){e.burnT-=dt;e.burnTick-=dt;
      if(e.burnTick<=0){e.burnTick=0.5;e.hp-=6;e.hitT=0.1;killEnemy(e);if(e.dead)continue;}}
    const slow=e.slowT>0?0.5:1;e.slowT-=dt;
    e.x-=e.speed*slow*dt;
    e.y+=Math.sin(e.t*3)*8*dt;
    if(e.x<W*0.1){
      e.dead=true;G.lives--;sfx.leak();G.shake=0.4;updateHUD();
      burst(W*0.1,e.y,'#ff4a5a',10);
      if(G.lives<=0){defeat();return;}
    }
  }
  G.enemies=G.enemies.filter(e=>!e.dead);
  // passive income
  G.gold+=dt*1.5;
  if(Math.random()<0.05)updateHUD();
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)p.a=false;}
}
function victory(){
  G.state='over';sfx.win();
  setTimeout(()=>{
    showOverlay('🏆 VICTORY!',
      `<p style="font-size:24px;font-weight:900">Score: ${G.score}</p><p>All 15 waves defended! The castle stands!</p>`,
      '🔥 Fire Safety: You\'re a champion defender!',
      '↻ PLAY AGAIN',()=>{reset();G.state='play';});
  },600);
}
function defeat(){
  G.state='over';
  setTimeout(()=>{
    showOverlay('💥 CASTLE FALLEN',
      `<p>Wave reached: ${G.wave}/15</p><p>Score: ${G.score}</p>`,
      '🔥 Fire Safety: Defend your home!',
      '↻ TRY AGAIN',()=>{reset();G.state='play';});
  },600);
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  window.__paused=false;pauseBtn.textContent='⏸';
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();resize();reset();G.state='play';overlay.classList.add('hidden');}
obtn.onclick=()=>{showMathGate();};
function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#17102a');bg.addColorStop(0.55,'#0d0a14');bg.addColorStop(1,'#1c0f08');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  drawEmbers();
  ctx.save();
  if(G.shake>0)ctx.translate((Math.random()-0.5)*G.shake*12,(Math.random()-0.5)*G.shake*12);
  const ls=lanes();
  // lanes
  for(const y of ls){
    ctx.fillStyle='rgba(255,255,255,0.04)';
    ctx.fillRect(W*0.1,y-26,W*0.84,52);
    ctx.strokeStyle='rgba(255,255,255,0.1)';ctx.lineWidth=2;ctx.setLineDash([14,10]);
    ctx.beginPath();ctx.moveTo(W*0.1,y);ctx.lineTo(W*0.94,y);ctx.stroke();
    ctx.setLineDash([]);
  }
  // castle
  ctx.fillStyle='#5a4a6a';
  ctx.fillRect(0,H*0.18,W*0.09,H*0.67);
  ctx.fillStyle='#7a6a8a';
  for(let y=H*0.18;y<H*0.85;y+=30)ctx.fillRect(0,y,W*0.09,14);
  ctx.font='34px system-ui';ctx.textAlign='center';
  ctx.fillText('🏰',W*0.045,H*0.52);ctx.textAlign='left';
  // towers
  for(const t of G.towers){
    const T=TOWERS[t.type];
    // range preview on recent build
    ctx.fillStyle='#4a3a2a';
    ctx.beginPath();ctx.arc(t.x,t.y,20,0,Math.PI*2);ctx.fill();
    ctx.fillStyle=T.color;ctx.shadowColor=T.color;ctx.shadowBlur=12;
    ctx.beginPath();ctx.arc(t.x,t.y-6,14,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
    ctx.font='20px system-ui';ctx.textAlign='center';
    ctx.fillText(T.emoji,t.x,t.y+1);ctx.textAlign='left';
    if(t.lvl>1){ctx.fillStyle='#ffd23f';ctx.font='900 11px system-ui';ctx.textAlign='center';ctx.fillText('★'.repeat(t.lvl),t.x,t.y+24);ctx.textAlign='left';}
    // long-press sell progress ring
    if(G.hold&&G.hold.tower===t&&!G.hold.cancelled){
      const f=Math.min(1,G.hold.t/SELL_HOLD);
      ctx.strokeStyle='rgba(255,210,63,0.95)';ctx.lineWidth=5;ctx.lineCap='round';
      ctx.beginPath();ctx.arc(t.x,t.y,30,-Math.PI/2,-Math.PI/2+Math.PI*2*f);ctx.stroke();
      ctx.fillStyle='#ffd23f';ctx.font='900 12px system-ui';ctx.textAlign='center';
      ctx.fillText('💰 SELL +'+sellRefund(t),t.x,t.y-40);ctx.textAlign='left';
    }
    // aim barrel
    if(t.aim!==undefined){
      ctx.strokeStyle=T.color;ctx.lineWidth=5;ctx.lineCap='round';
      ctx.beginPath();ctx.moveTo(t.x,t.y-6);
      ctx.lineTo(t.x+Math.cos(t.aim)*22,t.y-6+Math.sin(t.aim)*22);ctx.stroke();
    }
  }
  // build ghost
  // enemies
  for(const e of G.enemies){
    ctx.save();ctx.translate(e.x,e.y);
    const flash=e.hitT>0;
    const g=ctx.createRadialGradient(-5,-5,3,0,0,e.r);
    if(e.type==='tank'){g.addColorStop(0,flash?'#fff':'#5a4a5a');g.addColorStop(1,'#2a1a2a');}
    else if(e.type==='fast'){g.addColorStop(0,flash?'#fff':'#8a7a5a');g.addColorStop(1,'#3a2a1a');}
    else{g.addColorStop(0,flash?'#fff':'#7a6a6a');g.addColorStop(1,'#333');}
    if(e.burnT>0){ctx.strokeStyle='#ff5a2a';ctx.lineWidth=3;ctx.shadowColor='#ff5a2a';ctx.shadowBlur=10;
      ctx.beginPath();ctx.arc(0,0,e.r+4,0,Math.PI*2);ctx.stroke();ctx.shadowBlur=0;}
    if(e.slowT>0){ctx.strokeStyle='#aee2ff';ctx.lineWidth=3;
      ctx.beginPath();ctx.arc(0,0,e.r+4,0,Math.PI*2);ctx.stroke();}
    ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,e.r,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#ff4a00';
    ctx.beginPath();ctx.arc(-e.r*0.3,-3,3.5,0,Math.PI*2);ctx.arc(e.r*0.3,-3,3.5,0,Math.PI*2);ctx.fill();
    // hp
    ctx.fillStyle='rgba(0,0,0,.5)';ctx.fillRect(-e.r,-e.r-9,e.r*2,4);
    ctx.fillStyle='#ff4a5a';
    const maxHp=e.type==='tank'?90+G.wave*20:e.type==='fast'?18+G.wave*5:30+G.wave*8;
    ctx.fillRect(-e.r,-e.r-9,e.r*2*Math.max(0,e.hp/maxHp),4);
    ctx.restore();
  }
  // shots
  for(const s of G.shots){
    ctx.fillStyle=s.type==='cannon'?'#ff8a3a':s.type==='frost'?'#aee2ff':s.type==='ember'?'#ff5a2a':'#ffd23f';
    ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=12;
    ctx.beginPath();ctx.arc(s.x,s.y,s.type==='cannon'||s.type==='ember'?7:4,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  ctx.restore();
  if(G.msgT>0&&G.msg){ctx.fillStyle='#ffd23f';ctx.font='900 19px system-ui';ctx.textAlign='center';ctx.fillText(G.msg,W/2,H*0.16);ctx.textAlign='left';}
  // next wave countdown
  if(G.state==='play'&&!G.spawnQ.length&&!G.enemies.length&&G.wave<15){
    ctx.fillStyle='#fff';ctx.font='900 18px system-ui';ctx.textAlign='center';
    ctx.fillText(`Next wave in ${Math.ceil(G.betweenWaves)}...`,W/2,H*0.12);
    ctx.textAlign='left';
  }
}

window.__paused=false;window.__muted=false;
const pauseBtn=document.getElementById('pauseBtn'),muteBtn=document.getElementById('muteBtn');
function setPaused(v){if(!['play','countdown'].includes(G.state))return;window.__paused=v;pauseBtn.textContent=v?'▶':'⏸';}
pauseBtn.addEventListener('click',e=>{e.stopPropagation();setPaused(!window.__paused);});
function toggleMute(){window.__muted=!window.__muted;muteBtn.textContent=window.__muted?'🔇':'🔊';}
muteBtn.addEventListener('click',e=>{e.stopPropagation();toggleMute();});
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(k==='p'||k==='escape')setPaused(!window.__paused);if(k==='m')toggleMute();});
let lastT=0;
function loop(t){
  const rawDt=Math.min((t-lastT)/1000||0,0.25); // wall-clock delta: the hold-to-sell timer must take a real ~600ms even on slow devices, so it uses raw frame time (still frozen while paused), not the capped/scaled game dt
  if(G.hold&&!G.hold.cancelled&&!window.__paused&&G.state==='play'){G.hold.t+=rawDt;if(G.hold.t>=SELL_HOLD){const ht=G.hold.tower;G.hold=null;sellTower(ht);}}
  const dt=Math.min(rawDt,1/30)*(window.__speed||1);lastT=t;
  if(!window.__paused&&G.state==='play')update(dt);else if(!window.__paused)G.time+=dt;
  render();
  if(window.__paused){ctx.fillStyle='rgba(0,0,0,0.55)';ctx.fillRect(0,0,W,H);ctx.fillStyle='#fff';ctx.font='900 34px system-ui';ctx.textAlign='center';ctx.fillText('⏸ PAUSED',W/2,H/2);ctx.font='700 17px system-ui';ctx.fillText('Tap ▶ or press P to resume',W/2,H/2+38);ctx.textAlign='left';}
  requestAnimationFrame(loop);
}
resize();
requestAnimationFrame(loop);
window.__speed=1;
document.getElementById('speedBtn').addEventListener('click',e=>{e.stopPropagation();window.__speed=window.__speed===1?2:1;e.currentTarget.textContent=window.__speed===2?'⏩2×':'⏩1×';});
/* ===== MUSIC (Jeff 2026-10-15): 'Rampart Rock' — Boulder's Rampart's own
   track. Synthesized Web Audio only. 100 BPM, D minor: a heavy sawtooth lead
   over war pads (Dm-Bb-F-C) and syncopated war drums — a brand-new melody,
   not the game-05 siege tune.
   Freeze gate CONFIRMED at insertion (2026-10-15): window.__muted mutes, window.__paused pauses, and music only
   plays while G.state==='play' — all read from this shell's own code.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-31-boulders-rampart.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
// Freeze gate (insertion-confirmed 2026-10-15): hard-wired to this shell's
// own confirmed globals — window.__muted / window.__paused / G.state. try/catch kept so it can never throw.
const _mGate=()=>{try{return !!(window.__muted||window.__paused||G.state!=='play');}catch(e){return false;}};
const MUS={on:false,step:0,nextT:0,BPM:100,
 BASS:[38,0,38,0,0,38,0,38, 46,0,46,0,0,46,0,0, 41,0,41,0,0,41,0,41, 36,0,38,0,41,0,43,0],
 LEAD:[62,0,0,65,0,69,0,0, 70,0,0,69,0,65,0,0, 69,0,0,72,0,74,0,0, 72,0,69,0,65,0,62,0],
 PAD:[38,46,41,36],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(_mGate()){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  if(s%8===0){const p=this.PAD[s>>3];if(p){tone(_mf(p),_mf(p),1.6,'sawtooth',0.016,d);tone(_mf(p)*1.006,_mf(p)*1.006,1.6,'sawtooth',0.016,d);tone(_mf(p+7),_mf(p+7),1.6,'triangle',0.02,d);}} // pad chord
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.15,'sawtooth',0.06,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.2,'sawtooth',0.05,d);
  if(s%8===0||s%8===3||s%8===6)tone(115,40,0.13,'sine',0.15,d); // war-drum kick
  if(s%8===4)noise(0.08,0.08,d,1700); // snare
  if(s===30||s===31)noise(0.05,0.06,d,1700); // war roll into the loop
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

