scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();
let AC=null,muted=false;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(muted)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  jump(){tone(500,900,0.12,'sine',0.1);},
  land(){tone(400,600,0.08,'triangle',0.09);},
  perfect(){tone(800,1600,0.18,'triangle',0.13);tone(1200,2000,0.12,'sine',0.1,0.06);},
  fall(){tone(400,80,0.5,'sawtooth',0.14);},
  click(){tone(600,600,0.06,'square',0.1);}
};
const G={state:'title',score:0,best:0,perfects:0,
  plats:[],px:0,py:0,vx:0,vy:0,jumping:false,
  camY:0,time:0,dead:false,charge:0,charging:false,paused:false};
try{G.best=parseInt(localStorage.getItem('sparkjump_best')||'0',10)||0;}catch(e){}
function reset(){
  G.score=0;G.perfects=0;G.plats=[];G.camY=0;G.time=0;G.dead=false;
  G.jumping=false;G.charging=false;G.charge=0;G.paused=false;pauseBtn.textContent='⏸️';
  const pw=Math.min(150,W*0.35);
  G.plats.push({x:W/2-pw/2,y:H*0.75,w:pw,moving:0,dir:1});
  let y=H*0.75;
  for(let i=0;i<8;i++){
    y-=130+Math.random()*60;
    spawnPlat(y,i);
  }
  const p=G.plats[0];
  G.px=p.x+p.w/2;G.py=p.y;
  updateHUD();
  document.getElementById('best').textContent='🏆 '+G.best;
}
function spawnPlat(y,idx){
  const shrink=Math.min(70,idx*4);
  const w=Math.max(70,Math.min(150,W*0.35)-shrink);
  const moving=idx>3&&Math.random()<0.4;
  G.plats.push({
    x:Math.random()*(W-w),y,w,
    moving:moving?(40+Math.random()*60):0,
    dir:Math.random()<0.5?-1:1,phase:Math.random()*6
  });
}
function updateHUD(){
  document.getElementById('score').textContent='⭐ '+G.score;
  document.getElementById('perfect').textContent=`✨ ${G.perfects} perfect`;
}
canvas.addEventListener('pointerdown',e=>{
  if(G.state!=='play'||G.dead||G.jumping)return;
  e.preventDefault();
  G.charging=true;G.charge=0;
  canvas.setPointerCapture(e.pointerId);
});
canvas.addEventListener('pointerup',()=>{
  if(!G.charging)return;
  G.charging=false;
  doJump();
});
addEventListener('keydown',e=>{
  if((e.code==='Space'||e.code==='ArrowUp')&&G.state==='play'&&!G.dead&&!G.jumping&&!e.repeat){
    e.preventDefault();G.charging=true;G.charge=0;}
});
addEventListener('keyup',e=>{
  if((e.code==='Space'||e.code==='ArrowUp')&&G.charging){G.charging=false;doJump();}
});
canvas.addEventListener('pointercancel',()=>{
  // BUGFIX: without this, a cancelled touch left G.charging stuck true
  // (charge pinned at max and a stale jump fired on the next pointerup).
  G.charging=false;G.charge=0;
});
function doJump(){
  if(G.jumping)return;
  G.jumping=true;
  // find next platform (the one above current)
  const cur=G.plats.find(p=>Math.abs(G.py-p.y)<30);
  const idx=G.plats.indexOf(cur);
  const next=G.plats[idx+1];
  if(!next){G.jumping=false;return;}
  // jump toward next platform center with charge-based power
  const power=0.75+G.charge*0.5; // charge 0-1
  const tx=next.x+next.w/2;
  const dx=tx-G.px;
  const dy=G.py-next.y;
  const T=Math.sqrt(2*dy/1800); // time to reach
  G.vx=dx/T*power;
  G.vy=-Math.sqrt(2*1800*dy)*Math.min(1.15,power+0.15);
  G.targetPlat=next;
  sfx.jump();
}
const particles=[];
for(let i=0;i<60;i++)particles.push({a:false});
// Living background: 24 rising ember motes (positions derived from G.time — cheap, no per-frame state)
const EMBERS=[];
for(let i=0;i<24;i++)EMBERS.push({x:Math.random(),o:Math.random()*1200,s:26+Math.random()*38,r:1.4+Math.random()*2.2,ph:Math.random()*6.28});
function update(dt){
  G.time+=dt;
  if(G.charging){G.charge=Math.min(1,G.charge+dt*1.8);}
  // moving platforms
  for(const p of G.plats){
    if(p.moving){
      p.phase+=dt*2;
      p.x+=Math.cos(p.phase)*p.moving*dt;
      p.x=Math.max(0,Math.min(W-p.w,p.x));
    }
  }
  if(G.jumping){
    G.vy+=1800*dt;
    G.px+=G.vx*dt;G.py+=G.vy*dt;
    const tp=G.targetPlat;
    // landed?
    if(G.vy>0&&tp&&G.py>=tp.y-8&&G.py<=tp.y+24&&G.px>tp.x-14&&G.px<tp.x+tp.w+14){
      G.jumping=false;G.py=tp.y;
      const center=tp.x+tp.w/2;
      const off=Math.abs(G.px-center);
      const perfectZone=tp.w*0.18;
      if(off<perfectZone){
        G.score+=3;G.perfects++;sfx.perfect();
        spawnText(G.px,G.py-40,'PERFECT +3','#4caf50');
        for(let i=0;i<10;i++){const pt=particles.find(pt=>!pt.a);if(!pt)break;
          pt.a=true;pt.x=G.px;pt.y=G.py;const a=Math.random()*Math.PI*2;
          pt.vx=Math.cos(a)*200;pt.vy=Math.sin(a)*200-80;
          pt.life=0.5;pt.max=0.5;pt.color='#4caf50';pt.size=4;}
      }else{
        G.score+=1;sfx.land();
        spawnText(G.px,G.py-40,'+1','#fff');
      }
      updateHUD();
      // camera + new platform
      const dy=G.camY;
      G.camY=tp.y-H*0.6;
      for(const p of G.plats)p.y+=(dy-G.camY);
      G.py=tp.y;
      // remove old, add new
      G.plats=G.plats.filter(p=>p.y<H+100);
      let topY=Math.min(...G.plats.map(p=>p.y));
      while(topY>-100){
        topY-=130+Math.random()*60;
        spawnPlat(topY,G.score);
      }
    }
    // fell
    if(G.py>H+60){
      G.dead=true;sfx.fall();
      const isBest=G.score>G.best;
      if(isBest){G.best=G.score;try{localStorage.setItem('sparkjump_best',String(G.best));}catch(e){}}
      setTimeout(()=>{
        showOverlay('💥 YOU FELL!',
          `${isBest?'<p style="color:#ffd23f;font-weight:900">🏆 NEW BEST!</p>':''}<p style="font-size:26px;font-weight:900">Score: ${G.score}</p><p>Perfect landings: ${G.perfects}</p><p>Best: ${G.best}</p>`,
          '🔥 Fire Safety: Perfect landings take practice!',
          '↻ JUMP AGAIN',()=>{reset();G.state='play';});
      },600);
    }
  }
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=400*dt;p.life-=dt;if(p.life<=0)p.a=false;}
}
const floaters=[];
for(let i=0;i<8;i++)floaters.push({a:false});
function spawnText(x,y,txt,color){
  const f=floaters.find(f=>!f.a);if(!f)return;
  f.a=true;f.x=x;f.y=y;f.txt=txt;f.color=color;f.life=1;
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();reset();G.state='play';overlay.classList.add('hidden');}
obtn.onclick=()=>{showMathGate();};
const muteBtn=document.getElementById('muteBtn'),pauseBtn=document.getElementById('pauseBtn');
muteBtn.onclick=()=>{muted=!muted;muteBtn.textContent=muted?'🔇':'🔊';};
function togglePause(){if(!(G.state==='play'))return;G.paused=!G.paused;pauseBtn.textContent=G.paused?'▶️':'⏸️';}
pauseBtn.onclick=togglePause;
addEventListener('keydown',e=>{if(e.code==='KeyP')togglePause();});

function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  const hue=(200+G.score*2)%360;
  bg.addColorStop(0,`hsl(${hue},30%,10%)`);bg.addColorStop(1,'#140d08');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  // living embers behind gameplay (additive glow)
  ctx.save();ctx.globalCompositeOperation='lighter';
  for(const e of EMBERS){
    const ey=H-((G.time*e.s+e.o)%(H+30));
    const ex=e.x*W+Math.sin(G.time*0.9+e.ph)*10;
    ctx.globalAlpha=0.16+0.12*Math.sin(G.time*2+e.ph);
    ctx.fillStyle='#ff9a3c';
    ctx.beginPath();ctx.arc(ex,ey,e.r,0,Math.PI*2);ctx.fill();
  }
  ctx.restore();ctx.globalAlpha=1;
  // platforms
  for(const p of G.plats){
    const g=ctx.createLinearGradient(0,p.y,0,p.y+18);
    g.addColorStop(0,'#6a4a8a');g.addColorStop(1,'#3a244a');
    ctx.fillStyle=g;
    ctx.beginPath();ctx.roundRect(p.x,p.y,p.w,18,9);ctx.fill();
    // perfect zone
    const pz=p.w*0.18*2;
    ctx.fillStyle='rgba(76,175,80,0.5)';
    ctx.fillRect(p.x+p.w/2-pz/2,p.y,pz,18);
    ctx.fillStyle='rgba(255,255,255,0.25)';
    ctx.fillRect(p.x+6,p.y+3,p.w-12,4);
  }
  // player
  if(!G.dead){
    const squash=G.jumping?Math.max(0.8,Math.min(1.2,1+G.vy/3000)):1;
    ctx.save();ctx.translate(G.px,G.py-14);ctx.scale(1/squash,squash);
    const g=ctx.createRadialGradient(-6,-7,3,0,0,18);
    g.addColorStop(0,'#ffe9a0');g.addColorStop(0.5,'#ff7a2a');g.addColorStop(1,'#d42a1a');
    ctx.fillStyle=g;
    ctx.shadowColor='#ff8c2e';ctx.shadowBlur=18; // hero glow halo
    ctx.beginPath();ctx.arc(0,0,16,0,Math.PI*2);ctx.fill();
    ctx.shadowBlur=0;
    ctx.fillStyle='#2b1a0e';
    ctx.beginPath();ctx.arc(-5,-3,3,0,Math.PI*2);ctx.arc(5,-3,3,0,Math.PI*2);ctx.fill();
    ctx.restore();
    // charge indicator
    if(G.charging){
      ctx.fillStyle='rgba(0,0,0,.4)';
      ctx.fillRect(G.px-30,G.py-58,60,8);
      ctx.fillStyle=G.charge>0.8?'#ff4a5a':'#ffd23f';
      ctx.fillRect(G.px-30,G.py-58,60*G.charge,8);
    }
    // trajectory preview while charging
    if(G.charging&&!G.jumping){
      const cur=G.plats.find(p=>Math.abs(G.py-p.y)<30);
      const next=G.plats[G.plats.indexOf(cur)+1];
      if(next){
        ctx.strokeStyle='rgba(255,255,255,0.35)';ctx.lineWidth=2;ctx.setLineDash([8,8]);
        ctx.beginPath();ctx.moveTo(G.px,G.py-14);
        ctx.quadraticCurveTo(G.px,G.py-120,next.x+next.w/2,next.y);
        ctx.stroke();ctx.setLineDash([]);
      }
    }
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  ctx.textAlign='center';
  for(const f of floaters){
    if(!f.a)continue;
    ctx.globalAlpha=Math.min(1,f.life);
    ctx.font='900 20px system-ui';ctx.fillStyle='#000';
    ctx.fillText(f.txt,f.x+2,f.y+2);ctx.fillStyle=f.color;ctx.fillText(f.txt,f.x,f.y);
  }
  ctx.globalAlpha=1;ctx.textAlign='left';
  if(G.paused){ctx.fillStyle='rgba(0,0,0,0.45)';ctx.fillRect(0,0,W,H);ctx.fillStyle='#fff';ctx.font='900 34px system-ui';ctx.textAlign='center';ctx.fillText('⏸️ PAUSED',W/2,H/2);ctx.textAlign='left';}
}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(G.state==='play'&&!G.dead&&!G.paused)update(dt);else G.time+=dt;
  // floaters tick on real dt here (was a fixed 0.016 step inside render() — framerate-coupled)
  for(const f of floaters){if(!f.a)continue;f.y-=30*dt;f.life-=dt;if(f.life<=0)f.a=false;}
  render();
  requestAnimationFrame(loop);
}
document.getElementById('best').textContent='🏆 '+G.best;
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Arcade Sparks' — Spark Jump Arcade's own
   track. Synthesized Web Audio only. 144 BPM, C major pentatonic: pure
   chiptune — a square arpeggio lead bouncing over an ostinato bass, straight
   off a 1986 arcade board.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Freeze gate CONFIRMED at insertion (2026-10-15): script-scope `muted` mutes, G.paused pauses, and music only
   plays while G.state==='play' — all read from this shell's own code.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-34-spark-jump-arcade.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
// Freeze gate (insertion-confirmed 2026-10-15): hard-wired to this shell's
// own confirmed globals — muted / G.paused / G.state. try/catch kept so it can never throw.
const _mGate=()=>{try{return !!(muted||G.paused||G.state!=='play');}catch(e){return false;}};
const MUS={on:false,step:0,nextT:0,BPM:144,
 BASS:[36,36,48,36,36,36,48,36, 41,41,53,41,41,41,53,41, 43,43,55,43,43,43,55,43, 45,45,57,45,45,45,57,45],
 LEAD:[72,76,79,84,79,76,72,76, 79,81,84,81,79,81,84,81, 79,84,88,84,79,84,88,84, 81,84,88,84,81,84,81,84],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(_mGate()){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.11,'square',0.05,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.1,'square',0.042,d);
  if(s%2===0)tone(122,45,0.1,'sine',0.13,d); // kick
  if(s%8===2||s%8===6)tone(190,120,0.07,'triangle',0.07,d); // tone-only snare
  if(s%2===1)tone(7000,7000,0.012,'square',0.006,d); // hat click
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

