@media (prefers-reduced-motion: reduce){#fb-seasonal-ambience{display:none}.fb-sb-bob{animation:none}}

scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR,CX,CY,MOAT_R,CASTLE_R;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);
  CX=W/2;CY=H/2;MOAT_R=Math.min(W,H)*0.32;CASTLE_R=Math.min(W,H)*0.09;}
addEventListener('resize',resize);
let AC=null,muted=false;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(muted)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
function noise(dur,vol,delay=0,lp=800){if(muted)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const len=ac.sampleRate*dur,buf=ac.createBuffer(1,len,ac.sampleRate),d=buf.getChannelData(0);
  for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);
  const s=ac.createBufferSource();s.buffer=buf;const f=ac.createBiquadFilter();f.type='lowpass';f.frequency.value=lp;
  const g=ac.createGain();g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  s.connect(f);f.connect(g);g.connect(ac.destination);s.start(t);}
const sfx={
  build(){tone(300,650,0.12,'triangle',0.12);},
  shoot(){tone(750,450,0.05,'square',0.045);},
  boom(){noise(0.18,0.22,0,500);},
  kill(){tone(500,850,0.08,'sine',0.08);},
  leak(){tone(320,110,0.25,'sawtooth',0.14);},
  wave(){tone(400,800,0.3,'triangle',0.14);},
  win(){[523,659,784,1047,1319].forEach((f,i)=>tone(f,f,0.2,'triangle',0.15,i*0.09));},
  click(){tone(600,600,0.06,'square',0.1);}
};
const G={state:'title',gold:200,wave:0,hp:100,score:0,
  towers:[],enemies:[],shots:[],spawnQ:[],betweenWaves:0,time:0,shake:0,nova:0,paused:false,speed:1,msg:'',msgT:0,rangeT:0,lastTower:null,selTower:null};
const NOVA_NEED=12,NOVA_DMG=45,NOVA_R=230;
// Living background embers (positions derived from G.time — cheap, stateless)
const EMBERS=[];
for(let i=0;i<24;i++)EMBERS.push({x:Math.random(),o:Math.random()*1200,s:24+Math.random()*36,r:1.4+Math.random()*2.2,ph:Math.random()*6.28});
function reset(){
  G.gold=200;G.wave=0;G.hp=100;G.score=0;
  G.towers=[];G.enemies=[];G.shots=[];
  // BUGFIX: spawnQ and shake were never cleared — leftover queued enemies
  // from the previous run leaked into the fresh game after a restart.
  G.spawnQ=[];G.shake=0;G.nova=0;G.paused=false;G.msg='';G.msgT=0;G.rangeT=0;G.lastTower=null;G.selTower=null;document.getElementById('tpanel').style.display='none';pauseBtn.textContent='⏸️';
  G.betweenWaves=1.5;G.time=0;
  updateHUD();
}
function updateHUD(){
  document.getElementById('gold').textContent='🪙 '+Math.floor(G.gold);
  document.getElementById('wave').textContent=`🌊 Wave ${Math.min(Math.max(G.wave,1),17)}/17`; // was wave+1: HUD showed Wave 2 during Wave 1
  document.getElementById('hp').textContent='🏰 '+G.hp;
}
// WEAPON — Ember Nova Blast: charged by 12 tower kills. When ready, tap the
// castle (or press Space/N) to deal 45 damage to every enemy within 230px of
// the castle. Base tower shot is 11 dmg, so this is a gated area finisher,
// not a stronger always-on weapon.
function novaBlast(){
  if(G.state!=='play'||G.nova<NOVA_NEED)return;
  G.nova=0;sfx.boom();tone(180,720,0.35,'sawtooth',0.16);G.shake=Math.max(G.shake,0.3);
  burst(CX,CY,'#ffb03a',24);
  for(const e of G.enemies){
    if(e.dead)continue;
    if(Math.hypot(e.x-CX,e.y-CY)<=NOVA_R){
      e.hp-=NOVA_DMG;e.hitT=0.15;burst(e.x,e.y,'#ffd23f',5);
      if(e.hp<=0){e.dead=true;G.gold+=e.gold;G.score+=e.gold*10;sfx.kill();}
    }
  }
  G.enemies=G.enemies.filter(e=>!e.dead);
  updateHUD();
}
addEventListener('keydown',e=>{
  if((e.code==='Space'||e.code==='KeyN')&&G.state==='play'){e.preventDefault();novaBlast();}
});
// --- Manual upgrade/sell economy (leftover-fix) ---
// Balance vs the game's own numbers: base tower 50g, 11 dmg / 0.45s ≈ 24 DPS,
// 170 range. Enemies pay 7-22g and gold also trickles at 1.2/s, waves run
// 7-29 enemies. Upgrade costs 40/80/120g (Lv2/3/4) buy +45% damage and +8
// range per level (Lv4 ≈ 2.35x damage, 194 range ≈ 57 DPS before the capped
// veteran bonus). One maxed tower costs 290g total — about six base towers'
// worth of damage concentrated in ONE ring slot, which is the point: ring
// slots are limited by the 52px spacing, so upgrades win late, raw towers
// win early. That keeps both choices live instead of one dominating.
// Sell refunds 70% of total invested (genre standard), so repositioning
// costs something but is never a trap. The old auto-level-by-kills is now a
// capped veteran bonus (+0.3 dmg/kill, max +6) — kills still matter, but
// damage no longer grows without bound or without the player deciding.
const UP_COSTS=[0,40,80,120]; // index = current level (Lv1->2 costs 40, ...)
const MAX_LVL=4;
function towerRange(t){return 170+((t.lvl||1)-1)*8;}
function towerDmg(t){return (11+Math.min((t.kills||0)*0.3,6))*(1+0.45*((t.lvl||1)-1));}
function sellRefund35(t){const inv=t.invested!=null?t.invested:50;return Math.floor(inv*0.7);}
const tpanel=document.getElementById('tpanel'),tpInfo=document.getElementById('tpInfo'),
      tpUp=document.getElementById('tpUp'),tpSell=document.getElementById('tpSell');
function refreshPanel(){
  const t=G.selTower;
  if(!t||!G.towers.includes(t)){tpanel.style.display='none';return;}
  tpanel.style.display='flex';
  tpInfo.textContent='🔥 Lv'+(t.lvl||1)+' · ⚔️ '+towerDmg(t).toFixed(0);
  tpUp.textContent=(t.lvl||1)>=MAX_LVL?'⭐ MAX':'⬆️ Upgrade '+UP_COSTS[t.lvl||1]+'🪙';
  tpSell.textContent='💰 Sell +'+sellRefund35(t)+'🪙';
}
function selectTower(t){G.selTower=t;G.lastTower=t;G.rangeT=1.4;refreshPanel();}
function deselectTower(){G.selTower=null;tpanel.style.display='none';}
tpUp.addEventListener('click',e=>{
  e.stopPropagation();const t=G.selTower;if(!t)return;
  if((t.lvl||1)>=MAX_LVL){G.msg='⭐ That tower is max level (Lv'+MAX_LVL+')';G.msgT=1.6;return;}
  const cost=UP_COSTS[t.lvl||1];
  if(G.gold<cost){sfx.click();G.msg='🪙 Upgrade needs '+cost+' gold!';G.msgT=1.6;return;}
  G.gold-=cost;t.invested=(t.invested!=null?t.invested:50)+cost;t.lvl=(t.lvl||1)+1;
  sfx.build();updateHUD();G.rangeT=1.4;G.lastTower=t;refreshPanel();
  G.msg='⬆️ Tower upgraded to Lv'+t.lvl+'!';G.msgT=1.6;
});
tpSell.addEventListener('click',e=>{
  e.stopPropagation();const t=G.selTower;if(!t)return;
  const refund=sellRefund35(t);
  G.towers=G.towers.filter(x=>x!==t);G.gold+=refund;
  if(G.lastTower===t)G.lastTower=null;
  deselectTower();sfx.build();tone(900,1400,0.12,'triangle',0.1);burst(t.x,t.y,'#ffd23f',10);updateHUD();
  G.msg='💰 Tower sold! +🪙 '+refund;G.msgT=1.6;
});
document.getElementById('tpClose').addEventListener('click',e=>{e.stopPropagation();deselectTower();});
canvas.addEventListener('pointerdown',e=>{
  if(G.state!=='play')return;
  const rect=canvas.getBoundingClientRect();
  const x=e.clientX-rect.left,y=e.clientY-rect.top;
  const d=Math.hypot(x-CX,y-CY);
  // tapping the castle fires the Nova when charged (castle is not on the build ring)
  if(d<CASTLE_R+30&&G.nova>=NOVA_NEED){novaBlast();return;}
  if(d<CASTLE_R+30&&G.nova<NOVA_NEED){G.msg=`🔆 Nova needs ${NOVA_NEED-G.nova} more kills!`;G.msgT=1.6;return;}
  // tapping a placed tower selects it (upgrade / sell panel) — before any build logic
  for(const t of G.towers){
    if(Math.hypot(t.x-x,t.y-y)<44){selectTower(t);sfx.click();return;}
  }
  // must be near moat ring
  if(Math.abs(d-MOAT_R)>44){deselectTower();G.msg='👆 Tap ON the glowing ring to build!';G.msgT=1.6;return;}
  if(G.gold<50){sfx.click();G.msg='🪙 Need 50 gold for a tower!';G.msgT=1.6;return;}
  // check overlap
  for(const t of G.towers){
    const td=Math.hypot(t.x-x,t.y-y);
    if(td<52){G.msg='Too close to another tower!';G.msgT=1.4;return;}
  }
  deselectTower();
  G.gold-=50;sfx.build();updateHUD();
  // snap to ring
  const a=Math.atan2(y-CY,x-CX);
  const nt={x:CX+Math.cos(a)*MOAT_R,y:CY+Math.sin(a)*MOAT_R,a,cd:0,aim:0,kills:0,lvl:1,invested:50};
  G.towers.push(nt);G.lastTower=nt;G.rangeT=1.4; // flash the new tower's range so players learn its reach
});
function startWave(n){
  G.wave=n;sfx.wave();
  const count=5+n*2;
  const comp=[];
  for(let i=0;i<count;i++){
    const r=Math.random();
    let type='grunt';
    if(n>=5&&r<0.2)type='tank';
    else if(n>=3&&r<0.42)type='fast';
    else if(n>=7&&r<0.52)type='splitter';
    comp.push(type);
  }
  G.spawnQ=comp.map((t,i)=>({type:t,delay:i*(0.8-Math.min(0.45,n*0.03))}));
  updateHUD();
}
function spawnEnemy(type){
  const a=Math.random()*Math.PI*2;
  const R=Math.max(W,H)*0.62;
  const base={x:CX+Math.cos(a)*R,y:CY+Math.sin(a)*R,a,t:Math.random()*10,hitT:0};
  if(type==='grunt')Object.assign(base,{type,hp:26+G.wave*7,r:14,speed:48+G.wave*2.5,gold:7});
  else if(type==='fast')Object.assign(base,{type,hp:16+G.wave*4,r:11,speed:95+G.wave*3,gold:9});
  else if(type==='tank')Object.assign(base,{type:'tank',hp:80+G.wave*18,r:22,speed:32+G.wave*1.5,gold:22});
  else Object.assign(base,{type:'splitter',hp:34+G.wave*8,r:16,speed:55+G.wave*2,gold:12});
  base.maxhp=base.hp;G.enemies.push(base);
}
const particles=[];
for(let i=0;i<120;i++)particles.push({a:false});
function burst(x,y,color,n=7){
  for(let i=0;i<n;i++){const p=particles.find(p=>!p.a);if(!p)break;
    const a=Math.random()*Math.PI*2;
    p.a=true;p.x=x;p.y=y;p.vx=Math.cos(a)*200;p.vy=Math.sin(a)*200;
    p.life=0.4;p.max=0.4;p.color=color;p.size=3+Math.random()*3;}
}
function update(dt){
  G.time+=dt;G.shake=Math.max(0,G.shake-dt*3);G.msgT=Math.max(0,G.msgT-dt);G.rangeT=Math.max(0,G.rangeT-dt);
  if(!G.spawnQ.length&&!G.enemies.length&&G.state==='play'){
    if(G.wave>=17){victory();return;}
    G.betweenWaves-=dt;
    if(G.betweenWaves<=0){startWave(G.wave+1);G.betweenWaves=5;}
  }
  for(const q of G.spawnQ)q.delay-=dt;
  while(G.spawnQ.length&&G.spawnQ[0].delay<=0)spawnEnemy(G.spawnQ.shift().type);
  // towers
  for(const t of G.towers){
    t.cd-=dt;
    if(t.cd>0)continue;
    let best=null,bd=1e9;
    for(const e of G.enemies){
      const d=Math.hypot(e.x-t.x,e.y-t.y);
      if(d<towerRange(t)){
        const cd=Math.hypot(e.x-CX,e.y-CY);
        if(cd<bd){bd=cd;best=e;}
      }
    }
    if(best){
      t.cd=0.45;t.aim=Math.atan2(best.y-t.y,best.x-t.x);
      G.shots.push({x:t.x,y:t.y,target:best,speed:520,dmg:towerDmg(t),src:t});
      sfx.shoot();
    }
  }
  // shots
  for(const s of G.shots){
    if(s.target.dead){s.dead=true;continue;}
    const dx=s.target.x-s.x,dy=s.target.y-s.y,d=Math.hypot(dx,dy);
    const step=s.speed*dt;
    if(d<step+8){
      s.dead=true;const e=s.target;
      e.hp-=s.dmg;e.hitT=0.1;
      burst(s.x,s.y,'#ffd23f',4);
      if(e.hp<=0&&!e.dead){
        e.dead=true;G.gold+=e.gold;G.score+=e.gold*10;
        sfx.kill();burst(e.x,e.y,'#8a6a4a',10);
        // splitter spawns 2 grunts
        if(e.type==='splitter'){
          for(let i=0;i<2;i++){
            G.enemies.push({x:e.x+(Math.random()-0.5)*30,y:e.y+(Math.random()-0.5)*30,
              type:'grunt',hp:20+G.wave*5,maxhp:20+G.wave*5,r:11,speed:70+G.wave*2,gold:5,t:0,hitT:0,a:0});
          }
        }
        // BUGFIX: previously EVERY tower within 170px of a kill got credit,
        // levelling up towers that never fired. Only the shooter levels up.
        if(s.src)s.src.kills++;
        // Ember Nova charge: every tower kill feeds the Nova meter
        G.nova=Math.min(NOVA_NEED,G.nova+1);
        updateHUD();
      }
    }else{s.x+=dx/d*step;s.y+=dy/d*step;}
  }
  G.shots=G.shots.filter(s=>!s.dead);
  // enemies march to center
  for(const e of G.enemies){
    if(e.dead)continue;
    e.t+=dt;e.hitT=Math.max(0,e.hitT-dt);
    const dx=CX-e.x,dy=CY-e.y,d=Math.hypot(dx,dy);
    if(d>0.01){e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt;} // guard: d==0 would NaN-poison the position
    if(d<CASTLE_R+10){
      e.dead=true;
      const dmg=e.type==='tank'?15:8;
      G.hp-=dmg;sfx.leak();G.shake=0.4;updateHUD();
      burst(CX,CY,'#ff4a5a',12);
      if(G.hp<=0){defeat();return;}
    }
  }
  G.enemies=G.enemies.filter(e=>!e.dead);
  G.gold+=dt*1.2;
  if(Math.random()<0.05)updateHUD();
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)p.a=false;}
}
function victory(){
  G.state='over';sfx.win();
  setTimeout(()=>{
    showOverlay('🏆 VICTORY!',
      `<p style="font-size:24px;font-weight:900">Score: ${G.score}</p><p>All 17 waves repelled! The castle stands strong!</p>`,
      '🔥 Fire Safety: You\'re a champion!',
      '↻ PLAY AGAIN',()=>{reset();G.state='play';});
  },600);
}
function defeat(){
  G.state='over';
  setTimeout(()=>{
    showOverlay('💥 CASTLE BREACHED',
      `<p>Wave reached: ${G.wave}/17</p><p>Score: ${G.score}</p>`,
      '🔥 Fire Safety: Protect your home!',
      '↻ TRY AGAIN',()=>{reset();G.state='play';});
  },600);
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();resize();reset();G.state='play';overlay.classList.add('hidden');}
obtn.onclick=()=>{showMathGate();};
const muteBtn=document.getElementById('muteBtn'),pauseBtn=document.getElementById('pauseBtn');
muteBtn.onclick=()=>{muted=!muted;muteBtn.textContent=muted?'🔇':'🔊';};
function togglePause(){if(!(G.state==='play'))return;G.paused=!G.paused;pauseBtn.textContent=G.paused?'▶️':'⏸️';}
pauseBtn.onclick=togglePause;
addEventListener('keydown',e=>{if(e.code==='KeyP')togglePause();});

const ffBtn=document.getElementById('ffBtn');
ffBtn.onclick=()=>{G.speed=G.speed===1?2:1;ffBtn.textContent=G.speed===2?'⏩2x':'⏩';ffBtn.style.background=G.speed===2?'rgba(255,170,40,.6)':'rgba(0,0,0,.55)';};

function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#17100c');bg.addColorStop(0.55,'#0d0a08');bg.addColorStop(1,'#1c0d06');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  // living embers behind gameplay (additive glow)
  ctx.save();ctx.globalCompositeOperation='lighter';
  for(const e of EMBERS){
    const ey=H-((G.time*e.s+e.o)%(H+30));
    const ex=e.x*W+Math.sin(G.time*0.9+e.ph)*10;
    ctx.globalAlpha=0.15+0.11*Math.sin(G.time*2+e.ph);
    ctx.fillStyle='#ff9a3c';
    ctx.beginPath();ctx.arc(ex,ey,e.r,0,Math.PI*2);ctx.fill();
  }
  ctx.restore();ctx.globalAlpha=1;
  ctx.save();
  if(G.shake>0)ctx.translate((Math.random()-0.5)*G.shake*12,(Math.random()-0.5)*G.shake*12);
  // lava moat ring
  const lg=ctx.createRadialGradient(CX,CY,MOAT_R-30,CX,CY,MOAT_R+30);
  lg.addColorStop(0,'rgba(255,106,0,0)');lg.addColorStop(0.5,'rgba(255,106,0,0.35)');lg.addColorStop(1,'rgba(255,106,0,0)');
  ctx.fillStyle=lg;
  ctx.beginPath();ctx.arc(CX,CY,MOAT_R+44,0,Math.PI*2);ctx.arc(CX,CY,MOAT_R-44,0,Math.PI*2,true);ctx.fill();
  // moat bubbles
  for(let i=0;i<16;i++){
    const a=i/16*Math.PI*2+G.time*0.4;
    const bx=CX+Math.cos(a)*MOAT_R,by=CY+Math.sin(a)*MOAT_R;
    ctx.fillStyle='rgba(255,221,68,0.7)';
    ctx.beginPath();ctx.arc(bx,by,3+Math.sin(G.time*5+i)*1.5,0,Math.PI*2);ctx.fill();
  }
  // build hint ring
  if(G.state==='play'){
    ctx.strokeStyle='rgba(255,210,63,0.25)';ctx.lineWidth=3;ctx.setLineDash([16,12]);
    ctx.beginPath();ctx.arc(CX,CY,MOAT_R,0,Math.PI*2);ctx.stroke();
    ctx.setLineDash([]);
  }
  // castle
  const cg=ctx.createRadialGradient(CX-10,CY-10,5,CX,CY,CASTLE_R+20);
  cg.addColorStop(0,'#8a7aaa');cg.addColorStop(1,'#3a2a4a');
  ctx.fillStyle=cg;ctx.beginPath();ctx.arc(CX,CY,CASTLE_R,0,Math.PI*2);ctx.fill();
  ctx.font=`${CASTLE_R}px system-ui`;ctx.textAlign='center';
  ctx.fillText('🏰',CX,CY+CASTLE_R*0.35);ctx.textAlign='left';
  // hp ring
  ctx.strokeStyle=G.hp>50?'#4caf50':G.hp>25?'#ffd23f':'#ff4a5a';
  ctx.lineWidth=6;
  ctx.beginPath();ctx.arc(CX,CY,CASTLE_R+12,-Math.PI/2,-Math.PI/2+Math.PI*2*G.hp/100);ctx.stroke();
  // tower range preview: faint reach ring per tower, bright ring on the newest
  for(const t of G.towers){
    ctx.strokeStyle='rgba(255,210,63,0.07)';ctx.lineWidth=2;
    ctx.beginPath();ctx.arc(t.x,t.y,towerRange(t),0,Math.PI*2);ctx.stroke();
  }
  if(G.lastTower&&G.rangeT>0){
    ctx.strokeStyle=`rgba(255,210,63,${0.45*G.rangeT/1.4})`;ctx.lineWidth=3;
    ctx.beginPath();ctx.arc(G.lastTower.x,G.lastTower.y,towerRange(G.lastTower),0,Math.PI*2);ctx.stroke();
  }
  if(G.selTower&&G.towers.includes(G.selTower)){
    ctx.strokeStyle='rgba(255,210,63,0.55)';ctx.lineWidth=3;
    ctx.beginPath();ctx.arc(G.selTower.x,G.selTower.y,towerRange(G.selTower),0,Math.PI*2);ctx.stroke();
    ctx.strokeStyle='#ffd23f';ctx.lineWidth=3;
    ctx.beginPath();ctx.arc(G.selTower.x,G.selTower.y,26,0,Math.PI*2);ctx.stroke();
  }
  // towers
  for(const t of G.towers){
    ctx.fillStyle='#4a3a2a';
    ctx.beginPath();ctx.arc(t.x,t.y,18,0,Math.PI*2);ctx.fill();
    const lvl=t.lvl||1; // manual upgrade level (was auto-by-kills; kills now feed the capped veteran damage bonus)
    const g=ctx.createRadialGradient(t.x-5,t.y-11,2,t.x,t.y-6,14);
    g.addColorStop(0,'#ffe9a0');g.addColorStop(1,'#ff6a1a');
    ctx.fillStyle=g;
    ctx.shadowColor='#ff8c2e';ctx.shadowBlur=14; // tower flame glow
    ctx.beginPath();ctx.arc(t.x,t.y-6,12+lvl*2,0,Math.PI*2);ctx.fill();
    ctx.shadowBlur=0;
    // barrel
    ctx.strokeStyle='#ffd23f';ctx.lineWidth=4+lvl;ctx.lineCap='round';
    ctx.beginPath();ctx.moveTo(t.x,t.y-6);
    ctx.lineTo(t.x+Math.cos(t.aim)*20,t.y-6+Math.sin(t.aim)*20);ctx.stroke();
    if(lvl>1){
      ctx.fillStyle='#ffd23f';ctx.font='900 11px system-ui';ctx.textAlign='center';
      ctx.fillText('★'.repeat(lvl),t.x,t.y+22);ctx.textAlign='left';
    }
  }
  // enemies
  for(const e of G.enemies){
    ctx.save();ctx.translate(e.x,e.y);
    const flash=e.hitT>0;
    const g=ctx.createRadialGradient(-4,-4,2,0,0,e.r);
    if(e.type==='tank'){g.addColorStop(0,flash?'#fff':'#5a4a5a');g.addColorStop(1,'#2a1a2a');}
    else if(e.type==='fast'){g.addColorStop(0,flash?'#fff':'#8a7a5a');g.addColorStop(1,'#3a2a1a');}
    else if(e.type==='splitter'){g.addColorStop(0,flash?'#fff':'#7a5aaa');g.addColorStop(1,'#2a1a3a');}
    else{g.addColorStop(0,flash?'#fff':'#7a6a6a');g.addColorStop(1,'#333');}
    ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,e.r,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#ff4a00';
    ctx.beginPath();ctx.arc(-e.r*0.3,-2,3,0,Math.PI*2);ctx.arc(e.r*0.3,-2,3,0,Math.PI*2);ctx.fill();
    ctx.restore();
    // enemy HP bar (genre standard — shows tank damage progress)
    if(e.maxhp&&e.hp<e.maxhp){
      ctx.fillStyle='rgba(0,0,0,0.6)';ctx.fillRect(e.x-e.r,e.y-e.r-10,e.r*2,5);
      ctx.fillStyle=e.hp/e.maxhp>0.4?'#4caf50':'#ff4a5a';
      ctx.fillRect(e.x-e.r,e.y-e.r-10,e.r*2*Math.max(0,e.hp/e.maxhp),5);
    }
  }
  // shots (projectile glow)
  ctx.save();ctx.shadowColor='#ffd23f';ctx.shadowBlur=10;
  for(const s of G.shots){
    ctx.fillStyle='#ffd23f';
    ctx.beginPath();ctx.arc(s.x,s.y,4,0,Math.PI*2);ctx.fill();
  }
  ctx.restore();
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  ctx.restore();
  // Ember Nova status
  if(G.state==='play'){
    ctx.font='900 14px system-ui';ctx.textAlign='center';
    if(G.nova>=NOVA_NEED){
      ctx.fillStyle='#ffb03a';
      ctx.fillText('🔆 EMBER NOVA READY! Tap the castle or press SPACE!',W/2,H-18);
    }else{
      ctx.fillStyle='rgba(255,255,255,0.55)';
      ctx.fillText(`🔆 Nova charge: ${G.nova}/${NOVA_NEED} kills`,W/2,H-34);
    }
    ctx.textAlign='left';
  }
  if(G.msgT>0&&G.state==='play'){
    ctx.fillStyle='#ffd23f';ctx.font='900 19px system-ui';ctx.textAlign='center';
    ctx.fillText(G.msg,W/2,64);ctx.textAlign='left';
  }
  if(G.state==='play'&&!G.spawnQ.length&&!G.enemies.length&&G.wave<17){
    ctx.fillStyle='#fff';ctx.font='900 17px system-ui';ctx.textAlign='center';
    ctx.fillText(`Wave ${G.wave+1} in ${Math.ceil(G.betweenWaves)}...  TAP the ring to build! (50🪙)`,W/2,90);
    ctx.textAlign='left';
  }
  if(G.paused){ctx.fillStyle='rgba(0,0,0,0.45)';ctx.fillRect(0,0,W,H);ctx.fillStyle='#fff';ctx.font='900 34px system-ui';ctx.textAlign='center';ctx.fillText('⏸️ PAUSED',W/2,H/2);ctx.textAlign='left';}
}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(G.state==='play'&&!G.paused)update(dt*G.speed);else G.time+=dt;
  render();
  requestAnimationFrame(loop);
}
resize();
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Moat Patrol' — Lava Moat Defense's own
   track. Synthesized Web Audio only. 104 BPM, C minor: a marching square
   lead over moat pads (Cm-Ab-Eb-Bb) with a snare-roll flourish at the end of
   every loop.
   Freeze gate CONFIRMED at insertion (2026-10-15): script-scope `muted` mutes, G.paused pauses, and music only
   plays while G.state==='play' — all read from this shell's own code.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-35-lava-moat-defense.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
// Freeze gate (insertion-confirmed 2026-10-15): hard-wired to this shell's
// own confirmed globals — muted / G.paused / G.state. try/catch kept so it can never throw.
const _mGate=()=>{try{return !!(muted||G.paused||G.state!=='play');}catch(e){return false;}};
const MUS={on:false,step:0,nextT:0,BPM:104,
 BASS:[36,0,48,0,36,0,48,0, 44,0,56,0,44,0,56,0, 39,0,51,0,39,0,51,0, 34,0,46,0,34,0,43,0],
 LEAD:[60,0,63,0,67,0,63,0, 68,0,67,0,63,0,60,0, 63,0,67,0,70,0,67,0, 65,0,63,0,60,0,0,0],
 PAD:[36,44,39,34],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(_mGate()){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  if(s%8===0){const p=this.PAD[s>>3];if(p){tone(_mf(p),_mf(p),1.6,'sawtooth',0.016,d);tone(_mf(p)*1.006,_mf(p)*1.006,1.6,'sawtooth',0.016,d);tone(_mf(p+7),_mf(p+7),1.6,'triangle',0.02,d);}} // pad chord
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.15,'square',0.055,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.18,'square',0.05,d);
  if(s%8===0||s%8===4)tone(118,45,0.11,'sine',0.13,d); // marching kick
  if(s%8===2||s%8===6)noise(0.08,0.08,d,1800); // snare
  if(s===30||s===31)noise(0.05,0.07,d,1800); // snare-roll flourish
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

/* fb-cycle2: in-play restart — the cluster button runs the game's own overlay reset path. */
(function(){var b=document.getElementById('restartBtn');if(!b)return;b.addEventListener('click',function(e){e.stopPropagation();if(typeof G==='undefined'||G.state!=='play')return;reset();G.state='play';});})();
(function(){function kev(type,key,code){var ev=new KeyboardEvent(type,{key:key,code:code||'',bubbles:true,cancelable:true});(document.body||window).dispatchEvent(ev);}function bind(el){var key=el.getAttribute('data-k'),code=el.getAttribute('data-c');var dn=function(e){e.preventDefault();e.stopPropagation();el.classList.add('on');try{el.setPointerCapture(e.pointerId);}catch(_){} kev('keydown',key,code);};var up=function(e){if(!el.classList.contains('on'))return;el.classList.remove('on');kev('keyup',key,code);};el.addEventListener('pointerdown',dn);el.addEventListener('pointerup',up);el.addEventListener('pointercancel',up);el.addEventListener('lostpointercapture',up);el.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();});el.addEventListener('contextmenu',function(e){e.preventDefault();});}document.querySelectorAll('#fbCtl .fbtn').forEach(bind);})();

