scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);buildBoard();}
addEventListener('resize',resize);
let AC=null,muted=false;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(muted)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  drop(){tone(500,300,0.1,'sine',0.09);},
  peg(n){const f=Math.min(1500,480+(n||0)*45);tone(f,f*1.35,0.05,'triangle',0.07);}, // pitch climbs with the peg chain (Peggle-style audio feedback)
  bumper(){tone(400,900,0.12,'square',0.12);},
  slot(){tone(700,1400,0.2,'triangle',0.14);},
  jackpot(){[523,659,784,1047,1319,1568].forEach((f,i)=>tone(f,f,0.18,'triangle',0.13,i*0.08));},
  click(){tone(600,600,0.06,'square',0.1);}
};
// board layout
let PEGS=[],BUMPERS=[],SLOTS=[];
const MULTS=[0.5,1,2,5,10,5,2,1,0.5];
function buildBoard(){
  PEGS=[];BUMPERS=[];SLOTS=[];
  const topY=H*0.18,botY=H*0.78;
  const rows=8;
  for(let r=0;r<rows;r++){
    const y=topY+r*(botY-topY)/rows;
    const n=6+(r%2);
    for(let i=0;i<n;i++){
      const x=W*(0.08+0.84*i/(n-1))+(r%2?W*0.04:0);
      PEGS.push({x:Math.min(W*0.94,Math.max(W*0.06,x)),y,r:7,hit:0});
    }
  }
  // bumpers
  BUMPERS=[
    {x:W*0.3,y:H*0.42,r:22,hit:0},
    {x:W*0.7,y:H*0.42,r:22,hit:0},
    {x:W*0.5,y:H*0.55,r:22,hit:0},
  ];
  // slots
  const n=MULTS.length;
  for(let i=0;i<n;i++){
    SLOTS.push({x:W*(i+0.5)/n,w:W/n,mult:MULTS[i]});
  }
}
const G={state:'title',score:0,best:0,balls:10,
  ball:null,aimX:0,time:0,shake:0,combo:0,paused:false};
try{G.best=parseInt(localStorage.getItem('drop_best')||'0',10)||0;}catch(e){}
function reset(){
  G.score=0;G.balls=10;G.ball=null;G.combo=0;G.time=0;G.shake=0;G.paused=false;pauseBtn.textContent='⏸️';
  updateHUD();
  document.getElementById('best').textContent='🏆 '+G.best;
}
function updateHUD(){
  document.getElementById('score').textContent='⭐ '+G.score;
  document.getElementById('balls').textContent='🔮 '+G.balls;
}
canvas.addEventListener('pointerdown',e=>{
  if(G.state!=='play'||G.ball||G.balls<=0)return;
  const rect=canvas.getBoundingClientRect();
  G.aimX=Math.max(30,Math.min(W-30,e.clientX-rect.left));
  G.balls--;G.combo=0;
  G.ball={x:G.aimX,y:H*0.1,vx:(Math.random()-0.5)*40,vy:60,r:13,pegHits:0,age:0};
  sfx.drop();updateHUD();
});
canvas.addEventListener('pointermove',e=>{
  if(G.ball)return;
  const rect=canvas.getBoundingClientRect();
  G.aimX=Math.max(30,Math.min(W-30,e.clientX-rect.left));
});
const particles=[],floaters=[];
for(let i=0;i<100;i++)particles.push({a:false});
// Living background embers (positions derived from G.time — cheap, stateless)
const EMBERS=[];
for(let i=0;i<24;i++)EMBERS.push({x:Math.random(),o:Math.random()*1200,s:24+Math.random()*36,r:1.4+Math.random()*2.2,ph:Math.random()*6.28});
for(let i=0;i<10;i++)floaters.push({a:false});
function burst(x,y,color,n=8){
  for(let i=0;i<n;i++){const p=particles.find(p=>!p.a);if(!p)break;
    const a=Math.random()*Math.PI*2;
    p.a=true;p.x=x;p.y=y;p.vx=Math.cos(a)*200;p.vy=Math.sin(a)*200;
    p.life=0.4;p.max=0.4;p.color=color;p.size=3+Math.random()*3;}
}
function spawnText(x,y,txt,color){
  const f=floaters.find(f=>!f.a);if(!f)return;
  f.a=true;f.x=x;f.y=y;f.txt=txt;f.color=color;f.life=1.2;
}
function update(dt){
  G.time+=dt;G.shake=Math.max(0,G.shake-dt*3);
  // BUGFIX: particles/floaters used to update only at the END of update(),
  // after the early return below — so bursts and score popups froze in
  // mid-air whenever no ball was in flight. They now tick first, always.
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=400*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  for(const f of floaters){if(!f.a)continue;f.y-=36*dt;f.life-=dt;if(f.life<=0)f.a=false;}
  const b=G.ball;
  if(!b){
    if(G.balls<=0&&G.state==='play')gameOver();
    return;
  }
  b.vy+=1500*dt;b.vy=Math.min(b.vy,900);
  b.age=(b.age||0)+dt;
  if(b.age>10){b.vx+=(Math.random()-0.5)*320;b.vy=Math.max(b.vy,320);b.age=6;} // anti-stall nudge: never let a balanced ball freeze the turn
  b.x+=b.vx*dt;b.y+=b.vy*dt;
  // walls
  if(b.x<b.r){b.x=b.r;b.vx=Math.abs(b.vx)*0.8;}
  if(b.x>W-b.r){b.x=W-b.r;b.vx=-Math.abs(b.vx)*0.8;}
  // pegs
  for(const p of PEGS){
    const dx=b.x-p.x,dy=b.y-p.y,d=Math.hypot(dx,dy);
    if(d<b.r+p.r){
      const nx=dx/d||0,ny=dy/d||-1;
      b.x=p.x+nx*(b.r+p.r);b.y=p.y+ny*(b.r+p.r);
      const vn=b.vx*nx+b.vy*ny;
      if(vn<0){
        b.vx-=1.85*vn*nx;b.vy-=1.85*vn*ny;
        b.vx+=(Math.random()-0.5)*60;
        b.pegHits++;G.combo++;
        p.hit=1;sfx.peg(G.combo);
        if(b.pegHits%10===0){
          G.score+=b.pegHits;spawnText(b.x,b.y-20,`+${b.pegHits} PEGS!`,'#7fd4ff');
        }
      }
    }
    p.hit=Math.max(0,p.hit-dt*4);
  }
  // bumpers
  for(const bp of BUMPERS){
    const dx=b.x-bp.x,dy=b.y-bp.y,d=Math.hypot(dx,dy);
    if(d<b.r+bp.r){
      const nx=dx/d||0,ny=dy/d||-1;
      b.x=bp.x+nx*(b.r+bp.r);b.y=bp.y+ny*(b.r+bp.r);
      const sp=Math.hypot(b.vx,b.vy);
      b.vx=nx*Math.max(sp*1.2,420);b.vy=ny*Math.max(sp*1.2,420);
      bp.hit=1;sfx.bumper();G.shake=Math.max(G.shake,0.15);
      G.score+=25;spawnText(b.x,b.y-24,'+25','#ffd23f');
      burst(b.x,b.y,'#ffd23f',8);
      updateHUD();
    }
    bp.hit=Math.max(0,bp.hit-dt*3);
  }
  // slots
  const slotY=H*0.82;
  if(b.y>slotY){
    let slot=SLOTS[0];
    for(const s of SLOTS)if(b.x>s.x-s.w/2&&b.x<s.x+s.w/2)slot=s;
    const pts=Math.round(100*slot.mult*(1+G.combo*0.02));
    G.score+=pts;
    if(slot.mult>=10){sfx.jackpot();G.shake=0.4;spawnText(b.x,slotY-40,'🎰 JACKPOT +'+pts,'#ffd23f');}
    else{sfx.slot();spawnText(b.x,slotY-40,'+'+pts+' x'+slot.mult,'#fff');}
    burst(b.x,slotY,'#ffd23f',12);
    G.ball=null;updateHUD();
  }
}
function gameOver(){
  G.state='over';
  const isBest=G.score>G.best;
  if(isBest){G.best=G.score;try{localStorage.setItem('drop_best',String(G.best));}catch(e){}}
  setTimeout(()=>{
    showOverlay('🔮 GAME OVER',
      `${isBest?'<p style="color:#ffd23f;font-weight:900">🏆 NEW BEST!</p>':''}<p style="font-size:26px;font-weight:900">Score: ${G.score}</p><p>Best: ${G.best}</p>`,
      '🔥 Fire Safety: What goes up must come down!',
      '↻ DROP AGAIN',()=>{reset();G.state='play';});
  },500);
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();reset();G.state='play';overlay.classList.add('hidden');}
obtn.onclick=()=>{showMathGate();};
const muteBtn=document.getElementById('muteBtn'),pauseBtn=document.getElementById('pauseBtn');
muteBtn.onclick=()=>{muted=!muted;muteBtn.textContent=muted?'🔇':'🔊';};
function togglePause(){if(!(G.state==='play'))return;G.paused=!G.paused;pauseBtn.textContent=G.paused?'▶️':'⏸️';}
pauseBtn.onclick=togglePause;
/* [w5b] restart control (site standard pause/mute/restart) — wired to the same
   reset path the game-over DROP AGAIN button uses: reset() + state='play'
   (reset() also clears the paused flag and restores the pause label) */
const restartBtn=document.getElementById('restartBtn');
restartBtn.onclick=()=>{if(G.state==='title')return;reset();G.state='play';overlay.classList.add('hidden');};
addEventListener('keydown',e=>{if(e.code==='KeyP')togglePause();});

function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#140d08');bg.addColorStop(1,'#1e1006');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  // living embers behind the board (additive glow)
  ctx.save();ctx.globalCompositeOperation='lighter';
  for(const e of EMBERS){
    const ey=H-((G.time*e.s+e.o)%(H+30));
    const ex=e.x*W+Math.sin(G.time*0.9+e.ph)*10;
    ctx.globalAlpha=0.15+0.11*Math.sin(G.time*2+e.ph);
    ctx.fillStyle='#ff9a3c';
    ctx.beginPath();ctx.arc(ex,ey,e.r,0,Math.PI*2);ctx.fill();
  }
  ctx.restore();ctx.globalAlpha=1;
  ctx.save();
  if(G.shake>0)ctx.translate((Math.random()-0.5)*G.shake*12,(Math.random()-0.5)*G.shake*12);
  // drop zone
  ctx.fillStyle='rgba(255,255,255,0.05)';
  ctx.fillRect(0,0,W,H*0.12);
  ctx.strokeStyle='rgba(255,210,63,0.4)';ctx.lineWidth=2;ctx.setLineDash([10,8]);
  ctx.beginPath();ctx.moveTo(20,H*0.12);ctx.lineTo(W-20,H*0.12);ctx.stroke();
  ctx.setLineDash([]);
  // aim indicator
  if(!G.ball&&G.balls>0&&G.state==='play'){
    const ax=G.aimX||W/2;
    ctx.strokeStyle='rgba(255,210,63,0.5)';ctx.lineWidth=3;ctx.setLineDash([8,8]);
    ctx.beginPath();ctx.moveTo(ax,H*0.05);ctx.lineTo(ax,H*0.16);ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle='#ffd23f';ctx.font='900 15px system-ui';ctx.textAlign='center';
    ctx.fillText('👆 TAP TO DROP',ax,H*0.05);ctx.textAlign='left';
  }
  // pegs
  for(const p of PEGS){
    ctx.fillStyle=p.hit>0?'#ffd23f':'#8a7a6a';
    ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='rgba(255,255,255,0.4)';
    ctx.beginPath();ctx.arc(p.x-2,p.y-2,2.5,0,Math.PI*2);ctx.fill();
  }
  // bumpers
  for(const bp of BUMPERS){
    const pulse=1+bp.hit*0.3;
    ctx.save();ctx.translate(bp.x,bp.y);ctx.scale(pulse,pulse);
    const g=ctx.createRadialGradient(-6,-6,3,0,0,bp.r);
    g.addColorStop(0,'#fff');g.addColorStop(0.4,'#ffd23f');g.addColorStop(1,'#a36a00');
    ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,bp.r,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.stroke();
    ctx.restore();
  }
  // slots
  const slotY=H*0.82,slotH=H*0.12;
  for(const s of SLOTS){
    const hot=s.mult>=5;
    ctx.fillStyle=hot?'rgba(255,210,63,0.25)':'rgba(255,255,255,0.06)';
    ctx.fillRect(s.x-s.w/2,slotY,s.w,slotH);
    ctx.strokeStyle=hot?'#ffd23f':'rgba(255,255,255,0.2)';ctx.lineWidth=2;
    ctx.strokeRect(s.x-s.w/2,slotY,s.w,slotH);
    ctx.fillStyle=hot?'#ffd23f':'#fff';
    ctx.font='900 15px system-ui';ctx.textAlign='center';
    ctx.fillText('x'+s.mult,s.x,slotY+slotH/2+5);ctx.textAlign='left';
  }
  // ball
  if(G.ball){
    const b=G.ball;
    const g=ctx.createRadialGradient(b.x-4,b.y-4,2,b.x,b.y,b.r);
    g.addColorStop(0,'#ffe9a0');g.addColorStop(0.5,'#ff6a1a');g.addColorStop(1,'#a32a10');
    ctx.fillStyle=g;
    ctx.shadowColor='#ff7a2a';ctx.shadowBlur=18; // magma ball glow
    ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fill();
    ctx.shadowBlur=0;
    // trail
    ctx.strokeStyle='rgba(255,106,26,0.4)';ctx.lineWidth=4;
    ctx.beginPath();ctx.moveTo(b.x,b.y-b.vy*0.03);ctx.lineTo(b.x,b.y);ctx.stroke();
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  ctx.textAlign='center';
  for(const f of floaters){
    if(!f.a)continue;
    ctx.globalAlpha=Math.min(1,f.life);
    ctx.font='900 20px system-ui';ctx.fillStyle='#000';
    ctx.fillText(f.txt,f.x+2,f.y+2);ctx.fillStyle=f.color;ctx.fillText(f.txt,f.x,f.y);
  }
  ctx.globalAlpha=1;ctx.textAlign='left';
  if(G.ball&&G.combo>=5){
    ctx.fillStyle='#7fd4ff';ctx.font='900 20px system-ui';ctx.textAlign='center';
    ctx.fillText('🔗 PEG CHAIN x'+G.combo,W/2,H*0.155);ctx.textAlign='left';
  }
  ctx.restore();
  if(G.paused){ctx.fillStyle='rgba(0,0,0,0.45)';ctx.fillRect(0,0,W,H);ctx.fillStyle='#fff';ctx.font='900 34px system-ui';ctx.textAlign='center';ctx.fillText('⏸️ PAUSED',W/2,H/2);ctx.textAlign='left';}
}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(G.state==='play'&&!G.paused)update(dt);else G.time+=dt;
  render();
  requestAnimationFrame(loop);
}
resize();buildBoard();
document.getElementById('best').textContent='🏆 '+G.best;
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Plink Plonk Magma' — Magma Drop Physics's own
   track. Synthesized Web Audio only. 112 BPM, G major pentatonic: a plinky
   sine-bell lead (with the game-09 octave shimmer) dripping down the scale,
   bar after bar.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Freeze gate CONFIRMED at insertion (2026-10-15): script-scope `muted` mutes, G.paused pauses, and music only
   plays while G.state==='play' — all read from this shell's own code.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-36-magma-drop-physics.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
// Freeze gate (insertion-confirmed 2026-10-15): hard-wired to this shell's
// own confirmed globals — muted / G.paused / G.state. try/catch kept so it can never throw.
const _mGate=()=>{try{return !!(muted||G.paused||G.state!=='play');}catch(e){return false;}};
const MUS={on:false,step:0,nextT:0,BPM:112,
 BASS:[43,0,0,0,50,0,0,0, 48,0,0,0,55,0,0,0, 40,0,0,0,47,0,0,0, 38,0,0,0,45,0,50,0],
 LEAD:[83,0,79,0,76,0,74,0, 81,0,79,0,76,0,71,0, 79,0,76,0,74,0,71,0, 74,0,71,0,69,0,67,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(_mGate()){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.2,'triangle',0.05,d);
  const l=this.LEAD[s];if(l){tone(_mf(l),_mf(l),0.16,'sine',0.05,d);
   tone(_mf(l)*2,_mf(l)*2,0.1,'sine',0.012,d);} // bell shimmer
  if(s%8===0)tone(110,45,0.12,'sine',0.1,d); // soft kick
  if(s%8===4)tone(150,90,0.1,'sine',0.05,d); // low plonk
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

