#fb-seasonal-decor{position:fixed;inset:0;pointer-events:none;z-index:90}
html.fb-mode-game #fb-seasonal-decor{z-index:2}
#fb-seasonal-decor .fb-sb-glyph{position:absolute;line-height:1;filter:drop-shadow(0 4px 10px rgba(0,0,0,.45))}
#fb-seasonal-ambience{position:fixed;inset:0;pointer-events:none;z-index:89;overflow:hidden}
#fb-seasonal-ambience .fb-sb-fall{position:absolute;top:-8vh;line-height:1;opacity:.5;animation-name:fb-sb-fall;animation-timing-function:linear;animation-iteration-count:infinite}
@keyframes fb-sb-fall{from{transform:translate3d(0,-8vh,0) rotate(-8deg)}to{transform:translate3d(3vw,112vh,0) rotate(38deg)}}
@keyframes fb-sb-bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-9px)}}
.fb-sb-bob{animation:fb-sb-bob 3.6s ease-in-out infinite}
/* ---- game-page badge ---- */
.fb-sb-badge{position:absolute;left:50%;bottom:6px;transform:translateX(-50%);font-size:17px;letter-spacing:2px;opacity:.55;line-height:1;white-space:nowrap}
/* ---- accents: every page ---- */
html.fb-theme-halloween ::selection{background:rgba(255,140,26,.5);color:#fff}
html.fb-mode-page body{background-color:#1c0a2a}
/* ---- hub showcase: deep-purple night + pumpkin glow ---- */
html.fb-mode-hub body{background:radial-gradient(1100px 560px at 50% -120px,rgba(124,58,237,.34),transparent 62%),radial-gradient(700px 380px at 85% 110%,rgba(255,140,26,.16),transparent 60%),#170a26}
html.fb-mode-hub nav.top{background:rgba(23,10,38,.96);border-bottom-color:rgba(155,89,182,.55)}
html.fb-mode-hub .hero{background:radial-gradient(ellipse at 50% 0%,rgba(255,140,26,.20),transparent 65%);border-bottom-color:rgba(155,89,182,.55)}
html.fb-mode-hub .hero h1{color:#ffb347;text-shadow:0 0 26px rgba(124,58,237,.65),0 4px 30px rgba(255,106,26,.35)}
html.fb-mode-hub .card{border-color:rgba(155,89,182,.5)}
html.fb-mode-hub .card:hover{border-color:#ff8c1a;box-shadow:0 16px 36px rgba(0,0,0,.45),0 0 26px rgba(124,58,237,.35)}
html.fb-mode-hub footer{border-top-color:rgba(155,89,182,.5)}
html.fb-mode-hub .hero,html.fb-mode-hub .whatsnew,html.fb-mode-hub .wrap,html.fb-mode-hub footer{position:relative;z-index:1}
/* ---- reduced motion: no falling/floating glyphs ---- */
@media (prefers-reduced-motion: reduce){#fb-seasonal-ambience{display:none}.fb-sb-bob{animation:none}}

scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();
let AC=null,muted=false;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(muted)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
function noise(dur,vol,delay=0,lp=700){if(muted)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const len=ac.sampleRate*dur,buf=ac.createBuffer(1,len,ac.sampleRate),d=buf.getChannelData(0);
  for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);
  const s=ac.createBufferSource();s.buffer=buf;const f=ac.createBiquadFilter();f.type='lowpass';f.frequency.value=lp;
  const g=ac.createGain();g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  s.connect(f);f.connect(g);g.connect(ac.destination);s.start(t);}
const sfx={
  drop(){tone(400,600,0.08,'triangle',0.1);},
  land(){tone(300,500,0.1,'square',0.09);},
  perfect(){tone(800,1600,0.2,'triangle',0.14);},
  smash(){noise(0.2,0.25,0,600);},
  fall(){tone(400,80,0.5,'sawtooth',0.14);},
  click(){tone(600,600,0.06,'square',0.1);}
};
const BH=34;
const G={state:'title',score:0,best:0,perfects:0,
  stack:[],cur:null,falling:null,debris:[],
  camY:0,time:0,dead:false,shake:0,paused:false};
try{G.best=parseInt(localStorage.getItem('stack_best')||'0',10)||0;}catch(e){}
function reset(){
  G.score=0;G.perfects=0;G.stack=[];G.debris=[];
  G.camY=0;G.time=0;G.dead=false;G.shake=0;G.falling=null;G.paused=false;pauseBtn.textContent='⏸️';
  const w=Math.min(220,W*0.55);
  G.stack.push({x:W/2-w/2,y:H-60-BH,w,h:BH});
  spawnBlock();
  updateHUD();
  document.getElementById('best').textContent='🏆 '+G.best;
}
function spawnBlock(){
  const prev=G.stack[G.stack.length-1];
  const speed=Math.min(520,260+G.score*12);
  G.cur={w:prev.w,y:prev.y-BH,dir:Math.random()<0.5?-1:1,x:Math.random()<0.5?-prev.w:W,speed,phase:0};
}
function updateHUD(){
  document.getElementById('score').textContent='⭐ '+G.score;
  document.getElementById('perfect').textContent=`✨ ${G.perfects} perfect`;
}
function dropBlock(){
  if(G.state!=='play'||G.dead||!G.cur||G.falling||G.paused)return;
  G.falling={x:G.cur.x,y:G.cur.y,w:G.cur.w,vy:0};
  G.cur=null;sfx.drop();
}
canvas.addEventListener('pointerdown',e=>{e.preventDefault();dropBlock();});
addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();dropBlock();}});
const particles=[],floaters=[];
for(let i=0;i<80;i++)particles.push({a:false});
// Living background embers (positions derived from G.time — cheap, stateless)
const EMBERS=[];
for(let i=0;i<24;i++)EMBERS.push({x:Math.random(),o:Math.random()*1200,s:24+Math.random()*36,r:1.4+Math.random()*2.2,ph:Math.random()*6.28});
for(let i=0;i<8;i++)floaters.push({a:false});
function spawnText(x,y,txt,color){
  const f=floaters.find(f=>!f.a);if(!f)return;
  f.a=true;f.x=x;f.y=y;f.txt=txt;f.color=color;f.life=1.2;
}
function update(dt){
  G.time+=dt;G.shake=Math.max(0,G.shake-dt*3);
  // swing current
  if(G.cur){
    G.cur.x+=G.cur.dir*G.cur.speed*dt;
    if(G.cur.x<-G.cur.w){G.cur.x=-G.cur.w;G.cur.dir=1;}
    if(G.cur.x>W){G.cur.x=W;G.cur.dir=-1;}
  }
  // falling block
  if(G.falling){
    const f=G.falling;
    f.vy+=2600*dt;f.y+=f.vy*dt;
    const prev=G.stack[G.stack.length-1];
    if(f.y>=prev.y-BH){
      f.y=prev.y-BH;
      const overlapL=Math.max(f.x,prev.x);
      const overlapR=Math.min(f.x+f.w,prev.x+prev.w);
      const overlap=overlapR-overlapL;
      if(overlap<=8){
        // missed!
        G.dead=true;sfx.fall();G.shake=0.5;
        // block falls off
        G.debris.push({...f,vx:(f.x<prev.x?-1:1)*160,vy:-100,rot:0,vr:(Math.random()-0.5)*6});
        G.falling=null;
        const isBest=G.score>G.best;
        if(isBest){G.best=G.score;try{localStorage.setItem('stack_best',String(G.best));}catch(e){}}
        setTimeout(()=>{
          showOverlay('💥 TOWER TOPPLED!',
            `${isBest?'<p style="color:#ffd23f;font-weight:900">🏆 NEW BEST!</p>':''}<p style="font-size:26px;font-weight:900">Height: ${G.score}</p><p>Perfect drops: ${G.perfects}</p><p>Best: ${G.best}</p>`,
            '🔥 Fire Safety: Build strong habits!',
            '↻ STACK AGAIN',()=>{reset();G.state='play';});
        },700);
        return;
      }
      // perfect?
      const centerOff=Math.abs((f.x+f.w/2)-(prev.x+prev.w/2));
      if(centerOff<10){
        G.score++;G.perfects++;sfx.perfect();
        spawnText(f.x+f.w/2,f.y-30,'PERFECT!','#4caf50');
        // grow back slightly
        const nw=Math.min(prev.w+14,Math.min(220,W*0.55));
        G.stack.push({x:f.x+(f.w-nw)/2,y:f.y,w:nw,h:BH,perfect:true});
        for(let i=0;i<12;i++){const p=particles.find(p=>!p.a);if(!p)break;
          p.a=true;p.x=f.x+f.w/2;p.y=f.y;const a=Math.random()*Math.PI*2;
          p.vx=Math.cos(a)*220;p.vy=Math.sin(a)*220;
          p.life=0.5;p.max=0.5;p.color='#4caf50';p.size=4;}
      }else{
        // trim overhang
        G.score++;sfx.land();
        const nx=overlapL,nw=overlap;
        // debris from cut part
        if(f.x<overlapL)G.debris.push({x:f.x,y:f.y,w:overlapL-f.x,h:BH,vx:-140,vy:-60,rot:0,vr:-4});
        if(f.x+f.w>overlapR)G.debris.push({x:overlapR,y:f.y,w:f.x+f.w-overlapR,h:BH,vx:140,vy:-60,rot:0,vr:4});
        sfx.smash();G.shake=Math.max(G.shake,0.18);
        G.stack.push({x:nx,y:f.y,w:nw,h:BH});
      }
      G.falling=null;updateHUD();
      spawnBlock();
    }
  }
  tickFx(dt);
  // smooth camera: lerp toward the stack top EVERY frame (was a one-shot
  // 0.25 step per landing, so the view never finished settling)
  const topY=G.stack[G.stack.length-1].y;
  G.camY+=(topY-H*0.55-G.camY)*Math.min(1,dt*5);
}
function tickFx(dt){
  // debris / particles / floaters — also ticked while dead so the toppled
  // block keeps falling during the game-over beat instead of freezing
  for(const d of G.debris){
    d.vy+=2000*dt;d.x+=d.vx*dt;d.y+=d.vy*dt;d.rot+=d.vr*dt;
    if(d.y>H+100)d.gone=true;
  }
  G.debris=G.debris.filter(d=>!d.gone);
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=400*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  for(const f of floaters){if(!f.a)continue;f.y-=34*dt;f.life-=dt;if(f.life<=0)f.a=false;}
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();reset();G.state='play';overlay.classList.add('hidden');}
obtn.onclick=()=>{showMathGate();};
const muteBtn=document.getElementById('muteBtn'),pauseBtn=document.getElementById('pauseBtn');
muteBtn.onclick=()=>{muted=!muted;muteBtn.textContent=muted?'🔇':'🔊';};
function togglePause(){if(!(G.state==='play'))return;G.paused=!G.paused;pauseBtn.textContent=G.paused?'▶️':'⏸️';}
pauseBtn.onclick=togglePause;
addEventListener('keydown',e=>{if(e.code==='KeyP')togglePause();});

const HUES=[14,28,200,150,280,340];
function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#0d0a14');bg.addColorStop(1,'#140d08');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  // living embers behind the tower (additive glow, screen space)
  ctx.save();ctx.globalCompositeOperation='lighter';
  for(const e of EMBERS){
    const ey=H-((G.time*e.s+e.o)%(H+30));
    const ex=e.x*W+Math.sin(G.time*0.9+e.ph)*10;
    ctx.globalAlpha=0.15+0.11*Math.sin(G.time*2+e.ph);
    ctx.fillStyle='#ff9a3c';
    ctx.beginPath();ctx.arc(ex,ey,e.r,0,Math.PI*2);ctx.fill();
  }
  ctx.restore();ctx.globalAlpha=1;
  ctx.save();
  if(G.shake>0)ctx.translate((Math.random()-0.5)*G.shake*12,(Math.random()-0.5)*G.shake*12);
  ctx.translate(0,-G.camY);
  // stack
  G.stack.forEach((b,i)=>{
    const hue=HUES[i%HUES.length];
    const g=ctx.createLinearGradient(0,b.y,0,b.y+b.h);
    g.addColorStop(0,`hsl(${hue},60%,45%)`);g.addColorStop(1,`hsl(${hue},60%,28%)`);
    ctx.fillStyle=g;
    ctx.beginPath();ctx.roundRect(b.x,b.y,b.w,b.h,6);ctx.fill();
    ctx.fillStyle='rgba(255,255,255,0.25)';
    ctx.fillRect(b.x+6,b.y+4,b.w-12,5);
    if(b.perfect){
      ctx.strokeStyle='#4caf50';ctx.lineWidth=3;
      ctx.beginPath();ctx.roundRect(b.x,b.y,b.w,b.h,6);ctx.stroke();
    }
  });
  // current swinging
  if(G.cur){
    const c=G.cur,hue=HUES[G.stack.length%HUES.length];
    const g=ctx.createLinearGradient(0,c.y,0,c.y+BH);
    g.addColorStop(0,`hsl(${hue},60%,50%)`);g.addColorStop(1,`hsl(${hue},60%,32%)`);
    ctx.fillStyle=g;
    ctx.shadowColor=`hsl(${hue},80%,55%)`;ctx.shadowBlur=14; // active block glow
    ctx.beginPath();ctx.roundRect(c.x,c.y,c.w,BH,6);ctx.fill();
    ctx.shadowBlur=0;
    ctx.fillStyle='rgba(255,255,255,0.3)';
    ctx.fillRect(c.x+6,c.y+4,c.w-12,5);
    // drop guide
    const prev=G.stack[G.stack.length-1];
    ctx.strokeStyle='rgba(255,255,255,0.2)';ctx.lineWidth=2;ctx.setLineDash([8,8]);
    ctx.beginPath();ctx.moveTo(c.x+c.w/2,c.y+BH);ctx.lineTo(c.x+c.w/2,prev.y);ctx.stroke();
    ctx.setLineDash([]);
  }
  // falling
  if(G.falling){
    const f=G.falling,hue=HUES[G.stack.length%HUES.length];
    ctx.fillStyle=`hsl(${hue},60%,42%)`;
    ctx.beginPath();ctx.roundRect(f.x,f.y,f.w,BH,6);ctx.fill();
  }
  // debris
  for(const d of G.debris){
    ctx.save();ctx.translate(d.x+d.w/2,d.y+BH/2);ctx.rotate(d.rot);
    ctx.fillStyle='rgba(120,80,50,0.9)';
    ctx.fillRect(-d.w/2,-BH/2,d.w,BH);
    ctx.restore();
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  ctx.textAlign='center';
  for(const f of floaters){
    if(!f.a)continue;
    ctx.globalAlpha=Math.min(1,f.life);
    ctx.font='900 20px system-ui';ctx.fillStyle='#000';
    ctx.fillText(f.txt,f.x+2,f.y+2);ctx.fillStyle=f.color;ctx.fillText(f.txt,f.x,f.y);
  }
  ctx.globalAlpha=1;ctx.textAlign='left';
  ctx.restore();
  // tap hint
  if(G.state==='play'&&G.score<2&&G.cur){
    ctx.fillStyle='rgba(255,255,255,0.75)';ctx.font='900 20px system-ui';ctx.textAlign='center';
    ctx.fillText('👆 TAP TO DROP!',W/2,H*0.3);
    ctx.textAlign='left';
  }
  if(G.paused){ctx.fillStyle='rgba(0,0,0,0.45)';ctx.fillRect(0,0,W,H);ctx.fillStyle='#fff';ctx.font='900 34px system-ui';ctx.textAlign='center';ctx.fillText('⏸️ PAUSED',W/2,H/2);ctx.textAlign='left';}
}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(G.state==='play'&&!G.dead&&!G.paused)update(dt);else{G.time+=dt;if(G.state==='play'&&G.dead)tickFx(dt);}
  render();
  requestAnimationFrame(loop);
}
document.getElementById('best').textContent='🏆 '+G.best;
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Stack Attack' — Volcanic Stack Smash's own
   track. Synthesized Web Audio only. 126 BPM, F minor: a chunky square lead
   — and the drums stack up bar by bar (kick, then snare, then hats), just
   like the tower.
   Freeze gate CONFIRMED at insertion (2026-10-15): script-scope `muted` mutes, G.paused pauses, and music only
   plays while G.state==='play' — all read from this shell's own code.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-37-volcanic-stack-smash.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
// Freeze gate (insertion-confirmed 2026-10-15): hard-wired to this shell's
// own confirmed globals — muted / G.paused / G.state. try/catch kept so it can never throw.
const _mGate=()=>{try{return !!(muted||G.paused||G.state!=='play');}catch(e){return false;}};
const MUS={on:false,step:0,nextT:0,BPM:126,
 BASS:[41,0,41,41,0,41,0,0, 44,0,44,44,0,44,0,0, 37,0,37,37,0,37,0,0, 39,0,39,39,0,41,44,0],
 LEAD:[65,0,68,0,65,0,0,0, 72,0,68,0,65,0,0,0, 73,0,72,0,68,0,65,0, 77,0,75,0,72,0,68,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(_mGate()){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);const bar=(s/8)|0;
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.13,'square',0.06,d);
  const l=this.LEAD[s];if(l){tone(_mf(l),_mf(l),0.15,'square',0.05,d);
   if(bar===3)tone(_mf(l+12),_mf(l+12),0.1,'square',0.012,d);} // top layer: octave double
  if(s%8===0||s%8===4)tone(120,45,0.11,'sine',0.13,d); // kick from bar 1
  if(bar>=1&&(s%8===2||s%8===6))noise(0.08,0.08,d,1800); // snare stacks in bar 2
  if(bar>=2&&s%2===0)noise(0.02,0.016,d,6800); // hats stack in bar 3
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

