scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();
let AC=null,muted=false;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(muted)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  boost(){tone(300,1200,0.3,'sawtooth',0.1);},
  lap(){tone(600,1000,0.2,'triangle',0.13);},
  count(n){tone(400+n*200,400+n*200,0.15,'square',0.12);},
  win(){[523,659,784,1047,1319].forEach((f,i)=>tone(f,f,0.2,'triangle',0.14,i*0.09));},
  click(){tone(600,600,0.06,'square',0.1);}
};
// track: oval with waypoints
function trackPoints(){
  const cx=W/2,cy=H/2,rx=W*0.36,ry=H*0.32;
  const pts=[];
  for(let i=0;i<48;i++){
    const a=i/48*Math.PI*2;
    // slight wobble for interest
    const w=1+0.08*Math.sin(a*3);
    pts.push({x:cx+Math.cos(a)*rx*w,y:cy+Math.sin(a)*ry*w});
  }
  return pts;
}
let TRACK=[];
const G={state:'title',lap:1,lapTimes:[],raceT:0,
  x:0,y:0,a:0,v:0,boost:0,countdown:0,
  best:null,offTrack:false,time:0,skid:[],paused:false,lapMsg:'',lapMsgT:0,ghost:null,ghostBestLap:null,rec:[],recAcc:0};
try{const b=localStorage.getItem('rally_best');if(b)G.best=parseFloat(b);}catch(e){}
// --- Ghost car (leftover-fix): record the player's best LAP and replay it
// translucently on later races. Samples are {t,x,y,a} taken every 0.1s of lap
// time (10/s — a 3-minute lap caps at 1800 samples, ~90KB worst case, and the
// storage write happens once per lap at most). The ghost is render-only: it
// is never fed into physics, so it can never collide with or slow the player.
const GHOST_KEY='rally_ghost_v1',GHOST_DT=0.1,GHOST_MAX=1800;
function loadGhost(){
  G.ghost=null;G.ghostBestLap=null;
  try{
    const raw=localStorage.getItem(GHOST_KEY);
    if(raw){const d=JSON.parse(raw);if(d&&Array.isArray(d.samples)&&d.samples.length>10&&isFinite(d.time)){G.ghost=d.samples;G.ghostBestLap=d.time;}}
  }catch(e){}
}
function saveGhostIfBest(lapTime){
  if(!G.rec||G.rec.length<10)return;
  if(G.ghostBestLap!=null&&lapTime>=G.ghostBestLap)return;
  G.ghost=G.rec.slice(0,GHOST_MAX);G.ghostBestLap=lapTime;
  try{localStorage.setItem(GHOST_KEY,JSON.stringify({time:lapTime,samples:G.ghost}));}catch(e){}
}
function ghostPose(lapT){
  if(!G.ghost||!G.ghost.length)return null;
  const i=Math.max(0,Math.min(G.ghost.length-1,Math.floor(lapT/GHOST_DT)));
  return G.ghost[i];
}
function reset(){
  TRACK=trackPoints();
  loadGhost();G.rec=[];G.recAcc=0;
  const p0=TRACK[0];
  G.x=p0.x;G.y=p0.y-40;G.a=Math.PI/2;G.v=0;G.boost=0; // FIX: car was placed below the line facing UP (-PI/2) but the circuit runs DOWNWARD from the start point — it spawned facing the wrong way
  G.paused=false;G.lapMsg='';G.lapMsgT=0;pauseBtn.textContent='⏸️';
  G.lap=1;G.lapTimes=[];G.raceT=0;G.countdown=3;G.skid=[];
  G.state='countdown';G.countT=0;
  updateHUD();
}
function updateHUD(){
  document.getElementById('lap').textContent=`LAP ${Math.min(G.lap,8)}/8`;
  document.getElementById('time').textContent='⏱️ '+G.raceT.toFixed(1)+'s';
  document.getElementById('best').textContent='🏆 '+(G.best?G.best.toFixed(1)+'s':'--');
  document.getElementById('speed').textContent='🚗 '+Math.round(G.v*0.36);
}
// input
let gas=false,kbGas=false,steerL=false,steerR=false,gasId=null;
canvas.addEventListener('pointerdown',e=>{gas=true;gasId=e.pointerId;});
function clearGas(e){if(gasId===null||e.pointerId===gasId){gas=false;gasId=null;}}
canvas.addEventListener('pointerup',clearGas);
canvas.addEventListener('pointercancel',clearGas);
// BUGFIX (earlier): sliding a finger off the canvas left gas stuck ON.
// BUGFIX (now): the window-level clear also fired when the STEERING finger
// lifted, killing the gas mid-corner in two-finger play. Gas is now tied to
// its own pointerId — only the gas finger (or keyboard) can release it.
canvas.addEventListener('pointerleave',clearGas);
addEventListener('pointerup',clearGas);
function resetToTrack(){
  if(G.state!=='play')return;
  const{idx}=distToTrack(G.x,G.y);
  const p=TRACK[idx],q=TRACK[(idx+1)%TRACK.length],r=TRACK[(idx-1+TRACK.length)%TRACK.length];
  G.x=p.x;G.y=p.y;G.a=Math.atan2(q.y-r.y,q.x-r.x);G.v=Math.max(G.v,60);
  G.lapMsg='⟲ Back on track!';G.lapMsgT=1.2;
}
addEventListener('keydown',e=>{if(e.key.toLowerCase()==='r')resetToTrack();});
function bindHold(id,fn){
  const el=document.getElementById(id);
  el.addEventListener('pointerdown',e=>{e.stopPropagation();fn(true);});
  el.addEventListener('pointerup',()=>fn(false));
  el.addEventListener('pointerleave',()=>fn(false));
}
bindHold('leftBtn',v=>steerL=v);
bindHold('rightBtn',v=>steerR=v);
const keys={};
addEventListener('keydown',e=>{
  keys[e.key.toLowerCase()]=true;
  if(e.key==='ArrowUp'||e.key===' ')kbGas=true;
});
addEventListener('keyup',e=>{
  keys[e.key.toLowerCase()]=false;
  if(e.key==='ArrowUp'||e.key===' ')kbGas=false;
});
function distToTrack(x,y){
  let best=1e9,bi=0;
  for(let i=0;i<TRACK.length;i++){
    const p=TRACK[i];
    const d=Math.hypot(x-p.x,y-p.y);
    if(d<best){best=d;bi=i;}
  }
  return{d:best,idx:bi};
}
// boost pads at fixed indices
const BOOSTS=[8,20,32,44];
// Living background sparks (positions derived from G.time — cheap, stateless)
const EMBERS=[];
for(let i=0;i<24;i++)EMBERS.push({x:Math.random(),o:Math.random()*1200,s:20+Math.random()*30,r:1.3+Math.random()*2,ph:Math.random()*6.28});
function update(dt){
  G.time+=dt;
  if(G.state==='countdown'){
    G.countT+=dt;
    const n=3-Math.floor(G.countT);
    if(n!==G._cn&&n>0){G._cn=n;sfx.count(n);}
    if(G.countT>=3.6){G.state='play';sfx.count(4);}
    return;
  }
  if(G.state!=='play')return;
  G.raceT+=dt;G.boost=Math.max(0,G.boost-dt);G.lapMsgT=Math.max(0,G.lapMsgT-dt);
  // record this lap for a possible new ghost (light: one sample per 0.1s)
  G.recAcc+=dt;
  if(G.recAcc>=GHOST_DT&&G.rec.length<GHOST_MAX){G.recAcc=0;G.rec.push({t:G.raceT-(G.lapStart||0),x:Math.round(G.x),y:Math.round(G.y),a:+G.a.toFixed(3)});}
  const accel=(gas||kbGas||keys['w'])?420:0;
  const maxV=G.boost>0?560:340;
  if(accel)G.v=Math.min(maxV,G.v+accel*dt);
  else G.v=Math.max(0,G.v-180*dt);
  // steering
  const steer=(steerL||keys['arrowleft']||keys['a']?-1:0)+(steerR||keys['arrowright']||keys['d']?1:0);
  if(G.v>20)G.a+=steer*2.4*dt*(G.v/maxV);
  G.x+=Math.cos(G.a)*G.v*dt;
  G.y+=Math.sin(G.a)*G.v*dt;
  // track check
  const{d,idx}=distToTrack(G.x,G.y);
  const trackW=54;
  G.offTrack=d>trackW;
  // BUGFIX: was Math.max(80, v-300*dt) — that FORCED a stopped car off-track
  // back up to 80 speed, so the car crept forward on its own and could
  // never stop on the grass. Grass should only drag speed DOWN toward 80.
  if(G.offTrack&&G.v>80)G.v=Math.max(80,G.v-300*dt);
  // boost pads
  if(BOOSTS.includes(idx)&&G.v>50&&G.boost<=0){
    G.boost=1.2;sfx.boost();
    for(let i=0;i<10;i++)G.skid.push({x:G.x,y:G.y,vx:-Math.cos(G.a)*200+(Math.random()-0.5)*100,vy:-Math.sin(G.a)*200+(Math.random()-0.5)*100,life:0.5,color:'#7fd4ff'});
  }
  // lap detection (cross start/finish)
  G._lastIdx=G._lastIdx||0;
  if(G._lastIdx>40&&idx<8&&G.raceT>3){
    // crossed line
    const lt=G.raceT-(G.lapStart||0);
    saveGhostIfBest(lt);G.rec=[];G.recAcc=0; // this lap becomes / stays the ghost
    G.lapTimes.push(lt);G.lapStart=G.raceT;
    G.lapMsg=`🏁 Lap ${G.lapTimes.length}: ${lt.toFixed(1)}s`;G.lapMsgT=2.2; // live split (was only shown at race end)
    sfx.lap();
    if(G.lap>=8){finishRace();return;}
    G.lap++;
  }
  G._lastIdx=idx;
  if(!G.lapStart&&G.raceT>0.5)G.lapStart=0;
  // skids
  if(steer!==0&&G.v>200&&Math.random()<0.4){
    G.skid.push({x:G.x-Math.cos(G.a)*14,y:G.y-Math.sin(G.a)*14,
      vx:(Math.random()-0.5)*40,vy:(Math.random()-0.5)*40,life:0.6,color:'#555'});
  }
  for(const s of G.skid){s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;}
  G.skid=G.skid.filter(s=>s.life>0);
  updateHUD();
}
function finishRace(){
  G.state='over';
  const total=G.raceT;
  const isBest=!G.best||total<G.best;
  if(isBest){G.best=total;try{localStorage.setItem('rally_best',String(total));}catch(e){}}
  sfx.win();
  const laps=G.lapTimes.map((t,i)=>`Lap ${i+1}: ${t.toFixed(1)}s`).join('<br>');
  setTimeout(()=>{
    showOverlay('🏁 RACE COMPLETE!',
      `${isBest?'<p style="color:#ffd23f;font-weight:900">🏆 NEW BEST TIME!</p>':''}${laps}<p style="font-size:24px;font-weight:900">Total: ${total.toFixed(1)}s</p>`,
      '🔥 Fire Safety: Race to safety — never race real cars!',
      '↻ RACE AGAIN',()=>{reset();overlay.classList.add('hidden');});
  },600);
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();reset();overlay.classList.add('hidden');}
const muteBtn=document.getElementById('muteBtn'),pauseBtn=document.getElementById('pauseBtn');
muteBtn.onclick=()=>{muted=!muted;muteBtn.textContent=muted?'🔇':'🔊';};
function togglePause(){if(!(G.state==='play'||G.state==='countdown'))return;G.paused=!G.paused;pauseBtn.textContent=G.paused?'▶️':'⏸️';}
pauseBtn.onclick=togglePause;
addEventListener('keydown',e=>{if(e.code==='KeyP')togglePause();});

document.getElementById('resetBtn').onclick=()=>resetToTrack();

obtn.onclick=()=>{showMathGate();};
function render(){
  // grass
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#1a3a1a');bg.addColorStop(1,'#0d2412');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  // drifting sparks over the grass (additive glow)
  ctx.save();ctx.globalCompositeOperation='lighter';
  for(const e of EMBERS){
    const ey=H-((G.time*e.s+e.o)%(H+30));
    const ex=e.x*W+Math.sin(G.time*0.9+e.ph)*12;
    ctx.globalAlpha=0.13+0.1*Math.sin(G.time*2+e.ph);
    ctx.fillStyle='#ffb03a';
    ctx.beginPath();ctx.arc(ex,ey,e.r,0,Math.PI*2);ctx.fill();
  }
  ctx.restore();ctx.globalAlpha=1;
  if(!TRACK.length)return;
  // track (wide dark)
  ctx.strokeStyle='#2a2a3a';ctx.lineWidth=116;ctx.lineJoin='round';
  ctx.beginPath();
  TRACK.forEach((p,i)=>i===0?ctx.moveTo(p.x,p.y):ctx.lineTo(p.x,p.y));
  ctx.closePath();ctx.stroke();
  // track surface
  ctx.strokeStyle='#3a3a4a';ctx.lineWidth=100;
  ctx.stroke();
  // center dashes
  ctx.strokeStyle='rgba(255,255,255,0.25)';ctx.lineWidth=4;ctx.setLineDash([20,24]);
  ctx.beginPath();
  TRACK.forEach((p,i)=>i===0?ctx.moveTo(p.x,p.y):ctx.lineTo(p.x,p.y));
  ctx.closePath();ctx.stroke();
  ctx.setLineDash([]);
  // start/finish
  const p0=TRACK[0];
  ctx.save();ctx.translate(p0.x,p0.y);ctx.rotate(Math.atan2(TRACK[1].y-p0.y,TRACK[1].x-p0.x)+Math.PI/2);
  for(let i=0;i<4;i++)for(let j=0;j<6;j++){
    ctx.fillStyle=(i+j)%2?'#fff':'#111';
    ctx.fillRect(-50+i*25,-8+j*8,25,8);
  }
  ctx.restore();
  // boost pads
  for(const bi of BOOSTS){
    const p=TRACK[bi];
    const pulse=1+Math.sin(G.time*6)*0.12;
    ctx.save();ctx.translate(p.x,p.y);ctx.scale(pulse,pulse);
    ctx.fillStyle='rgba(127,212,255,0.85)';
    ctx.font='30px system-ui';ctx.textAlign='center';
    ctx.fillText('⚡',0,10);ctx.textAlign='left';
    ctx.restore();
  }
  // skids
  for(const s of G.skid){
    ctx.globalAlpha=Math.min(0.5,s.life);
    ctx.fillStyle=s.color;
    ctx.beginPath();ctx.arc(s.x,s.y,4,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  // ghost car (best-lap replay — translucent, render-only, never collides)
  if(G.ghost&&(G.state==='play')){
    const gp=ghostPose(G.raceT-(G.lapStart||0));
    if(gp){
      ctx.save();ctx.globalAlpha=0.42;ctx.translate(gp.x,gp.y);ctx.rotate(gp.a);
      ctx.fillStyle='#aee2ff';
      ctx.beginPath();ctx.roundRect(-20,-11,40,22,6);ctx.fill();
      ctx.fillStyle='#ffffff';ctx.beginPath();ctx.arc(2,0,8,0,Math.PI*2);ctx.fill();
      ctx.fillStyle='#111';
      ctx.fillRect(-14,-15,10,5);ctx.fillRect(-14,10,10,5);
      ctx.fillRect(6,-15,10,5);ctx.fillRect(6,10,10,5);
      ctx.restore();ctx.globalAlpha=1;
    }
  }
  // car
  if(G.state!=='title'){
    ctx.save();ctx.translate(G.x,G.y);ctx.rotate(G.a);
    if(G.boost>0){
      ctx.fillStyle='rgba(127,212,255,0.5)';
      ctx.beginPath();ctx.ellipse(-24,0,18,10,0,0,Math.PI*2);ctx.fill();
    }
    // shadow
    ctx.fillStyle='rgba(0,0,0,0.3)';
    ctx.beginPath();ctx.roundRect(-20,-11+3,40,22,6);ctx.fill();
    // body
    const g=ctx.createLinearGradient(0,-11,0,11);
    g.addColorStop(0,'#ff8a3a');g.addColorStop(1,'#d42a1a');
    ctx.fillStyle=G.offTrack?'#6a6a6a':g;
    ctx.shadowColor=G.boost>0?'#7fd4ff':'#ff8c2e';ctx.shadowBlur=G.boost>0?20:13; // car glow (blue when boosting)
    ctx.beginPath();ctx.roundRect(-20,-11,40,22,6);ctx.fill();
    ctx.shadowBlur=0;
    // cockpit (fire baby)
    ctx.fillStyle='#ffe9a0';ctx.beginPath();ctx.arc(2,0,8,0,Math.PI*2);ctx.fill();
    // wheels
    ctx.fillStyle='#111';
    ctx.fillRect(-14,-15,10,5);ctx.fillRect(-14,10,10,5);
    ctx.fillRect(6,-15,10,5);ctx.fillRect(6,10,10,5);
    ctx.restore();
  }
  // countdown
  if(G.state==='countdown'){
    const n=3-Math.floor(G.countT);
    ctx.fillStyle='rgba(0,0,0,0.4)';ctx.fillRect(0,0,W,H);
    ctx.fillStyle=n>0?'#ffd23f':'#4caf50';
    ctx.font='900 90px system-ui';ctx.textAlign='center';
    ctx.fillText(n>0?n:'GO!',W/2,H/2);
    ctx.textAlign='left';
  }
  if(G.lapMsgT>0&&G.state==='play'){
    ctx.fillStyle='rgba(0,0,0,0.55)';ctx.fillRect(W/2-150,84,300,40);
    ctx.fillStyle='#ffd23f';ctx.font='900 22px system-ui';ctx.textAlign='center';
    ctx.fillText(G.lapMsg,W/2,112);ctx.textAlign='left';
  }
  // gas hint
  if(G.state==='play'&&G.raceT<4){
    ctx.fillStyle='rgba(255,255,255,0.8)';ctx.font='900 18px system-ui';ctx.textAlign='center';
    ctx.fillText('HOLD TO GO! ◀ ▶ TO STEER',W/2,H*0.85);
    ctx.textAlign='left';
  }
  if(G.paused){ctx.fillStyle='rgba(0,0,0,0.45)';ctx.fillRect(0,0,W,H);ctx.fillStyle='#fff';ctx.font='900 34px system-ui';ctx.textAlign='center';ctx.fillText('⏸️ PAUSED',W/2,H/2);ctx.textAlign='left';}
}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if((G.state==='countdown'||G.state==='play')&&!G.paused)update(dt);else G.time+=dt;
  render();
  requestAnimationFrame(loop);
}
document.getElementById('best').textContent='🏆 '+(G.best?G.best.toFixed(1)+'s':'--');
TRACK=trackPoints(); // show the track behind the title overlay, not bare grass
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Rally Cry' — Fire Baby Rally's own
   track. Synthesized Web Audio only. 146 BPM, D major: the full-crew anthem
   — the lead is doubled square + triangle like everybody singing at once,
   over big drums.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Freeze gate CONFIRMED at insertion (2026-10-15): script-scope `muted` mutes, G.paused pauses, and music only
   plays while G.state==='play' — all read from this shell's own code.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-38-fire-baby-rally.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
// Freeze gate (insertion-confirmed 2026-10-15): hard-wired to this shell's
// own confirmed globals — muted / G.paused / G.state. try/catch kept so it can never throw.
const _mGate=()=>{try{return !!(muted||G.paused||G.state!=='play');}catch(e){return false;}};
const MUS={on:false,step:0,nextT:0,BPM:146,
 BASS:[38,0,50,0,38,0,50,0, 47,0,59,0,47,0,59,0, 43,0,55,0,43,0,55,0, 45,0,57,0,45,0,52,0],
 LEAD:[74,0,78,0,81,0,78,0, 78,0,76,0,74,0,0,0, 76,0,79,0,83,0,79,0, 81,0,78,0,76,0,74,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(_mGate()){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.14,'square',0.055,d);
  const l=this.LEAD[s];if(l){tone(_mf(l),_mf(l),0.16,'square',0.045,d);
   tone(_mf(l),_mf(l),0.16,'triangle',0.04,d);} // full-crew doubled lead
  if(s%8===0||s%8===4)tone(100,38,0.13,'sine',0.16,d); // big kick
  if(s%8===6)tone(100,38,0.12,'sine',0.1,d); // extra stomp
  if(s%8===2||s%8===6)tone(195,120,0.08,'triangle',0.09,d); // big tone-only snare
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

