'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
let _rw=0,_rh=0;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);
  try{ // mid-game rotate/resize: scale the playfield so bricks/ball stay on-layout (was: bricks stranded at old coordinates)
    if(_rw&&_rh&&(_rw!==W||_rh!==H)&&G.bricks&&G.bricks.length){const sx=W/_rw,sy=H/_rh;
      for(const b of G.bricks){b.x*=sx;b.w*=sx;b.y*=sy;b.h*=sy;}
      G.px*=sx;G.bx*=sx;G.by*=sy;for(const pk of G.pickups){pk.x*=sx;pk.y*=sy;}}
  }catch(e){}
  _rw=W;_rh=H;}
addEventListener('resize',resize);resize();
let AC=null;
let muted=false;try{muted=localStorage.getItem('fb_mute')==='1';}catch(e){}
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(muted)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  paddle(){tone(400,650,0.07,'square',0.09);},
  brick(){tone(600,900,0.07,'triangle',0.09);},
  wall(){tone(300,400,0.05,'square',0.06);},
  lose(){tone(350,100,0.3,'sawtooth',0.13);},
  power(){tone(500,1100,0.16,'triangle',0.13);tone(750,1500,0.14,'sine',0.1,0.05);},
  win(){[523,659,784,1047].forEach((f,i)=>tone(f,f,0.2,'triangle',0.15,i*0.09));},
  click(){tone(600,600,0.06,'square',0.1);}
};
const G={state:'title',level:1,score:0,lives:3,
  px:0,bx:0,by:0,bvx:0,bvy:0,balls:[],
  bricks:[],time:0,shake:0,stuck:true,
  pickups:[],blastT:0,breaks:0};
// Living background embers (positions derived from G.time — cheap, stateless)
const EMBERS=[];
for(let i=0;i<24;i++)EMBERS.push({x:Math.random(),o:Math.random()*1200,s:24+Math.random()*36,r:1.4+Math.random()*2.2,ph:Math.random()*6.28});
const PW=110,PH=16,BR=10;
function buildLevel(n){
  G.bricks=[];
  const cols=7,fullRows=4+n;
  const bw=(W*0.9)/cols,bh=26;
  const ox=W*0.05;
  let oy=H<500?112:H*0.12;
  // [audit-fix 2026-10-18] short screens (H<500): cap the wall at 9 rows —
  // uncapped rows (4+n) reach 14 at L10, putting the wall bottom at 554px
  // on a 390px screen (42 of 95 bricks off-screen). The removed rows are
  // converted into +1 HP on the remaining top rows below, so total brick
  // HP per level is preserved exactly. Tall screens are untouched.
  const shortScr=H<500;
  const rows=shortScr?Math.min(fullRows,9):fullRows;
  // [audit-fix 2026-10-18] a 9-row wall from oy=112 still bottoms at 394px —
  // 4px past a 390px screen — so on short screens clamp oy up just enough
  // to fit the capped wall on-screen (max shift 4px, only when H<394;
  // brick height/pitch themselves unchanged).
  if(shortScr)oy=Math.min(oy,H-(rows*(bh+6)-6));
  const hues=[0,25,45,200,280];
  for(let r=0;r<rows;r++){
    for(let c=0;c<cols;c++){
      // patterns
      if(n>=3&&r===2&&c>=2&&c<=4)continue; // hole
      if(n===7&&r===6&&c>=2&&c<=4)continue; // extra hole row (L7)
      if(n===9&&r===8&&c>=2&&c<=4)continue; // extra hole row (L9)
      G.bricks.push({
        x:ox+c*bw+3,y:oy+r*(bh+6),w:bw-6,h:bh,
        hp:r%3===0?2:1,maxHp:r%3===0?2:1,
        hue:hues[(r+c)%hues.length],hit:0
      });
    }
  }
  // [audit-fix 2026-10-18] HP compensation: pool = HP the removed rows
  // would have carried (same pattern skips applied), handed back +1 at a
  // time starting from the top rows, so ΣHP matches the uncapped wall.
  if(shortScr&&fullRows>rows){
    let pool=0;
    for(let r=rows;r<fullRows;r++)for(let c=0;c<cols;c++){
      if(n>=3&&r===2&&c>=2&&c<=4)continue;
      if(n===7&&r===6&&c>=2&&c<=4)continue;
      if(n===9&&r===8&&c>=2&&c<=4)continue;
      pool+=(r%3===0?2:1);
    }
    let i=0;
    while(pool>0&&G.bricks.length){const b=G.bricks[i%G.bricks.length];b.hp++;b.maxHp++;pool--;i++;}
  }
  document.getElementById('level').textContent=`LV ${n}/10`;
}
function resetBall(){
  G.px=W/2;G.bx=W/2;G.by=H-80;G.bvx=0;G.bvy=0;G.stuck=true;
  G.pickups=[]; // stale falling pickups don't carry across a lost ball
}
function initLevel(n){
  G.level=n;setPaused(false);G.blastT=0;G.breaks=0;buildLevel(n);resetBall();
  document.getElementById('lives').textContent='❤️ '+G.lives;
  updateHUD();
}
