const keysHeld={left:false,right:false};
addEventListener('keydown',e=>{
  if(G.state!=='play'||G.paused)return; // keys also ignore input while paused

  if(e.key==='ArrowLeft')keysHeld.left=true;
  if(e.key==='ArrowRight')keysHeld.right=true;
  if(e.key===' '&&G.stuck){
    G.stuck=false;
    const _lsp=430+G.level*30;G.bvx=(Math.random()-0.5)*200;G.bvy=-Math.sqrt(Math.max(40000,_lsp*_lsp-G.bvx*G.bvx)); // space launch matches tap-launch speed for the level
  }
