function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#0d0a14');bg.addColorStop(1,'#1a0f24');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  // living embers behind the bricks (additive glow)
  ctx.save();ctx.globalCompositeOperation='lighter';
  for(const e of EMBERS){
    const ey=H-((G.time*e.s+e.o)%(H+30));
    const ex=e.x*W+Math.sin(G.time*0.9+e.ph)*10;
    ctx.globalAlpha=0.15+0.11*Math.sin(G.time*2+e.ph);
    ctx.fillStyle='#ff9a3c';
    ctx.beginPath();ctx.arc(ex,ey,e.r,0,Math.PI*2);ctx.fill();
  }
  ctx.restore();ctx.globalAlpha=1;
  ctx.save();
  if(G.shake>0)ctx.translate((Math.random()-0.5)*G.shake*12,(Math.random()-0.5)*G.shake*12);
  // bricks
  for(const b of G.bricks){
    const flash=b.hit>0;
    const g=ctx.createLinearGradient(0,b.y,0,b.y+b.h);
    g.addColorStop(0,flash?'#fff':`hsl(${b.hue},70%,55%)`);
    g.addColorStop(1,`hsl(${b.hue},70%,38%)`);
    ctx.fillStyle=g;
    ctx.beginPath();ctx.roundRect(b.x,b.y,b.w,b.h,6);ctx.fill();
    if(b.maxHp>1&&b.hp===2){
      ctx.strokeStyle='#fff';ctx.lineWidth=2;
      ctx.beginPath();ctx.roundRect(b.x+2,b.y+2,b.w-4,b.h-4,5);ctx.stroke();
    }
    ctx.fillStyle='rgba(255,255,255,0.3)';
    ctx.fillRect(b.x+5,b.y+4,b.w-10,4);
  }
  // paddle
  const py=H-60;
  const pg=ctx.createLinearGradient(0,py,0,py+PH);
  pg.addColorStop(0,'#7fd4ff');pg.addColorStop(1,'#2a78b8');
  ctx.fillStyle=pg;
  ctx.beginPath();ctx.roundRect(G.px-PW/2,py,PW,PH,8);ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.35)';
  ctx.fillRect(G.px-PW/2+8,py+3,PW-16,4);
