  for(const pk of G.pickups){
    ctx.save();ctx.shadowColor='#ffb03a';ctx.shadowBlur=16;
    ctx.fillStyle='#ffb03a';
    ctx.beginPath();ctx.arc(pk.x,pk.y,10,0,Math.PI*2);ctx.fill();
    ctx.restore();
    ctx.font='13px system-ui';ctx.textAlign='center';
    ctx.fillText('💥',pk.x,pk.y+5);ctx.textAlign='left';
  }
  // ball (glow — bigger, hotter while Blast Ball is active)
  const g=ctx.createRadialGradient(G.bx-3,G.by-3,2,G.bx,G.by,BR);
  g.addColorStop(0,'#fff');g.addColorStop(0.4,'#ffd23f');g.addColorStop(1,'#ff6a00');
  ctx.fillStyle=g;
  ctx.shadowColor=G.blastT>0?'#ff4a1a':'#ffb03a';ctx.shadowBlur=G.blastT>0?24:14;
  ctx.beginPath();ctx.arc(G.bx,G.by,BR,0,Math.PI*2);ctx.fill();
  ctx.shadowBlur=0;
  if(G.blastT>0&&G.state==='play'){
    ctx.fillStyle='#ffb03a';ctx.font='900 15px system-ui';ctx.textAlign='center';
    ctx.fillText(`💥 BLAST BALL ${G.blastT.toFixed(0)}s — double brick damage!`,W/2,44);
    ctx.textAlign='left';
  }
  // stuck hint
  if(G.stuck&&G.state==='play'){
    ctx.fillStyle='rgba(255,255,255,0.7)';ctx.font='900 16px system-ui';ctx.textAlign='center';
    ctx.fillText('TAP TO LAUNCH!',W/2,H<500?H-104:H*0.6); // [landscape fix] keep clear of the lowered brick wall on short screens
    ctx.textAlign='left';
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
