#pauseBtn,#muteBtn{position:fixed;top:60px;z-index:15;width:44px;height:44px;border-radius:50%;border:2px solid rgba(255,255,255,.35);background:rgba(0,0,0,.55);color:#fff;font-size:19px;cursor:pointer}
#pauseBtn{right:12px}#muteBtn{right:64px}

