scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);
  try{if(G.items)for(const it of G.items)it.x=laneX(it.lane);}catch(e){} // keep live items in their lanes after rotate/resize
}
addEventListener('resize',resize);resize();
let AC=null;
let muted=false;try{muted=localStorage.getItem('fb_mute')==='1';}catch(e){}
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(muted)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  spark(){tone(800+Math.random()*300,1200,0.08,'sine',0.09);},
  jump(){tone(400,700,0.1,'square',0.08);},
  swipe(){tone(500,700,0.06,'sine',0.06);},
  die(){tone(400,80,0.4,'sawtooth',0.15);},
  click(){tone(600,600,0.06,'square',0.1);}
};
const G={state:'title',score:0,best:0,combo:1,comboT:0,
  lane:1,laneX:0,py:0,vy:0,jumping:false,
  items:[],spawnT:0.7,speed:380,dist:0,time:0,shake:0,dead:false,sliding:false,slideT:0,slideQ:false};
try{G.best=parseInt(localStorage.getItem('sparkrun_best')||'0',10)||0;}catch(e){}
function laneX(i){return W*0.2+i*W*0.3;}
const GY=()=>H*0.75;
function reset(){
  setPaused(false);G.score=0;G.combo=1;G.comboT=0;G.lane=1;G.laneX=laneX(1);
  G.py=GY();G.vy=0;G.jumping=false;G.items=[];
  G.spawnT=0.6;G.speed=380;G.dist=0;G.time=0;G.shake=0;G.dead=false;G.sliding=false;G.slideT=0;G.slideQ=false;
  updateHUD();
  document.getElementById('best').textContent='🏆 '+G.best;
}
function updateHUD(){
  document.getElementById('score').textContent='⭐ '+G.score+' • '+Math.floor(G.dist)+'m';
  document.getElementById('combo').textContent='🔥 x'+G.combo;
}
function spawnRow(){
  // spawn items in lanes
  const r=Math.random();
  const lanes=[0,1,2].sort(()=>Math.random()-0.5);
  if(r<0.5){
    // sparks in 1-2 lanes
    for(const l of lanes.slice(0,1+Math.floor(Math.random()*2))){
      G.items.push({type:'spark',lane:l,x:laneX(l),y:-30,t:Math.random()*6});
    }
  }else if(r>=0.80&&r<0.93&&G.dist>30){
    // overhead ember banner in one lane — must be SLID under (sparks in the others)
    const ol=lanes[0];
    G.items.push({type:'banner',lane:ol,x:laneX(ol),y:-40,t:0});
    for(const l of lanes.slice(1)){
      if(Math.random()<0.7)G.items.push({type:'spark',lane:l,x:laneX(l),y:-30-Math.random()*60,t:Math.random()*6});
    }
  }else if(r<0.8){
    // obstacle + sparks
    const ol=lanes[0];
    G.items.push({type:Math.random()<0.5?'rock':'firewall',lane:ol,x:laneX(ol),y:-40,t:0});
    for(const l of lanes.slice(1)){
      if(Math.random()<0.7)G.items.push({type:'spark',lane:l,x:laneX(l),y:-30-Math.random()*60,t:Math.random()*6});
    }
  }else{
    // spark arc (jump over low firewall)
    const ol=lanes[0];
    G.items.push({type:'firewall',lane:ol,x:laneX(ol),y:-40,t:0,low:true});
    for(let i=0;i<4;i++){
      G.items.push({type:'spark',lane:ol,x:laneX(ol),y:-60-i*44,t:i});
    }
  }
}
function moveLane(d){
  if(G.state!=='play'||G.dead||G.paused)return;
  const nl=Math.max(0,Math.min(2,G.lane+d));
  if(nl!==G.lane){G.lane=nl;sfx.swipe();}
}
function doDrop(){
  if(G.state!=='play'||G.dead||G.paused||!G.jumping)return;
  G.vy=Math.max(G.vy,950);sfx.swipe(); // genre-standard fast-fall: swipe down mid-jump
}
function doSlide(){
  if(G.state!=='play'||G.dead||G.paused)return;
  if(G.jumping){G.slideQ=true;doDrop();return;} // slam down, then slide on landing
  G.sliding=true;G.slideT=0.6;sfx.swipe();
}
function doDown(){doSlide();} // doSlide itself branches: air = fast-drop + queued slide, ground = slide now
function doJump(){
  if(G.state!=='play'||G.dead||G.paused||G.jumping)return;
  G.jumping=true;G.vy=-760;G.sliding=false;G.slideT=0;G.slideQ=false;sfx.jump();
}
// swipe
let sx=null,sy=null;
canvas.addEventListener('pointerdown',e=>{sx=e.clientX;sy=e.clientY;});
canvas.addEventListener('pointerup',e=>{
  if(sx===null)return;
  const dx=e.clientX-sx,dy=e.clientY-sy;
  if(Math.abs(dx)>Math.abs(dy)&&Math.abs(dx)>30)moveLane(dx>0?1:-1);
  else if(dy<-40)doJump();
  else if(dy>40)doDown();
  sx=sy=null;
});
addEventListener('keydown',e=>{
  if(e.key==='ArrowLeft')moveLane(-1);
  if(e.key==='ArrowRight')moveLane(1);
  if(e.key==='ArrowDown'){doDown();e.preventDefault();}
  if(e.key===' '||e.key==='ArrowUp'){doJump();e.preventDefault();}
});
const particles=[],floaters=[];
for(let i=0;i<80;i++)particles.push({a:false});
for(let i=0;i<10;i++)floaters.push({a:false});
function spawnText(x,y,txt,color){
  const f=floaters.find(f=>!f.a);if(!f)return;
  f.a=true;f.x=x;f.y=y;f.txt=txt;f.color=color;f.life=1;
}
function update(dt){
  G.time+=dt;G.shake=Math.max(0,G.shake-dt*3);
  G.speed=Math.min(750,380+G.dist*0.5);
  G.dist+=G.speed*dt/60;
  G.comboT-=dt;if(G.comboT<=0)G.combo=1;
  const _di=Math.floor(G.dist);if(_di!==G._di){G._di=_di;updateHUD();} // live distance in HUD (runner standard)
  // smooth lane
  G.laneX+=(laneX(G.lane)-G.laneX)*Math.min(1,dt*12);
  // slide timer
  if(G.slideT>0){G.slideT-=dt;if(G.slideT<=0)G.sliding=false;}
  // jump physics
  if(G.jumping){
    G.vy+=2200*dt;G.py+=G.vy*dt;
    if(G.py>=GY()){G.py=GY();G.vy=0;G.jumping=false;if(G.slideQ){G.slideQ=false;G.sliding=true;G.slideT=0.6;}}
  }
  // spawn
  G.spawnT-=dt*G.speed/380;
  if(G.spawnT<=0){spawnRow();G.spawnT=Math.max(0.45,0.85-G.dist*0.003)+Math.random()*0.3;}
  const px=G.laneX,py=G.py-24;
  for(let i=G.items.length-1;i>=0;i--){
    const it=G.items[i];
    it.y+=G.speed*dt;it.t+=dt*4;
    if(it.y>H+60){G.items.splice(i,1);continue;}
    const dx=Math.abs(it.x-px);
    if(it.type==='spark'){
      if(dx<36&&Math.abs(it.y-py)<44){
        G.items.splice(i,1);
        const pts=10*G.combo;
        G.score+=pts;G.combo=Math.min(10,G.combo+1);G.comboT=2.5;
        sfx.spark();updateHUD();
        spawnText(it.x,it.y-20,'+'+pts,'#ffd23f');
        for(let j=0;j<5;j++){const p=particles.find(p=>!p.a);if(!p)break;
          p.a=true;p.x=it.x;p.y=it.y;const a=Math.random()*Math.PI*2;
          p.vx=Math.cos(a)*160;p.vy=Math.sin(a)*160;
          p.life=0.35;p.max=0.35;p.color='#ffd23f';p.size=3;}
      }
    }else if(it.type==='banner'){
      // overhead banner: judged at the moment it reaches the runner's depth.
      // Its underside hangs 38px above the ground line — a standing or jumping
      // runner's head pokes into it; only a sliding runner (top ~24px above
      // the ground line) slips under. Sparks/ground rules are untouched.
      if(Math.abs(it.y-GY())<30&&dx<54&&!G.sliding){die();return;}
    }else{
      // obstacle
      const hitW=it.type==='firewall'?70:54;
      const hitH=it.type==='firewall'?(it.low?40:90):60;
      const oy=it.y+28-hitH; // obstacle top follows its falling y (was fixed ground line = instant kill on spawn)
      if(dx<hitW/2+16&&py+20>oy&&py-20<oy+hitH){
        die();return;
      }
    }
  }
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  for(const f of floaters){if(!f.a)continue;f.y-=36*dt;f.life-=dt;if(f.life<=0)f.a=false;}
}
function die(){
  if(G.dead)return;
  G.dead=true;sfx.die();G.shake=0.5;
  const isBest=G.score>G.best;
  if(isBest){G.best=G.score;try{localStorage.setItem('sparkrun_best',String(G.best));}catch(e){}}
  setTimeout(()=>{
    showOverlay('💥 WIPED OUT!',
      `${isBest?'<p style="color:#ffd23f;font-weight:900">🏆 NEW BEST!</p>':''}<p style="font-size:26px;font-weight:900">Score: ${G.score}</p><p>Distance: ${Math.floor(G.dist)}m</p><p>Best: ${G.best}</p>`,
      '🔥 Fire Safety: Collect good habits!',
      '↻ RUN AGAIN',()=>{reset();G.state='play';});
  },700);
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();reset();G.state='play';overlay.classList.add('hidden');}
obtn.onclick=()=>{showMathGate();};

// --- Overhaul: living ember background (24 cheap additive particles, deterministic from G.time) ---
function drawEmbers(){
  ctx.save();ctx.globalCompositeOperation='lighter';
  const maxW=Math.max(W,1),maxH=Math.max(H,1);
  for(let i=0;i<24;i++){
    const sp=14+(i%5)*7,off=(i*197)%maxH;
    const ex=((i*173)%maxW)+Math.sin(G.time*0.7+i)*12;
    const ey=maxH-((G.time*sp+off)%(maxH+30));
    ctx.globalAlpha=Math.max(0.08,0.35+0.3*Math.sin(G.time*3+i*1.7));
    ctx.fillStyle=i%3?'#ff8a3a':'#ffd23f';
    ctx.shadowBlur=0;
    ctx.beginPath();ctx.arc(ex,ey,1.6+(i%3),0,Math.PI*2);ctx.fill();
  }
  ctx.restore();
}
function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#0d1420');bg.addColorStop(1,'#141a2a');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  drawEmbers();
  ctx.save();
  if(G.shake>0)ctx.translate((Math.random()-0.5)*G.shake*14,(Math.random()-0.5)*G.shake*14);
  const gy=GY();
  // lanes
  for(let i=0;i<3;i++){
    const lx=laneX(i);
    ctx.fillStyle=i===G.lane?'rgba(255,210,63,0.08)':'rgba(255,255,255,0.03)';
    ctx.fillRect(lx-W*0.13,0,W*0.26,H);
  }
  // lane dividers (scrolling)
  ctx.strokeStyle='rgba(255,255,255,0.12)';ctx.lineWidth=3;ctx.setLineDash([24,24]);
  const off=(G.dist*40)%48;
  for(let i=0;i<2;i++){
    const lx=W*0.2+(i+0.5)*W*0.3;
    ctx.beginPath();ctx.moveTo(lx,-48+off);ctx.lineTo(lx,H);ctx.stroke();
  }
  ctx.setLineDash([]);
  // ground line
  ctx.fillStyle='#2a3a4a';ctx.fillRect(0,gy,W,H-gy);
  // items
  for(const it of G.items){
    if(it.type==='spark'){
      const bob=Math.sin(it.t)*5;
      ctx.save();ctx.translate(it.x,it.y+bob);
      const tw=0.7+Math.sin(it.t*2)*0.3;
      ctx.scale(tw,1);
      const g=ctx.createRadialGradient(-4,-4,2,0,0,14);
      g.addColorStop(0,'#fff');g.addColorStop(0.5,'#ffd23f');g.addColorStop(1,'#a37a00');
      ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,13,0,Math.PI*2);ctx.fill();
      ctx.restore();
    }else if(it.type==='banner'){
      // overhead ember banner: a leafy branch strung across the lane, drawn in
      // the game's flat shapes + ember palette. Bar bottom sits at it.y-44 —
      // level with a standing runner's head, well above a sliding one.
      const topY=it.y-84,botY=it.y-44,cx2=it.x;
      ctx.strokeStyle='rgba(90,60,30,0.85)';ctx.lineWidth=3;
      ctx.beginPath();ctx.moveTo(cx2-42,topY);ctx.lineTo(cx2-42,it.y-150);ctx.moveTo(cx2+42,topY);ctx.lineTo(cx2+42,it.y-150);ctx.stroke();
      ctx.fillStyle='#5a3a1e';
      ctx.beginPath();ctx.roundRect(cx2-46,topY,92,14,7);ctx.fill();
      ctx.fillStyle='#2e7d32';
      for(let k=-2;k<=2;k++){
        ctx.beginPath();ctx.ellipse(cx2+k*18,botY+6,9,13,0,0,Math.PI*2);ctx.fill();
      }
      ctx.fillStyle='#ff7a2a';
      for(let k=-1;k<=1;k++){
        const fl=Math.sin(it.t*3+k)*2;
        ctx.beginPath();ctx.arc(cx2+k*26,botY+12+fl,4.5,0,Math.PI*2);ctx.fill();
      }
      ctx.fillStyle='#ffd23f';ctx.font='900 11px system-ui';ctx.textAlign='center';
      ctx.fillText('▼ SLIDE ▼',cx2,topY-6);ctx.textAlign='left';
    }else if(it.type==='rock'){
      const baseY=it.y+28;
      ctx.fillStyle='#4a4a5a';
      ctx.beginPath();
      ctx.moveTo(it.x-27,baseY);ctx.lineTo(it.x,baseY-60);ctx.lineTo(it.x+27,baseY);ctx.closePath();ctx.fill();
      ctx.fillStyle='#6a6a7a';
      ctx.beginPath();
      ctx.moveTo(it.x-14,baseY);ctx.lineTo(it.x,baseY-44);ctx.lineTo(it.x+6,baseY);ctx.closePath();ctx.fill();
    }else{
      // firewall
      const fh=it.low?40:90;
      const baseY=it.y+28;
      const fg=ctx.createLinearGradient(0,baseY-fh,0,baseY);
      fg.addColorStop(0,'rgba(255,210,63,0.9)');fg.addColorStop(0.5,'rgba(255,106,0,0.9)');fg.addColorStop(1,'rgba(200,40,0,0.9)');
      ctx.fillStyle=fg;
      const wob=Math.sin(it.t*2)*6;
      ctx.beginPath();
      ctx.moveTo(it.x-35,baseY);
      ctx.quadraticCurveTo(it.x-35+wob,baseY-fh/2,it.x-20,baseY-fh);
      ctx.quadraticCurveTo(it.x,baseY-fh*1.2,it.x+20,baseY-fh);
      ctx.quadraticCurveTo(it.x+35+wob,baseY-fh/2,it.x+35,baseY);
      ctx.closePath();ctx.fill();
    }
  }
  // player
  if(!G.dead){
    const px=G.laneX,py=G.py;
    const squash=G.jumping?1:1+Math.sin(G.time*14)*0.04;
    ctx.save();ctx.translate(px,G.sliding?py+12:py);ctx.scale(G.sliding?1.3:1,G.sliding?0.52:squash);
    const g=ctx.createRadialGradient(-7,-30,4,0,-24,20);
    g.addColorStop(0,'#ffe9a0');g.addColorStop(0.5,'#ff7a2a');g.addColorStop(1,'#d42a1a');
    ctx.shadowColor='#ff7a2a';ctx.shadowBlur=18;
    ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,-24,20,0,Math.PI*2);ctx.fill();
    ctx.shadowBlur=0;
    ctx.fillStyle='#2b1a0e';
    ctx.beginPath();ctx.arc(-6,-28,3.5,0,Math.PI*2);ctx.arc(6,-28,3.5,0,Math.PI*2);ctx.fill();
    // spark trail
    ctx.fillStyle='rgba(255,210,63,0.5)';
    ctx.beginPath();ctx.arc(-8,-8,4,0,Math.PI*2);ctx.arc(8,-6,3,0,Math.PI*2);ctx.fill();
    ctx.restore();
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  ctx.textAlign='center';
  for(const f of floaters){
    if(!f.a)continue;
    ctx.globalAlpha=Math.min(1,f.life);
    ctx.font='900 20px system-ui';ctx.fillStyle='#000';
    ctx.fillText(f.txt,f.x+2,f.y+2);ctx.fillStyle=f.color;ctx.fillText(f.txt,f.x,f.y);
  }
  ctx.globalAlpha=1;ctx.textAlign='left';
  ctx.restore();
  if(G.state==='play'&&G.dist<20){
    ctx.fillStyle='rgba(255,255,255,0.8)';ctx.font='900 17px system-ui';ctx.textAlign='center';
    ctx.fillText('SWIPE ◀ ▶ TO SWITCH • SWIPE UP TO JUMP',W/2,H*0.4);
    ctx.textAlign='left';
  }
}
function setPaused(v){G.paused=!!v;const b=document.getElementById('pauseBtn');if(b)b.textContent=G.paused?'▶':'⏸';}
function togglePause(){if(G.state!=='play')return;setPaused(!G.paused);}
document.getElementById('pauseBtn').addEventListener('click',()=>{togglePause();});
document.getElementById('muteBtn').addEventListener('click',function(){muted=!muted;this.textContent=muted?'🔇':'🔊';try{localStorage.setItem('fb_mute',muted?'1':'0');}catch(e){}});
document.getElementById('muteBtn').textContent=muted?'🔇':'🔊';
addEventListener('keydown',e=>{if(e.key==='p'||e.key==='P'||e.key==='Escape')togglePause();});
function drawPaused(){ctx.fillStyle='rgba(5,3,10,0.72)';ctx.fillRect(0,0,W,H);ctx.fillStyle='#ffd76a';ctx.font='900 34px system-ui';ctx.textAlign='center';ctx.fillText('⏸ PAUSED',W/2,H/2);ctx.fillStyle='#fff';ctx.font='700 16px system-ui';ctx.fillText('Tap ⏸ or press P to resume',W/2,H/2+34);ctx.textAlign='left';}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(G.state==='play'&&!G.dead&&!G.paused)update(dt);else G.time+=dt;
  render();if(G.paused)drawPaused();
  requestAnimationFrame(loop);
}
document.getElementById('best').textContent='🏆 '+G.best;
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Spark Trail' — Sizzle's Spark Run's own
   track. Synthesized Web Audio only. 142 BPM, F# minor: a bright sawtooth
   lead leaves sparks over a galloping bass — always leaning forward.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Freeze gate CONFIRMED at insertion (2026-10-15): script-scope `muted` mutes, G.paused pauses, and music only
   plays while G.state==='play' — all read from this shell's own code.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-40-sizzles-spark-run.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
// Freeze gate (insertion-confirmed 2026-10-15): hard-wired to this shell's
// own confirmed globals — muted / G.paused / G.state. try/catch kept so it can never throw.
const _mGate=()=>{try{return !!(muted||G.paused||G.state!=='play');}catch(e){return false;}};
const MUS={on:false,step:0,nextT:0,BPM:142,
 BASS:[42,0,54,42,42,0,54,0, 38,0,50,38,38,0,50,0, 45,0,57,45,45,0,57,0, 40,0,52,40,40,0,52,0],
 LEAD:[78,0,81,0,85,0,81,0, 81,0,78,0,74,0,76,0, 78,0,81,0,85,0,88,0, 85,0,83,0,81,0,78,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(_mGate()){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.11,'sawtooth',0.055,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.14,'sawtooth',0.045,d);
  if(s%8===0||s%8===4)tone(120,45,0.11,'sine',0.13,d); // kick
  if(s%8===2||s%8===6)tone(190,120,0.07,'triangle',0.07,d); // tone-only snare
  if(s%2===0)tone(6900,6900,0.015,'square',0.008,d); // hat click
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

