let AC=null;
let muted=false;try{muted=localStorage.getItem('fb_mute')==='1';}catch(e){}
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(muted)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  star(){tone(900,1400,0.1,'sine',0.1);},
  goal(){[523,659,784,1047].forEach((f,i)=>tone(f,f,0.2,'triangle',0.15,i*0.09));},
  lava(){tone(300,80,0.4,'sawtooth',0.16);},
  bump(){tone(250,180,0.06,'square',0.07);},
  click(){tone(600,600,0.06,'square',0.1);}
};
const G={state:'title',level:1,score:0,
  grid:[],bx:0,by:0,bvx:0,bvy:0,
  stars:[],start:{},goal:{},time:0,shake:0,dead:false};
function initLevel(n){
  const mz=MAZES[n-1];
  MH=mz.length;MW=mz[0].length;
  layout();
  G.level=n;G.grid=[];G.stars=[];G.dead=false;G.time=0;G.elapsed=0;G.shake=0;setPaused(false);
  G.bvx=0;G.bvy=0;
  for(let r=0;r<MH;r++){
    G.grid[r]=[];
    for(let c=0;c<MW;c++){
      const ch=mz[r][c];
      G.grid[r][c]=ch;
      if(ch==='4'){G.start={r,c};G.bx=c;G.by=r;}
      else if(ch==='5')G.goal={r,c};
      else if(ch==='3')G.stars.push({r,c,taken:false,t:Math.random()*6});
    }
  }
  document.getElementById('level').textContent=`LV ${n}/11`;
  document.getElementById('stars').textContent=`⭐ 0/${G.stars.length}`;
  updateHUD();
}
function updateHUD(){document.getElementById('score').textContent='⭐ '+G.score;}
function cellXY(r,c){return{x:OX+(c+0.5)*CELL,y:OY+(r+0.5)*CELL};}
function cellAt(x,y){
  const c=Math.floor((x-OX)/CELL),r=Math.floor((y-OY)/CELL);
  if(r<0||r>=MH||c<0||c>=MW)return '1';
  return G.grid[r][c];
}
// tilt input
let tiltX=0,tiltY=0,dragging=false,lx=0,ly=0;
canvas.addEventListener('pointerdown',e=>{if(G.paused)return;dragging=true;lx=e.clientX;ly=e.clientY;canvas.setPointerCapture(e.pointerId);});
canvas.addEventListener('pointermove',e=>{
  if(!dragging||G.state!=='play'||G.paused)return;
  tiltX=Math.max(-1,Math.min(1,(e.clientX-lx)/60));
  tiltY=Math.max(-1,Math.min(1,(e.clientY-ly)/60));
});
canvas.addEventListener('pointerup',()=>{dragging=false;tiltX=0;tiltY=0;});
canvas.addEventListener('pointercancel',()=>{dragging=false;tiltX=0;tiltY=0;});
// Real device tilt (leftover-fix), following the game-08 pattern: a plain
// deviceorientation listener feeds devTilt, and iOS permission is requested
// from a user tap (see requestTiltPermission below). Tilt is ADDITIONAL —
// drag and keys keep working exactly as before, and where the API or
// permission is absent this is a graceful no-op (devTilt stays 0).
const devTilt={x:0,y:0,seen:false};
addEventListener('deviceorientation',e=>{
  if(!e||(e.gamma==null&&e.beta==null))return;
  devTilt.seen=true;
  devTilt.x=Math.max(-1,Math.min(1,(e.gamma||0)/25));
  // portrait phones rest around beta≈45° in the hand; use that as level
  devTilt.y=Math.max(-1,Math.min(1,((e.beta||0)-45)/25));
});
function requestTiltPermission(){
  try{
    if(typeof DeviceOrientationEvent!=='undefined'&&typeof DeviceOrientationEvent.requestPermission==='function'){
      const r=DeviceOrientationEvent.requestPermission();
      if(r&&typeof r.catch==='function')r.catch(()=>{});
    }
  }catch(e){}
}
const keys={};
addEventListener('keydown',e=>keys[e.key.toLowerCase()]=true);
addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
addEventListener('blur',()=>{for(const k in keys)keys[k]=false;tiltX=0;tiltY=0;dragging=false;}); // missed keyup / lost pointer left the ball driving itself
const particles=[];
for(let i=0;i<60;i++)particles.push({a:false});
function update(dt){
  G.time+=dt;G.elapsed=(G.elapsed||0)+dt;G.shake=Math.max(0,G.shake-dt*3);
  // input accel
  let ax=(tiltX+devTilt.x)*1400,ay=(tiltY+devTilt.y)*1400; // drag tilt + real device tilt (either or both)
  if(keys['arrowleft']||keys['a'])ax-=1400;
  if(keys['arrowright']||keys['d'])ax+=1400;
  if(keys['arrowup']||keys['w'])ay-=1400;
  if(keys['arrowdown']||keys['s'])ay+=1400;
  G.bvx+=ax*dt;G.bvy+=ay*dt;
  // friction
  G.bvx*=Math.pow(0.12,dt);G.bvy*=Math.pow(0.12,dt);
  const maxV=380;
  const sp=Math.hypot(G.bvx,G.bvy);
  if(sp>maxV){G.bvx*=maxV/sp;G.bvy*=maxV/sp;}
  // move with collision (circle vs grid)
  const R=CELL*0.28;
  let nx=G.bx+G.bvx*dt/CELL,ny=G.by+G.bvy*dt/CELL;
  // X collision
  const cx=OX+(nx+0.5)*CELL,cy=OY+(G.by+0.5)*CELL;
  const RD=R*0.72; // diagonal samples — cheap corner-clipping fix (was cardinal-only, ball overlapped wall corners)
  if(isWall(cx-R,cy)||isWall(cx+R,cy)||isWall(cx-RD,cy-RD)||isWall(cx+RD,cy-RD)||isWall(cx-RD,cy+RD)||isWall(cx+RD,cy+RD)){
    if(Math.abs(G.bvx)>70)sfx.bump();G.bvx*=-0.4;nx=G.bx;
  }else G.bx=nx;
  // Y collision
  const cx2=OX+(G.bx+0.5)*CELL,cy2=OY+(ny+0.5)*CELL;
  if(isWall(cx2,cy2-R)||isWall(cx2,cy2+R)||isWall(cx2-RD,cy2-RD)||isWall(cx2+RD,cy2-RD)||isWall(cx2-RD,cy2+RD)||isWall(cx2+RD,cy2+RD)){
    if(Math.abs(G.bvy)>70)sfx.bump();G.bvy*=-0.4;ny=G.by;
  }else G.by=ny;
  const px=OX+(G.bx+0.5)*CELL,py=OY+(G.by+0.5)*CELL;
  // lava check
  // lava kills on real overlap (centre + edge samples), not only when the centre crosses (ball could sit half-in lava, unharmed)
  const _lava=[cellAt(px,py),cellAt(px-R*0.55,py),cellAt(px+R*0.55,py),cellAt(px,py-R*0.55),cellAt(px,py+R*0.55)].includes('2');
  if(_lava&&!G.dead){
    G.dead=true;sfx.lava();G.shake=0.5;
    for(let i=0;i<16;i++){const p=particles.find(p=>!p.a);if(!p)break;
      p.a=true;p.x=px;p.y=py;const a=Math.random()*Math.PI*2;
      p.vx=Math.cos(a)*250;p.vy=Math.sin(a)*250;
      p.life=0.6;p.max=0.6;p.color='#ff4a00';p.size=4;}
    setTimeout(()=>{
      showOverlay('🔥 BURNED!',
        `<p>You fell in lava! Score: ${G.score}</p>`,
        '🔥 Fire Safety: Stay away from lava!',
        '↻ TRY AGAIN',()=>{initLevel(G.level);G.state='play';});
    },600);
    return;
  }
  // stars
  for(const s of G.stars){
    s.t+=dt*3;
    if(!s.taken&&s.r===Math.round(G.by)&&s.c===Math.round(G.bx)){
      const sp2=cellXY(s.r,s.c);
      if(Math.hypot(px-sp2.x,py-sp2.y)<CELL*0.5){
        s.taken=true;sfx.star();G.score+=50;updateHUD();
        const n=G.stars.filter(x=>x.taken).length;
        document.getElementById('stars').textContent=`⭐ ${n}/${G.stars.length}`;
      }
    }
  }
  // goal
  if(Math.round(G.by)===G.goal.r&&Math.round(G.bx)===G.goal.c){
    const gp=cellXY(G.goal.r,G.goal.c);
    if(Math.hypot(px-gp.x,py-gp.y)<CELL*0.5){
      const allStars=G.stars.every(s=>s.taken);
      if(allStars){
        sfx.goal();G.score+=200;updateHUD();
        setTimeout(()=>{
          if(G.level>=11){
            showOverlay('🏆 MAZE MASTER!',
              `<p style="font-size:24px;font-weight:900">Final Score: ${G.score}</p><p>All 11 mazes conquered!</p><p>Final maze time: ${(G.elapsed||0).toFixed(1)}s</p>`,
              '🔥 Fire Safety: You\'re a champion!',
              '↻ PLAY AGAIN',()=>{G.score=0;initLevel(1);G.state='play';});
          }else{
            showOverlay(`⭐ LEVEL ${G.level} CLEAR!`,
              `<p>+200 pts!</p><p>Score: ${G.score}</p><p>Maze time: ${(G.elapsed||0).toFixed(1)}s</p>`,
              '🔥 Fire Safety: Roll with it!',
              '▶ NEXT MAZE',()=>{initLevel(G.level+1);G.state='play';});
          }
        },400);
        G.state='clear';
      }
    }
  }
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)p.a=false;}
}
function isWall(x,y){
  return cellAt(x,y)==='1';
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');showLevels();
  }else document.getElementById('ma').value='';
}
function showLevels(){
  otitle.innerHTML='🔥 PICK MAZE';
  let h='';
  for(let i=1;i<=11;i++)h+=`<button class="lvlBtn" onclick="event.stopPropagation();pickLevel(${i})">${i}</button>`;
  obody.innerHTML=`<p>Roll through and collect every star!</p><div id="lvlSel">${h}</div>`;
  obtn.style.display='none';
  overlay.classList.remove('hidden');
}
function pickLevel(n){requestTiltPermission();sfx.click();audio();G.score=0;initLevel(n);G.state='play';overlay.classList.add('hidden');}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;
  obtn.textContent=btn;obtn.style.display='';
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
obtn.onclick=()=>{requestTiltPermission();showMathGate();}; // PLAY tap: iOS tilt permission prompt lives here (user gesture)

// --- Overhaul: living ember background (24 cheap additive particles, deterministic from G.time) ---
function drawEmbers(){
  ctx.save();ctx.globalCompositeOperation='lighter';
  const maxW=Math.max(W,1),maxH=Math.max(H,1);
  for(let i=0;i<24;i++){
    const sp=14+(i%5)*7,off=(i*197)%maxH;
    const ex=((i*173)%maxW)+Math.sin(G.time*0.7+i)*12;
    const ey=maxH-((G.time*sp+off)%(maxH+30));
    ctx.globalAlpha=Math.max(0.08,0.35+0.3*Math.sin(G.time*3+i*1.7));
    ctx.fillStyle=i%3?'#ff8a3a':'#ffd23f';
    ctx.shadowBlur=0;
    ctx.beginPath();ctx.arc(ex,ey,1.6+(i%3),0,Math.PI*2);ctx.fill();
  }
  ctx.restore();
}
function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#241209');bg.addColorStop(0.6,'#140d08');bg.addColorStop(1,'#1c0a04');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  drawEmbers();
  ctx.save();
  if(G.shake>0)ctx.translate((Math.random()-0.5)*G.shake*12,(Math.random()-0.5)*G.shake*12);
  if(!G.grid.length){ctx.restore();return;}
  // tilt indicator
  if(G.state==='play'&&(tiltX||tiltY)){
    ctx.strokeStyle='rgba(255,210,63,0.5)';ctx.lineWidth=4;
    ctx.beginPath();ctx.moveTo(W/2,H-60);ctx.lineTo(W/2+tiltX*40,H-60+tiltY*40);ctx.stroke();
    ctx.fillStyle='rgba(255,210,63,0.3)';
    ctx.beginPath();ctx.arc(W/2,H-60,44,0,Math.PI*2);ctx.fill();
  }
  for(let r=0;r<MH;r++)for(let c=0;c<MW;c++){
    const ch=G.grid[r][c];
    const x=OX+c*CELL,y=OY+r*CELL;
    if(ch==='1'){
      const g=ctx.createLinearGradient(0,y,0,y+CELL);
      g.addColorStop(0,'#4a3a2a');g.addColorStop(1,'#2a1e12');
      ctx.fillStyle=g;ctx.fillRect(x,y,CELL,CELL);
      ctx.fillStyle='rgba(255,255,255,0.08)';ctx.fillRect(x+3,y+3,CELL-6,4);
    }else if(ch==='2'){
      const g=ctx.createLinearGradient(0,y,0,y+CELL);
      g.addColorStop(0,'#ff6a00');g.addColorStop(1,'#a32a00');
      ctx.fillStyle=g;ctx.fillRect(x,y,CELL,CELL);
      ctx.fillStyle='rgba(255,221,68,0.7)';
      ctx.beginPath();ctx.arc(x+CELL/2+Math.sin(G.time*6+c)*6,y+CELL/2,5,0,Math.PI*2);ctx.fill();
    }else{
      ctx.fillStyle='rgba(255,255,255,0.03)';ctx.fillRect(x,y,CELL,CELL);
    }
  }
  // stars
  for(const s of G.stars){
    if(s.taken)continue;
    const p=cellXY(s.r,s.c);
    const bob=Math.sin(s.t)*3;
    ctx.save();ctx.translate(p.x,p.y+bob);
    ctx.scale(Math.abs(Math.cos(s.t*0.5))*0.4+0.6,1);
    const g=ctx.createRadialGradient(-4,-4,2,0,0,12);
    g.addColorStop(0,'#fff');g.addColorStop(0.5,'#ffd23f');g.addColorStop(1,'#a37a00');
    ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,11,0,Math.PI*2);ctx.fill();
    ctx.restore();
  }
  // goal
  const gp=cellXY(G.goal.r,G.goal.c);
  const pulse=1+Math.sin(G.time*4)*0.1;
  ctx.save();ctx.translate(gp.x,gp.y);ctx.scale(pulse,pulse);
  ctx.fillStyle='rgba(76,175,80,0.3)';
  ctx.beginPath();ctx.arc(0,0,CELL*0.42,0,Math.PI*2);ctx.fill();
  ctx.font=`${CELL*0.5}px system-ui`;ctx.textAlign='center';
  ctx.fillText('🏁',0,CELL*0.18);ctx.textAlign='left';
  ctx.restore();
  // goal-gate feedback: how many stars are still needed (was silent — ball sat on goal, nothing happened)
  const _rem=G.stars.filter(s=>!s.taken).length;
  if(_rem>0){
    ctx.fillStyle='rgba(0,0,0,0.55)';ctx.font='900 12px system-ui';ctx.textAlign='center';
    const _bt=_rem+' ⭐ LEFT';const _bw=ctx.measureText(_bt).width+16;
    ctx.beginPath();ctx.roundRect(gp.x-_bw/2,gp.y-CELL*0.95,_bw,18,9);ctx.fill();
    ctx.fillStyle='#ffd23f';ctx.fillText(_bt,gp.x,gp.y-CELL*0.95+13);ctx.textAlign='left';
    if(Math.round(G.by)===G.goal.r&&Math.round(G.bx)===G.goal.c){
      ctx.fillStyle='#ffd23f';ctx.font='900 19px system-ui';ctx.textAlign='center';
      ctx.fillText('⭐ COLLECT ALL THE STARS FIRST!',W/2,OY-14);ctx.textAlign='left';
    }
  }
  // ball
  if(!G.dead){
    const bp=cellXY(G.bx,G.by);
    // use fractional position
    const fx=OX+(G.bx+0.5)*CELL,fy=OY+(G.by+0.5)*CELL;
    const R=CELL*0.28;
    const g=ctx.createRadialGradient(fx-R*0.3,fy-R*0.3,2,fx,fy,R);
    g.addColorStop(0,'#ffe9a0');g.addColorStop(0.5,'#ff6a1a');g.addColorStop(1,'#a32a10');
    ctx.shadowColor='#ff6a1a';ctx.shadowBlur=18;
    ctx.fillStyle=g;ctx.beginPath();ctx.arc(fx,fy,R,0,Math.PI*2);ctx.fill();
    ctx.shadowBlur=0;
    ctx.strokeStyle='rgba(255,255,255,0.4)';ctx.lineWidth=2;ctx.stroke();
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  ctx.restore();
  if(G.state==='play'&&G.time<4){
    ctx.fillStyle='rgba(255,255,255,0.75)';ctx.font='900 16px system-ui';ctx.textAlign='center';
    ctx.fillText(devTilt.seen?'TILT OR DRAG • COLLECT ALL ⭐ THEN 🏁':'DRAG TO TILT • COLLECT ALL ⭐ THEN 🏁',W/2,H-100);
    ctx.textAlign='left';
  }
}
function setPaused(v){G.paused=!!v;const b=document.getElementById('pauseBtn');if(b)b.textContent=G.paused?'▶':'⏸';}
function togglePause(){if(G.state!=='play')return;setPaused(!G.paused);}
document.getElementById('pauseBtn').addEventListener('click',()=>{togglePause();});
document.getElementById('muteBtn').addEventListener('click',function(){muted=!muted;this.textContent=muted?'🔇':'🔊';try{localStorage.setItem('fb_mute',muted?'1':'0');}catch(e){}});
document.getElementById('muteBtn').textContent=muted?'🔇':'🔊';
addEventListener('keydown',e=>{if(e.key==='p'||e.key==='P'||e.key==='Escape')togglePause();});
function drawPaused(){ctx.fillStyle='rgba(5,3,10,0.72)';ctx.fillRect(0,0,W,H);ctx.fillStyle='#ffd76a';ctx.font='900 34px system-ui';ctx.textAlign='center';ctx.fillText('⏸ PAUSED',W/2,H/2);ctx.fillStyle='#fff';ctx.font='700 16px system-ui';ctx.fillText('Tap ⏸ or press P to resume',W/2,H/2+34);ctx.textAlign='left';}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(G.state==='play'&&!G.dead&&!G.paused)update(dt);else G.time+=dt;
  render();if(G.paused)drawPaused();
  requestAnimationFrame(loop);
}
MW=11;MH=7;
