'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();
let AC=null;
let muted=false;try{muted=localStorage.getItem('fb_mute')==='1';}catch(e){}
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(muted)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  good(){tone(700,1000,0.12,'triangle',0.12);},
  perfect(){tone(900,1800,0.2,'sine',0.14);tone(1400,2200,0.14,'triangle',0.1,0.06);},
  miss(){tone(350,150,0.2,'sawtooth',0.12);},
  tick(){tone(500,500,0.04,'square',0.05);},
  click(){tone(600,600,0.06,'square',0.1);}
};
const G={state:'title',score:0,best:0,round:0,
  angle:0,speed:2,target:0,targetW:0.5,
  result:null,resultT:0,time:0,shake:0,combo:0};
try{G.best=parseInt(localStorage.getItem('speedtrap_best')||'0',10)||0;}catch(e){}
const ROUNDS=15;
function reset(){
  setPaused(false);G.score=0;G.round=0;G.combo=0;G.time=0;G.shake=0;
  nextRound();
  updateHUD();
  document.getElementById('best').textContent='🏆 '+G.best;
}
function nextRound(){
  G.round++;
  if(G.round>ROUNDS){gameOver();return;}
  G.angle=Math.random()*Math.PI*2;
  G.speed=2+G.round*0.35; // balance: was 7.5 rad/s at R10 — perfect window ~20ms, below one frame = luck, not skill
  G.target=Math.random()*Math.PI*2;
  G.targetW=Math.max(0.28,0.55-G.round*0.027);
  G.result=null;
  document.getElementById('round').textContent=`ROUND ${G.round}/${ROUNDS}`;
}
function updateHUD(){document.getElementById('score').textContent='⭐ '+G.score;}
function angDiff(a,b){
  let d=Math.abs(a-b)%(Math.PI*2);
  return d>Math.PI?Math.PI*2-d:d;
}
function doTap(){
  if(G.state!=='play'||G.result||G.paused)return;
  const d=angDiff(G.angle,G.target);
  const perfectW=G.targetW*0.4;
  if(d<perfectW){
    G.result='PERFECT!';G.resultT=1.2;
    const pts=100+G.combo*20;
    G.score+=pts;G.combo++;
    sfx.perfect();G.shake=0.2;
    spawnText(W/2,H*0.3,'PERFECT +'+pts,'#ffd23f');
    burst(W/2,H*0.42,'#ffd23f',16);
  }else if(d<G.targetW){
    G.result='GOOD';G.resultT=1;
    const pts=50+G.combo*10;
    G.score+=pts;G.combo++;
    sfx.good();
    spawnText(W/2,H*0.3,'+'+pts,'#4caf50');
    burst(W/2,H*0.42,'#4caf50',8);
  }else{
    G.result='MISS';G.resultT=1;
    G.score=Math.max(0,G.score-25);G.combo=0;
    sfx.miss();G.shake=0.3;
    spawnText(W/2,H*0.3,'MISS -25','#ff4a5a');
  }
  updateHUD();
  setTimeout(function adv(){if(G.state!=='play')return;if(G.paused){setTimeout(adv,300);return;}nextRound();},900); // a pause during the result beat no longer starts the next needle behind the veil
}
canvas.addEventListener('pointerdown',e=>{e.preventDefault();doTap();});
addEventListener('keydown',e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();doTap();}});
const particles=[],floaters=[];
for(let i=0;i<80;i++)particles.push({a:false});
for(let i=0;i<8;i++)floaters.push({a:false});
function burst(x,y,color,n){
  for(let i=0;i<n;i++){const p=particles.find(p=>!p.a);if(!p)break;
    const a=Math.random()*Math.PI*2;
    p.a=true;p.x=x;p.y=y;p.vx=Math.cos(a)*240;p.vy=Math.sin(a)*240;
    p.life=0.5;p.max=0.5;p.color=color;p.size=4;}
}
function spawnText(x,y,txt,color){
  const f=floaters.find(f=>!f.a);if(!f)return;
  f.a=true;f.x=x;f.y=y;f.txt=txt;f.color=color;f.life=1.2;
}
function update(dt){
  G.time+=dt;G.shake=Math.max(0,G.shake-dt*3);
  if(!G.result)G.angle+=G.speed*dt;
  const _tickStep=Math.floor(G.angle/(Math.PI/2)); // tick 4x/rev (was 16x/rev — at speed that was a buzz, not a tick)
  if(G._tickStep!==_tickStep){G._tickStep=_tickStep;if(!G.result)sfx.tick();}
  G.resultT-=dt;
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  for(const f of floaters){if(!f.a)continue;f.y-=36*dt;f.life-=dt;if(f.life<=0)f.a=false;}
}
function gameOver(){
  G.state='over';
  const isBest=G.score>G.best;
  if(isBest){G.best=G.score;try{localStorage.setItem('speedtrap_best',String(G.best));}catch(e){}}
  setTimeout(()=>{
    const grade=G.score>=800?'🏆 LIGHTNING!':G.score>=500?'🥇 SHARP!':G.score>=250?'🥈 STEADY':'🥉 WARMING UP';
    showOverlay('⚡ GAME OVER',
      `${isBest?'<p style="color:#ffd23f;font-weight:900">🏆 NEW BEST!</p>':''}<p style="font-size:22px">${grade}</p><p style="font-size:26px;font-weight:900">Score: ${G.score}</p><p>Best: ${G.best}</p>`,
      '🔥 Fire Safety: React fast — but think first!',
      '↻ PLAY AGAIN',()=>{reset();G.state='play';});
  },500);
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();reset();G.state='play';overlay.classList.add('hidden');}
obtn.onclick=()=>{showMathGate();};

// --- Overhaul: living ember background (24 cheap additive particles, deterministic from G.time) ---
function drawEmbers(){
  ctx.save();ctx.globalCompositeOperation='lighter';
  const maxW=Math.max(W,1),maxH=Math.max(H,1);
  for(let i=0;i<24;i++){
    const sp=14+(i%5)*7,off=(i*197)%maxH;
    const ex=((i*173)%maxW)+Math.sin(G.time*0.7+i)*12;
    const ey=maxH-((G.time*sp+off)%(maxH+30));
    ctx.globalAlpha=Math.max(0.08,0.35+0.3*Math.sin(G.time*3+i*1.7));
    ctx.fillStyle=i%3?'#ff8a3a':'#ffd23f';
    ctx.shadowBlur=0;
    ctx.beginPath();ctx.arc(ex,ey,1.6+(i%3),0,Math.PI*2);ctx.fill();
  }
  ctx.restore();
}
function render(){
  const bg=ctx.createRadialGradient(W/2,H*0.42,50,W/2,H*0.42,Math.max(W,H)*0.7);
  bg.addColorStop(0,'#141a30');bg.addColorStop(1,'#0d1420');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  drawEmbers();
  ctx.save();
  if(G.shake>0)ctx.translate((Math.random()-0.5)*G.shake*12,(Math.random()-0.5)*G.shake*12);
  const cx=W/2,cy=H*0.42,R=Math.min(W,H)*0.32;
  // dial
  ctx.fillStyle='rgba(255,255,255,0.04)';
  ctx.beginPath();ctx.arc(cx,cy,R+24,0,Math.PI*2);ctx.fill();
  ctx.strokeStyle='rgba(255,255,255,0.15)';ctx.lineWidth=3;
  ctx.beginPath();ctx.arc(cx,cy,R+24,0,Math.PI*2);ctx.stroke();
  // ticks
  for(let i=0;i<24;i++){
    const a=i/24*Math.PI*2;
    ctx.strokeStyle='rgba(255,255,255,0.2)';ctx.lineWidth=2;
    ctx.beginPath();
    ctx.moveTo(cx+Math.cos(a)*(R+14),cy+Math.sin(a)*(R+14));
    ctx.lineTo(cx+Math.cos(a)*(R+24),cy+Math.sin(a)*(R+24));
    ctx.stroke();
  }
  // target zone
  ctx.strokeStyle='rgba(76,175,80,0.85)';ctx.lineWidth=22;ctx.lineCap='butt';
  ctx.beginPath();ctx.arc(cx,cy,R,G.target-G.targetW,G.target+G.targetW);ctx.stroke();
  // perfect zone
  ctx.strokeStyle='rgba(255,210,63,0.95)';ctx.lineWidth=22;
  ctx.beginPath();ctx.arc(cx,cy,R,G.target-G.targetW*0.3,G.target+G.targetW*0.3);ctx.stroke();
  // needle
  if(!G.result||G.resultT>0.6){
    const na=G.angle;
    ctx.strokeStyle='#fff';ctx.lineWidth=6;ctx.lineCap='round';
    ctx.beginPath();ctx.moveTo(cx,cy);
    ctx.lineTo(cx+Math.cos(na)*R,cy+Math.sin(na)*R);ctx.stroke();
    // tip
    ctx.shadowColor='#ff8a5a';ctx.shadowBlur=16;
    ctx.fillStyle='#ff4a5a';
    ctx.beginPath();ctx.arc(cx+Math.cos(na)*R,cy+Math.sin(na)*R,9,0,Math.PI*2);ctx.fill();
    ctx.shadowBlur=0;
  }
  // center
  const cg=ctx.createRadialGradient(cx-6,cy-6,3,cx,cy,26);
  cg.addColorStop(0,'#aee2ff');cg.addColorStop(1,'#2a5a89');
  ctx.fillStyle=cg;ctx.beginPath();ctx.arc(cx,cy,24,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#0d1420';ctx.font='900 20px system-ui';ctx.textAlign='center';
  ctx.fillText('⚡',cx,cy+7);ctx.textAlign='left';
  // result text
  if(G.result&&G.resultT>0){
    ctx.globalAlpha=Math.min(1,G.resultT*2);
    ctx.font='900 44px system-ui';ctx.textAlign='center';
    const col=G.result==='PERFECT!'?'#ffd23f':G.result==='GOOD'?'#4caf50':'#ff4a5a';
    ctx.fillStyle='#000';ctx.fillText(G.result,cx+3,cy+R+72);
    ctx.fillStyle=col;ctx.fillText(G.result,cx,cy+R+70);
    ctx.textAlign='left';ctx.globalAlpha=1;
  }
  // combo
  if(G.combo>1){
    ctx.fillStyle='#ffd23f';ctx.font='900 20px system-ui';ctx.textAlign='center';
    ctx.fillText(`🔥 COMBO x${G.combo}`,cx,cy-R-40);
    ctx.textAlign='left';
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  ctx.textAlign='center';
  for(const f of floaters){
    if(!f.a)continue;
    ctx.globalAlpha=Math.min(1,f.life);
    ctx.font='900 24px system-ui';ctx.fillStyle='#000';
    ctx.fillText(f.txt,f.x+2,f.y+2);ctx.fillStyle=f.color;ctx.fillText(f.txt,f.x,f.y);
  }
  ctx.globalAlpha=1;ctx.textAlign='left';
  ctx.restore();
  if(G.state==='play'&&G.round===1&&!G.result&&G.time<3){
    ctx.fillStyle='rgba(255,255,255,0.8)';ctx.font='900 18px system-ui';ctx.textAlign='center';
    ctx.fillText('TAP WHEN THE NEEDLE HITS GREEN!',W/2,H*0.85);
    ctx.textAlign='left';
  }
}
function setPaused(v){G.paused=!!v;const b=document.getElementById('pauseBtn');if(b)b.textContent=G.paused?'▶':'⏸';}
function togglePause(){if(G.state!=='play')return;setPaused(!G.paused);}
document.getElementById('pauseBtn').addEventListener('click',()=>{togglePause();});
document.getElementById('muteBtn').addEventListener('click',function(){muted=!muted;this.textContent=muted?'🔇':'🔊';try{localStorage.setItem('fb_mute',muted?'1':'0');}catch(e){}});
document.getElementById('muteBtn').textContent=muted?'🔇':'🔊';
addEventListener('keydown',e=>{if(e.key==='p'||e.key==='P'||e.key==='Escape')togglePause();});
function drawPaused(){ctx.fillStyle='rgba(5,3,10,0.94)';ctx.fillRect(0,0,W,H);ctx.fillStyle='#ffd76a';ctx.font='900 34px system-ui';ctx.textAlign='center';ctx.fillText('⏸ PAUSED',W/2,H/2);ctx.fillStyle='#fff';ctx.font='700 16px system-ui';ctx.fillText('Press P or tap ⏸ to resume — needle hidden, no peeking!',W/2,H/2+34);ctx.textAlign='left';}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(G.state==='play'&&!G.paused)update(dt);else G.time+=dt;
  render();if(G.paused)drawPaused();
  requestAnimationFrame(loop);
}
document.getElementById('best').textContent='🏆 '+G.best;
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Trap Sprung' — Ruko's Speed Trap's own
   track. Synthesized Web Audio only. 150 BPM, G minor: an urgent square
   arpeggio lead and a syncopated snare that lands where you don't expect it
   — sprung.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Freeze gate CONFIRMED at insertion (2026-10-15): script-scope `muted` mutes, G.paused pauses, and music only
   plays while G.state==='play' — all read from this shell's own code.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-42-rukos-speed-trap.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
// Freeze gate (insertion-confirmed 2026-10-15): hard-wired to this shell's
// own confirmed globals — muted / G.paused / G.state. try/catch kept so it can never throw.
const _mGate=()=>{try{return !!(muted||G.paused||G.state!=='play');}catch(e){return false;}};
const MUS={on:false,step:0,nextT:0,BPM:150,
 BASS:[43,43,0,43,43,0,43,0, 51,51,0,51,51,0,51,0, 46,46,0,46,46,0,46,0, 41,0,43,0,46,0,50,0],
 LEAD:[79,82,86,82,79,82,86,82, 75,79,82,87,82,79,75,79, 82,86,89,86,82,86,89,86, 81,84,89,84,81,84,81,84],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(_mGate()){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.11,'square',0.055,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.1,'square',0.04,d);
  if(s%8===0||s%8===4)tone(122,45,0.1,'sine',0.13,d); // kick
  if(s%8===3||s%8===6)tone(195,120,0.07,'triangle',0.08,d); // syncopated tone-only snare
  tone(7000,7000,0.012,'square',0.006,d); // hat click
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

/* fb-cycle2: in-play restart — the cluster button runs the game's own overlay reset path. */
(function(){var b=document.getElementById('restartBtn');if(!b)return;b.addEventListener('click',function(e){e.stopPropagation();if(typeof G==='undefined'||G.state!=='play')return;reset();G.state='play';});})();
(function(){function kev(type,key,code){var ev=new KeyboardEvent(type,{key:key,code:code||'',bubbles:true,cancelable:true});(document.body||window).dispatchEvent(ev);}function bind(el){var key=el.getAttribute('data-k'),code=el.getAttribute('data-c');var dn=function(e){e.preventDefault();e.stopPropagation();el.classList.add('on');try{el.setPointerCapture(e.pointerId);}catch(_){} kev('keydown',key,code);};var up=function(e){if(!el.classList.contains('on'))return;el.classList.remove('on');kev('keyup',key,code);};el.addEventListener('pointerdown',dn);el.addEventListener('pointerup',up);el.addEventListener('pointercancel',up);el.addEventListener('lostpointercapture',up);el.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();});el.addEventListener('contextmenu',function(e){e.preventDefault();});}document.querySelectorAll('#fbCtl .fbtn').forEach(bind);})();

