/* ---- banner (hub + content pages) ---- */
#fb-seasonal-banner{background:linear-gradient(90deg,#2a1052,#4b1d8f 45%,#2a1052);color:#ffe9d6;text-align:center;padding:12px 16px 11px;border-bottom:3px solid #ff8c1a;box-shadow:0 4px 24px rgba(124,58,237,.35);position:relative;z-index:60}
#fb-seasonal-banner .fb-sb-main{font-size:clamp(18px,3.6vw,26px);font-weight:900;letter-spacing:.5px;color:#ffb347;text-shadow:0 2px 14px rgba(255,140,26,.45);line-height:1.25}
#fb-seasonal-banner .fb-sb-sub{font-size:clamp(12px,2.6vw,14.5px);font-weight:600;color:#e9defc;margin-top:3px;line-height:1.4}
/* ---- decoration layers (never clickable, below menus) ---- */
#fb-seasonal-wall{position:fixed;inset:0;pointer-events:none;z-index:0;overflow:hidden}
#fb-seasonal-wall .fb-sb-wall-glyph{position:absolute;line-height:1;opacity:.09}
#fb-seasonal-decor{position:fixed;inset:0;pointer-events:none;z-index:90}
html.fb-mode-game #fb-seasonal-decor{z-index:2}
#fb-seasonal-decor .fb-sb-glyph{position:absolute;line-height:1;filter:drop-shadow(0 4px 10px rgba(0,0,0,.45))}
#fb-seasonal-ambience{position:fixed;inset:0;pointer-events:none;z-index:89;overflow:hidden}
#fb-seasonal-ambience .fb-sb-fall{position:absolute;top:-8vh;line-height:1;opacity:.5;animation-name:fb-sb-fall;animation-timing-function:linear;animation-iteration-count:infinite}
@keyframes fb-sb-fall{from{transform:translate3d(0,-8vh,0) rotate(-8deg)}to{transform:translate3d(3vw,112vh,0) rotate(38deg)}}
@keyframes fb-sb-bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-9px)}}
.fb-sb-bob{animation:fb-sb-bob 3.6s ease-in-out infinite}
/* ---- game-page badge ---- */
.fb-sb-badge{position:absolute;left:50%;bottom:6px;transform:translateX(-50%);font-size:17px;letter-spacing:2px;opacity:.55;line-height:1;white-space:nowrap}
/* ---- accents: every page ---- */
html.fb-theme-halloween ::selection{background:rgba(255,140,26,.5);color:#fff}
html.fb-mode-page body{background-color:#1c0a2a}
/* ---- hub showcase: deep-purple night + pumpkin glow ---- */
html.fb-mode-hub body{background:radial-gradient(1100px 560px at 50% -120px,rgba(124,58,237,.34),transparent 62%),radial-gradient(700px 380px at 85% 110%,rgba(255,140,26,.16),transparent 60%),#170a26}
html.fb-mode-hub nav.top{background:rgba(23,10,38,.96);border-bottom-color:rgba(155,89,182,.55)}
html.fb-mode-hub .hero{background:radial-gradient(ellipse at 50% 0%,rgba(255,140,26,.20),transparent 65%);border-bottom-color:rgba(155,89,182,.55)}
html.fb-mode-hub .hero h1{color:#ffb347;text-shadow:0 0 26px rgba(124,58,237,.65),0 4px 30px rgba(255,106,26,.35)}
html.fb-mode-hub .card{border-color:rgba(155,89,182,.5)}
html.fb-mode-hub .card:hover{border-color:#ff8c1a;box-shadow:0 16px 36px rgba(0,0,0,.45),0 0 26px rgba(124,58,237,.35)}
html.fb-mode-hub footer{border-top-color:rgba(155,89,182,.5)}
html.fb-mode-hub .hero,html.fb-mode-hub .whatsnew,html.fb-mode-hub .wrap,html.fb-mode-hub footer{position:relative;z-index:1}
/* ---- reduced motion: no falling/floating glyphs ---- */
@media (prefers-reduced-motion: reduce){#fb-seasonal-ambience{display:none}.fb-sb-bob{animation:none}}

scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR,GS,OX,OY;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);layout();}
function layout(){
  GS=Math.min(W*0.92/6,H*0.6/6,64);
  OX=(W-GS*6)/2;OY=(H-GS*6)/2+40;
}
addEventListener('resize',resize);
// levels: blocks as {r,c,len,horiz}
const LEVELS=[
  {blocks:[{r:2,c:0,len:2,h:1},{r:1,c:3,len:2,h:0},{r:3,c:4,len:2,h:0}],par:4},
  {blocks:[{r:2,c:0,len:2,h:1},{r:0,c:2,len:3,h:0},{r:4,c:3,len:2,h:1},{r:1,c:5,len:2,h:0}],par:8},
  {blocks:[{r:2,c:0,len:2,h:1},{r:0,c:0,len:2,h:0},{r:1,c:4,len:2,h:0},{r:3,c:2,len:3,h:1},{r:4,c:5,len:2,h:0}],par:10},
  {blocks:[{r:2,c:1,len:2,h:1},{r:0,c:3,len:3,h:0},{r:3,c:0,len:2,h:1},{r:4,c:2,len:2,h:0},{r:1,c:5,len:3,h:0},{r:5,c:4,len:2,h:1}],par:14},
  {blocks:[{r:2,c:0,len:2,h:1},{r:0,c:2,len:2,h:1},{r:1,c:3,len:3,h:0},{r:4,c:1,len:3,h:1},{r:3,c:4,len:2,h:0},{r:0,c:5,len:2,h:0}],par:16},
  {blocks:[{r:2,c:2,len:2,h:1},{r:0,c:0,len:3,h:0},{r:0,c:4,len:2,h:1},{r:3,c:3,len:2,h:0},{r:4,c:0,len:2,h:1},{r:5,c:2,len:3,h:1},{r:1,c:5,len:2,h:0}],par:20},
  {blocks:[{r:2,c:0,len:2,h:1},{r:0,c:1,len:2,h:0},{r:0,c:3,len:3,h:1},{r:2,c:4,len:2,h:0},{r:4,c:2,len:2,h:1},{r:3,c:0,len:2,h:0},{r:3,c:5,len:2,h:0},{r:1,c:4,len:2,h:1}],par:24},
  {blocks:[{r:2,c:1,len:2,h:1},{r:0,c:0,len:2,h:0},{r:0,c:2,len:3,h:1},{r:1,c:4,len:3,h:0},{r:3,c:0,len:2,h:1},{r:4,c:2,len:2,h:0},{r:5,c:3,len:3,h:1},{r:2,c:5,len:2,h:0},{r:4,c:3,len:2,h:1}],par:28},
  {blocks:[{r:2,c:2,len:2,h:1},{r:5,c:4,len:2,h:1},{r:2,c:0,len:2,h:0},{r:2,c:4,len:2,h:0},{r:3,c:2,len:2,h:1},{r:4,c:4,len:2,h:1},{r:4,c:3,len:2,h:0},{r:1,c:3,len:2,h:1},{r:0,c:5,len:3,h:0}],par:30},
  {blocks:[{r:2,c:0,len:2,h:1},{r:2,c:5,len:2,h:0},{r:5,c:1,len:3,h:1},{r:4,c:1,len:2,h:1},{r:0,c:4,len:2,h:1},{r:1,c:2,len:3,h:0},{r:3,c:3,len:2,h:0},{r:0,c:1,len:2,h:1},{r:2,c:4,len:2,h:0},{r:3,c:0,len:2,h:0}],par:34},
  {blocks:[{r:2,c:0,len:2,h:1},{r:1,c:2,len:3,h:0},{r:4,c:1,len:2,h:0},{r:1,c:4,len:2,h:0},{r:0,c:0,len:2,h:1},{r:4,c:2,len:3,h:1},{r:2,c:3,len:2,h:0},{r:3,c:4,len:2,h:1},{r:0,c:5,len:3,h:0},{r:5,c:4,len:2,h:1}],par:38},
  {blocks:[{r:2,c:0,len:2,h:1},{r:1,c:2,len:3,h:0},{r:4,c:1,len:2,h:0},{r:2,c:4,len:2,h:0},{r:0,c:4,len:2,h:1},{r:4,c:2,len:3,h:1},{r:2,c:3,len:2,h:0},{r:3,c:0,len:2,h:1},{r:2,c:5,len:3,h:0},{r:5,c:4,len:2,h:1},{r:5,c:2,len:2,h:1}],par:42},
  {blocks:[{r:2,c:0,len:2,h:1},{r:2,c:5,len:2,h:0},{r:5,c:0,len:3,h:1},{r:4,c:1,len:2,h:1},{r:0,c:4,len:2,h:1},{r:0,c:2,len:3,h:0},{r:4,c:3,len:2,h:0},{r:0,c:0,len:2,h:1},{r:4,c:4,len:2,h:0},{r:3,c:0,len:2,h:0},{r:4,c:5,len:2,h:0}],par:46},
];
let AC=null;
let muted=false;try{muted=localStorage.getItem('fb_mute')==='1';}catch(e){}
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(muted)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  slide(){tone(300,500,0.08,'sine',0.08);},
  bump(){tone(170,120,0.05,'square',0.05);},
  win(){[523,659,784,1047].forEach((f,i)=>tone(f,f,0.2,'triangle',0.15,i*0.09));},
  click(){tone(600,600,0.06,'square',0.1);}
};
const G={state:'title',level:1,score:0,moves:0,
  blocks:[],drag:null,time:0,ballX:-1,solved:false,history:[]};
function initLevel(n){
  const L=LEVELS[n-1];
  G.level=n;G.moves=0;G.solved=false;G.ballX=-1;G.drag=null;G.history=[];setPaused(false);
  G.blocks=L.blocks.map((b,i)=>({...b,idx:i,ox:b.c,oy:b.r}));
  document.getElementById('level').textContent=`LV ${n}/13`;
  document.getElementById('moves').textContent='👆 0';
  updateHUD();
}
function updateHUD(){document.getElementById('score').textContent='⭐ '+G.score;}
function occupied(r,c,ignore){
  for(const b of G.blocks){
    if(b===ignore)continue;
    for(let i=0;i<b.len;i++){
      const br=b.h?b.r:b.r+i,bc=b.h?b.c+i:b.c;
      if(br===r&&bc===c)return true;
    }
  }
  return false;
}
function blockAt(x,y){
  for(let i=G.blocks.length-1;i>=0;i--){
    const b=G.blocks[i];
    const bx=OX+b.c*GS,by=OY+b.r*GS;
    const bw=b.h?b.len*GS:GS,bh=b.h?GS:b.len*GS;
    if(x>bx&&x<bx+bw&&y>by&&y<by+bh)return b;
  }
  return null;
}
canvas.addEventListener('pointerdown',e=>{
  if(G.state!=='play'||G.solved||G.paused)return;
  const rect=canvas.getBoundingClientRect();
  const b=blockAt(e.clientX-rect.left,e.clientY-rect.top);
  if(b){
    G.drag={b,sx:e.clientX-rect.left,sy:e.clientY-rect.top,moved:false,snap:G.blocks.map(x=>({r:x.r,c:x.c})),lastThud:0};
    canvas.setPointerCapture(e.pointerId);
  }
});
canvas.addEventListener('pointermove',e=>{
  const d=G.drag;if(!d)return;
  const rect=canvas.getBoundingClientRect();
  const x=e.clientX-rect.left,y=e.clientY-rect.top;
  const b=d.b;
  // Step one cell at a time toward the drag target, checking every cell passed.
  // (Previously a fast drag teleported the block to its destination, leapfrogging blockers.)
  const target=b.h?b.ox+Math.round((x-d.sx)/GS):b.oy+Math.round((y-d.sy)/GS);
  while((b.h?b.c:b.r)!==target){
    const step=Math.sign(target-(b.h?b.c:b.r));
    const nc=(b.h?b.c:b.r)+step;
    let ok=nc>=0&&nc+b.len<=6;
    if(ok)for(let i=0;i<b.len;i++)if(occupied(b.h?b.r:nc+i,b.h?nc+i:b.c,b)){ok=false;break;}
    if(!ok){const now=performance.now();if(now-d.lastThud>200){d.lastThud=now;sfx.bump();}break;}
    if(b.h)b.c=nc;else b.r=nc;
    d.moved=true;sfx.slide();
    G.moves++;document.getElementById('moves').textContent='👆 '+G.moves; // count each cell step (genre standard; a long drag was 1 'move' vs par, making stars free)
  }
});
canvas.addEventListener('pointerup',()=>{
  const d=G.drag;if(!d)return;
  if(d.moved){
    d.b.ox=d.b.c;d.b.oy=d.b.r;
    G.history.push(d.snap);if(G.history.length>60)G.history.shift();
    checkWin();
  }
  G.drag=null;
});
function undoMove(){
  if(G.state!=='play'||G.solved||G.paused||!G.history.length)return;
  const snap=G.history.pop();
  G.blocks.forEach((b,i)=>{b.r=snap[i].r;b.c=snap[i].c;b.ox=b.c;b.oy=b.r;});
  G.moves++;document.getElementById('moves').textContent='👆 '+G.moves;sfx.slide();
}
canvas.addEventListener('pointercancel',()=>{const d=G.drag;if(!d)return;if(d.moved){d.b.ox=d.b.c;d.b.oy=d.b.r;G.history.push(d.snap);checkWin();}G.drag=null;}); // an interrupted touch (call/notification) no longer strands a half-drag
document.getElementById('undoBtn').addEventListener('click',undoMove);
addEventListener('keydown',e=>{if(e.key==='u'||e.key==='U')undoMove();});
document.getElementById('resetBtn').addEventListener('click',()=>{
  if(G.state==='play'){initLevel(G.level);sfx.click();}
});
function checkWin(){
  // fireball (block 0) needs clear path to right edge on row 2
  const ball=G.blocks[0];
  let clear=true;
  for(let c=ball.c+ball.len;c<6;c++)if(occupied(2,c,ball)){clear=false;break;}
  if(clear&&!G.solved){
    G.solved=true;sfx.win();
    const par=LEVELS[G.level-1].par;
    const stars=G.moves<=par?3:G.moves<=par*1.5?2:1;
    const pts=100+stars*50;
    G.score+=pts;updateHUD();
    // animate ball rolling out
    G.ballX=ball.c+ball.len;
    setTimeout(()=>{
      if(G.level>=13){
        showOverlay('🏆 PUZZLE MASTER!',
          `<p style="font-size:24px;font-weight:900">Final Score: ${G.score}</p><p>All 13 blockades cleared!</p>`,
          '🔥 Fire Safety: You\'re a champion!',
          '↻ PLAY AGAIN',()=>{G.score=0;initLevel(1);G.state='play';});
      }else{
        showOverlay(`⭐ LEVEL ${G.level} CLEAR!`,
          `<div style="color:#ffd23f;font-size:26px">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</div><p>${G.moves} moves (par ${par})</p><p>+${pts} pts</p>`,
          '🔥 Fire Safety: Clear a path!',
          '▶ NEXT LEVEL',()=>{initLevel(G.level+1);G.state='play';});
      }
    },900);
  }
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');showLevels();
  }else document.getElementById('ma').value='';
}
function showLevels(){
  otitle.innerHTML='🧱 PICK LEVEL';
  let h='';
  for(let i=1;i<=13;i++)h+=`<button class="lvlBtn" onclick="event.stopPropagation();pickLevel(${i})">${i}</button>`;
  obody.innerHTML=`<p>Slide blocks to free the fireball!</p><div id="lvlSel">${h}</div>`;
  obtn.style.display='none';
  overlay.classList.remove('hidden');
}
function pickLevel(n){sfx.click();audio();G.score=0;initLevel(n);G.state='play';overlay.classList.add('hidden');}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;
  obtn.textContent=btn;obtn.style.display='';
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
obtn.onclick=()=>{showMathGate();};

// --- Overhaul: living ember background (24 cheap additive particles, deterministic from G.time) ---
function drawEmbers(){
  ctx.save();ctx.globalCompositeOperation='lighter';
  const maxW=Math.max(W,1),maxH=Math.max(H,1);
  for(let i=0;i<24;i++){
    const sp=14+(i%5)*7,off=(i*197)%maxH;
    const ex=((i*173)%maxW)+Math.sin(G.time*0.7+i)*12;
    const ey=maxH-((G.time*sp+off)%(maxH+30));
    ctx.globalAlpha=Math.max(0.08,0.35+0.3*Math.sin(G.time*3+i*1.7));
    ctx.fillStyle=i%3?'#ff8a3a':'#ffd23f';
    ctx.shadowBlur=0;
    ctx.beginPath();ctx.arc(ex,ey,1.6+(i%3),0,Math.PI*2);ctx.fill();
  }
  ctx.restore();
}
function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#17102a');bg.addColorStop(1,'#0d0a14');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  drawEmbers();
  if(!G.blocks.length)return;
  // board
  ctx.fillStyle='rgba(255,255,255,0.04)';
  ctx.beginPath();ctx.roundRect(OX-8,OY-8,GS*6+16,GS*6+16,12);ctx.fill();
  // grid
  ctx.strokeStyle='rgba(255,255,255,0.06)';ctx.lineWidth=1;
  for(let i=0;i<=6;i++){
    ctx.beginPath();ctx.moveTo(OX+i*GS,OY);ctx.lineTo(OX+i*GS,OY+GS*6);ctx.stroke();
    ctx.beginPath();ctx.moveTo(OX,OY+i*GS);ctx.lineTo(OX+GS*6,OY+i*GS);ctx.stroke();
  }
  // goal exit (right side, row 2)
  const gy=OY+2*GS;
  ctx.fillStyle='rgba(76,175,80,0.25)';
  ctx.fillRect(OX+GS*6-4,gy,12,GS);
  ctx.font=`${GS*0.5}px system-ui`;ctx.textAlign='center';
  ctx.fillText('🏁',Math.min(OX+GS*6+22,W-16),gy+GS*0.72); // was off-screen on phonesctx.textAlign='left';
  // exit path highlight
  const ball=G.blocks[0];
  if(ball){
    let clear=true;
    for(let c=ball.c+ball.len;c<6;c++)if(occupied(2,c,ball)){clear=false;break;}
    if(clear){
      ctx.fillStyle='rgba(76,175,80,0.15)';
      ctx.fillRect(OX+(ball.c+ball.len)*GS,gy,GS*(6-ball.c-ball.len),GS);
    }
  }
  // blocks
  G.blocks.forEach((b,i)=>{
    const bx=OX+b.c*GS+3,by=OY+b.r*GS+3;
    const bw=(b.h?b.len*GS:GS)-6,bh=(b.h?GS:b.len*GS)-6;
    const isBall=i===0;
    const g=ctx.createLinearGradient(0,by,0,by+bh);
    if(isBall){g.addColorStop(0,'#ff8a3a');g.addColorStop(1,'#d42a1a');}
    else{g.addColorStop(0,'#6a5a8a');g.addColorStop(1,'#3a2a4a');}
    ctx.fillStyle=g;
    if(isBall){ctx.shadowColor='#ff6a1a';ctx.shadowBlur=16;}
    ctx.beginPath();ctx.roundRect(bx,by,bw,bh,10);ctx.fill();
    ctx.shadowBlur=0;
    ctx.strokeStyle=b===G.drag?.b?'#ffd23f':'rgba(255,255,255,0.25)';
    ctx.lineWidth=b===G.drag?.b?4:2;ctx.stroke();
    // arrows
    ctx.fillStyle='rgba(255,255,255,0.5)';ctx.font=`900 ${GS*0.3}px system-ui`;ctx.textAlign='center';
    const cxp=bx+bw/2,cyp=by+bh/2+GS*0.1;
    if(isBall)ctx.fillText('🔥',cxp,cyp);
    else ctx.fillText(b.h?'↔️':'↕️',cxp,cyp);
    ctx.textAlign='left';
  });
  // solved ball rolling
  if(G.solved&&G.ballX>=0){
    const bx=OX+G.ballX*GS;
    if(bx<W+40){
      const g=ctx.createRadialGradient(bx-6,gy+GS/2-8,3,bx,gy+GS/2,18);
      g.addColorStop(0,'#ffe9a0');g.addColorStop(1,'#ff6a1a');
      ctx.fillStyle=g;ctx.beginPath();ctx.arc(bx,gy+GS/2,16,0,Math.PI*2);ctx.fill();
    }
  }
}
function setPaused(v){G.paused=!!v;const b=document.getElementById('pauseBtn');if(b)b.textContent=G.paused?'▶':'⏸';}
function togglePause(){if(G.state!=='play')return;setPaused(!G.paused);}
document.getElementById('pauseBtn').addEventListener('click',()=>{togglePause();});
document.getElementById('muteBtn').addEventListener('click',function(){muted=!muted;this.textContent=muted?'🔇':'🔊';try{localStorage.setItem('fb_mute',muted?'1':'0');}catch(e){}});
document.getElementById('muteBtn').textContent=muted?'🔇':'🔊';
addEventListener('keydown',e=>{if(e.key==='p'||e.key==='P'||e.key==='Escape')togglePause();});
function drawPaused(){ctx.fillStyle='rgba(5,3,10,0.72)';ctx.fillRect(0,0,W,H);ctx.fillStyle='#ffd76a';ctx.font='900 34px system-ui';ctx.textAlign='center';ctx.fillText('⏸ PAUSED',W/2,H/2);ctx.fillStyle='#fff';ctx.font='700 16px system-ui';ctx.fillText('Tap ⏸ or press P to resume',W/2,H/2+34);ctx.textAlign='left';}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;G.time+=dt;
  if(G.solved&&G.ballX>=0&&!G.paused)G.ballX+=dt*4.8; // was per-frame — roll-out speed doubled on 120Hz screens
  render();if(G.paused)drawPaused();
  requestAnimationFrame(loop);
}
resize();
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Blockade Beatdown' — Boulder's Blockade's own
   track. Synthesized Web Audio only. 98 BPM, C minor: the heaviest stomp on
   the site — a low square lead, deep pads (Cm-Ab-Eb-Bb) and war drums that
   shake the barricade.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Freeze gate CONFIRMED at insertion (2026-10-15): script-scope `muted` mutes, G.paused pauses, and music only
   plays while G.state==='play' — all read from this shell's own code.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-43-boulders-blockade.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
// Freeze gate (insertion-confirmed 2026-10-15): hard-wired to this shell's
// own confirmed globals — muted / G.paused / G.state. try/catch kept so it can never throw.
const _mGate=()=>{try{return !!(muted||G.paused||G.state!=='play');}catch(e){return false;}};
const MUS={on:false,step:0,nextT:0,BPM:98,
 BASS:[36,0,0,36,0,36,0,0, 44,0,0,44,0,44,0,0, 39,0,0,39,0,39,0,0, 34,0,0,34,0,36,39,0],
 LEAD:[48,0,51,0,0,55,0,0, 56,0,55,0,51,0,0,0, 55,0,58,0,0,55,0,0, 53,0,51,0,48,0,0,0],
 PAD:[36,44,39,34],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(_mGate()){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  if(s%8===0){const p=this.PAD[s>>3];if(p){tone(_mf(p),_mf(p),1.6,'sawtooth',0.02,d);tone(_mf(p)*1.006,_mf(p)*1.006,1.6,'sawtooth',0.02,d);tone(_mf(p+7),_mf(p+7),1.6,'triangle',0.024,d);}} // pad chord
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.18,'square',0.065,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.24,'square',0.055,d);
  if(s%8===0||s%8===3||s%8===6)tone(95,38,0.15,'sine',0.16,d); // war-drum kick
  if(s%8===4)tone(85,55,0.12,'triangle',0.09,d); // low tom
  if(s===14||s===30)tone(185,115,0.08,'triangle',0.08,d); // sparse tone-only snare
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

