scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR,TS,OX,OY;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);layout();}
function layout(){
  TS=Math.min(W*0.9/G.n,H*0.62/G.n,120);
  OX=(W-TS*G.n)/2;OY=(H-TS*G.n)/2+30;
}
addEventListener('resize',resize);
let AC=null;
let muted=false;try{muted=localStorage.getItem('fb_mute')==='1';}catch(e){}
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(muted)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  slide(){tone(400+Math.random()*100,600,0.07,'sine',0.08);},
  win(){[523,659,784,1047,1319].forEach((f,i)=>tone(f,f,0.2,'triangle',0.14,i*0.09));},
  click(){tone(600,600,0.06,'square',0.1);}
};
const G={state:'title',n:3,grid:[],empty:{r:0,c:0},moves:0,startT:0,solved:false,time:0,anim:null};
function initPuzzle(n){
  setPaused(false);G.n=n;layout();
  G.grid=[];G.moves=0;G.solved=false;G.anim=null;
  G.startT=performance.now();
  let v=1;
  for(let r=0;r<n;r++){G.grid[r]=[];
    for(let c=0;c<n;c++){
      G.grid[r][c]=v<=n*n-1?v:0;v++;
    }
  }
  G.empty={r:n-1,c:n-1};
  // shuffle (valid moves — a walk from the solved state, so every dealt board is solvable by construction)
  const WALK={6:60,7:80,8:100,9:120,10:140};
  const shuffles=WALK[n]||n*n*20;
  for(let i=0;i<shuffles;i++){
    const moves=[];
    const{r,c}=G.empty;
    if(r>0)moves.push({r:r-1,c});
    if(r<n-1)moves.push({r:r+1,c});
    if(c>0)moves.push({r,c:c-1});
    if(c<n-1)moves.push({r,c:c+1});
    const m=moves[Math.floor(Math.random()*moves.length)];
    G.grid[G.empty.r][G.empty.c]=G.grid[m.r][m.c];
    G.grid[m.r][m.c]=0;
    G.empty=m;
  }
  // Guarantee the dealt board is not already solved (a random-walk shuffle can land back on solved).
  let _guard=0;
  while(checkWin()&&_guard++<12){
    const{r,c}=G.empty;const opts=[];
    if(r>0)opts.push({r:r-1,c});if(r<n-1)opts.push({r:r+1,c});
    if(c>0)opts.push({r,c:c-1});if(c<n-1)opts.push({r,c:c+1});
    const m=opts[Math.floor(Math.random()*opts.length)];
    G.grid[G.empty.r][G.empty.c]=G.grid[m.r][m.c];G.grid[m.r][m.c]=0;G.empty=m;
  }
  document.getElementById('level').textContent=`${n}×${n}`;
  document.getElementById('moves').textContent='👆 0';
  updateHUD();
}
function updateHUD(){}
function tileHome(v){
  return{r:Math.floor((v-1)/G.n),c:(v-1)%G.n};
}
function drawTileArt(hr,hc,px,py,ts){
  // draw portion of fire baby volcano scene
  ctx.save();
  ctx.beginPath();ctx.rect(px,py,ts,ts);ctx.clip();
  ctx.translate(px-hc*ts,py-hr*ts);
  const S=ts*G.n;
  // sky
  const g=ctx.createLinearGradient(0,0,0,S);
  g.addColorStop(0,'#1a2a4a');g.addColorStop(0.5,'#ff6a1a');g.addColorStop(1,'#3a1a0a');
  ctx.fillStyle=g;ctx.fillRect(0,0,S,S);
  // volcano
  ctx.fillStyle='#1a0d08';
  ctx.beginPath();
  ctx.moveTo(S*0.2,S*0.85);ctx.lineTo(S*0.5,S*0.25);ctx.lineTo(S*0.8,S*0.85);ctx.closePath();ctx.fill();
  // lava top
  ctx.fillStyle='#ff4a00';
  ctx.beginPath();ctx.ellipse(S*0.5,S*0.27,S*0.06,S*0.02,0,0,Math.PI*2);ctx.fill();
  // fire baby
  const babyR=S*0.075;
  const bg=ctx.createRadialGradient(S*0.5-babyR*0.3,S*0.6-babyR*0.4,babyR*0.15,S*0.5,S*0.6,babyR*1.1);
  bg.addColorStop(0,'#ffe9a0');bg.addColorStop(0.5,'#ff7a2a');bg.addColorStop(1,'#d42a1a');
  ctx.shadowColor='#ff7a2a';ctx.shadowBlur=14;
  ctx.fillStyle=bg;ctx.beginPath();ctx.arc(S*0.5,S*0.6,babyR,0,Math.PI*2);ctx.fill();
  ctx.shadowBlur=0;
  ctx.fillStyle='#2b1a0e';
  ctx.beginPath();ctx.arc(S*0.5-babyR*0.33,S*0.6-babyR*0.17,babyR*0.17,0,Math.PI*2);ctx.arc(S*0.5+babyR*0.33,S*0.6-babyR*0.17,babyR*0.17,0,Math.PI*2);ctx.fill();
  // tile number (subtle)
  ctx.restore();
  ctx.fillStyle='rgba(255,255,255,0.75)';ctx.font=`900 ${ts*0.18}px system-ui`;ctx.textAlign='left';
  ctx.fillText(G._drawV||'',px+6,py+ts*0.22);
}
function trySlide(r,c){
  if(G.state!=='play'||G.solved||G.anim||G.paused||G.peek)return false;
  if(r<0||r>=G.n||c<0||c>=G.n)return false;
  const er=G.empty.r,ec=G.empty.c;
  if(Math.abs(r-er)+Math.abs(c-ec)!==1)return false;
  G.anim={fr:r,fc:c,tr:er,tc:ec,t:0,v:G.grid[r][c]};
  G.grid[er][ec]=G.grid[r][c];
  G.grid[r][c]=0;
  G.empty={r,c};
  sfx.slide();
  return true;
}
canvas.addEventListener('pointerdown',e=>{
  const rect=canvas.getBoundingClientRect();
  const x=e.clientX-rect.left,y=e.clientY-rect.top;
  trySlide(Math.floor((y-OY)/TS),Math.floor((x-OX)/TS));
});
// keyboard play (desktop genre standard — arrows move the gap; the tile on that side slides in)
addEventListener('keydown',e=>{
  const er=G.empty.r,ec=G.empty.c;let used=true;
  if(e.key==='ArrowLeft')trySlide(er,ec-1);
  else if(e.key==='ArrowRight')trySlide(er,ec+1);
  else if(e.key==='ArrowUp')trySlide(er-1,ec);
  else if(e.key==='ArrowDown')trySlide(er+1,ec);
  else used=false;
  if(used)e.preventDefault();
});
// hold-to-peek at the finished picture (players had never seen the whole picture they are rebuilding)
const _peekBtn=document.getElementById('peekBtn');
['pointerdown'].forEach(ev=>_peekBtn.addEventListener(ev,e=>{e.preventDefault();if(G.state==='play')G.peek=true;}));
['pointerup','pointerleave','pointercancel'].forEach(ev=>_peekBtn.addEventListener(ev,()=>{G.peek=false;}));
document.getElementById('shuffleBtn').addEventListener('click',()=>{
  if(G.state==='play'){initPuzzle(G.n);sfx.click();}
});
function checkWin(){
  for(let r=0;r<G.n;r++)for(let c=0;c<G.n;c++){
    const v=G.grid[r][c];
    if(r===G.n-1&&c===G.n-1){if(v!==0)return false;}
    else if(v!==r*G.n+c+1)return false;
  }
  return true;
}
function onSolve(){
  G.solved=true;sfx.win();
  const elapsed=(performance.now()-G.startT)/1000;
  const score=Math.max(100,Math.round(5000/(G.moves+10)/(elapsed/60+1)));
  setTimeout(()=>{
    showOverlay('🏆 SOLVED!',
      `<p style="font-size:24px;font-weight:900">Score: ${score}</p><p>${G.moves} moves in ${elapsed.toFixed(1)}s</p><p>Grid: ${G.n}×${G.n}</p>`,
      '🔥 Fire Safety: You\'re a champion!',
      G.n<10?'▶ BIGGER PUZZLE':'↻ PLAY AGAIN',
      ()=>{
        if(G.n<10)initPuzzle(G.n+1);
        else initPuzzle(G.n);
        G.state='play';
      });
  },600);
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');showLevels();
  }else document.getElementById('ma').value='';
}
function showLevels(){
  otitle.innerHTML='🧩 PICK SIZE';
  const sizes=[3,4,5,6,7,8,9,10];
  let h='';
  sizes.forEach(n=>{h+=`<button class="lvlBtn" onclick="event.stopPropagation();pickLevel(${n})">${n}×${n}</button>`;});
  obody.innerHTML=`<p>Slide tiles to rebuild the picture!</p><div id="lvlSel">${h}</div>`;
  obtn.style.display='none';
  overlay.classList.remove('hidden');
}
function pickLevel(n){sfx.click();audio();initPuzzle(n);G.state='play';overlay.classList.add('hidden');}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;
  obtn.textContent=btn;obtn.style.display='';
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
obtn.onclick=()=>{showMathGate();};

// --- Overhaul: living ember background (24 cheap additive particles, deterministic from G.time) ---
function drawEmbers(){
  ctx.save();ctx.globalCompositeOperation='lighter';
  const maxW=Math.max(W,1),maxH=Math.max(H,1);
  for(let i=0;i<24;i++){
    const sp=14+(i%5)*7,off=(i*197)%maxH;
    const ex=((i*173)%maxW)+Math.sin(G.time*0.7+i)*12;
    const ey=maxH-((G.time*sp+off)%(maxH+30));
    ctx.globalAlpha=Math.max(0.08,0.35+0.3*Math.sin(G.time*3+i*1.7));
    ctx.fillStyle=i%3?'#ff8a3a':'#ffd23f';
    ctx.shadowBlur=0;
    ctx.beginPath();ctx.arc(ex,ey,1.6+(i%3),0,Math.PI*2);ctx.fill();
  }
  ctx.restore();
}
function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#2a1408');bg.addColorStop(1,'#160d08');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  drawEmbers();
  if(!G.grid.length)return;
  // board bg
  ctx.fillStyle='rgba(255,255,255,0.04)';
  ctx.beginPath();ctx.roundRect(OX-8,OY-8,TS*G.n+16,TS*G.n+16,14);ctx.fill();
  for(let r=0;r<G.n;r++)for(let c=0;c<G.n;c++){
    const v=G.peek?((r*G.n+c+1>=G.n*G.n)?0:r*G.n+c+1):G.grid[r][c];
    const px=OX+c*TS,py=OY+r*TS;
    if(v===0){
      // empty
      ctx.fillStyle='rgba(0,0,0,0.35)';
      ctx.beginPath();ctx.roundRect(px+3,py+3,TS-6,TS-6,10);ctx.fill();
      continue;
    }
    let dx=px,dy=py;
    // animation
    if(!G.peek&&G.anim&&G.anim.v===v){
      const t=Math.min(1,G.anim.t);
      const fx=OX+G.anim.fc*TS,fy=OY+G.anim.fr*TS;
      const tx=OX+G.anim.tc*TS,ty=OY+G.anim.tr*TS;
      dx=fx+(tx-fx)*t;dy=fy+(ty-fy)*t;
    }
    const home=tileHome(v);
    const correct=home.r===r&&home.c===c;
    G._drawV=v;
    drawTileArt(home.r,home.c,dx+3,dy+3,TS-6);
    ctx.strokeStyle=correct?'rgba(76,175,80,0.7)':'rgba(255,255,255,0.25)';
    ctx.lineWidth=correct?3:2;
    ctx.beginPath();ctx.roundRect(dx+3,dy+3,TS-6,TS-6,10);ctx.stroke();
  }
  G._drawV=null;
  // timer
  if(G.state==='play'&&!G.solved){
    const el=((G.paused&&G._pausedAt)?G._pausedAt-G.startT:performance.now()-G.startT)/1000;
    document.getElementById('timer').textContent='⏱️ '+el.toFixed(0)+'s';
  }
}
function setPaused(v){const was=G.paused;G.paused=!!v;const b=document.getElementById('pauseBtn');if(b)b.textContent=G.paused?'▶':'⏸';if(G.paused)G._pausedAt=performance.now();else if(was&&G._pausedAt){G.startT+=performance.now()-G._pausedAt;G._pausedAt=0;}}
function togglePause(){if(G.state!=='play')return;setPaused(!G.paused);}
document.getElementById('pauseBtn').addEventListener('click',()=>{togglePause();});
document.getElementById('muteBtn').addEventListener('click',function(){muted=!muted;this.textContent=muted?'🔇':'🔊';try{localStorage.setItem('fb_mute',muted?'1':'0');}catch(e){}});
document.getElementById('muteBtn').textContent=muted?'🔇':'🔊';
addEventListener('keydown',e=>{if(e.key==='p'||e.key==='P'||e.key==='Escape')togglePause();});
function drawPaused(){ctx.fillStyle='rgba(5,3,10,0.72)';ctx.fillRect(0,0,W,H);ctx.fillStyle='#ffd76a';ctx.font='900 34px system-ui';ctx.textAlign='center';ctx.fillText('⏸ PAUSED',W/2,H/2);ctx.fillStyle='#fff';ctx.font='700 16px system-ui';ctx.fillText('Tap ⏸ or press P to resume',W/2,H/2+34);ctx.textAlign='left';}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;G.time+=dt;
  if(G.anim&&!G.paused){
    G.anim.t+=dt*8;
    if(G.anim.t>=1){
      G.anim=null;G.moves++;
      document.getElementById('moves').textContent='👆 '+G.moves;
      if(checkWin())onSolve();
    }
  }
  render();if(G.paused)drawPaused();
  requestAnimationFrame(loop);
}
resize();
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Slippery Summit' — Cinder's Slide's own
   track. Synthesized Web Audio only. 114 BPM, Bb major: a gliding sine lead
   that slides a whole step into every note, up or down — nothing on this
   track stands still.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Freeze gate CONFIRMED at insertion (2026-10-15): script-scope `muted` mutes, G.paused pauses, and music only
   plays while G.state==='play' — all read from this shell's own code.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-44-cinders-slide.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
// Freeze gate (insertion-confirmed 2026-10-15): hard-wired to this shell's
// own confirmed globals — muted / G.paused / G.state. try/catch kept so it can never throw.
const _mGate=()=>{try{return !!(muted||G.paused||G.state!=='play');}catch(e){return false;}};
const MUS={on:false,step:0,nextT:0,BPM:114,
 BASS:[46,0,0,46,0,0,58,0, 43,0,0,43,0,0,55,0, 51,0,0,51,0,0,63,0, 41,0,0,41,0,0,53,0],
 LEAD:[70,0,74,0,77,0,74,0, 74,0,79,0,77,0,74,0, 75,0,79,0,82,0,79,0, 77,0,74,0,72,0,74,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(_mGate()){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.2,'triangle',0.05,d);
  const l=this.LEAD[s];if(l)tone(_mf(l+(s%2?-2:2)),_mf(l),0.26,'sine',0.05,d); // slippery slide into every note
  if(s%8===0||s%8===4)tone(115,45,0.11,'sine',0.11,d); // kick
  if(s%8===2||s%8===6)tone(188,118,0.07,'triangle',0.05,d); // soft tone-only snare
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

/* fb-cycle2: in-play restart — the cluster button runs the game's own overlay reset path. */
(function(){var b=document.getElementById('restartBtn');if(!b)return;b.addEventListener('click',function(e){e.stopPropagation();if(typeof G==='undefined'||G.state!=='play')return;initPuzzle(G.n);G.state='play';});})();

