scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();
addEventListener('resize',()=>{for(const e of G.enemies)e.x=Math.max(20,Math.min(W-20,e.x));});
let AC=null;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(window.__mute)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
function noise(dur,vol,delay=0,lp=2000){if(window.__mute)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const len=ac.sampleRate*dur,buf=ac.createBuffer(1,len,ac.sampleRate),d=buf.getChannelData(0);
  for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);
  const s=ac.createBufferSource();s.buffer=buf;const f=ac.createBiquadFilter();f.type='lowpass';f.frequency.value=lp;
  const g=ac.createGain();g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  s.connect(f);f.connect(g);g.connect(ac.destination);s.start(t);}
const sfx={
  zap(){noise(0.18,0.3,0,3000);tone(1800,300,0.15,'sawtooth',0.12);},
  nova(){noise(0.35,0.35,0,1800);tone(220,880,0.35,'sawtooth',0.14);},
  kill(){tone(500,900,0.08,'sine',0.09);},
  leak(){tone(320,110,0.25,'sawtooth',0.14);},
  wave(){tone(400,800,0.3,'triangle',0.13);},
  nomana(){tone(200,150,0.1,'square',0.08);},
  click(){tone(600,600,0.06,'square',0.1);}
};
const G={state:'title',score:0,best:0,wave:0,mana:100,kills:0,nova:0,
  enemies:[],bolts:[],spawnQ:[],castleHp:100,
  time:0,shake:0,flash:0};
try{G.best=parseInt(localStorage.getItem('strike_best')||'0',10)||0;}catch(e){}
const CASTLE_Y=()=>H*0.88;
function reset(){
  G.score=0;G.wave=0;G.mana=100;G.castleHp=100;G.kills=0;G.nova=0;
  G.enemies=[];G.bolts=[];G.spawnQ=[];
  G.time=0;G.shake=0;G.flash=0;
  updateHUD();
  document.getElementById('best').textContent='🏆 '+G.best;
  startWave(1);
}
const mfEl=document.getElementById('manaFill');
function updateHUD(){
  document.getElementById('score').textContent='⭐ '+G.score;
  document.getElementById('wave').textContent='🌊 Wave '+Math.max(1,G.wave)+' • 🏰 '+Math.max(0,G.castleHp)+'%'+(G.nova>0?' • 🔆 Nova ×'+G.nova:'');
  const nb=document.getElementById('novaBtn');if(nb)nb.classList.toggle('hidden',!(G.nova>0&&G.state==='play'));
  document.getElementById('manaFill').style.width=G.mana+'%';
}
function startWave(n){
  G.wave=n;sfx.wave();updateHUD();
  const count=4+n*2;
  const comp=[];
  for(let i=0;i<count;i++){
    const r=Math.random();
    let type='walker';
    if(n>=3&&r<0.25)type='runner';
    else if(n>=5&&r<0.4)type='brute';
    comp.push(type);
  }
  G.spawnQ=comp.map((t,i)=>({type:t,delay:1+i*0.8}));
}
function spawnEnemy(type){
  const base={x:Math.random()*W,y:-30,t:Math.random()*10,hitT:0};
  if(type==='walker')Object.assign(base,{type,hp:30,r:16,speed:60+G.wave*4,score:10});
  else if(type==='runner')Object.assign(base,{type,hp:18,r:12,speed:120+G.wave*6,score:15});
  else Object.assign(base,{type:'brute',hp:80,r:26,speed:40+G.wave*3,score:40});
  G.enemies.push(base);
}
canvas.addEventListener('pointerdown',e=>{
  if(G.state!=='play')return;
  if(G.mana<20){sfx.nomana();return;}
  const rect=canvas.getBoundingClientRect();
  const x=e.clientX-rect.left,y=e.clientY-rect.top;
  G.mana-=20;
  strike(x,y);
  updateHUD();
});
function strike(x,y){
  sfx.zap();G.flash=0.35;G.shake=Math.max(G.shake,0.2);
  // lightning bolt visual
  const segs=[];
  let px=x,py=0;
  segs.push({x:px,y:py});
  while(py<y){
    py+=30+Math.random()*30;
    px=x+(Math.random()-0.5)*60;
    segs.push({x:px,y:Math.min(py,y)});
  }
  G.bolts.push({segs,life:0.25,x,y});
  // damage: direct hit + chain
  const hitR=70;
  const hit=[];
  for(const e of G.enemies){
    if(Math.hypot(e.x-x,e.y-y)<hitR+e.r)hit.push(e);
  }
  // chain to nearby
  const chained=new Set(hit);
  for(const e of hit){
    for(const o of G.enemies){
      if(!chained.has(o)&&Math.hypot(o.x-e.x,o.y-e.y)<110){
        chained.add(o);
        G.bolts.push({segs:[{x:e.x,y:e.y},{x:(e.x+o.x)/2+(Math.random()-0.5)*40,y:(e.y+o.y)/2},{x:o.x,y:o.y}],life:0.2,chain:true});
      }
    }
  }
  for(const e of chained){
    e.hp-=45;e.hitT=0.15;
    burst(e.x,e.y,'#aee2ff',6);
    if(e.hp<=0&&!e.dead){
      e.dead=true;G.score+=e.score;sfx.kill();
      G.kills++;if(G.kills%6===0){G.nova++;burst(e.x,e.y,'#ffd23f',10);updateHUD();}
      burst(e.x,e.y,'#8a6a4a',10);
      updateHUD();
    }
  }
}
// --- New weapon: Inferno Nova (55 dmg vs the base strike's 45 = +22%, inside the 25% balance cap) ---
// Earned in normal play: +1 charge every 6 kills. SPACE / X blasts the most advanced enemy, radius 100.
function novaStrike(){
  if(G.state!=='play'||G.nova<=0||!G.enemies.length)return;
  G.nova--;
  let target=G.enemies[0];
  for(const e of G.enemies)if(e.y>target.y)target=e;
  sfx.nova();G.flash=0.5;G.shake=Math.max(G.shake,0.35);
  G.bolts.push({segs:[{x:target.x,y:0},{x:target.x+20,y:target.y*0.5},{x:target.x,y:target.y}],life:0.3,x:target.x,y:target.y});
  for(const e of [...G.enemies]){
    if(Math.hypot(e.x-target.x,e.y-target.y)<100+e.r){
      e.hp-=55;e.hitT=0.15;burst(e.x,e.y,'#ffd23f',6);
      if(e.hp<=0&&!e.dead){e.dead=true;G.score+=e.score;G.kills++;sfx.kill();burst(e.x,e.y,'#8a6a4a',10);}
    }
  }
  updateHUD();
}
addEventListener('keydown',e=>{if(e.key===' '||e.key.toLowerCase()==='x'){e.preventDefault();novaStrike();}});
const particles=[];
for(let i=0;i<120;i++)particles.push({a:false});
function burst(x,y,color,n=8){
  for(let i=0;i<n;i++){const p=particles.find(p=>!p.a);if(!p)break;
    const a=Math.random()*Math.PI*2;
    p.a=true;p.x=x;p.y=y;p.vx=Math.cos(a)*220;p.vy=Math.sin(a)*220;
    p.life=0.4;p.max=0.4;p.color=color;p.size=3+Math.random()*3;}
}
function update(dt){
  G.time+=dt;G.shake=Math.max(0,G.shake-dt*3);G.flash=Math.max(0,G.flash-dt*2);
  G.mana=Math.min(100,G.mana+dt*14);mfEl.style.width=G.mana+'%';
  // spawn
  for(const q of G.spawnQ)q.delay-=dt;
  while(G.spawnQ.length&&G.spawnQ[0].delay<=0){const q=G.spawnQ.shift();if(q.kind==='wave')startWave(q.n);else spawnEnemy(q.type);}
  // wave clear
  if(!G.spawnQ.length&&!G.enemies.length&&G.state==='play'){
    // bonus + schedule next wave (ticked in update = pause-safe, no sentinel hack)
    G.score+=G.wave*25;updateHUD();
    G.spawnQ.push({kind:'wave',n:G.wave+1,delay:1.2});
  }
  // enemies
  const cy=CASTLE_Y();
  for(const e of G.enemies){
    if(e.dead)continue;
    e.t+=dt;e.hitT=Math.max(0,e.hitT-dt);
    e.y+=e.speed*dt;
    e.x+=Math.sin(e.t*2)*20*dt;
    if(e.y>cy-20){
      e.dead=true;
      const dmg=e.type==='brute'?20:10;
      G.castleHp-=dmg;sfx.leak();G.shake=0.4;
      burst(e.x,cy,'#ff4a5a',10);
      if(G.castleHp<=0){gameOver();return;}
    }
  }
  G.enemies=G.enemies.filter(e=>!e.dead);
  for(const b of G.bolts)b.life-=dt;
  G.bolts=G.bolts.filter(b=>b.life>0);
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  if(Math.random()<0.1)updateHUD();
}
function gameOver(){
  G.state='over';
  const isBest=G.score>G.best;
  if(isBest){G.best=G.score;try{localStorage.setItem('strike_best',String(G.best));}catch(e){}}
  setTimeout(()=>{
    showOverlay('💥 CASTLE OVERRUN!',
      `${isBest?'<p style="color:#ffd23f;font-weight:900">🏆 NEW BEST!</p>':''}<p style="font-size:26px;font-weight:900">Score: ${G.score}</p><p>Wave reached: ${G.wave}</p><p>Best: ${G.best}</p>`,
      '🔥 Fire Safety: Lightning is dangerous — go inside!',
      '↻ STRIKE AGAIN',()=>{reset();G.state='play';});
  },600);
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();reset();G.state='play';overlay.classList.add('hidden');}
obtn.onclick=()=>{showMathGate();};

// --- Overhaul: living ember background (24 cheap additive particles, deterministic from G.time) ---
/* [w5c perf] Pre-baked glow sprites — the W5b-proven pattern copied from game-04:
   the ember loop's 24 per-frame shadowBlur=8 fills collapsed FPS under software
   rendering (10.0 FPS); blit a one-time radial-glow sprite instead. Colours,
   falloff and alpha unchanged; no gameplay/balance changes. */
function makeGlowSprite(hex){const c=document.createElement('canvas');c.width=c.height=96;const x=c.getContext('2d');
  const r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);
  const gr=x.createRadialGradient(48,48,0,48,48,48);
  gr.addColorStop(0,`rgba(${r},${g},${b},0.9)`);gr.addColorStop(0.35,`rgba(${r},${g},${b},0.38)`);gr.addColorStop(1,`rgba(${r},${g},${b},0)`);
  x.fillStyle=gr;x.fillRect(0,0,96,96);return c;}
const EMBER_SPRITE=makeGlowSprite('#ff8a3a');
const EMBER_SPRITE_GOLD=makeGlowSprite('#ffd23f');
function drawEmbers(){
  ctx.save();ctx.globalCompositeOperation='lighter';
  const maxW=Math.max(W,1),maxH=Math.max(H,1);
  for(let i=0;i<24;i++){
    const sp=14+(i%5)*7,off=(i*197)%maxH;
    const ex=((i*173)%maxW)+Math.sin(G.time*0.7+i)*12;
    const ey=maxH-((G.time*sp+off)%(maxH+30));
    ctx.globalAlpha=Math.max(0.08,0.35+0.3*Math.sin(G.time*3+i*1.7));
    const r=(1.6+(i%3))*7;ctx.drawImage(i%3?EMBER_SPRITE:EMBER_SPRITE_GOLD,ex-r,ey-r,r*2,r*2); // [w5c perf] pre-baked glow (was shadowBlur=8 per ember per frame)
  }
  ctx.restore();
}
function render(){
  // stormy sky
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#0d0a1a');bg.addColorStop(0.7,'#1a1230');bg.addColorStop(1,'#0d0a14');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  // rain
  ctx.strokeStyle='rgba(174,226,255,0.2)';ctx.lineWidth=1;
  for(let i=0;i<40;i++){
    const rx=(i*197+G.time*400)%W,ry=(i*131+G.time*600)%H;
    ctx.beginPath();ctx.moveTo(rx,ry);ctx.lineTo(rx-4,ry+14);ctx.stroke();
  }
  // clouds
  ctx.fillStyle='rgba(60,50,80,0.5)';
  for(let i=0;i<5;i++){
    const cx=(i*311+G.time*30)%(W+200)-100,cy=(i*97)%(H*0.3);
    ctx.beginPath();ctx.ellipse(cx,cy,90,26,0,0,Math.PI*2);ctx.fill();
  }
  drawEmbers();
  ctx.save();
  if(G.shake>0)ctx.translate((Math.random()-0.5)*G.shake*12,(Math.random()-0.5)*G.shake*12);
  // castle
  const cy=CASTLE_Y();
  ctx.fillStyle='#4a3a5a';
  ctx.fillRect(W/2-70,cy-60,140,60);
  ctx.fillStyle='#5a4a6a';
  for(let x=W/2-70;x<W/2+70;x+=28)ctx.fillRect(x,cy-72,20,14);
  ctx.font='36px system-ui';ctx.textAlign='center';
  ctx.shadowColor='#ffd23f';ctx.shadowBlur=14;
  ctx.fillText('🏰',W/2,cy-16);ctx.shadowBlur=0;ctx.textAlign='left';
  // castle hp
  ctx.fillStyle='rgba(0,0,0,.5)';ctx.fillRect(W/2-60,cy+8,120,8);
  ctx.fillStyle=G.castleHp>50?'#4caf50':'#ff4a5a';
  ctx.fillRect(W/2-60,cy+8,120*G.castleHp/100,8);
  // enemies
  for(const e of G.enemies){
    if(e.dead)continue;
    ctx.save();ctx.translate(e.x,e.y);
    const flash=e.hitT>0;
    const g=ctx.createRadialGradient(-5,-5,3,0,0,e.r);
    if(e.type==='brute'){g.addColorStop(0,flash?'#fff':'#5a4a5a');g.addColorStop(1,'#2a1a2a');}
    else if(e.type==='runner'){g.addColorStop(0,flash?'#fff':'#8a7a5a');g.addColorStop(1,'#3a2a1a');}
    else{g.addColorStop(0,flash?'#fff':'#7a6a6a');g.addColorStop(1,'#333');}
    ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,e.r,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#aee2ff';
    ctx.beginPath();ctx.arc(-e.r*0.3,-3,3,0,Math.PI*2);ctx.arc(e.r*0.3,-3,3,0,Math.PI*2);ctx.fill();
    ctx.restore();
  }
  // lightning bolts
  for(const b of G.bolts){
    ctx.globalAlpha=Math.min(1,b.life*4);
    ctx.strokeStyle=b.chain?'#7fd4ff':'#fff';
    ctx.lineWidth=b.chain?3:6;ctx.lineCap='round';
    ctx.shadowColor='#aee2ff';ctx.shadowBlur=16;
    ctx.beginPath();
    b.segs.forEach((s,i)=>i===0?ctx.moveTo(s.x,s.y):ctx.lineTo(s.x,s.y));
    ctx.stroke();
    ctx.shadowBlur=0;
  }
  ctx.globalAlpha=1;
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  ctx.restore();
  // flash
  if(G.flash>0){
    ctx.fillStyle=`rgba(200,220,255,${G.flash*0.5})`;ctx.fillRect(0,0,W,H);
  }
  if(G.state==='play'&&G.wave===1&&G.time<4){
    ctx.fillStyle='rgba(255,255,255,0.8)';ctx.font='900 17px system-ui';ctx.textAlign='center';
    ctx.fillText('👆 TAP TO CALL LIGHTNING! (20 mana)',W/2,H*0.4);
    ctx.textAlign='left';
  }
}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(G.state==='play')update(dt);else G.time+=dt;
  render();
  requestAnimationFrame(loop);
}
document.getElementById('best').textContent='🏆 '+G.best;
document.getElementById('novaBtn').onclick=e=>{e.stopPropagation();novaStrike();};

// [gamer-check batch-09] pause / mute / restart controls (P = pause, M = mute)
window.__mute=false;
let __prePause=null;
const __pTxt=document.getElementById('pausedTxt');
function __togglePause(){
  if(G.state==='play'){__prePause='play';G.state='paused';__pTxt.classList.remove('hidden');}
  else if(G.state==='paused'){G.state=__prePause||'play';__prePause=null;__pTxt.classList.add('hidden');}
}
document.getElementById('btnPause').onclick=e=>{e.stopPropagation();__togglePause();};
document.getElementById('btnMute').onclick=e=>{e.stopPropagation();window.__mute=!window.__mute;e.currentTarget.textContent=window.__mute?'\u{1F507}':'\u{1F50A}';};
document.getElementById('btnRestart').onclick=e=>{e.stopPropagation();if(G.state==='play'||G.state==='paused'){__pTxt.classList.add('hidden');__prePause=null;reset();G.state='play';}};
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(k==='p')__togglePause();if(k==='m')document.getElementById('btnMute').click();});

