scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();
let AC=null;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(window.__mute)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  jump(){tone(450,750,0.09,'square',0.09);},
  star(){tone(900,1400,0.1,'sine',0.1);},
  lava(){tone(300,80,0.35,'sawtooth',0.15);},
  fall(){tone(400,80,0.5,'sawtooth',0.14);},
  click(){tone(600,600,0.06,'square',0.1);}
};
const G={state:'title',score:0,best:0,combo:1,bonus:0,lastStarT:-99,
  px:0,py:0,vx:0,vy:0,onWall:1, // 1=right,-1=left
  camY:0,stars:[],lavas:[],time:0,dead:false,wallGap:0};
try{G.best=parseInt(localStorage.getItem('walljump_best')||'0',10)||0;}catch(e){}
function wallX(side,camY){
  // walls narrow as you climb
  const base=Math.min(W*0.42,180)-Math.min(60,-camY*0.008);
  return side>0?W/2+base:W/2-base;
}
function reset(){
  G.score=0;G.combo=1;G.bonus=0;G.lastStarT=-99;G.camY=0;G.time=0;G.dead=false;G.grace=2.5; // [gauntlet fix] gentle opener grace
  G.stars=[];G.lavas=[];
  G.onWall=1;
  G.px=wallX(1,0)-26;G.py=H*0.7;G.vx=0;G.vy=0; // [w5b] 26px wall inset (was 18): sprite body r16 + arms now render fully inside the shaft
  // initial stars/lava
  for(let i=0;i<10;i++)spawnRow(-i*220);
  updateHUD();
  document.getElementById('best').textContent='🏆 '+G.best;
}
function spawnRow(y){
  // y is world y (negative up)
  if(Math.random()<0.7){
    const side=Math.random()<0.5?-1:1;
    G.stars.push({x:W/2+side*Math.min(W*0.3,130),y:y-Math.random()*120,t:Math.random()*6,taken:false});
  }
  if(Math.random()<0.45){
    const side=Math.random()<0.5?-1:1;
    G.lavas.push({side,y:y-Math.random()*160,h:60+Math.random()*60});
  }
}
function updateHUD(){
  document.getElementById('score').textContent='📏 '+Math.floor(G.score/10)+'m';
  document.getElementById('combo').textContent='🔥 x'+G.combo+(G.bonus>0?' ⭐+'+G.bonus:'');
}
// [gamer-check] jumps only launch FROM a wall (vx===0 while clinging) —
// mid-air taps used to reset vy and let players tap-spam-fly past the whole game.
function doJump(){
  if(G.state!=='play'||G.dead)return;
  if(G.vx!==0)return;
  G.onWall*=-1;
  G.vx=G.onWall*420;
  G.vy=-780;
  sfx.jump();
}
canvas.addEventListener('pointerdown',e=>{
  if(G.state!=='play'||G.dead)return;
  e.preventDefault();
  doJump();
});
addEventListener('keydown',e=>{
  if(e.key===' '||e.key==='ArrowUp'){e.preventDefault();doJump();}
});
const particles=[];
for(let i=0;i<60;i++)particles.push({a:false});
function stickDust(){
  for(let i=0;i<4;i++){const p=particles.find(p=>!p.a);if(!p)break;
    p.a=true;p.x=G.px;p.y=G.py-G.camY;
    p.vx=(Math.random()-0.5)*120;p.vy=(Math.random()-0.5)*120;
    p.life=0.3;p.max=0.3;p.color='#ffb37a';p.size=2.5;}
}
// [overhaul] ambient living embers — cheap additive-glow particles behind gameplay
const amb=[];
for(let i=0;i<24;i++)amb.push({x:Math.random()*2000,y:Math.random()*2000,s:1+Math.random()*2.2,v:14+Math.random()*26,ph:Math.random()*6.28,on:false});
/* [w5c perf] Pre-baked glow sprites — the W5b-proven pattern copied from game-04:
   the ember loop's 24 per-frame shadowBlur=8 fills collapsed FPS under software
   rendering (10.0 FPS); blit a one-time radial-glow sprite instead. Colours,
   falloff and alpha unchanged; no gameplay/balance changes. */
function makeGlowSprite(hex){const c=document.createElement('canvas');c.width=c.height=96;const x=c.getContext('2d');
  const r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);
  const gr=x.createRadialGradient(48,48,0,48,48,48);
  gr.addColorStop(0,`rgba(${r},${g},${b},0.9)`);gr.addColorStop(0.35,`rgba(${r},${g},${b},0.38)`);gr.addColorStop(1,`rgba(${r},${g},${b},0)`);
  x.fillStyle=gr;x.fillRect(0,0,96,96);return c;}
const EMBER_SPRITE=makeGlowSprite('#ff9a3a');
function drawEmbers(){
  ctx.save();ctx.globalCompositeOperation='lighter';
  for(const e of amb){
    if(!e.on){e.on=true;e.x=Math.random()*W;e.y=Math.random()*H;}
    e.y-=e.v/60;e.x+=Math.sin(G.time*1.3+e.ph)*0.18;
    if(e.y<-6){e.y=H+6;e.x=Math.random()*W;}
    const tw=0.55+0.45*Math.sin(G.time*3+e.ph);
    ctx.globalAlpha=0.10+0.14*tw;
    const r=e.s*7;ctx.drawImage(EMBER_SPRITE,e.x-r,e.y-r,r*2,r*2); // [w5c perf] pre-baked glow (was shadowBlur=8 per ember per frame)
  }
  ctx.restore();ctx.globalAlpha=1;
}

function update(dt){
  G.time+=dt;
  if(G.grace>0)G.grace-=dt; // [gauntlet fix] first 2.5s: learn the jump, no deaths
  if(G.combo>1&&G.time-G.lastStarT>4){G.combo=1;updateHUD();}
  G.vy+=1500*dt;
  G.px+=G.vx*dt;G.py+=G.vy*dt;
  // wall stick
  const wl=wallX(-1,G.camY),wr=wallX(1,G.camY);
  if(G.px<wl+26){
    G.px=wl+26;
    if(G.vx<0){G.vx=0;G.vy=Math.min(G.vy,60);G.onWall=-1;stickDust();}
  }
  if(G.px>wr-26){
    G.px=wr-26;
    if(G.vx>0){G.vx=0;G.vy=Math.min(G.vy,60);G.onWall=1;stickDust();}
  }
  if(G.vx===0)G.vy=Math.min(G.vy,90); // clinging: slow genre-standard wall slide
  // lava collision
  const wy=G.py-G.camY;
  for(const l of G.lavas){
    const lx=wallX(l.side,G.camY);
    const ly=l.y-G.camY;
    if(G.grace<=0&&Math.abs(G.px-lx)<30&&wy>ly&&wy<ly+l.h){
      G.dead=true;sfx.lava();
      gameOver('🔥 BURNED!');return;
    }
  }
  // stars
  for(const s of G.stars){
    s.t+=dt*3;
    if(!s.taken&&Math.hypot(G.px-s.x,G.py-s.y)<36){
      s.taken=true;sfx.star();
      G.bonus+=25*G.combo;G.lastStarT=G.time;G.combo=Math.min(8,G.combo+1);
      updateHUD();
      for(let i=0;i<6;i++){const p=particles.find(p=>!p.a);if(!p)break;
        p.a=true;p.x=s.x;p.y=s.y-G.camY;const a=Math.random()*Math.PI*2;
        p.vx=Math.cos(a)*160;p.vy=Math.sin(a)*160;
        p.life=0.4;p.max=0.4;p.color='#ffd23f';p.size=3;}
    }
  }
  G.stars=G.stars.filter(s=>!s.taken&&s.y-G.camY<H+60);
  // camera follows up
  const screenY=G.py-G.camY;
  if(screenY<H*0.35){
    G.camY-=(H*0.35-screenY);
    const h=Math.floor(-G.camY/10);
    if(h>G.score){G.score=h;updateHUD();}
  }
  // spawn more
  let topY=1e9;
  for(const s of G.stars)topY=Math.min(topY,s.y);
  for(const l of G.lavas)topY=Math.min(topY,l.y);
  while(topY>G.camY-400){
    topY-=200+Math.random()*80;
    spawnRow(topY);
  }
  G.lavas=G.lavas.filter(l=>l.y-G.camY<H+100);
  // fell
  if(G.py-G.camY>H+16){ /* [audit 2026-10-18] was H+60: hero sank half-clipped below the screen for ~100px of fall before death registered; H+16 = sprite radius, death now matches the sprite fully leaving view */
    if(G.grace>0){ // [gauntlet fix] during grace a fall just re-sticks you to the wall
      G.px=wallX(1,G.camY)-26;G.py=G.camY+H*0.7;G.vx=0;G.vy=0;G.onWall=1;stickDust();
    }else{
      G.dead=true;sfx.fall();
      gameOver('💥 YOU FELL!');
    }
  }
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)p.a=false;}
}
function gameOver(title){
  const total=G.score+G.bonus;
  const isBest=total>G.best;
  if(isBest){G.best=total;try{localStorage.setItem('walljump_best',String(G.best));}catch(e){}}
  setTimeout(()=>{
    showOverlay(title,
      `${isBest?'<p style="color:#ffd23f;font-weight:900">🏆 NEW BEST!</p>':''}<p style="font-size:26px;font-weight:900">Height: ${Math.floor(G.score/10)}m</p><p>⭐ Star bonus: +${G.bonus}</p><p>Total score: ${total}</p><p>Best total: ${G.best}</p>`,
      '🔥 Fire Safety: Climb to safety!',
      '↻ CLIMB AGAIN',()=>{reset();G.state='play';});
  },600);
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();reset();G.state='play';overlay.classList.add('hidden');}
obtn.onclick=()=>{showMathGate();};
function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#140d08');bg.addColorStop(0.55,'#2a1408');bg.addColorStop(1,'#1e1006');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  const offY=-G.camY;
  // walls
  const wl=wallX(-1,G.camY),wr=wallX(1,G.camY);
  const wg=ctx.createLinearGradient(wl,0,wr,0);
  wg.addColorStop(0,'#3a2a1a');wg.addColorStop(0.5,'rgba(58,42,26,0)');wg.addColorStop(1,'#3a2a1a');
  // [w5b] side gutters carry the game's theme across the full canvas width
  // (the bg gradient + warm strata), instead of blank solid striped panels;
  // a 14px solid wall face still frames the shaft on each side.
  ctx.fillStyle=bg;
  ctx.fillRect(0,0,wl,H);
  ctx.fillRect(wr,0,W-wr,H);
  ctx.fillStyle='rgba(255,138,42,0.06)';
  for(let y=(offY%80);y<H;y+=80){
    ctx.fillRect(0,y,wl,4);ctx.fillRect(wr,y,W-wr,4);
  }
  ctx.fillStyle='#3a2a1a';
  ctx.fillRect(wl-14,0,14,H);
  ctx.fillRect(wr,0,14,H);
  drawEmbers();
  // lava patches
  for(const l of G.lavas){
    const lx=wallX(l.side,G.camY);
    const ly=l.y+offY;
    if(ly<-100||ly>H+100)continue;
    const lg=ctx.createLinearGradient(0,ly,0,ly+l.h);
    lg.addColorStop(0,'#ff6a00');lg.addColorStop(1,'#a32a00');
    ctx.fillStyle=lg;
    const x0=l.side<0?lx-24:lx-6;
    ctx.fillRect(x0,ly,30,l.h);
    ctx.fillStyle='rgba(255,221,68,0.8)';
    for(let i=0;i<3;i++){
      ctx.beginPath();ctx.arc(x0+15,ly+10+i*20+Math.sin(G.time*6+i)*3,4,0,Math.PI*2);ctx.fill();
    }
  }
  // stars
  for(const s of G.stars){
    const sy=s.y+offY;
    if(sy<-30||sy>H+30)continue;
    const bob=Math.sin(s.t)*4;
    ctx.save();ctx.translate(s.x,sy+bob);
    ctx.scale(Math.abs(Math.cos(s.t*0.5))*0.4+0.6,1);
    const g=ctx.createRadialGradient(-4,-4,2,0,0,12);
    g.addColorStop(0,'#fff');g.addColorStop(0.5,'#ffd23f');g.addColorStop(1,'#a37a00');
    ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,11,0,Math.PI*2);ctx.fill();
    ctx.restore();
  }
  // player
  if(!G.dead){
    const py=G.py+offY;
    if(py<H+40){
      ctx.save();ctx.translate(G.px,py);ctx.scale(-G.onWall,1); // [w5b] was squashed to 0.6 width, which read as a half-sprite buried in the wall
      const g=ctx.createRadialGradient(-6,-7,3,0,0,18);
      g.addColorStop(0,'#ffe9a0');g.addColorStop(0.5,'#ff7a2a');g.addColorStop(1,'#d42a1a');
      ctx.shadowColor='#ff7a2a';ctx.shadowBlur=18;
      ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,16,0,Math.PI*2);ctx.fill();
      ctx.shadowBlur=0;
      ctx.fillStyle='#2b1a0e';
      ctx.beginPath();ctx.arc(5,-3,3,0,Math.PI*2);ctx.fill();
      // cling arms
      ctx.strokeStyle='#a33c10';ctx.lineWidth=4;ctx.lineCap='round';
      ctx.beginPath();ctx.moveTo(8,-6);ctx.lineTo(18,-10);ctx.stroke();
      ctx.beginPath();ctx.moveTo(8,6);ctx.lineTo(18,10);ctx.stroke();
      ctx.restore();
    }
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    const sy=p.y;
    ctx.beginPath();ctx.arc(p.x,sy,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  // combo
  if(G.combo>1){
    ctx.fillStyle='#ffd23f';ctx.font='900 18px system-ui';ctx.textAlign='center';
    ctx.fillText(`🔥 COMBO x${G.combo}`,W/2,90);
    ctx.textAlign='left';
  }
  if(G.state==='play'&&G.time<3){
    ctx.fillStyle='rgba(255,255,255,0.8)';ctx.font='900 18px system-ui';ctx.textAlign='center';
    ctx.fillText('TAP OR SPACE — JUMP TO THE OTHER WALL!',W/2,H*0.5);
    ctx.textAlign='left';
  }
}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(G.state==='play'&&!G.dead)update(dt);else G.time+=dt;
  render();
  requestAnimationFrame(loop);
}
document.getElementById('best').textContent='🏆 '+G.best;

// [gamer-check batch-09] pause / mute / restart controls (P = pause, M = mute)
window.__mute=false;
let __prePause=null;
const __pTxt=document.getElementById('pausedTxt');
function __togglePause(){
  if(G.state==='play'){__prePause='play';G.state='paused';__pTxt.classList.remove('hidden');}
  else if(G.state==='paused'){G.state=__prePause||'play';__prePause=null;__pTxt.classList.add('hidden');}
}
document.getElementById('btnPause').onclick=e=>{e.stopPropagation();__togglePause();};
document.getElementById('btnMute').onclick=e=>{e.stopPropagation();window.__mute=!window.__mute;e.currentTarget.textContent=window.__mute?'\u{1F507}':'\u{1F50A}';};
document.getElementById('btnRestart').onclick=e=>{e.stopPropagation();if(G.state==='play'||G.state==='paused'){__pTxt.classList.add('hidden');__prePause=null;reset();G.state='play';}};
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(k==='p')__togglePause();if(k==='m')document.getElementById('btnMute').click();});

requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Jump Juice' — Magma Jump 2D's own
   track. Synthesized Web Audio only. 128 BPM, D major pentatonic: a bouncy
   square lead over a hop bass — carbonated platforming.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Freeze gate CONFIRMED at insertion (2026-10-15): window.__mute mutes, pause sets G.state='paused', and music
   only plays while G.state==='play' — all read from this shell's own code.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-46-magma-jump-2d.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
// Freeze gate (insertion-confirmed 2026-10-15): hard-wired to this shell's
// own confirmed globals — window.__mute / G.state. try/catch kept so it can never throw.
const _mGate=()=>{try{return !!(window.__mute||G.state!=='play');}catch(e){return false;}};
const MUS={on:false,step:0,nextT:0,BPM:128,
 BASS:[38,0,45,0,38,0,45,0, 43,0,50,0,43,0,50,0, 45,0,52,0,45,0,52,0, 47,0,54,0,47,0,52,0],
 LEAD:[74,0,78,0,81,0,78,0, 78,0,81,0,83,0,81,0, 81,0,83,0,86,0,83,0, 81,0,78,0,76,0,74,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(_mGate()){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.13,'triangle',0.055,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.13,'square',0.05,d);
  if(s%8===0||s%8===4)tone(120,45,0.11,'sine',0.12,d); // kick
  if(s%8===2||s%8===6)tone(190,120,0.07,'triangle',0.06,d); // tone-only snare
  if(s%2===0)tone(6800,6800,0.015,'square',0.008,d); // hat click
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

