scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();
addEventListener('resize',()=>{G.px=Math.max(24,Math.min(W-24,G.px));for(const g of G.gatesList)g.x=Math.max(g.w/2,Math.min(W-g.w/2,g.x));});
let AC=null;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(window.__mute)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  gate(){tone(700,1100,0.1,'triangle',0.11);},
  golden(){tone(1000,1800,0.16,'sine',0.13);},
  miss(){tone(350,150,0.2,'sawtooth',0.13);},
  click(){tone(600,600,0.06,'square',0.1);}
};
const G={state:'title',score:0,best:0,lives:3,gates:0,
  px:0,gatesList:[],speed:420,time:0,shake:0,dead:false,streak:0};
try{G.best=parseInt(localStorage.getItem('gatedash_best')||'0',10)||0;}catch(e){}
const TOTAL=25,PY=()=>H*0.72;
function reset(){
  G.score=0;G.lives=3;G.gates=0;G.streak=0;
  G.px=W/2;G.gatesList=[];G.speed=420;G.time=0;G.shake=0;G.dead=false;
  for(let i=0;i<6;i++)spawnGate(-300-i*340); // [gauntlet fix] gentle opener: first gate arrives at ~2s, not ~1.3s
  updateHUD();
  document.getElementById('best').textContent='🏆 '+G.best;
}
function spawnGate(y){
  const w=Math.max(110,190-G.gates*4);
  const x=w/2+Math.random()*(W-w);
  const golden=Math.random()<0.18;
  G.gatesList.push({x,y,w,golden,passed:false,t:Math.random()*6});
}
function updateHUD(){
  document.getElementById('score').textContent='⭐ '+G.score;
  document.getElementById('gates').textContent=`🚪 ${G.gates}/${TOTAL}`+(G.streak>=5?` 🔥x${1+Math.floor(G.streak/5)}`:'');
}
// steering
let dragX=null;
canvas.addEventListener('pointerdown',e=>{dragX=e.clientX;canvas.setPointerCapture(e.pointerId);});
canvas.addEventListener('pointermove',e=>{
  if(dragX===null||G.state!=='play')return;
  G.px+=(e.clientX-dragX)*1.6;dragX=e.clientX;
  G.px=Math.max(24,Math.min(W-24,G.px));
});
canvas.addEventListener('pointerup',()=>dragX=null);
canvas.addEventListener('pointercancel',()=>dragX=null);
const keys={};
addEventListener('keydown',e=>keys[e.key.toLowerCase()]=true);
addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
const particles=[],floaters=[];
for(let i=0;i<80;i++)particles.push({a:false});
for(let i=0;i<10;i++)floaters.push({a:false});
// [overhaul] ambient living embers — cheap additive-glow particles behind gameplay
const amb=[];
for(let i=0;i<24;i++)amb.push({x:Math.random()*2000,y:Math.random()*2000,s:1+Math.random()*2.2,v:14+Math.random()*26,ph:Math.random()*6.28,on:false});
/* [w5c perf] Pre-baked glow sprites — the W5b-proven pattern copied from game-04:
   the ember loop's 24 per-frame shadowBlur=8 fills collapsed FPS under software
   rendering (10.0 FPS); blit a one-time radial-glow sprite instead. Colours,
   falloff and alpha unchanged; no gameplay/balance changes. */
function makeGlowSprite(hex){const c=document.createElement('canvas');c.width=c.height=96;const x=c.getContext('2d');
  const r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);
  const gr=x.createRadialGradient(48,48,0,48,48,48);
  gr.addColorStop(0,`rgba(${r},${g},${b},0.9)`);gr.addColorStop(0.35,`rgba(${r},${g},${b},0.38)`);gr.addColorStop(1,`rgba(${r},${g},${b},0)`);
  x.fillStyle=gr;x.fillRect(0,0,96,96);return c;}
const EMBER_SPRITE=makeGlowSprite('#ff9a3a');
function drawEmbers(){
  ctx.save();ctx.globalCompositeOperation='lighter';
  for(const e of amb){
    if(!e.on){e.on=true;e.x=Math.random()*W;e.y=Math.random()*H;}
    e.y-=e.v/60;e.x+=Math.sin(G.time*1.3+e.ph)*0.18;
    if(e.y<-6){e.y=H+6;e.x=Math.random()*W;}
    const tw=0.55+0.45*Math.sin(G.time*3+e.ph);
    ctx.globalAlpha=0.10+0.14*tw;
    const r=e.s*7;ctx.drawImage(EMBER_SPRITE,e.x-r,e.y-r,r*2,r*2); // [w5c perf] pre-baked glow (was shadowBlur=8 per ember per frame)
  }
  ctx.restore();ctx.globalAlpha=1;
}

function spawnText(x,y,txt,color){
  const f=floaters.find(f=>!f.a);if(!f)return;
  f.a=true;f.x=x;f.y=y;f.txt=txt;f.color=color;f.life=1;
}
function update(dt){
  G.time+=dt;G.shake=Math.max(0,G.shake-dt*3);
  G.speed=Math.min(800,420+G.gates*16);
  if(keys['arrowleft']||keys['a'])G.px=Math.max(24,G.px-720*dt);
  if(keys['arrowright']||keys['d'])G.px=Math.min(W-24,G.px+720*dt);
  const py=PY();
  for(const g of G.gatesList){
    g.y+=G.speed*dt;g.t+=dt*4;
    if(g.passed||g.y<-80)continue;
    // check pass
    if(g.y>py-20&&g.y<py+20){
      g.passed=true;
      if(G.px>g.x-g.w/2&&G.px<g.x+g.w/2){
        // hit!
        G.gates++;
        const pts=(g.golden?30:10)*(1+Math.floor(G.streak/5));
        G.score+=pts;G.streak++;
        if(g.golden)sfx.golden();else sfx.gate();
        spawnText(g.x,py-60,'+'+pts,g.golden?'#ffd23f':'#fff');
        for(let i=0;i<8;i++){const p=particles.find(p=>!p.a);if(!p)break;
          p.a=true;p.x=g.x+(Math.random()-0.5)*g.w;p.y=g.y;
          p.vx=(Math.random()-0.5)*160;p.vy=(Math.random()-0.5)*160;
          p.life=0.4;p.max=0.4;p.color=g.golden?'#ffd23f':'#7fd4ff';p.size=3;}
        updateHUD();
        if(G.gates>=TOTAL){victory();return;}
      }else{
        // miss
        G.lives--;G.streak=0;sfx.miss();G.shake=0.35;
        spawnText(G.px,py-60,'MISS!','#ff4a5a');
        updateHUD();
        if(G.lives<=0){defeat();return;}
      }
    }
  }
  G.gatesList=G.gatesList.filter(g=>g.y<H+120);
  while(G.gatesList.length<6){
    const topY=G.gatesList.length?Math.min(...G.gatesList.map(g=>g.y)):-340;
    spawnGate(topY-340);
  }
  // speed trail
  if(Math.random()<0.5){
    const p=particles.find(p=>!p.a);
    if(p){p.a=true;p.x=G.px+(Math.random()-0.5)*20;p.y=py+20;
      p.vx=0;p.vy=200;p.life=0.3;p.max=0.3;p.color='#ff8a3a';p.size=3;}
  }
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  for(const f of floaters){if(!f.a)continue;f.y-=36*dt;f.life-=dt;if(f.life<=0)f.a=false;}
}
function victory(){
  G.state='over';
  const isBest=G.score>G.best;
  if(isBest){G.best=G.score;try{localStorage.setItem('gatedash_best',String(G.best));}catch(e){}}
  setTimeout(()=>{
    showOverlay('🏆 ALL GATES CLEARED!',
      `${isBest?'<p style="color:#ffd23f;font-weight:900">🏆 NEW BEST!</p>':''}<p style="font-size:26px;font-weight:900">Score: ${G.score}</p><p>Lives left: ${G.lives}</p><p>Best: ${G.best}</p>`,
      '🔥 Fire Safety: You\'re a champion!',
      '↻ DASH AGAIN',()=>{reset();G.state='play';});
  },600);
}
function defeat(){
  G.state='over';
  const isBest=G.score>G.best;
  if(isBest){G.best=G.score;try{localStorage.setItem('gatedash_best',String(G.best));}catch(e){}}
  setTimeout(()=>{
    showOverlay('💥 OUT OF LIVES',
      `<p>Gates cleared: ${G.gates}/${TOTAL}</p><p>Score: ${G.score}</p>`,
      '🔥 Fire Safety: Keep practicing!',
      '↻ TRY AGAIN',()=>{reset();G.state='play';});
  },600);
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');startGame();
  }else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){audio();reset();G.state='play';overlay.classList.add('hidden');}
obtn.onclick=()=>{showMathGate();};
function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#0d0a1a');bg.addColorStop(0.55,'#160b28');bg.addColorStop(1,'#1a0f24');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  drawEmbers();
  ctx.save();
  if(G.shake>0)ctx.translate((Math.random()-0.5)*G.shake*12,(Math.random()-0.5)*G.shake*12);
  // speed lines
  ctx.strokeStyle='rgba(255,255,255,0.06)';ctx.lineWidth=2;
  for(let i=0;i<12;i++){
    const lx=(i*173)%W,ly=(i*271+G.time*G.speed*1.5)%H;
    ctx.beginPath();ctx.moveTo(lx,ly);ctx.lineTo(lx,ly+40);ctx.stroke();
  }
  const py=PY();
  // gates
  for(const g of G.gatesList){
    if(g.y<-80||g.y>H+80)continue;
    const pulse=1+Math.sin(g.t)*0.05;
    ctx.save();ctx.translate(g.x,g.y);ctx.scale(pulse,1);
    const col=g.golden?'#ffd23f':'#7fd4ff';
    ctx.strokeStyle=g.passed?'rgba(255,255,255,0.2)':col;
    ctx.lineWidth=8;ctx.lineCap='round';
    const hw=g.w/2,gh=64;
    // left post
    ctx.beginPath();ctx.moveTo(-hw,-gh/2);ctx.lineTo(-hw,gh/2);ctx.stroke();
    // right post
    ctx.beginPath();ctx.moveTo(hw,-gh/2);ctx.lineTo(hw,gh/2);ctx.stroke();
    // top bar
    ctx.beginPath();ctx.moveTo(-hw,-gh/2);ctx.lineTo(hw,-gh/2);ctx.stroke();
    // glow
    if(!g.passed){
      ctx.fillStyle=g.golden?'rgba(255,210,63,0.12)':'rgba(127,212,255,0.1)';
      ctx.fillRect(-hw,-gh/2,g.w,gh);
    }
    ctx.restore();
    if(g.golden&&!g.passed){
      ctx.fillStyle='#ffd23f';ctx.font='900 14px system-ui';ctx.textAlign='center';
      ctx.fillText('3x',g.x,g.y-gh/2-10);ctx.textAlign='left';
    }
  }
  // player
  if(G.state!=='over'){
    const lean=Math.sin(G.time*8)*0.06;
    ctx.save();ctx.translate(G.px,py);ctx.rotate(lean);
    // dash trail
    const tg=ctx.createLinearGradient(0,0,0,60);
    tg.addColorStop(0,'rgba(255,138,58,0.6)');tg.addColorStop(1,'rgba(255,138,58,0)');
    ctx.fillStyle=tg;
    ctx.beginPath();ctx.ellipse(0,30,14,26,0,0,Math.PI*2);ctx.fill();
    const g=ctx.createRadialGradient(-7,-7,3,0,0,20);
    g.addColorStop(0,'#ffe9a0');g.addColorStop(0.5,'#ff7a2a');g.addColorStop(1,'#d42a1a');
    ctx.shadowColor='#ff7a2a';ctx.shadowBlur=20;
    ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,18,0,Math.PI*2);ctx.fill();
    ctx.shadowBlur=0;
    ctx.fillStyle='#2b1a0e';
    ctx.beginPath();ctx.arc(-6,-3,3.5,0,Math.PI*2);ctx.arc(6,-3,3.5,0,Math.PI*2);ctx.fill();
    ctx.restore();
  }
  // lives
  ctx.font='20px system-ui';ctx.textAlign='left';
  let lx=16;
  for(let i=0;i<3;i++){
    ctx.globalAlpha=i<G.lives?1:0.25;
    ctx.fillText('❤️',lx,84);lx+=28;
  }
  ctx.globalAlpha=1;
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  ctx.textAlign='center';
  for(const f of floaters){
    if(!f.a)continue;
    ctx.globalAlpha=Math.min(1,f.life);
    ctx.font='900 20px system-ui';ctx.fillStyle='#000';
    ctx.fillText(f.txt,f.x+2,f.y+2);ctx.fillStyle=f.color;ctx.fillText(f.txt,f.x,f.y);
  }
  ctx.globalAlpha=1;ctx.textAlign='left';
  if(G.state==='play'&&G.time<3){ // [gauntlet fix] in-play goal/control line (was silent)
    ctx.fillStyle='rgba(255,255,255,0.85)';ctx.font='900 '+(W<520?16:20)+'px system-ui';ctx.textAlign='center'; // [gauntlet fix] sized to fit phone widths
    ctx.fillText('DRAG OR ◀ ▶ — FLY THROUGH THE GATES!',W/2,H*0.3);
    ctx.textAlign='left';
  }
  ctx.restore();
}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(G.state==='play')update(dt);else G.time+=dt;
  render();
  requestAnimationFrame(loop);
}
document.getElementById('best').textContent='🏆 '+G.best;

// [gamer-check batch-09] pause / mute / restart controls (P = pause, M = mute)
window.__mute=false;
let __prePause=null;
const __pTxt=document.getElementById('pausedTxt');
function __togglePause(){
  if(G.state==='play'){__prePause='play';G.state='paused';__pTxt.classList.remove('hidden');}
  else if(G.state==='paused'){G.state=__prePause||'play';__prePause=null;__pTxt.classList.add('hidden');}
}
document.getElementById('btnPause').onclick=e=>{e.stopPropagation();__togglePause();};
document.getElementById('btnMute').onclick=e=>{e.stopPropagation();window.__mute=!window.__mute;e.currentTarget.textContent=window.__mute?'\u{1F507}':'\u{1F50A}';};
document.getElementById('btnRestart').onclick=e=>{e.stopPropagation();if(G.state==='play'||G.state==='paused'){__pTxt.classList.add('hidden');__prePause=null;reset();G.state='play';}};
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(k==='p')__togglePause();if(k==='m')document.getElementById('btnMute').click();});

requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Prime Rush' — Pyra Prime Dash's own
   track. Synthesized Web Audio only. 149 BPM, E dorian: a fast triangle lead
   with a sawtooth answering every phrase — a dash in two voices.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Freeze gate CONFIRMED at insertion (2026-10-15): window.__mute mutes, pause sets G.state='paused', and music
   only plays while G.state==='play' — all read from this shell's own code.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-47-pyra-prime-dash.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
// Freeze gate (insertion-confirmed 2026-10-15): hard-wired to this shell's
// own confirmed globals — window.__mute / G.state. try/catch kept so it can never throw.
const _mGate=()=>{try{return !!(window.__mute||G.state!=='play');}catch(e){return false;}};
const MUS={on:false,step:0,nextT:0,BPM:149, last:0,
 BASS:[40,40,52,40,40,40,52,40, 45,45,57,45,45,45,57,45, 38,38,50,38,38,38,50,38, 47,47,59,47,47,47,54,52],
 LEAD:[76,78,81,83,81,78,76,78, 81,83,85,83,81,83,81,78, 83,85,88,85,83,81,79,81, 83,81,79,78,76,0,0,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(_mGate()){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.1,'square',0.055,d);
  const l=this.LEAD[s];if(l){this.last=l;tone(_mf(l),_mf(l),0.11,'triangle',0.05,d);
   tone(_mf(l),_mf(l),0.11,'sawtooth',0.022,d);} // doubled lead
  if(!l&&(s%8===6||s%8===7)&&this.last)tone(_mf(this.last-4),_mf(this.last-4),0.09,'sawtooth',0.03,d); // saw answer
  if(s%2===0)tone(123,45,0.1,'sine',0.13,d); // kick
  if(s%8===2||s%8===6)tone(190,120,0.07,'triangle',0.07,d); // tone-only snare
  tone(7000,7000,0.012,'square',0.006,d); // hat click
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

