scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();
addEventListener('resize',()=>{if(G.bricks.length&&(Math.abs(W-G._lw)>40||Math.abs(H-G._lh)>160)&&(G.state==='play'||G.state==='title'||G.state==='paused'))initLevel(G.level);});
let AC=null;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(window.__mute)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  bounce(){tone(400,600,0.07,'square',0.08);},
  brick(){tone(500,800,0.09,'triangle',0.1);},
  star(){tone(900,1400,0.12,'sine',0.11);},
  power(){tone(500,1250,0.18,'triangle',0.13);tone(750,1500,0.16,'sine',0.09,0.05);},
  lose(){tone(300,100,0.3,'sawtooth',0.13);},
  win(){[523,659,784,1047].forEach((f,i)=>tone(f,f,0.2,'triangle',0.14,i*0.09));},
  click(){tone(600,600,0.06,'square',0.1);}
};
// level layouts: strings, # = brick, 2 = 2hp, s = star brick, . = empty
const LEVELS=[
  ["..........","..##..##..",".########.",".##ss##...",".########.","..######.."],
  ["..........",".##22##...","..######..",".#s####s#.",".########.","22######22"],
  ["..........","..##22##..",".###ss###.","##222222##",".#s####s#.",".########."],
  ["..........",".22#ss#22.","..######..","##2####2##",".#ss##ss#.","222####222"],
  ["..........","22##ss##22",".###22###.","##s####s##","222####222",".#ss##ss#."],
  ["..........","22##ss##22",".###22###.","##s##22s##",".########.","2#s####s#2"],
  ["..........","22##ss##22",".###22###.","##s222#s##",".#####s##.","2#s####s22"],
  ["..........","22##ss##22",".###222###","##s2222s##","##s###ss##","2#s####.22"],
  ["..........","22##ss##2.",".###222###","##s2222s##","##s#22ss#.","22s####s22"],
  ["..........","22##ss##22","2###222##.",".#s2222s##","##ss22s###","22s22##s2#"],
];
const G={state:'title',level:1,score:0,lives:3,
  px:0,ball:{x:0,y:0,vx:0,vy:0,stuck:true},bricks:[],time:0,shake:0,
  brickW:0,brickH:0,ox:0,oy:0,drops:[],pierceT:0};
function initLevel(n){
  G.level=n;G._lw=W;G._lh=H;G.time=0;G.shake=0;G.bricks=[];G.drops=[];G.pierceT=0;
  const lay=LEVELS[n-1];
  const rows=lay.length,cols=lay[0].length;
  G.brickW=W*0.94/cols;G.brickH=Math.min(34,H*0.05);
  G.ox=(W-G.brickW*cols)/2;G.oy=H*0.14;
  for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){
    const ch=lay[r][c];
    if(ch==='#'||ch==='2'||ch==='s')
      G.bricks.push({r,c,hp:ch==='2'?2:1,star:ch==='s',t:Math.random()*6});
  }
  G.px=W/2;
  G.ball.stuck=true;
  G.ball.x=W/2;G.ball.y=H*0.82-24;
  document.getElementById('level').textContent=`LV ${n}/10`;
  updateHUD();
}
function updateHUD(){
  document.getElementById('score').textContent='⭐ '+G.score;
  document.getElementById('lives').textContent='❤️'.repeat(Math.max(0,G.lives))||'💔';
}
const PW=()=>Math.min(130,W*0.24);
const PY=()=>H*0.82;
// paddle control
let dragX=null;
canvas.addEventListener('pointerdown',e=>{
  if(G.state!=='play')return;
  dragX=e.clientX;canvas.setPointerCapture(e.pointerId);
  if(G.ball.stuck){launchBall();}
});
canvas.addEventListener('pointermove',e=>{
  if(dragX===null||G.state!=='play')return;
  G.px+=(e.clientX-dragX)*1.8;dragX=e.clientX;
  G.px=Math.max(PW()/2,Math.min(W-PW()/2,G.px));
});
canvas.addEventListener('pointerup',()=>dragX=null);
canvas.addEventListener('pointercancel',()=>dragX=null);
const keys={};
addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(e.key===' '&&G.state==='play'&&G.ball.stuck)launchBall();});
addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
function launchBall(){
  if(!G.ball.stuck)return;
  G.ball.stuck=false;
  const a=-Math.PI/2+(Math.random()-0.5)*0.6;
  const sp=520;
  G.ball.vx=Math.cos(a)*sp;G.ball.vy=Math.sin(a)*sp;
  G.ball.x=G.px;G.ball.y=PY()-20;
}
const particles=[],floaters=[];
for(let i=0;i<100;i++)particles.push({a:false});
for(let i=0;i<10;i++)floaters.push({a:false});
// [overhaul] ambient living embers — cheap additive-glow particles behind gameplay
const amb=[];
for(let i=0;i<24;i++)amb.push({x:Math.random()*2000,y:Math.random()*2000,s:1+Math.random()*2.2,v:14+Math.random()*26,ph:Math.random()*6.28,on:false});
/* [w5c perf] Pre-baked glow sprites — the W5b-proven pattern copied from game-04:
   the ember loop's 24 per-frame shadowBlur=8 fills collapsed FPS under software
   rendering (10.0 FPS); blit a one-time radial-glow sprite instead. Colours,
   falloff and alpha unchanged; no gameplay/balance changes. */
function makeGlowSprite(hex){const c=document.createElement('canvas');c.width=c.height=96;const x=c.getContext('2d');
  const r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);
  const gr=x.createRadialGradient(48,48,0,48,48,48);
  gr.addColorStop(0,`rgba(${r},${g},${b},0.9)`);gr.addColorStop(0.35,`rgba(${r},${g},${b},0.38)`);gr.addColorStop(1,`rgba(${r},${g},${b},0)`);
  x.fillStyle=gr;x.fillRect(0,0,96,96);return c;}
const EMBER_SPRITE=makeGlowSprite('#ff9a3a');
function drawEmbers(){
  ctx.save();ctx.globalCompositeOperation='lighter';
  for(const e of amb){
    if(!e.on){e.on=true;e.x=Math.random()*W;e.y=Math.random()*H;}
    e.y-=e.v/60;e.x+=Math.sin(G.time*1.3+e.ph)*0.18;
    if(e.y<-6){e.y=H+6;e.x=Math.random()*W;}
    const tw=0.55+0.45*Math.sin(G.time*3+e.ph);
    ctx.globalAlpha=0.10+0.14*tw;
    const r=e.s*7;ctx.drawImage(EMBER_SPRITE,e.x-r,e.y-r,r*2,r*2); // [w5c perf] pre-baked glow (was shadowBlur=8 per ember per frame)
  }
  ctx.restore();ctx.globalAlpha=1;
}

function burst(x,y,color,n){
  for(let i=0;i<n;i++){const p=particles.find(p=>!p.a);if(!p)break;
    const a=Math.random()*Math.PI*2;
    p.a=true;p.x=x;p.y=y;p.vx=Math.cos(a)*200;p.vy=Math.sin(a)*200;
    p.life=0.4;p.max=0.4;p.color=color;p.size=3;}
}
function spawnText(x,y,txt,color){
  const f=floaters.find(f=>!f.a);if(!f)return;
  f.a=true;f.x=x;f.y=y;f.txt=txt;f.color=color;f.life=1;
}
function update(dt){
  G.time+=dt;G.shake=Math.max(0,G.shake-dt*3);
  // [weapon] Ember Splitter: falling cores + pierce timer
  G.pierceT=Math.max(0,G.pierceT-dt);
  for(let i=G.drops.length-1;i>=0;i--){const d=G.drops[i];d.y+=d.vy*dt;d.t+=dt*4;
    if(d.y>PY()-16&&d.y<PY()+18&&Math.abs(d.x-G.px)<PW()/2+12){
      G.drops.splice(i,1);G.pierceT=5;sfx.power();
      spawnText(G.px,PY()-34,'EMBER SPLITTER!','#ffd23f');burst(G.px,PY()-10,'#ffd23f',10);
    }else if(d.y>H+24)G.drops.splice(i,1);}
  if(keys['arrowleft']||keys['a'])G.px=Math.max(PW()/2,G.px-520*dt);
  if(keys['arrowright']||keys['d'])G.px=Math.min(W-PW()/2,G.px+520*dt);
  const b=G.ball;
  if(b.stuck){b.x=G.px;updateParts(dt);return;}
  // speed cap
  const sp=Math.hypot(b.vx,b.vy),maxSp=760;
  if(sp>maxSp){b.vx*=maxSp/sp;b.vy*=maxSp/sp;}
  // min vertical to avoid flat loops
  if(Math.abs(b.vy)<120){b.vy+=b.vy>=0?60*dt:-60*dt;}
  b.x+=b.vx*dt;b.y+=b.vy*dt;
  const R=12;
  // walls
  if(b.x<R){b.x=R;b.vx=Math.abs(b.vx);sfx.bounce();}
  if(b.x>W-R){b.x=W-R;b.vx=-Math.abs(b.vx);sfx.bounce();}
  if(b.y<R){b.y=R;b.vy=Math.abs(b.vy);sfx.bounce();}
  // paddle
  const pw=PW(),py=PY();
  if(b.vy>0&&b.y+R>py-10&&b.y-R<py+10&&Math.abs(b.x-G.px)<pw/2+R){
    b.y=py-10-R;
    const rel=(b.x-G.px)/(pw/2);
    const ang=rel*1.05; // angle from vertical
    const spd=Math.min(720,Math.hypot(b.vx,b.vy)*1.03+14);
    b.vx=Math.sin(ang)*spd;b.vy=-Math.cos(ang)*spd;
    sfx.bounce();
  }
  // bricks
  for(let i=G.bricks.length-1;i>=0;i--){
    const br=G.bricks[i];
    const bx=G.ox+br.c*G.brickW,by=G.oy+br.r*G.brickH;
    if(b.x+R>bx&&b.x-R<bx+G.brickW&&b.y+R>by&&b.y-R<by+G.brickH){
      // side of hit
      const ox=(G.brickW/2+R)-Math.abs(b.x-(bx+G.brickW/2));
      const oy=(G.brickH/2+R)-Math.abs(b.y-(by+G.brickH/2));
      if(G.pierceT<=0){if(ox<oy)b.vx*=-1;else b.vy*=-1;}
      br.hp--;sfx.brick();G.shake=0.15;
      burst(b.x,b.y,br.star?'#ffd23f':'#ff8a3a',6);
      if(br.hp<=0){
        G.bricks.splice(i,1);
        const pts=br.star?50:10;
        G.score+=pts;
        if(br.star){sfx.star();spawnText(bx+G.brickW/2,by,'+'+pts,'#ffd23f');}
        if(Math.random()<0.16)G.drops.push({x:bx+G.brickW/2,y:by+G.brickH/2,vy:230,t:0});
        updateHUD();
      }
      break;
    }
  }
  // fell
  if(b.y>H+30){
    G.lives--;updateHUD();sfx.lose();G.shake=0.4;
    if(G.lives<=0){
      setTimeout(()=>gameOver(false),400);
      G.state='dying';
    }else{
      b.stuck=true;b.x=G.px;b.y=py-24;
    }
    return;
  }
  // win level
  if(G.bricks.length===0){
    G.score+=100*G.level;updateHUD();sfx.win();
    setTimeout(()=>levelDone(),500);
    G.state='clear';
    return;
  }
  updateParts(dt);
}
function updateParts(dt){
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  for(const f of floaters){if(!f.a)continue;f.y-=36*dt;f.life-=dt;if(f.life<=0)f.a=false;}
}
function levelDone(){
  if(G.level>=10){
    showOverlay('🏆 BOUNCE MASTER!',
      `<p style="font-size:24px;font-weight:900">Final Score: ${G.score}</p><p>All 10 levels smashed!</p>`,
      '🔥 Fire Safety: You\'re a champion!',
      '↻ PLAY AGAIN',()=>{G.score=0;G.lives=3;initLevel(1);G.state='play';});
  }else{
    showOverlay(`⭐ LEVEL ${G.level} CLEAR!`,
      `<p>Score: ${G.score}</p><p>Lives: ${'❤️'.repeat(G.lives)}</p>`,
      '🔥 Fire Safety: Bounce back!',
      '▶ NEXT LEVEL',()=>{initLevel(G.level+1);G.state='play';});
  }
}
function gameOver(won){
  G.state='over';
  setTimeout(()=>{
    showOverlay('💥 OUT OF LIVES',
      `<p>Score: ${G.score}</p>`,
      '🔥 Fire Safety: Keep practicing!',
      '↻ TRY AGAIN',()=>{G.score=0;G.lives=3;initLevel(G.level);G.state='play';});
  },400);
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');showLevels();
  }else document.getElementById('ma').value='';
}
function showLevels(){
  otitle.innerHTML='🔥 PICK LEVEL';
  let h='';
  for(let i=1;i<=10;i++)h+=`<button class="lvlBtn" onclick="event.stopPropagation();pickLevel(${i})">${i}</button>`;
  obody.innerHTML=`<p>Smash every brick to win!</p><div id="lvlSel">${h}</div>`;
  obtn.style.display='none';
  overlay.classList.remove('hidden');
}
function pickLevel(n){sfx.click();audio();G.score=0;G.lives=3;initLevel(n);G.state='play';overlay.classList.add('hidden');}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;
  obtn.textContent=btn;obtn.style.display='';
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
obtn.onclick=()=>{showMathGate();};
function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#0d0a1a');bg.addColorStop(0.55,'#180c20');bg.addColorStop(1,'#1a0f14');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  drawEmbers();
  ctx.save();
  if(G.shake>0)ctx.translate((Math.random()-0.5)*G.shake*12,(Math.random()-0.5)*G.shake*12);
  // bricks
  for(const br of G.bricks){
    const bx=G.ox+br.c*G.brickW,by=G.oy+br.r*G.brickH;
    const g=ctx.createLinearGradient(0,by,0,by+G.brickH);
    if(br.star){g.addColorStop(0,'#ffd76a');g.addColorStop(1,'#a3701a');}
    else if(br.hp>1){g.addColorStop(0,'#b0b0c8');g.addColorStop(1,'#5a5a72');}
    else{g.addColorStop(0,'#ff8a3a');g.addColorStop(1,'#a33c10');}
    ctx.fillStyle=g;
    ctx.beginPath();ctx.roundRect(bx+2,by+2,G.brickW-4,G.brickH-4,6);ctx.fill();
    if(br.star){
      ctx.fillStyle='#2a1206';ctx.font=`900 ${G.brickH*0.55}px system-ui`;ctx.textAlign='center';
      ctx.fillText('⭐',bx+G.brickW/2,by+G.brickH*0.78);ctx.textAlign='left';
    }else if(br.hp>1){
      ctx.fillStyle='rgba(255,255,255,0.5)';ctx.font=`900 ${G.brickH*0.5}px system-ui`;ctx.textAlign='center';
      ctx.fillText('2',bx+G.brickW/2,by+G.brickH*0.75);ctx.textAlign='left';
    }
  }
  // [weapon] falling Splitter Cores
  for(const d of G.drops){
    ctx.save();ctx.translate(d.x,d.y+Math.sin(d.t)*3);
    ctx.shadowColor='#ffd23f';ctx.shadowBlur=18;
    const dg=ctx.createRadialGradient(-3,-3,2,0,0,12);
    dg.addColorStop(0,'#fff2c8');dg.addColorStop(0.6,'#ffd23f');dg.addColorStop(1,'#a35a10');
    ctx.fillStyle=dg;ctx.beginPath();ctx.arc(0,0,11,0,Math.PI*2);ctx.fill();
    ctx.shadowBlur=0;ctx.font='13px system-ui';ctx.textAlign='center';ctx.fillText('🔥',0,5);ctx.textAlign='left';
    ctx.restore();
  }
  // paddle
  const pw=PW(),py=PY();
  const pg=ctx.createLinearGradient(0,py-10,0,py+10);
  pg.addColorStop(0,'#ffd76a');pg.addColorStop(1,'#a35a10');
  ctx.shadowColor='#ff8a3a';ctx.shadowBlur=14;
  ctx.fillStyle=pg;
  ctx.beginPath();ctx.roundRect(G.px-pw/2,py-10,pw,20,10);ctx.fill();
  ctx.shadowBlur=0;
  // ball
  if(G.state==='play'||G.state==='clear'){
    const b=G.ball;
    const g=ctx.createRadialGradient(b.x-4,b.y-4,2,b.x,b.y,13);
    g.addColorStop(0,'#fff2c8');g.addColorStop(0.5,'#ff8a3a');g.addColorStop(1,'#a32a10');
    ctx.fillStyle=g;ctx.beginPath();ctx.arc(b.x,b.y,12,0,Math.PI*2);ctx.fill();
    ctx.shadowColor=G.pierceT>0?'#ffd23f':'#ff8a3a';ctx.shadowBlur=G.pierceT>0?26:14;
    ctx.fill();ctx.shadowBlur=0;
    if(G.pierceT>0){ctx.fillStyle='#ffd23f';ctx.font='900 16px system-ui';ctx.textAlign='center';ctx.fillText('🔥 EMBER SPLITTER '+Math.ceil(G.pierceT)+'s',W/2,110);ctx.textAlign='left';}
    // trail
    ctx.fillStyle='rgba(255,138,58,0.35)';
    ctx.beginPath();ctx.arc(b.x-b.vx*0.02,b.y-b.vy*0.02,8,0,Math.PI*2);ctx.fill();
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  ctx.textAlign='center';
  for(const f of floaters){
    if(!f.a)continue;
    ctx.globalAlpha=Math.min(1,f.life);
    ctx.font='900 20px system-ui';ctx.fillStyle='#000';
    ctx.fillText(f.txt,f.x+2,f.y+2);ctx.fillStyle=f.color;ctx.fillText(f.txt,f.x,f.y);
  }
  ctx.globalAlpha=1;ctx.textAlign='left';
  ctx.restore();
  if(G.state==='play'&&G.ball.stuck){
    ctx.fillStyle='rgba(255,255,255,0.8)';ctx.font='900 17px system-ui';ctx.textAlign='center';
    ctx.fillText('TAP TO LAUNCH!',W/2,H*0.6);
    ctx.textAlign='left';
  }
}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(G.state==='play')update(dt);else G.time+=dt;
  render();
  requestAnimationFrame(loop);
}

// [gamer-check batch-09] pause / mute / restart controls (P = pause, M = mute)
window.__mute=false;
let __prePause=null;
const __pTxt=document.getElementById('pausedTxt');
function __togglePause(){
  if(G.state==='play'){__prePause='play';G.state='paused';__pTxt.classList.remove('hidden');}
  else if(G.state==='paused'){G.state=__prePause||'play';__prePause=null;__pTxt.classList.add('hidden');}
}
document.getElementById('btnPause').onclick=e=>{e.stopPropagation();__togglePause();};
document.getElementById('btnMute').onclick=e=>{e.stopPropagation();window.__mute=!window.__mute;e.currentTarget.textContent=window.__mute?'\u{1F507}':'\u{1F50A}';};
document.getElementById('btnRestart').onclick=e=>{e.stopPropagation();if(G.state==='play'||G.state==='paused'){__pTxt.classList.add('hidden');__prePause=null;initLevel(G.level);G.state='play';}};
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(k==='p')__togglePause();if(k==='m')document.getElementById('btnMute').click();});

requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Master Bounce' — Ember Bounce Master's own
   track. Synthesized Web Audio only. 131 BPM, G major pentatonic: virtuoso
   bounce — the lead runs get denser every bar and the drum layers stack up
   underneath.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Freeze gate CONFIRMED at insertion (2026-10-15): window.__mute mutes, pause sets G.state='paused', and music
   only plays while G.state==='play' — all read from this shell's own code.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-50-ember-bounce-master.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
// Freeze gate (insertion-confirmed 2026-10-15): hard-wired to this shell's
// own confirmed globals — window.__mute / G.state. try/catch kept so it can never throw.
const _mGate=()=>{try{return !!(window.__mute||G.state!=='play');}catch(e){return false;}};
const MUS={on:false,step:0,nextT:0,BPM:131,
 BASS:[43,55,43,55,43,55,43,55, 48,60,48,60,48,60,48,60, 40,52,40,52,40,52,40,52, 38,50,38,50,38,50,38,50],
 LEAD:[79,81,83,86,83,81,79,81, 83,81,79,76,79,81,83,81, 86,88,86,83,81,83,86,83, 88,86,83,81,79,76,74,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(_mGate()){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);const bar=(s/8)|0;
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.11,'square',0.05,d);
  const l=this.LEAD[s];if(l){tone(_mf(l),_mf(l),0.12,'square',0.045,d);
   if(bar>=2)tone(_mf(l),_mf(l),0.12,'triangle',0.02,d);} // doubling joins bar 3
  if(bar===0){if(s%8===0)tone(120,45,0.11,'sine',0.12,d);}
  else if(s%8===0||s%8===4)tone(120,45,0.11,'sine',0.13,d); // kick fills in
  if(bar>=1&&(s%8===2||s%8===6))tone(190,120,0.07,'triangle',0.07,d); // snare joins bar 2
  if(bar>=3&&s%2===0)tone(6800,6800,0.015,'square',0.008,d); // hats join bar 4
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

