'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
const toolBar=document.getElementById('toolBar');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();
let AC=null;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(window.__FB_MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  drop(){tone(500,300,0.2,'sine',0.1);},
  win(){[523,659,784,1047].forEach((f,i)=>tone(f,f,0.2,'triangle',0.14,i*0.09));},
  splash(){tone(400,80,0.35,'sawtooth',0.14);},
  draw(){tone(700,700,0.04,'sine',0.05);},
  click(){tone(600,600,0.06,'square',0.1);}
};
// levels: walls (static), waters, goal, spawn
const LEVELS=[
  {walls:[{x:0.3,y:0.45,w:0.4,h:0.04}],waters:[],goal:{x:0.5,y:0.88},spawn:{x:0.5,y:0.12},items:3,slimers:[{x:0.63,y:0.40}]},
  {walls:[{x:0.1,y:0.4,w:0.35,h:0.04},{x:0.55,y:0.6,w:0.35,h:0.04}],waters:[],goal:{x:0.5,y:0.88},spawn:{x:0.2,y:0.12},items:3},
  {walls:[{x:0.3,y:0.5,w:0.4,h:0.04}],waters:[{x:0.5,y:0.72,r:0.05}],goal:{x:0.5,y:0.88},spawn:{x:0.5,y:0.12},items:3,slimers:[{x:0.62,y:0.45}]},
  {walls:[{x:0.05,y:0.35,w:0.3,h:0.04},{x:0.65,y:0.35,w:0.3,h:0.04},{x:0.3,y:0.62,w:0.4,h:0.04}],waters:[{x:0.5,y:0.78,r:0.05}],goal:{x:0.85,y:0.88},spawn:{x:0.5,y:0.1},items:4},
  {walls:[{x:0.2,y:0.3,w:0.25,h:0.04},{x:0.55,y:0.45,w:0.25,h:0.04},{x:0.2,y:0.6,w:0.25,h:0.04}],waters:[{x:0.35,y:0.75,r:0.05},{x:0.65,y:0.75,r:0.05}],goal:{x:0.5,y:0.9},spawn:{x:0.3,y:0.1},items:4},
  {walls:[{x:0.05,y:0.28,w:0.28,h:0.04},{x:0.67,y:0.28,w:0.28,h:0.04},{x:0.36,y:0.5,w:0.28,h:0.04},{x:0.05,y:0.68,w:0.28,h:0.04},{x:0.67,y:0.68,w:0.28,h:0.04}],waters:[{x:0.5,y:0.6,r:0.045}],goal:{x:0.5,y:0.9},spawn:{x:0.5,y:0.08},items:5,slimers:[{x:0.57,y:0.45}]},
  {walls:[{x:0.25,y:0.42,w:0.38,h:0.04}],waters:[{x:0.62,y:0.7,r:0.05}],goal:{x:0.35,y:0.88},spawn:{x:0.55,y:0.12},items:4},
  {walls:[{x:0.1,y:0.38,w:0.35,h:0.04},{x:0.55,y:0.58,w:0.35,h:0.04}],waters:[{x:0.5,y:0.74,r:0.05}],goal:{x:0.5,y:0.88},spawn:{x:0.2,y:0.12},items:4},
  {walls:[{x:0.2,y:0.3,w:0.25,h:0.04},{x:0.55,y:0.45,w:0.25,h:0.04},{x:0.2,y:0.6,w:0.25,h:0.04}],waters:[{x:0.35,y:0.75,r:0.05},{x:0.65,y:0.75,r:0.05}],goal:{x:0.85,y:0.88},spawn:{x:0.5,y:0.1},items:5,slimers:[{x:0.30,y:0.55}]},
  {walls:[{x:0.05,y:0.3,w:0.28,h:0.04},{x:0.67,y:0.3,w:0.28,h:0.04},{x:0.36,y:0.5,w:0.28,h:0.04},{x:0.2,y:0.68,w:0.3,h:0.04}],waters:[{x:0.65,y:0.6,r:0.045},{x:0.72,y:0.78,r:0.045}],goal:{x:0.5,y:0.9},spawn:{x:0.5,y:0.08},items:5},
  {walls:[{x:0.05,y:0.28,w:0.28,h:0.04},{x:0.67,y:0.28,w:0.28,h:0.04},{x:0.36,y:0.5,w:0.28,h:0.04},{x:0.05,y:0.68,w:0.28,h:0.04},{x:0.67,y:0.68,w:0.28,h:0.04}],waters:[{x:0.3,y:0.6,r:0.045},{x:0.7,y:0.78,r:0.045}],goal:{x:0.5,y:0.9},spawn:{x:0.5,y:0.08},items:5,slimers:[{x:0.84,y:0.63}]},
];
const G={state:'title',level:1,score:0,
  fx:0,fy:0,vx:0,vy:0,dropped:false,done:false,
  ramps:[],fans:[],itemsLeft:0,tool:'ramp',drawing:null,
  drops:[],slimers:[],
  time:0,shake:0};
function initLevel(n){
  const L=LEVELS[n-1];
  G.level=n;G.time=0;G.shake=0;
  G.fx=L.spawn.x*W;G.fy=L.spawn.y*H;G.vx=0;G.vy=0;
  G.dropped=false;G.done=false;G._stillT=0;G._ax=undefined;
  G.ramps=[];G.fans=[];G.itemsLeft=L.items;G.drawing=null;
  G.drops=[];G.slimers=(L.slimers||[]).map(s=>({x:s.x*W,y:s.y*H,baseR:26,scale:1,cover:0,state:'live',growT:0,panicT:0,wobT:0,defeatedT:0,slideDir:1}));
  document.getElementById('level').textContent=`LV ${n}/11`;
  document.getElementById('items').textContent='🛠️ '+G.itemsLeft;
  updateHUD();
}
function updateHUD(){document.getElementById('score').textContent='⭐ '+G.score;}
function setTool(t){
  G.tool=t;
  document.querySelectorAll('.tool').forEach(b=>b.classList.remove('sel'));
  const map={ramp:'toolRamp',fan:'toolFan',erase:'toolErase',water:'toolWater',smother:'toolSmother'};
  const id=map[t];if(id)document.getElementById(id).classList.add('sel');
}
document.getElementById('toolRamp').addEventListener('click',()=>setTool('ramp'));
document.getElementById('toolFan').addEventListener('click',()=>setTool('fan'));
document.getElementById('toolErase').addEventListener('click',()=>setTool('erase'));
document.getElementById('toolWater').addEventListener('click',()=>setTool('water'));
document.getElementById('toolSmother').addEventListener('click',()=>setTool('smother'));
document.getElementById('toolDrop').addEventListener('click',()=>{if(G.state==='play')dropFlame();});
canvas.addEventListener('pointerdown',e=>{
  if(G.state!=='play'||G.done)return;
  const rect=canvas.getBoundingClientRect();
  const x=e.clientX-rect.left,y=e.clientY-rect.top;
  // Slimer payload drops: 💧 water / 🛎️ smother fall from the top at the tap's x.
  // They work before AND after the flame drop — smothering the Slimer is its own mini-puzzle.
  if(G.tool==='water'||G.tool==='smother'){spawnDrop(x,G.tool);return;}
  if(G.dropped)return;
  if(G.tool==='erase'){
    for(let i=G.ramps.length-1;i>=0;i--){
      const r=G.ramps[i];
      const d=Math.hypot(x-(r.x1+r.x2)/2,y-(r.y1+r.y2)/2);
      if(d<50){G.ramps.splice(i,1);G.itemsLeft++;updItems();sfx.click();return;}
    }
    for(let i=G.fans.length-1;i>=0;i--){
      const f=G.fans[i];
      if(Math.hypot(x-f.x,y-f.y)<50){G.fans.splice(i,1);G.itemsLeft++;updItems();sfx.click();return;}
    }
    return;
  }
  if(G.tool==='fan'){
    if(G.itemsLeft<=0){sfx.click();return;}
    G.fans.push({x,y,t:Math.random()*6});
    G.itemsLeft--;updItems();sfx.draw();
    canvas.setPointerCapture(e.pointerId);
    G._fanDrag=G.fans[G.fans.length-1];
    return;
  }
  // ramp drawing
  if(G.itemsLeft<=0){sfx.click();return;}
  G.drawing={x1:x,y1:y,x2:x,y2:y};
  canvas.setPointerCapture(e.pointerId);
});
canvas.addEventListener('pointermove',e=>{
  const rect=canvas.getBoundingClientRect();
  const x=e.clientX-rect.left,y=e.clientY-rect.top;
  if(G.drawing){G.drawing.x2=x;G.drawing.y2=y;if(Math.hypot(x-(G._dsx||0),y-(G._dsy||0))>26){G._dsx=x;G._dsy=y;sfx.draw();}} // draw sfx was firing every pointermove (tone spam)
  if(G._fanDrag){G._fanDrag.x=x;G._fanDrag.y=y;}
});
canvas.addEventListener('pointerup',()=>{
  if(G.drawing){
    const d=G.drawing;
    if(Math.hypot(d.x2-d.x1,d.y2-d.y1)>30){
      G.ramps.push(d);G.itemsLeft--;updItems();
    }
    G.drawing=null;
  }
  G._fanDrag=null;
});
function updItems(){document.getElementById('items').textContent='🛠️ '+G.itemsLeft;}
/* ===== SLIMER (Jeff 2026-10-17 spec: SLIMERS-SPEC.md) — oil-blob villain.
   WATER IS THE TRAP: a 💧 drop makes him splash, spread and GROW (cap 1.6x),
   target NOT cleared. SMOTHER WINS: a 🛎️ lid drop builds cover per hit,
   he shrinks and panics; 2 hits = defeated (flattened under the lid, dizzy
   eyes peeking, slides off on his own slick, +50 = a standard target's
   minimum goal value). He never harms the flame/Babys; the joke is on him. */
function spawnDrop(x,kind){
  if(G.state!=='play'||G.done)return;
  if(G.drops.length>24)return;
  G.drops.push({x:Math.max(20,Math.min(W-20,x)),y:34,vy:0,kind,r:kind==='water'?13:16,spin:Math.random()*6});
  sfx.drop();
}
function updateDrops(dt){
  for(let i=G.drops.length-1;i>=0;i--){
    const d=G.drops[i];
    d.vy+=900*dt;d.y+=d.vy*dt;d.spin+=dt*3;
    let used=false;
    for(const s of G.slimers){
      if(s.state!=='live')continue;
      const rr=s.baseR*s.scale+d.r;
      if(Math.hypot(d.x-s.x,d.y-s.y)<rr){slimerHit(s,d.kind);used=true;break;}
    }
    if(used){G.drops.splice(i,1);continue;}
    if(d.y>H+30)G.drops.splice(i,1);
  }
}
function updateSlimers(dt){
  for(let i=G.slimers.length-1;i>=0;i--){
    const s=G.slimers[i];
    if(s.growT>0)s.growT-=dt;
    if(s.panicT>0)s.panicT-=dt;
    if(s.wobT>0)s.wobT-=dt;
    if(s.state==='defeated'){
      s.defeatedT+=dt;
      s.x+=s.slideDir*240*dt; // slides away on his own slick
      if(s.defeatedT>1.5||s.x<-90||s.x>W+90)G.slimers.splice(i,1);
    }
  }
}
function slimerHit(s,kind){
  if(s.state!=='live')return;
  if(kind==='water'){
    // THE TRAP: splashes, spreads, comes back BIGGER and smugger — not cleared
    s.scale=Math.min(1.6,s.scale+0.3);
    s.growT=1.4;s.wobT=1.2;
    sfx.splash();G.shake=Math.max(G.shake,0.3);
    const cols=['#4aa3d8','#b45fe0','#3fe0c8','#e08a3f','#e0529e'];
    for(let i=0;i<12;i++){const p=particles.find(p=>!p.a);if(!p)break;
      p.a=true;p.x=s.x+(Math.random()-0.5)*s.baseR*s.scale*2;p.y=s.y-s.baseR*s.scale;
      const a=Math.random()*Math.PI*2;
      p.vx=Math.cos(a)*170;p.vy=Math.sin(a)*170-70;
      p.life=0.6;p.max=0.6;p.color=cols[i%cols.length];p.size=4;}
  }else{
    // SMOTHER: cover builds per hit, he shrinks and panics
    s.cover++;
    s.scale=Math.max(0.65,s.scale-0.2);
    s.panicT=1.4;s.wobT=0.8;
    tone(300,110,0.22,'square',0.10);
    for(let i=0;i<10;i++){const p=particles.find(p=>!p.a);if(!p)break;
      p.a=true;p.x=s.x+(Math.random()-0.5)*s.baseR*2;p.y=s.y-s.baseR*s.scale;
      p.vx=(Math.random()-0.5)*160;p.vy=-60-Math.random()*60;
      p.life=0.55;p.max=0.55;p.color=i%2?'#c9b458':'#9aa3a8';p.size=4;}
    if(s.cover>=2){
      s.state='defeated';s.defeatedT=0;s.slideDir=(s.x<W/2?1:-1);
      G.score+=50;updateHUD();
      sfx.win();G.shake=Math.max(G.shake,0.25);
    }
  }
}
function spiralEye(cx,cy,rr){
  ctx.strokeStyle='#0d0716';ctx.lineWidth=1.6;
  ctx.beginPath();
  for(let a=0;a<Math.PI*4.5;a+=0.25){
    const q=rr*a/(Math.PI*4.5);
    const xx=cx+Math.cos(a)*q,yy=cy+Math.sin(a)*q;
    if(a===0)ctx.moveTo(xx,yy);else ctx.lineTo(xx,yy);
  }
  ctx.stroke();
}
function drawSlimerFace(px,py,r,s){
  if(s.panicT>0){
    // wide round panic eyes + small wobbly 'o' mouth
    for(const ex of [-r*0.42,r*0.42]){
      ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(px+ex,py,r*0.42,0,Math.PI*2);ctx.fill();
      ctx.lineWidth=3;ctx.strokeStyle='#0d0716';ctx.stroke();
