function update(dt){
  G.time+=dt;G.shake=Math.max(0,G.shake-dt*3);
  const L=LEVELS[G.level-1];
  updateSlimers(dt);updateDrops(dt); // Slimer mini-puzzle runs before AND after the flame drop
  if(!G.dropped||G.done){updateParts(dt);return;}
  // physics
  G.vy+=900*dt;
  // fans push
  for(const f of G.fans){
    const d=Math.hypot(G.fx-f.x,G.fy-f.y);
    if(d<130){
      const push=(1-d/130)*1600;
      const a=Math.atan2(G.fy-f.y,G.fx-f.x);
      G.vx+=Math.cos(a)*push*dt;G.vy+=Math.sin(a)*push*dt-300*dt;
    }
  }
  const prevFy=G.fy; // [gamer-check b10] pre-step centre: wall-top landing test below uses this so a fast flame can't tunnel past the top face in one step
  G.fx+=G.vx*dt;G.fy+=G.vy*dt;
  // [gamer-check b10] stuck detection: a flame resting on a flat wall/ramp never reached any terminal state = soft-lock.
  // Position-anchor based (not speed): a resting flame micro-bounces, which kept resetting a speed timer.
  if(G._ax===undefined||Math.hypot(G.fx-G._ax,G.fy-G._ay)>8){G._ax=G.fx;G._ay=G.fy;G._stillT=0;}
  else{G._stillT=(G._stillT||0)+dt;
    if(G._stillT>1.6&&!G.done){G.done=true;setTimeout(()=>{
      showOverlay('🔥 FLAME STUCK!',`<p>The flame came to rest! Score: ${G.score}</p>`,'🔥 Fire Safety: Try a different ramp!','↻ TRY AGAIN',()=>{initLevel(G.level);G.state='play';toolBar.classList.remove('hidden');});
    },300);}}
  const R=14;
  // user ramps (line collision)
  for(const r of G.ramps){
    // closest point on segment
    const dx=r.x2-r.x1,dy=r.y2-r.y1;
    const len2=dx*dx+dy*dy;
    let t=len2>0?((G.fx-r.x1)*dx+(G.fy-r.y1)*dy)/len2:0;
    t=Math.max(0,Math.min(1,t));
    const cx=r.x1+dx*t,cy=r.y1+dy*t;
    const d=Math.hypot(G.fx-cx,G.fy-cy);
    if(d<R+6){
      // bounce off line: reflect velocity
      const nx=d>0.001?(G.fx-cx)/d:0,ny=d>0.001?(G.fy-cy)/d:-1; // guard d=0 (centre exactly on line) — was NaN soft-lock
      G.fx=cx+nx*(R+6);G.fy=cy+ny*(R+6);
      const dot=G.vx*nx+G.vy*ny;
      if(dot<0){G.vx-=1.7*dot*nx;G.vy-=1.7*dot*ny;if(dot<-140)sfx.draw();} // impact sound only on real hits (was: every contact frame)
    }
  }
  // static walls
  for(const w of L.walls){
    const wx=w.x*W,wy=w.y*H,ww=w.w*W,wh=Math.max(8,w.h*H);
    if(G.fx+R>wx&&G.fx-R<wx+ww&&G.fy+R>wy&&G.fy-R<wy+wh){
      // bounce
      if(G.vy>0&&prevFy<=wy+2){G.fy=wy-R;G.vy*=-0.55;G.vx*=0.96;} // was G.fy<wy: a fast flame could cross the whole top face in one step and get side-ejected instead of landing
      else{G.vx*=-0.7;G.fx=G.fx<wx+ww/2?wx-R-1:wx+ww+R+1;} // positional push-out (was 4px/frame: frame-rate dependent)
      if(Math.abs(G.vy)>160)sfx.draw();
    }
  }
  // side walls
  if(G.fx<R){G.fx=R;G.vx=Math.abs(G.vx)*0.7;}
  if(G.fx>W-R){G.fx=W-R;G.vx=-Math.abs(G.vx)*0.7;}
  // water = death
  for(const wt of L.waters){
    if(Math.hypot(G.fx-wt.x*W,G.fy-wt.y*H)<wt.r*W+R){
      G.done=true;sfx.splash();G.shake=0.4;
