scripts:
'use strict';
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),olesson=document.getElementById('olesson');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();
let AC=null;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(window.__FB_MUTED)return;const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);o.start(t);o.stop(t+dur+0.05);}
const sfx={
  hop(){tone(500,700,0.08,'square',0.09);},
  star(){tone(900,1400,0.1,'sine',0.1);},
  crumble(){tone(250,120,0.2,'sawtooth',0.1);},
  fall(){tone(400,80,0.5,'sawtooth',0.14);},
  peak(){[523,659,784,1047].forEach((f,i)=>tone(f,f,0.2,'triangle',0.14,i*0.09));},
  click(){tone(600,600,0.06,'square',0.1);}
};
const PEAKS=9;
const G={state:'title',peak:1,score:0,best:0,
  plats:[],px:0,py:0,vx:0,vy:0,platIdx:0,
  camY:0,height:0,time:0,dead:false,flagY:0,won:false,grounded:false};
try{G.best=parseInt(localStorage.getItem('zenith_best')||'0',10)||0;}catch(e){}
function genPeak(n){
  G.plats=[];G.camY=0;G.height=0;G.dead=false;G.time=0;G.won=false;G.grounded=false;
  G.vx=0;G.vy=0;
  const gap=Math.max(120,170-n*12);
  let y=H*0.85;
  // start platform
  G.plats.push({x:W/2,y,w:110,type:'solid',t:0});
  let x=W/2;
  const total=14+n*3;
  for(let i=1;i<total;i++){
    x+=Math.max(-290,Math.min(290,(Math.random()-0.5)*W*0.5)); // [gamer-check b10] cap the sideways step to what one steered hop can actually cover (~350px): on wide screens the step scaled with W but hop physics didn't, leaving far platforms unreachable
    x=Math.max(70,Math.min(W-70,x));
    y-=gap*(0.85+Math.random()*0.2);
    const r=Math.random();
    const typeRamp=Math.min(1,Math.max(0,(n-1)/(PEAKS-1))); // gentle per-peak ramp: crumble + moving chances rise 12% -> 20% by peak 9; gap stays at its 120 floor
    const crumCh=0.12+0.08*typeRamp,moveCh=0.12+0.08*typeRamp;
    const type=r<crumCh?'crumble':r<crumCh+moveCh?'move':'solid';
    G.plats.push({x,y,w:type==='move'?100:80+Math.random()*50,type,t:Math.random()*6,phase:Math.random()*6,dir:Math.random()<0.5?-1:1});
    if(Math.random()<0.4){const so=(Math.random()-0.5)*60;G.plats[G.plats.length-1].star={x:x+so,y:y-50,t:Math.random()*6,off:so};}
  }
  G.flagY=y-80;
  G.platIdx=0;
  G.px=W/2;G.py=H*0.85-20;
  document.getElementById('level').textContent=`PEAK ${n}/${PEAKS}`;
  updateHUD();
}
function updateHUD(){
  document.getElementById('score').textContent='⛰️ '+Math.floor(G.height)+'m';
  document.getElementById('best').textContent='🏆 '+Math.floor(G.best)+'m';
}
function hop(dir){
  if(G.state!=='play'||G.dead||!G.grounded)return; // was: hoppable mid-air = infinite flight
  G.vx=dir*260; // gentler base impulse; HOLD steering (below) supplies the rest — a fixed full-power hop overshot near platforms and couldn't reach far ones
  G.vy=-815; // hop apex was 120px vs platform gaps of 134-182px: most hops were physically impossible (height stayed 0m in play-tests)
  G.grounded=false;
  sfx.hop();
}
canvas.addEventListener('pointerdown',e=>{
  if(G.state!=='play')return;
  const rect=canvas.getBoundingClientRect();
  const d=e.clientX-rect.left<W/2?-1:1;
  G._holdDir=d; // [gamer-check b10] holding steers mid-air (genre standard); a one-shot hop could not be corrected
  hop(d);
});
canvas.addEventListener('pointermove',e=>{
  if(!G._holdDir)return; // dragging across the midline while holding re-aims the steering
  const rect=canvas.getBoundingClientRect();
  G._holdDir=e.clientX-rect.left<W/2?-1:1;
});
addEventListener('pointerup',()=>{G._holdDir=0;});
addEventListener('pointercancel',()=>{G._holdDir=0;});
addEventListener('keydown',e=>{
  if(e.key==='ArrowLeft'||e.key==='a')G._keyDir=-1;
  if(e.key==='ArrowRight'||e.key==='d')G._keyDir=1;
});
addEventListener('keyup',e=>{
  if((e.key==='ArrowLeft'||e.key==='a')&&G._keyDir===-1)G._keyDir=0;
  if((e.key==='ArrowRight'||e.key==='d')&&G._keyDir===1)G._keyDir=0;
});
addEventListener('keydown',e=>{
  if(e.key==='ArrowLeft'||e.key==='a')hop(-1);
  if(e.key==='ArrowRight'||e.key==='d')hop(1);
});
const particles=[];
for(let i=0;i<80;i++)particles.push({a:false});
const embers=[];for(let i=0;i<24;i++)embers.push({x:Math.random()*1600,y:Math.random()*1200,s:1+Math.random()*2.2,v:14+Math.random()*30,ph:Math.random()*6.28});
function update(dt){
  G.time+=dt;
  // move platforms
  for(const p of G.plats){
    p.t+=dt;
    if(p.type==='move')p.x+=p.dir*90*dt;
    if(p.x<60||p.x>W-60)p.dir*=-1;
    if(p.star){p.star.t+=dt*3;if(p.type==='move'&&!p.star.taken)p.star.x=p.x+(p.star.off||0);} // star rides its moving platform (was left behind in mid-air)
  }
  // physics
  G.vy+=1700*dt;
  if(G.vy<-10)G.grounded=false;
  G.px+=G.vx*dt;G.py+=G.vy*dt;
  G.vx*=Math.pow(0.3,dt);
  const sd=G._holdDir||G._keyDir||0; // mid-air steering toward the held side
  if(sd&&!G.grounded){G.vx+=sd*1300*dt;G.vx=Math.max(-350,Math.min(350,G.vx));}
  // wrap x
  if(G.px<-20)G.px=W+20;
  if(G.px>W+20)G.px=-20;
  // land on platforms (falling only)
  if(G.vy>0){
    G.grounded=false;
    const prevPy=G.py-G.vy*dt; // [gamer-check b10] swept landing: the old 22px position window could be tunnelled through in one step at low frame rates / high fall speeds
    for(let i=0;i<G.plats.length;i++){
      const p=G.plats[i];
      const pw=p.w/2;
      if(G.px>p.x-pw&&G.px<p.x+pw&&prevPy<=p.y-2&&G.py>=p.y-6){
        const fell=G.vy;G.py=p.y-6;G.vy=0;G.grounded=true;
        if(fell>260)for(let j=0;j<4;j++){const pt=particles.find(q=>!q.a);if(!pt)break; // landing dust = impact feedback
          pt.a=true;pt.x=G.px+(Math.random()-0.5)*22;pt.y=p.y;pt.vx=(Math.random()-0.5)*120;pt.vy=-Math.random()*60;pt.life=0.3;pt.max=0.3;pt.color='#cbb59a';pt.size=3;}
        if(p.type==='crumble'&&!p.crumbling){
          p.crumbling=true;p.crT=0.65;sfx.crumble(); // 0.35s crumble was too harsh for kids; genre standard ~0.6s+
        }
        break;
      }
    }
  }
  // crumble
  for(let i=G.plats.length-1;i>=0;i--){
    const p=G.plats[i];
    if(p.crumbling){
      p.crT-=dt;
      if(p.crT<=0)G.plats.splice(i,1);
    }
  }
  // stars
  for(const p of G.plats){
    if(p.star&&!p.star.taken&&Math.hypot(G.px-p.star.x,G.py-p.star.y)<32){
      p.star.taken=true;sfx.star();G.score+=25;
      for(let j=0;j<6;j++){const pt=particles.find(pt=>!pt.a);if(!pt)break;
        pt.a=true;pt.x=p.star.x;pt.y=p.star.y;const a=Math.random()*Math.PI*2;
        pt.vx=Math.cos(a)*160;pt.vy=Math.sin(a)*160;
        pt.life=0.4;pt.max=0.4;pt.color='#ffd23f';pt.size=3;}
    }
  }
  // camera + height
  const screenY=G.py-G.camY;
  if(screenY<H*0.4){
    G.camY-=(H*0.4-screenY);
    const h=Math.floor(-G.camY/10);
    if(h>G.height){G.height=h;updateHUD();}
  }
  // peak reached
  if(G.py< G.flagY){
    peakDone();return;
  }
  // fell
  if(G.py-G.camY>H+80){
    G.dead=true;sfx.fall();
    const isBest=G.height>G.best;
    if(isBest){G.best=G.height;try{localStorage.setItem('zenith_best',String(Math.floor(G.best)));}catch(e){}}
    setTimeout(()=>{
      showOverlay('💥 YOU FELL!',
        `${isBest?'<p style="color:#ffd23f;font-weight:900">🏆 NEW BEST!</p>':''}<p style="font-size:26px;font-weight:900">${Math.floor(G.height)}m</p><p>Best: ${Math.floor(G.best)}m</p>`,
        '🔥 Fire Safety: Climb carefully!',
        '↻ CLIMB AGAIN',()=>{genPeak(G.peak);G.state='play';});
    },600);
    return;
  }
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)p.a=false;}
}
function peakDone(){
  if(G.won)return;G.won=true; // was: re-entered every frame for ~500ms (+150 pts & overlay each time)
  G.score+=150;updateHUD();sfx.peak();
  setTimeout(()=>{
    if(G.peak>=PEAKS){
      const isBest=G.height>G.best;
      if(isBest){G.best=G.height;try{localStorage.setItem('zenith_best',String(Math.floor(G.best)));}catch(e){}}
      showOverlay('🏆 ZENITH REACHED!',
        `<p style="font-size:24px;font-weight:900">Height: ${Math.floor(G.height)}m</p><p>Score: ${G.score}</p><p>All 9 peaks conquered!</p>`,
        '🔥 Fire Safety: You\'re a champion!',
        '↻ CLIMB AGAIN',()=>{G.score=0;G.peak=1;genPeak(1);G.state='play';});
    }else{
      showOverlay(`⛰️ PEAK ${G.peak} CONQUERED!`,
        `<p>+150 pts!</p><p>Height: ${Math.floor(G.height)}m</p><p>Score: ${G.score}</p>`,
        '🔥 Fire Safety: Keep climbing!',
        '▶ NEXT PEAK',()=>{G.peak++;genPeak(G.peak);G.state='play';});
    }
  },500);
}
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  document.getElementById('mathgate').classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){
    document.getElementById('mathgate').classList.add('hidden');showLevels();
  }else document.getElementById('ma').value='';
}
function showLevels(){
  otitle.innerHTML='⛰️ PICK PEAK';
  let h='';
  for(let i=1;i<=PEAKS;i++)h+=`<button class="lvlBtn" onclick="event.stopPropagation();pickLevel(${i})">${i}</button>`;
  obody.innerHTML=`<p>Hop to the flag at the top!</p><div id="lvlSel">${h}</div>`;
  obtn.style.display='none';
  overlay.classList.remove('hidden');
}
function pickLevel(n){sfx.click();audio();G.score=0;G.peak=n;G.height=0;genPeak(n);G.state='play';overlay.classList.add('hidden');}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;
  obtn.textContent=btn;obtn.style.display='';
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
obtn.onclick=()=>{showMathGate();};
function render(){
  const bg=ctx.createLinearGradient(0,0,0,H);
  // sky changes with altitude
  const alt=Math.min(1,-G.camY/4000);
  bg.addColorStop(0,alt>0.6?'#0d1a3a':'#1a0f24');
  bg.addColorStop(1,'#0d0a14');
  ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  ctx.save();ctx.globalCompositeOperation='lighter';
  for(const e of embers){const ey=H-((e.y+G.time*e.v)%(H+30));const ex=(e.x+Math.sin(G.time*0.7+e.ph)*14)%W;ctx.globalAlpha=0.3+0.2*Math.sin(G.time*2+e.ph);ctx.fillStyle='#ff9a2a';ctx.beginPath();ctx.arc(ex,ey,e.s,0,Math.PI*2);ctx.fill();}
  ctx.restore();ctx.globalAlpha=1;
  const offY=-G.camY;
  // volcano sides
  ctx.fillStyle='#1a0f0a';
  ctx.beginPath();ctx.moveTo(0,H);
  for(let y=0;y<H+100;y+=50){
    const t=(y-offY)/800;
    ctx.lineTo(Math.max(0,60-t*40),y);
  }
  ctx.lineTo(0,0);ctx.closePath();ctx.fill();
  ctx.beginPath();ctx.moveTo(W,H);
  for(let y=0;y<H+100;y+=50){
    const t=(y-offY)/800;
    ctx.lineTo(Math.min(W,W-60+t*40),y);
  }
  ctx.lineTo(W,0);ctx.closePath();ctx.fill();
  // stars in sky
  ctx.fillStyle='rgba(255,255,255,0.5)';
  for(let i=0;i<30;i++){
    const sy=((i*173)%2000+offY*0.3)%(H+100)-50;
    ctx.fillRect((i*271)%W,sy,2,2);
  }
  // platforms
  for(const p of G.plats){
    const sy=p.y+offY;
    if(sy<-60||sy>H+60)continue;
    const pw=p.w/2;
    let col1='#8a7052',col2='#4a3420'; // [gauntlet contrast] brightened (was #5a4a3a/#2a1e12 — dark brown on near-black)
    if(p.type==='crumble'){col1='#a8845e';col2='#5f4729';}
    if(p.type==='move'){col1='#5f87ad';col2='#37506e';}
    const alpha=p.crumbling?Math.max(0.2,p.crT/0.65):1;
    ctx.globalAlpha=alpha;
    const g=ctx.createLinearGradient(0,sy-12,0,sy+12);
    g.addColorStop(0,col1);g.addColorStop(1,col2);
    ctx.fillStyle=g;
    ctx.beginPath();ctx.roundRect(p.x-pw,sy-12,pw*2,24,8);ctx.fill();
    // [gauntlet contrast] lit top rim so the landing edge reads on a phone
    ctx.fillStyle=p.type==='move'?'rgba(170,225,255,0.9)':'rgba(255,222,160,0.85)';
    ctx.fillRect(p.x-pw+3,sy-12,pw*2-6,3);
    if(p.type==='crumble'){
      ctx.fillStyle='rgba(0,0,0,0.3)';
      for(let c=0;c<3;c++)ctx.fillRect(p.x-pw+10+c*24,sy-6,3,12);
    }
    ctx.globalAlpha=1;
    if(p.star&&!p.star.taken){
      const bob=Math.sin(p.star.t)*4;
      // [w5b] render-only clamp: a star above a near-top platform used to draw
      // half-clipped at the screen's top edge; collection uses world coords
      const starY=Math.max(14-(p.star.y+bob+offY),0);
      ctx.save();ctx.translate(p.star.x,p.star.y+bob+offY+starY);
      ctx.scale(Math.abs(Math.cos(p.star.t*0.5))*0.4+0.6,1);
      const sg=ctx.createRadialGradient(-4,-4,2,0,0,12);
      sg.addColorStop(0,'#fff');sg.addColorStop(0.5,'#ffd23f');sg.addColorStop(1,'#a37a00');
      ctx.fillStyle=sg;ctx.beginPath();ctx.arc(0,0,11,0,Math.PI*2);ctx.fill();
      ctx.restore();
    }
  }
  // flag
  const fsy=G.flagY+offY;
  if(fsy>-60&&fsy<H+60){
    ctx.strokeStyle='#fff';ctx.lineWidth=5;
    ctx.beginPath();ctx.moveTo(W/2,fsy);ctx.lineTo(W/2,fsy-70);ctx.stroke();
    const wave=Math.sin(G.time*6)*6;
    ctx.fillStyle='#4caf50';
    ctx.beginPath();ctx.moveTo(W/2,fsy-70);ctx.lineTo(W/2+44+wave,fsy-58);ctx.lineTo(W/2,fsy-46);ctx.closePath();ctx.fill();
  }
  // player
  if(!G.dead){
    const py=G.py+offY;
    if(py>-40&&py<H+40){
      ctx.save();ctx.translate(G.px,py);
      const squash=G.vy>0?1.08:0.95;
      ctx.scale(1/squash,squash);
      const g=ctx.createRadialGradient(-7,-7,3,0,0,19);
      g.addColorStop(0,'#ffe9a0');g.addColorStop(0.5,'#ff7a2a');g.addColorStop(1,'#d42a1a');
      ctx.fillStyle=g;ctx.shadowColor='rgba(255,122,42,0.95)';ctx.shadowBlur=20;ctx.beginPath();ctx.arc(0,-8,17,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
      ctx.fillStyle='#2b1a0e';
      ctx.beginPath();ctx.arc(-6,-12,3.2,0,Math.PI*2);ctx.arc(6,-12,3.2,0,Math.PI*2);ctx.fill();
      ctx.restore();
    }
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y+offY,p.size,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  if(G.state==='play'&&G.time<3){
    // [w5b] dark pill backdrop so the hint stays readable where a platform
    // crosses behind it (its left end used to tuck behind a platform)
    ctx.font='900 17px system-ui';ctx.textAlign='center';
    const hw=ctx.measureText('TAP LEFT / RIGHT TO HOP!').width;
    ctx.fillStyle='rgba(0,0,0,0.55)';
    ctx.beginPath();ctx.roundRect(W/2-hw/2-12,H*0.5-20,hw+24,28,9);ctx.fill();
    ctx.fillStyle='rgba(255,255,255,0.9)';
    ctx.fillText('TAP LEFT / RIGHT TO HOP!',W/2,H*0.5);
    ctx.textAlign='left';
  }
}
let lastT=0;
function loop(t){
  const dt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(G.state==='play'&&!G.dead)update(dt);else G.time+=dt;
  render();
  requestAnimationFrame(loop);
}
document.getElementById('best').textContent='🏆 '+Math.floor(G.best)+'m';

// [gamer-check b10] pause / mute / restart controls (were missing entirely)
window.__FB_MUTED=false;
let __prePause=null;
const __bp=document.getElementById('btnPause'),__bm=document.getElementById('btnMute'),__br=document.getElementById('btnRestart');
function __togglePause(){if(G.state==='play'){__prePause='play';G.state='pause';__bp.textContent='▶';document.getElementById('pauseLbl').classList.remove('hidden');}else if(G.state==='pause'){G.state=__prePause||'play';__prePause=null;__bp.textContent='⏸';document.getElementById('pauseLbl').classList.add('hidden');}}
__bp.addEventListener('click',()=>{__togglePause();});
__bm.addEventListener('click',()=>{window.__FB_MUTED=!window.__FB_MUTED;__bm.textContent=window.__FB_MUTED?'🔇':'🔊';});
__br.addEventListener('click',()=>{if(G.state==='title')return;overlay.classList.add('hidden');document.getElementById('pauseLbl').classList.add('hidden');__bp.textContent='⏸';__prePause=null;genPeak(G.peak);G.state='play';});
addEventListener('keydown',e=>{if(e.key==='p'||e.key==='P'||e.key==='Escape')__togglePause();if(e.key==='m'||e.key==='M')__bm.click();});
requestAnimationFrame(loop);
/* ===== MUSIC (Jeff 2026-10-15): 'Zenith' — Blaze's Zenith's own
   track. Synthesized Web Audio only. 127 BPM, A major: a triumphant square
   lead that climbs a bar higher every time, with double-time hats for the
   summit push.
   This shell has no noise() helper, so the drums are tone-only (the game-02
   Blaze Runner precedent).
   Freeze gate CONFIRMED at insertion (2026-10-15): window.__FB_MUTED mutes, pause sets G.state='pause', and music
   only plays while G.state==='play' — all read from this shell's own code.
   Starts on first interaction; 🔊 mute + pause freeze it. =====
   INSERT: paste at the end of game-54-blazes-zenith.html's main
   <script> block (same scope as audio()/tone()/noise()). No extra tags. */
const _mf=m=>440*Math.pow(2,(m-69)/12);
// Freeze gate (insertion-confirmed 2026-10-15): hard-wired to this shell's
// own confirmed globals — window.__FB_MUTED / G.state. try/catch kept so it can never throw.
const _mGate=()=>{try{return !!(window.__FB_MUTED||G.state!=='play');}catch(e){return false;}};
const MUS={on:false,step:0,nextT:0,BPM:127,
 BASS:[45,0,57,0,45,0,57,0, 40,0,52,0,40,0,52,0, 42,0,54,0,42,0,54,0, 38,0,50,0,38,0,45,0],
 LEAD:[69,0,73,0,76,0,0,0, 76,0,78,0,81,0,0,0, 81,0,85,0,88,0,85,0, 86,0,85,0,83,0,81,0],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(_mGate()){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);const bar=(s/8)|0;
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.13,'square',0.055,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.16,'square',0.05,d);
  if(s%8===0||s%8===4)tone(120,45,0.11,'sine',0.13,d); // kick
  if(s%8===2||s%8===6)tone(190,120,0.07,'triangle',0.07,d); // tone-only snare
  if(bar<2){if(s%2===0)tone(6800,6800,0.015,'square',0.008,d);} // hats
  else tone(6800,6800,0.015,'square',0.008,d); // double-time hats, bars 3-4
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

