 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.09,'sawtooth',0.055,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.09,'square',0.04,d);
  if(s%2===0)tone(124,45,0.1,'sine',0.14,d); // four-on-the-floor
  if(s%8===2||s%8===6)tone(190,120,0.07,'triangle',0.07,d); // tone-only snare
  tone(7000,7000,0.012,'square',0.006,d); // hat click
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

