scripts:
'use strict';
/* ============================================================
   SLINGSHOT CASCADE v2 — AAA Rebuild
   - Custom physics (no external deps)
   - Trauma-based screen shake, hit-stop, squash & stretch
   - Layered Web Audio, combo system, 5 levels, star ratings
   - Parental gate, zero PII/trackers, COPPA compliant
   ============================================================ */
const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
const overlay=document.getElementById('overlay'),otitle=document.getElementById('otitle'),
      obody=document.getElementById('obody'),obtn=document.getElementById('obtn'),
      olesson=document.getElementById('olesson'),mathgate=document.getElementById('mathgate'),
      comboEl=document.getElementById('combo');
let W,H,DPR;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;
  canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);}
addEventListener('resize',resize);resize();

/* [fbzoom 2026-10-15] Camera pulled back (Jeff: "too close zoomed in — back it
   up a bit"). The play layer renders at FB_ZOOM about the ground centre,
   widening the visible playfield by ~1/0.85 ≈ 18%. Physics, level layout and
   HUD stay in world coords; pointer input is converted through toWorld() so
   aiming, the trajectory preview and physics remain exactly consistent. */
const FB_ZOOM=0.85;
function toWorld(x,y){const px=W*0.5,py=groundY();return{x:px+(x-px)/FB_ZOOM,y:py+(y-py)/FB_ZOOM};}

/* ---------------- Audio: layered synth ---------------- */
let AC=null;
function audio(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
function tone(f0,f1,dur,type,vol,delay=0){if(window.__fbMuted)return;
  const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);
  o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);
  g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  o.start(t);o.stop(t+dur+0.05);
}
function noise(dur,vol,delay=0,lowpass=1000){if(window.__fbMuted)return;
  const ac=audio();if(!ac)return;const t=ac.currentTime+delay;
  const len=ac.sampleRate*dur,buf=ac.createBuffer(1,len,ac.sampleRate),d=buf.getChannelData(0);
  for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);
  const s=ac.createBufferSource();s.buffer=buf;
  const f=ac.createBiquadFilter();f.type='lowpass';f.frequency.value=lowpass;
  const g=ac.createGain();g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  s.connect(f);f.connect(g);g.connect(ac.destination);s.start(t);
}
const sfx={
  stretch(){tone(200,600,0.15,'sine',0.12);},
  launch(){noise(0.25,0.3,0,2000);tone(300,900,0.2,'sawtooth',0.15);},
  hit(){noise(0.12,0.35,0,800);tone(180,60,0.12,'square',0.2);},
  shatter(){noise(0.3,0.4,0,4000);tone(1200,300,0.25,'triangle',0.2);tone(1800,500,0.2,'sine',0.12,0.03);},
  combo(n){[523,659,784,1047,1319].slice(0,Math.min(n,5)).forEach((f,i)=>tone(f,f,0.15,'sine',0.15,i*0.06));},
  win(){[523,659,784,1047].forEach((f,i)=>tone(f,f,0.3,'triangle',0.2,i*0.12));},
  star(i){tone(880+i*220,880+i*220,0.2,'sine',0.2);tone(1320+i*220,1320+i*220,0.15,'sine',0.1,0.05);},
  click(){tone(600,600,0.06,'square',0.1);}
};

/* ---------------- Object pools ---------------- */
const particles=[],floaters=[],shards=[];
for(let i=0;i<300;i++)particles.push({a:false});
for(let i=0;i<30;i++)floaters.push({a:false});
for(let i=0;i<80;i++)shards.push({a:false});
function spawnP(x,y,vx,vy,life,color,size,grav=900){const p=particles.find(p=>!p.a);if(!p)return;
  p.a=true;p.x=x;p.y=y;p.vx=vx;p.vy=vy;p.life=life;p.max=life;p.color=color;p.size=size;p.grav=grav;}
function spawnShard(x,y,vx,vy,color){const s=shards.find(s=>!s.a);if(!s)return;
  s.a=true;s.x=x;s.y=y;s.vx=vx;s.vy=vy;s.rot=Math.random()*6;s.vr=(Math.random()-0.5)*12;s.life=1.2;s.color=color;s.size=4+Math.random()*8;}
function spawnText(x,y,txt,color='#ffd23f',size=22){const f=floaters.find(f=>!f.a);if(!f)return;
  f.a=true;f.x=x;f.y=y;f.txt=txt;f.color=color;f.size=size;f.life=1.1;}

/* ---------------- Trauma shake & hit-stop ---------------- */
let trauma=0,hitStop=0,shakeX=0,shakeY=0;
function addTrauma(t){trauma=Math.min(1,trauma+t);}
function addHitStop(t){hitStop=Math.max(hitStop,t);}

/* ---------------- Game state ---------------- */
const G={state:'title',level:1,score:0,shots:0,shotsUsed:0,combo:0,comboT:0,best:0,time:0,
  blocks:[],pig:null,sling:null,dragging:false,projectiles:[],stars:0,hero:'blaze',
  skels:[],skelsSmashed:0,skelBonusPaid:false,
  /* [slimer 2026-10-18] Jeff: oil-based villain. New enemy type, not a reskin.
     WATER IS THE TRAP: Aqua splash/direct water contact makes him GROW (x1.15/hit, cap 1.6).
     Blaze/Sparky/Ruko only wobble him. SMOTHER = structure debris falling onto him:
     2 solid cover hits, or 1 cover hit + ~1s pinned, defeats him (score = a skeleton). */
  slimers:[]};

/* ---------------- Heroes & specials (Jeff's spec) ---------------- */
const HEROES={
  blaze:{name:'Blaze',emoji:'🔥',sIcon:'💥',sName:'Explosion',trail:'#ff8a2a'},
  aqua:{name:'Aqua',emoji:'💧',sIcon:'💦',sName:'Splash Damage',trail:'#5ab8e8'},
  sparky:{name:'Sparky',emoji:'⚡',sIcon:'🧲',sName:'Magnetic',trail:'#ffd23f'},
  ruko:{name:'Ruko',emoji:'🌀',sIcon:'🌪',sName:'Tornado',trail:'#ff7043'}
};
function heroChipsHTML(){return Object.keys(HEROES).map(k=>{const h=HEROES[k];
  return `<button class="heroChip${G.hero===k?' sel':''}" data-hero="${k}" onclick="event.stopPropagation();selHero('${k}')">${h.emoji} ${h.name}<small>${h.sIcon} ${h.sName}</small></button>`;}).join('');}
function refreshHeroChips(){document.querySelectorAll('.heroPickSlot').forEach(el=>{el.innerHTML=heroChipsHTML();});}
function selHero(k){if(!HEROES[k])return;G.hero=k;try{sfx.click();}catch(e){}refreshHeroChips();}
try{G.best=parseInt(localStorage.getItem('sling_best')||'0',10)||0;}catch(e){}
const GRAV=1600;
const groundY=()=>H-(H<500?104:70);

/* ---------------- Level definitions ---------------- */
function buildLevel(n){
  G.blocks=[];G.projectiles=[];
  const gy=groundY();
  const B=(x,y,w,h,type,hp)=>G.blocks.push({x,y,w,h,type,hp,maxHp:hp,vx:0,vy:0,rot:0,vr:0,dead:false,settled:true});
  if(n===1){
    B(W*0.62,gy-40,26,80,'crystal',1);B(W*0.72,gy-40,26,80,'crystal',1);
    B(W*0.62,gy-100,140,24,'rock',2);
    B(W*0.67,gy-140,26,60,'crystal',1);
    G.shots=3;
  }else if(n===2){
    B(W*0.58,gy-35,26,70,'rock',2);B(W*0.70,gy-35,26,70,'rock',2);B(W*0.82,gy-35,26,70,'rock',2);
    B(W*0.58,gy-85,200,22,'crystal',1);
    B(W*0.63,gy-125,26,60,'crystal',1);B(W*0.75,gy-125,26,60,'crystal',1);
    B(W*0.63,gy-165,120,20,'rock',2);
    G.shots=4;
  }else if(n===3){
    // pyramid
    for(let r=0;r<4;r++)for(let i=0;i<4-r;i++)
      B(W*0.60+i*34+r*17,gy-25-r*48,30,44,r%2?'crystal':'rock',r%2?1:2);
    G.shots=4;
  }else if(n===4){
    // twin towers
    [0.55,0.78].forEach(bx=>{
      B(W*bx,gy-50,30,100,'rock',2);B(W*bx+44,gy-50,30,100,'rock',2);
      B(W*bx,gy-115,104,22,'crystal',1);
      B(W*bx+22,gy-155,30,60,'crystal',1);
    });
    B(W*0.665,gy-30,40,60,'crystal',1);
    G.shots=5;
  }else if(n===6){
    // Wide Tower — single broad tower, rock hp2 + crystal mix
    B(W*0.60,gy-50,32,100,'rock',2);B(W*0.67,gy-50,32,100,'crystal',1);B(W*0.74,gy-50,32,100,'rock',2);
    B(W*0.67,gy-112,230,24,'crystal',1);
    B(W*0.635,gy-155,30,62,'rock',2);B(W*0.705,gy-155,30,62,'crystal',1);
    B(W*0.67,gy-198,180,24,'rock',2);
    B(W*0.67,gy-235,30,50,'crystal',1);
    G.shots=4;
  }else if(n===7){
    // Twin Huts — two short towers + center crystal
    [0.56,0.76].forEach(bx=>{
      B(W*bx,gy-40,30,80,'rock',2);B(W*bx+46,gy-40,30,80,'crystal',1);
      B(W*bx+23,gy-92,106,22,'rock',2);
      B(W*bx+23,gy-128,30,50,'crystal',1);
    });
    B(W*0.685,gy-30,40,60,'crystal',1);
    G.shots=5;
  }else if(n===8){
    // Big Pyramid — the L3 pyramid loop pattern at 5 rows
    for(let r=0;r<5;r++)for(let i=0;i<5-r;i++)
      B(W*0.58+i*34+r*17,gy-25-r*48,30,44,r%2?'crystal':'rock',r%2?1:2);
    G.shots=5;
  }else if(n===9){
    // Twin Towers II — L4 twin towers with hp3 rock bases only (uppers stay hp1-2)
    [0.55,0.78].forEach(bx=>{
      B(W*bx,gy-50,30,100,'rock',3);B(W*bx+44,gy-50,30,100,'rock',3);
      B(W*bx,gy-115,104,22,'crystal',1);
      B(W*bx+22,gy-155,30,60,'crystal',1);
    });
    B(W*0.665,gy-30,40,60,'crystal',1);
    G.shots=6;
  }else if(n===10){
    // Fortress Remix — L5 fortress layout, crystals swapped onto the beams
    for(let i=0;i<5;i++)B(W*0.55+i*52,gy-60,34,120,'rock',3);
    B(W*0.55,gy-135,290,24,'crystal',1);
    for(let i=0;i<3;i++)B(W*0.60+i*80,gy-175,30,60,'rock',2);
    B(W*0.60,gy-215,240,22,'crystal',1);
    B(W*0.70,gy-255,30,60,'rock',2);
    G.shots=6;
  }else{
    // fortress
    for(let i=0;i<5;i++)B(W*0.55+i*52,gy-60,34,120,'rock',3);
    B(W*0.55,gy-135,290,24,'crystal',1);
    for(let i=0;i<3;i++)B(W*0.60+i*80,gy-175,30,60,'crystal',1);
    B(W*0.60,gy-215,240,22,'rock',2);
    B(W*0.70,gy-255,30,60,'crystal',1);
    G.shots=6;
  }
  /* ===== Jeff 2026-10-13: SKELETON bad guys perched on the towers (Angry-Birds style).
     SK(x, surfaceTopY): skeleton stands ON that surface; center y = top - 20. ===== */
  G.skels=[];G.skelsSmashed=0;G.skelBonusPaid=false;
  const SK=(x,top)=>G.skels.push({x,y:top-20,vx:0,vy:0,falling:false,dead:false,ph:Math.random()*6});
  if(n===1){
    SK(W*0.645,gy-112);SK(W*0.67,gy-170);SK(W*0.56,gy);
  }else if(n===2){
    SK(W*0.55,gy-96);SK(W*0.64,gy-96);SK(W*0.66,gy-175);SK(W*0.90,gy);
  }else if(n===3){
    SK(W*0.60+51,gy-191);SK(W*0.60+68,gy-143);SK(W*0.60+102,gy-47);SK(W*0.85,gy);
  }else if(n===4){
    SK(W*0.55+22,gy-126);SK(W*0.78+22,gy-126);SK(W*0.78+22,gy-185);SK(W*0.665,gy-60);
  }else if(n===6){
    SK(W*0.67,gy-124);SK(W*0.67,gy-210);SK(W*0.67,gy-260);SK(W*0.85,gy);
  }else if(n===7){
    SK(W*0.56+23,gy-103);SK(W*0.76+23,gy-103);SK(W*0.76+23,gy-153);SK(W*0.685,gy-60);
  }else if(n===8){
    SK(W*0.58+68,gy-239);SK(W*0.58+102,gy-143);SK(W*0.58+136,gy-47);SK(W*0.88,gy);
  }else if(n===9){
    SK(W*0.55+22,gy-126);SK(W*0.78+22,gy-126);SK(W*0.78+22,gy-185);SK(W*0.665,gy-60);SK(W*0.90,gy);
  }else if(n===10){
    SK(W*0.62,gy-147);SK(W*0.80,gy-147);SK(W*0.68,gy-226);SK(W*0.70,gy-285);
  }else{ // level 5 fortress
    SK(W*0.62,gy-147);SK(W*0.78,gy-147);SK(W*0.70,gy-226);SK(W*0.70,gy-285);
  }
  /* [slimer 2026-10-18] One Slimer beside the tower on the ground in levels 1-4
     (level 1 = gentle practice). x spots sit clear of the tower footprint, the
     ground skeletons and the centered hero-card bar (ground reserve via groundY()). */
  G.slimers=[];
  const SL=(x)=>G.slimers.push({x:x,gy:gy,scale:1,wobbleT:0,panicT:0,coverHits:0,coverNow:[],coverCounted:[],pinnedT:0,dead:false,gone:false,defeatT:0,hitCd:0,ph:Math.random()*6,slideDir:1});
  if(n===1)SL(W*0.80);
  else if(n===2)SL(W*0.50);
  else if(n===3)SL(W*0.78);
  else if(n===4)SL(W*0.92);
  updateEnemyHUD();
  G.sling={x:Math.max(90,W*0.14),y:gy-110};
  G.shotsUsed=0;G.combo=0;
  document.getElementById('level').textContent='LEVEL '+n+'/10';
  document.getElementById('shots').textContent='🎯 '+G.shots;
  document.getElementById('best').textContent='🏆 '+G.best;
}
function updateScoreUI(){document.getElementById('score').textContent='⭐ '+G.score;}

/* ---------------- Physics ---------------- */
function rectHit(ax,ay,aw,ah,bx,by,bw,bh){return ax<bx+bw&&ax+aw>bx&&ay<by+bh&&ay+ah>by;}
/* ---------------- Hero specials: armed in flight, once per launch ---------------- */
function trySpecial(){
  if(G.state!=='play')return false;
  const pr=G.projectiles.find(p=>p.live&&!p.specialUsed&&p.y<groundY()-20);
  if(!pr)return false;
  pr.pendingSpecial=true; // executed inside updatePhysics()'s projectile loop
  return true;
}
function heroFx(pr,n,color){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,sp=80+Math.random()*320;
  spawnP(pr.x,pr.y,Math.cos(a)*sp,Math.sin(a)*sp,0.6,color,5);}}
function executeSpecial(pr){
  if(pr.specialUsed)return;pr.specialUsed=true;
  const hero=pr.hero||'blaze';
  if(hero==='blaze'){
    // EXPLOSION: instant blast, 2 damage + radial knockback; hero's flight ENDS
    addTrauma(0.9);addHitStop(0.08);sfx.shatter();sfx.hit();
    heroFx(pr,26,'#ffb347');heroFx(pr,14,'#ff6a1a');
    spawnText(pr.x,pr.y-44,'💥 BOOM!','#ffd23f',28);
    for(const b of G.blocks){
      if(b.dead)continue;
      const dx=b.x-pr.x,dy=b.y-pr.y,d=Math.hypot(dx,dy);
      if(d<=130){
        b.hp-=2;b.settled=false;b.hitT=0.12;
        const nx=d?dx/d:0,ny=d?dy/d:-1;
        b.vx+=nx*380;b.vy+=ny*380-80;b.vr+=(Math.random()-0.5)*6;
        for(let i=0;i<5;i++)spawnP(b.x,b.y,(Math.random()-0.5)*300,(Math.random()-0.5)*300,0.5,b.type==='crystal'?'#7fd4ff':'#a08a6a',4);
        if(b.hp<=0)destroyBlock(b,pr);
      }
    }
    for(const s of G.skels){if(!s.dead&&Math.hypot(s.x-pr.x,s.y-pr.y)<=130)skelDie(s,'boom');}
    for(const sl of (G.slimers||[])){if(!sl.dead&&Math.hypot(sl.x-pr.x,slimerCY(sl)-pr.y)<=130)slimerWobble(sl,'blaze');} // [slimer] fire feeds oil — no damage
    pr.live=false;
  }else if(hero==='aqua'){
    // SPLASH DAMAGE: burst, 1 damage + small knockback; hero KEEPS flying
    addTrauma(0.35);sfx.shatter();
    heroFx(pr,20,'#7fd4ff');heroFx(pr,8,'#aee8ff');
    spawnText(pr.x,pr.y-44,'💦 SPLASH!','#aee8ff',24);
    for(const b of G.blocks){
      if(b.dead)continue;
      const dx=b.x-pr.x,dy=b.y-pr.y,d=Math.hypot(dx,dy);
      if(d<=100){
        b.hp-=1;b.settled=false;b.hitT=0.12;
        const nx=d?dx/d:0,ny=d?dy/d:-1;
        b.vx+=nx*170;b.vy+=ny*170-50;
        for(let i=0;i<4;i++)spawnP(b.x,b.y,(Math.random()-0.5)*200,(Math.random()-0.5)*200,0.4,'#7fd4ff',4);
        if(b.hp<=0)destroyBlock(b,pr);
      }
    }
    for(const s of G.skels){if(!s.dead&&Math.hypot(s.x-pr.x,s.y-pr.y)<=100)skelDie(s,'splash');}
    for(const sl of (G.slimers||[])){if(!sl.dead&&sl.hitCd<=0&&Math.hypot(sl.x-pr.x,slimerCY(sl)-pr.y)<=100)slimerGrow(sl);} // [slimer] WATER IS THE TRAP — splash makes him GROW, never damages
  }else if(hero==='sparky'){
    // MAGNETIC: 0.45s pull toward the hero (applied per-frame in applyMagnet)
    pr.magnetT=0.45;addTrauma(0.2);sfx.stretch();
    heroFx(pr,14,'#ffd23f');
    spawnText(pr.x,pr.y-44,'🧲 MAGNET!','#ffd23f',24);
    for(const sl of (G.slimers||[])){if(!sl.dead&&Math.hypot(sl.x-pr.x,slimerCY(sl)-pr.y)<=170)slimerWobble(sl,'sparky');} // [slimer] wobble only — magnet can't hurt oil
  }else if(hero==='ruko'){
    // TORNADO: instant whirlwind, upward + sideways scatter with spin; hero KEEPS flying
    addTrauma(0.5);addHitStop(0.03);sfx.launch();
    heroFx(pr,22,'#ffccbc');heroFx(pr,10,'#ff7043');
    spawnText(pr.x,pr.y-44,'🌪 TORNADO!','#ffccbc',24);
    for(const b of G.blocks){
      if(b.dead)continue;
      const dx=b.x-pr.x,dy=b.y-pr.y,d=Math.hypot(dx,dy);
      if(d<=140){
        b.settled=false;b.hitT=0.12;
        const nx=d?-dy/d:1,ny=d?dx/d:0; // tangential swirl
        b.vx+=nx*380+(Math.random()-0.5)*220;
        b.vy+=-320-Math.random()*220;
        b.vr+=(Math.random()-0.5)*16;
      }
    }
    for(const s of G.skels){
      if(s.dead)continue;
      if(Math.hypot(s.x-pr.x,s.y-pr.y)<=140){s.falling=true;s.vy=-520-Math.random()*220;s.vx=(Math.random()-0.5)*320;}
    }
    for(const sl of (G.slimers||[])){if(!sl.dead&&Math.hypot(sl.x-pr.x,slimerCY(sl)-pr.y)<=140)slimerWobble(sl,'ruko');} // [slimer] tornado wobbles him only — he is NOT thrown, NOT damaged
  }
}
function applyMagnet(pr,dt){
  // per-frame pull next to projectile physics; settled=false required or blocks never integrate
  spawnP(pr.x+(Math.random()-0.5)*30,pr.y+(Math.random()-0.5)*30,(Math.random()-0.5)*60,(Math.random()-0.5)*60,0.25,'#ffd23f',3);
  for(const b of G.blocks){
    if(b.dead)continue;
    const dx=pr.x-b.x,dy=pr.y-b.y,d=Math.hypot(dx,dy);
    if(d<=170&&d>1){
      b.settled=false;b.hitT=0.05;
      b.vx+=dx/d*1500*dt;b.vy+=dy/d*1500*dt;
    }
  }
}
/* ---------------- Skeletons: crush / fall physics ---------------- */
function skelDie(s,cause){
  if(s.dead)return;s.dead=true;G.skelsSmashed++;
  G.score+=500;updateScoreUI();
  document.getElementById('skels').textContent='💀 Skeletons: '+(G.skels.length-G.skelsSmashed)+' left';
  updateEnemyHUD();
  sfx.shatter();addTrauma(0.25);
  spawnText(s.x,s.y-34,'💀 SKELETON SMASHED +500','#e8e8f0',20);
  for(let i=0;i<10;i++)spawnP(s.x,s.y,(Math.random()-0.5)*360,(Math.random()-0.5)*360,0.6,'#e8e8f0',4);
  for(let i=0;i<4;i++)spawnShard(s.x,s.y,(Math.random()-0.5)*300,-Math.random()*300,'#cfcfdd');
  if(!G.skelBonusPaid&&G.skels.length>0&&G.skelsSmashed>=G.skels.length){
    G.skelBonusPaid=true;G.score+=500;updateScoreUI();
    spawnText(W/2,H*0.35,'💀 ALL SKELETONS SMASHED! +500','#ffd23f',26);
  }
}
/* ---------------- Slimer (oil villain, 2026-10-18) ----------------
   Brand law: a Slimer NEVER harms a Fire Baby; his defeats are slapstick —
   covered, shrunk, then he slides away on his own slick, giggling muffled. */
function updateEnemyHUD(){
  const el=document.getElementById('skels');if(!el)return;
  const sk=G.skels.length-G.skelsSmashed;
  let t='💀 Skeletons: '+sk+' left';
  const alive=(G.slimers||[]).filter(s=>!s.dead).length;
  if((G.slimers||[]).length)t+=' • 🫧 Slimer: '+(alive?alive+' loose':'smothered!');
  el.textContent=t;
}
function slimerR(sl){return 24*sl.scale;}
function slimerCY(sl){return sl.gy-slimerR(sl)*0.92;} // centre y; puddle sits on sl.gy (ground)
function slimerSplashFx(sl,n){
  for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,sp=60+Math.random()*260;
    spawnP(sl.x,slimerCY(sl),Math.cos(a)*sp,Math.sin(a)*sp-60,0.55,'hsl('+((G.time*60+i*36)%360)+',90%,62%)',5);}
}
function slimerGrow(sl){
  if(sl.dead)return;
  sl.scale=Math.min(1.6,sl.scale*1.15); // spec: ~15% per water hit, cap ~1.6x
  sl.wobbleT=0.9;sl.hitCd=0.6;
  slimerSplashFx(sl,16);
  spawnText(sl.x,slimerCY(sl)-slimerR(sl)-18,'💦 HE GROWS!','#aee8ff',22);
  try{tone(280,720,0.18,'sine',0.12);tone(420,900,0.16,'sine',0.08,0.07);}catch(e){}
}
function slimerWobble(sl,kind){
  if(sl.dead)return;
  sl.wobbleT=Math.max(sl.wobbleT,0.7);sl.hitCd=Math.max(sl.hitCd,0.35);
  if(kind==='blaze'){ // fire feeds oil: smug flare, NO damage
    for(let i=0;i<10;i++)spawnP(sl.x,slimerCY(sl),(Math.random()-0.5)*220,-Math.random()*220,0.4,'#ff8a2a',4);
    spawnText(sl.x,slimerCY(sl)-slimerR(sl)-18,'🔥 FEEDS HIM!','#ffb347',20);
    try{tone(180,420,0.15,'sawtooth',0.08);}catch(e){}
  }
}
function slimerDefeat(sl){
  if(sl.dead)return;sl.dead=true;sl.defeatT=0;sl.slideDir=sl.x<W*0.3?-1:1;
  G.score+=500;updateScoreUI();updateEnemyHUD(); // same score as a skeleton
  sfx.shatter();addTrauma(0.3);
  spawnText(sl.x,slimerCY(sl)-30,'🫧 SMOTHERED! +500','#c9a7ff',22);
  slimerSplashFx(sl,14);
  try{tone(700,140,0.35,'sine',0.14);noise(0.25,0.15,0,700);}catch(e){} // muffled giggle-slide
}
function updateSlimers(dt){
  for(const sl of (G.slimers||[])){
    sl.wobbleT=Math.max(0,sl.wobbleT-dt);sl.panicT=Math.max(0,sl.panicT-dt);sl.hitCd=Math.max(0,sl.hitCd-dt);
    if(sl.dead){ // slapstick defeat: flatten under debris, then slide off on his slick and despawn
      sl.defeatT+=dt;
      if(sl.defeatT>0.9&&!sl.gone)sl.x+=sl.slideDir*150*dt;
      if(sl.defeatT>2.0)sl.gone=true;
      continue;
    }
    /* SMOTHER: a solid block whose bottom edge rests/lands ON TOP of him
       (bottom above his centre, clear horizontal overlap). A block merely
       standing on the ground beside him never counts (its bottom = ground). */
    const r=slimerR(sl),cy=slimerCY(sl),top=cy-r;
    const now=[];
    for(const b of G.blocks){
      if(b.dead)continue;
      const bb=b.y+b.h/2;
      if(Math.abs(b.x-sl.x)<b.w/2+r*0.7&&bb>top-16&&bb<cy+8&&b.y<cy)now.push(b);
    }
    for(const b of now){
      if(!sl.coverCounted.includes(b)){ // each DISTINCT solid piece counts once, even if it bounces
        sl.coverCounted.push(b);
        sl.coverHits++;sl.panicT=1.0;sl.wobbleT=0.4;
        sl.scale=Math.max(0.55,sl.scale-0.25); // covered -> he shrinks
        slimerSplashFx(sl,8);
        spawnText(sl.x,top-16,'COVERED!','#e8d8ff',18);
        try{sfx.hit();}catch(e){}
      }
    }
    sl.coverNow=now;
    if(now.length) { sl.pinnedT+=dt; sl.panicT=Math.max(sl.panicT,0.25); } else sl.pinnedT=0;
    if(sl.coverHits>=2||(sl.coverHits>=1&&sl.pinnedT>=1.0))slimerDefeat(sl);
  }
}
function updateSkels(dt){
  const gy=groundY();
  for(const s of G.skels){
    if(s.dead)continue;
    const bot=s.y+20;
    // crush: any NON-settled (moving/falling) block overlapping the body box
    let crushed=false;
    for(const b of G.blocks){
      if(b.dead||b.settled)continue;
      if(rectHit(s.x-13,s.y-18,26,34,b.x-b.w/2,b.y-b.h/2,b.w,b.h)&&Math.hypot(b.vx,b.vy)>40){crushed=true;break;}
    }
    if(crushed){skelDie(s,'crush');continue;}
    // support: ground, or a live block whose top is at/just below the feet
    let sup=gy;
    for(const b of G.blocks){
      if(b.dead)continue;const top=b.y-b.h/2;
      if(Math.abs(s.x-b.x)<b.w/2+13&&top>=bot-16&&top<sup)sup=top;
    }
    if(!s.falling&&sup-bot>16){s.falling=true;s.vy=0;}
    if(s.falling){
      const prevBot=s.y+20;
      s.vy+=GRAV*dt;s.x+=s.vx*dt;s.y+=s.vy*dt;s.vx*=0.99;
      let land=gy;
      for(const b of G.blocks){
        if(b.dead)continue;const top=b.y-b.h/2;
        if(Math.abs(s.x-b.x)<b.w/2+13&&top>=prevBot-4&&top<land)land=top;
      }
      if(s.y+20>=land){s.y=land-20;
        if(s.vy>560){skelDie(s,'fall');continue;}
        s.vy=0;s.vx=0;s.falling=false;}
      if(s.y>H+60){skelDie(s,'fall');continue;}
    }
  }
}
function updatePhysics(dt){
  // projectiles
  for(const pr of G.projectiles){
    if(!pr.live)continue;
    if(pr.pendingSpecial){pr.pendingSpecial=false;executeSpecial(pr);if(!pr.live)continue;}
    if(pr.magnetT>0){pr.magnetT-=dt;applyMagnet(pr,dt);}
    pr.vy+=GRAV*dt;
    pr.x+=pr.vx*dt;pr.y+=pr.vy*dt;pr.rot+=pr.vr*dt;
    // squash on fast movement
    pr.squash=Math.min(0.3,Math.hypot(pr.vx,pr.vy)/4000);
    // ground bounce
    if(pr.y>groundY()-16){
      pr.y=groundY()-16;
      if(Math.abs(pr.vy)>250){pr.vy*=-0.4;pr.vx*=0.7;sfx.hit();addTrauma(0.15);
        for(let i=0;i<6;i++)spawnP(pr.x,groundY(),(Math.random()-0.5)*200,-Math.random()*150,0.4,'#8a6a4a',3);}
      else{pr.vy=0;pr.vx*=0.92;}
      if(Math.abs(pr.vx)<20&&Math.abs(pr.vy)<20)pr.restT=(pr.restT||0)+dt;
    }
    // block collisions
    for(const b of G.blocks){
      if(b.dead)continue;
      if(rectHit(pr.x-18,pr.y-18,36,36,b.x-b.w/2,b.y-b.h/2,b.w,b.h)){
        const impact=Math.hypot(pr.vx,pr.vy);
        if(impact>180){
          b.hp-=impact>700?2:1;b.vx+=pr.vx*0.12;b.vy+=pr.vy*0.12-60;b.settled=false;
          b.hitT=0.12;
          pr.vx*=-0.25;pr.vy*=-0.25;
          sfx.hit();addTrauma(Math.min(0.4,impact/2500));addHitStop(0.03);
          for(let i=0;i<8;i++)spawnP(b.x,b.y,(Math.random()-0.5)*300,(Math.random()-0.5)*300,0.5,b.type==='crystal'?'#7fd4ff':'#a08a6a',4);
          if(b.hp<=0)destroyBlock(b,pr);
          else{G.combo++;G.comboT=1.2;showCombo();}
        }
      }
    }
    // out of bounds / rest
    if(pr.x>W+100||pr.x<-100||pr.y>H+100||(pr.restT||0)>1.2)pr.live=false;
  }
  G.projectiles=G.projectiles.filter(p=>p.live);
  // blocks physics (knocked)
  for(const b of G.blocks){
    if(b.dead)continue;
    b.hitT=Math.max(0,(b.hitT||0)-dt);
    if(!b.settled){
      b.vy+=GRAV*dt;b.x+=b.vx*dt;b.y+=b.vy*dt;b.rot+=b.vr*dt;
      b.vx*=0.99;b.vr*=0.98;
      if(b.y>groundY()-b.h/2){b.y=groundY()-b.h/2;
        if(Math.abs(b.vy)>120){sfx.hit();for(let i=0;i<4;i++)spawnP(b.x,groundY(),(Math.random()-0.5)*150,-Math.random()*100,0.3,'#8a6a4a',3);}
        b.vy*=-0.3;b.vx*=0.8;b.vr*=0.7;
        if(Math.abs(b.vy)<40&&Math.abs(b.vx)<30){b.settled=true;b.vx=0;b.vy=0;b.vr=0;}
      }
      // block-block collision (simple)
      for(const o of G.blocks){
        if(o===b||o.dead)continue;
        if(rectHit(b.x-b.w/2,b.y-b.h/2,b.w,b.h,o.x-o.w/2,o.y-o.h/2,o.w,o.h)){
          if(!o.settled||Math.hypot(b.vx,b.vy)>150){
            o.hp-=1;o.settled=false;o.vx+=b.vx*0.3;o.vy-=40;o.hitT=0.12;
            if(o.hp<=0)destroyBlock(o,b);
            else{sfx.hit();for(let i=0;i<5;i++)spawnP(o.x,o.y,(Math.random()-0.5)*200,(Math.random()-0.5)*200,0.4,'#a08a6a',3);}
          }
        }
      }
    }
  }
  // skeleton proximity: hero projectile direct hit crushes
  for(const s of G.skels){
    if(s.dead)continue;
    for(const pr of G.projectiles){
      if(!pr.live)continue;
      if(rectHit(pr.x-18,pr.y-18,36,36,s.x-15,s.y-20,30,40)&&Math.hypot(pr.vx,pr.vy)>120){
        skelDie(s,'hit');pr.vx*=0.55;pr.vy*=0.55;break;
      }
    }
  }
  // [slimer 2026-10-18] hero projectile DIRECT contact: Aqua (water) makes him GROW;
  // Blaze flares him smugly; Sparky/Ruko just wobble him. None of them damage him.
  for(const sl of (G.slimers||[])){
    if(sl.dead)continue;
    for(const pr of G.projectiles){
      if(!pr.live)continue;
      if(Math.hypot(pr.x-sl.x,pr.y-slimerCY(sl))<19+slimerR(sl)*0.85&&Math.hypot(pr.vx,pr.vy)>80){
        if(sl.hitCd<=0){ if((pr.hero||'blaze')==='aqua')slimerGrow(sl); else slimerWobble(sl,pr.hero||'blaze'); }
        pr.vx*=0.55;pr.vy*=0.55;break;
      }
    }
  }
  updateSkels(dt);
  updateSlimers(dt);
  // check win — Jeff 2026-10-15: the MISSION is the skeletons, not the bricks.
  // Bricks are only what the skeletons stand on: the level is won the moment the
  // LAST skeleton is smashed, even with towers still standing.
  if(G.state==='play'&&G.skels.length>0&&G.skels.every(s=>s.dead)&&(G.slimers||[]).every(s=>s.dead))levelComplete();
  // check out of shots
  if(G.state==='play'&&G.projectiles.length===0&&!G.dragging&&G.shots-G.shotsUsed<=0&&G.pig===null){
    // small delay before fail
    G.failT=(G.failT||0)+dt;
    if(G.failT>1.5&&!(G.skels.every(s=>s.dead)&&(G.slimers||[]).every(s=>s.dead)))levelFailed();
  }else G.failT=0;
}
function destroyBlock(b,by){
  b.dead=true;
  const pts=(b.type==='crystal'?150:100)*(1+G.combo*0.25);
  G.score+=Math.round(pts);updateScoreUI();
  G.combo++;G.comboT=1.5;showCombo();
  sfx.shatter();addTrauma(0.3);
  spawnText(b.x,b.y-20,'+'+Math.round(pts));
  for(let i=0;i<6;i++)spawnShard(b.x+(Math.random()-0.5)*b.w,b.y+(Math.random()-0.5)*b.h,(Math.random()-0.5)*400,-Math.random()*400,b.type==='crystal'?'#7fd4ff':'#8a6a5a');
  for(let i=0;i<10;i++)spawnP(b.x,b.y,(Math.random()-0.5)*400,(Math.random()-0.5)*400,0.6,b.type==='crystal'?'#aee8ff':'#c8a87a',5);
}
function showCombo(){
  if(G.combo>=2){
    comboEl.textContent='🔥 COMBO x'+G.combo+'!';
    comboEl.classList.remove('pop');void comboEl.offsetWidth;comboEl.classList.add('pop');
    sfx.combo(G.combo);
    setTimeout(()=>comboEl.classList.remove('pop'),400);
  }
}

/* ---------------- Input: drag slingshot ---------------- */
let dragX=0,dragY=0;
function getPos(e){const t=e.touches?e.touches[0]:e;return toWorld(t.clientX,t.clientY);} // screen→world so drag/aim match the zoomed camera
function slingReady(){return G.state==='play'&&!G.dragging&&G.projectiles.length===0&&(G.shots-G.shotsUsed)>0;}
canvas.addEventListener('pointerdown',e=>{
  if(trySpecial())return; // mid-flight tap fires the hero special (once per launch)
  if(!slingReady())return;
  const p=getPos(e),s=G.sling;
  if(Math.hypot(p.x-s.x,p.y-s.y)<70){G.dragging=true;dragX=p.x;dragY=p.y;sfx.stretch();canvas.setPointerCapture(e.pointerId);}
});
canvas.addEventListener('pointermove',e=>{
  if(!G.dragging)return;const p=getPos(e);
  const s=G.sling;let dx=p.x-s.x,dy=p.y-s.y;
  const max=130,d=Math.hypot(dx,dy);
  if(d>max){dx=dx/d*max;dy=dy/d*max;}
  // only allow pulling back/down
  if(dx>20)dx=20;
  dragX=s.x+dx;dragY=s.y+dy;
});
canvas.addEventListener('pointerup',e=>{
  if(!G.dragging)return;G.dragging=false;
  const s=G.sling,dx=s.x-dragX,dy=s.y-dragY;
  const power=Math.hypot(dx,dy);
  if(power<25)return; // too weak
  // launch!
  const pr={x:s.x,y:s.y,vx:dx*7.5,vy:dy*7.5-150,rot:0,vr:8,live:true,restT:0,squash:0,trail:[],hero:G.hero,specialUsed:false,pendingSpecial:false,magnetT:0};
  G.projectiles.push(pr);
  G.shotsUsed++;G.combo=0;
  document.getElementById('shots').textContent='🎯 '+(G.shots-G.shotsUsed);
  sfx.launch();addTrauma(0.35);
  for(let i=0;i<12;i++)spawnP(s.x,s.y,(Math.random()-0.5)*300,(Math.random()-0.5)*200,0.4,'#ffb347',4);
});

/* ---------------- Level flow ---------------- */
function levelComplete(){
  G.state='clear';sfx.win();
  const shotsLeft=G.shots-G.shotsUsed;
  G.stars=shotsLeft>=2?3:shotsLeft>=1?2:1;
  const bonus=G.stars*500;G.score+=bonus;updateScoreUI();
  if(G.score>G.best){G.best=G.score;try{localStorage.setItem('sling_best',String(G.best));}catch(e){}}
  for(let i=0;i<30;i++)spawnP(W/2,H/2,(Math.random()-0.5)*600,(Math.random()-0.5)*600,1,'#ffd23f',6);
  setTimeout(()=>sfx.star(0),300);setTimeout(()=>sfx.star(1),600);setTimeout(()=>sfx.star(2),900);
  setTimeout(()=>{
    if(G.level>=10){gameComplete();}
    else showOverlay('⭐ LEVEL '+G.level+' CLEAR!',
      `<div class="stars">${'★'.repeat(G.stars)}${'☆'.repeat(3-G.stars)}</div><p>Score: ${G.score}</p><p>Bonus: +${bonus}</p><p>💀 Skeletons smashed: ${G.skelsSmashed}/${G.skels.length}</p>`+((G.slimers&&G.slimers.length)?'<p>🫧 Slimer smothered!</p>':''),
      '🔥 Fire Safety: Know two ways out of every room in case of fire!',
      '▶ NEXT LEVEL',()=>{G.level++;buildLevel(G.level);G.state='play';});
  },1200);
}
function levelFailed(){
  G.state='fail';
  showOverlay('💥 OUT OF SHOTS',
    `<p>So close! 💀 ${G.skels.length-G.skelsSmashed} skeleton${(G.skels.length-G.skelsSmashed)===1?'':'s'} still standing!</p><p>Score: ${G.score}</p>`,
    '🔥 Fire Safety: Never give up on safety — try again!',
    '↻ TRY AGAIN',()=>{G.score=Math.max(0,G.score-200);updateScoreUI();buildLevel(G.level);G.state='play';});
}
function gameComplete(){
  G.state='done';sfx.win();
  showOverlay('🏆 YOU DID IT!',
    `<p>All 10 levels cleared!</p><p style="font-size:28px;font-weight:900;color:#ffd23f">Final Score: ${G.score}</p><p>Best: ${G.best}</p>`,
    '🔥 Fire Safety: You\'re a fire safety champion! Share what you learned!',
    '↻ PLAY AGAIN',()=>{G.level=1;G.score=0;updateScoreUI();buildLevel(1);G.state='play';});
}

/* ---------------- Overlay & gates ---------------- */
let mathAnswer=0;
function showMathGate(){
  const a=1+Math.floor(Math.random()*9),b=1+Math.floor(Math.random()*9);
  mathAnswer=a+b;document.getElementById('mq').textContent=a+' + '+b;
  mathgate.classList.remove('hidden');
}
function checkMath(){
  if(parseInt(document.getElementById('ma').value,10)===mathAnswer){mathgate.classList.add('hidden');startGame();}
  else document.getElementById('ma').value='';
}
function showOverlay(title,body,lesson,btn,cb){
  otitle.innerHTML=title;obody.innerHTML=body;olesson.innerHTML=lesson;obtn.textContent=btn;
  obtn.onclick=()=>{sfx.click();overlay.classList.add('hidden');cb();};
  overlay.classList.remove('hidden');
}
function startGame(){
  audio();G.level=1;G.score=0;updateScoreUI();
  buildLevel(1);G.state='play';overlay.classList.add('hidden');
}
function showTitle(){
  const lv=document.getElementById('levelSel');
  // level select (all unlocked for kids)
  let h='';
  for(let i=1;i<=10;i++)h+=`<button class="lvlBtn" onclick="event.stopPropagation();selLevel(${i})">${i}</button>`;
  obody.innerHTML=`<p>Pick your hero, drag back on the slingshot and <b>release</b> to launch! While your hero is flying, <b>tap anywhere</b> (or press <b>Space</b>) to fire their special — once per launch. Your mission: smash EVERY <b>💀 skeleton</b> (+500 each) to win the level! The towers are just what they stand on — knock bricks down to drop, crush and topple them. Fewer shots = more stars!</p><p>🫧 <b>New villain: the Slimer!</b> He is made of oil — <b>water makes him GROW</b>, so do not splash him! Drop the tower on him and <b>bury him to smother him</b>. <b>Oil fire? Never spray it — smother it, and get a grown-up.</b></p><div class="heroPick heroPickSlot"></div><div id="levelSel">${h}</div>`;
  refreshHeroChips();
  obtn.textContent='▶ PLAY';
  obtn.onclick=()=>{showMathGate();};
  overlay.classList.remove('hidden');
}
function selLevel(n){sfx.click();G.level=n;G.score=0;updateScoreUI();mathgate.classList.add('hidden');buildLevel(n);G.state='play';overlay.classList.add('hidden');}
obtn.onclick=()=>{showMathGate();};

/* ---------------- Rendering ---------------- */
const HERO_ART={
  blaze:{glow:'rgba(255,140,0,',body:['#ffe9a0','#ff8a2a','#e8352c'],tip:'#ff6a1a'},
  aqua:{glow:'rgba(80,170,255,',body:['#d8f6ff','#3fa9f5','#1668b8'],tip:'#7fd4ff'},
  sparky:{glow:'rgba(255,210,63,',body:['#fff9c4','#ffd23f','#f59e0b'],tip:'#ffea00'},
  ruko:{glow:'rgba(255,87,34,',body:['#ffd0b0','#ff7043','#b71c1c'],tip:'#ff5722'}
};
function drawHero(x,y,r,squash,rot,hero){
  const art=HERO_ART[hero]||HERO_ART.blaze;
  ctx.save();ctx.translate(x,y);ctx.rotate(rot||0);
  ctx.scale(1+squash,1-squash);
  // glow
  const gl=ctx.createRadialGradient(0,0,r*0.5,0,0,r*2);
  gl.addColorStop(0,art.glow+'0.35)');gl.addColorStop(1,art.glow+'0)');
  ctx.fillStyle=gl;ctx.beginPath();ctx.arc(0,0,r*2,0,Math.PI*2);ctx.fill();
  // body
  const g=ctx.createRadialGradient(-r*0.3,-r*0.35,r*0.2,0,0,r);
  g.addColorStop(0,art.body[0]);g.addColorStop(0.5,art.body[1]);g.addColorStop(1,art.body[2]);
  ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();
  // hero tip (same code-art style per hero)
  const w=Math.sin(G.time*10)*3;
  ctx.fillStyle=art.tip;
  ctx.beginPath();
  if(hero==='aqua'){
    // droplet tip
    ctx.moveTo(w*0.4,-r*1.7);
    ctx.quadraticCurveTo(r*0.55,-r*0.95,r*0.42,-r*0.68);
    ctx.quadraticCurveTo(0,-r*1.05,-r*0.42,-r*0.68);
    ctx.quadraticCurveTo(-r*0.55,-r*0.95,w*0.4,-r*1.7);
  }else if(hero==='sparky'){
