/* [slimer 2026-10-18] Canvas-drawn in the game's art idiom: glossy black-purple
   blob, rotating rainbow oil swirls, drippy stub arms, smug grin; panic face while
   covered; dizzy spirals + flattened puddle when smothered. NO text on the character. */
function drawSlimer(sl){
  if(sl.gone)return;
  const r=slimerR(sl),cy=slimerCY(sl);
  const t=G.time;
  const wob=sl.wobbleT>0?Math.sin(t*30)*0.10*Math.min(1,sl.wobbleT):0;
  let sx=sl.scale,sy=sl.scale;
  if(sl.dead){const k=Math.min(1,sl.defeatT*3);sy=sl.scale*(1-0.78*k);sx=sl.scale*(1+0.55*k);}
  ctx.save();ctx.translate(sl.x,cy+Math.sin(t*3+sl.ph)*1.5);
  // rainbow slick puddle beneath him (widens as he grows)
  const pw=r*2.7*(sl.dead?1.35:1),ph2=Math.max(6,r*0.34);
  const pg=ctx.createLinearGradient(-pw/2,0,pw/2,0);
  for(let i=0;i<=4;i++)pg.addColorStop(i/4,'hsla('+((t*40+i*72)%360)+',85%,55%,0.75)');
  ctx.fillStyle=pg;
  ctx.beginPath();ctx.ellipse(0,r*0.95,pw/2,ph2,0,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.35)';
  ctx.beginPath();ctx.ellipse(-pw*0.18,r*0.88,pw*0.10,ph2*0.35,-0.3,0,Math.PI*2);ctx.fill();
  ctx.scale((sx/sl.scale)*(1+wob),(sy/sl.scale)*(1-wob)); // squash & stretch (geometry below uses r, which already includes sl.scale)
  if(sl.dead)ctx.translate(0,r*(1-(sy/sl.scale))*0.9); // flattened puddle sinks onto his slick, doesn't float
  // drippy stub arms
  ctx.fillStyle='#1c0b2e';
  for(const sgn of [-1,1]){
    ctx.beginPath();ctx.ellipse(sgn*r*1.02,r*0.18,r*0.34,r*0.52,sgn*0.5,0,Math.PI*2);ctx.fill();
    ctx.beginPath();ctx.arc(sgn*r*1.12,r*0.66,r*0.13,0,Math.PI*2);ctx.fill();
    const dl=r*0.10*(0.7+0.3*Math.sin(t*4+sgn));
    ctx.beginPath();ctx.ellipse(sgn*r*1.16,r*0.78+dl,r*0.06,r*0.14+dl*0.4,0,0,Math.PI*2);ctx.fill();
  }
  // glossy black-purple blob body
  const bg=ctx.createRadialGradient(-r*0.3,-r*0.4,r*0.2,0,0,r*1.15);
  bg.addColorStop(0,'#4b2566');bg.addColorStop(0.55,'#22103a');bg.addColorStop(1,'#0a0514');
  ctx.fillStyle=bg;
  ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();
  // rotating rainbow oil swirls, clipped inside the blob
  ctx.save();ctx.beginPath();ctx.arc(0,0,r-1.5,0,Math.PI*2);ctx.clip();
  ctx.lineWidth=r*0.20;ctx.lineCap='round';
  for(let i=0;i<3;i++){
    ctx.strokeStyle='hsla('+((t*45+i*120)%360)+',90%,60%,0.5)';
    ctx.beginPath();ctx.arc(Math.sin(t*0.6+i*2.1)*r*0.2,Math.cos(t*0.5+i*1.7)*r*0.18,r*(0.42+i*0.20),t*0.7+i*2.1,t*0.7+i*2.1+2.2);ctx.stroke();
  }
  ctx.restore();
  ctx.strokeStyle='#06030c';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.stroke();
  // gloss highlight
  ctx.fillStyle='rgba(255,255,255,0.4)';
  ctx.beginPath();ctx.ellipse(-r*0.36,-r*0.52,r*0.20,r*0.11,-0.6,0,Math.PI*2);ctx.fill();
  // face
  const panic=!sl.dead&&(sl.panicT>0||sl.coverNow.length>0);
  if(sl.dead){
    // dizzy spiral eyes
    ctx.strokeStyle='#efe6ff';ctx.lineWidth=2.2;
    for(const sgn of [-1,1]){
      ctx.beginPath();
      for(let a=0;a<Math.PI*5;a+=0.35){const rr=a*1.15,px=sgn*r*0.34+Math.cos(a+t*2)*rr,py=-r*0.18+Math.sin(a+t*2)*rr;a===0?ctx.moveTo(px,py):ctx.lineTo(px,py);}
      ctx.stroke();
    }
    // wavy flattened mouth
    ctx.strokeStyle='#efe6ff';ctx.lineWidth=2.4;ctx.beginPath();
    for(let i=0;i<=8;i++){const px=-r*0.26+i*r*0.065,py=r*0.30+Math.sin(i*1.6)*r*0.05;i===0?ctx.moveTo(px,py):ctx.lineTo(px,py);}
    ctx.stroke();
  }else if(panic){
    // wide round eyes + small "o" mouth
    ctx.fillStyle='#fff';
    ctx.beginPath();ctx.arc(-r*0.34,-r*0.16,r*0.21,0,Math.PI*2);ctx.arc(r*0.34,-r*0.16,r*0.21,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#12081f';
    ctx.beginPath();ctx.arc(-r*0.34,-r*0.14,r*0.09,0,Math.PI*2);ctx.arc(r*0.34,-r*0.14,r*0.09,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#efe6ff';ctx.lineWidth=2.6;
    ctx.beginPath();ctx.arc(0,r*0.34,r*0.13,0,Math.PI*2);ctx.stroke();
  }else{
    // sly half-lidded gloat + wide smug grin
    ctx.fillStyle='#fff';
    ctx.beginPath();ctx.ellipse(-r*0.34,-r*0.14,r*0.20,r*0.16,0,0,Math.PI*2);ctx.ellipse(r*0.34,-r*0.14,r*0.20,r*0.16,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#12081f';
    ctx.beginPath();ctx.arc(-r*0.26,-r*0.10,r*0.085,0,Math.PI*2);ctx.arc(r*0.42,-r*0.10,r*0.085,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#22103a'; // heavy lids
    ctx.beginPath();ctx.ellipse(-r*0.34,-r*0.26,r*0.21,r*0.10,0,0,Math.PI);ctx.ellipse(r*0.34,-r*0.26,r*0.21,r*0.10,0,0,Math.PI);ctx.fill();
    ctx.strokeStyle='#efe6ff';ctx.lineWidth=2.6;ctx.lineCap='round';
    ctx.beginPath();ctx.arc(0,r*0.10,r*0.52,0.35,Math.PI-0.35);ctx.stroke();
    ctx.fillStyle='hsla('+((t*45+60)%360)+',90%,65%,0.9)'; // grin drip
    ctx.beginPath();ctx.ellipse(r*0.18,r*0.52,r*0.06,r*0.13,0,0,Math.PI*2);ctx.fill();
  }
  ctx.restore();
}
function render(){
  // sky: volcano sunset
  const sky=ctx.createLinearGradient(0,0,0,H);
  sky.addColorStop(0,'#1a0d2a');sky.addColorStop(0.45,'#5a1a3a');sky.addColorStop(0.75,'#c84818');sky.addColorStop(1,'#2a1008');
  ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
  // sun
  ctx.fillStyle='#ffb347';ctx.globalAlpha=0.9;
  ctx.beginPath();ctx.arc(W*0.72,H*0.32,46,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
  // volcano silhouette
  ctx.fillStyle='#1a0d14';
  ctx.beginPath();ctx.moveTo(W*0.45,groundY());ctx.lineTo(W*0.62,H*0.25);ctx.lineTo(W*0.79,groundY());ctx.closePath();ctx.fill();
  // lava glow in crater
  ctx.fillStyle='#ff4a00';
  ctx.beginPath();ctx.ellipse(W*0.62,H*0.27,26,8,0,0,Math.PI*2);ctx.fill();
  // smoke
  for(let i=0;i<4;i++){
    const sy=H*0.22-((G.time*30+i*60)%240);
    ctx.fillStyle=`rgba(120,100,100,${0.25*(1-(H*0.22-sy)/240)})`;
    ctx.beginPath();ctx.arc(W*0.62+Math.sin(G.time+i)*20,sy,18+i*4,0,Math.PI*2);ctx.fill();
  }
  // distant mountains
  ctx.fillStyle='#241018';
  for(let i=0;i<5;i++){const mx=i*W/4.2-W*0.1;
    ctx.beginPath();ctx.moveTo(mx,groundY());ctx.lineTo(mx+W*0.14,groundY()-H*0.16);ctx.lineTo(mx+W*0.28,groundY());ctx.closePath();ctx.fill();}
  ctx.save();
  if(trauma>0)ctx.translate(shakeX,shakeY);
  const gy=groundY();
  // [fbzoom] pull the camera back: scale the whole play layer about the ground centre
  ctx.translate(W*0.5,gy);ctx.scale(FB_ZOOM,FB_ZOOM);ctx.translate(-W*0.5,-gy);
  // ground (drawn extra-wide so the zoomed-out view stays covered edge to edge)
  const gg=ctx.createLinearGradient(0,gy,0,H);
  gg.addColorStop(0,'#4a2a1a');gg.addColorStop(1,'#1a0d08');
  ctx.fillStyle=gg;ctx.fillRect(-W*0.3,gy,W*1.6,H-gy);
  ctx.fillStyle='#5a3a24';ctx.fillRect(-W*0.3,gy,W*1.6,6);
  // grass tufts / rocks detail
  ctx.fillStyle='#3a2418';
  for(let i=0;i<20;i++){const rx=(i*197)%W;ctx.fillRect(rx,gy+14+(i*37)%30,8,4);}
  // slingshot
  const s=G.sling;
  if(s){
    ctx.strokeStyle='#5a3a1a';ctx.lineWidth=14;ctx.lineCap='round';
    ctx.beginPath();ctx.moveTo(s.x,s.y+50);ctx.lineTo(s.x,s.y-10);ctx.stroke();
    ctx.lineWidth=10;
    ctx.beginPath();ctx.moveTo(s.x,s.y-10);ctx.lineTo(s.x-34,s.y-52);ctx.stroke();
    ctx.beginPath();ctx.moveTo(s.x,s.y-10);ctx.lineTo(s.x+34,s.y-52);ctx.stroke();
    // band
    const bx=G.dragging?dragX:s.x,by=G.dragging?dragY:s.y;
    ctx.strokeStyle='#c8352c';ctx.lineWidth=7;
    ctx.beginPath();ctx.moveTo(s.x-34,s.y-52);ctx.lineTo(bx,by);ctx.stroke();
    ctx.beginPath();ctx.moveTo(s.x+34,s.y-52);ctx.lineTo(bx,by);ctx.stroke();
    // Blaze in sling or dragging
    if(slingReady()||G.dragging)drawHero(bx,by-6,20,G.dragging?0.15:Math.sin(G.time*3)*0.05,0,G.hero);
    // trajectory dots
    if(G.dragging){
      const dx=s.x-dragX,dy=s.y-dragY;
      let tx=s.x,ty=s.y,tvx=dx*7.5,tvy=dy*7.5-150;
      ctx.fillStyle='rgba(255,255,255,0.65)';
      for(let i=0;i<14;i++){
        tvy+=GRAV*0.045;tx+=tvx*0.045;ty+=tvy*0.045;
        ctx.globalAlpha=1-i/14;
        ctx.beginPath();ctx.arc(tx,ty,5-i*0.25,0,Math.PI*2);ctx.fill();
      }
      ctx.globalAlpha=1;
    }
  }
  // blocks
  for(const b of G.blocks)if(!b.dead)drawBlock(b);
  // skeletons (bad guys perched on the towers)
  for(const s of G.skels){
    if(s.dead)continue;
    ctx.save();ctx.translate(s.x,s.y+Math.sin(G.time*3+s.ph)*1.5);
    if(s.falling)ctx.rotate(Math.sin(G.time*20)*0.15);
    // ribcage body
    ctx.strokeStyle='#d8d8e4';ctx.lineWidth=3;ctx.lineCap='round';
    ctx.beginPath();ctx.moveTo(0,-4);ctx.lineTo(0,12);ctx.stroke();
    for(let rI=0;rI<3;rI++){ctx.beginPath();ctx.arc(0,0+rI*5,8-rI,0.25,Math.PI-0.25);ctx.stroke();
      ctx.beginPath();ctx.arc(0,0+rI*5,8-rI,Math.PI+0.25,Math.PI*2-0.25);ctx.stroke();}
    // arms
    ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(-11,8+Math.sin(G.time*4+s.ph)*2);ctx.stroke();
    ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(11,8-Math.sin(G.time*4+s.ph)*2);ctx.stroke();
    // legs
    ctx.beginPath();ctx.moveTo(0,12);ctx.lineTo(-7,20);ctx.stroke();
    ctx.beginPath();ctx.moveTo(0,12);ctx.lineTo(7,20);ctx.stroke();
    // skull
    ctx.fillStyle='#ececf4';
    ctx.beginPath();ctx.arc(0,-13,10,0,Math.PI*2);ctx.fill();
    ctx.fillRect(-6,-6,12,6);
    // eye sockets + nose
    ctx.fillStyle='#14141f';
    ctx.beginPath();ctx.arc(-4,-13,3,0,Math.PI*2);ctx.arc(4,-13,3,0,Math.PI*2);ctx.fill();
    ctx.beginPath();ctx.moveTo(0,-9);ctx.lineTo(-2,-5);ctx.lineTo(2,-5);ctx.closePath();ctx.fill();
    // toothy grin
    ctx.strokeStyle='#14141f';ctx.lineWidth=1.2;
    ctx.beginPath();ctx.moveTo(-5,-2);ctx.lineTo(5,-2);ctx.stroke();
    ctx.beginPath();ctx.moveTo(-2,-4);ctx.lineTo(-2,0);ctx.moveTo(2,-4);ctx.lineTo(2,0);ctx.stroke();
    ctx.restore();
  }
  // slimers (oil villains standing on their rainbow slicks)
  for(const sl of (G.slimers||[]))drawSlimer(sl);
  // shards
  for(const sh of shards){
    if(!sh.a)continue;
    ctx.save();ctx.translate(sh.x,sh.y);ctx.rotate(sh.rot);
    ctx.globalAlpha=Math.min(1,sh.life);ctx.fillStyle=sh.color;
    ctx.fillRect(-sh.size/2,-sh.size/2,sh.size,sh.size*0.7);
    ctx.restore();
  }
  ctx.globalAlpha=1;
  // projectiles
  for(const pr of G.projectiles){
    if(!pr.live)continue;
    // trail
    pr.trail.push({x:pr.x,y:pr.y});if(pr.trail.length>10)pr.trail.shift();
    pr.trail.forEach((t,i)=>{ctx.globalAlpha=i/10*0.4;ctx.fillStyle=(HEROES[pr.hero]||HEROES.blaze).trail;
      ctx.beginPath();ctx.arc(t.x,t.y,10*i/10,0,Math.PI*2);ctx.fill();});
    ctx.globalAlpha=1;
    drawHero(pr.x,pr.y,19,pr.squash,pr.rot,pr.hero);
    // pulsing TAP! hint + special icon while the special is armed in flight
    if(!pr.specialUsed&&pr.y<groundY()-20){
      const hh=HEROES[pr.hero]||HEROES.blaze,pu=0.8+0.2*Math.sin(G.time*10);
      ctx.save();ctx.translate(pr.x,pr.y-48);ctx.scale(pu,pu);ctx.textAlign='center';
      ctx.font='900 17px system-ui';
      ctx.fillStyle='#000';ctx.fillText(hh.sIcon+' TAP!',2,2);
      ctx.fillStyle='#ffd23f';ctx.fillText(hh.sIcon+' TAP!',0,0);
      ctx.restore();ctx.textAlign='left';
    }
  }
  // particles
  for(const p of particles){
    if(!p.a)continue;
    ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;
    ctx.beginPath();ctx.arc(p.x,p.y,p.size*(p.life/p.max),0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  // floating text
  ctx.textAlign='center';
  for(const f of floaters){
    if(!f.a)continue;
    ctx.globalAlpha=Math.min(1,f.life*1.5);
    ctx.font=`900 ${f.size}px system-ui`;ctx.fillStyle='#000';
    ctx.fillText(f.txt,f.x+2,f.y+2);ctx.fillStyle=f.color;ctx.fillText(f.txt,f.x,f.y);
  }
  ctx.globalAlpha=1;ctx.textAlign='left';
  ctx.restore();
}

/* ---------------- Main loop ---------------- */
let lastT=0;
function loop(t){
  const rawDt=Math.min((t-lastT)/1000||0,1/30);lastT=t;
  if(window.__fbPaused){requestAnimationFrame(loop);return;} // [w5b] pause freeze: no sim update, no re-render
  let dt=rawDt;
  if(hitStop>0){hitStop-=rawDt;dt=rawDt*0.08;}
  G.time+=dt;
  // trauma decay
  trauma=Math.max(0,trauma-dt*1.6);
  const sh=trauma*trauma*22;
  shakeX=(Math.random()-0.5)*sh*2;shakeY=(Math.random()-0.5)*sh*2;
  // combo decay
  G.comboT-=dt;if(G.comboT<=0)G.combo=0;
  if(G.state==='play')updatePhysics(dt);
  // particles
  for(const p of particles){if(!p.a)continue;
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=p.grav*dt;p.life-=dt;if(p.life<=0)p.a=false;}
  for(const sh2 of shards){if(!sh2.a)continue;
    sh2.x+=sh2.vx*dt;sh2.y+=sh2.vy*dt;sh2.vy+=1400*dt;sh2.rot+=sh2.vr*dt;sh2.life-=dt;
    if(sh2.y>groundY()){sh2.y=groundY();sh2.vy*=-0.4;sh2.vx*=0.7;}
    if(sh2.life<=0)sh2.a=false;}
  for(const f of floaters){if(!f.a)continue;f.y-=70*dt;f.life-=dt;if(f.life<=0)f.a=false;}
  render();
  requestAnimationFrame(loop);
}
updateScoreUI();
showTitle();
requestAnimationFrame(loop);

/* [w5b] pause + mute controls (were missing entirely).
   Pause: the main loop early-returns before any sim update while
   window.__fbPaused is set, so gameplay state is fully frozen and the canvas
   is not re-rendered; the "⏸ Paused" overlay shows. Resume restores play.
   Mute: the tone/noise/sfx entry points check window.__fbMuted, and the
   game's AudioContext is suspended/resumed with the toggle. */
const __pb=document.getElementById('pauseBtn'),__mb=document.getElementById('muteBtn'),__pt=document.getElementById('pausedTxt');
function __setPaused(v){if(v&&G.state!=='play')return;window.__fbPaused=!!v;__pb.textContent=window.__fbPaused?'▶':'⏸';__pt.classList.toggle('hidden',!window.__fbPaused);}
__pb.addEventListener('click',e=>{e.stopPropagation();__setPaused(!window.__fbPaused);});
__mb.addEventListener('click',e=>{e.stopPropagation();window.__fbMuted=!window.__fbMuted;__mb.textContent=window.__fbMuted?'🔇':'🔊';try{if(typeof AC!=='undefined'&&AC){if(window.__fbMuted)AC.suspend();else AC.resume();}}catch(err){}});
addEventListener('keydown',e=>{if(e.key==='p'||e.key==='P'||e.key==='Escape')__setPaused(!window.__fbPaused);if(e.key==='m'||e.key==='M')__mb.click();if(e.code==='Space'||e.key===' '){if(G.state==='play'){e.preventDefault();trySpecial();}}});
/* ===== MUSIC (Jeff 2026-10-13): 'Tower Toppler' — Slingshot Cascade's own track.
   Synthesized Web Audio only. 112 BPM, bouncy square-wave bass over an
   Am–F–C–G march, playful triangle lead, marching kick/snare/hats.
   Starts on first interaction; 🔊 mute + pause freeze it. ===== */
const _mf=m=>440*Math.pow(2,(m-69)/12);
const MUS={on:false,step:0,nextT:0,BPM:112,
 BASS:[45,0,45,0,52,0,45,0, 41,0,41,0,48,0,41,0, 48,0,48,0,55,0,48,0, 43,0,43,0,50,0,55,0],
 LEAD:[69,0,72,0,76,0,72,74, 77,0,81,0,77,0,72,0, 76,0,79,0,84,0,79,0, 74,0,79,0,83,0,79,74],
 start(){if(this.on)return;const ac=audio();if(!ac)return;this.on=true;this.nextT=ac.currentTime+0.08;
  setInterval(()=>this.tick(),42);},
 tick(){const ac=audio();if(!ac)return;
  if(window.__fbMuted||window.__fbPaused){this.nextT=ac.currentTime+0.06;return;}
  while(this.nextT<ac.currentTime+0.14){this.play(this.step,this.nextT);this.nextT+=60/this.BPM/2;this.step=(this.step+1)%32;}},
 play(s,t){const d=Math.max(0,t-audio().currentTime);
  const b=this.BASS[s];if(b)tone(_mf(b),_mf(b),0.15,'square',0.05,d);
  const l=this.LEAD[s];if(l)tone(_mf(l),_mf(l),0.2,'triangle',0.06,d);
  if(s%8===0||s%8===4)tone(120,45,0.11,'sine',0.13,d); // marching kick
  if(s%8===2||s%8===6)noise(0.08,0.08,d,1800); // snare
  if(s%2===0)noise(0.025,0.02,d,6500); // hat
 }};
addEventListener('pointerdown',()=>MUS.start());
addEventListener('keydown',()=>MUS.start());

