*{box-sizing:border-box;margin:0;padding:0}
:root{--flame:#ff6a1a;--ember:#e8352c;--gold:#ffd76a;--amber:#ffb347;--cream:#ffe9d6;--ink:#1a0d06}
::selection{background:rgba(255,106,26,.45);color:#fff}
body{font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;background:radial-gradient(1200px 620px at 50% -120px,rgba(255,106,26,.16),transparent 60%),#1a0d06;color:var(--cream)}
.topbar{background:rgba(26,13,6,.96);border-bottom:2px solid rgba(255,106,26,.35);backdrop-filter:blur(6px);color:#ffe9d6;position:sticky;top:0;z-index:100}
.topbar .wrap{display:flex;align-items:center;justify-content:space-between;padding:12px 20px;max-width:1200px;margin:0 auto;flex-wrap:wrap;gap:8px 16px}
.brand{color:#ffb347;font-weight:900;font-size:22px;letter-spacing:1px;text-decoration:none}
.navlinks a{color:#ffd9ae;text-decoration:none;font-weight:700;margin-left:18px;font-size:15px;transition:color .15s}
.navlinks a:hover{color:#ff6a1a}
.hero{background:radial-gradient(ellipse at 50% 0%,rgba(255,106,26,.24),transparent 65%);text-align:center;padding:50px 20px 40px;border-bottom:2px solid rgba(255,106,26,.25)}
.hero h1{font-size:clamp(30px,6vw,52px);font-weight:900;letter-spacing:1px;margin-bottom:10px;color:#ffb347;text-shadow:0 4px 30px rgba(255,106,26,.35)}
.hero p{font-size:18px;font-weight:600;max-width:600px;margin:0 auto 20px;color:#ffd9ae}
.searchbar{max-width:500px;margin:0 auto;display:flex;gap:8px}
.searchbar input{flex:1;min-width:0;padding:14px 18px;border:2px solid rgba(255,106,26,.45);background:rgba(0,0,0,.35);color:#ffe9d6;border-radius:999px;font-size:16px;outline:none}
.searchbar input::placeholder{color:#a87f5c}
.searchbar input:focus{border-color:#ff8c2e;box-shadow:0 0 0 3px rgba(255,140,46,.25)}
.searchbar button{padding:14px 24px;background:linear-gradient(180deg,#ffd76a,#ff8c2e);color:#2a1206;border:2px solid #ff6a1a;box-shadow:0 4px 0 #a33c10;border-radius:999px;font-size:16px;font-weight:900;cursor:pointer}
.filters{max-width:1200px;margin:24px auto;padding:0 20px;display:flex;gap:10px;flex-wrap:wrap;justify-content:center}
