FSC.startEvac = function(){
  FSC.evacT = 5;
  FSC._lastEvac = 0;
  try{ if(typeof AudioSys !== 'undefined') AudioSys.alarm(); }catch(e){}
  FSC.hintOnce('evac', '\uD83D\uDEA8 GET OUT & STAY OUT! Two ways out \u2014 never go back inside!');
