/* =====================================================================
   PATCH 028 — hard-bots (the enemy army actually PLAYS, on HARD)
   Date: 2026-10-12 | For: Jeff (Fire Babys) — bot update order
   What it changes: the side-1 bot army in SPLASH battles stops being
     a random mob and plays like a hard-mode opponent:
     (1) FORMATION: after Game.startFight spawns the bot army, bots are
         arranged by role — guardians/boss front, brawlers mid,
         archers/pyros in the back — instead of random scatter.
     (2) FOCUS FIRE: every bot re-thinks ~6x/sec (staggered). A bot
         switches onto the weakest player unit it can see (by HP
         fraction) instead of blindly chasing the nearest forever.
     (3) FINISH THE HERO: if the player's hero is nearby (<320px) and
         hurt (<55% HP), bots pile onto the hero.
     (4) KITING: bot archers/pyros back away from melee attackers that
         get inside 55% of their range, so they keep shooting instead
         of standing still and getting flattened. They stop kiting a
         target that is nearly dead (<=15% HP) and finish it.
   FAIR-HARD ONLY: bots use only what a player can see (positions +
     HP). No stat, damage or HP changes; no new information; the
     baseline taunt rule still overrides everything. Player units and
     the hero are never touched. Catch-mode units (u.ctCatch) and
     anything outside the fight phase are left completely alone.
   Touches: updateUnit (wrapped, original called through),
     Game.startFight (wrapped, original called through).
   How to disable: set "enabled": false for this file in
                   patches/manifest.json, then run: python3 src/build.py
   Test: start any stage fight — bots line up tanks-front/archers-back,
     wounded player units get focused down, the hero gets swarmed when
     hurt, and archers retreat while shooting at an advancing brawler.
   ===================================================================== */
(function () {
  'use strict';

  function isBot(u) {
    return !!u && u.side === 1 && !u.isHero && !u.ctCatch &&
      typeof Game !== 'undefined' && Game && Game.phase === 'fight';
  }

  /* ---------------- brain: focus fire + finish the hero ---------------- */
  function botThink(u) {
    if (u.tauntT > 0) return; /* taunted: baseline rule wins, no override */
    var i, t, d2, frac;
    /* (3) finish the hero */
    if (typeof heroIdx !== 'undefined' && heroIdx >= 0) {
      var h = units[heroIdx];
      if (h && h.active && h.state !== ST.DYING && h.hp < h.maxHp * 0.55) {
        d2 = dist2(u.x, u.y, h.x, h.y);
        if (d2 < 320 * 320) {
          if (u.target !== heroIdx) {
            u.target = heroIdx;
            if (u.state === ST.ATK) u.state = ST.MOVE;
          }
          return;
        }
      }
    }
    /* (2) focus the weakest visible player unit within 380px */
    var best = -1, bestFrac = 2;
    for (i = 0; i < CFG.MAX_UNITS; i++) {
      t = units[i];
      if (!t.active || t.side !== 0 || t.state === ST.DYING) continue;
      d2 = dist2(u.x, u.y, t.x, t.y);
      if (d2 > 380 * 380) continue;
      frac = t.hp / t.maxHp;
      if (frac < bestFrac) { bestFrac = frac; best = i; }
    }
    if (best < 0 || best === u.target || bestFrac >= 0.999) return;
    var cur = (u.target >= 0 && u.target !== CASTLE_T) ? units[u.target] : null;
    var curFrac = (cur && cur.active && cur.side === 0 && cur.state !== ST.DYING)
      ? cur.hp / cur.maxHp : 1;
    /* switch only when the new target is clearly weaker (no thrash) */
    if (bestFrac < curFrac - 0.05) {
      u.target = best;
      if (u.state === ST.ATK) u.state = ST.MOVE;
    }
  }

  /* ---------------- kiting for ranged bots ---------------- */
  function botKite(u, dt) {
    if (u.key !== 'archer' && u.key !== 'pyro') return;
    if (u.target < 0 || u.target === CASTLE_T) return;
    var t = units[u.target];
    if (!t || !t.active || t.side !== 0 || t.state === ST.DYING) return;
    if (!t.isHero && t.key !== 'brawler' && t.key !== 'guardian' && t.key !== 'boss') return;
    if (t.hp <= t.maxHp * 0.15) return; /* nearly dead: stand and finish it */
    var dx = u.x - t.x, dy = u.y - t.y;
    var d = Math.sqrt(dx * dx + dy * dy) || 1;
    if (d >= u.range * 0.55) return;
    u.x = clamp(u.x + (dx / d) * u.moveSpeed * dt * 0.95, 20, CFG.W - 20);
    u.y = clamp(u.y + (dy / d) * u.moveSpeed * dt * 0.95, 120, CFG.H - 90);
  }

  /* ---------------- wrap updateUnit ---------------- */
  if (typeof updateUnit === 'function') {
    var __hb_origUpdateUnit = updateUnit;
    updateUnit = function (u, dt) {
      var bot = false;
      try { bot = isBot(u); } catch (e) { bot = false; }
      if (bot && u.state !== ST.DYING) {
        u.__hbT = (typeof u.__hbT === 'number') ? u.__hbT - dt : (u.idx % 5) * 0.03;
        if (u.__hbT <= 0) {
          u.__hbT = 0.16;
          /* retargets only stick while engaging — baseline re-acquires
             from IDLE/ACQ, which is its job; we steer MOVE/ATK units. */
          if (u.state === ST.MOVE || u.state === ST.ATK) {
            try { botThink(u); } catch (e) {}
          }
        }
      }
      __hb_origUpdateUnit(u, dt);
      if (bot && u.active && u.state !== ST.DYING) {
        try { botKite(u, dt); } catch (e) {}
      }
    };
  }

  /* ---------------- formation after the army spawns ---------------- */
  if (typeof Game !== 'undefined' && Game && typeof Game.startFight === 'function') {
    var __hb_origStartFight = Game.startFight;
    Game.startFight = function () {
      __hb_origStartFight.apply(this, arguments);
      try {
        if (Game.phase !== 'fight') return;
        var rows = { 0: [], 1: [], 2: [] }, i, u, rank;
        for (i = 0; i < CFG.MAX_UNITS; i++) {
          u = units[i];
          if (!u.active || u.side !== 1) continue;
          rank = (u.key === 'guardian' || u.key === 'boss') ? 0
               : (u.key === 'brawler') ? 1 : 2;
          rows[rank].push(u);
        }
        var rowY = [396, 326, 256];
        for (var r = 0; r < 3; r++) {
          var row = rows[r];
          row.sort(function (a, b) { return a.x - b.x; });
          for (i = 0; i < row.length; i++) {
            var n = row.length;
            row[i].x = clamp(240 + (i - (n - 1) / 2) * 74, 56, CFG.W - 56);
            row[i].y = rowY[r] + ((i % 3) - 1) * 9;
          }
        }
      } catch (e) { /* formation is a bonus — never break the fight */ }
    };
  }
})();
