/* Peek, don't consume: the links card re-renders when fresh server
   state lands, and the banner must survive that. It fades after 60s
   or when a newer message replaces it. */
function lkTakeMsg(){
  try{
    var raw = sessionStorage.getItem('fb_link_msg');
    if(!raw) return null;
    var o = JSON.parse(raw);
    if(!o || !o.m) return null;
    if(Date.now() - (o.at || 0) > 60000){ sessionStorage.removeItem('fb_link_msg'); return null; }
    return o.m;
  }catch(e){ return null; }
}
function lkCleanUrl(){
  try{
    var u = window.location.pathname + window.location.hash;
    window.history.replaceState({}, document.title, u);
  }catch(e){}
}
function lkOpenProfileSoon(){
  var tries = 0;
  var iv = setInterval(function(){
    tries++;
    try{
      if(window.__PROFILE_DEBUG && window.__PROFILE_DEBUG.open){
        window.__PROFILE_DEBUG.open();
        clearInterval(iv);
      }
    }catch(e){}
    if(tries > 20) clearInterval(iv);
  }, 400);
}
LK.startSteam = function(){
  var nonce = lkRand(18);
  try{
    sessionStorage.setItem('fb_link_pending', 'steam');
    sessionStorage.setItem('fb_link_nonce', nonce);
  }catch(e){}
  var rt = window.location.origin + window.location.pathname + '?fblink=steam&fbn=' + nonce;
  var url = 'https://steamcommunity.com/openid/login' +
    '?openid.ns=' + encodeURIComponent('http://specs.openid.net/auth/2.0') +
    '&openid.mode=checkid_setup' +
    '&openid.return_to=' + encodeURIComponent(rt) +
    '&openid.realm=' + encodeURIComponent(window.location.origin) +
    '&openid.identity=' + encodeURIComponent('http://specs.openid.net/auth/2.0/identifier_select') +
    '&openid.claimed_id=' + encodeURIComponent('http://specs.openid.net/auth/2.0/identifier_select');
  window.location.href = url;
};
LK.startDiscord = function(){
  if(!LK.server.discordClientId) return;
  var state = lkRand(18);
  try{
    sessionStorage.setItem('fb_link_pending', 'discord');
    sessionStorage.setItem('fb_link_nonce', state);
  }catch(e){}
  var ru = window.location.origin + window.location.pathname;
  var url = 'https://discord.com/oauth2/authorize' +
    '?client_id=' + encodeURIComponent(LK.server.discordClientId) +
    '&redirect_uri=' + encodeURIComponent(ru) +
    '&response_type=code&scope=identify' +
    '&state=' + encodeURIComponent(state);
  window.location.href = url;
};
LK.handleReturn = function(){
  var qs;
  try{ qs = new URLSearchParams(window.location.search || ''); }catch(e){ return; }
  var pending = null, nonce = null;
  try{
    pending = sessionStorage.getItem('fb_link_pending');
    nonce = sessionStorage.getItem('fb_link_nonce');
  }catch(e){}
  if(!pending) return;

  if(pending === 'steam' && qs.get('fblink') === 'steam' && qs.get('openid.mode') === 'id_res'){
    var okNonce = nonce && qs.get('fbn') === nonce;
    try{ sessionStorage.removeItem('fb_link_pending'); sessionStorage.removeItem('fb_link_nonce'); }catch(e){}
    if(!okNonce){ lkSetMsg('Steam link stopped — the sign-in reply didn\'t match. Try again.'); lkCleanUrl(); return; }
    var params = {};
    qs.forEach(function(v, k){ if(k.indexOf('openid.') === 0) params[k] = v; });
    /* The browser's word is never enough: the worker re-checks the
       assertion with Steam (check_authentication) before linking. */
    var wait = setInterval(function(){
      if(window.FireBabysAuth && window.FireBabysAuth.getToken && window.FireBabysAuth.getToken()){
        clearInterval(wait);
        LK.api('/link/steam/verify', { params: params }).then(function(res){
          if(res && res.ok){
            lkSetMsg('✅ Steam linked — SteamID ' + (res.steamId || '') + ' verified by Steam.');
            LK.server.steam = { id: res.steamId };
          } else {
            lkSetMsg('Steam link didn\'t verify (' + ((res && res.error) || 'server unavailable') + '). Nothing was linked.');
          }
          lkCleanUrl();
          lkOpenProfileSoon();
        }).catch(function(){
          lkSetMsg('Steam link couldn\'t reach the server. Nothing was linked.');
          lkCleanUrl();
        });
      }
    }, 500);
    setTimeout(function(){ clearInterval(wait); }, 20000);
    lkCleanUrl();
    return;
  }

  if(pending === 'discord' && qs.get('code')){
    var st = qs.get('state');
    var code = qs.get('code');
    try{ sessionStorage.removeItem('fb_link_pending'); sessionStorage.removeItem('fb_link_nonce'); }catch(e){}
    if(!nonce || st !== nonce){
      lkSetMsg('Discord link stopped — the sign-in reply didn\'t match. Try again.');
      lkCleanUrl();
      return;
    }
    var ru2 = window.location.origin + window.location.pathname;
    var wait2 = setInterval(function(){
      if(window.FireBabysAuth && window.FireBabysAuth.getToken && window.FireBabysAuth.getToken()){
        clearInterval(wait2);
        LK.api('/link/discord/exchange', { code: code, redirectUri: ru2 }).then(function(res){
          if(res && res.ok && res.discord){
            lkSetMsg('✅ Discord linked — ' + (res.discord.username || 'welcome') + ' is on your card.');
            LK.server.discord = res.discord;
          } else {
            lkSetMsg('Discord link didn\'t finish (' + ((res && res.error) || 'server unavailable') + '). Nothing was linked.');
          }
          lkCleanUrl();
          lkOpenProfileSoon();
        }).catch(function(){
          lkSetMsg('Discord link couldn\'t reach the server. Nothing was linked.');
          lkCleanUrl();
        });
      }
    }, 500);
    setTimeout(function(){ clearInterval(wait2); }, 20000);
    lkCleanUrl();
  }
};

