        var home = LS.home[id];
        if(!home || el.parentNode === home.parent) continue;
        if(home.next && home.next.parentNode === home.parent)
          home.parent.insertBefore(el, home.next);
        else home.parent.appendChild(el);
      }
      bar.style.display = 'none';
    }
  }catch(e){}
};

