function epClean(v){ return String(v == null ? '' : v).slice(0, 120); }
EP.displayOf = function(link){
  if(!link || typeof link !== 'object') return '';
  return epClean(link.email || link.name || link.username || link.id || '');
};
/* Mirror a server-verified link into 029's fb_links_v1 store (display
   only, sanitized subset). The Worker remains the source of truth. */
EP.mirror = function(key, link){
  try{
    var LK = EP.store();
    if(!LK || !LK.acct || !LK.save) return;
    var acct = LK.acct();
    if(!acct.extLinks || typeof acct.extLinks !== 'object') acct.extLinks = {};
    if(link && typeof link === 'object'){
      var m = {};
      if(link.id) m.id = epClean(link.id);
      if(link.email) m.email = epClean(link.email);
      if(link.name) m.name = epClean(link.name);
      if(link.username) m.username = epClean(link.username);
      if(link.at) m.at = epClean(link.at);
      acct.extLinks[key] = m;
    } else {
      delete acct.extLinks[key];
