};

/* ---------------- server state ---------------- */
EP.configured = function(p){
  var c = EP.server.cfg || {};
  return !!(c[p.key] === true || c[p.clientIdField]);
};
EP.refresh = function(done){
  if(!EP.authed()){ EP.server.checked = true; if(done) done(); return; }
  EP.api('/link/config', {}).then(function(cfg){
    if(!cfg || !cfg.ok) throw 0;
    EP.server.available = true;
    EP.server.cfg = cfg;
    return EP.api('/link/list', {});
  }).then(function(res){
    if(res && res.ok && res.links){
      for(var i = 0; i < EP.PROVIDERS.length; i++){
        var k = EP.PROVIDERS[i].key;
        EP.server.links[k] = res.links[k] || null;
        EP.mirror(k, EP.server.links[k]);
      }
    }
    EP.server.checked = true;
    if(done) done();
  }).catch(function(){
    EP.server.available = false;
    EP.server.checked = true;
    if(done) done();
  });
};
EP.rerenderProfile = function(){
  try{
    if(window.__PROFILE_DEBUG && window.__PROFILE_DEBUG.open)
      window.__PROFILE_DEBUG.open();
  }catch(e){}
};
EP.kickRefresh = function(){
  if(!EP.authed() || EP._refreshing) return;
  if(EP._fetchedFor === EP.accountKey()) return;
  EP._refreshing = true;
  EP._fetchedFor = EP.accountKey();
  EP.refresh(function(){
    EP._refreshing = false;
    try{
      var ovNow = document.getElementById('profileOv');
      var ae = document.activeElement;
      var typing = ae && ovNow && ovNow.contains(ae) &&
        (ae.tagName === 'INPUT' || ae.tagName === 'TEXTAREA');
      if(!typing && ovNow && ovNow.style.display !== 'none')
        EP.rerenderProfile();
    }catch(e){}
  });
};

/* ---------------- OAuth start / return (mirrors 029) ---------------- */
function epRand(n){
  var s = '', chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  for(var i = 0; i < n; i++) s += chars.charAt(Math.floor(Math.random() * chars.length));
  return s;
}
function epSetMsg(m){
  try{
    if(m) sessionStorage.setItem('fb_link_msg', JSON.stringify({ m:m, at:Date.now() }));
    else sessionStorage.removeItem('fb_link_msg');
  }catch(e){}
}
function epCleanUrl(){
  try{
    var u = window.location.pathname + window.location.hash;
    window.history.replaceState({}, document.title, u);
  }catch(e){}
}
function epOpenProfileSoon(){
  var tries = 0;
  var iv = setInterval(function(){
    tries++;
    try{
      if(window.__PROFILE_DEBUG && window.__PROFILE_DEBUG.open){
        window.__PROFILE_DEBUG.open();
        clearInterval(iv);
      }
    }catch(e){}
    if(tries > 20) clearInterval(iv);
  }, 400);
}
EP.provider = function(key){
  for(var i = 0; i < EP.PROVIDERS.length; i++)
    if(EP.PROVIDERS[i].key === key) return EP.PROVIDERS[i];
  return null;
};
EP.start = function(p){
  var clientId = EP.server.cfg && EP.server.cfg[p.clientIdField];
  if(!clientId) return;
  var state = epRand(18);
  try{
    sessionStorage.setItem('fb_link36_pending', p.key);
    sessionStorage.setItem('fb_link36_nonce', state);
  }catch(e){}
  var ru = window.location.origin + window.location.pathname;
  var url = p.authBase +
    '?client_id=' + encodeURIComponent(clientId) +
    '&redirect_uri=' + encodeURIComponent(ru) +
    '&response_type=code' +
    '&scope=' + encodeURIComponent(p.scope) +
    '&state=' + encodeURIComponent(state);
