};
EP.handleReturn = function(){
  var qs;
  try{ qs = new URLSearchParams(window.location.search || ''); }catch(e){ return; }
  var pending = null, nonce = null;
  try{
    pending = sessionStorage.getItem('fb_link36_pending');
    nonce = sessionStorage.getItem('fb_link36_nonce');
  }catch(e){}
  var p = pending ? EP.provider(pending) : null;
  if(!p) return;
  var code = qs.get('code');
  var st = qs.get('state');
  try{
    sessionStorage.removeItem('fb_link36_pending');
    sessionStorage.removeItem('fb_link36_nonce');
  }catch(e){}
  if(!code){
    epSetMsg(p.title + ' link stopped — no sign-in reply came back. Nothing was linked.');
    epCleanUrl();
    return;
  }
  if(!nonce || st !== nonce){
    epSetMsg(p.title + ' link stopped — the sign-in reply didn\'t match. Try again.');
    epCleanUrl();
    return;
  }
  var ru = window.location.origin + window.location.pathname;
  var wait = setInterval(function(){
    if(window.FireBabysAuth && window.FireBabysAuth.getToken && window.FireBabysAuth.getToken()){
      clearInterval(wait);
      EP.api('/link/' + p.key + '/exchange', { code: code, redirectUri: ru })
      .then(function(res){
        if(res && res.ok){
          var link = res[p.key] || (res.links && res.links[p.key]) || { id:'linked' };
          EP.server.links[p.key] = link;
          if(res.links){
            for(var i = 0; i < EP.PROVIDERS.length; i++){
              var k = EP.PROVIDERS[i].key;
              if(res.links[k]) EP.server.links[k] = res.links[k];
            }
          }
          EP.server.checked = true;
          EP.server.available = true;
          EP.mirror(p.key, link);
          var disp = EP.displayOf(link);
          epSetMsg('✅ ' + p.title + ' linked' + (disp ? ' — ' + disp : '') +
            ' (verified by ' + p.title + ').');
        } else {
          epSetMsg(p.title + ' link didn\'t finish (' +
            ((res && res.error) || 'server unavailable') + '). Nothing was linked.');
        }
        epCleanUrl();
        epOpenProfileSoon();
      }).catch(function(){
        epSetMsg(p.title + ' link couldn\'t reach the server. Nothing was linked.');
        epCleanUrl();
      });
    }
  }, 500);
  setTimeout(function(){ clearInterval(wait); }, 20000);
  epCleanUrl();
};

/* ---------------- rendering ---------------- */
EP.cssDone = false;
EP.css = function(){
  if(EP.cssDone || typeof document === 'undefined') return;
  EP.cssDone = true;
  var s = document.createElement('style');
  s.id = 'epCss';
  s.textContent =
    '.ep-row{display:flex;align-items:center;gap:10px;padding:9px 0;border-top:1px solid rgba(255,150,60,.14);}' +
    '.ep-ic{font-size:22px;flex:0 0 30px;text-align:center;}' +
    '.ep-tx{flex:1;min-width:0;}' +
    '.ep-tx b{color:#ffe9d6;font:800 13px system-ui;display:block;}' +
    '.ep-tx span{color:#c98a5a;font:600 11px/1.5 system-ui;display:block;word-break:break-word;}' +
    '.ep-ok{color:#7dff9a !important;}' +
    '.ep-btn{background:rgba(255,120,40,.22);border:1px solid rgba(255,150,60,.55);color:#ffd76a;' +
    'border-radius:10px;font:800 12px system-ui;padding:10px 14px;min-height:44px;cursor:pointer;flex:0 0 auto;}' +
    '.ep-btn:disabled{opacity:.45;cursor:default;}' +
    '.ep-btn.ghost{background:rgba(30,12,6,.85);color:#c98a5a;}' +
    '.ep-note{color:#c98a5a;font:600 11px/1.6 system-ui;margin-top:8px;}';
  var h = document.getElementsByTagName && document.getElementsByTagName('head')[0];
  (h || document.body).appendChild(s);
};
function epEl(tag, cls, text){
  var e = document.createElement(tag);
  if(cls) e.className = cls;
  if(text != null) e.textContent = text;
  return e;
}
EP.rowFor = function(p){
  var row = epEl('div', 'ep-row');
  row.id = 'epRow-' + p.key;
  row.appendChild(epEl('div', 'ep-ic', p.icon));
  var tx = epEl('div', 'ep-tx');
  tx.appendChild(epEl('b', null, p.title));
  var authed = EP.authed();
  var linked = EP.server.links[p.key];
  var status, btnLabel = 'Connect', btnFn = null, btnDis = false;
  if(!authed){ status = 'Sign in first to link ' + p.title + '.'; btnDis = true; }
  else if(linked){
    var disp = EP.displayOf(linked);
    status = '✅ Linked' + (disp ? ' — ' + disp : '') + ' (verified by ' + p.title + ')';
    btnLabel = 'Unlink';
  }
  else if(!EP.server.checked){ status = 'Checking link server…'; btnDis = true; }
  else if(!EP.server.available){
    status = 'Linking turns on soon — built and ready, switches on with the server update. Nothing is faked meanwhile.';
    btnDis = true;
  }
  else if(!EP.configured(p)){
    status = 'Linking turns on soon — ' + p.title + ' linking is being switched on.';
    btnDis = true;
  }
  else status = 'Not linked — ' + p.title + '\'s own page confirms it\'s you. We never see your ' + p.title + ' password.';
  tx.appendChild(epEl('span', linked ? 'ep-ok' : null, status));
  row.appendChild(tx);
  var b = epEl('button', 'ep-btn', btnLabel);
  if(btnDis) b.disabled = true;
  if(linked && authed && EP.server.available){
    btnFn = function(){
      if(!window.confirm('Unlink ' + p.title + ' from your Fire Babys profile?')) return;
      if(!EP.canChange()){ window.alert('Slow down a sec — too many changes at once.'); return; }
      EP.noteChange();
      EP.api('/link/unlink', { provider: p.key }).then(function(){
        EP.server.links[p.key] = null;
        EP.mirror(p.key, null);
        EP.rerenderProfile();
      }).catch(function(){ EP.rerenderProfile(); });
    };
  } else if(!btnDis){
    btnFn = function(){
      if(!EP.canChange()){
        window.alert(EP.authed() ? 'Slow down a sec — too many changes at once.' : 'Sign in first to change links.');
        return;
      }
      EP.noteChange();
      EP.start(p);
    };
  }
  if(btnFn) b.addEventListener('click', btnFn);
  row.appendChild(b);
  return row;
};
EP.findLinksCard = function(ov){
  try{
    var cards = ov.querySelectorAll('.pf-card');
    for(var i = 0; i < cards.length; i++){
      var h3 = cards[i].querySelector('h3');
      if(h3 && (h3.textContent || '').indexOf('LINKED ACCOUNTS') !== -1) return cards[i];
    }
  }catch(e){}
  return null;
};
EP.addRows = function(ov){
  try{
    if(!ov || !ov.appendChild) return;
    EP.css();
    var card = EP.findLinksCard(ov);
    if(!card){
      if(ov.querySelector && ov.querySelector('#epLinksCard')){ EP.kickRefresh(); return; }
      card = document.createElement('div');
      card.className = 'pf-card';
      card.id = 'epLinksCard';
      var h = document.createElement('h3');
      h.textContent = '🔗 LINKED ACCOUNTS — MORE WAYS TO LINK';
      card.appendChild(h);
      ov.appendChild(card);
    }
    if(card.querySelector && card.querySelector('#epRow-google')){ EP.kickRefresh(); return; }
    /* insert just above 029's display-only handle rows (PlayStation…) */
    var anchor = null;
    try{
      for(var i = 0; i < card.children.length; i++){
        var bb = card.children[i].querySelector && card.children[i].querySelector('b');
        if(bb && (bb.textContent || '') === 'PlayStation'){ anchor = card.children[i]; break; }
      }
    }catch(e){}
    for(var j = 0; j < EP.PROVIDERS.length; j++){
      var row = EP.rowFor(EP.PROVIDERS[j]);
      if(anchor) card.insertBefore(row, anchor); else card.appendChild(row);
    }
    var note = epEl('div', 'ep-note',
      '🛡️ Google, Yahoo and Amazon links only ever happen on that provider\'s own sign-in page — Fire Babys never sees that password.');
    if(anchor) card.insertBefore(note, anchor); else card.appendChild(note);
    EP.kickRefresh();
  }catch(e){}
};

/* Chain the hub hook like patch 033: previous renderer (029 + 033)
   runs first, unchanged; our rows land inside 029's links card. */
EP.renderInto = function(ov){
  try{
    if(EP._prevRenderInto && EP._prevRenderInto !== EP.renderInto)
      EP._prevRenderInto(ov);
  }catch(e){}
  EP.addRows(ov);
};
EP._prevRenderInto = null;
try{
  if(typeof window !== 'undefined' && window.__FBPROFILE_EXT &&
     typeof window.__FBPROFILE_EXT.renderInto === 'function'){
    EP._prevRenderInto = window.__FBPROFILE_EXT.renderInto;
  }
  if(typeof window !== 'undefined'){
    window.__FBPROFILE_EXT = { renderInto: EP.renderInto };
  }
}catch(e){}
/* 029's server-refresh re-render calls LK.renderInto directly (not
   the hub hook) — wrap it too, so the rows survive that rebuild. */
try{
  var LK0 = EP.store();
  if(LK0 && typeof LK0.renderInto === 'function' && !LK0.__epWrapped){
    var origLKRender = LK0.renderInto;
    LK0.renderInto = function(ov){
      origLKRender(ov);
      EP.addRows(ov);
    };
    LK0.__epWrapped = true;
  }
}catch(e){}

/* OAuth returns land back on play.html — handle on boot. */
try{ EP.handleReturn(); }catch(e){}

if(typeof window !== 'undefined'){
  window.__FB36_DEBUG = { providers: EP.PROVIDERS, server: EP.server,
    refresh: EP.refresh, addRows: EP.addRows, start: EP.start,
    configured: EP.configured };
}

})();

